Set-StrictMode -Version Latest

$script:UndoStack  = [System.Collections.Generic.List[object]]::new()
$script:RedoStack  = [System.Collections.Generic.List[object]]::new()
$script:IsUndoRedo = $false

# ==============================================================================
# Assemblies
# ==============================================================================
Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase
Add-Type -AssemblyName System.Drawing
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName WindowsFormsIntegration

function Hide-LauncherConsoleIfRequested {
  try {
    if ([string]$env:SMLT_HIDE_CONSOLE -ne '1') { return }
    if (-not ([System.Management.Automation.PSTypeName]'SmltConsoleWindowNative').Type) {
      Add-Type -Language CSharp -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class SmltConsoleWindowNative {
  [DllImport("kernel32.dll")]
  public static extern IntPtr GetConsoleWindow();
  [DllImport("user32.dll")]
  public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
}
"@ | Out-Null
    }
    $hwnd = [SmltConsoleWindowNative]::GetConsoleWindow()
    if ($hwnd -ne [IntPtr]::Zero) {
      [void][SmltConsoleWindowNative]::ShowWindow($hwnd, 0)
    }
  } catch {}
}

Hide-LauncherConsoleIfRequested

# ==============================================================================
# Single-instance guard (same script version)
# ==============================================================================
$script:SingleInstanceMutex = $null
$script:SingleInstanceMutexName = ''
try {
  $scriptBase = ''
  try { $scriptBase = [System.IO.Path]::GetFileNameWithoutExtension([string]$PSCommandPath) } catch { $scriptBase = '' }
  if ([string]::IsNullOrWhiteSpace($scriptBase)) { $scriptBase = 'Start_Menu_Lite_Tools' }
  $scriptBase = ($scriptBase -replace '[^A-Za-z0-9_.-]', '_')
  $scriptPathKey = ''
  try {
    $scriptPathForMutex = [string]$PSCommandPath
    if ([string]::IsNullOrWhiteSpace($scriptPathForMutex)) { $scriptPathForMutex = [string]$MyInvocation.MyCommand.Path }
    if (-not [string]::IsNullOrWhiteSpace($scriptPathForMutex)) {
      $scriptPathForMutex = [System.IO.Path]::GetFullPath($scriptPathForMutex).ToLowerInvariant()
      $bytes = [System.Text.Encoding]::UTF8.GetBytes($scriptPathForMutex)
      $sha1 = [System.Security.Cryptography.SHA1]::Create()
      try {
        $hash = $sha1.ComputeHash($bytes)
        $scriptPathKey = ([System.BitConverter]::ToString($hash)).Replace('-', '').Substring(0, 12)
      } finally {
        if ($sha1) { try { $sha1.Dispose() } catch {} }
      }
    }
  } catch { $scriptPathKey = '' }
  if ([string]::IsNullOrWhiteSpace($scriptPathKey)) { $scriptPathKey = 'local' }
  $script:SingleInstanceMutexName = ('Local\{0}_{1}' -f $scriptBase, $scriptPathKey)
  $createdNew = $false
  $script:SingleInstanceMutex = New-Object System.Threading.Mutex($true, $script:SingleInstanceMutexName, [ref]$createdNew)
  if (-not $createdNew) {
    exit
  }
  try {
    Register-EngineEvent -SourceIdentifier PowerShell.Exiting -Action {
      try {
        if ($script:SingleInstanceMutex) {
          try { $script:SingleInstanceMutex.ReleaseMutex() } catch {}
          try { $script:SingleInstanceMutex.Dispose() } catch {}
        }
      } catch {}
    } | Out-Null
  } catch {}
} catch {}

function Release-SingleInstanceMutexForRestart {
  try {
    if ($script:SingleInstanceMutex) {
      try { $script:SingleInstanceMutex.ReleaseMutex() } catch {}
      try { $script:SingleInstanceMutex.Dispose() } catch {}
      $script:SingleInstanceMutex = $null
    }
  } catch {}
}

