function Invoke-StartMenuRefresh {
  param([string]$TouchedFolder)

  # Touch folder timestamp (cheap and effective)
  if ($TouchedFolder -and (Test-Path -LiteralPath $TouchedFolder)) {
    try { (Get-Item -LiteralPath $TouchedFolder).LastWriteTime = Get-Date } catch {}
  }

  # SHCNE_ASSOCCHANGED + SHCNF_IDLIST
  try { [ShellNotify]::SHChangeNotify(0x08000000, 0x0000, [IntPtr]::Zero, [IntPtr]::Zero) } catch {}
}

# ==============================================================================
# Helpers (general)
# ==============================================================================
function Normalize-Path {
  param([string]$p)
  if ([string]::IsNullOrWhiteSpace($p)) { return $null }
  $p = $p.Trim([char[]]@(0x20,0x09,0x0D,0x0A))
  if ($p.StartsWith("@")) { $p = $p.Substring(1) }
  $p = $p.Trim('"')
  $p = [Environment]::ExpandEnvironmentVariables($p)
  return $p
}

function Get-StringNormalizationVariants {
  param([string]$Text)
  $vals = New-Object System.Collections.Generic.List[string]
  try {
    $s = [string]$Text
    if ([string]::IsNullOrWhiteSpace($s)) { return @() }
    [void]$vals.Add($s)
    foreach ($form in @(
      [Text.NormalizationForm]::FormC,
      [Text.NormalizationForm]::FormD,
      [Text.NormalizationForm]::FormKC,
      [Text.NormalizationForm]::FormKD
    )) {
      try {
        $n = $s.Normalize($form)
        if (-not [string]::IsNullOrWhiteSpace($n)) { [void]$vals.Add($n) }
      } catch {}
    }
    return @($vals.ToArray() | Sort-Object -Unique)
  } catch {
    return @()
  }
}

function Resolve-ExistingPathLenient {
  param([string]$Path)
  try {
    $p = Normalize-Path $Path
    if ([string]::IsNullOrWhiteSpace($p)) { return $null }
    if (-not (Test-Path variable:script:LenientPathResolveCache)) {
      $script:LenientPathResolveCache = @{}
    }
    $cacheKey = [string]$p
    if ($script:LenientPathResolveCache.ContainsKey($cacheKey)) {
      return [string]$script:LenientPathResolveCache[$cacheKey]
    }
    if (Test-Path -LiteralPath $p) {
      $script:LenientPathResolveCache[$cacheKey] = $p
      return $p
    }
    foreach ($pv in @(Get-StringNormalizationVariants -Text $p)) {
      if (Test-Path -LiteralPath $pv) {
        $script:LenientPathResolveCache[$cacheKey] = $pv
        return $pv
      }
    }
    $root = ''
    try { $root = [IO.Path]::GetPathRoot($p) } catch { $root = '' }
    if ([string]::IsNullOrWhiteSpace($root) -or -not (Test-Path -LiteralPath $root -PathType Container)) {
      $script:LenientPathResolveCache[$cacheKey] = $null
      return $null
    }
    $cur = $root.TrimEnd('\')
    $rel = ''
    try { $rel = $p.Substring($root.Length).TrimStart('\') } catch { $rel = '' }
    if ([string]::IsNullOrWhiteSpace($rel)) {
      $script:LenientPathResolveCache[$cacheKey] = $cur
      return $cur
    }
    $segments = @($rel -split '[\\/]')
    foreach ($seg in $segments) {
      if ([string]::IsNullOrWhiteSpace($seg)) { continue }
      $direct = Join-Path $cur $seg
      if (Test-Path -LiteralPath $direct) { $cur = $direct; continue }
      if (-not (Test-Path -LiteralPath $cur -PathType Container)) { $cur = $null; break }
      $segCandidates = @(Get-StringNormalizationVariants -Text ([string]$seg))
      if ($segCandidates.Count -eq 0) { $cur = $null; break }
      $match = $null
      foreach ($e in @(Get-ChildItem -LiteralPath $cur -Force -ErrorAction SilentlyContinue)) {
        $en = ''
        try { $en = [string]$e.Name } catch { $en = '' }
        if ([string]::IsNullOrWhiteSpace($en)) { continue }
        if ($en.Equals([string]$seg, [System.StringComparison]::OrdinalIgnoreCase)) { $match = $e; break }
        $enVariants = @(Get-StringNormalizationVariants -Text $en)
        $found = $false
        foreach ($sv in $segCandidates) {
          foreach ($ev in $enVariants) {
            if ($sv.Equals($ev, [System.StringComparison]::OrdinalIgnoreCase)) { $found = $true; break }
          }
          if ($found) { break }
        }
        if ($found) { $match = $e; break }
      }
      if (-not $match) { $cur = $null; break }
      try { $cur = [string]$match.FullName } catch { $cur = $null }
      if ([string]::IsNullOrWhiteSpace($cur)) { break }
    }
    if (-not [string]::IsNullOrWhiteSpace($cur) -and (Test-Path -LiteralPath $cur)) {
      $script:LenientPathResolveCache[$cacheKey] = $cur
      return $cur
    }
    $script:LenientPathResolveCache[$cacheKey] = $null
    return $null
  } catch {
    return $null
  }
}

function Test-PathEqualsCI {
  param(
    [string]$A,
    [string]$B
  )
  if ([string]::IsNullOrWhiteSpace($A) -or [string]::IsNullOrWhiteSpace($B)) { return $false }
  try {
    $aa = ([string]$A).TrimEnd('\').ToLowerInvariant()
    $bb = ([string]$B).TrimEnd('\').ToLowerInvariant()
    return ($aa -eq $bb)
  } catch {
    return $false
  }
}

function Test-IsSettingsAliasShortcutRow {
  param([object]$Row)
  try {
    if (-not $Row) { return $false }
    $tp = [string](Get-PropString -Obj $Row -Names @('Type') -Fallback '')
    if (-not [string]::IsNullOrWhiteSpace($tp) -and $tp -ne 'Shortcut') { return $false }

    $p = [string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback '')
    $nm = [string](Get-PropString -Obj $Row -Names @('Name','OriginalName') -Fallback '')
    $tgt = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('Target') -Fallback ''))
    $args = [string](Get-PropString -Obj $Row -Names @('Arguments') -Fallback '')

    $leaf = ''
    try { if (-not [string]::IsNullOrWhiteSpace($p)) { $leaf = [System.IO.Path]::GetFileName($p) } } catch {}
    $leafKey = Normalize-VisualKey $leaf
    $nameKey = Normalize-VisualKey $nm

    # Direct known legacy shortcut.
    if ($leaf -and $leaf.Equals('Immersive Control Panel.lnk', [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    if ($nameKey -eq 'immersive control panel') { return $true }

    # Command-line marker (most reliable when present).
    if (
      -not [string]::IsNullOrWhiteSpace($tgt) -and
      $tgt -match '(?i)\\control\.exe$' -and
      $args -match '(?i)(immersivecontrolpanel|microsoft\.windows\.immersivecontrolpanel|ms-settings:)'
    ) {
      return $true
    }

    # Defensive fallback for renamed legacy Settings links:
    # root-level control.exe shortcut in Start Menu roots with Settings-like naming.
    $isRootLevel = $false
    if (-not [string]::IsNullOrWhiteSpace($p)) {
      try {
        $dir = (Split-Path -Path $p -Parent)
        foreach ($sc in @('AllUsers','CurrentUser')) {
          if (-not ($scopeRoots -and $scopeRoots.ContainsKey($sc))) { continue }
          $root = [string]$scopeRoots[$sc]
          if (Test-PathEqualsCI -A $dir -B $root) { $isRootLevel = $true; break }
        }
      } catch {}
    }

    if ($isRootLevel -and -not [string]::IsNullOrWhiteSpace($tgt) -and $tgt -match '(?i)\\control\.exe$') {
      if ($leafKey -like 'immersive control panel*') { return $true }
      if ($nameKey -like 'settings*') { return $true }
      # In practice renamed legacy Settings links often end up as root-level control.exe with empty args.
      if ([string]::IsNullOrWhiteSpace($args)) { return $true }
    }
  } catch {}
  return $false
}

function Test-IsSettingsAppsFolderRow {
  param([object]$Row)
  try {
    if (-not $Row) { return $false }

    $isProxy = $false
    try { $isProxy = ($Row.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderProxy) } catch { $isProxy = $false }
    if (-not $isProxy) {
      try { $isProxy = ($Row.PSObject.Properties.Match('IsAppsFolderDisplayProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderDisplayProxy) } catch { $isProxy = $false }
    }
    if (-not $isProxy) { return $false }

    $kind = [string](Get-PropString -Obj $Row -Names @('AppsFolderProxyKind') -Fallback '')
    if ($kind -and $kind -eq 'Settings') { return $true }

    $aid = [string](Get-PropString -Obj $Row -Names @('AppsFolderId') -Fallback '')
    if (-not [string]::IsNullOrWhiteSpace($aid) -and $aid -match '(?i)microsoft\.windows\.immersivecontrolpanel') { return $true }

    # Extra fallback for cloned/rehydrated visual rows where proxy flags are dropped.
    $p = [string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback '')
    $a = [string](Get-PropString -Obj $Row -Names @('Arguments') -Fallback '')
    $n = [string](Get-PropString -Obj $Row -Names @('Name','OriginalName') -Fallback '')
    if (-not [string]::IsNullOrWhiteSpace($p) -and $p -match '(?i)^shell:AppsFolder\\') {
      if ($p -match '(?i)immersivecontrolpanel') { return $true }
      if ($a -match '(?i)immersivecontrolpanel|ms-settings:') { return $true }
      if ((Normalize-VisualKey $n) -like 'settings*') { return $true }
    }
  } catch {}
  return $false
}

function Test-IsOutlookAppsFolderRow {
  param([object]$Row)
  try {
    if (-not $Row) { return $false }

    $isProxy = $false
    try { $isProxy = ($Row.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderProxy) } catch { $isProxy = $false }
    if (-not $isProxy) {
      try { $isProxy = ($Row.PSObject.Properties.Match('IsAppsFolderDisplayProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderDisplayProxy) } catch { $isProxy = $false }
    }
    if (-not $isProxy) { return $false }

    $kind = [string](Get-PropString -Obj $Row -Names @('AppsFolderProxyKind') -Fallback '')
    if ($kind -and $kind -eq 'Outlook') { return $true }

    $aid = [string](Get-PropString -Obj $Row -Names @('AppsFolderId') -Fallback '')
    if (-not [string]::IsNullOrWhiteSpace($aid) -and $aid -match '(?i)microsoft\.outlookforwindows') { return $true }

    $p = [string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback '')
    $a = [string](Get-PropString -Obj $Row -Names @('Arguments') -Fallback '')
    $n = [string](Get-PropString -Obj $Row -Names @('Name','OriginalName') -Fallback '')
    if (-not [string]::IsNullOrWhiteSpace($p) -and $p -match '(?i)^shell:AppsFolder\\') {
      if ($p -match '(?i)microsoft\.outlookforwindows') { return $true }
      if ($a -match '(?i)microsoft\.outlookforwindows|outlookforwindows') { return $true }
      if ((Normalize-VisualKey $n) -like 'outlook*') { return $true }
    }
  } catch {}
  return $false
}

function Get-SettingsSystemIconLocation {
  try {
    $exe = Join-Path $env:WINDIR 'ImmersiveControlPanel\SystemSettings.exe'
    if (Test-Path -LiteralPath $exe) { return ($exe + ',0') }
  } catch {}
  return $null
}

function Test-IsEdgeAppId {
  param([string]$AppId)
  try {
    if ([string]::IsNullOrWhiteSpace($AppId)) { return $false }
    $a = [string]$AppId
    if ($a -match '(?i)^msedge$') { return $true }
    if ($a -match '(?i)microsoft\.microsoftedge') { return $true }
    if ($a -match '(?i)microsoftedge') { return $true }
  } catch {}
  return $false
}

function Get-EdgeSystemIconLocation {
  try {
    $candidates = @(
      (Join-Path ${env:ProgramFiles(x86)} 'Microsoft\Edge\Application\msedge.exe'),
      (Join-Path $env:ProgramFiles 'Microsoft\Edge\Application\msedge.exe')
    )
    foreach ($exe in @($candidates)) {
      if ([string]::IsNullOrWhiteSpace([string]$exe)) { continue }
      if (Test-Path -LiteralPath $exe) { return ($exe + ',0') }
    }
  } catch {}
  return $null
}

function Ensure-EdgeIconOnShortcut {
  param(
    [Parameter(Mandatory=$true)][string]$LnkPath,
    [object]$Row = $null
  )

  try {
    if ([string]::IsNullOrWhiteSpace($LnkPath)) { return $false }
    if (-not (Test-Path -LiteralPath $LnkPath)) { return $false }
    if (-not ([string]$LnkPath).ToLowerInvariant().EndsWith('.lnk')) { return $false }

    $isEdge = $false
    $rowTarget = ''
    $rowArgs = ''
    $rowPath = ''
    $rowAid = ''
    try { $rowTarget = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('Target') -Fallback '')) } catch {}
    try { $rowArgs   = [string](Get-PropString -Obj $Row -Names @('Arguments') -Fallback '') } catch {}
    try { $rowPath   = [string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback '') } catch {}
    try { $rowAid    = [string](Get-PropString -Obj $Row -Names @('AppsFolderId') -Fallback '') } catch {}

    if (-not [string]::IsNullOrWhiteSpace($rowTarget) -and $rowTarget -match '(?i)\\msedge\.exe$') { $isEdge = $true }
    if (-not $isEdge -and -not [string]::IsNullOrWhiteSpace($rowArgs) -and $rowArgs -match '(?i)shell:AppsFolder\\(MSEdge|Microsoft\.MicrosoftEdge)') { $isEdge = $true }
    if (-not $isEdge -and -not [string]::IsNullOrWhiteSpace($rowPath) -and $rowPath -match '(?i)shell:AppsFolder\\(MSEdge|Microsoft\.MicrosoftEdge)') { $isEdge = $true }
    if (-not $isEdge -and (Test-IsEdgeAppId -AppId $rowAid)) { $isEdge = $true }

    $ws = New-Object -ComObject WScript.Shell
    $sc = $ws.CreateShortcut($LnkPath)
    $tgt = ''
    $arg = ''
    try { $tgt = Normalize-Path ([string]$sc.TargetPath) } catch { $tgt = '' }
    try { $arg = [string]$sc.Arguments } catch { $arg = '' }

    if (-not $isEdge -and -not [string]::IsNullOrWhiteSpace($tgt) -and $tgt -match '(?i)\\msedge\.exe$') { $isEdge = $true }
    if (-not $isEdge -and -not [string]::IsNullOrWhiteSpace($arg) -and $arg -match '(?i)shell:AppsFolder\\(MSEdge|Microsoft\.MicrosoftEdge)') { $isEdge = $true }
    if (-not $isEdge) { return $false }

    $edgeIcon = Get-EdgeSystemIconLocation
    if ([string]::IsNullOrWhiteSpace($edgeIcon)) { return $false }

    try { $sc.IconLocation = [string]$edgeIcon } catch { return $false }
    try { $sc.Save() } catch { return $false }
    return $true
  } catch {
    return $false
  }
}

function Get-OutlookSystemIconLocation {
  try {
    $pkgs = @(Get-AppxPackage -Name 'Microsoft.OutlookForWindows' -ErrorAction SilentlyContinue)
    foreach ($p in @($pkgs)) {
      if (-not $p) { continue }
      $loc = ''
      try { $loc = [string]$p.InstallLocation } catch { $loc = '' }
      if ([string]::IsNullOrWhiteSpace($loc)) { continue }
      $exe = Join-Path $loc 'olk.exe'
      if (Test-Path -LiteralPath $exe) { return ($exe + ',0') }
    }
  } catch {}

  try {
    $wa = Join-Path $env:ProgramFiles 'WindowsApps'
    $dirs = @(Get-ChildItem -LiteralPath $wa -Directory -Filter 'Microsoft.OutlookForWindows_*' -ErrorAction SilentlyContinue |
      Sort-Object Name -Descending)
    foreach ($d in @($dirs)) {
      if (-not $d) { continue }
      $exe = Join-Path $d.FullName 'olk.exe'
      if (Test-Path -LiteralPath $exe) { return ($exe + ',0') }
    }
  } catch {}

  return $null
}

