  try {
    $ico = Join-Path $env:WINDIR 'SystemApps\MicrosoftWindows.Client.CBS_cw5n1h2txyewy\WindowsBackup\Assets\WindowsBackup.ico'
    if (Test-Path -LiteralPath $ico) { return ($ico + ',0') }
  } catch {}
  return $null
}

function Set-PropSafeGlobal {
  param(
    [Parameter(Mandatory=$true)][object]$Obj,
    [Parameter(Mandatory=$true)][string]$Name,
    $Value
  )
  if (-not $Obj) { return }
  if ($Obj.PSObject.Properties.Match($Name).Count -eq 0) {
    Add-Member -InputObject $Obj -NotePropertyName $Name -NotePropertyValue $Value -Force
  } else {
    try { $Obj.$Name = $Value } catch {}
  }
}

function Convert-HIconToImageSource {
  param([IntPtr]$HIcon)
  if ($HIcon -eq [IntPtr]::Zero) { return $null }

  $src = [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon(
    $HIcon,
    [System.Windows.Int32Rect]::Empty,
    [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions()
  )
  $src.Freeze()
  return $src
}

function Add-ImageSourcePadding {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Media.ImageSource]$Source,
    [int]$Padding = 2
  )
  try {
    if (-not $Source) { return $null }
    $bmp = $Source -as [System.Windows.Media.Imaging.BitmapSource]
    if (-not $bmp) { return $Source }
    $pad = [int]$Padding
    if ($pad -lt 1) { return $Source }
    $w = 0; $h = 0
    try { $w = [int]$bmp.PixelWidth } catch { $w = 0 }
    try { $h = [int]$bmp.PixelHeight } catch { $h = 0 }
    if ($w -le 0 -or $h -le 0) { return $Source }
    $dpiX = 96.0; $dpiY = 96.0
    try { $dpiX = [double]$bmp.DpiX } catch {}
    try { $dpiY = [double]$bmp.DpiY } catch {}
    if ($dpiX -le 0) { $dpiX = 96.0 }
    if ($dpiY -le 0) { $dpiY = 96.0 }
    $newW = $w + ($pad * 2)
    $newH = $h + ($pad * 2)
    $dv = New-Object System.Windows.Media.DrawingVisual
    $dc = $dv.RenderOpen()
    try {
      $dc.DrawImage($bmp, (New-Object System.Windows.Rect([double]$pad, [double]$pad, [double]$w, [double]$h)))
    } finally {
      if ($dc) { $dc.Close() }
    }
    $rtb = New-Object System.Windows.Media.Imaging.RenderTargetBitmap($newW, $newH, $dpiX, $dpiY, [System.Windows.Media.PixelFormats]::Pbgra32)
    $rtb.Render($dv)
    try { $rtb.Freeze() } catch {}
    return $rtb
  } catch {
    return $Source
  }
}

function Get-ImageSourceFromIcon {
  param(
    [string]$IconPath,
    [int]$IconIndex = 0,
    [string]$FallbackExePath
  )

  try {
    $IconPath        = Normalize-Path $IconPath
    $FallbackExePath = Normalize-Path $FallbackExePath
    try {
      if (-not [string]::IsNullOrWhiteSpace($IconPath)) {
        $ipResolved = Resolve-ExistingPathLenient -Path $IconPath
        if (-not [string]::IsNullOrWhiteSpace($ipResolved)) { $IconPath = $ipResolved }
      }
    } catch {}
    try {
      if (-not [string]::IsNullOrWhiteSpace($FallbackExePath)) {
        $fbResolved = Resolve-ExistingPathLenient -Path $FallbackExePath
        if (-not [string]::IsNullOrWhiteSpace($fbResolved)) { $FallbackExePath = $fbResolved }
      }
    } catch {}

    # Unicode-safe shortcut handling:
    # when IconPath points to a .lnk (including names/folders with symbols/emoji),
    # resolve actual icon resource from the shortcut first.
    if ($IconPath -and $IconPath.ToLowerInvariant().EndsWith('.lnk') -and (Test-Path -LiteralPath $IconPath -PathType Leaf)) {
      try {
        $spec = Get-ShortcutIconLocationSpecFromLink -LnkPath $IconPath
        if ($spec -and -not [string]::IsNullOrWhiteSpace([string]$spec.IconPath)) {
          $resolvedIconPath = Normalize-Path ([string]$spec.IconPath)
          $resolvedIconIndex = 0
          try { $resolvedIconIndex = [int]$spec.IconIndex } catch { $resolvedIconIndex = 0 }
          if (-not [string]::IsNullOrWhiteSpace($resolvedIconPath) -and -not $resolvedIconPath.Equals($IconPath, [System.StringComparison]::OrdinalIgnoreCase)) {
            $srcFromSpec = Get-ImageSourceFromIcon -IconPath $resolvedIconPath -IconIndex $resolvedIconIndex -FallbackExePath $FallbackExePath
            if ($srcFromSpec) { return $srcFromSpec }
          }
        }
      } catch {}
      # If no explicit fallback target was provided, attempt to read it from the .lnk.
      if ([string]::IsNullOrWhiteSpace($FallbackExePath)) {
        try {
          $wsLnk = New-Object -ComObject WScript.Shell
          $scLnk = $wsLnk.CreateShortcut($IconPath)
          $tgtLnk = ''
          try { $tgtLnk = Normalize-Path ([string]$scLnk.TargetPath) } catch { $tgtLnk = '' }
          try {
            if (-not [string]::IsNullOrWhiteSpace($tgtLnk)) {
              $tgtResolved = Resolve-ExistingPathLenient -Path $tgtLnk
              if (-not [string]::IsNullOrWhiteSpace($tgtResolved)) { $tgtLnk = $tgtResolved }
            }
          } catch {}
          if (-not [string]::IsNullOrWhiteSpace($tgtLnk)) { $FallbackExePath = $tgtLnk }
        } catch {}
      }
    }

    if ($IconPath -and (Test-Path -LiteralPath $IconPath)) {

      if ($IconPath.ToLower().EndsWith(".ico")) {
        $large = New-Object IntPtr[] 1
        $small = New-Object IntPtr[] 1
        [void][IconNative]::ExtractIconEx($IconPath, 0, $large, $small, 1)

        $hIcon = if ($large[0] -ne [IntPtr]::Zero) { $large[0] } else { $small[0] }
        if ($hIcon -ne [IntPtr]::Zero) {
          $src = Convert-HIconToImageSource -HIcon $hIcon
          [void][IconNative]::DestroyIcon($hIcon)
          if ($src) { return $src }
        }
      }

      # For icon locations using negative indices (resource IDs), use SHDefExtractIcon.
      if ($IconIndex -lt 0) {
        try {
          $hLarge = [IntPtr]::Zero
          $hSmall = [IntPtr]::Zero
          $sz = [uint32]((32 -band 0xFFFF) -bor ((32 -band 0xFFFF) -shl 16))
          $hr = [IconNative2]::SHDefExtractIcon($IconPath, $IconIndex, 0, [ref]$hLarge, [ref]$hSmall, $sz)
          if ($hr -eq 0) {
            $h = if ($hLarge -ne [IntPtr]::Zero) { $hLarge } else { $hSmall }
            if ($h -ne [IntPtr]::Zero) {
              $src = Convert-HIconToImageSource -HIcon $h
              if ($src) {
                try { if ($hSmall -ne [IntPtr]::Zero) { [void][IconNative]::DestroyIcon($hSmall) } } catch {}
                try { if ($hLarge -ne [IntPtr]::Zero) { [void][IconNative]::DestroyIcon($hLarge) } } catch {}
                return $src
              }
            }
          }
          try { if ($hSmall -ne [IntPtr]::Zero) { [void][IconNative]::DestroyIcon($hSmall) } } catch {}
          try { if ($hLarge -ne [IntPtr]::Zero) { [void][IconNative]::DestroyIcon($hLarge) } } catch {}
        } catch {}
      }

      $indexes = @($IconIndex)
      if ($IconIndex -lt 0) { $indexes += @([Math]::Abs($IconIndex)) }

      foreach ($idx in $indexes) {
        $large = New-Object IntPtr[] 1
        $small = New-Object IntPtr[] 1
        [void][IconNative]::ExtractIconEx($IconPath, $idx, $large, $small, 1)

        $hIcon = [IntPtr]::Zero
        if ($large[0] -ne [IntPtr]::Zero) { $hIcon = $large[0] }
        elseif ($small[0] -ne [IntPtr]::Zero) { $hIcon = $small[0] }

        if ($hIcon -ne [IntPtr]::Zero) {
          $src = Convert-HIconToImageSource -HIcon $hIcon
          [void][IconNative]::DestroyIcon($hIcon)
          if ($src) { return $src }
        }
      }
    }

    if ($FallbackExePath -and (Test-Path -LiteralPath $FallbackExePath)) {
      # Prefer associated/shell icon resolution for any valid filesystem target,
      # not just .exe. This keeps icon binding robust for links to folders/files.
      try {
        $srcAssoc = Get-ImageSourceFromAssociatedIconPath -Path $FallbackExePath
        if ($srcAssoc) { return $srcAssoc }
      } catch {}
      try {
        $srcShell = Get-ImageSourceFromShellFileInfoPath -Path $FallbackExePath -Size Small
        if ($srcShell) { return $srcShell }
      } catch {}
      if ($FallbackExePath.ToLower().EndsWith(".exe")) {
        $assoc = [System.Drawing.Icon]::ExtractAssociatedIcon($FallbackExePath)
        if ($assoc) {
          $src = Convert-HIconToImageSource -HIcon $assoc.Handle
          if ($src) { return $src }
        }
      }
    }
  } catch {}
  return $null
}

function Get-ImageSourceFromAssociatedIconPath {
  param([string]$Path)
  try {
    $p = Normalize-Path $Path
    if ([string]::IsNullOrWhiteSpace($p)) { return $null }
    $pResolved = Resolve-ExistingPathLenient -Path $p
    if ([string]::IsNullOrWhiteSpace($pResolved)) { $pResolved = $p }
    if ([string]::IsNullOrWhiteSpace($pResolved) -or -not (Test-Path -LiteralPath $pResolved)) { return $null }
    $assoc = $null
    try { $assoc = [System.Drawing.Icon]::ExtractAssociatedIcon($pResolved) } catch { $assoc = $null }
    if (-not $assoc) { return $null }
    try {
      $src = Convert-HIconToImageSource -HIcon $assoc.Handle
      if ($src) { return $src }
    } finally {
      try { $assoc.Dispose() } catch {}
    }
  } catch {}
  return $null
}

function Get-ImageSourceFromShellFileInfoPath {
  param(
    [string]$Path,
    [ValidateSet('Small','Large')]
    [string]$Size = 'Small'
  )
  try {
    $p = Normalize-Path $Path
    if ([string]::IsNullOrWhiteSpace($p)) { return $null }
    $pResolved = Resolve-ExistingPathLenient -Path $p
    if ([string]::IsNullOrWhiteSpace($pResolved)) { $pResolved = $p }
    if ([string]::IsNullOrWhiteSpace($pResolved) -or -not (Test-Path -LiteralPath $pResolved)) { return $null }

    # Ensure Win32.StartMenuIcon type is available.
    if (-not ('Win32.StartMenuIcon' -as [type])) {
      try { [void](Get-SystemFolderIconImageSource -Size Small) } catch {}
    }
    if (-not ('Win32.StartMenuIcon' -as [type])) { return $null }

    $flags = [Win32.StartMenuIcon]::SHGFI_ICON -bor ($(if ($Size -eq 'Small') { [Win32.StartMenuIcon]::SHGFI_SMALLICON } else { [Win32.StartMenuIcon]::SHGFI_LARGEICON }))
    $info = New-Object Win32.StartMenuIcon+SHFILEINFO
    [void][Win32.StartMenuIcon]::SHGetFileInfo(
      $pResolved,
      0,
      [ref]$info,
[uint32][Runtime.InteropServices.Marshal]::SizeOf($info),
      [uint32]$flags
    )
    if ($info.hIcon -eq [IntPtr]::Zero) { return $null }
    try {
      $src = [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon(
        $info.hIcon,
        [System.Windows.Int32Rect]::Empty,
        [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions()
      )
      $src.Freeze()
      return $src
    }
    finally {
      try { [void][Win32.StartMenuIcon]::DestroyIcon($info.hIcon) } catch {}
    }
  } catch {}
  return $null
}

function Rotate-ImageSource90CCW {
  param([System.Windows.Media.ImageSource]$Source)
  try {
    if (-not $Source) { return $null }
    $bmp = $Source -as [System.Windows.Media.Imaging.BitmapSource]
    if (-not $bmp) { return $Source }

    $w = 0; $h = 0
    try { $w = [int]$bmp.PixelWidth } catch { $w = 0 }
    try { $h = [int]$bmp.PixelHeight } catch { $h = 0 }
    if ($w -le 0 -or $h -le 0) { return $Source }

    $dpiX = 96.0; $dpiY = 96.0
    try { $dpiX = [double]$bmp.DpiX } catch { $dpiX = 96.0 }
    try { $dpiY = [double]$bmp.DpiY } catch { $dpiY = 96.0 }
    if ($dpiX -le 0) { $dpiX = 96.0 }
    if ($dpiY -le 0) { $dpiY = 96.0 }

    # Keep the same canvas size and rotate around absolute center.
    $dv = New-Object System.Windows.Media.DrawingVisual
    $dc = $null
    try {
      $dc = $dv.RenderOpen()
      $cx = [double]$w / 2.0
      $cy = [double]$h / 2.0
      $dc.PushTransform((New-Object System.Windows.Media.RotateTransform(-0.0, $cx, $cy)))
      $dc.DrawImage($bmp, (New-Object System.Windows.Rect(0.0, 0.0, [double]$w, [double]$h)))
      $dc.Pop()
    } finally {
      if ($dc) { $dc.Close() }
    }

    $rtb = New-Object System.Windows.Media.Imaging.RenderTargetBitmap($w, $h, $dpiX, $dpiY, [System.Windows.Media.PixelFormats]::Pbgra32)
    $rtb.Render($dv)
    try { $rtb.Freeze() } catch {}
    if (($rtb.PixelWidth -le 0) -or ($rtb.PixelHeight -le 0)) { return $Source }
    return $rtb
  } catch {
    return $Source
  }
}

function Get-ImageSourceFromShellParsingName {
  param([Parameter(Mandatory=$true)][string]$ParsingName)

  try {
    $pn = [string]$ParsingName
    if ([string]::IsNullOrWhiteSpace($pn)) { return $null }
    $pn = $pn.Trim()

    # Safety-first path: avoid PIDL-based SHGetFileInfo calls because they can AV.
    # Resolve only direct filesystem icon sources or "path,index" icon locations.
    if (Test-Path -LiteralPath $pn) {
      $src = Get-ImageSourceFromIcon -IconPath $pn -IconIndex 0 -FallbackExePath $pn
      if ($src) { return $src }
    }

    if ($pn -match '^\s*([^,]+)\s*,\s*(-?\d+)\s*$') {
      $base = [string]$Matches[1]
      $idx = 0
      try { $idx = [int]$Matches[2] } catch { $idx = 0 }
      if (Test-Path -LiteralPath $base) {
        $src = Get-ImageSourceFromIcon -IconPath $base -IconIndex $idx -FallbackExePath $base
        if ($src) { return $src }
      }
    }

    return (Get-GenericAppIconImageSource)
  } catch {
    return $null
  }
}

function Get-GenericAppIconImageSource {
  try {
    $ico = [System.Drawing.SystemIcons]::Application
    if ($ico) {
      $src = Convert-HIconToImageSource -HIcon $ico.Handle
      if ($src) { return $src }
    }
  } catch {}
  return $null
}

function Test-ValidFileName {
  param([Parameter(Mandatory=$true)][string]$Name)

  $n = (Trim-NameInputPreserveNbsp -Text $Name)
  if ([string]::IsNullOrWhiteSpace($n)) { return $false }

  foreach ($c in [IO.Path]::GetInvalidFileNameChars()) {
    if ($n.Contains([string]$c)) { return $false }
  }

  if ($n.EndsWith(" ") -or $n.EndsWith(".")) { return $false }
  return $true
}

function Trim-NameInputPreserveNbsp {
  param([string]$Text)
  try {
    $s = [string]$Text
    if ($null -eq $s) { return '' }
    # Trim only regular ASCII whitespace around input.
    # Intentionally preserve U+00A0 (NBSP) so Alt+0160 can be kept in names.
    return $s.Trim([char[]]@(0x20,0x09,0x0D,0x0A))
  } catch {
    try { return [string]$Text } catch { return '' }
  }
}
function Get-FolderRowIcon {
  try {
    $isNewBuild = $false
    try { $isNewBuild = [bool](Get-IsWindowsBuildAbove1809Runtime) } catch { $isNewBuild = $false }
    if ($isNewBuild) {
      $mmc = Join-Path $env:WINDIR "System32\mmcndmgr.dll"
      $srcMmc = Get-ImageSourceFromIcon -IconPath $mmc -IconIndex 0 -FallbackExePath $mmc
      if (-not $srcMmc) { $srcMmc = Get-ImageSourceFromIcon -IconPath $mmc -IconIndex (-0) -FallbackExePath $mmc }
      if ($srcMmc) { return $srcMmc }
    } else {
      $dm = Join-Path $env:WINDIR "System32\dmdskres.dll"
      $srcDm = Get-ImageSourceFromIcon -IconPath $dm -IconIndex 11 -FallbackExePath $dm
      if (-not $srcDm) { $srcDm = Get-ImageSourceFromIcon -IconPath $dm -IconIndex (-11) -FallbackExePath $dm }
      if ($srcDm) { return $srcDm }
    }
    $img = Join-Path $env:WINDIR "System32\imageres.dll"
    $src = Get-ImageSourceFromIcon -IconPath $img -IconIndex 5 -FallbackExePath $img
    if ($src) { return $src }
    $shell32 = Join-Path $env:WINDIR "System32\shell32.dll"
    return (Get-ImageSourceFromIcon -IconPath $shell32 -IconIndex 3 -FallbackExePath $shell32)
  } catch {
    return $null
  }
}

function Get-DuplicateTargetOverlayIconSource {
  try {
    if ($script:DuplicateTargetOverlayIconSource) { return $script:DuplicateTargetOverlayIconSource }
    $img = Join-Path $env:WINDIR "System32\compstui.dll"
    $src = $null
    try { $src = Get-ImageSourceFromIcon -IconPath $img -IconIndex 2 -FallbackExePath $img } catch { $src = $null }
    if ($src) {
      try { $src.Freeze() } catch {}
      $script:DuplicateTargetOverlayIconSource = $src
      return $script:DuplicateTargetOverlayIconSource
    }
  } catch {}
  return $null
}

function Get-BrokenLinkOverlayIconSource {
