  } catch {}
  return $null
}
function Darken-ImageSourceRgb {
  param(
    [System.Windows.Media.ImageSource]$Source,
    [double]$Factor = 0.60
  )
  try {
    if (-not $Source) { return $null }
    $bmp = $Source -as [System.Windows.Media.Imaging.BitmapSource]
    if (-not $bmp) { return $Source }

    $f = [double]$Factor
    if ($f -lt 0.0) { $f = 0.0 }
    if ($f -gt 1.0) { $f = 1.0 }
    if ([Math]::Abs($f - 1.0) -lt 0.0001) { return $Source }

    $w = [int]$bmp.PixelWidth
    $h = [int]$bmp.PixelHeight
    if ($w -le 0 -or $h -le 0) { return $Source }

    # Simple darken pass: draw icon as-is, then overlay black with alpha based on factor.
    $overlayAlpha = [int][Math]::Round((1.0 - $f) * 255.0)
    if ($overlayAlpha -lt 0) { $overlayAlpha = 0 }
    if ($overlayAlpha -gt 255) { $overlayAlpha = 255 }

    $dv = New-Object System.Windows.Media.DrawingVisual
    $dc = $dv.RenderOpen()
    $rect = New-Object System.Windows.Rect(0, 0, $w, $h)
    $dc.DrawImage($bmp, $rect)
    if ($overlayAlpha -gt 0) {
      $brush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb([byte]$overlayAlpha, 0, 0, 0))
      $dc.DrawRectangle($brush, $null, $rect)
    }
    $dc.Close()

    $rtb = New-Object System.Windows.Media.Imaging.RenderTargetBitmap($w, $h, 96.0, 96.0, [System.Windows.Media.PixelFormats]::Pbgra32)
    $rtb.Render($dv)
    try { $rtb.Freeze() } catch {}
    return $rtb
  } catch {
    return $Source
  }
}

function Get-SystemIconSourcePathsFromCategoryProfiles {
  $out = New-Object System.Collections.Generic.List[string]
  $seen = @{}
  try {
    $root = Get-SystemIconCategoriesRootPath
    if ([string]::IsNullOrWhiteSpace($root) -or -not (Test-Path -LiteralPath $root -PathType Container)) {
      return @()
    }
    $files = @()
    try { $files = @(Get-ChildItem -LiteralPath $root -File -Filter *.json -ErrorAction SilentlyContinue | Sort-Object Name) } catch { $files = @() }
    foreach ($f in @($files)) {
      if (-not $f) { continue }
      $json = ''
      try { $json = Get-Content -LiteralPath ([string]$f.FullName) -Raw -Encoding UTF8 } catch { $json = '' }
      if ([string]::IsNullOrWhiteSpace($json)) { continue }
      $obj = $null
      try { $obj = $json | ConvertFrom-Json } catch { $obj = $null }
      if (-not $obj) { continue }
      $entries = @()
      try {
        if ($obj.PSObject.Properties.Match('Assignments').Count -gt 0) { $entries = @($obj.Assignments) }
        elseif ($obj.PSObject.Properties.Match('IconAssignments').Count -gt 0) { $entries = @($obj.IconAssignments) }
        elseif ($obj.PSObject.Properties.Match('Items').Count -gt 0) { $entries = @($obj.Items) }
      } catch { $entries = @() }
      foreach ($e in @($entries)) {
        if (-not $e) { continue }
        $ip = ''
        try { if ($e.PSObject.Properties.Match('IconPath').Count -gt 0) { $ip = [string]$e.IconPath } } catch { $ip = '' }
        $p = Normalize-Path $ip
        if ([string]::IsNullOrWhiteSpace($p)) { continue }
        if (-not (Test-Path -LiteralPath $p -PathType Leaf)) { continue }
        $k = $p.ToLowerInvariant()
        if ($seen.ContainsKey($k)) { continue }
        $seen[$k] = $true
        [void]$out.Add($p)
      }
    }
  } catch {}
  return @($out.ToArray())
}

function Get-CreateShortcutSystemIconSources {
  $raw = @()
  $rawFromDirectoryState = $false
  try {
    $srcPath = Get-SystemIconSourceDirectoriesStatePath
    if (-not [string]::IsNullOrWhiteSpace($srcPath) -and (Test-Path -LiteralPath $srcPath -PathType Leaf)) {
      $json = Get-Content -LiteralPath $srcPath -Raw -Encoding UTF8
      if (-not [string]::IsNullOrWhiteSpace($json)) {
        $obj = $json | ConvertFrom-Json
        if ($obj -is [array]) {
          $raw = @($obj | ForEach-Object { [string]$_ })
        } else {
          $candidate = @()
          try {
            if ($obj.PSObject.Properties.Match('Directories').Count -gt 0) { $candidate = @($obj.Directories) }
            elseif ($obj.PSObject.Properties.Match('Sources').Count -gt 0) { $candidate = @($obj.Sources) }
            elseif ($obj.PSObject.Properties.Match('IconSources').Count -gt 0) { $candidate = @($obj.IconSources) }
            elseif ($obj.PSObject.Properties.Match('Items').Count -gt 0) { $candidate = @($obj.Items) }
          } catch { $candidate = @() }
          if (@($candidate).Count -gt 0) {
            $raw = @($candidate | ForEach-Object { [string]$_ })
          } elseif ($obj -is [string]) {
            $raw = @([string]$obj)
          } else {
            $raw = @()
          }
        }
        $rawFromDirectoryState = $true
      }
    }
  } catch {}
  if (@($raw).Count -eq 0) {
    try { $raw = @(Get-SystemIconSourcePathsFromCategoryProfiles) } catch { $raw = @() }
  }
  if (@($raw).Count -eq 0) { return @() }

  $out = New-Object System.Collections.Generic.List[string]
  $seen = @{}
  $extSet = @('.dll','.exe','.cpl','.icl')
  $maxDirFiles = 2500
  foreach ($r in $raw) {
    $p = ''
    try { $p = [Environment]::ExpandEnvironmentVariables([string]$r) } catch { $p = [string]$r }
    if ([string]::IsNullOrWhiteSpace($p)) { continue }
    $p = (Normalize-Path $p)
    if ([string]::IsNullOrWhiteSpace($p)) { continue }
    if (-not (Test-Path -LiteralPath $p)) { continue }

    $isDir = $false
    try { $isDir = Test-Path -LiteralPath $p -PathType Container } catch { $isDir = $false }
    if ($isDir) {
      try {
        $picked = 0
        Get-ChildItem -LiteralPath $p -File -Recurse -Force -ErrorAction SilentlyContinue |
          Where-Object {
            try { $extSet -contains ([string]$_.Extension).ToLowerInvariant() } catch { $false }
          } |
          ForEach-Object {
            if ($picked -ge $maxDirFiles) { return }
            $fp = ''
            try { $fp = Normalize-Path ([string]$_.FullName) } catch { $fp = '' }
            if ([string]::IsNullOrWhiteSpace($fp)) { return }
            $k = $fp.ToLowerInvariant()
            if ($seen.ContainsKey($k)) { return }
            $seen[$k] = $true
            [void]$out.Add($fp)
            $picked++
          }
      } catch {}
      continue
    }

    $k = $p.ToLowerInvariant()
    if ($seen.ContainsKey($k)) { continue }
    $seen[$k] = $true
    [void]$out.Add($p)
  }
  if (@($out).Count -eq 0 -and $rawFromDirectoryState) {
    try {
      $fallback = @(Get-SystemIconSourcePathsFromCategoryProfiles)
      if (@($fallback).Count -gt 0) { return @($fallback) }
    } catch {}
  }
  return @($out.ToArray())
}

function Get-SystemIconUserSettingsRoot {
  try {
    $baseDir = ''
    try { $baseDir = Split-Path -Parent $PSCommandPath } catch { $baseDir = '' }
    if ([string]::IsNullOrWhiteSpace($baseDir)) {
      try { $baseDir = Split-Path -Parent $MyInvocation.MyCommand.Path } catch { $baseDir = '' }
    }
    if ([string]::IsNullOrWhiteSpace($baseDir)) { $baseDir = (Get-Location).Path }
    $dir = Join-Path $baseDir 'User Settings'
    if (-not (Test-Path -LiteralPath $dir -PathType Container)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    return [string]$dir
  } catch { return '' }
}

function Get-SystemIconCategoriesRootPath {
  try {
    $root = Get-SystemIconUserSettingsRoot
    if ([string]::IsNullOrWhiteSpace($root)) { return '' }
    $dir = Join-Path $root 'Icon Categories'
    if (-not (Test-Path -LiteralPath $dir -PathType Container)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    return [string]$dir
  } catch { return '' }
}

function Get-SystemIconSourceDirectoriesStatePath {
  try {
    $root = Get-SystemIconUserSettingsRoot
    if ([string]::IsNullOrWhiteSpace($root)) { return '' }
    return (Join-Path $root 'IconSourceDirectories.json')
  } catch { return '' }
}

function Get-IconCountForFile {
  param([Parameter(Mandatory=$true)][string]$Path)
  try {
    $p = Normalize-Path $Path
    if ([string]::IsNullOrWhiteSpace($p) -or -not (Test-Path -LiteralPath $p)) { return 0 }
    $c = [IconNative]::ExtractIconEx($p, -1, $null, $null, 0)
    try { return [int]$c } catch { return 0 }
  } catch {
    return 0
  }
}

function Get-SystemIconCategoryMapDefaultPath {
  try {
    $catDir = Get-SystemIconCategoriesRootPath
    if ([string]::IsNullOrWhiteSpace($catDir)) { return 'IconCategoryAssignments.json' }
    return (Join-Path $catDir 'IconCategoryAssignments.json')
  } catch {
    return 'IconCategoryAssignments.json'
  }
}

function Get-SystemIconCatalogKey {
  param(
    [Parameter(Mandatory=$true)][string]$SourcePath,
    [Parameter(Mandatory=$true)][int]$IconIndex
  )
  $p = ''
  try { $p = Normalize-Path ([string]$SourcePath) } catch { $p = [string]$SourcePath }
  if ([string]::IsNullOrWhiteSpace($p)) { return '' }
  try { $p = $p.Trim([char[]]@(0x20,0x09,0x0D,0x0A)).ToLowerInvariant() } catch {}
  return ("{0},{1}" -f $p, [int]$IconIndex)
}

function Normalize-SystemIconCategoryName {
  param([string]$Name)
  $n = ''
  try { $n = [string]$Name } catch { $n = '' }
  return $n.Trim()
}

function Sync-SystemIconCategoryListFromState {
  try {
    if (-not ($script:SystemIconDefaultCategoryList -is [array])) { $script:SystemIconDefaultCategoryList = @() }
    if (-not ($script:SystemIconUserCategoryList -is [array])) { $script:SystemIconUserCategoryList = @() }
    if (-not ($script:SystemIconDeletedCategorySet -is [hashtable])) { $script:SystemIconDeletedCategorySet = @{} }
    if (-not ($script:SystemIconSelectedCategories -is [hashtable])) { $script:SystemIconSelectedCategories = @{} }
    $list = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    foreach ($c in @($script:SystemIconDefaultCategoryList)) {
      $n = Normalize-SystemIconCategoryName -Name ([string]$c)
      if ([string]::IsNullOrWhiteSpace($n)) { continue }
      if ($script:SystemIconDeletedCategorySet.ContainsKey($n.ToLowerInvariant())) { continue }
      $k = $n.ToLowerInvariant()
      if ($seen.ContainsKey($k)) { continue }
      $seen[$k] = $true
      [void]$list.Add($n)
    }
    foreach ($c in @($script:SystemIconUserCategoryList)) {
      $n = Normalize-SystemIconCategoryName -Name ([string]$c)
      if ([string]::IsNullOrWhiteSpace($n)) { continue }
      if ($script:SystemIconDeletedCategorySet.ContainsKey($n.ToLowerInvariant())) { continue }
      $k = $n.ToLowerInvariant()
      if ($seen.ContainsKey($k)) { continue }
      $seen[$k] = $true
      [void]$list.Add($n)
    }
    $script:SystemIconCategoryList = @($list.ToArray())
    foreach ($k in @($script:SystemIconSelectedCategories.Keys)) {
      if ([string]::IsNullOrWhiteSpace([string]$k)) { continue }
      $kn = [string]$k
      if (-not $seen.ContainsKey($kn.ToLowerInvariant())) {
        try { [void]$script:SystemIconSelectedCategories.Remove($kn) } catch {}
      }
    }
  } catch {}
}

function Remove-SystemIconCategories {
  param([string[]]$Names)
  try {
    $targets = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    foreach ($x in @($Names)) {
      $n = Normalize-SystemIconCategoryName -Name ([string]$x)
      if ([string]::IsNullOrWhiteSpace($n)) { continue }
      $k = $n.ToLowerInvariant()
      if ($seen.ContainsKey($k)) { continue }
      $seen[$k] = $true
      [void]$targets.Add($n)
    }
    if (@($targets).Count -eq 0) {
      return [pscustomobject]@{ RemovedCategories = 0; UpdatedAssignments = 0 }
    }

    $defaultSet = @{}
    foreach ($d in @($script:SystemIconDefaultCategoryList)) {
      $dn = Normalize-SystemIconCategoryName -Name ([string]$d)
      if ([string]::IsNullOrWhiteSpace($dn)) { continue }
      $defaultSet[$dn.ToLowerInvariant()] = $dn
    }

    $removedCategoryCount = 0
    foreach ($n in @($targets.ToArray())) {
      $lk = $n.ToLowerInvariant()
      if ($defaultSet.ContainsKey($lk)) {
        $script:SystemIconDeletedCategorySet[$lk] = $n
      }
      $newUser = New-Object System.Collections.Generic.List[string]
      foreach ($u in @($script:SystemIconUserCategoryList)) {
        $un = Normalize-SystemIconCategoryName -Name ([string]$u)
        if ([string]::IsNullOrWhiteSpace($un)) { continue }
        if ($un.ToLowerInvariant() -eq $lk) { continue }
        [void]$newUser.Add($un)
      }
      $script:SystemIconUserCategoryList = @($newUser.ToArray())
      try { if ($script:SystemIconSelectedCategories.ContainsKey($n)) { [void]$script:SystemIconSelectedCategories.Remove($n) } } catch {}
      $removedCategoryCount++
    }

    $changedAssignments = 0
    foreach ($k in @($script:SystemIconManualCategoryByKey.Keys)) {
      $cats = @()
      try { $cats = @($script:SystemIconManualCategoryByKey[$k]) } catch { $cats = @() }
      if (@($cats).Count -eq 0) { continue }
      $newCats = New-Object System.Collections.Generic.List[string]
      $changed = $false
      foreach ($c in @($cats)) {
        $cn = Normalize-SystemIconCategoryName -Name ([string]$c)
        if ([string]::IsNullOrWhiteSpace($cn)) { continue }
        if ($seen.ContainsKey($cn.ToLowerInvariant())) { $changed = $true; continue }
        [void]$newCats.Add($cn)
      }
      if ($changed) {
        $changedAssignments++
        if (@($newCats).Count -eq 0) {
          try { [void]$script:SystemIconManualCategoryByKey.Remove($k) } catch {}
        } else {
          $script:SystemIconManualCategoryByKey[$k] = @($newCats.ToArray())
        }
      }
    }

    $manualSet = @{}
    foreach ($k in @($script:SystemIconManualCategoryByKey.Keys)) {
      foreach ($c in @($script:SystemIconManualCategoryByKey[$k])) {
        $cn = Normalize-SystemIconCategoryName -Name ([string]$c)
        if ([string]::IsNullOrWhiteSpace($cn)) { continue }
        if ($script:SystemIconDeletedCategorySet.ContainsKey($cn.ToLowerInvariant())) { continue }
        $manualSet[$cn.ToLowerInvariant()] = $cn
      }
    }
    $script:SystemIconManualCategoryList = @($manualSet.Values | Sort-Object -Unique)
    foreach ($mc in @($script:SystemIconManualCategoryList)) {
      $n = Normalize-SystemIconCategoryName -Name ([string]$mc)
      if ([string]::IsNullOrWhiteSpace($n)) { continue }
      if ($script:SystemIconDeletedCategorySet.ContainsKey($n.ToLowerInvariant())) { continue }
      if (-not (@($script:SystemIconUserCategoryList) -contains $n)) { $script:SystemIconUserCategoryList += $n }
    }

    Sync-SystemIconCategoryListFromState
    $script:SystemIconCatalogLoaded = $false
    $script:SystemIconCatalogAll = @()
    $script:SystemIconSearchIndexReady = $false
    $script:SystemIconTokenIndex = @{}
    $script:SystemIconCategoryIndex = @{}
    $script:SystemIconCurrentPage = 1
    try { Rebuild-SystemIconCategoryChecklistUi } catch {}
    try { Queue-CreateSystemIconRefresh -Immediate } catch {}

    return [pscustomobject]@{
      RemovedCategories = [int]$removedCategoryCount
      UpdatedAssignments = [int]$changedAssignments
    }
  } catch {
    return [pscustomobject]@{ RemovedCategories = 0; UpdatedAssignments = 0 }
  }
}

function Get-SystemIconManualCategoriesForIcon {
  param(
    [Parameter(Mandatory=$true)][string]$SourcePath,
    [Parameter(Mandatory=$true)][int]$IconIndex
  )
  try {
    if (-not $script:SystemIconManualCategoryByKey) { return @() }
    $k = Get-SystemIconCatalogKey -SourcePath $SourcePath -IconIndex $IconIndex
    if ([string]::IsNullOrWhiteSpace($k)) { return @() }
    $v = @()
    try { $v = @($script:SystemIconManualCategoryByKey[$k]) } catch { $v = @() }
    $out = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    foreach ($c in $v) {
      $n = ''
      try { $n = [string]$c } catch { $n = '' }
      $n = $n.Trim()
      if ([string]::IsNullOrWhiteSpace($n)) { continue }
      $lk = $n.ToLowerInvariant()
      if ($seen.ContainsKey($lk)) { continue }
      $seen[$lk] = $true
      [void]$out.Add($n)
    }
    return @($out.ToArray())
  } catch {
    return @()
  }
}

function Import-SystemIconCategoryAssociationsFromFile {
  param(
    [Parameter(Mandatory=$true)][string]$Path,
    [string]$ForcedCategory = '',
    [switch]$SkipUiRefresh,
    [switch]$Silent
  )
  $res = [pscustomobject]@{
    Ok = $false
    Path = [string]$Path
    AssignmentCount = 0
    CategoryCount = 0
    Error = ''
  }
  try {
    $p = Normalize-Path ([string]$Path)
    if ([string]::IsNullOrWhiteSpace($p) -or -not (Test-Path -LiteralPath $p -PathType Leaf)) {
      throw "Category file not found."
    }
    $json = Get-Content -LiteralPath $p -Raw -Encoding UTF8
    if ([string]::IsNullOrWhiteSpace($json)) { throw "Category file is empty." }
    $obj = $json | ConvertFrom-Json
    if (-not $obj) { throw "Invalid category JSON." }

    $entries = @()
    try {
      if ($obj.PSObject.Properties.Match('Assignments').Count -gt 0) { $entries = @($obj.Assignments) }
      elseif ($obj.PSObject.Properties.Match('IconAssignments').Count -gt 0) { $entries = @($obj.IconAssignments) }
      elseif ($obj.PSObject.Properties.Match('Items').Count -gt 0) { $entries = @($obj.Items) }
    } catch { $entries = @() }
    if (@($entries).Count -eq 0) { throw "No assignments were found in the category file." }

    $map = @{}
    $catSet = @{}
    $forced = ''
    try { $forced = Normalize-SystemIconCategoryName -Name ([string]$ForcedCategory) } catch { $forced = '' }
    if ([string]::IsNullOrWhiteSpace($forced)) { $forced = '' }
    foreach ($e in $entries) {
      if (-not $e) { continue }
      $iconPath = ''
      $iconIndex = 0
      $catsRaw = @()
      try { if ($e.PSObject.Properties.Match('IconPath').Count -gt 0) { $iconPath = [string]$e.IconPath } } catch {}
      try {
        if ($e.PSObject.Properties.Match('IconIndex').Count -gt 0) { $iconIndex = [int]$e.IconIndex }
        elseif ($e.PSObject.Properties.Match('Index').Count -gt 0) { $iconIndex = [int]$e.Index }
      } catch { $iconIndex = 0 }
      if (-not [string]::IsNullOrWhiteSpace($forced)) {
        $catsRaw = @($forced)
      } else {
        try {
          if ($e.PSObject.Properties.Match('Categories').Count -gt 0) { $catsRaw = @($e.Categories) }
          elseif ($e.PSObject.Properties.Match('Category').Count -gt 0) { $catsRaw = @([string]$e.Category) }
        } catch { $catsRaw = @() }
      }

      $normPath = Normalize-Path $iconPath
      if ([string]::IsNullOrWhiteSpace($normPath)) { continue }
      $cats = New-Object System.Collections.Generic.List[string]
      $seenCats = @{}
      foreach ($c in @($catsRaw)) {
        $n = ''
        try { $n = [string]$c } catch { $n = '' }
        $n = $n.Trim()
        if ([string]::IsNullOrWhiteSpace($n)) { continue }
        $lk = $n.ToLowerInvariant()
        if ($seenCats.ContainsKey($lk)) { continue }
        $seenCats[$lk] = $true
        [void]$cats.Add($n)
        $catSet[$lk] = $n
      }
      if (@($cats).Count -eq 0) { continue }
      $k = Get-SystemIconCatalogKey -SourcePath $normPath -IconIndex $iconIndex
      if ([string]::IsNullOrWhiteSpace($k)) { continue }
      $map[$k] = @($cats.ToArray())
    }
    if (@($map.Keys).Count -eq 0) { throw "No valid assignments were parsed." }

    if (-not ($script:SystemIconManualCategoryByKey -is [hashtable])) { $script:SystemIconManualCategoryByKey = @{} }
    foreach ($k in @($map.Keys)) {
      $incoming = @($map[$k])
      if (-not $script:SystemIconManualCategoryByKey.ContainsKey($k)) {
        $script:SystemIconManualCategoryByKey[$k] = @($incoming)
        continue
      }
      $existing = @()
      try { $existing = @($script:SystemIconManualCategoryByKey[$k]) } catch { $existing = @() }
      $merged = New-Object System.Collections.Generic.List[string]
      $seenM = @{}
      foreach ($c in @($existing + $incoming)) {
        $n = Normalize-SystemIconCategoryName -Name ([string]$c)
        if ([string]::IsNullOrWhiteSpace($n)) { continue }
        if ($script:SystemIconDeletedCategorySet.ContainsKey($n.ToLowerInvariant())) { [void]$script:SystemIconDeletedCategorySet.Remove($n.ToLowerInvariant()) }
        $lk = $n.ToLowerInvariant()
        if ($seenM.ContainsKey($lk)) { continue }
        $seenM[$lk] = $true
        [void]$merged.Add($n)
      }
      $script:SystemIconManualCategoryByKey[$k] = @($merged.ToArray())
    }

    $manualSet = @{}
    foreach ($k in @($script:SystemIconManualCategoryByKey.Keys)) {
      foreach ($c in @($script:SystemIconManualCategoryByKey[$k])) {
        $n = Normalize-SystemIconCategoryName -Name ([string]$c)
        if ([string]::IsNullOrWhiteSpace($n)) { continue }
        if ($script:SystemIconDeletedCategorySet.ContainsKey($n.ToLowerInvariant())) { continue }
        $manualSet[$n.ToLowerInvariant()] = $n
      }
    }
    $script:SystemIconManualCategoryList = @($manualSet.Values | Sort-Object -Unique)
    $script:SystemIconManualCategoryMapPath = [string]$p

    foreach ($c in @($catSet.Values)) {
      $n = Normalize-SystemIconCategoryName -Name ([string]$c)
      if ([string]::IsNullOrWhiteSpace($n)) { continue }
      if ($script:SystemIconDeletedCategorySet.ContainsKey($n.ToLowerInvariant())) { [void]$script:SystemIconDeletedCategorySet.Remove($n.ToLowerInvariant()) }
      if (-not (@($script:SystemIconUserCategoryList) -contains $n)) { $script:SystemIconUserCategoryList += $n }
      $script:SystemIconSelectedCategories[$n] = $true
    }
    foreach ($c in @($script:SystemIconManualCategoryList)) {
      $n = Normalize-SystemIconCategoryName -Name ([string]$c)
      if ([string]::IsNullOrWhiteSpace($n)) { continue }
      if (-not (@($script:SystemIconUserCategoryList) -contains $n)) { $script:SystemIconUserCategoryList += $n }
      $script:SystemIconSelectedCategories[$n] = $true
    }
    Sync-SystemIconCategoryListFromState

    $script:SystemIconCatalogLoaded = $false
    $script:SystemIconCatalogAll = @()
    $script:SystemIconSearchIndexReady = $false
    $script:SystemIconTokenIndex = @{}
    $script:SystemIconCategoryIndex = @{}
    $script:SystemIconCurrentPage = 1

    try { Rebuild-SystemIconCategoryChecklistUi } catch {}
    try { Update-SystemIconCategoryButtonCaption } catch {}
    if (-not $SkipUiRefresh) {
      try { Queue-CreateSystemIconRefresh -Immediate } catch {}
    }

    $res.Ok = $true
    $res.AssignmentCount = @($map.Keys).Count
    $res.CategoryCount = @($catSet.Values | Sort-Object -Unique).Count
    return $res
  } catch {
    $res.Error = [string]$_.Exception.Message
    if (-not $Silent) {
      [System.Windows.MessageBox]::Show(
        ("Failed to import icon category associations.`n`n" + $res.Error),
        "Upload Categories",
        [System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]::Error
      ) | Out-Null
    }
    return $res
  }
}

function Import-SystemIconCategoriesFromFolder {
  param([switch]$Silent)
  $res = [pscustomobject]@{
    Ok = $false
    Folder = ''
    FileCount = 0
    ImportedFiles = 0
    AssignmentCount = 0
    CategoryCount = 0
    Error = ''
  }
  try {
    $root = Get-SystemIconCategoriesRootPath
    $res.Folder = [string]$root
    if ([string]::IsNullOrWhiteSpace($root) -or -not (Test-Path -LiteralPath $root -PathType Container)) {
      throw "Icon category folder not found."
    }
    $files = @()
    try { $files = @(Get-ChildItem -LiteralPath $root -File -Filter *.json -ErrorAction SilentlyContinue | Sort-Object Name) } catch { $files = @() }
    $files = @($files | Where-Object { $_ -and ([string]$_.Name).Trim().ToLowerInvariant() -ne 'iconsourcedirectories.json' })
    $res.FileCount = @($files).Count
    if (@($files).Count -eq 0) {
      $res.Ok = $true
      return $res
    }

    foreach ($f in @($files)) {
      if (-not $f) { continue }
      $rr = $null
      $forcedCat = ''
      try { $forcedCat = [System.IO.Path]::GetFileNameWithoutExtension([string]$f.Name) } catch { $forcedCat = '' }
      try { $forcedCat = Normalize-SystemIconCategoryName -Name ([string]$forcedCat) } catch {}
      try { $rr = Import-SystemIconCategoryAssociationsFromFile -Path ([string]$f.FullName) -ForcedCategory $forcedCat -SkipUiRefresh -Silent:$true } catch { $rr = $null }
      if ($rr -and [bool]$rr.Ok) {
        $res.ImportedFiles++
        try { $res.AssignmentCount += [int]$rr.AssignmentCount } catch {}
        try { $res.CategoryCount += [int]$rr.CategoryCount } catch {}
      }
    }
    $res.Ok = $true
    return $res
  } catch {
    $res.Error = [string]$_.Exception.Message
    if (-not $Silent) {
      try {
        [System.Windows.MessageBox]::Show(
          ("Failed to load icon categories from folder.`n`n" + $res.Error),
          "Icon Categories",
          [System.Windows.MessageBoxButton]::OK,
          [System.Windows.MessageBoxImage]::Error
        ) | Out-Null
      } catch {}
    }
    return $res
  }
}

function Get-SystemIconCategorySpec {
  param(
    [Parameter(Mandatory=$true)][string]$SourcePath,
    [Parameter(Mandatory=$true)][int]$IconIndex
  )

  $leaf = ''
  try { $leaf = [System.IO.Path]::GetFileName([string]$SourcePath).ToLowerInvariant() } catch { $leaf = [string]$SourcePath }

  $category = ''
  $keywords = 'general common windows icon app shortcut file status ui'
  $tags = New-Object System.Collections.Generic.List[string]

  # Module-level categories following the directory reference grouping requested by user.
  switch -Regex ($leaf) {
    '^compstui\.dll$' {
      $category = 'Common Property Sheet UI'
      $keywords = 'property sheet dialog tab interface ui wizard controls settings configure'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Common Property Sheet UI'); [void]$tags.Add('UI')
      break
    }
    '^ddores\.dll$' {
      $category = 'Device Category & Resources'
      $keywords = 'device hardware resource category computer monitor printer keyboard mouse driver'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Device Category & Resources'); [void]$tags.Add('Devices')
      break
    }
    '^ieframe\.dll$' {
      $category = 'Internet Explorer'
      $keywords = 'internet explorer browser web page site ie html link security'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Internet Explorer'); [void]$tags.Add('Browser')
      break
    }
    '^inetcpl\.cpl$' {
      $category = 'Internet Control Panel'
      $keywords = 'internet control panel browser settings privacy security zones content connections'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Internet Control Panel'); [void]$tags.Add('Browser')
      break
    }
    '^imageres\.dll$' {
      $category = 'Windows Image Resource'
      $keywords = 'windows image resources folder file drive desktop computer icon generic'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Windows Image Resource'); [void]$tags.Add('Folders')
      break
    }
    '^mmcndmgr\.dll$' {
      $category = 'MMC Node Manager'
      $keywords = 'mmc node manager management console admin tools snapin server system'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('MMC Node Manager'); [void]$tags.Add('Management')
      break
    }
    '^moricons\.dll$' {
      $category = 'Windows NT Setup Icon Resources'
      $keywords = 'windows nt setup icon resources legacy classic old dos installer'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Windows NT Setup Icon Resources'); [void]$tags.Add('Legacy')
      break
    }
    '^netshell\.dll$|^pnidui\.dll$' {
      $category = 'Network Shell & System Icons'
      $keywords = 'network shell system icons wifi ethernet lan internet connection adapter'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Network Shell & System Icons'); [void]$tags.Add('Networking')
      break
    }
    '^shell32\.dll$' {
      $category = 'Windows Shell Common'
      $keywords = 'windows shell common folder file desktop explorer control panel shortcut'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Windows Shell Common'); [void]$tags.Add('Shell')
      break
    }
    '^wmploc\.dll$' {
      $category = 'Windows Media Player Resources'
      $keywords = 'windows media player music audio video play pause speaker note'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Windows Media Player Resources'); [void]$tags.Add('Audio')
      break
    }
    '^pifmgr\.dll$' {
      $category = 'Windows NT PIF Manager Icons'
      $keywords = 'windows nt pif manager icon resources legacy classic old dos'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Windows NT PIF Manager Icons'); [void]$tags.Add('Legacy')
      break
    }
    '^wpdshext\.dll$' {
      $category = 'Portable Devices Shell Extension'
      $keywords = 'portable devices shell extension phone camera usb mobile sync transfer'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Portable Devices Shell Extension'); [void]$tags.Add('Devices')
      break
    }
    '^comres\.dll$' {
      $category = 'COM+ Resources'
      $keywords = 'com plus resources service component enterprise status warning system'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('COM+ Resources'); [void]$tags.Add('System')
      break
    }
    '^dmdskres\.dll$' {
      $category = 'Disk Management Support'
      $keywords = 'disk management support partition volume storage drive format mount'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Disk Management Support'); [void]$tags.Add('Storage')
      break
    }
    '^dsuiext\.dll$' {
      $category = 'Directory Service Common UI'
      $keywords = 'directory service common ui active directory domain users groups admin'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Directory Service Common UI'); [void]$tags.Add('Directory')
      break
    }
    '^mstsc\.exe$' {
      $category = 'Remote Desktop Client'
      $keywords = 'remote desktop client rdp terminal session host connection server'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Remote Desktop Client'); [void]$tags.Add('Remote Desktop')
      break
    }
    '^mstscax\.dll$|^shdocvw\.dll$' {
      $category = 'Remote Desktop AX + Shell Doc'
      $keywords = 'remote desktop activex shell doc object control rdp session client'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Remote Desktop AX + Shell Doc'); [void]$tags.Add('Remote Desktop')
      break
    }
    '^setupapi\.dll$' {
      $category = 'Windows Setup API'
      $keywords = 'windows setup api install installer driver device package deployment'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Windows Setup API'); [void]$tags.Add('Setup')
      break
    }
    '^wiashext\.dll$' {
      $category = 'Imaging Devices Shell UI'
      $keywords = 'imaging devices shell ui scanner camera photo import image picture'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('Imaging Devices Shell UI'); [void]$tags.Add('Imaging')
      break
    }
    '^mmres\.dll$' {
      $category = 'General Audio Resources'
      $keywords = 'general audio resources sound speaker volume music wave multimedia'
      $tags = [System.Collections.Generic.List[string]]::new(); [void]$tags.Add('General Audio Resources'); [void]$tags.Add('Audio')
      break
    }
    default {
      $category = ''
      $keywords = 'general common windows icon app shortcut file status ui'
      $tags = [System.Collections.Generic.List[string]]::new()
      break
    }
  }

  $mergedTags = New-Object System.Collections.Generic.List[string]
  $seenTag = @{}

  # Strict category isolation:
  # use only categories assigned from files in User Settings\Icon Categories.
  # If an icon has no assignment, do not place it in any fallback category.
  $manualCats = @(Get-SystemIconManualCategoriesForIcon -SourcePath $SourcePath -IconIndex $IconIndex)
  if (@($manualCats).Count -gt 0) {
    $category = [string]$manualCats[0]
    foreach ($mc in @($manualCats)) {
      $n = ''
      try { $n = [string]$mc } catch { $n = '' }
      $n = $n.Trim()
      if ([string]::IsNullOrWhiteSpace($n)) { continue }
      $k = $n.ToLowerInvariant()
      if ($seenTag.ContainsKey($k)) { continue }
      $seenTag[$k] = $true
      [void]$mergedTags.Add($n)
    }
  } else {
    $category = ''
  }

  return [pscustomobject]@{
    Category = [string]$category
    Keywords = [string]$keywords
    Tags     = @($mergedTags.ToArray())
  }
}

function Get-SystemIconTokens {
  param([string]$Text)
  $s = ''
  try { $s = [string]$Text } catch { $s = '' }
  if ([string]::IsNullOrWhiteSpace($s)) { return @() }
  $seen = @{}
  $out = New-Object System.Collections.Generic.List[string]
  $parts = @()
  try { $parts = @($s.ToLowerInvariant() -split '[^a-z0-9]+' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) } catch { $parts = @() }
  foreach ($p in $parts) {
    if ($p.Length -lt 2) { continue }
    if ($seen.ContainsKey($p)) { continue }
    $seen[$p] = $true
    [void]$out.Add($p)
  }
  return @($out.ToArray())
}

function Ensure-SystemIconSearchIndexes {
  if ($script:SystemIconSearchIndexReady) { return }
  $all = @($script:SystemIconCatalogAll)
  if ($all.Count -eq 0) {
    $script:SystemIconTokenIndex = @{}
    $script:SystemIconCategoryIndex = @{}
    $script:SystemIconSearchBlobByIndex = @{}
    $script:SystemIconSearchIndexReady = $true
    return
  }

  $tokIdx = @{}
  $catIdx = @{}
  $blobIdx = @{}

  for ($i = 0; $i -lt $all.Count; $i++) {
    $e = $all[$i]
    if (-not $e) { continue }

    $cats = @()
    try { $cats = @($e.Categories) } catch { $cats = @() }
    if ($cats.Count -eq 0) {
      $c0 = ''
      try { $c0 = [string]$e.Category } catch { $c0 = '' }
      if (-not [string]::IsNullOrWhiteSpace($c0)) { $cats = @($c0) }
    }
    foreach ($c in $cats) {
      if ([string]::IsNullOrWhiteSpace([string]$c)) { continue }
      if (-not $catIdx.ContainsKey([string]$c)) { $catIdx[[string]$c] = New-Object System.Collections.Generic.List[int] }
      [void]$catIdx[[string]$c].Add([int]$i)
    }

    $searchText = ''
    try { $searchText = [string]$e.SearchText } catch { $searchText = '' }
    try {
      if (-not [string]::IsNullOrWhiteSpace($searchText)) { $blobIdx[[int]$i] = $searchText.ToLowerInvariant() } else { $blobIdx[[int]$i] = '' }
    } catch {
      $blobIdx[[int]$i] = ''
    }
    foreach ($tk in @(Get-SystemIconTokens -Text $searchText)) {
      if (-not $tokIdx.ContainsKey($tk)) { $tokIdx[$tk] = New-Object System.Collections.Generic.List[int] }
      [void]$tokIdx[$tk].Add([int]$i)
    }
  }

  $script:SystemIconTokenIndex = @{}
  foreach ($k in @($tokIdx.Keys)) { $script:SystemIconTokenIndex[$k] = @($tokIdx[$k].ToArray()) }

  $script:SystemIconCategoryIndex = @{}
  foreach ($k in @($catIdx.Keys)) { $script:SystemIconCategoryIndex[$k] = @($catIdx[$k].ToArray()) }
  $script:SystemIconSearchBlobByIndex = $blobIdx

  $script:SystemIconSearchIndexReady = $true
}

function Get-SystemIconFilteredRows {
  param(
    [string[]]$SelectedCategories = @(),
    [string]$Query = ''
  )

  $all = @($script:SystemIconCatalogAll)
  if ($all.Count -eq 0) { return @() }
  Ensure-SystemIconSearchIndexes

  $candidate = @{}
  $sel = @($SelectedCategories | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
  if ($sel.Count -gt 0) {
    foreach ($c in $sel) {
      $seed = @()
      try { $seed = @($script:SystemIconCategoryIndex[[string]$c]) } catch { $seed = @() }
      foreach ($ix in $seed) { $candidate[[int]$ix] = $true }
    }
  } else {
    return @()
  }
  if ($candidate.Count -eq 0) { return @() }

  $q = ''
  try { $q = [string]$Query } catch { $q = '' }
  try { $q = $q.Trim().ToLowerInvariant() } catch { $q = '' }
  if (-not [string]::IsNullOrWhiteSpace($q)) {
    foreach ($ix in @($candidate.Keys)) {
      $ii = 0
      try { $ii = [int]$ix } catch { $ii = -1 }
      if ($ii -lt 0) {
        [void]$candidate.Remove($ix)
        continue
      }
      $blob = ''
      try {
        if ($script:SystemIconSearchBlobByIndex.ContainsKey($ii)) {
          $blob = [string]$script:SystemIconSearchBlobByIndex[$ii]
        }
      } catch { $blob = '' }
      if ([string]::IsNullOrWhiteSpace($blob)) {
        try { $blob = [string]$all[$ii].SearchText } catch { $blob = '' }
        try { if (-not [string]::IsNullOrWhiteSpace($blob)) { $blob = $blob.ToLowerInvariant() } } catch {}
        try { $script:SystemIconSearchBlobByIndex[$ii] = [string]$blob } catch {}
      }
      if ([string]::IsNullOrWhiteSpace($blob) -or (-not $blob.Contains($q))) {
        [void]$candidate.Remove($ii)
      }
    }
    if ($candidate.Count -eq 0) { return @() }
  }

  $out = New-Object System.Collections.Generic.List[object]
  for ($i = 0; $i -lt $all.Count; $i++) {
    if ($candidate.ContainsKey($i)) { [void]$out.Add($all[$i]) }
  }
  return @($out.ToArray())
}

function Queue-CreateSystemIconRefresh {
  param([switch]$Immediate)

  if ($Immediate) {
    try { if ($script:SystemIconSearchDebounceTimer) { $script:SystemIconSearchDebounceTimer.Stop() } } catch {}
    Refresh-CreateSystemIconList
    return
  }

  if (-not $script:SystemIconSearchDebounceTimer) {
    $t = New-Object System.Windows.Threading.DispatcherTimer
    try { $t.Interval = [TimeSpan]::FromMilliseconds([double]$script:SystemIconSearchDebounceMs) } catch { $t.Interval = [TimeSpan]::FromMilliseconds(180) }
    $t.Add_Tick({
      try { if ($script:SystemIconSearchDebounceTimer) { $script:SystemIconSearchDebounceTimer.Stop() } } catch {}
      try { Refresh-CreateSystemIconList } catch {}
    })
    $script:SystemIconSearchDebounceTimer = $t
  }

  try {
    $script:SystemIconSearchDebounceTimer.Stop()
    $script:SystemIconSearchDebounceTimer.Start()
  } catch {
    Refresh-CreateSystemIconList
  }
}

function Ensure-SystemIconCatalogLoaded {
  if ($script:SystemIconCatalogLoaded -and $script:SystemIconCatalogAll -and @($script:SystemIconCatalogAll).Count -gt 0) { return }

  $all = New-Object System.Collections.Generic.List[object]
  foreach ($src in @(Get-CreateShortcutSystemIconSources)) {
    if (-not $src) { continue }
    $count = Get-IconCountForFile -Path $src
    if ($count -le 0) { continue }
    for ($i = 0; $i -lt $count; $i++) {
      $img = $null
      try { $img = Get-ImageSourceFromIcon -IconPath $src -IconIndex $i -FallbackExePath $src } catch { $img = $null }
      if (-not $img) { continue }
      $leaf = ''
      try { $leaf = [System.IO.Path]::GetFileName($src) } catch { $leaf = $src }
      $spec = $null
      try { $spec = Get-SystemIconCategorySpec -SourcePath $src -IconIndex $i } catch { $spec = $null }
      $cat = ''
      $kw = ''
      $cats = @()
      if ($spec) {
        try { if (-not [string]::IsNullOrWhiteSpace([string]$spec.Category)) { $cat = [string]$spec.Category } } catch {}
        try { if (-not [string]::IsNullOrWhiteSpace([string]$spec.Keywords)) { $kw = [string]$spec.Keywords } } catch {}
        try {
          $tmpCats = @($spec.Tags)
          if ($tmpCats.Count -gt 0) { $cats = @($tmpCats) } else { $cats = @($cat) }
        } catch { $cats = @($cat) }
      }
      $searchText = ''
      try {
        $iconSpecLeaf = ([string]$leaf + ',' + [string]$i)
        $iconSpecFull = ([string]$src + ',' + [string]$i)
        $searchText = (([string]$iconSpecLeaf + ' ' + [string]$iconSpecFull + ' ' + [string]$leaf + ' ' + [string]$src + ' ' + [string]$cat + ' ' + ([string]::Join(' ', @($cats))) + ' ' + [string]$kw + ' ' + [string]$i).ToLowerInvariant())
      } catch {
        $searchText = ([string]$leaf).ToLowerInvariant()
      }
      [void]$all.Add([pscustomobject]@{
        Label     = ($leaf + ',' + [string]$i)
        IconPath  = [string]$src
        IconIndex = [int]$i
        Icon      = $img
        Category  = [string]$cat
        Categories= @($cats)
        Keywords  = [string]$kw
        SearchText= [string]$searchText
      })
    }
  }
  $script:SystemIconCatalogAll = @($all.ToArray() | Sort-Object @{Expression='Category';Ascending=$true}, @{Expression='Label';Ascending=$true})
  $script:SystemIconTokenIndex = @{}
  $script:SystemIconCategoryIndex = @{}
  $script:SystemIconSearchBlobByIndex = @{}
  $script:SystemIconSearchIndexReady = $false
  $script:SystemIconCatalogLoaded = $true
}

function Remove-PendingCreateRowById {
  param([Parameter(Mandatory=$true)][string]$Id)
  if ([string]::IsNullOrWhiteSpace($Id)) { return $false }
  if (-not $script:PendingCreateRows) { return $false }
  for ($i = $script:PendingCreateRows.Count - 1; $i -ge 0; $i--) {
    $r = $script:PendingCreateRows[$i]
    if (-not $r) { continue }
    $rid = ''
    try { $rid = [string]$r.Id } catch {}
    if ($rid -eq $Id) {
      $script:PendingCreateRows.RemoveAt($i)
      return $true
    }
  }
  return $false
}

function Add-PendingCreateRow {
  param([Parameter(Mandatory=$true)][object]$Row)
  if (-not $script:PendingCreateRows) { $script:PendingCreateRows = New-Object System.Collections.Generic.List[object] }
  if (-not $Row) { return }

  $k = ''
  try { $k = ([string]$Row.Path).Trim().ToLowerInvariant() } catch { $k = '' }
  if (-not [string]::IsNullOrWhiteSpace($k)) {
    for ($i = $script:PendingCreateRows.Count - 1; $i -ge 0; $i--) {
      $x = $script:PendingCreateRows[$i]
      if (-not $x) { continue }
      $xp = ''
      try { $xp = ([string]$x.Path).Trim().ToLowerInvariant() } catch { $xp = '' }
      if ($xp -eq $k) { $script:PendingCreateRows.RemoveAt($i) }
    }
  }
  [void]$script:PendingCreateRows.Add($Row)
  try { Touch-VisualRuntimeState -Reason "AddPendingCreate" } catch {}
}

function Get-PendingCreateRows {
  if (-not $script:PendingCreateRows) { return @() }
  $out = New-Object System.Collections.Generic.List[object]
  foreach ($r in @($script:PendingCreateRows.ToArray())) {
    if (-not $r) { continue }
    $act = ''
    try { $act = [string]$r.Action } catch {}
    if ($act -eq 'Create') { [void]$out.Add($r) }
  }
  return @($out.ToArray())
}

function Inject-PendingCreateRowsIntoVisible {
  try {
    $rows = @(Get-PendingCreateRows)
    if ($rows.Count -eq 0) { return }
    $pendingTop = New-Object System.Collections.Generic.List[object]
    foreach ($r in $rows) {
      if (-not $r) { continue }
      Add-RowIndentMeta -Row $r -Level 0
      if (([string]$r.RowKind) -eq 'Folder') { Apply-FolderIconIfNeeded -Row $r }
      Ensure-RowIconIfMissing -Row $r
      [void]$pendingTop.Add($r)
    }

    if ($pendingTop.Count -gt 0) {
      $existing = @($script:VisibleRows)
      $script:VisibleRows.Clear()
      foreach ($r in @($pendingTop.ToArray())) { [void]$script:VisibleRows.Add($r) }
      foreach ($r in $existing) { [void]$script:VisibleRows.Add($r) }
    }
  } catch {}
}

function Get-DeletedFolderMap {
  # Returns: @{ "ScopeName" = [List[string]] folderPathsLowerCase }
  $map = @{}
  foreach ($r in $script:TreeRoots) {
    $stack = New-Object System.Collections.Generic.Stack[FolderNode]
    $stack.Push($r)

    while ($stack.Count -gt 0) {
      $n = $stack.Pop()

      foreach ($f in $n.Folders) {
        if ($f.Action -eq "Delete") {
          try { if (Test-IsStartupFolderRow -Row $f) { continue } } catch {}
          $scope = [string]$f.Scope
          $p = Normalize-Path ([string]$f.Path)
          if ([string]::IsNullOrWhiteSpace($scope) -or [string]::IsNullOrWhiteSpace($p)) { continue }
          if (-not $map.ContainsKey($scope)) {
            $map[$scope] = New-Object System.Collections.Generic.List[string]
          }
          [void]$map[$scope].Add($p.ToLowerInvariant().TrimEnd('\'))
        }
      }

      foreach ($ch in $n.Children) { $stack.Push($ch) }
    }
  }
  return $map
}

function Test-IsUnderDeletedFolder {
  param(
    [Parameter(Mandatory=$true)][string]$Scope,
    [Parameter(Mandatory=$true)][string]$Path,
    [Parameter(Mandatory=$true)][hashtable]$DeletedFolderMap
  )

  if (-not $DeletedFolderMap.ContainsKey($Scope)) { return $false }

  $p = (Normalize-Path $Path)
  if ([string]::IsNullOrWhiteSpace($p)) { return $false }
  $p = $p.ToLowerInvariant()

  foreach ($fp in $DeletedFolderMap[$Scope]) {
    # If folder itself OR any descendant path
    if ($p -eq $fp) { return $true }
    if ($p.StartsWith($fp + "\")) { return $true }
  }
  return $false
}

function Find-RowById {
  param([Parameter(Mandatory=$true)][object]$Id)

  $idStr = [string]$Id
  if ([string]::IsNullOrWhiteSpace($idStr)) { return $null }

  # Visual-only proxy rows are not in TreeRoots; check them first.
  try {
    if ($script:WindowsSecurityProxyRow) {
      try { if ([string]$script:WindowsSecurityProxyRow.Id -eq $idStr) { return $script:WindowsSecurityProxyRow } } catch {}
    }
  } catch {}
  try {
    if ($script:WindowsBackupProxyRow) {
      try { if ([string]$script:WindowsBackupProxyRow.Id -eq $idStr) { return $script:WindowsBackupProxyRow } } catch {}
    }
  } catch {}
  try {
    if ($script:SettingsProxyRow) {
      try { if ([string]$script:SettingsProxyRow.Id -eq $idStr) { return $script:SettingsProxyRow } } catch {}
    }
  } catch {}
  try {
    if ($script:OutlookProxyRow) {
      try { if ([string]$script:OutlookProxyRow.Id -eq $idStr) { return $script:OutlookProxyRow } } catch {}
    }
  } catch {}
  try {
    foreach ($px in @($script:VisualAppsFolderProxyRows)) {
      if (-not $px) { continue }
      try { if ([string]$px.Id -eq $idStr) { return $px } } catch {}
    }
  } catch {}
  try {
    foreach ($px in @(Get-PendingCreateRows)) {
      if (-not $px) { continue }
      try { if ([string]$px.Id -eq $idStr) { return $px } } catch {}
    }
  } catch {}

  foreach ($r in $script:TreeRoots) {
    $stack = New-Object System.Collections.Generic.Stack[FolderNode]
    $stack.Push($r)

    while ($stack.Count -gt 0) {
      $n = $stack.Pop()

      # 1) Folder rows (to be introduced later)
      if ($n.PSObject.Properties.Match('Folders').Count -gt 0 -and $n.Folders) {
        foreach ($f in $n.Folders) {
          if ([string]$f.Id -eq $idStr) { return $f }
        }
      }

      # 2) Existing item rows (.lnk/.url)
      foreach ($x in $n.Items) {
        if ([string]$x.Id -eq $idStr) { return $x }
      }

      foreach ($ch in $n.Children) { $stack.Push($ch) }
    }
  }

  return $null
}






# Cache so we don't call the shell 5000 times
$script:IconCache = @{}

function Get-SystemFolderIconImageSource {
  param(
    [ValidateSet('Small','Large')]
    [string]$Size = 'Small'
  )

  # Build > 1809: use mmcndmgr.dll,0 for the Name column folder icon.
  try {
    $isNewBuild = $false
    try { $isNewBuild = [bool](Get-IsWindowsBuildAbove1809Runtime) } catch { $isNewBuild = $false }
    if ($isNewBuild) {
      $mmc = Join-Path $env:WINDIR "System32\mmcndmgr.dll"
      $srcMmc = Get-ImageSourceFromIcon -IconPath $mmc -IconIndex 0 -FallbackExePath $mmc
      if ($srcMmc) { return $srcMmc }
    } else {
      # Legacy builds <= 1809: use dmdskres.dll,11.
      $dm = Join-Path $env:WINDIR "System32\dmdskres.dll"
      $srcDm = Get-ImageSourceFromIcon -IconPath $dm -IconIndex 11 -FallbackExePath $dm
      if (-not $srcDm) { $srcDm = Get-ImageSourceFromIcon -IconPath $dm -IconIndex (-11) -FallbackExePath $dm }
      if ($srcDm) { return $srcDm }
    }
  } catch {}

  # Fallback path if requested icon is unavailable.
  try {
    $img = Join-Path $env:WINDIR "System32\imageres.dll"
    $src = Get-ImageSourceFromIcon -IconPath $img -IconIndex 5 -FallbackExePath $img
    if ($src) { return $src }
  } catch {}

  # Compile once (StrictMode-safe): use a UNIQUE typename check
  if (-not ('Win32.StartMenuIcon' -as [type])) {

    $cs = @'
using System;
using System.Runtime.InteropServices;

namespace Win32 {
  public static class StartMenuIcon {

    [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Unicode)]
    public struct SHFILEINFO {
      public IntPtr hIcon;
      public int iIcon;
      public uint dwAttributes;

      [MarshalAs(UnmanagedType.ByValTStr, SizeConst=260)]
      public string szDisplayName;

      [MarshalAs(UnmanagedType.ByValTStr, SizeConst=80)]
      public string szTypeName;
    }

    public const uint SHGFI_ICON      = 0x000000100;
    public const uint SHGFI_SMALLICON = 0x000000001;
    public const uint SHGFI_LARGEICON = 0x000000000;
    public const uint SHGFI_USEFILEATTRIBUTES = 0x000000010;
    public const uint FILE_ATTRIBUTE_DIRECTORY = 0x00000010;

    [DllImport("shell32.dll", CharSet=CharSet.Unicode)]
    public static extern IntPtr SHGetFileInfo(
      string pszPath,
      uint dwFileAttributes,
      out SHFILEINFO psfi,
      uint cbFileInfo,
      uint uFlags
    );

    [DllImport("user32.dll")]
    public static extern bool DestroyIcon(IntPtr hIcon);
  }
}
'@

    try {
      Add-Type -TypeDefinition $cs -Language CSharp -ErrorAction Stop | Out-Null
    } catch {
      # If compilation fails, return null and don't murder the UI thread
      return $null
    }
  }

  # Ask for the generic folder icon (no real path required)
  $flags = [Win32.StartMenuIcon]::SHGFI_ICON -bor [Win32.StartMenuIcon]::SHGFI_USEFILEATTRIBUTES
  $flags = $flags -bor ($(if ($Size -eq 'Small') { [Win32.StartMenuIcon]::SHGFI_SMALLICON } else { [Win32.StartMenuIcon]::SHGFI_LARGEICON }))

  $info = New-Object Win32.StartMenuIcon+SHFILEINFO
  [void][Win32.StartMenuIcon]::SHGetFileInfo(
    "folder",
    [Win32.StartMenuIcon]::FILE_ATTRIBUTE_DIRECTORY,
    [ref]$info,
[uint32][Runtime.InteropServices.Marshal]::SizeOf($info),
    [uint32]$flags
  )

  if ($info.hIcon -eq [IntPtr]::Zero) { return $null }

  try {
    $src = [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon(
      $info.hIcon,
      [System.Windows.Int32Rect]::Empty,
      [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions()
    )
    $src.Freeze()
    return $src
  }
  finally {
    [void][Win32.StartMenuIcon]::DestroyIcon($info.hIcon)
  }
}



# ==============================================================================
# Folder picker
# ==============================================================================
function Get-WpfWindowHandle {
  param([System.Windows.Window]$Window)
  try {
    if ($Window) {
      return (New-Object System.Windows.Interop.WindowInteropHelper($Window)).Handle
    }
  } catch {}
  return [IntPtr]::Zero
}

function Convert-HexToDwmColorRef {
  param([Parameter(Mandatory=$true)][string]$Hex)
  try {
    $cObj = [System.Windows.Media.ColorConverter]::ConvertFromString([string]$Hex)
    $c = [System.Windows.Media.Color]$cObj
    # COLORREF is 0x00BBGGRR
    return [int](([int]$c.R) -bor (([int]$c.G) -shl 8) -bor (([int]$c.B) -shl 16))
  } catch {
    return 0
  }
}

function Set-WindowTitleBarTheme {
  param(
    [Parameter(Mandatory=$false)][System.Windows.Window]$Window = $script:window,
    [Parameter(Mandatory=$true)][ValidateSet('Light','Dark')][string]$Mode
  )
  try {
    if (-not $Window) { return }
    if (-not ("DwmTitleBarNative" -as [type])) { return }
    $hwnd = Get-WpfWindowHandle -Window $Window
    if ($hwnd -eq [IntPtr]::Zero) { return }

    $isDark = ([string]$Mode -ieq 'Dark')
    $captionHex = if ($isDark) { '#202020' } else { '#E1E1E1' }
    $textHex    = if ($isDark) { '#E1E1E1' } else { '#202020' }
    $captionColorRef = Convert-HexToDwmColorRef -Hex $captionHex
    $textColorRef    = Convert-HexToDwmColorRef -Hex $textHex
    $darkFlag = if ($isDark) { 1 } else { 0 }
    $cb = 4

    # Compatibility across Win10/Win11 builds.
    try { [void][DwmTitleBarNative]::DwmSetWindowAttribute($hwnd, 20, [ref]$darkFlag, $cb) } catch {}
    try { [void][DwmTitleBarNative]::DwmSetWindowAttribute($hwnd, 19, [ref]$darkFlag, $cb) } catch {}
    try { [void][DwmTitleBarNative]::DwmSetWindowAttribute($hwnd, 35, [ref]$captionColorRef, $cb) } catch {}
    try { [void][DwmTitleBarNative]::DwmSetWindowAttribute($hwnd, 36, [ref]$textColorRef, $cb) } catch {}
    # On Win10 21H2+ some systems render a 1px DWM border around custom windows.
    # Try to suppress it where supported (ignored on unsupported builds).
    try {
      if (Get-IsWindowsBuildAtLeast19044Runtime) {
        $borderNone = -2  # DWMWA_COLOR_NONE
        try { [void][DwmTitleBarNative]::DwmSetWindowAttribute($hwnd, 34, [ref]$borderNone, $cb) } catch {}
      }
    } catch {}
  } catch {}
}

function Apply-CustomWindowChrome {
  param(
    [Parameter(Mandatory=$false)][System.Windows.Window]$Window = $script:window
  )
  try {
    if (-not $Window) { return }
    $frameThicknessPx = 1.0
    try { if (Get-IsWindowsBuildAtLeast19044Runtime) { $frameThicknessPx = 0.0 } } catch {}
    $wc = New-Object System.Windows.Shell.WindowChrome
    $wc.CaptionHeight = 0
    $wc.CornerRadius = New-Object System.Windows.CornerRadius 0
    # Keep a thin glass frame so DWM can render a soft native shadow.
    $wc.GlassFrameThickness = New-Object System.Windows.Thickness($frameThicknessPx)
    $wc.ResizeBorderThickness = New-Object System.Windows.Thickness 5
    $wc.UseAeroCaptionButtons = $false
    [System.Windows.Shell.WindowChrome]::SetWindowChrome($Window, $wc)
  } catch {}
}

function Enable-SoftWindowShadow {
  param(
    [Parameter(Mandatory=$false)][System.Windows.Window]$Window = $script:window
  )
  try {
    if (-not $Window) { return }

    # Re-assert chrome values (safe/no-op if already set).
    try {
      $wc = [System.Windows.Shell.WindowChrome]::GetWindowChrome($Window)
      if ($wc) {
        $frameThicknessPx = 1.0
        try { if (Get-IsWindowsBuildAtLeast19044Runtime) { $frameThicknessPx = 0.0 } } catch {}
        $wc.GlassFrameThickness = New-Object System.Windows.Thickness($frameThicknessPx)
        $wc.ResizeBorderThickness = New-Object System.Windows.Thickness 5
      }
    } catch {}

    # Ask DWM to keep non-client rendering enabled (helps native soft shadow on borderless windows).
    try {
      if ("DwmTitleBarNative" -as [type]) {
        $hwnd = Get-WpfWindowHandle -Window $Window
        if ($hwnd -ne [IntPtr]::Zero) {
          $ncrpEnabled = 2  # DWMNCRP_ENABLED
          $cb = 4
          try { [void][DwmTitleBarNative]::DwmSetWindowAttribute($hwnd, 2, [ref]$ncrpEnabled, $cb) } catch {}
        }
      }
    } catch {}
  } catch {}
}

function Update-CustomTitleBarMaxGlyph {
  try {
    if (-not $script:window) { return }
    $glyph = if ($script:window.WindowState -eq [System.Windows.WindowState]::Maximized) { [string][char]0x25F1 } else { [string][char]0x2610 }
    if ($script:AppMaxGlyphText) {
      $script:AppMaxGlyphText.Text = $glyph
      return
    }
    if (-not $script:AppMaxButton) { return }
    if ($script:window.WindowState -eq [System.Windows.WindowState]::Maximized) {
      $script:AppMaxButton.Content = ([string][char]0x25F1)
    } else {
      $script:AppMaxButton.Content = ([string][char]0x2610)
    }
  } catch {}
}

function Apply-CustomTitleBarForeground {
  param(
    [Parameter(Mandatory=$false)][ValidateSet('Light','Dark')][string]$Mode = $script:UiThemeMode
  )
  try {
    $hex = if ([string]$Mode -ieq 'Dark') { '#7C7C7C' } else { '#202020' }
    $fg = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($hex))
    try { if ($script:AppTitleBarText) { $script:AppTitleBarText.Foreground = $fg } } catch {}
    try { if ($script:AppMinGlyphText) { $script:AppMinGlyphText.Foreground = $fg } } catch {}
    try { if ($script:AppMaxGlyphText) { $script:AppMaxGlyphText.Foreground = $fg } } catch {}
    try { if ($script:AppCloseGlyphText) { $script:AppCloseGlyphText.Foreground = $fg } } catch {}
    try { if ($script:AppMinButton) { $script:AppMinButton.Foreground = $fg } } catch {}
    try { if ($script:AppMaxButton) { $script:AppMaxButton.Foreground = $fg } } catch {}
    try { if ($script:AppCloseButton) { $script:AppCloseButton.Foreground = $fg } } catch {}
  } catch {}
}

function Sync-CustomTitleBarText {
  try {
    if ($script:AppTitleBarText -and $script:window) {
      $script:AppTitleBarText.Text = [string]$script:window.Title
    }
  } catch {}
}


function Select-FolderDialog {
  param(
    [string]$Title = "Select a folder",
    [string]$InitialPath = $null,
    [System.Windows.Window]$OwnerWindow = $script:window,
    [string]$SuggestedName = $null,
    [switch]$PreferModernOnly,  # if set, we will NOT show Shell BrowseForFolder unless BOTH modern methods fail
    [switch]$StrictFolderPicker # if set, skip OpenFileDialog hack and use true folder pickers only
  )


  $InitialPath = Normalize-Path $InitialPath
  $ownerHwnd   = Get-WpfWindowHandle -Window $OwnerWindow

  try {
    if ([System.Threading.Thread]::CurrentThread.ApartmentState -ne 'STA') {
    }

    if (-not ("FileDialogNative" -as [type])) {
      return $null
    }

    # -------------------------
    # Attempt 1: IFileOpenDialog (true modern Explorer picker)
    # -------------------------
    try {
      $clsid   = [Guid]::Parse([FileDialogNative]::CLSID_FileOpenDialog)
      $comType = [Type]::GetTypeFromCLSID($clsid, $true)
      $comObj  = [Activator]::CreateInstance($comType)

      # IMPORTANT: wrap the COM object as the interface (avoids your "System.__ComObject has no method GetOptions" problem)
      $fd = [Runtime.InteropServices.Marshal]::CreateWrapperOfType(
        $comObj,
        [type]([FileDialogNative+IFileOpenDialog])
      )


      $opts = [FileDialogNative+FOS]0
      $fd.GetOptions([ref]$opts) | Out-Null

      $opts = $opts -bor [FileDialogNative+FOS]::FOS_PICKFOLDERS `
                   -bor [FileDialogNative+FOS]::FOS_FORCEFILESYSTEM `
                   -bor [FileDialogNative+FOS]::FOS_NOCHANGEDIR `
                   -bor [FileDialogNative+FOS]::FOS_PATHMUSTEXIST

      $fd.SetOptions($opts)
      if ($Title) { $fd.SetTitle($Title) }

      if ($InitialPath -and (Test-Path -LiteralPath $InitialPath)) {
        try {
          $riid = [Guid]::Parse("43826D1E-E718-42EE-BC55-A1E261C37BFE") # IShellItem
          $si   = $null
          $hrInit = [FileDialogNative]::SHCreateItemFromParsingName($InitialPath, [IntPtr]::Zero, [ref]$riid, [ref]$si)
          if ($hrInit -eq 0 -and $si) { $fd.SetFolder($si) }
        } catch {
        }
      }

      $hrShow = $fd.Show($ownerHwnd)

      if ($hrShow -ne 0) { return $null }  # cancel/failure

      $res = $null
      $fd.GetResult([ref]$res)
      if (-not $res) { return $null }

      $psz = [IntPtr]::Zero
      $res.GetDisplayName([FileDialogNative+SIGDN]::SIGDN_FILESYSPATH, [ref]$psz)
      if ($psz -eq [IntPtr]::Zero) { return $null }

      $path = [Runtime.InteropServices.Marshal]::PtrToStringUni($psz)
      [Runtime.InteropServices.Marshal]::FreeCoTaskMem($psz)

      return $path
    }
    catch {
    }

    if (-not $StrictFolderPicker) {
      # -------------------------
      # Attempt 2: OpenFileDialog folder-pick hack (still modern Explorer UI)
      # -------------------------
      try {
  

        $dlg = New-Object System.Windows.Forms.OpenFileDialog
        $dlg.Title = $Title
        $dlg.Filter = "Folders|*.*"
        $dlg.CheckFileExists = $false
        $dlg.CheckPathExists = $true
        $dlg.ValidateNames = $false
        $dlg.Multiselect = $false

        $start = $InitialPath
        if (-not $start -or -not (Test-Path -LiteralPath $start)) {
          $start = [Environment]::GetFolderPath("Desktop")
        }
        $dlg.InitialDirectory = $start
        $dlg.FileName = if ([string]::IsNullOrWhiteSpace($SuggestedName)) { "[Select Folder]" } else { [string]$SuggestedName }

        $dr = $dlg.ShowDialog()
        if ($dr -ne [System.Windows.Forms.DialogResult]::OK) { return $null }

        $path = Split-Path -Path $dlg.FileName -Parent
        if ([string]::IsNullOrWhiteSpace($path)) { return $null }

        return $path
      }
      catch {
      }
    } else {
    }

    # -------------------------
    # Attempt 3: Shell.Application BrowseForFolder (legacy UI)
    # Only if allowed.
    # -------------------------
    if ($PreferModernOnly) {
      return $null
    }

    try {
      $sh = New-Object -ComObject Shell.Application
      $flags = 0x0001 -bor 0x0040 # RETURNONLYFSDIRS + NEWDIALOGSTYLE

      $folder = $sh.BrowseForFolder(0, $Title, $flags, 0)
      if ($folder -and $folder.Self -and $folder.Self.Path) {
        $path = [string]$folder.Self.Path
        return $path
      }

      return $null
    }
    catch {
      return $null
    }
  }
  finally {
  }
}




# ==============================================================================
# Shortcut identity helpers (NO duplicate definitions)
# ==============================================================================
function Get-LnkSignature {
  param([Parameter(Mandatory=$true)][string]$LnkPath)

  if (-not (Test-Path -LiteralPath $LnkPath)) { return $null }

  try {
    $ws = New-Object -ComObject WScript.Shell
    $sc = $ws.CreateShortcut($LnkPath)

    $t = $sc.TargetPath;       if ($null -eq $t) { $t = "" }
    $a = $sc.Arguments;        if ($null -eq $a) { $a = "" }
    $w = $sc.WorkingDirectory; if ($null -eq $w) { $w = "" }

    return (($t.ToString().ToLowerInvariant()) + "|" +
            ($a.ToString().ToLowerInvariant()) + "|" +
            ($w.ToString().ToLowerInvariant()))
  } catch {
    return $null
  }
}

function Get-LnkIconSignature {
  param([Parameter(Mandatory=$true)][string]$LnkPath)
  if (-not (Test-Path -LiteralPath $LnkPath)) { return '' }
  try {
    $ws = New-Object -ComObject WScript.Shell
    $sc = $ws.CreateShortcut($LnkPath)
    $ico = ''
    try { $ico = [string]$sc.IconLocation } catch { $ico = '' }
    if ([string]::IsNullOrWhiteSpace($ico)) { return '' }
    return $ico.Trim().ToLowerInvariant()
  } catch {
    return ''
  }
}

function Get-FileSha256Safe {
  param([Parameter(Mandatory=$true)][string]$Path)
  try {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return '' }
    return [string](Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash
  } catch {
    return ''
  }
}

function Test-RestoreDestinationExactMatch {
  param(
    [Parameter(Mandatory=$true)][string]$SnapshotPath,
    [Parameter(Mandatory=$true)][string]$DestinationPath
  )
  try {
    $src = Normalize-Path $SnapshotPath
    $dst = Normalize-Path $DestinationPath
    if ([string]::IsNullOrWhiteSpace($src) -or [string]::IsNullOrWhiteSpace($dst)) { return $false }
    if (-not (Test-Path -LiteralPath $src -PathType Leaf)) { return $false }
    if (-not (Test-Path -LiteralPath $dst -PathType Leaf)) { return $false }
    $ext = ''
    try { $ext = [string][IO.Path]::GetExtension($src) } catch { $ext = '' }
    $ext = $ext.ToLowerInvariant()
    if ($ext -eq '.lnk') {
      $sigSrc = Get-LnkSignature -LnkPath $src
      $sigDst = Get-LnkSignature -LnkPath $dst
      $icoSrc = Get-LnkIconSignature -LnkPath $src
      $icoDst = Get-LnkIconSignature -LnkPath $dst
      return (
        (-not [string]::IsNullOrWhiteSpace($sigSrc)) -and
        (-not [string]::IsNullOrWhiteSpace($sigDst)) -and
        ([string]$sigSrc -eq [string]$sigDst) -and
        ([string]$icoSrc -eq [string]$icoDst)
      )
    }
    $h1 = Get-FileSha256Safe -Path $src
    $h2 = Get-FileSha256Safe -Path $dst
    if ([string]::IsNullOrWhiteSpace($h1) -or [string]::IsNullOrWhiteSpace($h2)) { return $false }
    return ([string]$h1 -eq [string]$h2)
  } catch {
    return $false
  }
}

function Find-EquivalentShortcutInFolder {
  param(
    [Parameter(Mandatory)] [string] $Folder,
    [Parameter(Mandatory)] [string] $IncomingLnkPath
  )

  if (-not (Test-Path -LiteralPath $Folder)) { return $null }

  $sigIn = Get-LnkSignature -LnkPath $IncomingLnkPath
  if (-not $sigIn) { return $null }

  $match = $null
  Get-ChildItem -LiteralPath $Folder -Filter *.lnk -File -ErrorAction SilentlyContinue | ForEach-Object {
    if ($match) { return }
    $sig = Get-LnkSignature -LnkPath $_.FullName
    if ($sig -and $sig -eq $sigIn) { $match = $_.FullName }
  }

  return $match
}

# ==============================================================================
# Restore helper (REPLACE mode)
# - Faithful restore: overwrite ONLY the exact destination path from snapshot
# - Do not remove other shortcuts in the folder, even if target/args match
# ==============================================================================
function Restore-ShortcutReplace {
  param(
    [Parameter(Mandatory=$true)][string]$SnapshotLnkPath,
    [Parameter(Mandatory=$true)][string]$DestFolder
  )

  $SnapshotLnkPath = Resolve-DestinationPathLenient -Path $SnapshotLnkPath
  if ([string]::IsNullOrWhiteSpace($SnapshotLnkPath)) { $SnapshotLnkPath = Normalize-Path $SnapshotLnkPath }
  $DestFolder      = Resolve-DestinationPathLenient -Path $DestFolder
  if ([string]::IsNullOrWhiteSpace($DestFolder)) { $DestFolder = Normalize-Path $DestFolder }

  if (-not $SnapshotLnkPath -or -not (Test-Path -LiteralPath $SnapshotLnkPath)) { return $null }
  if (-not $DestFolder) { return $null }

  if (-not (Test-Path -LiteralPath $DestFolder)) {
    New-Item -ItemType Directory -Path $DestFolder -Force | Out-Null
  }

  $snapName = [IO.Path]::GetFileName($SnapshotLnkPath)
  $destPath = Resolve-DestinationPathLenient -Path (Join-Path $DestFolder $snapName) -IsFilePath
  if ([string]::IsNullOrWhiteSpace($destPath)) { $destPath = Join-Path $DestFolder $snapName }

  # If exact same file content/shortcut payload is already present at the
  # exact path, keep it (avoid unnecessary churn and accidental duplicates).
  try {
    if (Test-Path -LiteralPath $destPath -PathType Leaf) {
      if (Test-RestoreDestinationExactMatch -SnapshotPath $SnapshotLnkPath -DestinationPath $destPath) {
        return $destPath
      }
    }
  } catch {}

  # 1) Overwrite destination file (same name/path) if present
  try {
    if (Test-Path -LiteralPath $destPath) {
      Remove-Item -LiteralPath $destPath -Force -ErrorAction SilentlyContinue
    }
  } catch {}

  # 2) Copy snapshot into destination
  try {
    Copy-Item -LiteralPath $SnapshotLnkPath -Destination $destPath -Force -ErrorAction Stop
  } catch {
    return $null
  }

  # 3) Nudge shell
  Invoke-StartMenuRefresh -TouchedFolder $DestFolder

  return $destPath
}

# ==============================================================================
# Pending state helper
# ==============================================================================
function Set-PendingState {
  param(
    [Parameter(Mandatory=$true)][object]$it,
    [string]$PreviewName,
    [string[]]$BumpLabels = @()
  )


  try {
    $prevAction = ''
    $prevPending = ''
    $prevName = ''
    try { $prevAction = [string](Get-PropString -Obj $it -Names @('Action') -Fallback '') } catch {}
    try { $prevPending = [string](Get-PropString -Obj $it -Names @('PendingLabel') -Fallback '') } catch {}
    try { $prevName = [string](Get-PropString -Obj $it -Names @('Name') -Fallback '') } catch {}

    if (-not $it.PSObject.Properties.Match("Action").Count) {
      $it | Add-Member -NotePropertyName "Action" -NotePropertyValue "None" -Force
    }
    if (-not $it.PSObject.Properties.Match("PendingLabel").Count) {
      $it | Add-Member -NotePropertyName "PendingLabel" -NotePropertyValue "" -Force
    }
    if (-not $it.PSObject.Properties.Match("OriginalName").Count) {
      $it | Add-Member -NotePropertyName "OriginalName" -NotePropertyValue ([string]$it.Name) -Force
    }

    function Normalize-PendingLabelToken {
      param([string]$Label)
      $t = ''
      try { $t = [string]$Label } catch { $t = '' }
      $t = $t.Trim()
      if ([string]::Equals($t, 'Icon Changed', [System.StringComparison]::OrdinalIgnoreCase)) { return 'Icon Edit' }
      return $t
    }

    function Get-PendingLabelRowsFromText {
      param([string]$Text)
      $rows = New-Object System.Collections.Generic.List[object]
      $seen = @{}
      foreach ($raw in @(([string]$Text -split "`r?`n"))) {
        $tok = Normalize-PendingLabelToken -Label ([string]$raw)
        if ([string]::IsNullOrWhiteSpace($tok)) { continue }
        $k = $tok.ToLowerInvariant()
        if ($seen.ContainsKey($k)) { continue }
        $seen[$k] = $true
        $clr = '#fdfb70'
        if ([string]::Equals($tok, 'Moved', [System.StringComparison]::OrdinalIgnoreCase)) {
          $clr = '#57c8eb'
        } elseif ([string]::Equals($tok, 'Renamed', [System.StringComparison]::OrdinalIgnoreCase)) {
          $clr = '#4ee077'
        } elseif ([string]::Equals($tok, 'Target Edit', [System.StringComparison]::OrdinalIgnoreCase)) {
          $clr = '#80b3ff'
        } elseif ([string]::Equals($tok, 'Icon Edit', [System.StringComparison]::OrdinalIgnoreCase)) {
          $clr = '#ffbc6b'
        } elseif ([string]::Equals($tok, 'Deleted', [System.StringComparison]::OrdinalIgnoreCase)) {
          $clr = '#ff3a3a'
        }
        [void]$rows.Add([pscustomobject]@{ Text = [string]$tok; Color = [string]$clr })
      }
      return @($rows.ToArray())
    }

    function Set-PendingLabelVisual {
      param(
        [Parameter(Mandatory=$true)][object]$Row,
        [string]$Text
      )
      $txt = ''
      try { $txt = [string]$Text } catch { $txt = '' }
      $txt = $txt.Trim()
      if ($txt -match '(?i)Icon Changed') { $txt = ($txt -replace '(?im)^Icon Changed$', 'Icon Edit') }
      try { $Row.PendingLabel = $txt } catch {}
      try {
        if (-not $Row.PSObject.Properties.Match('PendingLabelRows').Count) {
          $Row | Add-Member -NotePropertyName 'PendingLabelRows' -NotePropertyValue (@()) -Force
        }
      } catch {}
      try { $Row.PendingLabelRows = @(Get-PendingLabelRowsFromText -Text $txt) } catch {}
    }

    function Update-PendingLabelStack {
      param(
        [Parameter(Mandatory=$true)][object]$Row,
        [string[]]$ActiveLabels = @(),
        [string[]]$BumpLabels = @()
      )

      if (-not $Row.PSObject.Properties.Match("PendingOrderMap").Count) {
        $Row | Add-Member -NotePropertyName "PendingOrderMap" -NotePropertyValue (@{}) -Force
      }
      if (-not $Row.PSObject.Properties.Match("PendingOrderNext").Count) {
        $Row | Add-Member -NotePropertyName "PendingOrderNext" -NotePropertyValue 1 -Force
      }

      $orderMap = @{}
      try {
        if ($Row.PendingOrderMap -is [hashtable]) {
          $orderMap = $Row.PendingOrderMap
        } else {
          $orderMap = @{}
        }
      } catch { $orderMap = @{} }

      $next = 1
      try { $next = [int]$Row.PendingOrderNext } catch { $next = 1 }
      if ($next -lt 1) { $next = 1 }

      $activeKeys = New-Object System.Collections.Generic.List[string]
      $activeCanonical = @{}
      foreach ($raw in @($ActiveLabels)) {
        $tok = Normalize-PendingLabelToken -Label ([string]$raw)
        if ([string]::IsNullOrWhiteSpace($tok)) { continue }
        $k = $tok.ToLowerInvariant()
        if ($activeCanonical.ContainsKey($k)) { continue }
        $activeCanonical[$k] = $tok
        [void]$activeKeys.Add($k)
      }

      if ($activeKeys.Count -eq 0) {
        Set-PendingLabelVisual -Row $Row -Text ''
        $Row.PendingOrderMap = @{}
        $Row.PendingOrderNext = 1
        return
      }

      foreach ($k in @($activeKeys.ToArray())) {
        if (-not $orderMap.ContainsKey($k)) {
          $orderMap[$k] = $next
          $next++
        }
      }

      $bumpCanonical = @{}
      foreach ($raw in @($BumpLabels)) {
        $tok = Normalize-PendingLabelToken -Label ([string]$raw)
        if ([string]::IsNullOrWhiteSpace($tok)) { continue }
        $k = $tok.ToLowerInvariant()
        if (-not $activeCanonical.ContainsKey($k)) { continue }
        if ($bumpCanonical.ContainsKey($k)) { continue }
        $bumpCanonical[$k] = $true
      }
      foreach ($k in @($bumpCanonical.Keys)) {
        $kk = [string]$k
        if ($orderMap.ContainsKey($kk)) {
          $orderMap[$kk] = $next
          $next++
        }
      }

      foreach ($k in @($orderMap.Keys)) {
        if (-not $activeCanonical.ContainsKey([string]$k)) {
          $orderMap.Remove([string]$k)
        }
      }

      # Newest pending action should appear at the top of the stack.
      $sortedKeys = @(@($activeKeys.ToArray()) | Sort-Object { [int]$orderMap[[string]$_] } -Descending)

      $labels = New-Object System.Collections.Generic.List[string]
      foreach ($k in @($sortedKeys)) {
        $kk = [string]$k
        if ($activeCanonical.ContainsKey($kk)) {
          [void]$labels.Add([string]$activeCanonical[$kk])
        }
      }

      Set-PendingLabelVisual -Row $Row -Text (@($labels.ToArray()) -join "`n")
      $Row.PendingOrderMap = $orderMap
      $Row.PendingOrderNext = $next
    }

    $wasDeleteAction = ([string]$it.Action -eq "Delete")

    $effectiveName = ''
    try { $effectiveName = [string]$it.Name } catch { $effectiveName = '' }
    try {
      if ($PSBoundParameters.ContainsKey('PreviewName')) {
        $effectiveName = [string]$PreviewName
      }
    } catch {}
    $nameChanged = ([string]$effectiveName -ne [string]$it.OriginalName)
    $pathChanged = $false
    try {
      $curPath = Normalize-Path ([string](Get-PropString -Obj $it -Names @('Path') -Fallback ''))
      $origPath = Normalize-Path ([string](Get-PropString -Obj $it -Names @('OriginalPath') -Fallback $curPath))
      if (-not [string]::IsNullOrWhiteSpace($curPath) -and -not [string]::IsNullOrWhiteSpace($origPath)) {
        $pathChanged = (-not (Test-PathEqualsCI -A $curPath -B $origPath))
      }
    } catch { $pathChanged = $false }

    $iconChanged = $false
    try {
      $iconPendingPath = [string](Get-PropString -Obj $it -Names @('PendingIconPath') -Fallback '')
      if (-not [string]::IsNullOrWhiteSpace($iconPendingPath)) { $iconChanged = $true }
    } catch { $iconChanged = $false }
    $targetChanged = $false
    try {
      $pendingTarget = Normalize-Path ([string](Get-PropString -Obj $it -Names @('PendingTargetPath') -Fallback ''))
      $currentTarget = Normalize-Path ([string](Get-PropString -Obj $it -Names @('Target') -Fallback ''))
      if (-not [string]::IsNullOrWhiteSpace($pendingTarget) -and -not [string]::IsNullOrWhiteSpace($currentTarget)) {
        $targetChanged = (-not (Test-PathEqualsCI -A $pendingTarget -B $currentTarget))
      }
    } catch { $targetChanged = $false }

    $activePendingLabels = New-Object System.Collections.Generic.List[string]
    if ($nameChanged -or $pathChanged) {
      if (-not $wasDeleteAction) { $it.Action = "Rename" }
      if ($pathChanged) { [void]$activePendingLabels.Add("Moved") }
      if ($nameChanged) { [void]$activePendingLabels.Add("Renamed") }
    } else {
      if (-not $wasDeleteAction) { $it.Action = "None" }
    }
    if ($iconChanged) {
      [void]$activePendingLabels.Add("Icon Edit")
    }
    if ($targetChanged) {
      [void]$activePendingLabels.Add("Target Edit")
    }
    if ($wasDeleteAction) {
      $it.Action = "Delete"
      [void]$activePendingLabels.Add("Deleted")
    }
    Update-PendingLabelStack -Row $it -ActiveLabels @($activePendingLabels.ToArray()) -BumpLabels @($BumpLabels)

    try {
      $changed = ($prevAction -ne [string]$it.Action) -or ($prevPending -ne [string]$it.PendingLabel) -or ($prevName -ne [string]$it.Name)
      if ($changed) { Touch-VisualRuntimeState -Reason "Set-PendingState" }
    } catch {}

    if ($wasDeleteAction) {
    } else {
    }
  } catch {
    throw
  }
}

function Test-RowHasPendingIconChange {
  param([object]$Row)
  if (-not $Row) { return $false }
  $p = ''
  try { $p = [string](Get-PropString -Obj $Row -Names @('PendingIconPath') -Fallback '') } catch { $p = '' }
  return (-not [string]::IsNullOrWhiteSpace($p))
}

function Test-RowHasPendingTargetChange {
  param([object]$Row)
  if (-not $Row) { return $false }
  $pending = ''
  $current = ''
  try { $pending = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('PendingTargetPath') -Fallback '')) } catch { $pending = '' }
  try { $current = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('Target') -Fallback '')) } catch { $current = '' }
  if ([string]::IsNullOrWhiteSpace($pending) -or [string]::IsNullOrWhiteSpace($current)) { return $false }
  return (-not (Test-PathEqualsCI -A $pending -B $current))
}

function Resolve-ExistingShortcutPathForRow {
  param([Parameter(Mandatory=$true)][object]$Row)

  $candidates = New-Object System.Collections.Generic.List[string]
  try {
    $p1 = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('Path') -Fallback ''))
    if (-not [string]::IsNullOrWhiteSpace($p1)) { [void]$candidates.Add($p1) }
  } catch {}
  try {
    $p2 = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('OriginalPath') -Fallback ''))
    if (-not [string]::IsNullOrWhiteSpace($p2)) { [void]$candidates.Add($p2) }
  } catch {}

  foreach ($p in @($candidates.ToArray())) {
    if ([string]::IsNullOrWhiteSpace($p)) { continue }
    if (-not $p.EndsWith('.lnk', [System.StringComparison]::OrdinalIgnoreCase)) { continue }
    try {
      if (Test-Path -LiteralPath $p -PathType Leaf) { return $p }
    } catch {}
  }
  return $null
}

function Get-ShortcutIconLocationSpecFromLink {
  param([Parameter(Mandatory=$true)][string]$LnkPath)
  if ([string]::IsNullOrWhiteSpace($LnkPath)) { return $null }
  $lnkResolved = Resolve-ExistingPathLenient -Path ([string]$LnkPath)
  if ([string]::IsNullOrWhiteSpace($lnkResolved)) { $lnkResolved = Normalize-Path ([string]$LnkPath) }
  if ([string]::IsNullOrWhiteSpace($lnkResolved)) { $lnkResolved = [string]$LnkPath }
  if (-not (Test-Path -LiteralPath $lnkResolved -PathType Leaf)) { return $null }
  # Prefer native Unicode shell-link reader first for symbol/emoji paths.
  try {
    Ensure-ShellLinkInteropTypes
    $link = New-Object StartMenuTool.ShellLink
    $pf = [StartMenuTool.IPersistFile]$link
    [void]$pf.Load([string]$lnkResolved, 0)
    $sl = [StartMenuTool.IShellLinkW]$link
    $sbIcon = New-Object System.Text.StringBuilder 32767
    $iconIdx = 0
    try { [void]$sl.GetIconLocation($sbIcon, $sbIcon.Capacity, [ref]$iconIdx) } catch {}
    $loc = ''
    try { $loc = [string]$sbIcon.ToString() } catch { $loc = '' }
    if (-not [string]::IsNullOrWhiteSpace($loc)) {
      $parsed = Parse-IconLocationString -IconLocation $loc
      if ($parsed -and -not [string]::IsNullOrWhiteSpace([string]$parsed.IconPath)) {
        $ip = Resolve-ExistingPathLenient -Path ([string]$parsed.IconPath)
        if ([string]::IsNullOrWhiteSpace($ip)) { $ip = Normalize-Path ([string]$parsed.IconPath) }
        if (-not [string]::IsNullOrWhiteSpace($ip)) {
          return [pscustomobject]@{
            IconPath     = [string]$ip
            IconIndex    = [int]$parsed.IconIndex
            IconLocation = ("{0},{1}" -f [string]$ip, [int]$parsed.IconIndex)
          }
        }
      }
    }
  } catch {}
  try {
    $ws = New-Object -ComObject WScript.Shell
    $sc = $ws.CreateShortcut($lnkResolved)
    $loc = ''
    try { $loc = [string]$sc.IconLocation } catch { $loc = '' }
    if ([string]::IsNullOrWhiteSpace($loc)) { return $null }
    $parsed = Parse-IconLocationString -IconLocation $loc
    if (-not $parsed) { return $null }
    $ip = Resolve-ExistingPathLenient -Path ([string]$parsed.IconPath)
    if ([string]::IsNullOrWhiteSpace($ip)) { $ip = Normalize-Path ([string]$parsed.IconPath) }
    if ([string]::IsNullOrWhiteSpace($ip)) { return $null }
    return [pscustomobject]@{
      IconPath     = [string]$ip
      IconIndex    = [int]$parsed.IconIndex
      IconLocation = ("{0},{1}" -f [string]$ip, [int]$parsed.IconIndex)
    }
  } catch {
    return $null
  }
}

function Show-ShortcutIconPickerDialog {
  param(
    [string]$InitialIconPath = '',
    [int]$InitialIconIndex = 0
  )

  $startPath = Normalize-Path ([string]$InitialIconPath)
  if ([string]::IsNullOrWhiteSpace($startPath) -or -not (Test-Path -LiteralPath $startPath)) {
    $startPath = Join-Path $env:WINDIR 'System32\shell32.dll'
  }
  if (-not (Test-Path -LiteralPath $startPath)) { return $null }

  try {
    $sb = New-Object System.Text.StringBuilder 1024
    [void]$sb.Append([string]$startPath)
    $idx = [int]$InitialIconIndex
    $hWnd = [IntPtr]::Zero
    try {
      if ($script:window) {
        $hWnd = (New-Object System.Windows.Interop.WindowInteropHelper($script:window)).Handle
      }
    } catch { $hWnd = [IntPtr]::Zero }

    $picked = [IconPickerNative]::PickIconDlg($hWnd, $sb, $sb.Capacity, [ref]$idx)
    if ($picked -eq 0) { return $null }

    $iconPath = Normalize-Path ([string]$sb.ToString())
    if ([string]::IsNullOrWhiteSpace($iconPath)) { return $null }
    if (-not (Test-Path -LiteralPath $iconPath)) { return $null }
    return [pscustomobject]@{
      IconPath     = [string]$iconPath
      IconIndex    = [int]$idx
      IconLocation = ("{0},{1}" -f [string]$iconPath, [int]$idx)
    }
  } catch {
    return $null
  }
}

# ==============================================================================
# Start Menu roots (per scope)
# ==============================================================================
function Get-CanonicalStartMenuScopeRoots {
  $allUsersPrograms = ''
  $currentUserPrograms = ''
  try {
    $commonStart = [string][Environment]::GetFolderPath([Environment+SpecialFolder]::CommonStartMenu)
    if (-not [string]::IsNullOrWhiteSpace($commonStart)) {
      $allUsersPrograms = Normalize-Path (Join-Path $commonStart 'Programs')
    }
  } catch {}
  if ([string]::IsNullOrWhiteSpace($allUsersPrograms)) {
    try { $allUsersPrograms = Normalize-Path (Join-Path $env:ProgramData "Microsoft\Windows\Start Menu\Programs") } catch {}
  }
  try {
    $userStart = [string][Environment]::GetFolderPath([Environment+SpecialFolder]::StartMenu)
    if (-not [string]::IsNullOrWhiteSpace($userStart)) {
      $currentUserPrograms = Normalize-Path (Join-Path $userStart 'Programs')
    }
  } catch {}
  if ([string]::IsNullOrWhiteSpace($currentUserPrograms)) {
    try { $currentUserPrograms = Normalize-Path (Join-Path $env:AppData "Microsoft\Windows\Start Menu\Programs") } catch {}
  }
  return @{
    AllUsers    = [string]$allUsersPrograms
    CurrentUser = [string]$currentUserPrograms
  }
}

function Get-PortableStartMenuRootForScope {
  param([string]$Scope)
  switch -Regex ([string]$Scope) {
    '^AllUsers$'    { return '%ProgramData%\Microsoft\Windows\Start Menu\Programs' }
    '^CurrentUser$' { return '%AppData%\Microsoft\Windows\Start Menu\Programs' }
    default         { return '' }
  }
}

function Convert-ToPortableStartMenuPath {
  param(
    [string]$Scope,
    [string]$AbsolutePath,
    [string]$RelativePath
  )
  try {
    $portableRoot = Get-PortableStartMenuRootForScope -Scope ([string]$Scope)
    $rel = [string]$RelativePath
    if (-not [string]::IsNullOrWhiteSpace($portableRoot) -and -not [string]::IsNullOrWhiteSpace($rel)) {
      $relNorm = $rel -replace '/', '\'
      return [string](Join-Path $portableRoot $relNorm)
    }
    $abs = Normalize-Path ([string]$AbsolutePath)
    if ([string]::IsNullOrWhiteSpace($abs)) { return [string]$AbsolutePath }
    if (-not [string]::IsNullOrWhiteSpace($portableRoot) -and $scopeRoots.ContainsKey([string]$Scope)) {
      $root = Normalize-Path ([string]$scopeRoots[[string]$Scope])
      if (-not [string]::IsNullOrWhiteSpace($root) -and $abs.StartsWith($root.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)) {
        $tail = $abs.Substring($root.TrimEnd('\').Length).TrimStart('\')
        return [string](Join-Path $portableRoot $tail)
      }
    }
    return [string]$abs
  } catch {
    return [string]$AbsolutePath
  }
}

function Convert-RelativePathToBackupStorage {
  param([string]$RelativePath)
  try {
    $rel = [string]$RelativePath
    if ([string]::IsNullOrWhiteSpace($rel)) { return '' }
    $normalized = $rel -replace '/', '\'
    $parts = $normalized -split '\\'
    $encoded = New-Object System.Collections.Generic.List[string]
    foreach ($p in $parts) {
      $seg = [string]$p
      if ([string]::IsNullOrWhiteSpace($seg)) { continue }
      $enc = [Uri]::EscapeDataString($seg)
      [void]$encoded.Add($enc)
    }
    return ([string]::Join('\', $encoded.ToArray()))
  } catch {
    return [string]$RelativePath
  }
}

function Convert-RelativePathFromBackupStorage {
  param([string]$RelativePath)
  try {
    $rel = [string]$RelativePath
    if ([string]::IsNullOrWhiteSpace($rel)) { return '' }
    $normalized = $rel -replace '/', '\'
    $parts = $normalized -split '\\'
    $decoded = New-Object System.Collections.Generic.List[string]
    foreach ($p in $parts) {
      $seg = [string]$p
      if ([string]::IsNullOrWhiteSpace($seg)) { continue }
      $dec = [Uri]::UnescapeDataString($seg)
      [void]$decoded.Add($dec)
    }
    return ([string]::Join('\', $decoded.ToArray()))
  } catch {
    return [string]$RelativePath
  }
}

function Convert-NameSegmentToUnicodeNotation {
  param([string]$Name)
  try {
    $s = [string]$Name
    if ([string]::IsNullOrEmpty($s)) { return '' }
    $sb = New-Object System.Text.StringBuilder
    for ($i = 0; $i -lt $s.Length; $i++) {
      $ch = [char]$s[$i]
      $cp = 0
      $piece = [string]$ch
      if ([char]::IsHighSurrogate($ch) -and ($i + 1) -lt $s.Length) {
        $ch2 = [char]$s[$i + 1]
        if ([char]::IsLowSurrogate($ch2)) {
          $cp = [char]::ConvertToUtf32($ch, $ch2)
          $piece = [string]::new(@($ch, $ch2))
          $i++
        } else {
          $cp = [int]$ch
        }
      } else {
        $cp = [int]$ch
      }
      if ($cp -ge 0x20 -and $cp -le 0x7E) {
        [void]$sb.Append($piece)
      } else {
        $fmt = if ($cp -le 0xFFFF) { 'U+{0:X4}' } else { 'U+{0:X6}' }
        [void]$sb.Append(([string]::Format($fmt, $cp)))
      }
    }
    return $sb.ToString()
  } catch {
    return [string]$Name
  }
}

function Convert-RelativePathToUnicodeNotation {
  param([string]$RelativePath)
  try {
    $rel = [string]$RelativePath
    if ([string]::IsNullOrWhiteSpace($rel)) { return '' }
    $normalized = $rel -replace '/', '\'
    $parts = $normalized -split '\\'
    $converted = New-Object System.Collections.Generic.List[string]
    foreach ($p in $parts) {
      $seg = [string]$p
      if ([string]::IsNullOrWhiteSpace($seg)) { continue }
      [void]$converted.Add((Convert-NameSegmentToUnicodeNotation -Name $seg))
    }
    return ([string]::Join('\', $converted.ToArray()))
  } catch {
    return [string]$RelativePath
  }
}

function Add-ConversionListMapping {
  param(
    [hashtable]$Seen = $null,
    [object]$OriginalList = $null,
    [object]$UnicodeList = $null,
    [object]$Mappings = $null,
    [string]$Scope,
    [string]$Type,
    [string]$OriginalRelativePath,
    [string]$UnicodeRelativePath
  )
  try {
    if ($null -eq $Seen) { return }
    if ($null -eq $OriginalList) { return }
    if ($null -eq $UnicodeList) { return }
    if ($null -eq $Mappings) { return }
    $orig = [string]$OriginalRelativePath
    $uni = [string]$UnicodeRelativePath
    if ([string]::IsNullOrWhiteSpace($orig) -or [string]::IsNullOrWhiteSpace($uni)) { return }
    $key = ("{0}|{1}|{2}" -f [string]$Scope, [string]$Type, $orig.ToLowerInvariant())
    if ($Seen.ContainsKey($key)) { return }
    $Seen[$key] = $true
    [void]$OriginalList.Add([pscustomobject]@{
      Scope        = [string]$Scope
      Type         = [string]$Type
      RelativePath = [string]$orig
    })
    [void]$UnicodeList.Add([pscustomobject]@{
      Scope        = [string]$Scope
      Type         = [string]$Type
      RelativePath = [string]$uni
    })
    if ($orig -ne $uni) {
      [void]$Mappings.Add([pscustomobject]@{
        Scope                = [string]$Scope
        Type                 = [string]$Type
        OriginalRelativePath = [string]$orig
        UnicodeRelativePath  = [string]$uni
      })
    }
  } catch {}
}

function Save-ConversionListJson {
  param(
    [Parameter(Mandatory=$true)][string]$BackupRoot,
    [object]$OriginalList = $null,
    [object]$UnicodeList = $null,
    [object]$Mappings = $null
  )
  try {
    function Convert-AnyListToArray {
      param([object]$Value)
      $out = New-Object System.Collections.Generic.List[object]
      try {
        if ($null -eq $Value) { return @() }
        if ($Value -is [System.Collections.Generic.List[object]]) {
          return @($Value.ToArray())
        }
        if ($Value -is [System.Array]) {
          foreach ($x in $Value) { [void]$out.Add($x) }
          return @($out.ToArray())
        }
        if (($Value -is [System.Collections.IEnumerable]) -and -not ($Value -is [string])) {
          foreach ($x in $Value) { [void]$out.Add($x) }
          return @($out.ToArray())
        }
        [void]$out.Add($Value)
        return @($out.ToArray())
      } catch {
        return @()
      }
    }
    $origArr = @()
    $uniArr  = @()
    $mapArr  = @()
    try { $origArr = Convert-AnyListToArray -Value $OriginalList } catch {}
    try { $uniArr  = Convert-AnyListToArray -Value $UnicodeList  } catch {}
    try { $mapArr  = Convert-AnyListToArray -Value $Mappings     } catch {}
    $path = Join-Path $BackupRoot 'Conversion List.json'
    $payload = [pscustomobject]@{
      SchemaVersion     = 1
      CreatedUtc        = (Get-Date).ToUniversalTime().ToString("o")
      'Original Naming' = $origArr
      'Unicode Naming'  = $uniArr
      Mappings          = $mapArr
    }
    Save-PlanJson -Path $path -Payload $payload
  } catch {}
}

function Invoke-RestoreRenameFromConversionList {
  param(
    [object]$ConversionList,
    [System.Collections.Generic.List[string]]$Errors
  )
  $renamed = 0
  try {
    if (-not $ConversionList) { return 0 }
    $mappings = @()
    try { $mappings = @($ConversionList.Mappings) } catch { $mappings = @() }
    if ($mappings.Count -eq 0) { return 0 }
    $fileMaps = @()
    $folderMaps = @()
    foreach ($m in @($mappings)) {
      if (-not $m) { continue }
      $tp = ''
      try { $tp = [string]$m.Type } catch { $tp = '' }
      if ($tp -eq 'Folder') { $folderMaps += $m } else { $fileMaps += $m }
    }
    # Files first: rename leaf only in current (unicode) parent.
    foreach ($m in @($fileMaps)) {
      try {
        $scope = [string]$m.Scope
        if ([string]::IsNullOrWhiteSpace($scope) -or -not $scopeRoots.ContainsKey($scope)) { continue }
        $root = Normalize-Path ([string]$scopeRoots[$scope])
        if ([string]::IsNullOrWhiteSpace($root)) { continue }
        $uniRel = [string]$m.UnicodeRelativePath
        $origRel = [string]$m.OriginalRelativePath
        if ([string]::IsNullOrWhiteSpace($uniRel) -or [string]::IsNullOrWhiteSpace($origRel)) { continue }
        $oldPath = Normalize-Path (Join-Path $root $uniRel)
        if ([string]::IsNullOrWhiteSpace($oldPath) -or -not (Test-Path -LiteralPath $oldPath -PathType Leaf)) { continue }
        $newLeaf = ''
        try { $newLeaf = [IO.Path]::GetFileName($origRel) } catch { $newLeaf = '' }
        if ([string]::IsNullOrWhiteSpace($newLeaf)) { continue }
        $parent = Split-Path -Path $oldPath -Parent
        if ([string]::IsNullOrWhiteSpace($parent)) { continue }
        $newPath = Normalize-Path (Join-Path $parent $newLeaf)
        if ([string]::IsNullOrWhiteSpace($newPath)) { continue }
        if ($oldPath.Equals($newPath, [StringComparison]::OrdinalIgnoreCase)) { continue }
        if (Test-Path -LiteralPath $newPath) { continue }
        Move-Item -LiteralPath $oldPath -Destination $newPath -Force -ErrorAction Stop
        $renamed++
      } catch {
        if ($Errors) { [void]$Errors.Add(("CONVERSION RENAME FILE :: {0}" -f $_.Exception.Message)) }
      }
    }
    # Folders deepest first: rename leaf only in current (unicode) parent.
    $orderedFolders = @()
    try {
      $orderedFolders = @($folderMaps | Sort-Object { ([string]$_.UnicodeRelativePath).Length } -Descending)
    } catch { $orderedFolders = @($folderMaps) }
    foreach ($m in @($orderedFolders)) {
      try {
        $scope = [string]$m.Scope
        if ([string]::IsNullOrWhiteSpace($scope) -or -not $scopeRoots.ContainsKey($scope)) { continue }
        $root = Normalize-Path ([string]$scopeRoots[$scope])
        if ([string]::IsNullOrWhiteSpace($root)) { continue }
        $uniRel = [string]$m.UnicodeRelativePath
        $origRel = [string]$m.OriginalRelativePath
        if ([string]::IsNullOrWhiteSpace($uniRel) -or [string]::IsNullOrWhiteSpace($origRel)) { continue }
        $oldPath = Normalize-Path (Join-Path $root $uniRel)
        if ([string]::IsNullOrWhiteSpace($oldPath) -or -not (Test-Path -LiteralPath $oldPath -PathType Container)) { continue }
        $newLeaf = ''
        try { $newLeaf = [IO.Path]::GetFileName($origRel) } catch { $newLeaf = '' }
        if ([string]::IsNullOrWhiteSpace($newLeaf)) { continue }
        $parent = Split-Path -Path $oldPath -Parent
        if ([string]::IsNullOrWhiteSpace($parent)) { continue }
        $newPath = Normalize-Path (Join-Path $parent $newLeaf)
        if ([string]::IsNullOrWhiteSpace($newPath)) { continue }
        if ($oldPath.Equals($newPath, [StringComparison]::OrdinalIgnoreCase)) { continue }
        if (Test-Path -LiteralPath $newPath -PathType Container) {
          # Target special-character folder already exists (often empty).
          # Merge content from unicode folder into it, then remove unicode folder if empty.
          try {
            $children = @()
            try { $children = @(Get-ChildItem -LiteralPath $oldPath -Force -ErrorAction SilentlyContinue) } catch { $children = @() }
            foreach ($ch in @($children)) {
              if (-not $ch) { continue }
              $srcChild = Normalize-Path ([string]$ch.FullName)
              if ([string]::IsNullOrWhiteSpace($srcChild) -or -not (Test-Path -LiteralPath $srcChild)) { continue }
              $dstChild = Normalize-Path (Join-Path $newPath ([string]$ch.Name))
              if ([string]::IsNullOrWhiteSpace($dstChild)) { continue }
              $isDir = $false
              try { $isDir = (Test-Path -LiteralPath $srcChild -PathType Container) } catch { $isDir = $false }
              if ($isDir) {
                if (-not (Test-Path -LiteralPath $dstChild -PathType Container)) {
                  Move-Item -LiteralPath $srcChild -Destination $dstChild -Force -ErrorAction Stop
                } else {
                  $grand = @()
                  try { $grand = @(Get-ChildItem -LiteralPath $srcChild -Force -ErrorAction SilentlyContinue) } catch { $grand = @() }
                  foreach ($g in @($grand)) {
                    if (-not $g) { continue }
                    $gSrc = Normalize-Path ([string]$g.FullName)
                    if ([string]::IsNullOrWhiteSpace($gSrc) -or -not (Test-Path -LiteralPath $gSrc)) { continue }
                    $gDst = Normalize-Path (Join-Path $dstChild ([string]$g.Name))
                    if ([string]::IsNullOrWhiteSpace($gDst)) { continue }
                    if (Test-Path -LiteralPath $gDst) {
                      try {
                        $gIsDir = (Test-Path -LiteralPath $gSrc -PathType Container)
                        if (-not $gIsDir) { Move-Item -LiteralPath $gSrc -Destination $gDst -Force -ErrorAction Stop }
                      } catch {}
                    } else {
                      Move-Item -LiteralPath $gSrc -Destination $gDst -Force -ErrorAction Stop
                    }
                  }
                  try {
                    $left = @(Get-ChildItem -LiteralPath $srcChild -Force -ErrorAction SilentlyContinue)
                    if ($left.Count -eq 0) { Remove-Item -LiteralPath $srcChild -Force -ErrorAction SilentlyContinue }
                  } catch {}
                }
              } else {
                Move-Item -LiteralPath $srcChild -Destination $dstChild -Force -ErrorAction Stop
              }
            }
            try {
              $leftOld = @(Get-ChildItem -LiteralPath $oldPath -Force -ErrorAction SilentlyContinue)
              if ($leftOld.Count -eq 0) {
                Remove-Item -LiteralPath $oldPath -Force -ErrorAction SilentlyContinue
                $renamed++
              }
            } catch {}
          } catch {
            if ($Errors) { [void]$Errors.Add(("CONVERSION MERGE FOLDER :: {0}" -f $_.Exception.Message)) }
          }
          continue
        }
        Move-Item -LiteralPath $oldPath -Destination $newPath -Force -ErrorAction Stop
        $renamed++
      } catch {
        if ($Errors) { [void]$Errors.Add(("CONVERSION RENAME FOLDER :: {0}" -f $_.Exception.Message)) }
      }
    }
  } catch {
    if ($Errors) { [void]$Errors.Add(("CONVERSION RENAME :: {0}" -f $_.Exception.Message)) }
  }
  return [int]$renamed
}

function Resolve-DestinationPathLenient {
  param([string]$Path, [switch]$IsFilePath)
  try {
    $p = Normalize-Path ([string]$Path)
    if ([string]::IsNullOrWhiteSpace($p)) { return $null }
    $resolvedExisting = Resolve-ExistingPathLenient -Path $p
    if (-not [string]::IsNullOrWhiteSpace($resolvedExisting)) { return $resolvedExisting }
    if ($IsFilePath) {
      $parent = ''
      $leaf = ''
      try { $parent = Split-Path -Path $p -Parent } catch { $parent = '' }
      try { $leaf = Split-Path -Path $p -Leaf } catch { $leaf = '' }
      if (-not [string]::IsNullOrWhiteSpace($parent) -and -not [string]::IsNullOrWhiteSpace($leaf)) {
        $resolvedParent = Resolve-ExistingPathLenient -Path $parent
        if (-not [string]::IsNullOrWhiteSpace($resolvedParent)) {
          return (Join-Path $resolvedParent $leaf)
        }
      }
    }
    return $p
  } catch {
    return (Normalize-Path ([string]$Path))
  }
}

function Save-BitmapSourceAsPngIco {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Media.Imaging.BitmapSource]$Bitmap,
    [Parameter(Mandatory=$true)][string]$DestinationPath
  )
  $ok = $false
  $pngMs = $null
  $fs = $null
  $bw = $null
  try {
    if (-not $Bitmap) { return $false }
    try {
      $destDir = [System.IO.Path]::GetDirectoryName([string]$DestinationPath)
      if (-not [string]::IsNullOrWhiteSpace($destDir)) { [void][System.IO.Directory]::CreateDirectory($destDir) }
    } catch {}

    $pngMs = New-Object System.IO.MemoryStream
    $enc = New-Object System.Windows.Media.Imaging.PngBitmapEncoder
    [void]$enc.Frames.Add([System.Windows.Media.Imaging.BitmapFrame]::Create($Bitmap))
    $enc.Save($pngMs)
    $pngBytes = $pngMs.ToArray()

    $w = 0; $h = 0
    try { $w = [int]$Bitmap.PixelWidth } catch { $w = 0 }
    try { $h = [int]$Bitmap.PixelHeight } catch { $h = 0 }
    if ($w -le 0 -or $h -le 0) { return $false }

    $wByte = if ($w -ge 256) { [byte]0 } else { [byte]$w }
    $hByte = if ($h -ge 256) { [byte]0 } else { [byte]$h }

    $fs = [System.IO.File]::Open($DestinationPath, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
    $bw = New-Object System.IO.BinaryWriter($fs)

    $bw.Write([UInt16]0)  # reserved
    $bw.Write([UInt16]1)  # type = icon
    $bw.Write([UInt16]1)  # count
    $bw.Write([byte]$wByte)
    $bw.Write([byte]$hByte)
    $bw.Write([byte]0)      # color count
    $bw.Write([byte]0)      # reserved
    $bw.Write([UInt16]1)    # planes
    $bw.Write([UInt16]32)   # bit count
    $bw.Write([UInt32]$pngBytes.Length)
    $bw.Write([UInt32]22)   # image offset (6 + 16)
    $bw.Write($pngBytes)
    $ok = $true
  } catch {
    $ok = $false
  } finally {
    try { if ($bw) { $bw.Close() } } catch {}
    try { if ($fs) { $fs.Close() } } catch {}
    try { if ($pngMs) { $pngMs.Close() } } catch {}
  }
  return [bool]$ok
}

function Export-ShortcutIconToIcoFile {
  param(
    [Parameter(Mandatory=$true)][string]$ShortcutPath,
    [Parameter(Mandatory=$true)][string]$DestinationIcoPath
  )
  $allHandles = New-Object 'System.Collections.Generic.List[System.IntPtr]'
  $ico = $null
  $clone = $null
  $fs = $null
  try {
    $lnk = Resolve-ExistingPathLenient -Path ([string]$ShortcutPath)
    if ([string]::IsNullOrWhiteSpace($lnk)) { $lnk = Normalize-Path ([string]$ShortcutPath) }
    $dst = Normalize-Path ([string]$DestinationIcoPath)
    if ([string]::IsNullOrWhiteSpace($lnk) -or -not (Test-Path -LiteralPath $lnk -PathType Leaf)) { return $null }
    if ([string]::IsNullOrWhiteSpace($dst)) { return $null }
    $dstDir = ''
    try { $dstDir = Split-Path -Path $dst -Parent } catch { $dstDir = '' }
    if (-not [string]::IsNullOrWhiteSpace($dstDir) -and -not (Test-Path -LiteralPath $dstDir)) {
      New-Item -ItemType Directory -Path $dstDir -Force | Out-Null
    }

    $spec = $null
    try { $spec = Get-ShortcutIconLocationSpecFromLink -LnkPath $lnk } catch { $spec = $null }
    $iconSource = ''
    $iconIndex = 0
    if ($spec) {
      try { $iconSource = Normalize-Path ([string]$spec.IconPath) } catch { $iconSource = '' }
      try { $iconIndex = [int]$spec.IconIndex } catch { $iconIndex = 0 }
    }
    if ([string]::IsNullOrWhiteSpace($iconSource) -or -not (Test-Path -LiteralPath $iconSource -PathType Leaf)) {
      $iconSource = $lnk
      $iconIndex = 0
    }
    # Collect fallback candidates in priority order.
    $fallbackCandidates = New-Object System.Collections.Generic.List[object]
    $seenCand = @{}
    function Add-Candidate {
      param([string]$Path,[int]$Index = 0)
      try {
        $p0 = Resolve-ExistingPathLenient -Path ([string]$Path)
        if ([string]::IsNullOrWhiteSpace($p0)) { $p0 = Normalize-Path ([string]$Path) }
        if ([string]::IsNullOrWhiteSpace($p0)) { return }
        $k = ($p0.ToLowerInvariant() + '|' + [string]$Index)
        if ($seenCand.ContainsKey($k)) { return }
        $seenCand[$k] = $true
        [void]$fallbackCandidates.Add([pscustomobject]@{ Path = [string]$p0; Index = [int]$Index })
      } catch {}
    }
    Add-Candidate -Path $iconSource -Index $iconIndex
    Add-Candidate -Path $lnk -Index 0
    try {
      $li = Inventory-GetLnkInfoNative -LnkPath $lnk
      if (-not $li) { $li = Inventory-GetLnkInfo -LnkPath $lnk }
      if ($li) {
        try { Add-Candidate -Path ([string]$li.IconPath) -Index ([int]$li.IconIndex) } catch {}
        try { Add-Candidate -Path ([string]$li.TargetPath) -Index 0 } catch {}
      }
    } catch {}

    $hUse = [IntPtr]::Zero
    foreach ($cand in @($fallbackCandidates.ToArray())) {
      if (-not $cand) { continue }
      $candPath = [string]$cand.Path
      $candIdx = 0
      try { $candIdx = [int]$cand.Index } catch { $candIdx = 0 }
      if ([string]::IsNullOrWhiteSpace($candPath) -or -not (Test-Path -LiteralPath $candPath)) { continue }
      foreach ($sz in @(256,128,96,64,48,32)) {
        $tmp = New-Object IntPtr[] 1
        $ids = New-Object UInt32[] 1
        $count = 0
        try {
          $count = [uint][IconBackupNative]::PrivateExtractIcons($candPath, $candIdx, $sz, $sz, $tmp, $ids, 1, 0)
        } catch { $count = 0 }
        if ($tmp[0] -ne [IntPtr]::Zero) { [void]$allHandles.Add($tmp[0]) }
        if ($count -gt 0 -and $tmp[0] -ne [IntPtr]::Zero) {
          $hUse = $tmp[0]
          break
        }
      }
      if ($hUse -ne [IntPtr]::Zero) { break }
    }

    if ($hUse -eq [IntPtr]::Zero) {
      foreach ($cand in @($fallbackCandidates.ToArray())) {
        if (-not $cand) { continue }
        $candPath = [string]$cand.Path
        $candIdx = 0
        try { $candIdx = [int]$cand.Index } catch { $candIdx = 0 }
        if ([string]::IsNullOrWhiteSpace($candPath) -or -not (Test-Path -LiteralPath $candPath)) { continue }
        $lArr = New-Object IntPtr[] 1
        $sArr = New-Object IntPtr[] 1
        $count = 0
        try { $count = [int][IconBackupNative]::ExtractIconEx([string]$candPath, [int]$candIdx, $lArr, $sArr, 1) } catch { $count = 0 }
        if ($count -le 0 -and $candIdx -gt 0) {
          try { $count = [int][IconBackupNative]::ExtractIconEx([string]$candPath, (-1 * [int]$candIdx), $lArr, $sArr, 1) } catch { $count = 0 }
        }
        try { if ($lArr[0] -ne [IntPtr]::Zero) { [void]$allHandles.Add($lArr[0]) } } catch {}
        try { if ($sArr[0] -ne [IntPtr]::Zero) { [void]$allHandles.Add($sArr[0]) } } catch {}
        if ($lArr[0] -ne [IntPtr]::Zero) { $hUse = $lArr[0] } elseif ($sArr[0] -ne [IntPtr]::Zero) { $hUse = $sArr[0] }
        if ($hUse -ne [IntPtr]::Zero) { break }
      }
    }

    if ($hUse -eq [IntPtr]::Zero) {
      # Last-chance fallback: render whatever UI icon source resolves and write ICO.
      foreach ($cand in @($fallbackCandidates.ToArray())) {
        if (-not $cand) { continue }
        $candPath = [string]$cand.Path
        $candIdx = 0
        try { $candIdx = [int]$cand.Index } catch { $candIdx = 0 }
        if ([string]::IsNullOrWhiteSpace($candPath)) { continue }
        $img = $null
        try { $img = Get-ImageSourceFromIcon -IconPath $candPath -IconIndex $candIdx -FallbackExePath $candPath } catch { $img = $null }
        if (-not $img -and (Test-Path -LiteralPath $candPath)) {
          try { $img = Get-ImageSourceFromAssociatedIconPath -Path $candPath } catch { $img = $null }
        }
        if ($img) {
          $bmp = $img -as [System.Windows.Media.Imaging.BitmapSource]
          if ($bmp) {
            try { if ($bmp) { $bmp.Freeze() } } catch {}
            $okFinal = [bool](Save-BitmapSourceAsPngIco -Bitmap $bmp -DestinationPath $dst)
            if ($okFinal -and (Test-Path -LiteralPath $dst -PathType Leaf)) { return $dst }
          }
        }
      }
      return $null
    }

    $ok = $false
    $bmp = $null
    try {
      $bmp = [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon(
        $hUse,
        [System.Windows.Int32Rect]::Empty,
        [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions()
      )
      try { if ($bmp) { $bmp.Freeze() } } catch {}
    } catch { $bmp = $null }
    if ($bmp) {
      $ok = [bool](Save-BitmapSourceAsPngIco -Bitmap $bmp -DestinationPath $dst)
    }

    if (-not $ok) {
      $ico = [System.Drawing.Icon]::FromHandle($hUse)
      if (-not $ico) { return $null }
      $clone = [System.Drawing.Icon]$ico.Clone()
      $fs = [System.IO.File]::Open([string]$dst, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
      $clone.Save($fs)
      $ok = $true
    }

    if ($ok -and (Test-Path -LiteralPath $dst -PathType Leaf)) { return $dst }
  } catch {}
  finally {
    try { if ($fs) { $fs.Close() } } catch {}
    try { if ($clone) { $clone.Dispose() } } catch {}
    try { if ($ico) { $ico.Dispose() } } catch {}
    $destroyed = @{}
    foreach ($h in @($allHandles.ToArray())) {
      try {
        if ($h -eq [IntPtr]::Zero) { continue }
        $k = $h.ToInt64()
        if ($destroyed.ContainsKey($k)) { continue }
        [void][IconBackupNative]::DestroyIcon($h)
        $destroyed[$k] = $true
      } catch {}
    }
  }
  return $null
}

