try {
  $cvBuildObj = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop
  $cvBuildStr = ''
  try { if ($cvBuildObj.PSObject.Properties.Match('CurrentBuild').Count -gt 0) { $cvBuildStr = [string]$cvBuildObj.CurrentBuild } } catch {}
  if ([string]::IsNullOrWhiteSpace($cvBuildStr)) {
    try { if ($cvBuildObj.PSObject.Properties.Match('CurrentBuildNumber').Count -gt 0) { $cvBuildStr = [string]$cvBuildObj.CurrentBuildNumber } } catch {}
  }
  $cvBuild = 0
  if ([int]::TryParse($cvBuildStr, [ref]$cvBuild)) {
    try { $script:IsWindowsBuildAbove1809 = ($cvBuild -gt 17763) } catch {}
    if ($cvBuild -gt 17763) { $script:EnableNameIconAccentBoxes = $false }
  }
} catch {}

