function Ensure-GridSmoothScrollTimer {
  try {
    if ($script:GridSmoothTimer -and ($script:GridSmoothTimer -is [System.Windows.Threading.DispatcherTimer])) {
      return
    }

    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(10)
    $timer.Add_Tick({
      try {
        $sv = $null
        try { $sv = $script:GridSmoothScrollViewer } catch { $sv = $null }
        if (-not $sv) { try { $script:GridSmoothTimer.Stop() } catch {}; return }

        $extent = 0.0; $viewport = 0.0; $current = 0.0; $target = 0.0
        try { $extent = [double]$sv.ExtentHeight } catch { $extent = 0.0 }
        try { $viewport = [double]$sv.ViewportHeight } catch { $viewport = 0.0 }
        try { $current = [double]$sv.VerticalOffset } catch { $current = 0.0 }
        try { $target = [double]$script:GridSmoothTargetOffset } catch { $target = $current }

        $maxOffset = [Math]::Max(0.0, ($extent - $viewport))
        if ($target -lt 0.0) { $target = 0.0 }
        if ($target -gt $maxOffset) { $target = $maxOffset }
        $script:GridSmoothTargetOffset = $target

        $delta = ($target - $current)
        $absDelta = [Math]::Abs($delta)
        $snapEps = 0.35
        try { $snapEps = [double]$script:GridSmoothSnapEpsilonPx } catch { $snapEps = 0.35 }
        if ($snapEps -lt 0.05) { $snapEps = 0.05 }
        if ($absDelta -le $snapEps) {
          $sv.ScrollToVerticalOffset($target)
          try { $script:GridSmoothTimer.Stop() } catch {}
          try { Queue-MidGridScrollBarSync -LayoutUpdate:$false } catch {}
          return
        }

        $ease = 0.35
        try { $ease = [double]$script:GridSmoothEaseFactor } catch { $ease = 0.35 }
        if ($ease -lt 0.05) { $ease = 0.05 }
        if ($ease -gt 0.95) { $ease = 0.95 }
        $step = $delta * $ease

        $minStep = 0.25
        try { $minStep = [double]$script:GridSmoothMinStepPx } catch { $minStep = 0.25 }
        if ($minStep -lt 0.1) { $minStep = 0.1 }
        if ($absDelta -le $minStep) {
          $step = $delta
        } elseif ([Math]::Abs($step) -lt $minStep) {
          $step = [Math]::Sign($delta) * $minStep
        }

        $next = $current + $step
        if (($delta -gt 0.0 -and $next -gt $target) -or ($delta -lt 0.0 -and $next -lt $target)) {
          $next = $target
        }
        if ($next -lt 0.0) { $next = 0.0 }
        if ($next -gt $maxOffset) { $next = $maxOffset }
        $sv.ScrollToVerticalOffset($next)
      } catch {
        try { $script:GridSmoothTimer.Stop() } catch {}
      }
    })

    $script:GridSmoothTimer = $timer
  } catch {}
}

function Queue-GridSmoothWheelScroll {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Controls.ScrollViewer]$ScrollViewer,
    [Parameter(Mandatory=$true)][double]$WheelDelta
  )

  try {
    if (-not $ScrollViewer) { return }
    Ensure-GridSmoothScrollTimer

    $cur = 0.0
    try { $cur = [double]$ScrollViewer.VerticalOffset } catch { $cur = 0.0 }
    $tgt = 0.0
    try { $tgt = [double]$script:GridSmoothTargetOffset } catch { $tgt = $cur }
    if (-not ($script:GridSmoothTimer -and $script:GridSmoothTimer.IsEnabled)) { $tgt = $cur }

    $notch = 140.0
    try { $notch = [double]$script:GridSmoothWheelNotchPx } catch { $notch = 140.0 }
    if ($notch -lt 20.0) { $notch = 20.0 }

    $tgt = $tgt - (($WheelDelta / 120.0) * $notch)

    $extent = 0.0; $viewport = 0.0
    try { $extent = [double]$ScrollViewer.ExtentHeight } catch { $extent = 0.0 }
    try { $viewport = [double]$ScrollViewer.ViewportHeight } catch { $viewport = 0.0 }
    $maxOffset = [Math]::Max(0.0, ($extent - $viewport))
    if ($tgt -lt 0.0) { $tgt = 0.0 }
    if ($tgt -gt $maxOffset) { $tgt = $maxOffset }

    $script:GridSmoothScrollViewer = $ScrollViewer
    $script:GridSmoothTargetOffset = $tgt
    $script:GridSmoothLastWheelAt = Get-Date
    try { $script:GridSmoothTimer.Start() } catch {}
  } catch {}
}

function Suspend-GridSmoothScrollForDrag {
  param([bool]$Suspend)
  try {
    $script:GridSmoothSuspendByDrag = [bool]$Suspend
    if ($Suspend) {
      try { if ($script:GridSmoothTimer) { $script:GridSmoothTimer.Stop() } } catch {}
      try {
        $sv = $null
        try { $sv = $script:GridSmoothScrollViewer } catch { $sv = $null }
        if ($sv) { $script:GridSmoothTargetOffset = [double]$sv.VerticalOffset }
      } catch {}
    }
  } catch {}
}

function Touch-VisualRuntimeState {
  param([string]$Reason = '')
  try { $script:VisualRuntimeStateVersion = [int]$script:VisualRuntimeStateVersion + 1 } catch { $script:VisualRuntimeStateVersion = 1 }
  try { $script:VisualImmediateMergeCache = @{} } catch {}
  try {
    if (-not [string]::IsNullOrWhiteSpace($Reason)) {
    }
  } catch {}
}

function Clear-VisualProxyCaches {
  try { $script:VisualAppsFolderProxyRows = @() } catch {}
  try { $script:WindowsSecurityProxyRow = $null } catch {}
  try { $script:VisualProxyDiscoveryCache = $null } catch {}
  try { $script:WinSecShellAppPresentCacheAt = [datetime]::MinValue; $script:WinSecShellAppPresentCache = $false } catch {}
  try { $script:StartAppsCacheAt = [datetime]::MinValue; $script:StartAppsCache = @() } catch {}
  try { $script:AppsFolderInfoCacheAt = [datetime]::MinValue; $script:AppsFolderInfoCache = @{} } catch {}
  try { $script:AppxPkgCacheAt = [datetime]::MinValue; $script:AppxPkgByFamilyCache = @{} } catch {}
  try { $script:AppxLogoRelCache = @{} } catch {}
  try { $script:AppxLogoAbsCache = @{} } catch {}
  try { $script:WinSecEditableShortcutCacheAt = [datetime]::MinValue; $script:WinSecEditableShortcutCache = $false } catch {}
  try { $script:VisualImmediateMergeCache = @{} } catch {}
  try { Touch-VisualRuntimeState -Reason 'Clear-VisualProxyCaches' } catch {}
}

function Invalidate-LaunchDuplicateCaches {
  try { $script:DuplicateTargetPathSet = @{} } catch {}
  try { $script:DuplicateTargetPathSetReady = $false } catch {}
  try { $script:LaunchDuplicateReadErrorItems = @() } catch {}
  try { $script:DuplicateTargetExpandPendingRebuild = $false } catch {}
}

function Get-StartAppsCached {
  param([int]$MaxAgeSeconds = 30)
  try {
    $now = Get-Date
    if ($script:StartAppsCacheAt -and (($now - $script:StartAppsCacheAt).TotalSeconds -lt $MaxAgeSeconds)) {
      return @($script:StartAppsCache)
    }

    $apps = @()
    if (Get-Command Get-StartApps -ErrorAction SilentlyContinue) {
      $apps = @(Get-StartApps)
    }

    $script:StartAppsCacheAt = $now
    $script:StartAppsCache   = $apps
    return @($apps)
  } catch {
    return @()
  }
}

function Get-AppxInstallLocationByFamilyCached {
  param([int]$MaxAgeSeconds = 120)
  try {
    $now = Get-Date
    if ($script:AppxPkgCacheAt -and (($now - $script:AppxPkgCacheAt).TotalSeconds -lt $MaxAgeSeconds) -and $script:AppxPkgByFamilyCache.Count -gt 0) {
      return $script:AppxPkgByFamilyCache
    }

    $map = @{}
    try {
      # Current user only; -AllUsers often requires elevation and is slower.
      $pkgs = @(Get-AppxPackage -ErrorAction SilentlyContinue)
      foreach ($p in $pkgs) {
        if (-not $p) { continue }
        $fam = $null
        $loc = $null
        try { $fam = [string]$p.PackageFamilyName } catch {}
        try { $loc = [string]$p.InstallLocation } catch {}
        if ([string]::IsNullOrWhiteSpace($fam) -or [string]::IsNullOrWhiteSpace($loc)) { continue }
        if (-not $map.ContainsKey($fam)) { $map[$fam] = $loc }
      }
    } catch {}

    $script:AppxPkgByFamilyCache = $map
    $script:AppxPkgCacheAt = $now
    return $map
  } catch {
    return @{}
  }
}

function Get-AppxLogoRelPathFromManifest {
  param(
    [Parameter(Mandatory=$true)][string]$InstallLocation,
    [Parameter(Mandatory=$true)][string]$AppId
  )

  $k = ($InstallLocation.ToLowerInvariant().TrimEnd('\\') + '|' + $AppId.ToLowerInvariant())
  if ($script:AppxLogoRelCache.ContainsKey($k)) { return $script:AppxLogoRelCache[$k] }

  $rel = $null
  try {
    $mPath = Join-Path $InstallLocation 'AppxManifest.xml'
    if (-not (Test-Path -LiteralPath $mPath)) { $script:AppxLogoRelCache[$k] = $null; return $null }

    [xml]$xml = Get-Content -LiteralPath $mPath -ErrorAction Stop
    $apps = $null
    try { $apps = @($xml.Package.Applications.Application) } catch { $apps = @() }

    foreach ($a in $apps) {
      if (-not $a) { continue }
      $id = $null
      try { $id = [string]$a.Id } catch {}
      if ([string]::IsNullOrWhiteSpace($id) -or ($id -ne $AppId)) { continue }

      $ve = $null
      foreach ($ch in @($a.ChildNodes)) {
        if ($ch -and $ch.LocalName -eq 'VisualElements') { $ve = $ch; break }
      }
      if (-not $ve) { break }

      foreach ($attrName in @('Square44x44Logo','SmallLogo','Logo','Square30x30Logo')) {
        try {
          $v = $ve.GetAttribute($attrName)
          if (-not [string]::IsNullOrWhiteSpace($v)) { $rel = [string]$v; break }
        } catch {}
      }
      break
    }
  } catch {}

  $script:AppxLogoRelCache[$k] = $rel
  return $rel
}

function Resolve-AppxLogoAbsolutePath {
  param(
    [Parameter(Mandatory=$true)][string]$InstallLocation,
    [Parameter(Mandatory=$true)][string]$RelativeLogoPath
  )

  $k = ($InstallLocation.ToLowerInvariant().TrimEnd('\\') + '|' + $RelativeLogoPath.ToLowerInvariant())
  if ($script:AppxLogoAbsCache.ContainsKey($k)) { return $script:AppxLogoAbsCache[$k] }

  $abs = $null
  try {
    $abs0 = Join-Path $InstallLocation $RelativeLogoPath
    if (Test-Path -LiteralPath $abs0) { $abs = $abs0 }
    else {
      $dir  = Split-Path -Path $abs0 -Parent
      $stem = [IO.Path]::GetFileNameWithoutExtension($abs0)
      $ext  = [IO.Path]::GetExtension($abs0)
      if (Test-Path -LiteralPath $dir) {
        $cand = @(Get-ChildItem -LiteralPath $dir -File -Force -ErrorAction SilentlyContinue | Where-Object {
          $_.Extension -ieq $ext -and $_.BaseName -like ($stem + '*')
        })

        if ($cand.Count -gt 0) {
          # Prefer highest scale variant if present.
          $best = $null
          $bestScale = -1
          foreach ($c in $cand) {
            $s = -1
            if ($c.Name -match 'scale-(\\d+)') { [void][int]::TryParse($matches[1], [ref]$s) }
            if ($s -gt $bestScale) { $bestScale = $s; $best = $c }
          }
          if (-not $best) { $best = $cand | Select-Object -First 1 }
          if ($best) { $abs = $best.FullName }
        }
      }
    }
  } catch {}

  $script:AppxLogoAbsCache[$k] = $abs
  return $abs
}

function Get-ImageSourceFromPngFile {
  param([Parameter(Mandatory=$true)][string]$Path)
  try {
    $p = Normalize-Path $Path
    if ([string]::IsNullOrWhiteSpace($p) -or -not (Test-Path -LiteralPath $p)) { return $null }
    $bmp = New-Object System.Windows.Media.Imaging.BitmapImage
    $bmp.BeginInit()
    $bmp.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
    $bmp.UriSource = New-Object System.Uri($p)
    $bmp.EndInit()
    $bmp.Freeze()
    return $bmp
  } catch {
    return $null
  }
}

function Get-AppsFolderIconImageSource {
  param([Parameter(Mandatory=$true)][string]$AppId)

  # Cache by AppId for session.
  $ck = ('appsfolder-icon|' + $AppId.ToLowerInvariant())
  if ($script:IconCache.ContainsKey($ck)) { return $script:IconCache[$ck] }

  $img = $null
  try {
    # If it's an AppX AUMID, pull logo from the app package manifest/assets.
    if ($AppId -like '*!*') {
      $parts = $AppId.Split('!',2)
      $fam   = [string]$parts[0]
      $app   = [string]$parts[1]
      $map = Get-AppxInstallLocationByFamilyCached -MaxAgeSeconds 120
      if ($map -and $map.ContainsKey($fam)) {
        $loc = [string]$map[$fam]
        if (-not [string]::IsNullOrWhiteSpace($loc) -and (Test-Path -LiteralPath $loc)) {
          $rel = Get-AppxLogoRelPathFromManifest -InstallLocation $loc -AppId $app
          if (-not [string]::IsNullOrWhiteSpace($rel)) {
            $abs = Resolve-AppxLogoAbsolutePath -InstallLocation $loc -RelativeLogoPath $rel
            if ($abs) {
              $img = Get-ImageSourceFromPngFile -Path $abs
            }
          }
        }
      }
    }
  } catch {}

  $script:IconCache[$ck] = $img
  return $img
}

function Parse-IconLocationString {
  param([string]$IconLocation)

  $s = [string]$IconLocation
  if ([string]::IsNullOrWhiteSpace($s)) { return $null }
  $s = $s.Trim()

  # Common forms:
  # - "@{C:\\Windows\\System32\\imageres.dll,-1024}"
  # - "@%SystemRoot%\\System32\\imageres.dll,-1024"
  # - "C:\\Path\\app.exe,0"
  if ($s.StartsWith('@{') -and $s.EndsWith('}')) { $s = $s.Substring(2, $s.Length - 3) }
  if ($s.StartsWith('@')) { $s = $s.Substring(1) }

  $s = Normalize-Path $s
  if ([string]::IsNullOrWhiteSpace($s)) { return $null }

  $path = $s
  $idx  = 0
  $lastComma = $s.LastIndexOf(',')
  if ($lastComma -gt 0 -and $lastComma -lt ($s.Length - 1)) {
    $tail = $s.Substring($lastComma + 1).Trim()
    $tmpIdx = 0
    if ([int]::TryParse($tail, [ref]$tmpIdx)) {
      $path = $s.Substring(0, $lastComma).Trim()
      $idx = $tmpIdx
    }
  }

  $path = Normalize-Path $path
  if ([string]::IsNullOrWhiteSpace($path)) { return $null }

  return [pscustomobject]@{ IconPath = $path; IconIndex = $idx }
}

function Get-AppsFolderInfoMapCached {
  param(
    [Parameter(Mandatory=$true)][string[]]$AppIds,
    [int]$MaxAgeSeconds = 120
  )

  $out = @{}
  try {
    $now = Get-Date
    $useCache = ($script:AppsFolderInfoCacheAt -and (($now - $script:AppsFolderInfoCacheAt).TotalSeconds -lt $MaxAgeSeconds))

    foreach ($id in $AppIds) {
      if ([string]::IsNullOrWhiteSpace($id)) { continue }
      if ($useCache -and $script:AppsFolderInfoCache.ContainsKey($id)) {
        $out[$id] = $script:AppsFolderInfoCache[$id]
      }
    }

    $missing = @()
    foreach ($id in $AppIds) {
      if ([string]::IsNullOrWhiteSpace($id)) { continue }
      if (-not $out.ContainsKey($id)) { $missing += $id }
    }

    if ($missing.Count -eq 0 -and $useCache) { return $out }

    $want = @{}
    foreach ($id in $missing) { $want[$id.ToLowerInvariant()] = $id }

    $sh = New-Object -ComObject Shell.Application
    $ns = $sh.NameSpace('shell:AppsFolder')
    if (-not $ns) { return $out }

    foreach ($it in @($ns.Items())) {
      if (-not $it) { continue }
      $aid = $null
      try { $aid = [string]$it.ExtendedProperty('System.AppUserModel.ID') } catch {}
      if ([string]::IsNullOrWhiteSpace($aid)) { continue }

      $k = $aid.ToLowerInvariant()
      if (-not $want.ContainsKey($k)) { continue }

      $name = ''
      try { $name = [string]$it.Name } catch {}

      $iconRes = ''
      try { $iconRes = [string]$it.ExtendedProperty('System.AppUserModel.RelaunchIconResource') } catch {}

      $info = [pscustomobject]@{
        Name         = $name
        IconResource = $iconRes
      }

      $script:AppsFolderInfoCache[$aid] = $info
      $out[$aid] = $info

      $null = $want.Remove($k)
      if ($want.Count -eq 0) { break }
    }

    $script:AppsFolderInfoCacheAt = $now
  } catch {}

  return $out
}

function New-AppsFolderProxyRow {
  param(
    [Parameter(Mandatory=$true)][string]$AppId,
    [string]$FallbackName,
    $Info = $null
  )

  $info = $Info

  $name = $FallbackName
  if ($info -and -not [string]::IsNullOrWhiteSpace([string]$info.Name)) { $name = [string]$info.Name }
  if ([string]::IsNullOrWhiteSpace($name)) { $name = [string]$AppId }

  $img = Get-AppsFolderIconImageSource -AppId $AppId
  $iconStrategy = 'AppxLogo'

  # Next: ask Shell for the icon for the parsing name. This works for many "ShellApp" entries
  # (This PC, Control Panel, Run, File Explorer, etc) where RelaunchIconResource is a resource ID.
  if (-not $img) {
    try {
      $pn = ('shell:AppsFolder\' + $AppId)
      $img = Get-ImageSourceFromShellParsingName -ParsingName $pn
      if ($img) { $iconStrategy = 'ShellParsingName' }
    } catch {}
  }

  # Secondary fallback: try the AppsFolder-provided RelaunchIconResource if it points at a real file resource.
  if (-not $img) {
    try {
      $parsed = Parse-IconLocationString -IconLocation ([string]($info.IconResource))
      if ($parsed -and (Test-Path -LiteralPath $parsed.IconPath)) {
        $img = Get-ImageSourceFromIcon -IconPath $parsed.IconPath -IconIndex ([int]$parsed.IconIndex) -FallbackExePath $parsed.IconPath
        if ($img) { $iconStrategy = 'RelaunchIconResource' }
      }
    } catch {}
  }

  # Final fallback: generic application icon (never blank)
  if (-not $img) {
    try {
      $img = Get-GenericAppIconImageSource
      if ($img) { $iconStrategy = 'GenericApp' }
    } catch {}
  }

  if (-not $img) {
    # Absolute last resort: try shell32 index 2 (should exist on all Windows installs).
    try {
      $shell32 = Join-Path $env:WINDIR 'System32\shell32.dll'
      $img = Get-ImageSourceFromIcon -IconPath $shell32 -IconIndex 2 -FallbackExePath $shell32
      if ($img) { $iconStrategy = 'Shell32Fallback' }
    } catch {}
  }


  return [pscustomobject]@{
    Id           = [guid]::NewGuid().ToString()
    Selected     = $false
    Action       = 'None'
    PendingLabel = ''

    OriginalName = $name
    Name         = $name
    Type         = 'ShellApp'
    Scope        = 'AppsFolder'
    Target       = (Join-Path $env:WINDIR 'explorer.exe')
    Path         = ('shell:AppsFolder\' + $AppId)
    OriginalPath = ('shell:AppsFolder\' + $AppId)
    Icon         = $img
    RowKind      = 'Item'

    IsAppsFolderProxy = $true
    AppsFolderId      = $AppId
    EditBlockedReason = 'AppsFolder entry. Rename is not supported in this tool. Delete (if supported) is handled as a special Apply step.'
  }
}

function Apply-AppsFolderProxyDeletes {
  param(
    [Parameter(Mandatory=$true)][object[]]$Rows,
    [string]$BackupRoot = $null
  )

  # IMPORTANT:
  # - These rows are NOT filesystem .lnk entries.
  # - "Delete" here means: create an editable replacement shortcut (with a trailing backtick in the filename)
  #   and apply an FSLogix hide rule so the original entry disappears from Start Menu.
  # - We do NOT uninstall packages.

  $created = New-Object System.Collections.Generic.List[string]
  $hidden  = New-Object System.Collections.Generic.List[object]
  $skipped = New-Object System.Collections.Generic.List[string]
  $errors  = New-Object System.Collections.Generic.List[string]

  $dstRoot = [string]$scopeRoots['CurrentUser']
  if ([string]::IsNullOrWhiteSpace($dstRoot)) { $dstRoot = (Join-Path $env:AppData 'Microsoft\Windows\Start Menu\Programs') }

  $rulesAdded = 0
  $startedAgent = $false

  

  foreach ($r in $Rows) {
    if (-not $r) { continue }

    $aid = ''
    $nm  = ''
    try { $aid = [string]$r.AppsFolderId } catch {}
    try { $nm  = [string]$r.Name } catch {}

    if ([string]::IsNullOrWhiteSpace($aid)) {
      [void]$errors.Add("AppsFolder delete: missing AppsFolderId.")
      continue
    }
    if ([string]::IsNullOrWhiteSpace($nm)) { $nm = $aid }

    # 1) Create editable replacement shortcut for user to customize
    try {
      $lnk = Write-AppsFolderReplacementShortcut -DestRoot $dstRoot -DisplayName $nm -AppId $aid -BackupRoot $BackupRoot
      if ($lnk) { [void]$created.Add([string]$lnk) }
    } catch {
      [void]$errors.Add(("AppsFolder replacement link failed for '" + $nm + "': " + [string]$_.Exception.Message))
    }

    # 2) Apply FSLogix hide rule
    try {
      if (-not $startedAgent) {
        $null = Invoke-FSLogixFrx -Args @('start-agent')
        $startedAgent = $true
      }

      $didHide = $false

      # Best-case: there is an actual Start Menu .lnk representing this AppsFolder item.
      # Hide THAT file (safe; does not break the app itself).
      $fileName = ((Trim-NameInputPreserveNbsp -Text $nm) + '.lnk')
      if (-not (Test-ValidFileName -Name $fileName)) { $fileName = $null }

      $candPaths = New-Object System.Collections.Generic.List[string]
      foreach ($scope in @('AllUsers','CurrentUser')) {
        $root = [string]$scopeRoots[$scope]
        if ([string]::IsNullOrWhiteSpace($root) -or -not (Test-Path -LiteralPath $root)) { continue }

        if ($fileName) {
          $direct = Join-Path $root $fileName
          if (Test-Path -LiteralPath $direct) { [void]$candPaths.Add([string]$direct) }
        }

        if ($fileName) {
          try {
            foreach ($x in @(Get-ChildItem -LiteralPath $root -Recurse -File -Filter $fileName -ErrorAction SilentlyContinue | Select-Object -First 30)) {
              if ($x -and $x.FullName) { [void]$candPaths.Add([string]$x.FullName) }
            }
          } catch {}
        }
      }

      $uniq = @{}
      $candList = New-Object System.Collections.Generic.List[string]
      foreach ($p in $candPaths) {
        if ([string]::IsNullOrWhiteSpace($p)) { continue }
        $k = $p.ToLowerInvariant()
        if ($uniq.ContainsKey($k)) { continue }
        $uniq[$k] = $true
        [void]$candList.Add($p)
      }

      foreach ($p in $candList) {
        $spec = _GetShortcutSpec -LnkPath $p
        if (-not $spec) { continue }
        $args = [string]$spec.Arguments
        if ($args -and ($args -like ('*shell:AppsFolder*' + $aid + '*'))) {
          $parent = Split-Path -Path $p -Parent
          $leaf   = Split-Path -Path $p -Leaf
          $res = Invoke-FSLogixFrx -Args @('add-rule','-hide','-src-parent',[string]$parent,'-src',[string]$leaf)
          if ($res.ExitCode -ne 0) { throw ("FSLogix add-rule failed (file): " + $res.Output) }
          [void]$hidden.Add([pscustomobject]@{ Kind='File'; Path=$p })
          $rulesAdded++
          $didHide = $true
          break
        }
      }

      # Fallback: hide the AppX registration keys (may disable the app).
      if (-not $didHide) {
        if ($aid -like '*!*') {
          $h = Add-FSLogixHideForAppId -AppId $aid -SkipAgentStart -SkipReload
          foreach ($x in @($h.Added)) { if ($x) { [void]$hidden.Add([pscustomobject]@{ Kind='Registry'; Parent=$x.SrcParent; Src=$x.Src }) } }
          $rulesAdded += @($h.Added).Count
          $didHide = $true
        } else {
          [void]$skipped.Add(("No supported FSLogix hide mapping for non-AppX AppsFolderId: " + $aid))
        }
      }

      if (-not $didHide) {
        [void]$skipped.Add(("FSLogix hide skipped: " + $nm + " (" + $aid + ")"))
      }
    } catch {
      [void]$errors.Add(("FSLogix hide failed for '" + $nm + "': " + [string]$_.Exception.Message))
    }
  }

  if ($startedAgent -and $rulesAdded -gt 0) {
    try { $null = Invoke-FSLogixFrx -Args @('reload-rules') } catch {}
  }

   # Bust caches so next rebuild reflects masking.
  try { $script:StartAppsCacheAt = [datetime]::MinValue; $script:StartAppsCache = @() } catch {}
  try { $script:AppsFolderInfoCacheAt = [datetime]::MinValue; $script:AppsFolderInfoCache = @{} } catch {}
  try { $script:AppxPkgCacheAt = [datetime]::MinValue; $script:AppxPkgByFamilyCache = @{} } catch {}

  return [pscustomobject]@{
    Created = $created.ToArray()
    Hidden  = $hidden.ToArray()
    Skipped = $skipped.ToArray()
    Errors  = $errors.ToArray()
  }
}

function Apply-AppsFolderProxyActions {
  param(
    [Parameter(Mandatory=$true)][object[]]$Rows,
    [string]$BackupRoot = $null
  )

  # Supported:
  # - Rename: create editable shortcut with the new name (no backtick) + hide original AppsFolder entry.
  # - Delete: hide original AppsFolder entry (no replacement shortcut).
  #
  # This is the generalized ShellApp logic requested by user (Windows Backup handled separately).

  $created = New-Object System.Collections.Generic.List[string]
  $hidden  = New-Object System.Collections.Generic.List[object]
  $skipped = New-Object System.Collections.Generic.List[string]
  $errors  = New-Object System.Collections.Generic.List[string]

  $dstRoot = [string]$scopeRoots['CurrentUser']
  if ([string]::IsNullOrWhiteSpace($dstRoot)) { $dstRoot = (Join-Path $env:AppData 'Microsoft\Windows\Start Menu\Programs') }

  $rulesAdded = 0
  $startedAgent = $false

  function _GetShortcutSpec {
    param([Parameter(Mandatory=$true)][string]$LnkPath)
    try {
      if (-not (Test-Path -LiteralPath $LnkPath)) { return $null }
      $ws = New-Object -ComObject WScript.Shell
      $sc = $ws.CreateShortcut($LnkPath)
      return [pscustomobject]@{
        TargetPath   = [string]$sc.TargetPath
        Arguments    = [string]$sc.Arguments
        IconLocation = [string]$sc.IconLocation
      }
    } catch { return $null }
  }

  foreach ($r in @($Rows)) {
    if (-not $r) { continue }

    $act = ''
    $aid = ''
    $newName = ''
    $oldName = ''
    try { $act = [string]$r.Action } catch {}
    try { $aid = [string]$r.AppsFolderId } catch {}
    try { $newName = [string](Get-PropString -Obj $r -Names @('Name') -Fallback '') } catch {}
    try { $oldName = [string](Get-PropString -Obj $r -Names @('OriginalName','Name') -Fallback '') } catch {}

    if ($act -ne 'Rename' -and $act -ne 'Delete') { continue }
    if ([string]::IsNullOrWhiteSpace($aid)) { [void]$errors.Add("AppsFolder action: missing AppsFolderId."); continue }

    # 1) If rename: create editable shortcut with requested name (no backtick).
    if ($act -eq 'Rename') {
      try {
        $lnk = Write-AppsFolderEditableShortcut -DestRoot $dstRoot -LinkName $newName -AppId $aid -BackupRoot $BackupRoot
        if ($lnk) { [void]$created.Add([string]$lnk) }
      } catch {
        [void]$errors.Add(("AppsFolder rename shortcut failed for '" + $newName + "': " + [string]$_.Exception.Message))
      }
    }

    # 2) Hide the original AppsFolder entry (best-effort).
    try {
      if (-not $startedAgent) {
        $null = Invoke-FSLogixFrx -Args @('start-agent')
        $startedAgent = $true
      }

      $didHide = $false
      $baseForFile = $oldName
      if ([string]::IsNullOrWhiteSpace($baseForFile)) { $baseForFile = $newName }
      if ([string]::IsNullOrWhiteSpace($baseForFile)) { $baseForFile = $aid }

      $fileName = ((Trim-NameInputPreserveNbsp -Text $baseForFile) + '.lnk')
      if (-not (Test-ValidFileName -Name $fileName)) { $fileName = $null }

      $candPaths = New-Object System.Collections.Generic.List[string]
      foreach ($scope in @('AllUsers','CurrentUser')) {
        $root = [string]$scopeRoots[$scope]
        if ([string]::IsNullOrWhiteSpace($root) -or -not (Test-Path -LiteralPath $root)) { continue }

        if ($fileName) {
          $direct = Join-Path $root $fileName
          if (Test-Path -LiteralPath $direct) { [void]$candPaths.Add([string]$direct) }
        }

        if ($fileName) {
          try {
            foreach ($x in @(Get-ChildItem -LiteralPath $root -Recurse -File -Filter $fileName -ErrorAction SilentlyContinue | Select-Object -First 30)) {
              if ($x -and $x.FullName) { [void]$candPaths.Add([string]$x.FullName) }
            }
          } catch {}
        }
      }

      $uniq = @{}
      $candList = New-Object System.Collections.Generic.List[string]
      foreach ($p in $candPaths) {
        if ([string]::IsNullOrWhiteSpace($p)) { continue }
        $k = $p.ToLowerInvariant()
        if ($uniq.ContainsKey($k)) { continue }
        $uniq[$k] = $true
        [void]$candList.Add($p)
      }

      foreach ($p in $candList) {
        $spec = _GetShortcutSpec -LnkPath $p
        if (-not $spec) { continue }
        $args = [string]$spec.Arguments
        if ($args -and ($args -like ('*shell:AppsFolder*' + $aid + '*'))) {
          $parent = Split-Path -Path $p -Parent
          $leaf   = Split-Path -Path $p -Leaf
          $res = Invoke-FSLogixFrx -Args @('add-rule','-hide','-src-parent',[string]$parent,'-src',[string]$leaf)
          if ($res.ExitCode -ne 0) { throw ("FSLogix add-rule failed (file): " + $res.Output) }
          [void]$hidden.Add([pscustomobject]@{ Kind='File'; Path=$p })
          $rulesAdded++
          $didHide = $true
          break
        }
      }

      if (-not $didHide) {
        if ($aid -like '*!*') {
          $h = Add-FSLogixHideForAppId -AppId $aid -SkipAgentStart -SkipReload
          foreach ($x in @($h.Added)) { if ($x) { [void]$hidden.Add([pscustomobject]@{ Kind='Registry'; Parent=$x.SrcParent; Src=$x.Src }) } }
          $rulesAdded += @($h.Added).Count
          $didHide = $true
        } else {
          [void]$skipped.Add(("No supported FSLogix hide mapping for non-AppX AppsFolderId: " + $aid))
        }
      }

      if (-not $didHide) {
        [void]$skipped.Add(("FSLogix hide skipped: " + $baseForFile + " (" + $aid + ")"))
      }
    } catch {
      [void]$errors.Add(("FSLogix hide failed for '" + $oldName + "': " + [string]$_.Exception.Message))
    }
  }

  if ($startedAgent -and $rulesAdded -gt 0) {
    try { $null = Invoke-FSLogixFrx -Args @('reload-rules') } catch {}
  }

  if ($BackupRoot -and (Test-Path -LiteralPath $BackupRoot)) {
    try {
      $pp = Join-Path $BackupRoot 'AppsFolderProxyActions.json'
      [pscustomobject]@{
        When        = (Get-Date).ToString('s')
        Created     = $created.ToArray()
        Hidden      = $hidden.ToArray()
        Skipped     = $skipped.ToArray()
        Errors      = $errors.ToArray()
      } | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $pp -Encoding UTF8
    } catch {}
  }

  try { $script:StartAppsCacheAt = [datetime]::MinValue; $script:StartAppsCache = @() } catch {}
  try { $script:AppsFolderInfoCacheAt = [datetime]::MinValue; $script:AppsFolderInfoCache = @{} } catch {}
  try { $script:AppxPkgCacheAt = [datetime]::MinValue; $script:AppxPkgByFamilyCache = @{} } catch {}

  return [pscustomobject]@{
    Created = $created.ToArray()
    Hidden  = $hidden.ToArray()
    Skipped = $skipped.ToArray()
    Errors  = $errors.ToArray()
  }
}

function Test-IsWindowsBackupAppsFolderRow {
  param([object]$Row)
  try {
    if (-not $Row) { return $false }
    $isProxy = $false
    try { $isProxy = ($Row.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderProxy) } catch {}
    if (-not $isProxy) { try { $isProxy = ($Row.PSObject.Properties.Match('IsAppsFolderDisplayProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderDisplayProxy) } catch {} }
    if (-not $isProxy) { try { $isProxy = ($Row.PSObject.Properties.Match('IsWindowsBackupProxy').Count -gt 0 -and [bool]$Row.IsWindowsBackupProxy) } catch {} }

    $plannedPkg = ''
    try {
      if ($Row.PSObject.Properties.Match('WindowsBackupPlannedPackageName').Count -gt 0) {
        $plannedPkg = [string]$Row.WindowsBackupPlannedPackageName
      }
    } catch { $plannedPkg = '' }
    if (-not [string]::IsNullOrWhiteSpace($plannedPkg)) { return $true }

    $nm  = ''
    $aid = ''
    $args = ''
    $pp = ''
    try { $nm = [string](Get-PropString -Obj $Row -Names @('Name','OriginalName') -Fallback '') } catch {}
    try { $aid = [string](Get-PropString -Obj $Row -Names @('AppsFolderId') -Fallback '') } catch {}
    try { $args = [string](Get-PropString -Obj $Row -Names @('Arguments') -Fallback '') } catch {}
    try { $pp = [string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback '') } catch {}

    $nk = Normalize-VisualKey $nm
    if ($isProxy -and $nk -eq 'windows backup') { return $true }
    if ($nk -eq 'windows backup') { return $true }
    if (-not [string]::IsNullOrWhiteSpace($aid) -and ($aid.ToLowerInvariant() -match 'windowsbackup')) { return $true }
    if (-not [string]::IsNullOrWhiteSpace($args) -and ($args.ToLowerInvariant() -match 'windowsbackup')) { return $true }
    if (-not [string]::IsNullOrWhiteSpace($pp) -and ($pp.ToLowerInvariant() -match 'windowsbackup')) { return $true }
  } catch {}
  return $false
}

function Show-ContinueCancelDialog {
  param(
    [Parameter(Mandatory=$true)][string]$Title,
    [Parameter(Mandatory=$true)][string]$Message,
    [string]$ContinueText = 'Continue',
    [string]$CancelText = 'Cancel'
  )

  try {
    $x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="$Title" SizeToContent="WidthAndHeight" WindowStartupLocation="CenterOwner"
        ResizeMode="NoResize" ShowInTaskbar="False" Topmost="True">
  <Grid Margin="14">
    <Grid.RowDefinitions>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>
    <TextBox Name="Msg" Grid.Row="0" TextWrapping="Wrap" IsReadOnly="True" BorderThickness="0"
             Background="Transparent" FontSize="13" Width="300" />
    <StackPanel Grid.Row="1" Orientation="Horizontal" HorizontalAlignment="Center" Margin="0,12,0,0">
      <Button Name="CancelBtn" MinWidth="60" Margin="0,0,8,0"/>
      <Button Name="OkBtn" MinWidth="60" IsDefault="True"/>
    </StackPanel>
  </Grid>
</Window>
"@
    $reader = New-Object System.Xml.XmlNodeReader ([xml]$x)
    $w = [Windows.Markup.XamlReader]::Load($reader)
    try { if ($script:window) { $w.Owner = $script:window } } catch {}
    $w.FindName('Msg').Text = $Message
    $w.FindName('OkBtn').Content = $ContinueText
    $w.FindName('CancelBtn').Content = $CancelText
    $result = $false
    $w.FindName('OkBtn').Add_Click({ $script:__dlg_res = $true; $w.Close() })
    $w.FindName('CancelBtn').Add_Click({ $script:__dlg_res = $false; $w.Close() })
    $script:__dlg_res = $false
    $null = $w.ShowDialog()
    return [bool]$script:__dlg_res
  } catch {
    # Fallback to MessageBox (button labels not exact).
    $r = [System.Windows.MessageBox]::Show($Message, $Title, [System.Windows.MessageBoxButton]::OKCancel, [System.Windows.MessageBoxImage]::Warning)
    return ($r -eq [System.Windows.MessageBoxResult]::OK)
  }
}

function Open-IconAllocatorTool {
  try {
    $baseDir = ''
    try { $baseDir = Split-Path -Parent $PSCommandPath } catch { $baseDir = '' }
    if ([string]::IsNullOrWhiteSpace($baseDir)) {
      try { $baseDir = Split-Path -Parent $MyInvocation.MyCommand.Path } catch { $baseDir = '' }
    }
    if ([string]::IsNullOrWhiteSpace($baseDir)) { $baseDir = (Get-Location).Path }

    $launcherPath = ''
    try { $launcherPath = Join-Path $baseDir 'Launch IA.cmd' } catch { $launcherPath = '' }
    if ([string]::IsNullOrWhiteSpace($launcherPath) -or -not (Test-Path -LiteralPath $launcherPath -PathType Leaf)) {
      [System.Windows.MessageBox]::Show(
        "Icon Allocator launcher is not present in the directory. Launch canceled.",
        "Open Icon Allocator",
        [System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]::Warning
      ) | Out-Null
      return
    }

    [void](Start-Process -FilePath 'cmd.exe' -WorkingDirectory $baseDir -ArgumentList @('/c', ('"{0}"' -f $launcherPath)) -WindowStyle Hidden -PassThru -ErrorAction Stop)
  } catch {
    [System.Windows.MessageBox]::Show(
      ("Unable to open Icon Allocator.`n`n" + [string]$_.Exception.Message),
      "Open Icon Allocator",
      [System.Windows.MessageBoxButton]::OK,
      [System.Windows.MessageBoxImage]::Error
    ) | Out-Null
  }
}
function Show-AppMessageBox {
  param(
    [Parameter(Mandatory=$true)][string]$Message,
    [Parameter(Mandatory=$true)][string]$Title,
    [System.Windows.MessageBoxButton]$Button = [System.Windows.MessageBoxButton]::OK,
    [System.Windows.MessageBoxImage]$Icon = [System.Windows.MessageBoxImage]::Information
  )
  try {
    $owner = $null
    try {
      if ($script:window -and ($script:window -is [System.Windows.Window]) -and $script:window.IsLoaded) { $owner = $script:window }
    } catch {}
    if ($owner) {
      return [System.Windows.MessageBox]::Show($owner, [string]$Message, [string]$Title, $Button, $Icon)
    }
  } catch {}
  return [System.Windows.MessageBox]::Show([string]$Message, [string]$Title, $Button, $Icon)
}

function Set-SystemIconOperationStatus {
  param(
    [Parameter(Mandatory=$true)][string]$Text,
    [switch]$IsError
  )
  try {
    if (-not $createSystemIconSummaryText) { return }
    $msg = [string]$Text
    if ([string]::IsNullOrWhiteSpace($msg)) { return }
    $createSystemIconSummaryText.Text = (" " + $msg.Trim())
    if ($IsError) {
      try { $createSystemIconSummaryText.Foreground = (Resolve-WpfBrush -Value '#c93535') } catch {}
    } else {
      try { $createSystemIconSummaryText.Foreground = (Resolve-WpfBrush -Value $script:UiPanelTextBrush) } catch {}
    }
  } catch {}
}

function Show-UploadIconCategoriesDialog {
  try {
    $dlg = New-Object Microsoft.Win32.OpenFileDialog
    $dlg.Title = 'Upload Categories'
    $dlg.Filter = 'JSON files (*.json)|*.json|All files (*.*)|*.*'
    $defaultPath = Get-SystemIconCategoryMapDefaultPath
    try {
      $dir = Split-Path -Parent $defaultPath
      if (-not [string]::IsNullOrWhiteSpace($dir) -and (Test-Path -LiteralPath $dir -PathType Container)) { $dlg.InitialDirectory = $dir }
    } catch {}
    if (-not ($dlg.ShowDialog())) { return }
    $picked = Normalize-Path ([string]$dlg.FileName)
    if ([string]::IsNullOrWhiteSpace($picked)) { return }
    $res = Import-SystemIconCategoryAssociationsFromFile -Path $picked -Silent
    if (-not $res.Ok) {
      Set-SystemIconOperationStatus -Text ("Upload Categories failed: " + [string]$res.Error) -IsError
      return
    }
    Set-SystemIconOperationStatus -Text ("Uploaded categories. Assignments: {0}; Categories: {1}" -f [int]$res.AssignmentCount, [int]$res.CategoryCount)
  } catch {
    Set-SystemIconOperationStatus -Text ("Upload Categories exception: " + [string]$_.Exception.Message) -IsError
  }
}

function Show-DeleteIconCategoriesDialog {
  try {
    $toDelete = @()
    $selSet = @{}
    try { $selSet = Get-SystemIconSelectedCategorySet } catch { $selSet = @{} }
    foreach ($k in @($selSet.Keys)) {
      $n = Normalize-SystemIconCategoryName -Name ([string]$k)
      if ([string]::IsNullOrWhiteSpace($n)) { continue }
      $toDelete += $n
    }
    $toDelete = @($toDelete | Sort-Object -Unique)
    if (@($toDelete).Count -eq 0) {
      Set-SystemIconOperationStatus -Text "Delete Icon Category: select one or more categories first."
      try {
        Show-AppMessageBox -Message "Select one or more categories first using the 'Categories' selector in System Icons." -Title "Delete Icon Category" -Button ([System.Windows.MessageBoxButton]::OK) -Icon ([System.Windows.MessageBoxImage]::Information) | Out-Null
      } catch {}
      return
    }
    $res = Remove-SystemIconCategories -Names @($toDelete)
    Set-SystemIconOperationStatus -Text ("Deleted categories: {0}; Updated icon assignments: {1}" -f [int]$res.RemovedCategories, [int]$res.UpdatedAssignments)
  } catch {
    Set-SystemIconOperationStatus -Text ("Delete Icon Category exception: " + [string]$_.Exception.Message) -IsError
  }
}

function Get-InstalledUserExperiencePackages {
  try {
    $cmd = Get-Command -Name Get-WindowsPackage -ErrorAction SilentlyContinue
    if ($cmd) {
      $pkgs = @(Get-WindowsPackage -Online -ErrorAction Stop | ForEach-Object {
        if (-not $_ -or -not $_.PackageName) { return }
        $state = ''
        try {
          if ($_.PSObject.Properties.Match('PackageState').Count -gt 0) { $state = [string]$_.PackageState }
          elseif ($_.PSObject.Properties.Match('State').Count -gt 0) { $state = [string]$_.State }
        } catch { $state = '' }
        if ([string]::IsNullOrWhiteSpace($state)) { return }
        if ($state -ne 'Installed' -and $state -ne 'Superseded') { return }
        if (-not ([string]$_.PackageName -match 'UserExperience')) { return }
        $rt = ''
        try { if ($_.PSObject.Properties.Match('ReleaseType').Count -gt 0) { $rt = [string]$_.ReleaseType } } catch { $rt = '' }
        $it = $null
        try { if ($_.PSObject.Properties.Match('InstallTime').Count -gt 0) { $it = $_.InstallTime } } catch { $it = $null }
        $itRaw = ''
        try { if ($it) { $itRaw = ([datetime]$it).ToString('g') } } catch { $itRaw = [string]$it }
        [pscustomobject]@{
          PackageName    = [string]$_.PackageName
          State          = $state
          ReleaseType    = $rt
          InstallTime    = $it
          InstallTimeRaw = $itRaw
        }
      } | Where-Object { $_ })
      $installed = @($pkgs | Where-Object { $_ -and ([string]$_.State -eq 'Installed') } | Sort-Object { $_.InstallTime } -Descending)
      if ($installed.Count -gt 0) { return @($installed) }
      $superseded = @($pkgs | Where-Object { $_ -and ([string]$_.State -eq 'Superseded') } | Sort-Object { $_.InstallTime } -Descending)
      return @($superseded)
    }
  } catch {}
  # Fallback: DISM text parse (best-effort).
  try {
    $out = & dism.exe /online /Get-Packages 2>$null
    if (-not $out) { return @() }
    $cur = $null
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($ln in @($out)) {
      if ($ln -match '^\s*Package Identity\s*:\s*(.+)\s*$') {
        if ($cur -and $cur.PackageName -and ($cur.PackageName -match 'UserExperience') -and ($cur.State -eq 'Installed' -or $cur.State -eq 'Superseded')) {
          [void]$list.Add($cur)
        }
        $cur = [pscustomobject]@{
          PackageName    = ($matches[1].Trim())
          State          = ''
          ReleaseType    = ''
          InstallTime    = $null
          InstallTimeRaw = ''
        }
        continue
      }
      if ($cur -and $ln -match '^\s*State\s*:\s*(.+)\s*$') {
        try { $cur.State = [string]($matches[1].Trim()) } catch {}
        continue
      }
      if ($cur -and $ln -match '^\s*Release Type\s*:\s*(.+)\s*$') {
        try { $cur.ReleaseType = [string]($matches[1].Trim()) } catch {}
        continue
      }
      if ($cur -and $ln -match '^\s*Install Time\s*:\s*(.+)\s*$') {
        $dt = $null
        $raw = $matches[1].Trim()
        try { $dt = [datetime]::Parse($raw) } catch { $dt = $null }
        $cur.InstallTime = $dt
        try { $cur.InstallTimeRaw = [string]$raw } catch {}
        continue
      }
    }
    if ($cur -and $cur.PackageName -and ($cur.PackageName -match 'UserExperience') -and ($cur.State -eq 'Installed' -or $cur.State -eq 'Superseded')) {
      [void]$list.Add($cur)
    }
    $arr = @($list.ToArray())
    $installed = @($arr | Where-Object { $_ -and ([string]$_.State -eq 'Installed') } | Sort-Object { $_.InstallTime } -Descending)
    if ($installed.Count -gt 0) { return @($installed) }
    $superseded = @($arr | Where-Object { $_ -and ([string]$_.State -eq 'Superseded') } | Sort-Object { $_.InstallTime } -Descending)
    return @($superseded)
  } catch {}
  return @()
}

function Get-WindowsBackupRemovalPackageCandidates {
  try {
    $base = @(Get-InstalledUserExperiencePackages)
    if ($base -and $base.Count -gt 0) { return @($base) }
  } catch {}

  # Fallback: broaden candidate search for builds where package names do not
  # include "UserExperience" but still host Windows Backup dependencies.
  try {
    $cmd = Get-Command -Name Get-WindowsPackage -ErrorAction SilentlyContinue
    if ($cmd) {
      $rows = @(Get-WindowsPackage -Online -ErrorAction Stop | ForEach-Object {
        if (-not $_ -or -not $_.PackageName) { return }
        $state = ''
        try {
          if ($_.PSObject.Properties.Match('PackageState').Count -gt 0) { $state = [string]$_.PackageState }
          elseif ($_.PSObject.Properties.Match('State').Count -gt 0) { $state = [string]$_.State }
        } catch { $state = '' }
        if ($state -ne 'Installed' -and $state -ne 'Superseded') { return }
        $pn = ''
        try { $pn = [string]$_.PackageName } catch { $pn = '' }
        if ([string]::IsNullOrWhiteSpace($pn)) { return }
        $pnL = $pn.ToLowerInvariant()
        if (-not ($pnL -match 'userexperience|client\.cbs|windowsbackup|microsoft-windows-client')) { return }
        $it = $null
        try { if ($_.PSObject.Properties.Match('InstallTime').Count -gt 0) { $it = $_.InstallTime } } catch { $it = $null }
        $itRaw = ''
        try { if ($it) { $itRaw = ([datetime]$it).ToString('g') } } catch { $itRaw = [string]$it }
        [pscustomobject]@{
          PackageName    = $pn
          State          = $state
          ReleaseType    = ''
          InstallTime    = $it
          InstallTimeRaw = $itRaw
        }
      } | Where-Object { $_ })
      if ($rows -and $rows.Count -gt 0) {
        return @($rows | Sort-Object { $_.InstallTime } -Descending)
      }
    }
  } catch {}

  return @()
}

function Test-UserExperiencePackageInstalled {
  param([string]$PackageName)
  try {
    $pn = ''
    try { $pn = [string]$PackageName } catch { $pn = '' }
    if ([string]::IsNullOrWhiteSpace($pn)) { return $false }
    $pn = $pn.Trim()
    foreach ($p in @(Get-InstalledUserExperiencePackages)) {
      if (-not $p) { continue }
      $n = ''
      try { $n = [string]$p.PackageName } catch { $n = '' }
      if ([string]::IsNullOrWhiteSpace($n)) { continue }
      if ([string]::Equals($n.Trim(), $pn, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    }
  } catch {}
  return $false
}

function Remove-UserExperiencePackageStrict {
  param([Parameter(Mandatory=$true)][string]$PackageName)
  $pkg = ''
  try { $pkg = [string]$PackageName } catch { $pkg = '' }
  if ([string]::IsNullOrWhiteSpace($pkg)) {
    return [pscustomobject]@{ Ok = $false; Method = ''; ExitCode = -1; Error = 'Empty package identity.' }
  }
  $pkg = $pkg.Trim()

  $installedBefore = $false
  try { $installedBefore = [bool](Test-UserExperiencePackageInstalled -PackageName $pkg) } catch { $installedBefore = $false }
  if (-not $installedBefore) {
    return [pscustomobject]@{ Ok = $false; Method = ''; ExitCode = -1; Error = ('Package is not currently installed: ' + $pkg) }
  }

  $method = ''
  $exitCode = 0
  $errText = ''
  try {
    $rm = Get-Command -Name Remove-WindowsPackage -ErrorAction SilentlyContinue
    if ($rm) {
      $method = 'Remove-WindowsPackage'
      try {
        Remove-WindowsPackage -Online -PackageName $pkg -NoRestart -ErrorAction Stop | Out-Null
      } catch {
        Remove-WindowsPackage -Online -PackageName $pkg -ErrorAction Stop | Out-Null
      }
    } else {
      $method = 'DISM'
      $out = @(& dism.exe /online /Remove-Package /PackageName:$pkg /NoRestart 2>&1)
      $exitCode = 0
      try { $exitCode = [int]$LASTEXITCODE } catch { $exitCode = 1 }
      if ($exitCode -ne 0) {
        $msg = ($out -join "`n")
        if ([string]::IsNullOrWhiteSpace($msg)) { $msg = ('DISM failed with exit code ' + [string]$exitCode) }
        throw $msg
      }
    }
  } catch {
    try { $errText = [string]$_.Exception.Message } catch { $errText = 'Unknown uninstall error.' }
    return [pscustomobject]@{ Ok = $false; Method = $method; ExitCode = $exitCode; Error = $errText }
  }

  try { Start-Sleep -Milliseconds 500 } catch {}
  $stillInstalled = $false
  try { $stillInstalled = [bool](Test-UserExperiencePackageInstalled -PackageName $pkg) } catch { $stillInstalled = $true }
  if ($stillInstalled) {
    return [pscustomobject]@{ Ok = $false; Method = $method; ExitCode = $exitCode; Error = ('Package still shows as installed after uninstall attempt: ' + $pkg) }
  }

  return [pscustomobject]@{ Ok = $true; Method = $method; ExitCode = $exitCode; Error = '' }
}

function Select-InstalledPackageDialog {
  param(
    [Parameter(Mandatory=$true)][object[]]$Packages,
    [string]$Title = 'Select Package'
  )
  if (-not $Packages -or $Packages.Count -eq 0) { return $null }
  # Build view model with a Selected bool.
  $vm = New-Object System.Collections.Generic.List[object]
  foreach ($p in @($Packages)) {
    if (-not $p) { continue }
    $name = ''
    $time = $null
    $state = ''
    try { $name = [string]$p.PackageName } catch {}
    try { $time = $p.InstallTime } catch {}
    try { if ($p.PSObject.Properties.Match('State').Count -gt 0) { $state = [string]$p.State } } catch {}
    if ([string]::IsNullOrWhiteSpace($name)) { continue }
    $timeText = ''
    try {
      if ($time) { $timeText = ([datetime]$time).ToString('g') }
      elseif ($p.PSObject.Properties.Match('InstallTimeRaw').Count -gt 0) { $timeText = [string]$p.InstallTimeRaw }
    } catch {}
    [void]$vm.Add([pscustomobject]@{ Selected=$false; PackageName=$name; State=$state; InstallTime=$timeText })
  }
  if ($vm.Count -eq 0) { return $null }
  $x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="$Title" Width="860" Height="520" WindowStartupLocation="CenterOwner"
        ResizeMode="CanResize" ShowInTaskbar="False" Topmost="True">
  <Grid Margin="10">
    <Grid.RowDefinitions>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="*"/>
      <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>

    <TextBlock Grid.Row="0" TextWrapping="Wrap" FontSize="13" Margin="0,0,0,8">
Select one Windows UserExperience package to uninstall.
    </TextBlock>

    <DataGrid Name="Grid" Grid.Row="1" AutoGenerateColumns="False" CanUserAddRows="False"
              SelectionMode="Single" HeadersVisibility="Column" IsReadOnly="False">
      <DataGrid.Columns>
        <DataGridCheckBoxColumn Header="Select" Binding="{Binding Selected, Mode=TwoWay, UpdateSourceTrigger=PropertyChanged}" Width="75"/>
        <DataGridTextColumn Header="Package Name" Binding="{Binding PackageName}" Width="*"/>
        <DataGridTextColumn Header="State" Binding="{Binding State}" Width="120"/>
        <DataGridTextColumn Header="Install Time" Binding="{Binding InstallTime}" Width="185"/>
      </DataGrid.Columns>
    </DataGrid>

    <StackPanel Grid.Row="2" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,10,0,0">
      <Button Name="CancelBtn" MinWidth="90" Margin="0,0,8,0">Cancel</Button>
      <Button Name="OkBtn" MinWidth="110" IsDefault="True">Continue</Button>
    </StackPanel>
  </Grid>
</Window>
"@
  $reader = New-Object System.Xml.XmlNodeReader ([xml]$x)
  $w = [Windows.Markup.XamlReader]::Load($reader)
  try { if ($script:window) { $w.Owner = $script:window } } catch {}
  $dg = $w.FindName('Grid')
  $dg.ItemsSource = $vm
  # Enforce single checkbox selection.
  $dg.Add_CurrentCellChanged({
    try {
      $sel = $dg.SelectedItem
      if (-not $sel) { return }
      if (-not $sel.Selected) { return }
      foreach ($row in @($dg.ItemsSource)) {
        if ($row -ne $sel -and $row.Selected) { $row.Selected = $false }
      }
    } catch {}
  })
  $script:__pkg_sel = $null
  $w.FindName('OkBtn').Add_Click({
    try {
      $picks = @()
      foreach ($row in @($dg.ItemsSource)) { if ($row -and $row.Selected) { $picks += $row } }
      if ($picks.Count -ne 1) {
        [System.Windows.MessageBox]::Show("Select exactly one package.", "Select Package") | Out-Null
        return
      }
      $script:__pkg_sel = [string]$picks[0].PackageName
      $w.Close()
    } catch { $w.Close() }
  })
  $w.FindName('CancelBtn').Add_Click({ $script:__pkg_sel = $null; $w.Close() })
  $null = $w.ShowDialog()
  return $script:__pkg_sel
}

function Invoke-WindowsBackupRemovalViaPackageUninstall {
  param([string]$BackupRoot = $null)
  $warn = @(
    "To remove Windows Backup shortcut from the Start Menu a certain Windows UserExperience Package must be uninstalled."
    ""
    "As a consequence, the following features will also be lost from this 2023 update:"
    "ScreenClippingHost.exe - Snipping Tool capture UI (Win+Shift+S and screen clipping host)."
    "TextInputHost.exe - Touch keyboard, emoji panel, and IME text input interface."
    "WindowsBackupClient.exe - Windows Backup app client and backup workflow UI."
    ""
    "Continue?"
  ) -join "`n"
  $go = Show-ContinueCancelDialog -Title "Remove Windows Backup" -Message $warn -ContinueText "Continue" -CancelText "Cancel"
  if (-not $go) { return [pscustomobject]@{ Performed=$false; Package=$null; Error=$null } }
  $pkgs = @(Get-WindowsBackupRemovalPackageCandidates)
  if (-not $pkgs -or $pkgs.Count -eq 0) {
    return [pscustomobject]@{ Performed=$false; Package=$null; Error="No installed package candidates were found." }
  }
  $pick = Select-InstalledPackageDialog -Packages $pkgs -Title "Select UserExperience Package"
  if ([string]::IsNullOrWhiteSpace($pick)) {
    return [pscustomobject]@{ Performed=$false; Package=$null; Error=$null }
  }
  try {
    if ($BackupRoot -and (Test-Path -LiteralPath $BackupRoot)) {
      try { ('WindowsBackupUninstallSelected=' + $pick) | Set-Content -LiteralPath (Join-Path $BackupRoot 'WindowsBackupUninstall.txt') -Encoding ASCII } catch {}
    }
  } catch {}
  $rem = $null
  try { $rem = Remove-UserExperiencePackageStrict -PackageName ([string]$pick) } catch { $rem = $null }
  if ($rem -and $rem.Ok) {
    return [pscustomobject]@{ Performed=$true; Package=$pick; Error=$null }
  }
  $err = 'Package uninstall failed.'
  try { if ($rem -and -not [string]::IsNullOrWhiteSpace([string]$rem.Error)) { $err = [string]$rem.Error } } catch {}
  return [pscustomobject]@{ Performed=$false; Package=$pick; Error=$err }
}

function Show-WindowsBackupMockDeleteDialog {
  param([switch]$ShowRemoveFromPending)
  $msg = @(
    "To remove Windows Backup shortcut from the Start Menu a certain Windows UserExperience Package must be uninstalled."
    ""
    "As a consequence, the following features will also be lost from this 2023 update:"
    "ScreenClippingHost.exe - Snipping Tool capture UI (Win+Shift+S and screen clipping host)."
    "TextInputHost.exe - Touch keyboard, emoji panel, and IME text input interface."
    "WindowsBackupClient.exe - Windows Backup app client and backup workflow UI."
  ) -join "`n"
  $x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Remove Windows Backup" SizeToContent="WidthAndHeight" WindowStartupLocation="CenterOwner"
        ResizeMode="NoResize" ShowInTaskbar="False" Topmost="True">
  <Grid Margin="14">
    <Grid.RowDefinitions>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>
    <TextBox Name="Msg" Grid.Row="0" TextWrapping="Wrap" IsReadOnly="True" BorderThickness="0"
             Background="Transparent" FontSize="13" Width="620" />
    <StackPanel Grid.Row="1" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,12,0,0">
      <Button Name="RemoveBtn" MinWidth="170" Margin="0,0,8,0">Remove From Pending</Button>
      <Button Name="OkBtn" MinWidth="110" Margin="0,0,8,0" IsDefault="True">Continue</Button>
      <Button Name="CancelBtn" MinWidth="90" IsCancel="True">Cancel</Button>
    </StackPanel>
  </Grid>
</Window>
"@
  try {
    $reader = New-Object System.Xml.XmlNodeReader ([xml]$x)
    $w = [Windows.Markup.XamlReader]::Load($reader)
    try { if ($script:window) { $w.Owner = $script:window } } catch {}
    $w.FindName('Msg').Text = $msg
    # User request: "Remove From Pending" must never be greyed out.
    try { $w.FindName('RemoveBtn').IsEnabled = $true } catch {}
    $script:__wb_choice = 'Cancel'
    $w.FindName('OkBtn').Add_Click({ $script:__wb_choice = 'Continue'; $w.Close() })
    $w.FindName('CancelBtn').Add_Click({ $script:__wb_choice = 'Cancel'; $w.Close() })
    $w.FindName('RemoveBtn').Add_Click({ $script:__wb_choice = 'RemovePending'; $w.Close() })
    $null = $w.ShowDialog()
    return [string]$script:__wb_choice
  } catch {
    # Fallback: no third button in MessageBox; treat Cancel as Cancel.
    $r = [System.Windows.MessageBox]::Show($msg, "Remove Windows Backup", [System.Windows.MessageBoxButton]::OKCancel, [System.Windows.MessageBoxImage]::Warning)
    if ($r -eq [System.Windows.MessageBoxResult]::OK) { return 'Continue' }
    return 'Cancel'
  }
}

function Ensure-VisualAppsFolderProxyRows {
  try {
    $visual = $null
    try { $visual = Get-StartMenuVisualNode } catch {}
    if (-not $visual) { return }
    function _BuildShortcutNameIndexLive {
      $idx = @{}
      try {
        foreach ($r in $script:TreeRoots) {
          if (-not $r -or -not ($r -is [FolderNode])) { continue }
          $stack = New-Object System.Collections.Generic.Stack[FolderNode]
          $stack.Push($r)
          while ($stack.Count -gt 0) {
            $n = $stack.Pop()
            if (-not $n) { continue }
            foreach ($it in @($n.Items)) {
              if (-not $it) { continue }
              $tp = [string](Get-PropString -Obj $it -Names @('Type') -Fallback '')
              if ($tp -ne 'Shortcut') { continue }
              # Ignore legacy "Immersive Control Panel.lnk" style shortcuts.
              # Settings should be represented by the AppsFolder proxy row.
              try { if (Test-IsSettingsAliasShortcutRow -Row $it) { continue } } catch {}
              foreach ($nm in @([string](Get-PropString -Obj $it -Names @('Name') -Fallback ''), [string](Get-PropString -Obj $it -Names @('OriginalName') -Fallback ''))) {
                $k = Normalize-VisualKey $nm
                if (-not [string]::IsNullOrWhiteSpace($k)) { $idx[$k] = $true }
              }
            }
            foreach ($ch in @($n.Children)) { if ($ch) { $stack.Push($ch) } }
          }
        }
      } catch {}
      return $idx
    }
    function _BuildShortcutCandidates {
      $rows = New-Object System.Collections.Generic.List[object]
      $seen = @{}
      function _addRow {
        param([object]$row)
        if (-not $row) { return }
        $tp = [string](Get-PropString -Obj $row -Names @('Type') -Fallback '')
        if ($tp -ne 'Shortcut') { return }
        $sc = [string](Get-PropString -Obj $row -Names @('Scope') -Fallback '')
        $pp = [string](Get-PropString -Obj $row -Names @('Path','OriginalPath') -Fallback '')
        $k = (($sc + '|' + $pp).Trim().ToLowerInvariant())
        if ([string]::IsNullOrWhiteSpace($k)) { return }
        if ($seen.ContainsKey($k)) { return }
        $seen[$k] = $true
        [void]$rows.Add($row)
      }
      # Use startup inventory first (includes rows filtered out from TreeRoots, e.g. legacy Settings link).
      try {
        foreach ($it in @($script:StartupInventory)) { _addRow -row $it }
      } catch {}
      # Include live tree rows too.
      try {
        foreach ($r in $script:TreeRoots) {
          if (-not $r -or -not ($r -is [FolderNode])) { continue }
          $stack = New-Object System.Collections.Generic.Stack[FolderNode]
          $stack.Push($r)
          while ($stack.Count -gt 0) {
            $n = $stack.Pop()
            if (-not $n) { continue }
            foreach ($it in @($n.Items)) { _addRow -row $it }
            foreach ($ch in @($n.Children)) { if ($ch) { $stack.Push($ch) } }
          }
        }
      } catch {}
      return @($rows.ToArray())
    }
    function _ShortcutAffiliatedWithAppId {
      param(
        [Parameter(Mandatory=$true)][object]$Row,
        [Parameter(Mandatory=$true)][string]$AppId,
        [string]$DisplayName
      )
      try {
        if (-not $Row) { return $false }
        $target = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('Target') -Fallback ''))
        $args   = [string](Get-PropString -Obj $Row -Names @('Arguments') -Fallback '')
        $path   = [string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback '')
        $dispK  = Normalize-VisualKey $DisplayName
        $appK   = ($AppId.Trim().ToLowerInvariant())
        # Direct AppsFolder launch reference.
        if (-not [string]::IsNullOrWhiteSpace($args)) {
          $argsK = $args.ToLowerInvariant()
          if ($argsK -like ('*shell:appsfolder*' + $appK + '*')) { return $true }
          if ($argsK -like ('*appsfolder*' + $appK + '*')) { return $true }
        }
        if (-not [string]::IsNullOrWhiteSpace($path)) {
          $pathK = $path.ToLowerInvariant()
          if ($pathK -like ('*shell:appsfolder*' + $appK + '*')) { return $true }
        }
        # Settings legacy shortcut mapping:
        # Do NOT treat "Immersive Control Panel.lnk" as an affiliation that suppresses the Settings AppsFolder row.
        # The legacy alias is removed from the Visual grid; Settings must be represented by the AppsFolder display proxy.
        # Microsoft Edge direct shortcut mapping.
        # Get-StartApps AppID for Edge is not stable across builds (often 'MSEdge', sometimes UWP family!app),
        # but any of them should be considered "covered" if a filesystem shortcut targets msedge.exe.
        $isEdge = $false
        try {
          if ($dispK -eq 'microsoft edge') { $isEdge = $true }
          elseif ($appK -eq 'msedge') { $isEdge = $true }
          elseif ($appK -eq 'msedge'.ToLowerInvariant()) { $isEdge = $true }
          elseif ($appK -match '(^msedge$)') { $isEdge = $true }
          elseif ($appK -match 'microsoftedge') { $isEdge = $true }
        } catch {}
        if ($isEdge) {
          if (-not [string]::IsNullOrWhiteSpace($target) -and $target -match '(?i)\\msedge\\.exe$') { return $true }
        }
        # Conservative fallback by display name in path leaf only (for canonical, not renamed links).
        if (-not [string]::IsNullOrWhiteSpace($dispK) -and -not [string]::IsNullOrWhiteSpace($path)) {
          $leaf = ''
          try { $leaf = [System.IO.Path]::GetFileNameWithoutExtension($path) } catch {}
          if ((Normalize-VisualKey $leaf) -eq $dispK) { return $true }
        }
      } catch {}
      return $false
    }
    $shortcutNameIndex = $null
    $shortcutCandidates = @()
    $hasAnyEdgeShortcut = $false
    $hasAnyOutlookShortcut = $false
    $canUseDiscoveryCache = $false
    try {
      if ($script:VisualProxyDiscoveryCache) {
        $cacheNodeMapRef = $null
        $cacheStateVersion = -1
        try { $cacheNodeMapRef = $script:VisualProxyDiscoveryCache.NodeMapRef } catch {}
        try { $cacheStateVersion = [int]$script:VisualProxyDiscoveryCache.StateVersion } catch { $cacheStateVersion = -1 }
        if (($cacheNodeMapRef -eq $script:NodeMap) -and ($cacheStateVersion -eq [int]$script:VisualRuntimeStateVersion)) {
          $canUseDiscoveryCache = $true
        }
      }
    } catch { $canUseDiscoveryCache = $false }
    if ($canUseDiscoveryCache) {
      try { $shortcutNameIndex = $script:VisualProxyDiscoveryCache.ShortcutNameIndex } catch { $shortcutNameIndex = @{} }
      try { $shortcutCandidates = @($script:VisualProxyDiscoveryCache.ShortcutCandidates) } catch { $shortcutCandidates = @() }
      try { $hasAnyEdgeShortcut = [bool]$script:VisualProxyDiscoveryCache.HasAnyEdgeShortcut } catch { $hasAnyEdgeShortcut = $false }
      try { $hasAnyOutlookShortcut = [bool]$script:VisualProxyDiscoveryCache.HasAnyOutlookShortcut } catch { $hasAnyOutlookShortcut = $false }
    } else {
      $shortcutNameIndex = _BuildShortcutNameIndexLive
      $shortcutCandidates = _BuildShortcutCandidates
    }
    # Edge is special: Windows may expose an AppsFolder "Microsoft Edge" entry even when a normal shortcut exists.
    # The real Start Menu typically shows only the filesystem shortcut if present (even if renamed), so suppress the
    # AppsFolder proxy whenever ANY shortcut appears to launch Edge.
    function _HasAnyEdgeShortcut {
      param([object[]]$Rows)
      try {
        foreach ($r in @($Rows)) {
          if (-not $r) { continue }
          $tp = [string](Get-PropString -Obj $r -Names @('Type') -Fallback '')
          if ($tp -ne 'Shortcut') { continue }
          $tgt = Normalize-Path ([string](Get-PropString -Obj $r -Names @('Target') -Fallback ''))
          $arg = [string](Get-PropString -Obj $r -Names @('Arguments') -Fallback '')
          $pth = [string](Get-PropString -Obj $r -Names @('Path','OriginalPath') -Fallback '')
          if (-not [string]::IsNullOrWhiteSpace($tgt) -and $tgt -match '(?i)\\msedge\\.exe$') { return $true }
          $a = ''
          try { $a = $arg.ToLowerInvariant() } catch { $a = [string]$arg }
          $p = ''
          try { $p = $pth.ToLowerInvariant() } catch { $p = [string]$pth }
          # Explorer shell launch to AppsFolder Edge.
          if ($a -like '*shell:appsfolder*\\msedge*') { return $true }
          if ($p -like '*shell:appsfolder*\\msedge*') { return $true }
          # Older/newer Edge identifiers can appear as the UWP family id.
          if ($a -like '*shell:appsfolder*\\microsoft.microsoftedge_*') { return $true }
          if ($p -like '*shell:appsfolder*\\microsoft.microsoftedge_*') { return $true }
        }
      } catch {}
      return $false
    }
    if (-not $canUseDiscoveryCache) {
      try { $hasAnyEdgeShortcut = _HasAnyEdgeShortcut -Rows $shortcutCandidates } catch { $hasAnyEdgeShortcut = $false }
    }
    $script:HasAnyEdgeShortcut = [bool]$hasAnyEdgeShortcut
    # Outlook can come back from Get-StartApps with transient/old display names right after rename/apply.
    # To avoid phantom proxy rows, suppress Outlook proxy whenever ANY Outlook shortcut exists.
    function _HasAnyOutlookShortcut {
      param([object[]]$Rows)
      try {
        foreach ($r in @($Rows)) {
          if (-not $r) { continue }
          $tp = [string](Get-PropString -Obj $r -Names @('Type') -Fallback '')
          if ($tp -ne 'Shortcut') { continue }
          $nm = [string](Get-PropString -Obj $r -Names @('Name','OriginalName') -Fallback '')
          $nk = Normalize-VisualKey $nm
          if (-not [string]::IsNullOrWhiteSpace($nk) -and $nk -like 'outlook*') { return $true }
          $tgt = Normalize-Path ([string](Get-PropString -Obj $r -Names @('Target') -Fallback ''))
          if (-not [string]::IsNullOrWhiteSpace($tgt) -and $tgt -match '(?i)\\olk\.exe$') { return $true }
          $arg = [string](Get-PropString -Obj $r -Names @('Arguments') -Fallback '')
          $pth = [string](Get-PropString -Obj $r -Names @('Path','OriginalPath') -Fallback '')
          $a = ''
          try { $a = $arg.ToLowerInvariant() } catch { $a = [string]$arg }
          $p = ''
          try { $p = $pth.ToLowerInvariant() } catch { $p = [string]$pth }
          if ($a -like '*shell:appsfolder*\\microsoft.outlookforwindows*') { return $true }
          if ($p -like '*shell:appsfolder*\\microsoft.outlookforwindows*') { return $true }
          $leaf = ''
          try { if (-not [string]::IsNullOrWhiteSpace($pth)) { $leaf = [System.IO.Path]::GetFileNameWithoutExtension($pth) } } catch {}
          $leafK = Normalize-VisualKey $leaf
          if (-not [string]::IsNullOrWhiteSpace($leafK) -and $leafK -like 'outlook*') { return $true }
        }
      } catch {}
      return $false
    }
    if (-not $canUseDiscoveryCache) {
      try { $hasAnyOutlookShortcut = _HasAnyOutlookShortcut -Rows $shortcutCandidates } catch { $hasAnyOutlookShortcut = $false }
    }
    $script:HasAnyOutlookShortcut = [bool]$hasAnyOutlookShortcut
    if (-not $canUseDiscoveryCache) {
      try {
        $script:VisualProxyDiscoveryCache = [pscustomobject]@{
          NodeMapRef          = $script:NodeMap
          StateVersion        = [int]$script:VisualRuntimeStateVersion
          ShortcutNameIndex   = $shortcutNameIndex
          ShortcutCandidates  = @($shortcutCandidates)
          HasAnyEdgeShortcut  = [bool]$hasAnyEdgeShortcut
          HasAnyOutlookShortcut = [bool]$hasAnyOutlookShortcut
        }
      } catch {}
    }
    $wantNamePatterns = @(
      @{ Pattern = '^Settings$';       Fallback = 'Settings' },
      # Edge AppsFolder entry is intentionally hidden from this grid.
      # Users should interact with the real filesystem shortcut only.
      @{ Pattern = '^Outlook';         Fallback = 'Outlook' },
      @{ Pattern = '^Windows Backup$'; Fallback = 'Windows Backup' }
    )
    $apps = Get-StartAppsCached -MaxAgeSeconds 30
    if (-not $apps -or $apps.Count -eq 0) { $apps = @() }
    $found = New-Object System.Collections.Generic.List[object]
    foreach ($spec in $wantNamePatterns) {
      $pat = [string]$spec.Pattern
      $fb  = [string]$spec.Fallback
      $match = $null
      foreach ($a in $apps) {
        if (-not $a) { continue }
        $nm = ''
        try { $nm = [string]$a.Name } catch {}
        if ($nm -and ($nm -match $pat)) { $match = $a; break }
      }
      if ($match) {
        $appid = ''
        $disp  = ''
        try { $appid = [string]$match.AppID } catch {}
        try { $disp  = [string]$match.Name } catch {}
        if (-not [string]::IsNullOrWhiteSpace($appid)) {
          # If a real Start Menu shortcut exists ANYWHERE for this display name, don't add a proxy (prevents duplicates).
          $hasShortcutByName = $false
          try {
            if (-not [string]::IsNullOrWhiteSpace($disp) -and $shortcutNameIndex) {
              $k = Normalize-VisualKey $disp
              if (-not [string]::IsNullOrWhiteSpace($k) -and $shortcutNameIndex.ContainsKey($k)) { $hasShortcutByName = $true }
            }
          } catch {}
          $hasShortcutByAffiliation = $false
          if (-not $hasShortcutByName) {
            try {
              # Edge suppression by launcher-detection (name-independent).
              if ($pat -eq '^Microsoft Edge$' -and $script:HasAnyEdgeShortcut) {
                $hasShortcutByAffiliation = $true
              } elseif ($pat -eq '^Outlook' -and $script:HasAnyOutlookShortcut) {
                $hasShortcutByAffiliation = $true
              } else {
                foreach ($sr in @($shortcutCandidates)) {
                  if (_ShortcutAffiliatedWithAppId -Row $sr -AppId $appid -DisplayName $disp) {
                    $hasShortcutByAffiliation = $true
                    break
                  }
                }
              }
            } catch {}
          }
          if (-not $hasShortcutByName -and -not $hasShortcutByAffiliation) {
            [void]$found.Add([pscustomobject]@{ AppId=$appid; Fallback=$fb; Name=$disp })
          } else {
          }
        }
      }
    }
    $infoMap = @{}
    if ($found.Count -gt 0) {
      $ids = @()
      foreach ($f in $found) { if ($f -and $f.AppId) { $ids += [string]$f.AppId } }
      try { $infoMap = Get-AppsFolderInfoMapCached -AppIds $ids -MaxAgeSeconds 120 } catch { $infoMap = @{} }
    }
    $existingByAppId = @{}
    foreach ($r in @($script:VisualAppsFolderProxyRows)) {
      if (-not $r) { continue }
      # Only reuse display proxies. Never reuse legacy ShellApp proxies (they cause self-suppression/disappearing rows).
      $isDisp = $false
      try { $isDisp = ($r.PSObject.Properties.Match('IsAppsFolderDisplayProxy').Count -gt 0 -and [bool]$r.IsAppsFolderDisplayProxy) } catch { $isDisp = $false }
      if (-not $isDisp) { continue }
      $aid = ''
      try { $aid = [string]$r.AppsFolderId } catch {}
      if ([string]::IsNullOrWhiteSpace($aid)) { continue }
      $existingByAppId[$aid] = $r
    }
    $newRows = New-Object System.Collections.Generic.List[object]
    foreach ($f in $found) {
      $aid = [string]$f.AppId
      if ($existingByAppId.ContainsKey($aid)) {
        [void]$newRows.Add($existingByAppId[$aid])
        continue
      }
      # IMPORTANT:
      # Use a DISPLAY proxy row (Type=Shortcut) instead of an actual ShellApp row.
      # ShellApp rows must never appear in the grid, and converting them in-place causes the proxy to
      # self-suppress (it looks like a real shortcut to our own inventory scanners).
      $disp = [string]$f.Name
      if ([string]::IsNullOrWhiteSpace($disp)) { $disp = [string]$f.Fallback }
      $kind = 'AppsFolder'
      try {
        if ($disp -match '^Settings$') { $kind = 'Settings' }
        elseif ($disp -match '^Microsoft Edge$') { $kind = 'Edge' }
        elseif ($disp -match '^Outlook') { $kind = 'Outlook' }
        elseif ($disp -match '^Windows Backup$') { $kind = 'WindowsBackup' }
      } catch {}
      # Outlook display names from Get-StartApps can lag after rename/delete of editable links.
      # Always render the ShellApp proxy as canonical "Outlook" to avoid stale phantom labels.
      if ($kind -eq 'Outlook') { $disp = 'Outlook' }
      $row = New-AppsFolderDisplayProxyRow -AppId $aid -DisplayName $disp -ProxyKind $kind
      # Windows Backup needs the special delete flow (package uninstall planning).
      if ($row -and $kind -eq 'WindowsBackup') {
        try { Set-PropSafeGlobal -Obj $row -Name 'IsWindowsBackupProxy' -Value $true } catch {}
        try {
          if ($row.PSObject.Properties.Match('WindowsBackupPlannedPackageName').Count -eq 0) {
            $row | Add-Member -NotePropertyName 'WindowsBackupPlannedPackageName' -NotePropertyValue '' -Force
          }
        } catch {}
      }
      if ($row) { [void]$newRows.Add($row) }
    }
    $script:VisualAppsFolderProxyRows = @($newRows.ToArray())
  } catch {}
}

function Test-IsElevated {
  try {
    # Fast path: if not even in Administrators group, definitely not elevated.
    $id = [Security.Principal.WindowsIdentity]::GetCurrent()
    $p  = New-Object Security.Principal.WindowsPrincipal $id
    if (-not $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { return $false }
    # UAC nuance: an admin-group user can run with a filtered (non-elevated) token.
    # Check token elevation directly.
    if (-not ([System.Management.Automation.PSTypeName]'Win32Token').Type) {
      Add-Type -Language CSharp -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class Win32Token {
  [DllImport("kernel32.dll", SetLastError=true)]
  public static extern IntPtr GetCurrentProcess();

  [DllImport("advapi32.dll", SetLastError=true)]
  public static extern bool OpenProcessToken(IntPtr ProcessHandle, UInt32 DesiredAccess, out IntPtr TokenHandle);

  [DllImport("advapi32.dll", SetLastError=true)]
  public static extern bool GetTokenInformation(IntPtr TokenHandle, int TokenInformationClass, out int TokenInformation, int TokenInformationLength, out int ReturnLength);

  public const UInt32 TOKEN_QUERY = 0x0008;
  public const int TokenElevation = 20;
}
"@ | Out-Null
    }

    $h = [IntPtr]::Zero
    $ok = [Win32Token]::OpenProcessToken([Win32Token]::GetCurrentProcess(), [Win32Token]::TOKEN_QUERY, [ref]$h)
    if (-not $ok) { return $false }

    $elev = 0
    $len  = 0
    $ok2  = [Win32Token]::GetTokenInformation($h, [Win32Token]::TokenElevation, [ref]$elev, 4, [ref]$len)
    return ($ok2 -and ($elev -ne 0))
  } catch {
    return $false
  }
}

function Restart-ThisScriptAsAdmin {
  try {
    $scriptPath = $null
    try { $scriptPath = [string]$PSCommandPath } catch {}
    if ([string]::IsNullOrWhiteSpace($scriptPath)) {
      try { $scriptPath = [string]$MyInvocation.MyCommand.Path } catch {}
    }
    if ([string]::IsNullOrWhiteSpace($scriptPath)) {
      throw "Unable to determine script path for elevation restart."
    }

    $args = @('-NoProfile','-STA','-ExecutionPolicy','Bypass','-File', $scriptPath)
    Release-SingleInstanceMutexForRestart
    Start-Process -FilePath 'powershell.exe' -Verb RunAs -WorkingDirectory $PSScriptRoot -ArgumentList $args | Out-Null
    try { $window.Close() } catch {}
  } catch {
    [System.Windows.MessageBox]::Show($_.Exception.Message, 'Elevation Error') | Out-Null
  }
}

function Ensure-ElevatedOrPrompt {
  param([Parameter(Mandatory=$true)][string]$Reason)
  $isElev = $false
  try { $isElev = [bool](Test-IsElevated) } catch {}
  if ($isElev) { return $true }

  $res = [System.Windows.MessageBox]::Show(
    ($Reason + "`n`nRestart this tool as Administrator now?"),
    "Elevation Required",
    [System.Windows.MessageBoxButton]::YesNo,
    [System.Windows.MessageBoxImage]::Warning
  )
  if ($res -eq [System.Windows.MessageBoxResult]::Yes) {
    Restart-ThisScriptAsAdmin
  }
  return $false
}

function Test-WindowsSecurityShellAppPresent {
  # Cached because Get-StartApps can be slow.
  try {
    $now = Get-Date
    if ($script:WinSecShellAppPresentCacheAt -and (($now - $script:WinSecShellAppPresentCacheAt).TotalSeconds -lt 30)) {
      return [bool]$script:WinSecShellAppPresentCache
    }

    $present = $false
    try {
      if (Get-Command Get-StartApps -ErrorAction SilentlyContinue) {
        $apps = @(Get-StartApps | Where-Object {
          ($_.Name -eq 'Windows Security') -or ([string]$_.AppID -match 'SecHealthUI')
        })
        if ($apps.Count -gt 0) { $present = $true }
      }
    } catch {}

    $script:WinSecShellAppPresentCacheAt = $now
    $script:WinSecShellAppPresentCache   = $present

    return [bool]$present
  } catch {
    return $false
  }
}

function Get-WindowsSecurityLaunchSpec {
  $explorer = Join-Path $env:WINDIR 'explorer.exe'
  $args     = 'windowsdefender:'

  $icon = (Join-Path $env:WINDIR 'System32\imageres.dll') + ',2'
  $shield = Join-Path $env:WINDIR 'System32\SecurityHealthSystray.exe'
  if (Test-Path -LiteralPath $shield) { $icon = ($shield + ',0') }

  return [pscustomobject]@{
    Target = $explorer
    Args   = $args
    Icon   = $icon
  }
}

function Test-WindowsSecurityEditableShortcutExists {
  param([int]$MaxAgeSeconds = 15)

  # Returns true if a filesystem-backed shortcut exists that launches Windows Security.
  # If true, we suppress the protected proxy row and don't prompt the rename dialog again.
  try {
    $now = Get-Date
    if ($script:WinSecEditableShortcutCacheAt -and (($now - $script:WinSecEditableShortcutCacheAt).TotalSeconds -lt $MaxAgeSeconds)) {
      return [bool]$script:WinSecEditableShortcutCache
    }

    $spec = Get-WindowsSecurityLaunchSpec
    $tgt  = [string]$spec.Target

    $found = $false
    foreach ($it in @($script:StartupInventory)) {
      if (-not $it) { continue }
      $type = ''
      try { $type = [string]$it.Type } catch {}
      if ($type -ne 'Shortcut') { continue }

      $target = ''
      $args   = ''
      try { $target = [string]$it.Target } catch {}
      try { $args   = [string]$it.Arguments } catch {}
      if ([string]::IsNullOrWhiteSpace($args)) { try { $args = [string]$it.Args } catch {} }

      if ([string]::IsNullOrWhiteSpace($target) -or [string]::IsNullOrWhiteSpace($args)) { continue }
      if (-not ($target -ieq $tgt)) { continue }

      if ($args -match 'windowsdefender' -or $args -match 'SecHealthUI' -or $args -match 'AppsFolder\\\\Microsoft\\.Windows\\.SecHealthUI') {
        $found = $true
        break
      }
    }

    $script:WinSecEditableShortcutCacheAt = $now
    $script:WinSecEditableShortcutCache   = [bool]$found
    return [bool]$found
  } catch {
    return $false
  }
}

function Ensure-ShellLinkInteropTypes {
  if ("StartMenuTool.ShellLink" -as [type]) { return }

  Add-Type -Language CSharp -TypeDefinition @"
using System;
using System.Runtime.InteropServices;

namespace StartMenuTool {
  [StructLayout(LayoutKind.Sequential, Pack = 4)]
  public struct PROPERTYKEY {
    public Guid fmtid;
    public uint pid;
    public PROPERTYKEY(Guid fmtid, uint pid) { this.fmtid = fmtid; this.pid = pid; }
  }

  [StructLayout(LayoutKind.Explicit)]
  public struct PROPVARIANT {
    [FieldOffset(0)] public ushort vt;
    [FieldOffset(8)] public IntPtr pwszVal;

    public static PROPVARIANT FromString(string value) {
      var pv = new PROPVARIANT();
      pv.vt = 31; // VT_LPWSTR
      pv.pwszVal = Marshal.StringToCoTaskMemUni(value);
      return pv;
    }

    public void Clear() {
      PropVariantClear(ref this);
    }

    [DllImport("Ole32.dll")]
    private static extern int PropVariantClear(ref PROPVARIANT pvar);
  }

  [ComImport]
  [Guid("000214F9-0000-0000-C000-000000000046")]
  [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  public interface IShellLinkW {
    int GetPath([Out, MarshalAs(UnmanagedType.LPWStr)] System.Text.StringBuilder pszFile, int cchMaxPath, IntPtr pfd, int fFlags);
    int GetIDList(out IntPtr ppidl);
    int SetIDList(IntPtr pidl);
    int GetDescription([Out, MarshalAs(UnmanagedType.LPWStr)] System.Text.StringBuilder pszName, int cchMaxName);
    int SetDescription([MarshalAs(UnmanagedType.LPWStr)] string pszName);
    int GetWorkingDirectory([Out, MarshalAs(UnmanagedType.LPWStr)] System.Text.StringBuilder pszDir, int cchMaxPath);
    int SetWorkingDirectory([MarshalAs(UnmanagedType.LPWStr)] string pszDir);
    int GetArguments([Out, MarshalAs(UnmanagedType.LPWStr)] System.Text.StringBuilder pszArgs, int cchMaxPath);
    int SetArguments([MarshalAs(UnmanagedType.LPWStr)] string pszArgs);
    int GetHotkey(out short pwHotkey);
    int SetHotkey(short wHotkey);
    int GetShowCmd(out int piShowCmd);
    int SetShowCmd(int iShowCmd);
    int GetIconLocation([Out, MarshalAs(UnmanagedType.LPWStr)] System.Text.StringBuilder pszIconPath, int cchIconPath, out int piIcon);
    int SetIconLocation([MarshalAs(UnmanagedType.LPWStr)] string pszIconPath, int iIcon);
    int SetRelativePath([MarshalAs(UnmanagedType.LPWStr)] string pszPathRel, int dwReserved);
    int Resolve(IntPtr hwnd, int fFlags);
    int SetPath([MarshalAs(UnmanagedType.LPWStr)] string pszFile);
  }

  [ComImport]
  [Guid("886D8EEB-8CF2-4446-8D02-CDBA1DBDCF99")]
  [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  public interface IPropertyStore {
    int GetCount(out uint cProps);
    int GetAt(uint iProp, out PROPERTYKEY pkey);
    int GetValue(ref PROPERTYKEY key, out PROPVARIANT pv);
    int SetValue(ref PROPERTYKEY key, ref PROPVARIANT pv);
    int Commit();
  }

  [ComImport]
  [Guid("0000010b-0000-0000-C000-000000000046")]
  [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  public interface IPersistFile {
    int GetClassID(out Guid pClassID);
    int IsDirty();
    int Load([MarshalAs(UnmanagedType.LPWStr)] string pszFileName, uint dwMode);
    int Save([MarshalAs(UnmanagedType.LPWStr)] string pszFileName, bool fRemember);
    int SaveCompleted([MarshalAs(UnmanagedType.LPWStr)] string pszFileName);
    int GetCurFile([MarshalAs(UnmanagedType.LPWStr)] out string ppszFileName);
  }

  [ComImport]
  [Guid("00021401-0000-0000-C000-000000000046")]
