}
"@ | Out-Null
}

function Set-ShortcutAppUserModelId {
  param(
    [Parameter(Mandatory=$true)][string]$LnkPath,
    [Parameter(Mandatory=$true)][string]$AppUserModelId
  )

  if (-not (Test-Path -LiteralPath $LnkPath)) { return $false }
  if ([string]::IsNullOrWhiteSpace($AppUserModelId)) { return $false }

  Ensure-ShellLinkInteropTypes

  $pf = $null
  $ps = $null
  $pv = $null
  try {
    $link = New-Object StartMenuTool.ShellLink
    $pf = [StartMenuTool.IPersistFile]$link
    # STGM_READWRITE (0x2) is sufficient for .lnk updates
    [void]$pf.Load($LnkPath, 2)

    $ps = [StartMenuTool.IPropertyStore]$link
    $key = New-Object StartMenuTool.PROPERTYKEY ([Guid]'9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3'), 5
    $pv = [StartMenuTool.PROPVARIANT]::FromString($AppUserModelId)
    [void]$ps.SetValue([ref]$key, [ref]$pv)
    [void]$ps.Commit()
    [void]$pf.Save($LnkPath, $true)
    return $true
  } catch {
    return $false
  } finally {
    try { if ($pv) { $pv.Clear() } } catch {}
  }
}

function Set-ShortcutAppUserModelStringProperty {
  param(
    [Parameter(Mandatory=$true)][string]$LnkPath,
    [Parameter(Mandatory=$true)][uint32]$Pid,
    [Parameter(Mandatory=$true)][string]$Value
  )

  if (-not (Test-Path -LiteralPath $LnkPath)) { return $false }
  if ([string]::IsNullOrWhiteSpace($Value)) { return $false }

  Ensure-ShellLinkInteropTypes

  $pv = $null
  try {
    $link = New-Object StartMenuTool.ShellLink
    $pf = [StartMenuTool.IPersistFile]$link
    [void]$pf.Load($LnkPath, 2)

    $ps = [StartMenuTool.IPropertyStore]$link
    $key = New-Object StartMenuTool.PROPERTYKEY ([Guid]'9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3'), $Pid
    $pv = [StartMenuTool.PROPVARIANT]::FromString($Value)
    [void]$ps.SetValue([ref]$key, [ref]$pv)
    [void]$ps.Commit()
    [void]$pf.Save($LnkPath, $true)
    return $true
  } catch {
    return $false
  } finally {
    try { if ($pv) { $pv.Clear() } } catch {}
  }
}

function Get-FSLogixFrxExe {
  $p = 'C:\Program Files\FSLogix\Apps\frx.exe'
  if (Test-Path -LiteralPath $p) { return $p }
  return $null
}

function Invoke-FSLogixFrx {
  param([Parameter(Mandatory=$true)][string[]]$Args)
  $frx = Get-FSLogixFrxExe
  if ([string]::IsNullOrWhiteSpace($frx)) { throw "FSLogix frx.exe not found." }
  $out = ''
  try { $out = (& $frx @Args 2>&1 | Out-String) } catch { $out = ($_ | Out-String) }
  return [pscustomobject]@{ Output = [string]$out; ExitCode = $LASTEXITCODE }
}

function Get-CurrentUserSidString {
  try { return ([Security.Principal.WindowsIdentity]::GetCurrent().User.Value) } catch { return $null }
}

function Get-FSLogixHideTargetsForPackageFullName {
  param([Parameter(Mandatory=$true)][string]$PackageFullName)

  $targets = New-Object System.Collections.Generic.List[object]
  $sid = Get-CurrentUserSidString

  $roots = @(
    @{ Ps='HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\InboxApplications'; Parent='\Registry\Machine\SOFTWARE\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\InboxApplications' },
    @{ Ps=("HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\" + $sid); Parent=('\Registry\Machine\SOFTWARE\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\' + $sid) }
  )

  foreach ($r in $roots) {
    if (-not $r.Ps) { continue }
    try {
      $k = Join-Path ([string]$r.Ps) $PackageFullName
      if (Test-Path -LiteralPath $k) {
        [void]$targets.Add([pscustomobject]@{ SrcParent = [string]$r.Parent; Src = $PackageFullName })
      }
    } catch {}
  }

  return $targets.ToArray()
}

function Add-FSLogixHideForAppId {
  param(
    [Parameter(Mandatory=$true)][string]$AppId,
    [switch]$SkipAgentStart,
    [switch]$SkipReload
  )

  if ($AppId -notlike '*!*') { throw ("FSLogix hide mapping requires an AppX AUMID (family!app). Got: " + $AppId) }
  $family = [string]($AppId.Split('!',2)[0])
  if ([string]::IsNullOrWhiteSpace($family)) { throw ("Unable to parse PackageFamilyName from: " + $AppId) }

  $pkgs = @()
  try { $pkgs = @(Get-AppxPackage -ErrorAction SilentlyContinue | Where-Object { [string]$_.PackageFamilyName -eq $family }) } catch { $pkgs = @() }
  if (-not $pkgs -or $pkgs.Count -eq 0) { throw ("No AppX package found for family: " + $family) }

  $allTargets = New-Object System.Collections.Generic.List[object]
  foreach ($p in $pkgs) {
    $pf = ''
    try { $pf = [string]$p.PackageFullName } catch {}
    if ([string]::IsNullOrWhiteSpace($pf)) { continue }
    foreach ($t in @(Get-FSLogixHideTargetsForPackageFullName -PackageFullName $pf)) {
      if ($t) { [void]$allTargets.Add($t) }
    }
  }

  if ($allTargets.Count -eq 0) { throw "No registry keys found to hide for this app." }

  # Unique targets
  $seen = @{}
  $uniq = New-Object System.Collections.Generic.List[object]
  foreach ($t in $allTargets) {
    $k = ([string]$t.SrcParent + '|' + [string]$t.Src).ToLowerInvariant()
    if ($seen.ContainsKey($k)) { continue }
    $seen[$k] = $true
    [void]$uniq.Add($t)
  }

  if (-not $SkipAgentStart) {
    $null = Invoke-FSLogixFrx -Args @('start-agent')
  }

  $added = New-Object System.Collections.Generic.List[object]
  foreach ($t in $uniq) {
    $res = Invoke-FSLogixFrx -Args @('add-rule','-hide','-src-parent',[string]$t.SrcParent,'-src',[string]$t.Src)
    if ($res.ExitCode -ne 0) { throw ("FSLogix add-rule failed: " + $res.Output) }
    [void]$added.Add($t)
  }
  if (-not $SkipReload) {
    $null = Invoke-FSLogixFrx -Args @('reload-rules')
  }

  return [pscustomobject]@{ Added = $added.ToArray() }
}

function Write-AppsFolderReplacementShortcut {
  param(
    [Parameter(Mandatory=$true)][string]$DestRoot,
    [Parameter(Mandatory=$true)][string]$DisplayName,
    [Parameter(Mandatory=$true)][string]$AppId,
    [string]$BackupRoot = $null
  )

  if (-not (Test-Path -LiteralPath $DestRoot)) { New-Item -ItemType Directory -Path $DestRoot -Force | Out-Null }

  $base = ([string]$DisplayName).Trim()
  if ([string]::IsNullOrWhiteSpace($base)) { $base = $AppId }
  $fileName = ($base + '`' + ".lnk")
  if (-not (Test-ValidFileName -Name $fileName)) {
    $fileName = ("AppsFolder Item" + '`' + ".lnk")
  }

  $lnkPath = Join-Path $DestRoot $fileName
  if ($BackupRoot -and (Test-Path -LiteralPath $lnkPath)) {
    try {
      $backupDir = Join-Path $BackupRoot 'AppsFolderReplacementBackup'
      New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
      $stamp = (Get-Date).ToString('yyyyMMdd_HHmmss')
      Copy-Item -LiteralPath $lnkPath -Destination (Join-Path $backupDir ("$fileName.prev.$stamp")) -Force -ErrorAction Stop
    } catch {}
  }

  $explorer = Join-Path $env:WINDIR 'explorer.exe'
  $args = ('shell:AppsFolder\' + $AppId)

  # Pull AppsFolder icon resource if possible for better Start rendering.
  $iconRes = ''
  $forceWinBackupIcon = $false
  try {
    if ([string]$AppId -match '(?i)windowsbackup') {
      $wbIco = Get-WindowsBackupIconLocation
      if (-not [string]::IsNullOrWhiteSpace($wbIco)) {
        $iconRes = [string]$wbIco
        $forceWinBackupIcon = $true
      }
    }
    if (-not $forceWinBackupIcon) {
      $m = Get-AppsFolderInfoMapCached -AppIds @($AppId) -MaxAgeSeconds 120
      if ($m.ContainsKey($AppId)) { $iconRes = [string]$m[$AppId].IconResource }
    }
  } catch {}

  $ws = New-Object -ComObject WScript.Shell
  $sc = $ws.CreateShortcut($lnkPath)
  $sc.TargetPath = $explorer
  $sc.Arguments  = $args
  $sc.WorkingDirectory = $env:WINDIR

  $parsed = $null
  try { $parsed = Parse-IconLocationString -IconLocation $iconRes } catch { $parsed = $null }
  if ($parsed -and -not [string]::IsNullOrWhiteSpace([string]$parsed.IconPath) -and ($forceWinBackupIcon -or (Test-Path -LiteralPath $parsed.IconPath))) {
    $sc.IconLocation = ("{0},{1}" -f [string]$parsed.IconPath, [int]$parsed.IconIndex)
  } else {
    # Try AppX logo from package assets (PNG). Some builds render PNG icons fine for .lnk.
    $logo = $null
    try {
      if ($AppId -like '*!*') {
        $parts = $AppId.Split('!',2)
        $fam   = [string]$parts[0]
        $app   = [string]$parts[1]
        $map = Get-AppxInstallLocationByFamilyCached -MaxAgeSeconds 120
        if ($map -and $map.ContainsKey($fam)) {
          $loc = [string]$map[$fam]
          if (-not [string]::IsNullOrWhiteSpace($loc) -and (Test-Path -LiteralPath $loc)) {
            $rel = Get-AppxLogoRelPathFromManifest -InstallLocation $loc -AppId $app
            if (-not [string]::IsNullOrWhiteSpace($rel)) {
              $logo = Resolve-AppxLogoAbsolutePath -InstallLocation $loc -RelativeLogoPath $rel
            }
          }
        }
      }
    } catch { $logo = $null }

    if ($logo -and (Test-Path -LiteralPath $logo)) {
      $sc.IconLocation = ("{0},0" -f [string]$logo)
    } else {
      $imageres = Join-Path $env:WINDIR 'System32\\imageres.dll'
      $sc.IconLocation = ("{0},2" -f $imageres)
    }
  }
  $sc.Description = $DisplayName
  $sc.Save()

  # AppUserModel properties help Start resolve correct icon/display for shell:AppsFolder entries.
  try { [void](Set-ShortcutAppUserModelId -LnkPath $lnkPath -AppUserModelId $AppId) } catch {}
  if (-not [string]::IsNullOrWhiteSpace($iconRes)) {
    try { [void](Set-ShortcutAppUserModelStringProperty -LnkPath $lnkPath -Pid 3 -Value $iconRes) } catch {}
  }

  try { Invoke-StartMenuRefresh -TouchedFolder $DestRoot } catch {}
  return $lnkPath
}

function New-WindowsSecurityProxyRow {
  $spec = Get-WindowsSecurityLaunchSpec

  # Planned path: create in CurrentUser start menu root on Apply (no admin needed for the shortcut itself).
  $dstRoot = [string]$scopeRoots['CurrentUser']
  if ([string]::IsNullOrWhiteSpace($dstRoot)) { $dstRoot = (Join-Path $env:AppData 'Microsoft\Windows\Start Menu\Programs') }
  $planned = Join-Path $dstRoot 'Windows Security.lnk'

  $img = $null
  try {
    $parts = [string]$spec.Icon -split ','
    $ip = $parts[0]
    $ii = 0
    if ($parts.Length -ge 2) { [void][int]::TryParse($parts[1], [ref]$ii) }
    if (Test-Path -LiteralPath $ip) {
      $img = Get-ImageSourceFromIcon -IconPath $ip -IconIndex $ii -FallbackExePath $ip
    }
  } catch {}

  return [pscustomobject]@{
    Id           = [guid]::NewGuid().ToString()
    Selected     = $false
    Action       = 'None'
    PendingLabel = ''

    OriginalName = 'Windows Security'
    Name         = 'Windows Security'
    Type         = 'Shortcut'
    Scope        = 'WinSecProxy'
    IsSelectable = $false

    Target       = [string]$spec.Target
    Path         = $planned
    OriginalPath = $planned

    Icon         = $img
    RowKind      = 'Item'

    IsWindowsSecurityProxy = $true
  }
}

function Ensure-WindowsSecurityProxyRow {
  try {
    if (-not (Test-WindowsSecurityShellAppPresent)) { return }

    $visual = $null
    try { $visual = Get-StartMenuVisualNode } catch {}
    if (-not $visual) { return }

    # If an editable, filesystem-backed Windows Security shortcut already exists,
    # suppress the protected proxy row so users interact with the real shortcut.
    if (Test-WindowsSecurityEditableShortcutExists) {
      try {
        for ($i = $visual.Items.Count - 1; $i -ge 0; $i--) {
          $it = $visual.Items[$i]
          if (-not $it) { continue }
          $isWinSec = $false
          try { $isWinSec = ($it.PSObject.Properties.Match('IsWindowsSecurityProxy').Count -gt 0 -and [bool]$it.IsWindowsSecurityProxy) } catch {}
          if ($isWinSec) { $visual.Items.RemoveAt($i) }
        }
      } catch {}
      try { $script:WindowsSecurityProxyRow = $null } catch {}
      return
    }

    if (-not $script:WindowsSecurityProxyRow) {
      $script:WindowsSecurityProxyRow = New-WindowsSecurityProxyRow
    }

    # Attach to VisualMenu node so undo/redo can find it.
    $exists = $false
    foreach ($it in @($visual.Items)) {
      if ($null -ne $it -and ($it -eq $script:WindowsSecurityProxyRow)) { $exists = $true; break }
    }
    if (-not $exists) {
      [void]$visual.Items.Add($script:WindowsSecurityProxyRow)
    }
  } catch {}
}

function Write-WindowsSecurityReplacementShortcut {
  param(
    [Parameter(Mandatory=$true)][string]$DestRoot,
    [Parameter(Mandatory=$true)][string]$LinkName,
    [ValidateSet('Root','ShellAppsReplacements','WinSecFolder')][string]$Placement = 'ShellAppsReplacements',
    [string]$BackupRoot = $null
  )

  $spec = Get-WindowsSecurityLaunchSpec

  $folder = $DestRoot
  switch ($Placement) {
    'Root' { $folder = $DestRoot }
    'ShellAppsReplacements' { $folder = Join-Path $DestRoot 'ShellApps Replacements' }
    'WinSecFolder' { $folder = Join-Path $DestRoot 'Windows Security' }
  }
  if (-not (Test-Path -LiteralPath $folder)) { New-Item -ItemType Directory -Path $folder -Force | Out-Null }

  $safeName = ([string]$LinkName).Trim()
  if ([string]::IsNullOrWhiteSpace($safeName)) { $safeName = 'Windows Security' }
  if (-not $safeName.ToLowerInvariant().EndsWith('.lnk')) { $safeName = ($safeName + '.lnk') }

  $lnkPath = Join-Path $folder $safeName

  # Backup any existing shortcut we are about to overwrite.
  if ($BackupRoot -and (Test-Path -LiteralPath $lnkPath)) {
    try {
      $backupDir = Join-Path $BackupRoot 'WindowsSecurityReplacementBackup'
      New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
      $stamp = (Get-Date).ToString('yyyyMMdd_HHmmss')
      Copy-Item -LiteralPath $lnkPath -Destination (Join-Path $backupDir ("$safeName.prev.$stamp")) -Force -ErrorAction Stop
    } catch {}
  }

  $ws = New-Object -ComObject WScript.Shell
  $sc = $ws.CreateShortcut($lnkPath)
  $sc.TargetPath = [string]$spec.Target
  $sc.Arguments = [string]$spec.Args
  $sc.WorkingDirectory = $env:WINDIR
  $sc.IconLocation = [string]$spec.Icon
  $sc.Description = 'Windows Security'
  $sc.Save()

  # Try to set AUMID so Start Menu can de-duplicate the built-in entry and prefer this shortcut (safe, reversible).
  try { [void](Set-ShortcutAppUserModelId -LnkPath $lnkPath -AppUserModelId 'Microsoft.Windows.SecHealthUI_cw5n1h2txyewy!SecHealthUI') } catch {}

  try { Invoke-StartMenuRefresh -TouchedFolder $folder } catch {}

  return $lnkPath
}

function Write-AppsFolderEditableShortcut {
  param(
    [Parameter(Mandatory=$true)][string]$DestRoot,
    [Parameter(Mandatory=$true)][string]$LinkName,
    [Parameter(Mandatory=$true)][string]$AppId,
    [string]$BackupRoot = $null
  )

  if (-not (Test-Path -LiteralPath $DestRoot)) { New-Item -ItemType Directory -Path $DestRoot -Force | Out-Null }

  $base = ([string]$LinkName).Trim()
  if ([string]::IsNullOrWhiteSpace($base)) { $base = $AppId }
  $fileName = ($base + '.lnk')
  if (-not (Test-ValidFileName -Name $fileName)) { $fileName = ('AppsFolder Item.lnk') }

  $lnkPath = Join-Path $DestRoot $fileName

  if ($BackupRoot -and (Test-Path -LiteralPath $lnkPath)) {
    try {
      $backupDir = Join-Path $BackupRoot 'AppsFolderEditableBackup'
      New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
      $stamp = (Get-Date).ToString('yyyyMMdd_HHmmss')
      Copy-Item -LiteralPath $lnkPath -Destination (Join-Path $backupDir ("$fileName.prev.$stamp")) -Force -ErrorAction Stop
    } catch {}
  }

  $explorer = Join-Path $env:WINDIR 'explorer.exe'
  $args = ('shell:AppsFolder\' + $AppId)

  $iconRes = ''
  $forceSettingsIcon = $false
  $forceOutlookIcon = $false
  $forceWinBackupIcon = $false
  $forceEdgeIcon = $false
  try {
    if ([string]$AppId -match '(?i)immersivecontrolpanel') {
      $setIco = Get-SettingsSystemIconLocation
      if (-not [string]::IsNullOrWhiteSpace($setIco)) {
        $iconRes = [string]$setIco
        $forceSettingsIcon = $true
      }
    }
    elseif (Test-IsEdgeAppId -AppId ([string]$AppId)) {
      $edIco = Get-EdgeSystemIconLocation
      if (-not [string]::IsNullOrWhiteSpace($edIco)) {
        $iconRes = [string]$edIco
        $forceEdgeIcon = $true
      }
    }
    elseif ([string]$AppId -match '(?i)microsoft\.outlookforwindows') {
      $outIco = Get-OutlookSystemIconLocation
      if (-not [string]::IsNullOrWhiteSpace($outIco)) {
        $iconRes = [string]$outIco
        $forceOutlookIcon = $true
      }
    }
    elseif ([string]$AppId -match '(?i)windowsbackup') {
      $wbIco = Get-WindowsBackupIconLocation
      if (-not [string]::IsNullOrWhiteSpace($wbIco)) {
        $iconRes = [string]$wbIco
        $forceWinBackupIcon = $true
      }
    }
  } catch {}
  try {
    if (-not $forceSettingsIcon -and -not $forceEdgeIcon -and -not $forceOutlookIcon -and -not $forceWinBackupIcon) {
      $m = Get-AppsFolderInfoMapCached -AppIds @($AppId) -MaxAgeSeconds 120
      if ($m -and $m.ContainsKey($AppId)) { $iconRes = [string]$m[$AppId].IconResource }
    }
  } catch {}

  $ws = New-Object -ComObject WScript.Shell
  $sc = $ws.CreateShortcut($lnkPath)
  $sc.TargetPath = $explorer
  $sc.Arguments  = $args
  $sc.WorkingDirectory = $env:WINDIR

  $parsed = $null
  try { $parsed = Parse-IconLocationString -IconLocation $iconRes } catch { $parsed = $null }
  if ($parsed -and -not [string]::IsNullOrWhiteSpace([string]$parsed.IconPath) -and (($forceSettingsIcon -or $forceEdgeIcon -or $forceOutlookIcon -or $forceWinBackupIcon) -or (Test-Path -LiteralPath $parsed.IconPath))) {
    $sc.IconLocation = ("{0},{1}" -f [string]$parsed.IconPath, [int]$parsed.IconIndex)
  } else {
    $imageres = Join-Path $env:WINDIR 'System32\imageres.dll'
    $sc.IconLocation = ("{0},2" -f $imageres)
  }
  $sc.Description = $base
  $sc.Save()

  # Best-effort: encourage Start Menu to prefer this filesystem shortcut.
  try { [void](Set-ShortcutAppUserModelId -LnkPath $lnkPath -AppUserModelId $AppId) } catch {}
  if (-not [string]::IsNullOrWhiteSpace($iconRes)) {
    try { [void](Set-ShortcutAppUserModelStringProperty -LnkPath $lnkPath -Pid 3 -Value $iconRes) } catch {}
  }

  # Final guardrail for Edge: keep icon pinned to msedge.exe,0.
  try { if (Test-IsEdgeAppId -AppId ([string]$AppId)) { [void](Ensure-EdgeIconOnShortcut -LnkPath $lnkPath) } } catch {}
  try { Invoke-StartMenuRefresh -TouchedFolder $DestRoot } catch {}
  return $lnkPath
}

function New-AppsFolderDisplayProxyRow {
  param(
    [Parameter(Mandatory=$true)][string]$AppId,
    [Parameter(Mandatory=$true)][string]$DisplayName,
    [string]$ProxyKind = 'AppsFolder'
  )

  $info = $null
  try {
    $m = Get-AppsFolderInfoMapCached -AppIds @($AppId) -MaxAgeSeconds 120
    if ($m -and $m.ContainsKey($AppId)) { $info = $m[$AppId] }
  } catch { $info = $null }

  $img = $null
  $settingsIconApplied = $false
  $outlookIconApplied = $false
  $windowsBackupIconApplied = $false
  if ([string]$ProxyKind -eq 'Settings') {
    try {
      $setLoc = Get-SettingsSystemIconLocation
      if (-not [string]::IsNullOrWhiteSpace($setLoc)) {
        $parsedSet = Parse-IconLocationString -IconLocation $setLoc
        if ($parsedSet -and (Test-Path -LiteralPath $parsedSet.IconPath)) {
          $img = Get-ImageSourceFromIcon -IconPath $parsedSet.IconPath -IconIndex ([int]$parsedSet.IconIndex) -FallbackExePath $parsedSet.IconPath
          if ($img) { $settingsIconApplied = $true }
        }
      }
    } catch {}
  }
  elseif ([string]$ProxyKind -eq 'Outlook') {
    try {
      $outLoc = Get-OutlookSystemIconLocation
      if (-not [string]::IsNullOrWhiteSpace($outLoc)) {
        $parsedOut = Parse-IconLocationString -IconLocation $outLoc
        if ($parsedOut -and -not [string]::IsNullOrWhiteSpace([string]$parsedOut.IconPath)) {
          $img = Get-ImageSourceFromIcon -IconPath $parsedOut.IconPath -IconIndex ([int]$parsedOut.IconIndex) -FallbackExePath $parsedOut.IconPath
          if ($img) { $outlookIconApplied = $true }
        }
      }
    } catch {}
  }
  elseif ([string]$ProxyKind -eq 'WindowsBackup') {
    try {
      $wbLoc = Get-WindowsBackupIconLocation
      if (-not [string]::IsNullOrWhiteSpace($wbLoc)) {
        $parsedWb = Parse-IconLocationString -IconLocation $wbLoc
        if ($parsedWb -and -not [string]::IsNullOrWhiteSpace([string]$parsedWb.IconPath)) {
          $img = Get-ImageSourceFromIcon -IconPath $parsedWb.IconPath -IconIndex ([int]$parsedWb.IconIndex) -FallbackExePath $parsedWb.IconPath
          if ($img) { $windowsBackupIconApplied = $true }
        }
      }
    } catch {}
  }
  try {
    if (-not $settingsIconApplied -and -not $outlookIconApplied -and -not $windowsBackupIconApplied) {
      # Reuse the same icon logic as the ShellApp proxy row builder.
      $tmp = New-AppsFolderProxyRow -AppId $AppId -FallbackName $DisplayName -Info $info
      if ($tmp -and $tmp.Icon) { $img = $tmp.Icon }
    }
  } catch { $img = $null }

  if (-not $img) {
    try { $img = Get-GenericAppIconImageSource } catch { $img = $null }
  }

  return [pscustomobject]@{
    Id           = [guid]::NewGuid().ToString()
    Selected     = $false
    Action       = 'None'
    PendingLabel = ''

    OriginalName = $DisplayName
    Name         = $DisplayName

    # IMPORTANT: Do not use Type=ShellApp in the Visual grid (user-requested global suppression).
    Type         = 'Shortcut'
    Scope        = 'AppsFolderDisplayProxy'

    Target       = (Join-Path $env:WINDIR 'explorer.exe')
    Arguments    = ('shell:AppsFolder\' + $AppId)
    Path         = ('shell:AppsFolder\' + $AppId)
    OriginalPath = ('shell:AppsFolder\' + $AppId)

    Icon         = $img
    RowKind      = 'Item'

    # Treated like a ShellApp/AppsFolder row for pending + Apply logic, but displayed as a normal shortcut row.
    IsAppsFolderProxy        = $true
    IsAppsFolderDisplayProxy = $true
    AppsFolderId             = $AppId
    AppsFolderProxyKind      = $ProxyKind
    IsSettingsProxy          = ([string]$ProxyKind -eq 'Settings')
    IsOutlookProxy           = ([string]$ProxyKind -eq 'Outlook')
    EditBlockedReason        = 'AppsFolder entry. This row is a display proxy; actions are handled as special Apply steps (like Windows Security).'
  }
}

function Ensure-SettingsProxyRow {
  try {
    $script:SettingsProxyRow = $null
    $apps = Get-StartAppsCached -MaxAgeSeconds 30
    if (-not $apps) { return }

    $match = $null
    foreach ($a in @($apps)) {
      if (-not $a) { continue }
      $nm = ''
      try { $nm = [string]$a.Name } catch {}
      if ($nm -and $nm -eq 'Settings') { $match = $a; break }
    }
    if (-not $match) { return }

    $appid = ''
    try { $appid = [string]$match.AppID } catch {}
    if ([string]::IsNullOrWhiteSpace($appid)) { return }

    # If an existing shortcut already represents Settings, no proxy needed.
    $has = $false
    try {
      foreach ($it in @($script:StartupInventory)) {
        if (-not $it) { continue }
        if ([string](Get-PropString -Obj $it -Names @('Type') -Fallback '') -ne 'Shortcut') { continue }
        try { if (Test-IsSettingsAliasShortcutRow -Row $it) { $has = $true; break } } catch {}

        $args = [string](Get-PropString -Obj $it -Names @('Arguments') -Fallback '')
        if ($args -and ($args.ToLowerInvariant() -like ('*shell:appsfolder*' + $appid.Trim().ToLowerInvariant() + '*'))) { $has = $true; break }
      }
    } catch {}
    if ($has) { return }

    $script:SettingsProxyRow = New-AppsFolderDisplayProxyRow -AppId $appid -DisplayName 'Settings' -ProxyKind 'Settings'
  } catch {}
}

function Ensure-OutlookProxyRow {
  try {
    $script:OutlookProxyRow = $null
    $apps = Get-StartAppsCached -MaxAgeSeconds 30
    if (-not $apps) { return }

    $match = $null
    foreach ($a in @($apps)) {
      if (-not $a) { continue }
      $nm = ''
      try { $nm = [string]$a.Name } catch {}
      if ($nm -and ($nm -eq 'Outlook' -or $nm -like 'Outlook*')) { $match = $a; break }
    }
    if (-not $match) { return }

    $appid = ''
    try { $appid = [string]$match.AppID } catch {}
    if ([string]::IsNullOrWhiteSpace($appid)) { return }

    # If an editable shortcut already exists that launches this AppsFolder target, no proxy needed.
    $has = $false
    try {
      foreach ($it in @($script:StartupInventory)) {
        if (-not $it) { continue }
        if ([string](Get-PropString -Obj $it -Names @('Type') -Fallback '') -ne 'Shortcut') { continue }
        $args = [string](Get-PropString -Obj $it -Names @('Arguments') -Fallback '')
        if ($args -and ($args.ToLowerInvariant() -like ('*shell:appsfolder*' + $appid.Trim().ToLowerInvariant() + '*'))) { $has = $true; break }
      }
    } catch {}
    if ($has) { return }

    $script:OutlookProxyRow = New-AppsFolderDisplayProxyRow -AppId $appid -DisplayName 'Outlook' -ProxyKind 'Outlook'
  } catch {}
}

function Ensure-WindowsBackupProxyRow {
  try {
    $script:WindowsBackupProxyRow = $null
    $apps = Get-StartAppsCached -MaxAgeSeconds 30
    if (-not $apps) { return }

    $match = $null
    foreach ($a in @($apps)) {
      if (-not $a) { continue }
      $nm = ''
      try { $nm = [string]$a.Name } catch {}
      if ($nm -and ($nm -eq 'Windows Backup')) { $match = $a; break }
    }
    if (-not $match) { return }

    $appid = ''
    try { $appid = [string]$match.AppID } catch {}
    if ([string]::IsNullOrWhiteSpace($appid)) { return }

    $row = New-AppsFolderDisplayProxyRow -AppId $appid -DisplayName 'Windows Backup' -ProxyKind 'WindowsBackup'
    if ($row) {
      try { Set-PropSafeGlobal -Obj $row -Name 'IsWindowsBackupProxy' -Value $true } catch {}
      try { Set-PropSafeGlobal -Obj $row -Name 'WindowsBackupPlannedPackageName' -Value '' } catch {}
    }
    $script:WindowsBackupProxyRow = $row
  } catch {}
}

function Get-RootDisplayName([string]$scope) {
  switch ($scope) {
    "AllUsers"       { "All Users" }
    "CurrentUser"    { "Current User" }
    "DefaultProfile" { "Default Profile" }
    default { $scope }
  }
}


# ==============================================================================
# Meta rename expansion helpers
# ==============================================================================
function Get-RelPathFromScopeRoots {
  param(
    [Parameter(Mandatory=$true)][string]$Path,
    [Parameter(Mandatory=$true)][hashtable]$ScopeRoots
  )
  foreach ($kv in $ScopeRoots.GetEnumerator()) {
    $root = [string]$kv.Value
    if ([string]::IsNullOrWhiteSpace($root)) { continue }
    $rootN = $root.TrimEnd('\')
    if ($Path.StartsWith($rootN, [System.StringComparison]::OrdinalIgnoreCase)) {
      $rel = $Path.Substring($rootN.Length).TrimStart('\')
      return ,@([string]$kv.Key, $rel)  # (Scope, RelPath)
    }
  }
  return $null
}

function Expand-MetaRenameTargets {
  param(
    [Parameter(Mandatory=$true)][object]$Row,
    [Parameter(Mandatory=$true)][hashtable]$ScopeRoots
  )
  $src = Get-PropString -Obj $Row -Names @('OriginalPath','Path','FullPath') -Fallback ''
  if ([string]::IsNullOrWhiteSpace($src)) { return @() }

  $match = Get-RelPathFromScopeRoots -Path $src -ScopeRoots $ScopeRoots
  if (-not $match) { return @() }

  $rel = [string]$match[1]
  $relDir  = Split-Path $rel -Parent
  $leaf    = Split-Path $rel -Leaf

  $targets = New-Object 'System.Collections.Generic.List[object]'
  foreach ($kv in $ScopeRoots.GetEnumerator()) {
    $scope = [string]$kv.Key
    $root  = [string]$kv.Value
    if ([string]::IsNullOrWhiteSpace($root)) { continue }

    $candRel = if ([string]::IsNullOrWhiteSpace($relDir)) { $leaf } else { Join-Path $relDir $leaf }
    $cand = Join-Path $root $candRel

    if (Test-Path -LiteralPath $cand) {
      $targets.Add([pscustomobject]@{
        Action       = 'Rename'
        Scope        = $scope
        OriginalPath = $cand
        Path         = $cand
        OriginalName = (Get-PropString -Obj $Row -Names @('OriginalName','Name') -Fallback '')
        Name         = (Get-PropString -Obj $Row -Names @('Name') -Fallback '')
      }) | Out-Null
    }
  }
  return $targets.ToArray()
}

# ==============================================================================
# Inventory loader
# ==============================================================================
$script:InventoryCommonPrograms  = Join-Path $env:ProgramData "Microsoft\Windows\Start Menu\Programs"
$script:InventoryUserPrograms    = Join-Path $env:AppData     "Microsoft\Windows\Start Menu\Programs"
$script:InventoryDefaultPrograms = "C:\Users\Default\AppData\Roaming\Microsoft\Windows\Start Menu\Programs"
if (-not (Test-Path variable:script:InventoryWshShellCom)) { $script:InventoryWshShellCom = $null }
if (-not (Test-Path variable:script:InventoryShellAppCom)) { $script:InventoryShellAppCom = $null }
if (-not (Test-Path variable:script:InventoryShellNsCache)) { $script:InventoryShellNsCache = @{} }
if (-not (Test-Path variable:script:InventoryDefaultBrowserIconSpecAt)) { $script:InventoryDefaultBrowserIconSpecAt = [datetime]::MinValue }
if (-not (Test-Path variable:script:InventoryDefaultBrowserIconSpec)) { $script:InventoryDefaultBrowserIconSpec = $null }

function Inventory-GetWshShellCom {
  if ($null -eq $script:InventoryWshShellCom) {
    $script:InventoryWshShellCom = New-Object -ComObject WScript.Shell
  }
  return $script:InventoryWshShellCom
}

function Inventory-GetShellAppCom {
  if ($null -eq $script:InventoryShellAppCom) {
    $script:InventoryShellAppCom = New-Object -ComObject Shell.Application
  }
  return $script:InventoryShellAppCom
}

function Inventory-GetShellDisplayNameForFile {
  param([Parameter(Mandatory=$true)][string]$FilePath)
  try {
    if (-not (Test-Path -LiteralPath $FilePath)) { return $null }
    $dir  = Split-Path -Path $FilePath -Parent
    $leaf = Split-Path -Path $FilePath -Leaf
    if ([string]::IsNullOrWhiteSpace($dir) -or [string]::IsNullOrWhiteSpace($leaf)) { return $null }
    $key = $dir.ToLowerInvariant()
    $ns = $null
    if ($script:InventoryShellNsCache.ContainsKey($key)) {
      $ns = $script:InventoryShellNsCache[$key]
    } else {
      $sh = Inventory-GetShellAppCom
      $ns = $sh.NameSpace($dir)
      $script:InventoryShellNsCache[$key] = $ns
    }
    if (-not $ns) { return $null }
    $it = $ns.ParseName($leaf)
    if (-not $it) { return $null }
    $nm = $null
    try { $nm = [string]$it.Name } catch { $nm = $null }
    if ([string]::IsNullOrWhiteSpace($nm)) { return $null }
    return $nm
  } catch {
    return $null
  }
}

function Inventory-NormalizeIconPath {
  param([string]$Path)
  if ([string]::IsNullOrWhiteSpace($Path)) { return $null }
  $p = [string]$Path
  $p = $p.Trim([char[]]@(0x20,0x09,0x0D,0x0A))
  if ($p.StartsWith('@{') -and $p.EndsWith('}')) { $p = $p.Substring(2, $p.Length - 3) }
  if ($p.StartsWith('@')) { $p = $p.Substring(1) }
  $p = $p.Trim('"')
  $p = [Environment]::ExpandEnvironmentVariables($p)
  return $p
}

function Inventory-GetRegistryDefaultValue {
  param([Parameter(Mandatory=$true)][string]$RegistryPath)
  try {
    if (-not (Test-Path -LiteralPath $RegistryPath)) { return $null }
    $k = Get-Item -LiteralPath $RegistryPath -ErrorAction SilentlyContinue
    if (-not $k) { return $null }
    return [string]$k.GetValue('')
  } catch {
    return $null
  }
}

function Inventory-ParseIconLocationValue {
  param([string]$Value)
  $raw = [string]$Value
  if ([string]::IsNullOrWhiteSpace($raw)) { return $null }
  $raw = $raw.Trim()
  $path = $raw
  $idx = 0
  $lastComma = $raw.LastIndexOf(',')
  if ($lastComma -gt 0 -and $lastComma -lt ($raw.Length - 1)) {
    $tail = $raw.Substring($lastComma + 1).Trim()
    $tmp = 0
    if ([int]::TryParse($tail, [ref]$tmp)) {
      $path = $raw.Substring(0, $lastComma).Trim()
      $idx = $tmp
    }
  }
  $path = Inventory-NormalizeIconPath $path
  if ([string]::IsNullOrWhiteSpace($path)) { return $null }
  return [pscustomobject]@{
    IconPath  = $path
    IconIndex = $idx
  }
}

function Inventory-ResolveIconPathForShortcut {
  param(
    [string]$ShortcutPath,
    [string]$IconPathRaw
  )
  try {
    $raw = [string]$IconPathRaw
    if ([string]::IsNullOrWhiteSpace($raw)) { return '' }
    $expanded = Inventory-NormalizeIconPath $raw
    if ([string]::IsNullOrWhiteSpace($expanded)) { return '' }
    # Absolute / rooted path case.
    try {
      if ([System.IO.Path]::IsPathRooted([string]$expanded)) {
        $abs = Normalize-Path ([string]$expanded)
        if (-not [string]::IsNullOrWhiteSpace($abs)) { return $abs }
        return [string]$expanded
      }
    } catch {}
    # Relative path case: resolve against shortcut directory.
    $baseDir = ''
    try { $baseDir = Split-Path -Path ([string]$ShortcutPath) -Parent } catch { $baseDir = '' }
    if (-not [string]::IsNullOrWhiteSpace($baseDir)) {
      try {
        $cand = Normalize-Path (Join-Path $baseDir ([string]$expanded))
        if (-not [string]::IsNullOrWhiteSpace($cand)) { return $cand }
      } catch {}
      try {
        $cand2 = Join-Path $baseDir ([string]$expanded)
        if (-not [string]::IsNullOrWhiteSpace($cand2)) { return [string]$cand2 }
      } catch {}
    }
    return [string]$expanded
  } catch {
    return ''
  }
}

function Inventory-ParseExePathFromCommand {
  param([string]$Command)
  try {
    $cmd = [string]$Command
    if ([string]::IsNullOrWhiteSpace($cmd)) { return $null }
    $cmd = $cmd.Trim()
    if ($cmd.StartsWith('"')) {
      $end = $cmd.IndexOf('"', 1)
      if ($end -gt 1) {
        $exe = $cmd.Substring(1, $end - 1)
        $exe = Inventory-NormalizeIconPath $exe
        if (-not [string]::IsNullOrWhiteSpace($exe)) { return $exe }
      }
    }
    $token = ($cmd -split '\s+')[0]
    $token = Inventory-NormalizeIconPath $token
    if (-not [string]::IsNullOrWhiteSpace($token)) { return $token }
  } catch {}
  return $null
}

function Inventory-GetDefaultBrowserIconSpec {
  param([int]$MaxAgeSeconds = 120)
  try {
    $now = Get-Date
    if ($script:InventoryDefaultBrowserIconSpecAt -and (($now - $script:InventoryDefaultBrowserIconSpecAt).TotalSeconds -lt $MaxAgeSeconds)) {
      return $script:InventoryDefaultBrowserIconSpec
    }
    $progId = $null
    foreach ($assoc in @('https','http')) {
      $ucPath = "Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\Shell\Associations\UrlAssociations\$assoc\UserChoice"
      try {
        $tmp = [string](Get-ItemPropertyValue -LiteralPath $ucPath -Name 'ProgId' -ErrorAction SilentlyContinue)
        if (-not [string]::IsNullOrWhiteSpace($tmp)) { $progId = $tmp; break }
      } catch {}
    }
    if (-not [string]::IsNullOrWhiteSpace($progId)) {
      foreach ($root in @('Registry::HKEY_CURRENT_USER\Software\Classes','Registry::HKEY_CLASSES_ROOT')) {
        $iconRaw = Inventory-GetRegistryDefaultValue -RegistryPath ("$root\$progId\DefaultIcon")
        $parsed = Inventory-ParseIconLocationValue -Value $iconRaw
        if ($parsed -and -not [string]::IsNullOrWhiteSpace([string]$parsed.IconPath) -and (Test-Path -LiteralPath ([string]$parsed.IconPath))) {
          $script:InventoryDefaultBrowserIconSpecAt = $now
          $script:InventoryDefaultBrowserIconSpec = $parsed
          return $parsed
        }
      }
      foreach ($root in @('Registry::HKEY_CURRENT_USER\Software\Classes','Registry::HKEY_CLASSES_ROOT')) {
        $cmdRaw = Inventory-GetRegistryDefaultValue -RegistryPath ("$root\$progId\shell\open\command")
        $exe = Inventory-ParseExePathFromCommand -Command $cmdRaw
        if (-not [string]::IsNullOrWhiteSpace($exe) -and (Test-Path -LiteralPath $exe)) {
          $spec = [pscustomobject]@{ IconPath = $exe; IconIndex = 0 }
          $script:InventoryDefaultBrowserIconSpecAt = $now
          $script:InventoryDefaultBrowserIconSpec = $spec
          return $spec
        }
      }
    }
    foreach ($edge in @(
      (Join-Path ${env:ProgramFiles(x86)} 'Microsoft\Edge\Application\msedge.exe'),
      (Join-Path $env:ProgramFiles 'Microsoft\Edge\Application\msedge.exe')
    )) {
      if (-not [string]::IsNullOrWhiteSpace([string]$edge) -and (Test-Path -LiteralPath $edge)) {
        $spec = [pscustomobject]@{ IconPath = [string]$edge; IconIndex = 0 }
        $script:InventoryDefaultBrowserIconSpecAt = $now
        $script:InventoryDefaultBrowserIconSpec = $spec
        return $spec
      }
    }
    $script:InventoryDefaultBrowserIconSpecAt = $now
    $script:InventoryDefaultBrowserIconSpec = $null
    return $null
  } catch {
    return $null
  }
}

function Inventory-GetLnkInfo {
  param([Parameter(Mandatory=$true)] [string]$LnkPath)
  try {
    $lnkPathResolved = $null
    try {
      $lnkPathResolved = Resolve-ExistingPathLenient -Path ([string]$LnkPath)
      if ([string]::IsNullOrWhiteSpace($lnkPathResolved)) { $lnkPathResolved = Normalize-Path ([string]$LnkPath) }
      if ([string]::IsNullOrWhiteSpace($lnkPathResolved)) { $lnkPathResolved = [string]$LnkPath }
    } catch { $lnkPathResolved = [string]$LnkPath }
    # Prefer native Unicode shell-link parsing first (handles symbol/emoji paths robustly).
    $native = $null
    try { $native = Inventory-GetLnkInfoNative -LnkPath $lnkPathResolved } catch { $native = $null }
    if ($native) { return $native }

    # Fallback: WScript.Shell for environments where native COM path read fails.
    $wsh = Inventory-GetWshShellCom
    $sc  = $wsh.CreateShortcut($lnkPathResolved)
    $iconPath  = $null
    $iconIndex = 0
    $parsedIcon = $null
    try { $parsedIcon = Inventory-ParseIconLocationValue -Value ([string]$sc.IconLocation) } catch { $parsedIcon = $null }
    if ($parsedIcon) {
      try { $iconPath = [string]$parsedIcon.IconPath } catch { $iconPath = $null }
      try { $iconIndex = [int]$parsedIcon.IconIndex } catch { $iconIndex = 0 }
      try { $iconPath = Inventory-ResolveIconPathForShortcut -ShortcutPath $lnkPathResolved -IconPathRaw ([string]$iconPath) } catch {}
    }
    if ([string]::IsNullOrWhiteSpace($iconPath) -or -not (Test-Path -LiteralPath $iconPath)) {
      $iconPath  = $lnkPathResolved
      $iconIndex = 0
    }
    [pscustomobject]@{
      TargetPath = $sc.TargetPath
      Arguments  = $sc.Arguments
      IconPath   = $iconPath
      IconIndex  = $iconIndex
    }
  } catch {
    return $null
  }
}

function Inventory-GetLnkInfoNative {
  param([Parameter(Mandatory=$true)] [string]$LnkPath)
  try {
    $lp = Normalize-Path ([string]$LnkPath)
    if ([string]::IsNullOrWhiteSpace($lp)) { return $null }
    $lpResolved = Resolve-ExistingPathLenient -Path $lp
    if ([string]::IsNullOrWhiteSpace($lpResolved)) { $lpResolved = $lp }
    if ([string]::IsNullOrWhiteSpace($lpResolved) -or -not (Test-Path -LiteralPath $lpResolved -PathType Leaf)) { return $null }

    Ensure-ShellLinkInteropTypes

    $link = New-Object StartMenuTool.ShellLink
    $pf = [StartMenuTool.IPersistFile]$link
    # STGM_READ = 0
    [void]$pf.Load([string]$lpResolved, 0)
    $sl = [StartMenuTool.IShellLinkW]$link

    $sbTarget = New-Object System.Text.StringBuilder 32767
    $sbArgs   = New-Object System.Text.StringBuilder 8192
    $sbIcon   = New-Object System.Text.StringBuilder 32767
    $iconIdx  = 0

    try { [void]$sl.GetPath($sbTarget, $sbTarget.Capacity, [IntPtr]::Zero, 0) } catch {}
    try { [void]$sl.GetArguments($sbArgs, $sbArgs.Capacity) } catch {}
    try { [void]$sl.GetIconLocation($sbIcon, $sbIcon.Capacity, [ref]$iconIdx) } catch {}

    $target = ''
    $args = ''
    $iconPath = ''
    try { $target = Normalize-Path ([string]$sbTarget.ToString()) } catch { $target = '' }
    try { $args   = [string]$sbArgs.ToString() } catch { $args = '' }
    try {
      if (-not [string]::IsNullOrWhiteSpace($target)) {
        $targetResolved = Resolve-ExistingPathLenient -Path $target
        if (-not [string]::IsNullOrWhiteSpace($targetResolved)) { $target = $targetResolved }
      }
    } catch {}
    $parsedIcon = $null
    try { $parsedIcon = Inventory-ParseIconLocationValue -Value ([string]$sbIcon.ToString()) } catch { $parsedIcon = $null }
    if ($parsedIcon) {
      try { $iconPath = Inventory-ResolveIconPathForShortcut -ShortcutPath $lpResolved -IconPathRaw ([string]$parsedIcon.IconPath) } catch { $iconPath = '' }
      try { $iconIdx = [int]$parsedIcon.IconIndex } catch { $iconIdx = 0 }
    }
    if (-not [string]::IsNullOrWhiteSpace($iconPath)) {
      try {
        $iconResolved = Resolve-ExistingPathLenient -Path $iconPath
        if (-not [string]::IsNullOrWhiteSpace($iconResolved)) { $iconPath = $iconResolved }
      } catch {}
    }
    if ([string]::IsNullOrWhiteSpace($iconPath) -or -not (Test-Path -LiteralPath $iconPath)) {
      $iconPath = [string]$lpResolved
      $iconIdx = 0
    }

    # If native GetPath/GetIconLocation yielded unresolved values (common with some
    # symbol/emoji-heavy targets), pull a WScript fallback while keeping native-first logic.
    $needWshFallback = $false
    try {
      if ([string]::IsNullOrWhiteSpace($target)) { $needWshFallback = $true }
      elseif (-not ($target.StartsWith('shell:', [System.StringComparison]::OrdinalIgnoreCase)) -and -not (Test-Path -LiteralPath $target)) {
        $needWshFallback = $true
      }
    } catch {}
    if ($needWshFallback) {
      try {
        $wsh = Inventory-GetWshShellCom
        $scW = $wsh.CreateShortcut($lpResolved)
        $wTarget = ''
        $wArgs = ''
        $wIcon = ''
        try { $wTarget = Normalize-Path ([string]$scW.TargetPath) } catch { $wTarget = '' }
        try { $wArgs = [string]$scW.Arguments } catch { $wArgs = '' }
        try { $wIcon = [string]$scW.IconLocation } catch { $wIcon = '' }
        try {
          if (-not [string]::IsNullOrWhiteSpace($wTarget)) {
            $wTargetResolved = Resolve-ExistingPathLenient -Path $wTarget
            if (-not [string]::IsNullOrWhiteSpace($wTargetResolved)) { $wTarget = $wTargetResolved }
          }
        } catch {}
        if (-not [string]::IsNullOrWhiteSpace($wTarget)) { $target = $wTarget }
        if (-not [string]::IsNullOrWhiteSpace($wArgs)) { $args = $wArgs }
        if (-not [string]::IsNullOrWhiteSpace($wIcon)) {
          $wParsed = $null
          try { $wParsed = Inventory-ParseIconLocationValue -Value $wIcon } catch { $wParsed = $null }
          if ($wParsed) {
            $wIconPath = ''
            $wIconIndex = 0
            try { $wIconPath = Inventory-ResolveIconPathForShortcut -ShortcutPath $lpResolved -IconPathRaw ([string]$wParsed.IconPath) } catch { $wIconPath = '' }
            try { $wIconIndex = [int]$wParsed.IconIndex } catch { $wIconIndex = 0 }
            if (-not [string]::IsNullOrWhiteSpace($wIconPath)) {
              $wIconResolved = Resolve-ExistingPathLenient -Path $wIconPath
              if (-not [string]::IsNullOrWhiteSpace($wIconResolved)) { $wIconPath = $wIconResolved }
              if (Test-Path -LiteralPath $wIconPath) {
                $iconPath = $wIconPath
                $iconIdx = $wIconIndex
              }
            }
          }
        }
      } catch {}
    }

    return [pscustomobject]@{
      TargetPath = [string]$target
      Arguments  = [string]$args
      IconPath   = [string]$iconPath
      IconIndex  = [int]$iconIdx
    }
  } catch {
    return $null
  }
}

function Inventory-GetUrlInfo {
  param([Parameter(Mandatory=$true)] [string]$UrlPath)
  $content = Get-Content -LiteralPath $UrlPath -ErrorAction SilentlyContinue
  $urlLine = $content | Where-Object { $_ -match '^\s*URL\s*=' } | Select-Object -First 1
  $url = if ($urlLine) { $urlLine -replace '^\s*URL\s*=\s*','' } else { $null }
  $iconFileLine = $content | Where-Object { $_ -match '^\s*IconFile\s*=' } | Select-Object -First 1
  $iconFile = if ($iconFileLine) { $iconFileLine -replace '^\s*IconFile\s*=\s*','' } else { $null }
  $iconFile = Inventory-NormalizeIconPath $iconFile
  $iconIndex = 0
  $idxLine = $content | Where-Object { $_ -match '^\s*IconIndex\s*=' } | Select-Object -First 1
  if ($idxLine) {
    $tmp = 0
    [void][int]::TryParse((($idxLine -replace '^\s*IconIndex\s*=\s*','').Trim()), [ref]$tmp)
    $iconIndex = $tmp
  }
  try {
    $spec = Inventory-GetDefaultBrowserIconSpec -MaxAgeSeconds 120
    if ($spec -and -not [string]::IsNullOrWhiteSpace([string]$spec.IconPath)) {
      $iconFile = [string]$spec.IconPath
      $iconIndex = [int]$spec.IconIndex
    }
  } catch {}
  [pscustomobject]@{
    Url       = $url
    IconPath  = $iconFile
    IconIndex = $iconIndex
  }
}

function Inventory-GetFileIconImageSafe {
  param([Parameter(Mandatory=$true)][string]$Path)
  try {
    $p = Normalize-Path ([string]$Path)
    if ([string]::IsNullOrWhiteSpace($p)) { return $null }
    $pResolved = Resolve-ExistingPathLenient -Path $p
    if ([string]::IsNullOrWhiteSpace($pResolved)) { $pResolved = $p }
    if ([string]::IsNullOrWhiteSpace($pResolved) -or -not (Test-Path -LiteralPath $pResolved -PathType Leaf)) { return $null }

    $img = $null
    try { $img = Get-ImageSourceFromShellFileInfoPath -Path $pResolved -Size Small } catch { $img = $null }
    if (-not $img) {
      try { $img = Get-ImageSourceFromAssociatedIconPath -Path $pResolved } catch { $img = $null }
    }
    if (-not $img) {
      try { $img = Get-ImageSourceFromIcon -IconPath $pResolved -IconIndex 0 -FallbackExePath $pResolved } catch { $img = $null }
    }
    return $img
  } catch {
    return $null
  }
}

function Inventory-GetShortcutDisplayIconImage {
  param(
    [string]$LnkPath,
    [string]$IconPath,
    [int]$IconIndex = 0,
    [string]$TargetPath
  )
  try {
    $img = $null
    $ip = Normalize-Path ([string]$IconPath)
    $lp = Normalize-Path ([string]$LnkPath)
    $tp = Normalize-Path ([string]$TargetPath)

    if (-not [string]::IsNullOrWhiteSpace($ip)) {
      try { $img = Get-ImageSourceFromIcon -IconPath $ip -IconIndex ([int]$IconIndex) -FallbackExePath $tp } catch { $img = $null }
      if (-not $img) {
        try { $img = Get-ImageSourceFromAssociatedIconPath -Path $ip } catch { $img = $null }
      }
    }
    if (-not $img -and -not [string]::IsNullOrWhiteSpace($tp)) {
      try { $img = Get-ImageSourceFromIcon -IconPath $tp -IconIndex 0 -FallbackExePath $tp } catch { $img = $null }
      if (-not $img) {
        try { $img = Get-ImageSourceFromAssociatedIconPath -Path $tp } catch { $img = $null }
      }
    }
    if (-not $img -and -not [string]::IsNullOrWhiteSpace($lp)) {
      # Read icon resource from the .lnk itself; do NOT query shell file icon for .lnk to avoid arrow overlay.
      try { $img = Get-ImageSourceFromIcon -IconPath $lp -IconIndex 0 -FallbackExePath $tp } catch { $img = $null }
      if (-not $img) {
        try { $img = Get-ImageSourceFromShellParsingName -ParsingName $lp } catch { $img = $null }
      }
    }
    return $img
  } catch {
    return $null
  }
}

function Inventory-GetStartMenuItemsFromRoot {
  param(
    [Parameter(Mandatory=$true)] [string]$Root,
    [Parameter(Mandatory=$true)] [string]$Scope
  )
  if (-not (Test-Path $Root)) { return @() }
  $items = New-Object System.Collections.Generic.List[object]
  Get-ChildItem -LiteralPath $Root -Recurse -Filter *.lnk -ErrorAction SilentlyContinue | ForEach-Object {
    $lnk = Inventory-GetLnkInfo $_.FullName
    $target = $null
    $iconPath = $null
    $iconIndex = 0
    if ($lnk) {
      $target = $lnk.TargetPath
      $iconPath = $lnk.IconPath
      $iconIndex = $lnk.IconIndex
    }
    $iconImage = $null
    try {
      $iconImage = Inventory-GetShortcutDisplayIconImage `
        -LnkPath ([string]$_.FullName) `
        -IconPath ([string]$iconPath) `
        -IconIndex ([int]$iconIndex) `
        -TargetPath ([string]$target)
    } catch { $iconImage = $null }
    $dn = $null
    try { $dn = Inventory-GetShellDisplayNameForFile -FilePath $_.FullName } catch { $dn = $null }
    $name = if (-not [string]::IsNullOrWhiteSpace([string]$dn)) { [string]$dn } else { [IO.Path]::GetFileNameWithoutExtension($_.Name) }
    $items.Add([pscustomobject]@{
      Name      = $name
      Type      = "Shortcut"
      Scope     = $Scope
      Path      = $_.FullName
      Target    = $target
      Arguments = $(if($lnk){$lnk.Arguments}else{$null})
      IconPath  = $iconPath
      IconIndex = $iconIndex
      IconImage = $iconImage
    })
  }
  Get-ChildItem -LiteralPath $Root -Recurse -Filter *.url -ErrorAction SilentlyContinue | ForEach-Object {
    $u = Inventory-GetUrlInfo $_.FullName
    $target = $null
    $iconPath = $null
    $iconIndex = 0
    if ($u) {
      $target = $u.Url
      $iconPath = $u.IconPath
      $iconIndex = $u.IconIndex
    }
    $iconImage = $null
    try { $iconImage = Inventory-GetFileIconImageSafe -Path ([string]$_.FullName) } catch { $iconImage = $null }
    if (-not $iconImage -and -not [string]::IsNullOrWhiteSpace([string]$iconPath)) {
      try { $iconImage = Get-ImageSourceFromIcon -IconPath ([string]$iconPath) -IconIndex ([int]$iconIndex) -FallbackExePath ([string]$target) } catch { $iconImage = $null }
    }
    $dn = $null
    try { $dn = Inventory-GetShellDisplayNameForFile -FilePath $_.FullName } catch { $dn = $null }
    $name = if (-not [string]::IsNullOrWhiteSpace([string]$dn)) { [string]$dn } else { [IO.Path]::GetFileNameWithoutExtension($_.Name) }
    $items.Add([pscustomobject]@{
      Name      = $name
      Type      = "Url"
      Scope     = $Scope
      Path      = $_.FullName
      Target    = $target
      IconPath  = $iconPath
      IconIndex = $iconIndex
      IconImage = $iconImage
    })
  }
  $items
}

function Get-Inventory {
  param(
    [switch]$IncludeCurrentUser,
    [switch]$IncludeDefaultProfile
  )
  if (-not $PSBoundParameters.ContainsKey('IncludeCurrentUser') -and -not $PSBoundParameters.ContainsKey('IncludeDefaultProfile')) {
    $IncludeCurrentUser = $true
  }
  $result = New-Object System.Collections.Generic.List[object]
  $allUsersItems = @(Inventory-GetStartMenuItemsFromRoot -Root $script:InventoryCommonPrograms -Scope "AllUsers")
  if ($allUsersItems -and $allUsersItems.Count -gt 0) {
    $result.AddRange([object[]]$allUsersItems)
  }
  if ($IncludeCurrentUser) {
    $currentUserItems = @(Inventory-GetStartMenuItemsFromRoot -Root $script:InventoryUserPrograms -Scope "CurrentUser")
    if ($currentUserItems -and $currentUserItems.Count -gt 0) {
      $result.AddRange([object[]]$currentUserItems)
    }
  }
  if ($IncludeDefaultProfile) {
    $defaultProfileItems = @(Inventory-GetStartMenuItemsFromRoot -Root $script:InventoryDefaultPrograms -Scope "DefaultProfile")
    if ($defaultProfileItems -and $defaultProfileItems.Count -gt 0) {
      $result.AddRange([object[]]$defaultProfileItems)
    }
  }
  return $result.ToArray()
}

# ==============================================================================
# Model
# ==============================================================================
if (-not ([System.Management.Automation.PSTypeName]'FolderNode').Type) {
  Add-Type -TypeDefinition @"
using System.Collections.ObjectModel;

public class FolderNode {
  public string Name { get; set; }
  public string FullPath { get; set; }
  public string Scope { get; set; }
  public ObservableCollection<FolderNode> Children { get; set; }
  public ObservableCollection<object> Items { get; set; }
  public ObservableCollection<object> Folders { get; set; }
  public int TotalItemCount { get; set; }
  public string DisplayName { get; set; }

  public FolderNode(string name, string fullPath, string scope) {
    Name = name;
    FullPath = fullPath;
    Scope = scope;
    Children = new ObservableCollection<FolderNode>();
    Items = new ObservableCollection<object>();
    Folders = new ObservableCollection<object>();
    TotalItemCount = 0;
    DisplayName = name;
  }

  public override string ToString() {
    return DisplayName;
  }
}
"@
}


function Update-TreeCounts {
  param([FolderNode]$node)

  $total = 0
  if ($node.Items) { $total += $node.Items.Count }
  if ($node.Children) {
    foreach ($ch in $node.Children) { $total += (Update-TreeCounts -node $ch) }
  }

  $node.TotalItemCount = $total
  $node.DisplayName    = "{0} ({1})" -f $node.Name, $node.TotalItemCount
  return $total
}

function Build-Model {
  param([object[]]$inventoryItems)

  $script:VisualMergedRoot = $null
  $script:VisualCacheNodeMapRef = $null
  $script:ShortcutNameIndex = @{}

  $treeRoots = [System.Collections.ObjectModel.ObservableCollection[FolderNode]]::new()
  $nodeMap   = @{}

  $profilesRoot = [FolderNode]::new("Profiles", "", "Meta")
  [void]$treeRoots.Add($profilesRoot)
  $nodeMap["Meta|"] = $profilesRoot

  $visualRoot = [FolderNode]::new("Simulated Start Menu (default selection)", "::VISUAL::", "VisualMenu")
  [void]$treeRoots.Add($visualRoot)
  $nodeMap["VisualMenu|::VISUAL::"] = $visualRoot

  foreach ($kv in $scopeRoots.GetEnumerator()) {
    $scope    = $kv.Key
    $rootPath = ($kv.Value.TrimEnd('\'))
    if (-not (Test-Path -LiteralPath $rootPath)) { continue }

    $root = [FolderNode]::new((Get-RootDisplayName $scope), $rootPath, $scope)
    [void]$profilesRoot.Children.Add($root)
    $nodeMap["$scope|$rootPath"] = $root
  }

  if ($profilesRoot.Children.Count -eq 0) {
    throw "No Start Menu roots found. Checked: $($scopeRoots.Values -join '; ')"
  }

  function Ensure-FolderNode {
    param(
      [Parameter(Mandatory=$true)][string]$Scope,
      [Parameter(Mandatory=$true)][string]$FolderPath
    )

    $folderPath = $FolderPath.TrimEnd('\')
    $key = "$Scope|$folderPath"
    if ($nodeMap.ContainsKey($key)) { return $nodeMap[$key] }

    $parentPath = Split-Path -Path $folderPath -Parent
    if (-not $parentPath) { return $null }
    $parentPath = $parentPath.TrimEnd('\')

    $parentKey = "$Scope|$parentPath"
    if (-not $nodeMap.ContainsKey($parentKey)) {
      $null = Ensure-FolderNode -Scope $Scope -FolderPath $parentPath
    }
    if (-not $nodeMap.ContainsKey($parentKey)) { return $null }

    $name = Split-Path -Path $folderPath -Leaf
    $node = [FolderNode]::new($name, $folderPath, $Scope)
    $nodeMap[$key] = $node
    [void]$nodeMap[$parentKey].Children.Add($node)
    return $node
  }

function Add-FolderRowsToAllNodes {
  param(
    [Parameter(Mandatory=$true)][hashtable]$NodeMap
  )

  foreach ($kvp in $NodeMap.GetEnumerator()) {
    $node = $kvp.Value
    if (-not ($node -is [FolderNode])) { continue }

    # Skip synthetic meta root; folder rows there aren't meaningful
    if ([string]$node.Scope -eq 'Meta') { continue }

    # Ensure property exists (defensive)
    if ($node.PSObject.Properties.Match('Folders').Count -eq 0) { continue }

    # Rebuild folder rows from current Children
    try { $node.Folders.Clear() } catch {}

    foreach ($child in $node.Children) {
      if (-not $child) { continue }

      $node.Folders.Add([pscustomobject]@{
        Id           = [guid]::NewGuid().ToString()
        RowKind      = 'Folder'
        Selected     = $false
        Action       = 'None'     # None | Delete | Rename (rename later, not now)
        PendingLabel = ''

        OriginalName = [string]$child.Name
        Name         = [string]$child.Name
        Type         = 'Folder'
        Scope        = [string]$child.Scope

        Target       = ''
        Path         = [string]$child.FullPath
        OriginalPath = [string]$child.FullPath

        Icon         = $null
      }) | Out-Null
    }
  }
}


  foreach ($kv in $scopeRoots.GetEnumerator()) {
    $scope    = $kv.Key
    $rootPath = ($kv.Value.TrimEnd('\'))
    if (-not (Test-Path -LiteralPath $rootPath)) { continue }

    Get-ChildItem -LiteralPath $rootPath -Directory -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object {
      $null = Ensure-FolderNode -Scope $scope -FolderPath $_.FullName
    }
  }

  # STEP 3: populate folder rows after directory discovery
  Add-FolderRowsToAllNodes -NodeMap $nodeMap

  # Build a fast lookup for "does a filesystem shortcut with this display name exist anywhere"
  # (used to avoid showing duplicate AppsFolder proxy rows in VisualMenu).
  try {
    $idx = @{}
    foreach ($it0 in @($inventoryItems)) {
      if (-not $it0) { continue }
      $t0 = ''
      $n0 = ''
      try { $t0 = [string]$it0.Type } catch {}
      try { $n0 = [string]$it0.Name } catch {}
      if ($t0 -ne 'Shortcut') { continue }
      try { if (Test-IsSettingsAliasShortcutRow -Row $it0) { continue } } catch {}
      $k0 = Normalize-VisualKey $n0
      if ([string]::IsNullOrWhiteSpace($k0)) { continue }
      $idx[$k0] = $true
    }
    $script:ShortcutNameIndex = $idx
  } catch { $script:ShortcutNameIndex = @{} }

  foreach ($it in $inventoryItems) {
    if (-not $scopeRoots.ContainsKey($it.Scope)) { continue }
    if ($it.Type -ne "Shortcut" -and $it.Type -ne "Url") { continue }
    try { if (Test-IsSettingsAliasShortcutRow -Row $it) { continue } } catch {}

    $folderPath = Split-Path -Path $it.Path -Parent
    if (-not $folderPath) { continue }
    $folderPath = $folderPath.TrimEnd('\')

    $rootPath = $scopeRoots[$it.Scope].TrimEnd('\')
    if ($folderPath -ieq $rootPath) {
      $folderNode = $nodeMap["$($it.Scope)|$rootPath"]
    } else {
      $folderNode = Ensure-FolderNode -Scope $it.Scope -FolderPath $folderPath
    }
    if (-not $folderNode) { continue }
 
    $img = $null
    try {
      if ($it.PSObject.Properties.Match('IconImage').Count -gt 0) {
        $img = $it.IconImage
      }
    } catch { $img = $null }
    if (-not $img) {
      $img = Get-ImageSourceFromIcon -IconPath $it.IconPath -IconIndex $it.IconIndex -FallbackExePath $it.Target
    }
    if (-not $img -and ([string]$it.Type -eq 'Url')) {
      try {
        $ipath0 = Normalize-Path ([string]$it.Path)
        if (-not [string]::IsNullOrWhiteSpace($ipath0)) {
          $img = Get-ImageSourceFromShellFileInfoPath -Path $ipath0 -Size Small
        }
      } catch {}
    }
    if (-not $img -and ([string]$it.Type -eq 'Shortcut')) {
      try {
        $ipath = Normalize-Path ([string]$it.Path)
        if (-not [string]::IsNullOrWhiteSpace($ipath) -and $ipath.EndsWith('.lnk', [System.StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $ipath)) {
          $img = Get-ImageSourceFromIcon -IconPath $ipath -IconIndex 0 -FallbackExePath ([string]$it.Target)
          if (-not $img) {
            try { $img = Get-ImageSourceFromShellParsingName -ParsingName $ipath } catch {}
          }
        }
      } catch {}
    }
    if (-not $img -and ([string]$it.Type -eq 'Shortcut')) {
      try {
        $tpath2 = Normalize-Path ([string]$it.Target)
        if (-not [string]::IsNullOrWhiteSpace($tpath2)) {
          $img = Get-ImageSourceFromAssociatedIconPath -Path $tpath2
        }
      } catch {}
      if (-not $img) {
        try {
          $tpath3 = Normalize-Path ([string]$it.Target)
          if (-not [string]::IsNullOrWhiteSpace($tpath3)) {
            $img = Get-ImageSourceFromShellFileInfoPath -Path $tpath3 -Size Small
          }
        } catch {}
      }
    }
    if (-not $img) {
      try {
        $imageres = Join-Path $env:WINDIR 'System32\imageres.dll'
        $img = Get-ImageSourceFromIcon -IconPath $imageres -IconIndex 2 -FallbackExePath $imageres
      } catch {}
    }
 
    $argsVal = $null
    try {
      if ($it.PSObject.Properties.Match('Arguments').Count -gt 0) {
        $argsVal = $it.Arguments
      }
    } catch {}

    [void]$folderNode.Items.Add([pscustomobject]@{
      Id           = [guid]::NewGuid().ToString()
      Selected     = $false
      Action       = "None"     # None | Delete | Rename
      PendingLabel = ""         # "", "Deleted", "Renamed"
      OriginalName = [string]$it.Name
      Icon         = $img
      Name         = [string]$it.Name
      Type         = $it.Type
      Scope        = $it.Scope
      Target       = $it.Target
      Arguments    = $argsVal
      Path         = $it.Path
      OriginalPath = $it.Path
    })
  }

  foreach ($r in $treeRoots) { [void](Update-TreeCounts -node $r) }

  [pscustomobject]@{
    TreeRoots = $treeRoots
    NodeMap   = $nodeMap
  }
}

