# --------------------------
# Sort state (mock view only; persists for current running instance)
# --------------------------
if (-not (Test-Path variable:script:SortDirection)) { $script:SortDirection = 'Asc' }   # Asc | Desc
if (-not (Test-Path variable:script:SortMode))      { $script:SortMode      = 'Mixed' } # FoldersFirst | ItemsFirst | Mixed

function Get-SortMultiplier {
  if (([string]$script:SortDirection) -eq 'Desc') { return -1 }
  return 1
}

function Toggle-SortDirection {
  if (([string]$script:SortDirection) -eq 'Desc') { $script:SortDirection = 'Asc' }
  else { $script:SortDirection = 'Desc' }
}

function Get-NameColumn {
  param([Parameter(Mandatory=$true)][System.Windows.Controls.DataGrid]$Grid)

  foreach ($col in $Grid.Columns) {
    try {
      # Keep Header exactly "Name" because other code searches by header text.
      if ($col.Header -is [string] -and $col.Header -eq 'Name') { return $col }
    } catch {}
  }
  return $null
}

function Update-NameHeaderSortIndicator {
  param([Parameter(Mandatory=$true)][System.Windows.Controls.DataGrid]$Grid)

  $col = Get-NameColumn -Grid $Grid
  if (-not $col) { return }

  foreach ($c in $Grid.Columns) { try { $c.SortDirection = $null } catch {} }

  if (([string]$script:SortDirection) -eq 'Desc') {
    $col.SortDirection = [System.ComponentModel.ListSortDirection]::Descending
  } else {
    $col.SortDirection = [System.ComponentModel.ListSortDirection]::Ascending
  }
}

function Get-RowDisplayName {
  param([Parameter(Mandatory=$true)][object]$Row)

  try {
    # VisualMenu: sort by what we actually display (VisualDisplayName), unless user has a pending rename/delete.
    if ($Row.PSObject.Properties.Match('VisualDisplayName').Count -gt 0) {
      $canOverride = $true
      try {
        if ($Row.PSObject.Properties.Match('Action').Count -gt 0) {
          $a = [string]$Row.Action
          if ($a -eq 'Rename' -or $a -eq 'Delete') { $canOverride = $false }
        }
      } catch {}

      if ($canOverride) {
        $vd = [string]$Row.VisualDisplayName
        if (-not [string]::IsNullOrWhiteSpace($vd)) { return (Trim-NameInputPreserveNbsp -Text $vd) }
      }
    }

    # If a view name exists (some rebuild paths may pre-populate it), prefer it.
    if ($Row.PSObject.Properties.Match('ViewName').Count -gt 0) {
      $vn = [string]$Row.ViewName
      if (-not [string]::IsNullOrWhiteSpace($vn)) { return (Trim-NameInputPreserveNbsp -Text $vn) }
    }

    if ($Row.PSObject.Properties.Match('DisplayName').Count -gt 0) {
      $dn = [string]$Row.DisplayName
      if (-not [string]::IsNullOrWhiteSpace($dn)) { return (Trim-NameInputPreserveNbsp -Text $dn) }
    }

    if ($Row.PSObject.Properties.Match('Name').Count -gt 0) {
      $nm = [string]$Row.Name
      if (-not [string]::IsNullOrWhiteSpace($nm)) { return (Trim-NameInputPreserveNbsp -Text $nm) }
    }

    if ($Row.PSObject.Properties.Match('Path').Count -gt 0) {
      $p = [string]$Row.Path
      if (-not [string]::IsNullOrWhiteSpace($p)) { return (Trim-NameInputPreserveNbsp -Text ([System.IO.Path]::GetFileName($p.TrimEnd('\')))) }
    }

    if ($Row.PSObject.Properties.Match('Target').Count -gt 0) {
      $t = [string]$Row.Target
      if (-not [string]::IsNullOrWhiteSpace($t)) { return (Trim-NameInputPreserveNbsp -Text ([System.IO.Path]::GetFileName($t.TrimEnd('\')))) }
    }
  } catch {}

  return ''
}

function Compare-NameLogical {
  param(
    # In Windows PowerShell, mandatory string params reject empty strings unless AllowEmptyString is present.
    # Sorting can legitimately compare blanks (e.g., transient rows), so allow it.
    [AllowNull()][AllowEmptyString()][string]$A,
    [AllowNull()][AllowEmptyString()][string]$B
  )

  if ($null -eq $A) { $A = "" }
  if ($null -eq $B) { $B = "" }

  try { return [LogicalSortNative]::StrCmpLogicalW($A, $B) } catch {}
  return [string]::Compare($A, $B, $true, [Globalization.CultureInfo]::CurrentCulture)
}
function Test-StartsWithNbspAfterAsciiTrim {
  param([string]$Name)
  try {
    if ($null -eq $Name) { return $false }
    $s = [string]$Name
    try { $s = [regex]::Replace($s, '^[\u0009\u000A\u000D\u0020]+', '') } catch {}
    if ([string]::IsNullOrEmpty($s)) { return $false }
    return ([int][char]$s[0] -eq 0x00A0)
  } catch {
    return $false
  }
}

function Get-GroupKeyForRow {
  param(
    [Parameter(Mandatory=$true)][string]$Mode,
    [Parameter(Mandatory=$true)][string]$Kind  # Folder | Item
  )

  switch ($Mode) {
    'FoldersFirst' { return $(if ($Kind -eq 'Folder') { 0 } else { 1 }) }
    'ItemsFirst'   { return $(if ($Kind -eq 'Item')   { 0 } else { 1 }) }
    'Mixed'        { return 0 }
    default        { return $(if ($Kind -eq 'Folder') { 0 } else { 1 }) }
  }
}

function Get-OrderedImmediateRows {
  param(
    [object[]]$FolderRows,
    [object[]]$ItemRows,
    [Parameter(Mandatory=$true)][string]$Mode
  )

  $list = [System.Collections.Generic.List[object]]::new()
  $idx = 0

  if ($FolderRows) {
    foreach ($r in $FolderRows) {
      $list.Add([pscustomobject]@{
        Row       = $r
        Kind      = 'Folder'
        GroupKey  = (Get-GroupKeyForRow -Mode $Mode -Kind 'Folder')
        NameKey   = (Get-RowDisplayName -Row $r)
        OrigIndex = $idx
      })
      $idx++
    }
  }

  if ($ItemRows) {
    foreach ($r in $ItemRows) {
      $list.Add([pscustomobject]@{
        Row       = $r
        Kind      = 'Item'
        GroupKey  = (Get-GroupKeyForRow -Mode $Mode -Kind 'Item')
        NameKey   = (Get-RowDisplayName -Row $r)
        OrigIndex = $idx
      })
      $idx++
    }
  }

  $cmp = [System.Comparison[object]]{
    param($a, $b)

    if ($a.GroupKey -ne $b.GroupKey) { return ([int]$a.GroupKey - [int]$b.GroupKey) }

        $aName = [string]$a.NameKey
    $bName = [string]$b.NameKey

    # NBSP-leading names should appear first inside the special-character bucket (&).
    $aBucket = Get-StartMenuAlphaBucketKey -Name $aName
    $bBucket = Get-StartMenuAlphaBucketKey -Name $bName
    if ($aBucket -eq '&' -and $bBucket -eq '&') {
      $aNbsp = Test-StartsWithNbspAfterAsciiTrim -Name $aName
      $bNbsp = Test-StartsWithNbspAfterAsciiTrim -Name $bName
      if ($aNbsp -ne $bNbsp) {
        if ($aNbsp) { return -1 } else { return 1 }
      }
    }

    $mult = Get-SortMultiplier
    $c = Compare-NameLogical -A $aName -B $bName
    if ($c -ne 0) { return ($c * $mult) }

    return ([int]$a.OrigIndex - [int]$b.OrigIndex)
  }

  $list.Sort($cmp)
  return $list.ToArray()
}

