    <SolidColorBrush x:Key="UiSortComboHoverBrush" Color="#EDEDED"/>
    <SolidColorBrush x:Key="UiPanelButtonBrush" Color="#E4E4E4"/>
    <SolidColorBrush x:Key="UiPanelButtonHoverBrush" Color="#DADADA"/>
    <SolidColorBrush x:Key="UiPanelButtonBorderBrush" Color="#8f8f8f"/>
    <SolidColorBrush x:Key="UiApplyBorderBrush" Color="#40999999"/>
    <SolidColorBrush x:Key="UiTabIdleBrush" Color="#E4E4E4"/>
    <SolidColorBrush x:Key="UiTabActiveBrush" Color="#F0F0F0"/>
    <SolidColorBrush x:Key="SelectNameAccentBrush" Color="#121212"/>
    <SolidColorBrush x:Key="SelectNameAccentBrushExact" Color="#202020"/>
    <SolidColorBrush x:Key="NameIconBoxAccentBrush" Color="#202020"/>
    <SolidColorBrush x:Key="NameColumnTextBrush" Color="#FFFFFFFF"/>
    <SolidColorBrush x:Key="GridHeaderTextBrush" Color="#FF202020"/>
    <SolidColorBrush x:Key="UiCheckBoxFillBrush" Color="#00FFFFFF"/>
    <SolidColorBrush x:Key="UiCheckBoxBorderBrush" Color="#7A7A7A"/>
    <SolidColorBrush x:Key="UiCheckBoxGlyphBrush" Color="#898686"/>
    <SolidColorBrush x:Key="SelectCheckboxFillBrush" Color="#00FFFFFF"/>
    <SolidColorBrush x:Key="SelectCheckboxBorderBrush" Color="#A8FFFFFF"/>
    <SolidColorBrush x:Key="SelectCheckboxGlyphBrush" Color="#898686"/>
    <SolidColorBrush x:Key="FolderCaretBrush" Color="#CCFFFFFF"/>
    <SolidColorBrush x:Key="MidScrollGlyphBrush" Color="#FFFFFFFF"/>
    <SolidColorBrush x:Key="UiPanelScrollThumbBrush" Color="#818181"/>
    <SolidColorBrush x:Key="UiPanelScrollTrackBrush" Color="#D0D0D0"/>
    <SolidColorBrush x:Key="BottomFrameAccentBrush" Color="#0f0f0f"/>
    <Thickness x:Key="DuplicateOverlayIconMargin">0,-3,-9,0</Thickness>
    <Thickness x:Key="BrokenOverlayIconMargin">0,0,-11,-6</Thickness>
    <SolidColorBrush x:Key="UiTitleBarBrush" Color="#E1E1E1"/>
    <SolidColorBrush x:Key="UiTitleBarTextBrush" Color="#202020"/>
    <SolidColorBrush x:Key="UiTitleBarButtonHoverBrush" Color="#D6D6D6"/>
    <SolidColorBrush x:Key="UiTitleBarButtonPressedBrush" Color="#C8C8C8"/>
    <Style x:Key="AppTitleBarButtonStyle" TargetType="{x:Type Button}">
      <Setter Property="Background" Value="Transparent"/>
      <Setter Property="Foreground" Value="{DynamicResource UiTitleBarTextBrush}"/>
      <Setter Property="BorderBrush" Value="Transparent"/>
      <Setter Property="BorderThickness" Value="0"/>
      <Setter Property="Padding" Value="0"/>
      <Setter Property="FontSize" Value="12"/>
      <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
      <Setter Property="HorizontalContentAlignment" Value="Center"/>
      <Setter Property="VerticalContentAlignment" Value="Center"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="{x:Type Button}">
            <Border x:Name="TitleBtnBorder"
                    Background="{TemplateBinding Background}"
                    BorderBrush="{TemplateBinding BorderBrush}"
                    BorderThickness="{TemplateBinding BorderThickness}">
              <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                VerticalAlignment="{TemplateBinding VerticalContentAlignment}"
                                RecognizesAccessKey="True"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="TitleBtnBorder" Property="Background" Value="{DynamicResource UiTitleBarButtonHoverBrush}"/>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Setter TargetName="TitleBtnBorder" Property="Background" Value="{DynamicResource UiTitleBarButtonPressedBrush}"/>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.6"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style x:Key="UiCheckBoxStyle" TargetType="CheckBox">
      <Setter Property="Background" Value="{DynamicResource UiCheckBoxFillBrush}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource UiCheckBoxBorderBrush}"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Foreground" Value="{DynamicResource UiCheckBoxGlyphBrush}"/>
      <Setter Property="VerticalContentAlignment" Value="Center"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="CheckBox">
            <Grid SnapsToDevicePixels="True">
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="16"/>
                <ColumnDefinition Width="*"/>
              </Grid.ColumnDefinitions>
              <Border x:Name="UiCbBox"
                      Width="13"
                      Height="13"
                      CornerRadius="2"
                      Background="{TemplateBinding Background}"
                      BorderBrush="{TemplateBinding BorderBrush}"
                      BorderThickness="{TemplateBinding BorderThickness}"
                      VerticalAlignment="Center"
                      HorizontalAlignment="Left"/>
              <Path x:Name="UiCbMark"
                    Data="M 2 7 L 5 10 L 11 3"
                    Stroke="{TemplateBinding Foreground}"
                    StrokeThickness="1.8"
                    StrokeStartLineCap="Round"
                    StrokeEndLineCap="Round"
                    StrokeLineJoin="Round"
                    Width="13"
                    Height="13"
                    VerticalAlignment="Center"
                    HorizontalAlignment="Left"
                    Visibility="Collapsed"/>
              <ContentPresenter Grid.Column="1"
                                Margin="6,0,0,0"
                                VerticalAlignment="{TemplateBinding VerticalContentAlignment}"
                                RecognizesAccessKey="True"/>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsChecked" Value="True">
                <Setter TargetName="UiCbMark" Property="Visibility" Value="Visible"/>
              </Trigger>
              <Trigger Property="IsChecked" Value="{x:Null}">
                <Setter TargetName="UiCbMark" Property="Visibility" Value="Visible"/>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.6"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style x:Key="UiPanelTabItemStyle" TargetType="{x:Type TabItem}">
      <Setter Property="Foreground" Value="{DynamicResource UiTextBrush}"/>
      <Setter Property="Background" Value="{DynamicResource UiTabIdleBrush}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource UiBorderBrush}"/>
      <Setter Property="BorderThickness" Value="4"/>
      <Setter Property="Padding" Value="12,3,12,3"/>
      <Setter Property="Margin" Value="0,0,0,0"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="{x:Type TabItem}">
            <Border x:Name="TabHeaderBorder"
                    Background="{TemplateBinding Background}"
                    BorderBrush="{TemplateBinding BorderBrush}"
                    BorderThickness="{TemplateBinding BorderThickness}"
                    CornerRadius="4,4,0,0"
                    Padding="{TemplateBinding Padding}"
                    SnapsToDevicePixels="True">
              <ContentPresenter ContentSource="Header"
                                RecognizesAccessKey="True"
                                HorizontalAlignment="Center"
                                VerticalAlignment="Center"
                                Margin="2,0,2,0"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsSelected" Value="True">
                <Setter TargetName="TabHeaderBorder" Property="Background" Value="{DynamicResource UiTabActiveBrush}"/>
                <Setter Property="Foreground" Value="{DynamicResource UiTextBrush}"/>
                <Setter Property="FontWeight" Value="SemiBold"/>
                <Setter Property="Panel.ZIndex" Value="5"/>
              </Trigger>
              <Trigger Property="IsSelected" Value="False">
                <Setter TargetName="TabHeaderBorder" Property="Background" Value="{DynamicResource UiTabIdleBrush}"/>
                <Setter Property="FontWeight" Value="Normal"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style x:Key="RightPanelNavButtonStyle" TargetType="Button">
      <Setter Property="Foreground" Value="{DynamicResource UiTextBrush}"/>
      <Setter Property="Background" Value="{DynamicResource UiPanelButtonBrush}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource UiPanelButtonBorderBrush}"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Padding" Value="6,2"/>
      <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="{x:Type Button}">
            <Border x:Name="BtnBorder"
                    Background="{TemplateBinding Background}"
                    BorderBrush="{TemplateBinding BorderBrush}"
                    BorderThickness="{TemplateBinding BorderThickness}"
