            <Setter Property="Template">
              <Setter.Value>
                <ControlTemplate TargetType="{x:Type ComboBoxItem}">
                  <Border x:Name="ItemBorder" Background="{TemplateBinding Background}">
                    <ContentPresenter Margin="{TemplateBinding Padding}"
                                      VerticalAlignment="Center"
                                      HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"/>
                  </Border>
                  <ControlTemplate.Triggers>
                    <Trigger Property="IsHighlighted" Value="True">
                      <Setter TargetName="ItemBorder" Property="Background" Value="{DynamicResource UiSortComboHoverBrush}"/>
                    </Trigger>
                    <Trigger Property="IsSelected" Value="True">
                      <Setter TargetName="ItemBorder" Property="Background" Value="{DynamicResource UiSortComboHoverBrush}"/>
                    </Trigger>
                  </ControlTemplate.Triggers>
                </ControlTemplate>
              </Setter.Value>
            </Setter>
          </Style>
        </Setter.Value>
      </Setter>
    </Style>
  </Window.Resources>

  <Grid Name="RootUiGrid" Margin="0" Background="{DynamicResource UiSurfaceBrush}">
    <Grid.RowDefinitions>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="*"/>
      <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>

    <Border Name="AppTitleBar"
            Grid.Row="0"
            Height="35"
            Background="{DynamicResource UiTitleBarBrush}"
            BorderBrush="Transparent"
            BorderThickness="0">
      <Grid Name="AppTitleBarLayoutGrid">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="*"/>
          <ColumnDefinition Width="45"/>
          <ColumnDefinition Width="45"/>
          <ColumnDefinition Width="45"/>
        </Grid.ColumnDefinitions>
        <StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center" Margin="5,5,0,0">
          <Image Name="AppTitleBarIcon"
                 Width="16"
                 Height="16"
                 Margin="0,0,5,0"
                 VerticalAlignment="Center"
                 Stretch="Uniform"
                 SnapsToDevicePixels="True"
                 RenderOptions.BitmapScalingMode="HighQuality"
                 Source="{Binding Icon, RelativeSource={RelativeSource AncestorType=Window}}"/>
          <TextBlock Name="AppTitleBarText"
                     VerticalAlignment="Center"
                     Foreground="{DynamicResource UiTitleBarTextBrush}"
                     TextTrimming="CharacterEllipsis"
                     Text="{Binding Title, RelativeSource={RelativeSource AncestorType=Window}}"/>
        </StackPanel>
        <Button Name="AppMinButton"
                Grid.Column="1"
                Style="{StaticResource AppTitleBarButtonStyle}">
          <TextBlock Name="AppMinGlyphText" Text="&#x2796;" Foreground="{DynamicResource UiTitleBarTextBrush}" FontFamily="Segoe UI Symbol" FontSize="14"/>
        </Button>
        <Button Name="AppMaxButton"
                Grid.Column="2"
                Style="{StaticResource AppTitleBarButtonStyle}">
          <TextBlock Name="AppMaxGlyphText" Text="&#x2610;" Foreground="{DynamicResource UiTitleBarTextBrush}" FontFamily="Segoe UI Symbol" FontSize="14"/>
        </Button>
        <Button Name="AppCloseButton"
                Grid.Column="3"
                Style="{StaticResource AppTitleBarButtonStyle}">
          <TextBlock Name="AppCloseGlyphText" Text="&#x274C;" Foreground="{DynamicResource UiTitleBarTextBrush}" FontFamily="Segoe UI Symbol" FontSize="14"/>
        </Button>
      </Grid>
    </Border>

    <Grid Name="TopUiPanel" Grid.Row="1" Margin="0,0,0,10" VerticalAlignment="Top" Background="{DynamicResource UiSurfaceBrush}">
      <Grid.Resources>
        <Style x:Key="TopUiFlatButtonStyle" TargetType="Button">
          <Setter Property="Background" Value="Transparent"/>
          <Setter Property="BorderBrush" Value="Transparent"/>
          <Setter Property="BorderThickness" Value="0"/>
          <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
          <Setter Property="Padding" Value="4,3"/>
          <Setter Property="HorizontalContentAlignment" Value="Center"/>
          <Setter Property="VerticalContentAlignment" Value="Center"/>
          <Setter Property="Template">
            <Setter.Value>
              <ControlTemplate TargetType="{x:Type Button}">
                <Border x:Name="TopUiBtnBorder"
                        Background="{TemplateBinding Background}"
                        BorderBrush="{TemplateBinding BorderBrush}"
                        BorderThickness="{TemplateBinding BorderThickness}"
                        CornerRadius="0"
                        SnapsToDevicePixels="True">
                  <ContentPresenter Margin="{TemplateBinding Padding}"
                                    HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                    VerticalAlignment="{TemplateBinding VerticalContentAlignment}"
                                    RecognizesAccessKey="True"/>
                </Border>
                <ControlTemplate.Triggers>
                  <Trigger Property="IsEnabled" Value="False">
                    <Setter Property="Opacity" Value="0.6"/>
                  </Trigger>
                </ControlTemplate.Triggers>
              </ControlTemplate>
            </Setter.Value>
          </Setter>
        </Style>
        <Style x:Key="TopUiApplyButtonStyle" TargetType="Button" BasedOn="{StaticResource TopUiFlatButtonStyle}">
          <Setter Property="Background" Value="Transparent"/>
          <Setter Property="BorderBrush" Value="{DynamicResource UiApplyBorderBrush}"/>
          <Setter Property="BorderThickness" Value="3"/>
          <Setter Property="Padding" Value="2,1"/>
          <Setter Property="Template">
            <Setter.Value>
              <ControlTemplate TargetType="{x:Type Button}">
                <Border x:Name="ApplyBtnBorder"
                        Background="{TemplateBinding Background}"
                        BorderBrush="{TemplateBinding BorderBrush}"
                        BorderThickness="{TemplateBinding BorderThickness}"
                        CornerRadius="8"
                        SnapsToDevicePixels="True">
                  <ContentPresenter Margin="{TemplateBinding Padding}"
                                    HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                    VerticalAlignment="{TemplateBinding VerticalContentAlignment}"
                                    RecognizesAccessKey="True"/>
                </Border>
                <ControlTemplate.Triggers>
                  <Trigger Property="IsEnabled" Value="False">
                    <Setter Property="Opacity" Value="0.6"/>
                  </Trigger>
                </ControlTemplate.Triggers>
              </ControlTemplate>
            </Setter.Value>
          </Setter>
        </Style>
        <Style x:Key="TopUiActionLabelStyle" TargetType="TextBlock">
          <Setter Property="Foreground" Value="{DynamicResource UiTextBrush}"/>
          <Setter Property="TextAlignment" Value="Center"/>
          <Setter Property="HorizontalAlignment" Value="Center"/>
          <Setter Property="LineStackingStrategy" Value="BlockLineHeight"/>
          <Setter Property="LineHeight" Value="11"/>
          <Setter Property="Margin" Value="0"/>
        </Style>
        <Style x:Key="TopUiCheckBoxStyle" TargetType="CheckBox" BasedOn="{StaticResource UiCheckBoxStyle}"/>
        <Style x:Key="TopUiSortModeComboStyle" TargetType="{x:Type ComboBox}" BasedOn="{StaticResource CharMapFontStaticComboStyle}"/>
      </Grid.Resources>

      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="Auto"/>
        <ColumnDefinition Width="16"/>
        <ColumnDefinition Width="Auto"/>
        <ColumnDefinition Width="16"/>
        <ColumnDefinition Width="Auto"/>
        <ColumnDefinition Width="16"/>
        <ColumnDefinition Width="*"/>
        <ColumnDefinition Width="Auto"/>
      </Grid.ColumnDefinitions>

      <StackPanel Grid.Column="0" Orientation="Vertical" Margin="10,0,0,-5" HorizontalAlignment="Left">
        <TextBlock Name="SearchCaptionText" Text="Search:" Margin="16,0,0,1" Foreground="{DynamicResource UiTextBrush}"/>
        <StackPanel Orientation="Horizontal" VerticalAlignment="Center" HorizontalAlignment="Left">
          <Image Name="SearchFieldIcon" Width="24" Height="24" Margin="-10,0,0,0" VerticalAlignment="Center" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
          <TextBox Name="SearchBox" Width="150"/>
        </StackPanel>
        <StackPanel Orientation="Horizontal" Margin="20,10,0,0">
          <Button Name="UndoBtn" Width="72" Margin="-10,0,6,0" Style="{StaticResource TopUiFlatButtonStyle}">
            <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
              <Image Name="UndoBtnIcon"
                     Width="14"
                     Height="14"
                     Margin="0,2,4,0"
                     Stretch="Uniform"
                     SnapsToDevicePixels="True"
                     RenderOptions.BitmapScalingMode="HighQuality"
                     RenderTransformOrigin="0.5,0.5">
                <Image.RenderTransform>
                  <ScaleTransform ScaleX="-1" ScaleY="1"/>
                </Image.RenderTransform>
              </Image>
              <TextBlock Text="Undo" VerticalAlignment="Center" Foreground="{DynamicResource UiTextBrush}"/>
            </StackPanel>
          </Button>
          <Button Name="RedoBtn" Width="72" Margin="0,0,0,0" Style="{StaticResource TopUiFlatButtonStyle}">
            <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
              <TextBlock Text="Redo" VerticalAlignment="Center" Foreground="{DynamicResource UiTextBrush}"/>
              <Image Name="RedoBtnIcon"
                     Width="14"
                     Height="14"
                     Margin="4,2,0,0"
                     Stretch="Uniform"
                     SnapsToDevicePixels="True"
                     RenderOptions.BitmapScalingMode="HighQuality"/>
            </StackPanel>
          </Button>
        </StackPanel>
      </StackPanel>

      

      <StackPanel Grid.Column="2" Orientation="Vertical" Margin="20,0,10,-5" HorizontalAlignment="Left">
        <TextBlock Name="ViewCaptionText" Text="View:" Margin="0,0,0,1" Foreground="{DynamicResource UiTextBrush}"/>
        <StackPanel Orientation="Horizontal" VerticalAlignment="Center" Margin="-10,0,0,2" HorizontalAlignment="Left">
          <Image Name="SortModeIcon" Width="24" Height="24" Margin="-15,0,1,0" VerticalAlignment="Center" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
          <ComboBox Name="SortModeBox" Width="150" SelectedIndex="0" Style="{StaticResource TopUiSortModeComboStyle}">
            <ComboBoxItem Content="Folders > items" Tag="FoldersFirst"/>
            <ComboBoxItem Content="Items > folders" Tag="ItemsFirst"/>
            <ComboBoxItem Content="Mixed (Widows view)" Tag="Mixed"/>
          </ComboBox>
        </StackPanel>
        <CheckBox Name="ShowAlphaSeparatorsBox" Content="Show separators" VerticalAlignment="Center" Margin="0,1,0,1" Style="{StaticResource TopUiCheckBoxStyle}"/>
        <CheckBox Name="ShowNestedFoldersBox" Content="Show nested folders" VerticalAlignment="Center" Style="{StaticResource TopUiCheckBoxStyle}"/>
      </StackPanel>

      <Border Name="TopUiSep1" Grid.Column="3" Width="1" Height="74" Background="{DynamicResource UiTopSeparatorBrush}" VerticalAlignment="Center" Panel.ZIndex="50" SnapsToDevicePixels="True"/>

      <StackPanel Grid.Column="4" Orientation="Vertical" Margin="8,5,5,-5">
        <CheckBox Name="ShowStartupFolderBox" Content="Show Startup folder" VerticalAlignment="Center" Margin="0,0,0,1" Style="{StaticResource TopUiCheckBoxStyle}"/>
        <CheckBox Name="ShowEmptyFoldersBox" Content="Show empty folders" VerticalAlignment="Center" Margin="0,0,0,1" Style="{StaticResource TopUiCheckBoxStyle}"/>
        <CheckBox Name="ExpandAllFoldersBox" Content="Expand all folders" VerticalAlignment="Center" Margin="0,0,0,1" Style="{StaticResource TopUiCheckBoxStyle}"/>
        <CheckBox Name="SelectAllBox" Content="Select All in view" VerticalAlignment="Center" Style="{StaticResource TopUiCheckBoxStyle}"/>
      </StackPanel>

      <Border Name="TopUiSep2" Grid.Column="5" Width="1" Height="74" Background="{DynamicResource UiTopSeparatorBrush}" VerticalAlignment="Center" Panel.ZIndex="50" SnapsToDevicePixels="True"/>

      <StackPanel Grid.Column="6" Orientation="Horizontal" VerticalAlignment="Center" HorizontalAlignment="Left">
        <Button Name="MockDeleteBtn" Width="Auto" MinWidth="50" Height="64" Margin="0,0,6,0" Style="{StaticResource TopUiFlatButtonStyle}">
          <StackPanel Orientation="Vertical" VerticalAlignment="Center">
            <Image Name="MockDeleteBtnIcon" Width="30" Height="30" Margin="0,0,0,2" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
            <TextBlock Text="Delete&#x0a;Selected" Style="{StaticResource TopUiActionLabelStyle}"/>
          </StackPanel>
        </Button>
        <Button Name="UnDeleteBtn" Width="Auto" MinWidth="50" Height="64" Margin="-5,0,6,0" Style="{StaticResource TopUiFlatButtonStyle}">
          <StackPanel Orientation="Vertical" VerticalAlignment="Center">
            <Image Name="UnDeleteBtnIcon" Width="26" Height="26" Margin="10,2,6,4" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
            <TextBlock Text="Un-Delete&#x0a;Selected" Style="{StaticResource TopUiActionLabelStyle}"/>
          </StackPanel>
        </Button>
        <Border Name="TopUiSep3" Width="1" Height="74" Background="{DynamicResource UiTopSeparatorBrush}" Margin="0,0,8,0" VerticalAlignment="Center" Panel.ZIndex="50" SnapsToDevicePixels="True"/>

        <Button Name="PrepareStartMenuBtn" Width="Auto" MinWidth="50" Height="64" Margin="3,0,10,0" Style="{StaticResource TopUiFlatButtonStyle}">
          <StackPanel Orientation="Vertical" VerticalAlignment="Center">
            <Image Name="PrepareStartMenuBtnIcon" Width="30" Height="30" Margin="0,0,0,2" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
            <TextBlock Text="Prepare&#x0a;Start Menu" Style="{StaticResource TopUiActionLabelStyle}"/>
          </StackPanel>
        </Button>
        <Border Name="TopUiSep4" Width="1" Height="74" Background="{DynamicResource UiTopSeparatorBrush}" Margin="0,0,8,0" VerticalAlignment="Center" Panel.ZIndex="50" SnapsToDevicePixels="True"/>

        <Button Name="SaveProfileBtn" Width="Auto" MinWidth="45" Height="64" Margin="5,0,6,0" Style="{StaticResource TopUiFlatButtonStyle}">
          <StackPanel Orientation="Vertical" VerticalAlignment="Center">
            <Image Name="SaveProfileBtnIcon" Width="30" Height="30" Margin="0,0,0,2" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
            <TextBlock Text="Create&#x0a;Backup" Style="{StaticResource TopUiActionLabelStyle}"/>
          </StackPanel>
        </Button>

        <Button Name="RestoreBackupBtn" Width="Auto" MinWidth="45" Height="64" Margin="-5,0,10,0" Style="{StaticResource TopUiFlatButtonStyle}">
          <StackPanel Orientation="Vertical" VerticalAlignment="Center">
            <Image Name="RestoreBackupBtnIcon" Width="30" Height="30" Margin="0,0,0,2" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
            <TextBlock Text="Restore&#x0a;Backup" Style="{StaticResource TopUiActionLabelStyle}"/>
          </StackPanel>
        </Button>
        <Border Name="TopUiSep5" Width="1" Height="74" Background="{DynamicResource UiTopSeparatorBrush}" Margin="0,0,8,0" VerticalAlignment="Center" Panel.ZIndex="50" SnapsToDevicePixels="True"/>

        <Button Name="SavePendingStatesBtn" Width="Auto" MinWidth="45" Height="64" Margin="5,0,6,0" Style="{StaticResource TopUiFlatButtonStyle}">
          <StackPanel Orientation="Vertical" VerticalAlignment="Center">
            <Image Name="SavePendingStatesBtnIcon" Width="30" Height="30" Margin="0,0,0,2" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
            <TextBlock Text="Save&#x0a;Pending" Style="{StaticResource TopUiActionLabelStyle}"/>
          </StackPanel>
        </Button>

        <Button Name="LoadProfileBtn" Width="Auto" MinWidth="45" Height="64" Margin="-5,0,10,0" Style="{StaticResource TopUiFlatButtonStyle}">
          <StackPanel Orientation="Vertical" VerticalAlignment="Center">
            <Image Name="LoadProfileBtnIcon" Width="30" Height="30" Margin="0,0,0,2" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
            <TextBlock Text="Load&#x0a;Pending" Style="{StaticResource TopUiActionLabelStyle}"/>
          </StackPanel>
        </Button>
        <Border Name="TopUiSep6" Width="1" Height="74" Background="{DynamicResource UiTopSeparatorBrush}" Margin="0,0,8,0" VerticalAlignment="Center" Panel.ZIndex="50" SnapsToDevicePixels="True"/>

        <Button Name="RefreshBtn" Width="Auto" MinWidth="45" Height="64" Margin="5,0,6,0" Style="{StaticResource TopUiFlatButtonStyle}">
          <StackPanel Orientation="Vertical" VerticalAlignment="Center">
            <Image Name="RefreshBtnIcon" Width="30" Height="30" Margin="0,0,0,2" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
            <TextBlock Text="Refresh&#x0a;Grid" Style="{StaticResource TopUiActionLabelStyle}"/>
          </StackPanel>
        </Button>

        <Button Name="ResetBtn" Width="Auto" MinWidth="45" Height="64" Margin="-5,0,10,0" Style="{StaticResource TopUiFlatButtonStyle}">
          <StackPanel Orientation="Vertical" VerticalAlignment="Center">
            <Image Name="ResetBtnIcon" Width="30" Height="30" Margin="0,0,0,2" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
            <TextBlock Text="Clear&#x0a;Pending" Style="{StaticResource TopUiActionLabelStyle}"/>
          </StackPanel>
        </Button>
        <Border Name="TopUiSep7" Width="1" Height="74" Background="{DynamicResource UiTopSeparatorBrush}" Margin="0,0,10,0" VerticalAlignment="Center" Panel.ZIndex="50" SnapsToDevicePixels="True"/>

        <Button Name="ApplyBtn" Width="Auto" MinWidth="105" Height="70" Margin="15,0,0,0" Style="{StaticResource TopUiApplyButtonStyle}">
          <StackPanel Orientation="Vertical" VerticalAlignment="Center">
            <Image Name="ApplyBtnIcon" Width="30" Height="30" Margin="0,1,0,3" Stretch="Uniform" SnapsToDevicePixels="False" RenderOptions.BitmapScalingMode="HighQuality"/>
            <TextBlock Text="Apply All Changes" Style="{StaticResource TopUiActionLabelStyle}"/>
            <TextBlock Text="(Commit to actual Start Menu)"
                       FontSize="8"
                       Foreground="{DynamicResource UiTextBrush}"
                       HorizontalAlignment="Center"
                       TextAlignment="Center"
                       Margin="0,0,0,0"/>
          </StackPanel>
        </Button>
      </StackPanel>

      <StackPanel Grid.Column="7" Orientation="Vertical" VerticalAlignment="Top" HorizontalAlignment="Right" Margin="10,0,0,0">
        <Button Name="InfoBtn" Width="30" Height="30" Margin="0,0,0,4" Style="{StaticResource TopUiFlatButtonStyle}">
          <Image Name="InfoBtnIcon" Width="20" Height="20" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
        </Button>
        <Button Name="UiThemeToggleBtn" Width="30" Height="30" Margin="0,0,0,0" Style="{StaticResource TopUiFlatButtonStyle}" ToolTip="Light/Dark mode">
          <Image Name="UiThemeToggleIcon" Width="20" Height="20" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
        </Button>
      </StackPanel>
    </Grid>

    <Grid Grid.Row="2">
      <Grid.ColumnDefinitions>
        <ColumnDefinition Name="MainLeftHostCol" Width="*" MinWidth="330"/>
        <ColumnDefinition Name="MainSplitterCol" Width="0"/>
        <ColumnDefinition Name="MainRightPanelCol" Width="420" MinWidth="330"/>
      </Grid.ColumnDefinitions>

      <TabControl Grid.Column="2" Name="RightPanelTabs" Background="{DynamicResource UiSurfaceBrush}" Foreground="{DynamicResource UiTextBrush}" BorderThickness="0" Padding="0" Margin="-6,-4,0,0" ItemContainerStyle="{StaticResource UiPanelTabItemStyle}">
        <TabItem Name="ProfilesTab" Header="Profiles" Style="{StaticResource UiPanelTabItemStyle}" Margin="0,0,0,-1">
          <Border Name="ProfilesPanelBorder" BorderBrush="{DynamicResource UiBorderBrush}" BorderThickness="1,1,0,0" CornerRadius="4,4,0,0" Padding="8" Margin="0" Background="{DynamicResource UiPanelBrush}">
            <TreeView Name="FolderTree" Background="{DynamicResource UiPanelBrush}" Foreground="{DynamicResource UiTextBrush}">
              <TreeView.ItemTemplate>
                <HierarchicalDataTemplate ItemsSource="{Binding Children}">
                  <TextBlock Text="{Binding DisplayName, Mode=OneWay}" />
                </HierarchicalDataTemplate>
              </TreeView.ItemTemplate>
            </TreeView>
          </Border>
        </TabItem>

        <TabItem Name="CreateTab" Header="Create/Edit Shortcut" Style="{StaticResource UiPanelTabItemStyle}" Margin="-2,0,2,-1">
          <Border Name="CreateShortcutPanel" BorderBrush="{DynamicResource UiBorderBrush}" BorderThickness="1,1,1,0" CornerRadius="4,4,4,0" Padding="8" Margin="0" Background="{DynamicResource UiSurfaceBrush}">
            <Grid>
              <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
              </Grid.RowDefinitions>

            <TextBlock Grid.Row="0" Text="Create and edit Start Menu items." FontWeight="SemiBold" Margin="0,0,0,6"/>

            <StackPanel Grid.Row="1" Orientation="Horizontal" Margin="0,0,0,6">
              <TextBlock Name="CreateModeCaptionText" Text="" VerticalAlignment="Center" Margin="0,0,10,0"/>
              <RadioButton Name="CreateModeFolderRadio" GroupName="CreateModeGroup" VerticalAlignment="Center" Margin="0,0,14,0">Create Folder</RadioButton>
              <RadioButton Name="CreateModeShortcutRadio" GroupName="CreateModeGroup" VerticalAlignment="Center" Margin="0,0,14,0">Create Shortcut</RadioButton>
              <RadioButton Name="CreateModeEditRadio" GroupName="CreateModeGroup" VerticalAlignment="Center">Edit Selected</RadioButton>
            </StackPanel>

            <Grid Grid.Row="3" Name="CreateTargetRow" Margin="0,0,0,6" Visibility="Collapsed">
              <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
              </Grid.RowDefinitions>
              <TextBox Grid.Row="0" Name="CreateTargetBox" MinWidth="140" ToolTip="Browse / paste path / drag and drop target item" AllowDrop="True"/>
              <StackPanel Grid.Row="1" Orientation="Horizontal" Margin="0,6,0,0">
                <Button Name="CreateTargetBrowseFileBtn" Width="120" Margin="0,0,8,0" Style="{StaticResource RightPanelNavButtonStyle}">Browse for File</Button>
                <Button Name="CreateTargetBrowseFolderBtn" Width="130" Style="{StaticResource RightPanelNavButtonStyle}">Browse for Folder</Button>
              </StackPanel>
            </Grid>

            <Grid Grid.Row="2" Margin="0,0,0,6">
              <Grid.ColumnDefinitions>
                <ColumnDefinition Name="CreateIconValueCol" Width="Auto"/>
                <ColumnDefinition Name="CreateIconSpacerCol" Width="8"/>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="8"/>
                <ColumnDefinition Width="Auto"/>
              </Grid.ColumnDefinitions>
              <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
              </Grid.RowDefinitions>

              <TextBlock Name="CreateIconLabel" Grid.Row="0" Grid.Column="0" Text="Icon" Margin="0,0,0,2"/>
              <TextBlock Name="CreateNameLabel" Grid.Row="0" Grid.Column="2" Text="Name" Margin="0,0,0,2"/>

              <Border Name="CreateIconPreviewBorder" Grid.Row="1" Grid.Column="0" Width="32" Height="32" BorderBrush="Transparent" BorderThickness="1" VerticalAlignment="Center">
                <Image Name="CreateSelectedIconPreview" Stretch="Uniform"/>
              </Border>
              <TextBox Grid.Row="1" Grid.Column="2" Name="CreateNameBox" Height="32"/>
              <Button Grid.Row="1" Grid.Column="4" Name="CreateQueueBtn" Width="72" Height="32" VerticalAlignment="Center" Style="{StaticResource RightPanelNavButtonStyle}">Create</Button>
            </Grid>

            <Grid Grid.Row="4">
            <TabControl Name="CreateIconTabs" MinHeight="120" Margin="-8,0,-8,-8" HorizontalAlignment="Stretch" VerticalAlignment="Stretch" Background="{DynamicResource UiSurfaceBrush}" BorderThickness="0" Padding="0" ItemContainerStyle="{StaticResource UiPanelTabItemStyle}">
              <TabControl.Effect>
                <DropShadowEffect Color="#00000000" BlurRadius="13" ShadowDepth="1" Direction="45" Opacity="0.20" RenderingBias="Performance"/>
              </TabControl.Effect>
              <TabItem Name="CreateSystemIconsTab" Header="System Icons" Style="{StaticResource UiPanelTabItemStyle}" Margin="0,0,0,-1">
                <Grid Margin="0">
                  <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                  </Grid.RowDefinitions>
                  <StackPanel Grid.Row="0" Orientation="Horizontal" Margin="8,10,0,4">
                    <ToggleButton Name="CreateSystemIconCategoryFilterBtn" HorizontalAlignment="Left" Style="{StaticResource RightPanelNavToggleStyle}">Category</ToggleButton>
                    <Popup Name="CreateSystemIconCategoryPopup"
                           PlacementTarget="{Binding ElementName=CreateSystemIconCategoryFilterBtn}"
                           Placement="Bottom"
                           StaysOpen="False"
                           AllowsTransparency="True"
                           PopupAnimation="Fade">
                      <Border Background="Transparent" Padding="8">
                        <Border Name="CreateSystemIconCategoryPopupBorder" Background="{DynamicResource UiPanelBrush}" BorderBrush="{DynamicResource UiSeparatorBrush}" BorderThickness="1" CornerRadius="6" Padding="6" MinWidth="260" Opacity="1.0">
                          <Border.Effect>
                            <DropShadowEffect Color="#CC000000" BlurRadius="10" ShadowDepth="0" Direction="90" Opacity="0.50" RenderingBias="Performance"/>
                          </Border.Effect>
                          <StackPanel>
                            <WrapPanel Margin="0,0,0,4">
                              <Button Name="CreateSystemIconSelectAllBtn" Width="65" Margin="0,0,6,0" Style="{StaticResource RightPanelNavButtonStyle}">Select All</Button>
                              <Button Name="CreateSystemIconClearAllBtn" Width="65" Margin="0,0,6,0" Style="{StaticResource RightPanelNavButtonStyle}">Clear All</Button>
                              <Button Name="MiscOpenIconAllocatorBtn" MinWidth="80" Height="23" Style="{StaticResource RightPanelNavButtonStyle}">Open Icon Allocator</Button>
                            </WrapPanel>
                            <ScrollViewer VerticalScrollBarVisibility="Auto" MaxHeight="260">
                              <UniformGrid Name="CreateSystemIconCategoryChecklist" Columns="2"/>
                            </ScrollViewer>
                          </StackPanel>
                        </Border>
                      </Border>
                    </Popup>
                    <TextBlock Text="Search:" VerticalAlignment="Center" Margin="14,0,6,0"/>
                    <TextBox Name="CreateSystemIconSearchBox" Width="180" VerticalAlignment="Center"/>
                  </StackPanel>
                  <TextBlock Name="CreateSystemIconSummaryText" Grid.Row="1" Margin="8,0,0,4" Foreground="Gray" FontSize="11"/>
                  <ListBox Name="CreateSystemIconListBox"
                           Grid.Row="2"
                           Background="{DynamicResource UiPanelBrush}"
                           Margin="0"
                           Padding="0"
                           BorderThickness="0"
                           UseLayoutRounding="True"
                           SnapsToDevicePixels="True"
                           ScrollViewer.VerticalScrollBarVisibility="Auto"
                           ScrollViewer.HorizontalScrollBarVisibility="Disabled"
                           ScrollViewer.CanContentScroll="False">
                    <ListBox.ItemsPanel>
                      <ItemsPanelTemplate>
                        <WrapPanel IsItemsHost="True"/>
                      </ItemsPanelTemplate>
                    </ListBox.ItemsPanel>
                    <ListBox.ItemContainerStyle>
                      <Style TargetType="ListBoxItem">
                        <Setter Property="Width" Value="40"/>
                        <Setter Property="Height" Value="40"/>
                        <Setter Property="Margin" Value="2"/>
                        <Setter Property="Padding" Value="0"/>
                        <Setter Property="BorderThickness" Value="0"/>
                        <Setter Property="Background" Value="Transparent"/>
                        <Setter Property="BorderBrush" Value="Transparent"/>
                        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
                        <Setter Property="SnapsToDevicePixels" Value="True"/>
                        <Setter Property="HorizontalContentAlignment" Value="Center"/>
                        <Setter Property="VerticalContentAlignment" Value="Center"/>
                        <Setter Property="ToolTip" Value="{Binding Label}"/>
                        <Setter Property="Template">
                          <Setter.Value>
                            <ControlTemplate TargetType="ListBoxItem">
                              <Grid SnapsToDevicePixels="True">
                                <Border x:Name="BaseLayer"
                                        Panel.ZIndex="0"
                                        Background="{TemplateBinding Background}"
                                        BorderBrush="{TemplateBinding BorderBrush}"
                                        BorderThickness="{TemplateBinding BorderThickness}"
                                        CornerRadius="2"/>
                                <ContentPresenter Panel.ZIndex="1"
                                                  HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                                  VerticalAlignment="{TemplateBinding VerticalContentAlignment}"
                                                  SnapsToDevicePixels="{TemplateBinding SnapsToDevicePixels}"/>
                                <Border x:Name="HoverOverlay"
                                        Panel.ZIndex="9"
                                        Background="{DynamicResource UiPanelButtonHoverBrush}"
                                        BorderBrush="{DynamicResource UiPanelButtonHoverBrush}"
                                        BorderThickness="1"
                                        CornerRadius="2"
                                        Opacity="0"
                                        IsHitTestVisible="False"/>
                              </Grid>
                              <ControlTemplate.Triggers>
                                <Trigger Property="IsMouseOver" Value="True">
                                  <Setter TargetName="HoverOverlay" Property="Opacity" Value="0.20"/>
                                </Trigger>
                                <Trigger Property="IsSelected" Value="True">
                                  <Setter TargetName="HoverOverlay" Property="Opacity" Value="0.30"/>
                                </Trigger>
                              </ControlTemplate.Triggers>
                            </ControlTemplate>
                          </Setter.Value>
                        </Setter>
                      </Style>
                    </ListBox.ItemContainerStyle>
                    <ListBox.ItemTemplate>
                      <DataTemplate>
                        <Image Source="{Binding Icon}" Width="32" Height="32" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
                      </DataTemplate>
                    </ListBox.ItemTemplate>
                  </ListBox>
                  <WrapPanel Grid.Row="3" Margin="0,3,85,3" HorizontalAlignment="Right" VerticalAlignment="Bottom">
                    <Button Name="CreateSystemIconPrevPageBtn" Width="80" Margin="0,0,6,0" Style="{StaticResource RightPanelNavButtonStyle}">Back</Button>
                    <TextBlock Name="CreateSystemIconPageText" VerticalAlignment="Center" Margin="0,0,6,0"/>
                    <Button Name="CreateSystemIconNextPageBtn" Width="80" Style="{StaticResource RightPanelNavButtonStyle}">Next</Button>
                  </WrapPanel>
                </Grid>
              </TabItem>
              <TabItem Name="CreateCustomIconTab" Header="Custom Icon" Style="{StaticResource UiPanelTabItemStyle}" Margin="0,0,0,0">
                <StackPanel Margin="0">
                  <StackPanel Orientation="Horizontal">
                    <TextBox Name="CreateCustomIconPathBox" Width="180" Margin="10,10,6,0"/>
                    <Button Name="CreateCustomIconBrowseBtn" Width="70" Margin="8,10,6,0" Style="{StaticResource RightPanelNavButtonStyle}">Browse</Button>
                  </StackPanel>
                  <TextBlock Margin="0,6,0,0" Foreground="Gray" Text="   Supports .ico .exe .dll files (index 0)."/>
                </StackPanel>
              </TabItem>
              <TabItem Name="CreateCharMapTab" Header="Character Map" Style="{StaticResource UiPanelTabItemStyle}" Margin="0,0,0,0">
                <Grid Margin="0,10,0,0">
                  <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                  </Grid.RowDefinitions>
                  <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="*"/>
                  </Grid.ColumnDefinitions>                  <TextBlock Grid.Row="0" Grid.Column="0" Text="Font:" VerticalAlignment="Center" Margin="8,0,0,6"/>
                  <StackPanel Grid.Row="0" Grid.Column="1" Orientation="Horizontal" Margin="-60,0,0,6" HorizontalAlignment="Left">
                    <ComboBox Name="CreateCharMapFontBox" IsEditable="False" Width="180" HorizontalAlignment="Left" Style="{StaticResource CharMapFontStaticComboStyle}"/>
                    <Button Name="CreateCharMapInsertBlankBtn" Margin="8,0,0,0" MinWidth="95" Style="{StaticResource RightPanelNavButtonStyle}">Insert blank character</Button>
                  </StackPanel>
                  <ListBox Grid.Row="1" Grid.ColumnSpan="2" Name="CreateCharMapListBox"
                           Background="{DynamicResource UiPanelBrush}"
                           Foreground="{DynamicResource UiTextBrush}"
                           BorderBrush="#66656576" BorderThickness="0"
                           ScrollViewer.VerticalScrollBarVisibility="Auto"
                           ScrollViewer.HorizontalScrollBarVisibility="Disabled"
                           ScrollViewer.CanContentScroll="True"
                           VirtualizingPanel.IsVirtualizing="True"
                           VirtualizingPanel.VirtualizationMode="Recycling"
                           HorizontalContentAlignment="Stretch">
                    <ListBox.ItemsPanel>
                      <ItemsPanelTemplate>
                        <VirtualizingStackPanel/>
                      </ItemsPanelTemplate>
                    </ListBox.ItemsPanel>
                    <ListBox.ItemContainerStyle>
                      <Style TargetType="ListBoxItem">
                        <Setter Property="Background" Value="Transparent"/>
                        <Setter Property="BorderBrush" Value="Transparent"/>
                        <Setter Property="Margin" Value="0"/>
                        <Setter Property="Padding" Value="0"/>
                        <Setter Property="Focusable" Value="False"/>
                        <Setter Property="BorderThickness" Value="0"/>
                        <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
                        <Setter Property="VerticalContentAlignment" Value="Top"/>
                        <Setter Property="Template">
                          <Setter.Value>
                            <ControlTemplate TargetType="ListBoxItem">
                              <Border Background="Transparent"
                                      BorderBrush="Transparent"
                                      BorderThickness="0"
                                      SnapsToDevicePixels="True">
                                <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                                  VerticalAlignment="{TemplateBinding VerticalContentAlignment}"
                                                  SnapsToDevicePixels="{TemplateBinding SnapsToDevicePixels}"/>
                              </Border>
                            </ControlTemplate>
                          </Setter.Value>
                        </Setter>
                      </Style>
                    </ListBox.ItemContainerStyle>
                    <ListBox.ItemTemplate>
                      <DataTemplate>
                        <ItemsControl ItemsSource="{Binding Cells}">
                          <ItemsControl.ItemsPanel>
                            <ItemsPanelTemplate>
                              <UniformGrid Columns="{Binding Columns}"/>
                            </ItemsPanelTemplate>
                          </ItemsControl.ItemsPanel>
                          <ItemsControl.ItemTemplate>
                            <DataTemplate>
                              <Button Width="28" Height="28" Margin="1" Padding="0"
                                      Tag="{Binding}" Focusable="False"
                                      Background="Transparent" BorderBrush="Transparent" BorderThickness="0">
                                <Button.Style>
                                  <Style TargetType="Button">
                                    <Setter Property="Foreground" Value="{DynamicResource UiTextBrush}"/>
                                    <Setter Property="Background" Value="Transparent"/>
                                    <Setter Property="BorderBrush" Value="Transparent"/>
                                    <Setter Property="BorderThickness" Value="0"/>
                                    <Setter Property="Padding" Value="0"/>
                                    <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
                                    <Setter Property="Template">
                                      <Setter.Value>
                                        <ControlTemplate TargetType="Button">
                                          <Grid SnapsToDevicePixels="True">
                                            <Border x:Name="BaseLayer"
                                                    Panel.ZIndex="0"
                                                    Background="{TemplateBinding Background}"
                                                    BorderBrush="{TemplateBinding BorderBrush}"
                                                    BorderThickness="{TemplateBinding BorderThickness}"
                                                    CornerRadius="2"/>
                                            <ContentPresenter Panel.ZIndex="1"
                                                              HorizontalAlignment="Center"
                                                              VerticalAlignment="Center"/>
                                            <Border x:Name="HoverOverlay"
                                                    Panel.ZIndex="9"
                                                    Background="{DynamicResource UiPanelButtonHoverBrush}"
                                                    BorderBrush="{DynamicResource UiPanelButtonHoverBrush}"
                                                    BorderThickness="1"
                                                    CornerRadius="2"
                                                    Opacity="0"
                                                    IsHitTestVisible="False"/>
                                          </Grid>
                                          <ControlTemplate.Triggers>
                                            <Trigger Property="IsMouseOver" Value="True">
                                              <Setter TargetName="HoverOverlay" Property="Opacity" Value="0.20"/>
                                            </Trigger>
                                            <Trigger Property="IsPressed" Value="True">
                                              <Setter TargetName="HoverOverlay" Property="Opacity" Value="0.30"/>
                                            </Trigger>
                                          </ControlTemplate.Triggers>
                                        </ControlTemplate>
                                      </Setter.Value>
                                    </Setter>
                                  </Style>
                                </Button.Style>
                                <TextBlock Text="{Binding Char}"
                                           FontFamily="{Binding FontFamily}"
                                           FontSize="16"
                                           FontWeight="Normal"
                                           FontStyle="Normal"
                                           Foreground="{Binding RelativeSource={RelativeSource AncestorType=ListBox}, Path=Foreground}"
                                           HorizontalAlignment="Center"
                                           VerticalAlignment="Center"
                                           TextAlignment="Center"/>
                              </Button>
                            </DataTemplate>
                          </ItemsControl.ItemTemplate>
                        </ItemsControl>
                      </DataTemplate>
                    </ListBox.ItemTemplate>
                  </ListBox>
                  <TextBlock Grid.Row="2" Grid.Column="0" Text="Characters to copy :" VerticalAlignment="Center" Margin="8,8,8,0"/>
                  <TextBox Grid.Row="2" Grid.Column="1" Name="CreateCharMapCopyBox" Margin="8,8,8,0"/>
                  <Grid Grid.Row="3" Grid.ColumnSpan="2" Name="CreateCharMapAdvancedPanel" Margin="0,6,0,0" Visibility="Visible">
                    <Grid.RowDefinitions>
                      <RowDefinition Height="Auto"/>
                      <RowDefinition Height="Auto"/>
                    </Grid.RowDefinitions>
                    <Grid.ColumnDefinitions>
                      <ColumnDefinition Width="Auto"/>
                      <ColumnDefinition Width="*"/>
                      <ColumnDefinition Width="Auto"/>
                      <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <TextBlock Grid.Row="0" Grid.Column="0" Text="Search for :" VerticalAlignment="Center" Margin="8,0,8,4"/>
                    <TextBox Grid.Row="0" Grid.Column="1" Name="CreateCharMapSearchBox" Margin="8,0,8,4"/>
                    <Button Grid.Row="0" Grid.Column="2" Name="CreateCharMapSearchBtn" Width="66" Margin="0,0,9,4" Style="{StaticResource RightPanelNavButtonStyle}">Search</Button>
                    <TextBlock Grid.Row="1" Grid.Column="0" Text="Code :" Margin="8,0,4,0" VerticalAlignment="Center"/>
                    <TextBlock Grid.Row="1" Grid.Column="1" Grid.ColumnSpan="3" Name="CreateCharMapCodePointText" Margin="-16,0,50,0" VerticalAlignment="Center" Foreground="Gray"/>
                  </Grid>
                </Grid>
              </TabItem>
            </TabControl>
            <Border Name="CreateIconTabsTopRule"
                    Height="1"
                    VerticalAlignment="Top"
                    HorizontalAlignment="Stretch"
                    Margin="-8,26,-8,0"
                    Background="{DynamicResource UiBorderBrush}"
                    IsHitTestVisible="False"/>
            </Grid>

            </Grid>
          </Border>
        </TabItem>

        <TabItem Name="MiscTab" Header="misc." Style="{StaticResource UiPanelTabItemStyle}" Margin="2,0,-2,-1">
          <Border Name="MiscPanelBorder" BorderBrush="{DynamicResource UiBorderBrush}" BorderThickness="1,1,1,0" CornerRadius="4,4,0,0" Padding="8" Margin="0" Background="{DynamicResource UiSurfaceBrush}">
            <Grid>
              <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
              </Grid.RowDefinitions>
              <TextBlock Grid.Row="0" Text="Extra Options &amp; Addons" FontWeight="SemiBold" Margin="0,0,0,8"/>
              <CheckBox Grid.Row="1" Name="MiscBlurGridWallpaperBox" Margin="0,10,0,0" Style="{DynamicResource UiCheckBoxStyle}">Blur app's wallpaper</CheckBox>
              <CheckBox Grid.Row="2" Name="MiscMatchScreenWallpaperBox" Margin="0,8,0,0" Style="{DynamicResource UiCheckBoxStyle}">Match app's wallpaper to current screen resolution</CheckBox>
              <CheckBox Grid.Row="3" Name="MiscDesktopPassthroughBox" Margin="0,8,0,0" Style="{DynamicResource UiCheckBoxStyle}">Remove app's wallpaper</CheckBox>
              <CheckBox Grid.Row="4" Name="MiscDisableDuplicateFlaggingBox" Margin="0,8,0,0" Style="{DynamicResource UiCheckBoxStyle}">Disable duplicate shortcut flagging</CheckBox>
              <StackPanel Grid.Row="5" Orientation="Horizontal" Margin="0,8,0,0" HorizontalAlignment="Left">
                <Button Name="MiscLaunchIconAllocatorBtn" Width="108" Height="42" Margin="0,0,8,0" Style="{StaticResource RightPanelNavButtonStyle}">
                  <StackPanel Orientation="Horizontal" VerticalAlignment="Center" HorizontalAlignment="Center">
                    <Image Name="MiscLaunchIconAllocatorBtnIcon" Width="32" Height="32" Margin="0,0,4,0" Stretch="Uniform" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
                    <TextBlock VerticalAlignment="Center" TextAlignment="Center" FontSize="10" LineHeight="11" Text="Launch&#x0a;Icon Allocator"/>
                  </StackPanel>
                </Button>
                <Button Name="MiscRestoreAdminToolsBtn" Width="116" Height="42" Style="{StaticResource RightPanelNavButtonStyle}">
                  <TextBlock VerticalAlignment="Center" TextAlignment="Center" FontSize="10" LineHeight="11" Text="Restore Windows&#x0a;Admin Tools"/>
                </Button>
              </StackPanel>
              <Grid Grid.Row="6" Margin="0,10,0,6">
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <TextBlock Name="MiscAddonsHeaderText" Grid.Column="0" Text="Addons:" FontWeight="SemiBold" Foreground="Gray" VerticalAlignment="Center"/>
                <Button Name="MiscAddonsRefreshBtn" Grid.Column="1" Width="24" Height="22" Padding="0" Margin="6,0,0,0" FontSize="13" Style="{StaticResource RightPanelNavButtonStyle}">↻</Button>
              </Grid>
              <Border Name="MiscAddonsPanelBorder" Grid.Row="7" BorderBrush="{DynamicResource UiAddonsPanelBorderBrush}" BorderThickness="1" CornerRadius="4" Padding="6" Margin="0,0,0,0" Background="{DynamicResource UiPanelBrush}">
                <Grid>
                  <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                  </Grid.RowDefinitions>
                  <Grid Grid.Row="0" Margin="0,0,0,6">
                    <Grid.ColumnDefinitions>
                      <ColumnDefinition Width="Auto"/>
                      <ColumnDefinition Width="*"/>
                      <ColumnDefinition Width="Auto"/>
                      <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <TextBlock Name="MiscAddonsSearchLabel" Grid.Column="0" VerticalAlignment="Center" Margin="0,0,6,0" Text="Search:"/>
                    <TextBox Name="MiscAddonsSearchBox" Grid.Column="1" Height="24" Margin="0,0,8,0" VerticalContentAlignment="Center"/>
                    <Button Name="MiscAddonsOpenFolderBtn" Grid.Column="2" Height="24" MinWidth="100" Margin="0,0,8,0" Style="{StaticResource RightPanelNavButtonStyle}">Open Directory</Button>
                    <Button Name="MiscAddonsCreateBtn" Grid.Column="3" Height="24" MinWidth="80" Style="{StaticResource RightPanelNavButtonStyle}">Create Addon</Button>
                  </Grid>
                  <ScrollViewer Name="MiscAddonsPanelScroll" Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" CanContentScroll="False" PanningMode="VerticalOnly">
                    <StackPanel>
                      <TextBlock Name="MiscAddonsEmptyText" TextWrapping="Wrap" Foreground="#747474" Margin="0,0,0,6" Text="No addon files found. Add .reg or .txt files into the Addons folder or click Create Addon."/>
                      <UniformGrid Name="MiscAddonsButtonsHost" Columns="2"/>
                    </StackPanel>
                  </ScrollViewer>
                </Grid>
              </Border>
            </Grid>
          </Border>
        </TabItem>
      </TabControl>

      <GridSplitter Name="MainPanelsSplitter" Grid.Column="1"
                    Width="10"
                    Margin="-9,0,-1,0"
                    HorizontalAlignment="Stretch"
                    VerticalAlignment="Stretch"
                    Background="Transparent"
                    ResizeDirection="Columns"
                    ResizeBehavior="PreviousAndNext"
                    ShowsPreview="False"
                    Panel.ZIndex="1000" />

      <Border Grid.Column="0" BorderBrush="Transparent" BorderThickness="0" CornerRadius="0" Padding="0">
        <Grid>
          <Grid.RowDefinitions>
            <RowDefinition Height="0"/>
            <RowDefinition Height="*"/>
          </Grid.RowDefinitions>

          <Border Name="GridWallpaperFauxTintOverlay"
                  Grid.Row="1"
                  Background="Transparent"
                  HorizontalAlignment="Stretch"
                  VerticalAlignment="Stretch"
                  IsHitTestVisible="False"
                  Panel.ZIndex="-2" />

          <Border Name="GridWallpaperFauxNoiseOverlay"
                  Grid.Row="1"
                  Background="Transparent"
                  HorizontalAlignment="Stretch"
                  VerticalAlignment="Stretch"
                  IsHitTestVisible="False"
                  Panel.ZIndex="-1" />

          <Border Name="GridSelectNameBand"
                  Grid.Row="1"
                  Background="{DynamicResource SelectNameAccentBrush}"
                  HorizontalAlignment="Left"
                  VerticalAlignment="Stretch"
                  Width="0"
                  Margin="0,0,0,0"
                  IsHitTestVisible="False"
                  Panel.ZIndex="0" />

<DataGrid Name="Grid"
                    Grid.Row="1"
                    AutoGenerateColumns="False"
                    CanUserAddRows="False"
                    IsReadOnly="False"
                    CanUserReorderColumns="True"
                    CanUserResizeColumns="True"
                    BorderThickness="0"
                    BorderBrush="Transparent"
                    SelectionMode="Extended"
                    HeadersVisibility="Column"
                    RowHeaderWidth="0"
                    GridLinesVisibility="None"
                    RowHeight="36"
                    VirtualizingPanel.IsVirtualizing="True"
                    VirtualizingPanel.VirtualizationMode="Recycling"
                    VirtualizingPanel.ScrollUnit="Pixel"
                    ScrollViewer.CanContentScroll="True"
                    ScrollViewer.VerticalScrollBarVisibility="Hidden"
                    ScrollViewer.HorizontalScrollBarVisibility="Hidden"
                    Background="Transparent"
                    Panel.ZIndex="1">

            <DataGrid.Resources>
              <SolidColorBrush x:Key="{x:Static SystemColors.HighlightBrushKey}" Color="#2e8cf8"/>
              <SolidColorBrush x:Key="{x:Static SystemColors.HighlightTextBrushKey}" Color="#FFFFFFFF"/>
              <SolidColorBrush x:Key="{x:Static SystemColors.InactiveSelectionHighlightBrushKey}" Color="#7f7f83"/>
              <SolidColorBrush x:Key="{x:Static SystemColors.InactiveSelectionHighlightTextBrushKey}" Color="#FFFFFFFF"/>
            </DataGrid.Resources>
            <DataGrid.ColumnHeaderStyle>
              <Style TargetType="{x:Type DataGridColumnHeader}">
                <Setter Property="Background" Value="{DynamicResource UiSurfaceBrush}"/>
                <Setter Property="BorderBrush" Value="{DynamicResource UiSeparatorBrush}"/>
                <Setter Property="BorderThickness" Value="0"/>
                <Setter Property="SeparatorBrush" Value="{DynamicResource UiSeparatorBrush}"/>
                <Setter Property="Height" Value="30"/>
                <Setter Property="HorizontalContentAlignment" Value="Left"/>
                <Setter Property="VerticalContentAlignment" Value="Center"/>
                <Setter Property="Padding" Value="6,0,6,2"/>
                <Setter Property="Foreground" Value="{DynamicResource GridHeaderTextBrush}"/>
                <Setter Property="Template">
                  <Setter.Value>
                    <ControlTemplate TargetType="{x:Type DataGridColumnHeader}">
                      <Grid SnapsToDevicePixels="True">
                        <Border Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}"
                                Margin="1,0,0,0">
                          <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                            VerticalAlignment="{TemplateBinding VerticalContentAlignment}"
                                            TextElement.Foreground="{TemplateBinding Foreground}"
                                            Margin="{TemplateBinding Padding}"
                                            RecognizesAccessKey="True"/>
                        </Border>
                        <Rectangle Width="1"
                                   HorizontalAlignment="Left"
                                   VerticalAlignment="Stretch"
                                   Fill="{DynamicResource UiSeparatorBrush}"
                                   IsHitTestVisible="False"
                                   Panel.ZIndex="2"/>
                        <Thumb x:Name="PART_LeftHeaderGripper"
                               Width="8"
                               HorizontalAlignment="Left"
                               Cursor="SizeWE"
                               Background="Transparent"
                               Opacity="0"/>
                        <Thumb x:Name="PART_RightHeaderGripper"
                               Width="8"
                               HorizontalAlignment="Right"
                               Cursor="SizeWE"
                               Background="Transparent"
                               Opacity="0"/>
                      </Grid>
                    </ControlTemplate>
                  </Setter.Value>
                </Setter>
              </Style>
            </DataGrid.ColumnHeaderStyle>
            <DataGrid.CellStyle>
              <Style TargetType="{x:Type DataGridCell}">
                <Setter Property="BorderBrush" Value="Transparent"/>
                <Setter Property="BorderThickness" Value="0"/>
                <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
                <Style.Triggers>
                  <Trigger Property="IsSelected" Value="True">
                    <Setter Property="BorderBrush" Value="Transparent"/>
                    <Setter Property="BorderThickness" Value="0"/>
                  </Trigger>
                </Style.Triggers>
              </Style>
            </DataGrid.CellStyle>

            <!-- 4. No StaticResources in XAML block -->
            <DataGrid.Columns>

               <!-- Select -->
 <DataGridTemplateColumn Header="" Width="65" MinWidth="65" MaxWidth="65" CanUserResize="False" CanUserReorder="False">
  <DataGridTemplateColumn.HeaderStyle>
    <Style TargetType="{x:Type DataGridColumnHeader}">
      <Setter Property="Background" Value="{DynamicResource UiSurfaceBrush}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource UiSeparatorBrush}"/>
      <Setter Property="BorderThickness" Value="0"/>
      <Setter Property="SeparatorBrush" Value="{DynamicResource UiSeparatorBrush}"/>
      <Setter Property="Height" Value="30"/>
      <Setter Property="HorizontalContentAlignment" Value="Center"/>
      <Setter Property="Foreground" Value="{DynamicResource GridHeaderTextBrush}"/>
      <Setter Property="VerticalContentAlignment" Value="Center"/>
      <Setter Property="Padding" Value="6,2,6,2"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="{x:Type DataGridColumnHeader}">
            <Border Background="{TemplateBinding Background}"
                    BorderBrush="{TemplateBinding BorderBrush}"
                    BorderThickness="{TemplateBinding BorderThickness}"
                    SnapsToDevicePixels="True">
              <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                VerticalAlignment="{TemplateBinding VerticalContentAlignment}"
                                TextElement.Foreground="{TemplateBinding Foreground}"
                                Margin="{TemplateBinding Padding}"
                                RecognizesAccessKey="True"/>
            </Border>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
  </DataGridTemplateColumn.HeaderStyle>
  <DataGridTemplateColumn.CellStyle>
     <Style TargetType="{x:Type DataGridCell}">
        <Setter Property="Background" Value="{DynamicResource SelectNameAccentBrush}"/>
        <Setter Property="Foreground" Value="White"/>
        <Setter Property="BorderBrush" Value="Transparent"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Padding" Value="0"/>
        <Setter Property="Template">
          <Setter.Value>
            <ControlTemplate TargetType="{x:Type DataGridCell}">
              <Border Background="{TemplateBinding Background}"
                      BorderBrush="Transparent"
                      BorderThickness="0"
                      SnapsToDevicePixels="True">
                <ContentPresenter SnapsToDevicePixels="{TemplateBinding SnapsToDevicePixels}"/>
              </Border>
            </ControlTemplate>
          </Setter.Value>
        </Setter>
        <Style.Triggers>
          <Trigger Property="IsSelected" Value="True">
            <Setter Property="Background" Value="{DynamicResource SelectNameAccentBrush}"/>
            <Setter Property="BorderBrush" Value="Transparent"/>
            <Setter Property="BorderThickness" Value="0"/>
          </Trigger>
        </Style.Triggers>
      </Style>
   </DataGridTemplateColumn.CellStyle>
   <DataGridTemplateColumn.CellTemplate>
     <DataTemplate>
<CheckBox IsChecked="{Binding Selected, Mode=TwoWay, UpdateSourceTrigger=PropertyChanged}"
          Tag="SelectCascade"
          HorizontalAlignment="Center"
          VerticalAlignment="Center"
          Focusable="False">
        <CheckBox.Style>
          <Style TargetType="CheckBox">
            <Setter Property="Visibility" Value="Visible"/>
            <Setter Property="Background" Value="{DynamicResource SelectCheckboxFillBrush}"/>
            <Setter Property="BorderBrush" Value="{DynamicResource SelectCheckboxBorderBrush}"/>
            <Setter Property="BorderThickness" Value="0.5"/>
            <Setter Property="Foreground" Value="{DynamicResource SelectCheckboxGlyphBrush}"/>
            <Setter Property="Template">
              <Setter.Value>
                <ControlTemplate TargetType="CheckBox">
                  <Grid Width="12" Height="12" Background="Transparent" SnapsToDevicePixels="True">
                    <Border x:Name="SelectBox"
                            Background="{TemplateBinding Background}"
                            BorderBrush="{TemplateBinding BorderBrush}"
                            BorderThickness="{TemplateBinding BorderThickness}"
                            CornerRadius="2.5"/>
                    <Path x:Name="SelectCheck"
                          Data="M 2 6 L 5 9 L 10 3"
                          Stroke="{TemplateBinding Foreground}"
                          StrokeThickness="1.7"
                          StrokeStartLineCap="Round"
                          StrokeEndLineCap="Round"
                          StrokeLineJoin="Round"
                          SnapsToDevicePixels="True"
                          Visibility="Collapsed"/>
                  </Grid>
                  <ControlTemplate.Triggers>
                    <Trigger Property="IsChecked" Value="True">
                      <Setter TargetName="SelectCheck" Property="Visibility" Value="Visible"/>
                    </Trigger>
                    <Trigger Property="IsChecked" Value="{x:Null}">
                      <Setter TargetName="SelectCheck" Property="Visibility" Value="Visible"/>
                    </Trigger>
                  </ControlTemplate.Triggers>
                </ControlTemplate>
              </Setter.Value>
            </Setter>
            <Style.Triggers>
              <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                <Setter Property="Visibility" Value="Collapsed"/>
              </DataTrigger>
              <DataTrigger Binding="{Binding IsWindowsSecurityProxy}" Value="True">
                <Setter Property="Visibility" Value="Collapsed"/>
              </DataTrigger>
              <DataTrigger Binding="{Binding IsSettingsProxy}" Value="True">
                <Setter Property="Visibility" Value="Collapsed"/>
              </DataTrigger>
            </Style.Triggers>
          </Style>
        </CheckBox.Style>
                 
         <CheckBox.LayoutTransform>
           <ScaleTransform ScaleX="1.4" ScaleY="1.4"/>
         </CheckBox.LayoutTransform>
       </CheckBox>
     </DataTemplate>
   </DataGridTemplateColumn.CellTemplate>
 </DataGridTemplateColumn>


              <!-- 73 Pending -->
              <DataGridTemplateColumn Header="Pending" Width="55" MinWidth="55" MaxWidth="55" CanUserResize="False" CanUserReorder="False" IsReadOnly="True">
                <DataGridTemplateColumn.CellTemplate>
                  <DataTemplate>
                    <Border CornerRadius="5"
                            Background="#851a1a1a"
                            VerticalAlignment="Center"
                            HorizontalAlignment="Center"
                            Padding="2,2,2,2"
                            Margin="-2,-2,-2,-2"
                            IsHitTestVisible="False">
                      <Border.Style>
                        <Style TargetType="Border">
                          <Setter Property="Visibility" Value="Visible"/>
                          <Style.Triggers>
                            <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                              <Setter Property="Visibility" Value="Collapsed"/>
                            </DataTrigger>
                            <DataTrigger Binding="{Binding PendingLabelRows.Count}" Value="0">
                              <Setter Property="Visibility" Value="Collapsed"/>
                            </DataTrigger>
                            <DataTrigger Binding="{Binding PendingLabel}" Value="">
                              <Setter Property="Visibility" Value="Collapsed"/>
                            </DataTrigger>
                            <DataTrigger Binding="{Binding PendingLabel}" Value="{x:Null}">
                              <Setter Property="Visibility" Value="Collapsed"/>
                            </DataTrigger>
                          </Style.Triggers>
                        </Style>
                      </Border.Style>
                      <ItemsControl ItemsSource="{Binding PendingLabelRows}"
                                    HorizontalAlignment="Center"
                                    VerticalAlignment="Center">
                        <ItemsControl.ItemsPanel>
                          <ItemsPanelTemplate>
                            <StackPanel Orientation="Vertical"/>
                          </ItemsPanelTemplate>
                        </ItemsControl.ItemsPanel>
                        <ItemsControl.ItemTemplate>
                          <DataTemplate>
                            <Grid>
                            <TextBlock Text="{Binding Text}"
                                       Foreground="#FFFFFFFF"
                                       Opacity="1.00"
                                       FontWeight="Normal"
                                       FontSize="9"
                                       LineStackingStrategy="BlockLineHeight"
                                       LineHeight="9"
                                       TextAlignment="Left"
                                       HorizontalAlignment="Left"
                                       Margin="1,0,0,0"
                                       Visibility="Collapsed" IsHitTestVisible="False">
                              <TextBlock.Style>
                                <Style TargetType="TextBlock">
                                  <Setter Property="Visibility" Value="Visible"/>
                                  <Style.Triggers>
                                  </Style.Triggers>
                                </Style>
                              </TextBlock.Style>
                              <TextBlock.Effect>
                                <BlurEffect Radius="10.1"/>
                              </TextBlock.Effect>
                            </TextBlock>
                            <TextBlock Text="{Binding Text}"
                                       Foreground="#FFFFFFFF"
                                       Opacity="0.98"
                                       FontWeight="Normal"
                                       FontSize="9"
                                       LineStackingStrategy="BlockLineHeight"
                                       LineHeight="9"
                                       TextAlignment="Left"
                                       HorizontalAlignment="Left"
                                       Margin="1,0,0,0"
                                       Visibility="Collapsed" IsHitTestVisible="False">
                              <TextBlock.Style>
                                <Style TargetType="TextBlock">
                                  <Setter Property="Visibility" Value="Visible"/>
                                  <Style.Triggers>
                                  </Style.Triggers>
                                </Style>
                              </TextBlock.Style>
                              <TextBlock.Effect>
                                <BlurEffect Radius="11.1"/>
                              </TextBlock.Effect>
                            </TextBlock>
                            <TextBlock Text="{Binding Text}"
                                       Foreground="#FFFFFFFF"
                                       Opacity="1.00"
                                       FontWeight="Normal"
                                       FontSize="9"
                                       LineStackingStrategy="BlockLineHeight"
                                       LineHeight="9"
                                       TextAlignment="Left"
                                       HorizontalAlignment="Left"
                                       Margin="1,0,0,0"
                                       Visibility="Collapsed" IsHitTestVisible="False">
                              <TextBlock.Style>
                                <Style TargetType="TextBlock">
                                  <Setter Property="Visibility" Value="Visible"/>
                                  <Style.Triggers>
                                  </Style.Triggers>
                                </Style>
                              </TextBlock.Style>
                            </TextBlock>
                             <TextBlock Text="{Binding Text}"
                                        Foreground="{Binding Color}"
                                        FontWeight="Normal"
                                        FontSize="9"
                                        LineStackingStrategy="BlockLineHeight"
                                        LineHeight="9"
                                        TextAlignment="Left"
                                        HorizontalAlignment="Left"
                                        Margin="0"/>
                            </Grid>
                          </DataTemplate>
                        </ItemsControl.ItemTemplate>
                      </ItemsControl>
                    </Border>
                  </DataTemplate>
                </DataGridTemplateColumn.CellTemplate>
              </DataGridTemplateColumn>

<!-- 10 Name (indent applies to icon + text) -->
<DataGridTemplateColumn Header="Name" Width="256" MinWidth="256" CanUserResize="False" CanUserReorder="False">
  <DataGridTemplateColumn.HeaderStyle>
    <Style TargetType="{x:Type DataGridColumnHeader}">
      <Setter Property="Background" Value="{DynamicResource UiSurfaceBrush}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource UiSeparatorBrush}"/>
      <Setter Property="BorderThickness" Value="0,0,0,0"/>
      <Setter Property="SeparatorBrush" Value="{DynamicResource UiSeparatorBrush}"/>
      <Setter Property="Height" Value="30"/>
      <Setter Property="HorizontalContentAlignment" Value="Left"/>
      <Setter Property="VerticalContentAlignment" Value="Center"/>
      <Setter Property="Padding" Value="65,2,6,2"/>
      <Setter Property="Foreground" Value="{DynamicResource GridHeaderTextBrush}"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="{x:Type DataGridColumnHeader}">
            <Border Background="{TemplateBinding Background}"
                    BorderBrush="{TemplateBinding BorderBrush}"
                    BorderThickness="{TemplateBinding BorderThickness}"
                    SnapsToDevicePixels="True">
              <StackPanel Orientation="Horizontal"
                          HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                          VerticalAlignment="{TemplateBinding VerticalContentAlignment}"
                          Margin="{TemplateBinding Padding}">
                <ContentPresenter TextElement.Foreground="{TemplateBinding Foreground}"
                                  RecognizesAccessKey="True"/>
                <TextBlock x:Name="NameSortGlyph"
                           Margin="5,0,0,0"
                           VerticalAlignment="Center"
                           Foreground="{TemplateBinding Foreground}"
                           FontSize="10"
                           Visibility="Collapsed"
                           Text="?"/>
              </StackPanel>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="SortDirection" Value="Ascending">
                <Setter TargetName="NameSortGlyph" Property="Visibility" Value="Visible"/>
                <Setter TargetName="NameSortGlyph" Property="Text" Value=" A→z"/>
              </Trigger>
              <Trigger Property="SortDirection" Value="Descending">
                <Setter TargetName="NameSortGlyph" Property="Visibility" Value="Visible"/>
                <Setter TargetName="NameSortGlyph" Property="Text" Value=" Z→a"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
  </DataGridTemplateColumn.HeaderStyle>
  <DataGridTemplateColumn.CellStyle>
    <Style TargetType="{x:Type DataGridCell}">
      <Setter Property="Background" Value="{DynamicResource SelectNameAccentBrush}"/>
      <Setter Property="Foreground" Value="{DynamicResource NameColumnTextBrush}"/>
      <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
    </Style>
  </DataGridTemplateColumn.CellStyle>
  <DataGridTemplateColumn.CellTemplate>
    <DataTemplate>
      <Grid VerticalAlignment="Center">
        <Border Margin="0,0,30,0" ClipToBounds="False" Background="Transparent">
          <Border.OpacityMask>
            <LinearGradientBrush StartPoint="0,0" EndPoint="1,0">
              <GradientStop Offset="0.00" Color="#FFFFFFFF"/>
              <GradientStop Offset="0.82" Color="#FFFFFFFF"/>
              <GradientStop Offset="1.00" Color="#00FFFFFF"/>
            </LinearGradientBrush>
          </Border.OpacityMask>
          <StackPanel Orientation="Horizontal"
                      Margin="{Binding IndentMargin}"
                      VerticalAlignment="Center">
            <Border>
              <Border.Style>
                <Style TargetType="Border">
                  <Setter Property="Background" Value="{DynamicResource NameIconBoxAccentBrush}"/>
                  <Setter Property="CornerRadius" Value="1"/>
                  <Setter Property="Padding" Value="4"/>
                  <Setter Property="Margin" Value="0,0,8,0"/>
                  <Setter Property="Visibility" Value="Visible"/>
                  <Style.Triggers>
                    <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                      <Setter Property="Visibility" Value="Collapsed"/>
                    </DataTrigger>
                    <DataTrigger Binding="{Binding ShowNameIconAccentBox}" Value="False">
                      <Setter Property="Background" Value="Transparent"/>
                      <Setter Property="Padding" Value="0"/>
                      <Setter Property="Margin" Value="0,0,8,0"/>
                    </DataTrigger>
                  </Style.Triggers>
                </Style>
              </Border.Style>
             <Grid Width="24" Height="24">
               <Image Width="24" Height="24"
                      Source="{Binding Icon}"
                      SnapsToDevicePixels="True"
                      RenderOptions.BitmapScalingMode="HighQuality"
                      RenderTransformOrigin="0.5,0.5">
                <Image.Style>
                  <Style TargetType="Image">
                    <Setter Property="Visibility" Value="Visible"/>
                    <Style.Triggers>
                      <DataTrigger Binding="{Binding RotateFolderIcon}" Value="True">
                        <Setter Property="Visibility" Value="Collapsed"/>
                      </DataTrigger>
                    </Style.Triggers>
                  </Style>
                </Image.Style>
              </Image>
              <Viewbox Width="24" Height="24" Stretch="Uniform" IsHitTestVisible="False">
                <Viewbox.Style>
                  <Style TargetType="Viewbox">
                    <Setter Property="Visibility" Value="Collapsed"/>
                    <Style.Triggers>
                      <DataTrigger Binding="{Binding RotateFolderIcon}" Value="True">
                        <Setter Property="Visibility" Value="Visible"/>
                      </DataTrigger>
                    </Style.Triggers>
                  </Style>
                </Viewbox.Style>
                <Canvas Width="26" Height="22">
                  <Path Data="M 3 0 C 1 0 0 0 0 2 L 0 5 L 10 5 C 12 5 13 4 13 3 C 13 3 12 0 10 0 L 3 0"
                        Fill="#de9c00"/>
                  <Path Data="M 10 5 L 0 5 L 0 20 C 0 21 1 22 2 22 L 24 22 C 25 22 26 21 26 20 L 26 5 C 26 4 25 3 24 3 L 13 3 C 13 4 12 5 10 5">
                    <Path.Fill>
                      <LinearGradientBrush StartPoint="1,1" EndPoint="0,0">
                        <GradientStop Color="#f5b810" Offset="0.00"/>
                        <GradientStop Color="#ffd868" Offset="1.00"/>
                      </LinearGradientBrush>
                    </Path.Fill>
                  </Path>
                </Canvas>
              </Viewbox>
              <Image Width="11" Height="11"
                     Source="{Binding DuplicateTargetOverlayIcon}"
                     HorizontalAlignment="Right"
                     VerticalAlignment="Top"
                     Margin="{DynamicResource DuplicateOverlayIconMargin}"
                     SnapsToDevicePixels="True"
                     RenderOptions.BitmapScalingMode="HighQuality"
                     IsHitTestVisible="False"
                     Panel.ZIndex="30">
                <Image.Style>
                  <Style TargetType="Image">
                    <Setter Property="Visibility" Value="Collapsed"/>
                    <Style.Triggers>
                      <DataTrigger Binding="{Binding IsTargetTextDuplicate}" Value="True">
                        <Setter Property="Visibility" Value="Visible"/>
                      </DataTrigger>
                      <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                        <Setter Property="Visibility" Value="Collapsed"/>
                      </DataTrigger>
                    </Style.Triggers>
                  </Style>
                </Image.Style>
              </Image>
              <Image Width="17" Height="17"
                     Source="{Binding BrokenLinkOverlayIcon}"
                     HorizontalAlignment="Right"
                     VerticalAlignment="Bottom"
                     Margin="{DynamicResource BrokenOverlayIconMargin}"
                     SnapsToDevicePixels="True"
                     RenderOptions.BitmapScalingMode="HighQuality"
                     IsHitTestVisible="False"
                     Panel.ZIndex="40">
                <Image.Style>
                  <Style TargetType="Image">
                    <Setter Property="Visibility" Value="Collapsed"/>
                    <Style.Triggers>
                      <DataTrigger Binding="{Binding IsBrokenTarget}" Value="True">
                        <Setter Property="Visibility" Value="Visible"/>
                      </DataTrigger>
                      <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                        <Setter Property="Visibility" Value="Collapsed"/>
                      </DataTrigger>
                    </Style.Triggers>
                  </Style>
                </Image.Style>
              </Image>
            </Grid>
            </Border>
            <TextBlock Text="{Binding ViewName}"
                       FontFamily="Segoe UI Emoji, Segoe UI Symbol, Segoe UI"
                       TextOptions.TextRenderingMode="Auto"
                       VerticalAlignment="Center">
              <TextBlock.Style>
                <Style TargetType="TextBlock">
                  <Setter Property="Foreground" Value="{DynamicResource NameColumnTextBrush}"/>
                  <Setter Property="Cursor" Value="Arrow"/>
                  <Style.Triggers>
                    <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                      <Setter Property="FontWeight" Value="Normal"/>
                      <Setter Property="Foreground" Value="{DynamicResource NameColumnTextBrush}"/>
                      <Setter Property="FontSize" Value="13"/>
                    </DataTrigger>
                    <DataTrigger Binding="{Binding RowKind}" Value="Folder">
                      <Setter Property="Cursor" Value="Arrow"/>
                    </DataTrigger>
                    <DataTrigger Binding="{Binding IsStartupFolderRow}" Value="True">
                      <Setter Property="TextDecorations" Value="Underline"/>
                    </DataTrigger>
                    <DataTrigger Binding="{Binding Action}" Value="Delete">
                      <Setter Property="Foreground" Value="{DynamicResource NameColumnTextBrush}"/>
                      <Setter Property="TextDecorations" Value="Strikethrough"/>
                    </DataTrigger>
                  </Style.Triggers>
                </Style>
              </TextBlock.Style>
            </TextBlock>
          </StackPanel>
        </Border>
        <Grid Width="7"
              Height="7"
              HorizontalAlignment="Right"
              VerticalAlignment="Center"
              Margin="0,0,20,0"
              Panel.ZIndex="50"
              IsHitTestVisible="False">
          <Grid.Style>
            <Style TargetType="Grid">
              <Setter Property="Visibility" Value="Collapsed"/>
              <Style.Triggers>
                <DataTrigger Binding="{Binding ShowFolderChevron}" Value="True">
                  <Setter Property="Visibility" Value="Visible"/>
                </DataTrigger>
                <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                  <Setter Property="Visibility" Value="Collapsed"/>
                </DataTrigger>
              </Style.Triggers>
            </Style>
          </Grid.Style>
          <Path Name="FolderChevronPath"
                Data="{Binding FolderChevronData}"
                Stroke="{DynamicResource FolderCaretBrush}"
                Opacity="0.78"
                StrokeThickness="1.1"
                StrokeStartLineCap="Round"
                StrokeEndLineCap="Round"
                Stretch="Uniform"
                Visibility="Visible"/>
        </Grid>
      </Grid>
    </DataTemplate>
  </DataGridTemplateColumn.CellTemplate>

  <DataGridTemplateColumn.CellEditingTemplate>
