                     RenderOptions.BitmapScalingMode="HighQuality"
                     IsHitTestVisible="False"
                     Panel.ZIndex="40">
                <Image.Style>
                  <Style TargetType="Image">
                    <Setter Property="Visibility" Value="Collapsed"/>
                    <Style.Triggers>
                      <DataTrigger Binding="{Binding IsBrokenTarget}" Value="True">
