                      <TextBlock Text="{Binding Type}" VerticalAlignment="Center" FontSize="9" FontWeight="Normal" Foreground="#FFFFFFFF" Opacity="0.98" Margin="0,0,0,0" Visibility="Collapsed" IsHitTestVisible="False">
