                      <TextBlock Text="{Binding Type}" VerticalAlignment="Center" FontSize="9" FontWeight="Normal" Foreground="#FFFFFFFF" Opacity="1.00" Margin="0,0,0,0" Visibility="Collapsed" IsHitTestVisible="False">
                        <TextBlock.Style>
                          <Style TargetType="TextBlock">
                            <Setter Property="Visibility" Value="Visible"/>
