                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                            </Style.Triggers>
                          </Style>
                        </TextBlock.Style>
                      </TextBlock>
                      <TextBlock Text="{Binding Type}" VerticalAlignment="Center" FontSize="9" FontWeight="Normal">
                        <TextBlock.Style>
                          <Style TargetType="TextBlock">
                            <Setter Property="Visibility" Value="Visible"/>
                            <Setter Property="Foreground" Value="#57f357"/>
                            <Style.Triggers>
                              <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding RowKind}" Value="Folder">
                                <Setter Property="Foreground" Value="#f1cf0e"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding Type}" Value="Folder">
                                <Setter Property="Foreground" Value="#f1cf0e"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding IsStartupFolderRow}" Value="True">
                                <Setter Property="Foreground" Value="#b86cff"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding Type}" Value="Url">
                                <Setter Property="Foreground" Value="#45e2e7"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding Type}" Value="URL">
                                <Setter Property="Foreground" Value="#45e2e7"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding IsShellAppReplacementShortcut}" Value="True">
                                <Setter Property="Foreground" Value="#6eb4ff"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding IsAppsFolderDisplayProxy}" Value="True">
                                <Setter Property="Foreground" Value="#6eb4ff"/>
                                <Setter Property="Text" Value="Shortcut*"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding IsWindowsSecurityProxy}" Value="True">
                                <Setter Property="Foreground" Value="#b86cff"/>
                                <Setter Property="Text" Value="Shortcut*"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding IsSettingsProxy}" Value="True">
                                <Setter Property="Foreground" Value="#b86cff"/>
                                <Setter Property="Text" Value="Shortcut*"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding Type}" Value="ShellApp">
                                <Setter Property="Foreground" Value="#b86cff"/>
                                <Setter Property="Text" Value="Shortcut*"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding Action}" Value="Delete">
                                <Setter Property="Foreground" Value="#ee3131"/>
                                <Setter Property="TextDecorations" Value="Strikethrough"/>
                              </DataTrigger>
                            </Style.Triggers>
                          </Style>
                        </TextBlock.Style>
                      </TextBlock>
                    </Grid>
                  </DataTemplate>
                </DataGridTemplateColumn.CellTemplate>
