                              Background="#1a1a1a"
                              Opacity="0.52"
                              VerticalAlignment="Center"
                              HorizontalAlignment="Left"
                              Padding="2,0,2,0"
                              Margin="-2,2,2,0"
                              IsHitTestVisible="False">
                        <Border.Style>
                          <Style TargetType="Border">
                            <Setter Property="Visibility" Value="Visible"/>
                            <Style.Triggers>
                              <DataTrigger Binding="{Binding Path}" Value="">
                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding Path}" Value="{x:Null}">
                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding IsSelected, RelativeSource={RelativeSource AncestorType=DataGridRow}}" Value="True">
                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                            </Style.Triggers>
                          </Style>
                        </Border.Style>
                        <TextBlock Text="{Binding Path}"
                                   FontWeight="Normal"
                                   Opacity="0"
                                   IsHitTestVisible="False"/>
                      </Border>
                      <TextBlock Text="{Binding Path}"
                                 Foreground="#FFFFFFFF"
                                 FontWeight="Normal"
                                 Opacity="1.00"
                                 VerticalAlignment="Center"
                                 Margin="2,0,0,0"
                                 Visibility="Collapsed" IsHitTestVisible="False">
                        <TextBlock.Effect>
                          <BlurEffect Radius="10.1"/>
                        </TextBlock.Effect>
                        <TextBlock.Style>
                          <Style TargetType="TextBlock">
                            <Setter Property="Visibility" Value="Visible"/>
                            <Style.Triggers>
                              <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding IsSelected, RelativeSource={RelativeSource AncestorType=DataGridRow}}" Value="True">
                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                            </Style.Triggers>
                          </Style>
                        </TextBlock.Style>
                      </TextBlock>
                      <TextBlock Text="{Binding Path}"
                                 Foreground="#FFFFFFFF"
                                 FontWeight="Normal"
                                 Opacity="0.98"
                                 VerticalAlignment="Center"
                                 Margin="2,0,0,0"
                                 Visibility="Collapsed" IsHitTestVisible="False">
                        <TextBlock.Effect>
                          <BlurEffect Radius="11.1"/>
                        </TextBlock.Effect>
                        <TextBlock.Style>
                          <Style TargetType="TextBlock">
                            <Setter Property="Visibility" Value="Visible"/>
                            <Style.Triggers>
                              <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding IsSelected, RelativeSource={RelativeSource AncestorType=DataGridRow}}" Value="True">
                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                            </Style.Triggers>
                          </Style>
                        </TextBlock.Style>
                      </TextBlock>
                      <TextBlock Text="{Binding Path}"
                                 Foreground="#FFFFFFFF"
                                 FontWeight="Normal"
                                 Opacity="1.00"
                                 VerticalAlignment="Center"
                                 Margin="2,0,0,0"
                                 Visibility="Collapsed" IsHitTestVisible="False">
                        <TextBlock.Style>
                          <Style TargetType="TextBlock">
                            <Setter Property="Visibility" Value="Visible"/>
                            <Style.Triggers>
                              <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding IsSelected, RelativeSource={RelativeSource AncestorType=DataGridRow}}" Value="True">
                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                            </Style.Triggers>
                          </Style>
                        </TextBlock.Style>
                      </TextBlock>
                      <TextBox Text="{Binding Path}"
                               IsReadOnly="True"
                               BorderThickness="0"
                               Background="Transparent"
                               VerticalAlignment="Center"
                               SelectionTextBrush="White"
                               SelectionBrush="#0b3c91"
                               SelectionOpacity="0.40"
                               Padding="0"
                               Margin="0">
                        <TextBox.Style>
                          <Style TargetType="TextBox">
                            <Setter Property="Visibility" Value="Visible"/>
                            <Setter Property="Foreground" Value="White"/>
                            <Setter Property="FontWeight" Value="Normal"/>
                            <Setter Property="SelectionTextBrush" Value="White"/>
                            <Style.Triggers>
                              <DataTrigger Binding="{Binding IsAlphaSeparator}" Value="True">
                                <Setter Property="Visibility" Value="Collapsed"/>
                              </DataTrigger>
                              <DataTrigger Binding="{Binding Action}" Value="Delete">
                                <Setter Property="Foreground" Value="White"/>
                              </DataTrigger>
                              <MultiDataTrigger>
                                <MultiDataTrigger.Conditions>
                                  <Condition Binding="{Binding IsSelected, RelativeSource={RelativeSource AncestorType=DataGridRow}}" Value="True"/>
                                  <Condition Binding="{Binding IsKeyboardFocusWithin, RelativeSource={RelativeSource AncestorType=DataGrid}}" Value="True"/>
                                </MultiDataTrigger.Conditions>
                                <Setter Property="Foreground" Value="White"/>
                              </MultiDataTrigger>
                            </Style.Triggers>
                          </Style>
                        </TextBox.Style>
                      </TextBox>
                    </Grid>
                  </DataTemplate>
                </DataGridTemplateColumn.CellTemplate>
              </DataGridTemplateColumn>

            

            </DataGrid.Columns>
          </DataGrid>
          <Border Name="GridHeaderShadowBand"
                  Grid.Row="1"
                  Height="14"
                  HorizontalAlignment="Stretch"
                  VerticalAlignment="Top"
                  Margin="0,36,0,0"
                  Background="Transparent"
                  IsHitTestVisible="False"
                  Opacity="0"
                  Panel.ZIndex="2" />
          <Border Name="GridTopOverlay"
                  Grid.Row="1"
                  Background="Transparent"
                  Height="38"
                  HorizontalAlignment="Left"
                  VerticalAlignment="Top"
                  Margin="0,26,0,0"
                  IsHitTestVisible="False"
                  Panel.ZIndex="11" />
          <Thumb Name="GridTopMaskResizeThumb"
                 Grid.Row="1"
                 Height="6"
                 Width="180"
                 HorizontalAlignment="Left"
                 VerticalAlignment="Top"
                 Margin="0,64,0,0"
                 Cursor="SizeNS"
                 Opacity="0"
                 Background="Transparent"
                 Panel.ZIndex="13" />
          <Thumb Name="GridNameResizeThumb"
                 Grid.Row="1"
                 Width="10"
                 HorizontalAlignment="Left"
                 VerticalAlignment="Stretch"
                 Margin="0,26,0,0"
                 Cursor="SizeWE"
                 Opacity="0"
                 Panel.ZIndex="14">
            <Thumb.Template>
              <ControlTemplate TargetType="{x:Type Thumb}">
                <Border Background="Transparent" BorderBrush="Transparent" BorderThickness="0" CornerRadius="0"/>
              </ControlTemplate>
            </Thumb.Template>
          </Thumb>
          <ScrollBar Name="MidVScrollBar"
                     Grid.Row="1"
                     Orientation="Vertical"
                     Width="2"
                     Opacity="0.80"
                     Visibility="Collapsed"
                     RenderTransformOrigin="0.5,0.5"
                     HorizontalAlignment="Left"
                     VerticalAlignment="Stretch"
                     Margin="500,26,0,2"
                     Minimum="0"
                     Maximum="0"
                     SmallChange="24"
                     LargeChange="120"
                     IsTabStop="False"
                     Panel.ZIndex="12">
            <ScrollBar.Template>
              <ControlTemplate TargetType="{x:Type ScrollBar}">
                <Grid Name="MidScrollBarRoot" Background="Transparent" SnapsToDevicePixels="True">
                  <Grid.RowDefinitions>
                    <RowDefinition Height="14"/>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="14"/>
                  </Grid.RowDefinitions>

                  <RepeatButton x:Name="MidScrollBarLineUpButton"
                                Grid.Row="0"
                                Command="ScrollBar.LineUpCommand"
                                Focusable="False"
                                Background="{TemplateBinding Background}"
                                BorderBrush="Transparent"
                                BorderThickness="0"
                                Padding="0">
                    <RepeatButton.Template>
                      <ControlTemplate TargetType="{x:Type RepeatButton}">
                        <Border Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}"
                                Padding="{TemplateBinding Padding}">
                          <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                      </ControlTemplate>
                    </RepeatButton.Template>
                    <Path x:Name="MidScrollBarUpGlyph"
                          Data="M 4 9 L 7 7 L 10 9"
                          Width="10"
                          Height="10"
                          HorizontalAlignment="Center"
                          VerticalAlignment="Center"
                          Fill="Transparent"
                          Stroke="{DynamicResource MidScrollGlyphBrush}"
                          StrokeThickness="1.5"
                          StrokeStartLineCap="Round"
                          StrokeEndLineCap="Round"
                          Stretch="Uniform"/>
                  </RepeatButton>

                  <Border x:Name="MidScrollBarTrack"
                          Grid.Row="1"
                          Background="{TemplateBinding Background}"
                          CornerRadius="0"
                          Margin="0,0,0,0"/>

                  <Track x:Name="PART_Track"
                         Grid.Row="1"
                         IsDirectionReversed="True"
                         Focusable="False">
                    <Track.DecreaseRepeatButton>
                      <RepeatButton x:Name="MidScrollBarPageUpButton"
                                    Command="ScrollBar.PageUpCommand"
                                    Focusable="False"
                                    Opacity="0"
                                    BorderThickness="0"
                                    Background="Transparent"/>
                    </Track.DecreaseRepeatButton>
                    <Track.Thumb>
                      <Thumb x:Name="MidScrollBarThumb"
                             Background="{TemplateBinding Foreground}"
                             BorderBrush="#80FFFFFF"
                             BorderThickness="0">
                        <Thumb.Template>
                          <ControlTemplate TargetType="{x:Type Thumb}">
                            <Border x:Name="MidScrollBarThumbBorder"
                                    Background="{TemplateBinding Background}"
                                    BorderBrush="{TemplateBinding BorderBrush}"
                                    BorderThickness="{TemplateBinding BorderThickness}"
                                    CornerRadius="0"
                                    Opacity="0.99"/>
                            <ControlTemplate.Triggers>
                              <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="MidScrollBarThumbBorder" Property="Opacity" Value="1"/>
                                <Setter TargetName="MidScrollBarThumbBorder" Property="BorderBrush" Value="#D0FFFFFF"/>
                              </Trigger>
                              <Trigger Property="IsDragging" Value="True">
                                <Setter TargetName="MidScrollBarThumbBorder" Property="Opacity" Value="1"/>
                                <Setter TargetName="MidScrollBarThumbBorder" Property="BorderBrush" Value="#D0FFFFFF"/>
                              </Trigger>
                            </ControlTemplate.Triggers>
                          </ControlTemplate>
                        </Thumb.Template>
                      </Thumb>
                    </Track.Thumb>
                    <Track.IncreaseRepeatButton>
                      <RepeatButton x:Name="MidScrollBarPageDownButton"
                                    Command="ScrollBar.PageDownCommand"
                                    Focusable="False"
                                    Opacity="0"
                                    BorderThickness="0"
                                    Background="Transparent"/>
                    </Track.IncreaseRepeatButton>
                  </Track>

                  <RepeatButton x:Name="MidScrollBarLineDownButton"
                                Grid.Row="2"
                                Command="ScrollBar.LineDownCommand"
                                Focusable="False"
                                Background="{TemplateBinding Background}"
                                BorderBrush="Transparent"
                                BorderThickness="0"
                                Padding="0">
                    <RepeatButton.Template>
                      <ControlTemplate TargetType="{x:Type RepeatButton}">
                        <Border Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}"
                                Padding="{TemplateBinding Padding}">
                          <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                      </ControlTemplate>
                    </RepeatButton.Template>
                    <Path x:Name="MidScrollBarDownGlyph"
                          Data="M 4 9 L 7 11 L 10 9"
                          Width="10"
                          Height="10"
                          HorizontalAlignment="Center"
                          VerticalAlignment="Center"
                          Fill="Transparent"
                          Stroke="{DynamicResource MidScrollGlyphBrush}"
                          StrokeThickness="1.5"
                          StrokeStartLineCap="Round"
                          StrokeEndLineCap="Round"
                          Stretch="Uniform"/>
                  </RepeatButton>
                </Grid>
              </ControlTemplate>
            </ScrollBar.Template>
            <ScrollBar.RenderTransform>
              <TransformGroup>
                <ScaleTransform ScaleX="0.80" ScaleY="1"/>
                <TranslateTransform x:Name="MidScrollBarSlideTransform" X="0"/>
              </TransformGroup>
            </ScrollBar.RenderTransform>
          </ScrollBar>
        </Grid>
      </Border>
    </Grid>

    <Border Name="BottomStripBar"
            Grid.Row="3"
            Background="{DynamicResource BottomFrameAccentBrush}"
            Margin="0,0,0,0"
            Padding="0,0,0,0">
      <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
        <Border Name="BottomStripLogoAccentBox"
                Background="{DynamicResource SelectNameAccentBrushExact}"
                CornerRadius="0"
                Padding="17,12,17,12"
                Margin="0,0,8,0">
          <Grid Width="16" Height="16">
            <Viewbox Stretch="Fill">
              <Path Name="BottomStripLogoPath"
                    Fill="#FFFFFFFF"
                    Stretch="Uniform"
                    Data="M 0.55 0.45 H 1.025 L 1.025 0.025 L 0.55 0.09 Z M 0.15 0.15 L 0.15 0.45 H 0.5 L 0.5 0.1 Z M 0.15 0.5 L 0.15 0.79 L 0.5 0.84 L 0.5 0.5 Z M 0.55 0.5 L 0.55 0.85 L 1.025 0.925 L 1.025 0.5 Z"/>
            </Viewbox>
          </Grid>
        </Border>
      </StackPanel>
    </Border>
    <Grid Name="BusyOverlayHost"
          Grid.RowSpan="4"
          Visibility="Collapsed"
          IsHitTestVisible="True"
          Panel.ZIndex="950">
      <Border Background="#6A000000"/>
      <TextBlock Name="BusyOverlayStatusText"
                 Text="Working..."
                 FontSize="20"
                 HorizontalAlignment="Center"
                 VerticalAlignment="Center"
                 Foreground="#FFFFFFFF"
                 FontWeight="SemiBold"/>
    </Grid>
  </Grid>
</Window>
"@

$reader = New-Object System.Xml.XmlNodeReader $xaml

# ==============================================================================
# Settings / feature flags
# ==============================================================================

try { Set-StartupSplashStatus -Status "Building main window..." -Value 16 } catch {}
$window = [Windows.Markup.XamlReader]::Load($reader)
try { $script:window = $window } catch {}
try { Set-StartupSplashStatus -Status "Initializing controls..." -Value 28 } catch {}
try {
  $mainIcon = Get-ImageSourceFromIcon -IconPath (Join-Path $env:WINDIR 'explorer.exe') -IconIndex 15 -FallbackExePath (Join-Path $env:WINDIR 'explorer.exe')
  if ($mainIcon) { $window.Icon = $mainIcon }
} catch {}
try { $script:AppTitleBase = [string]$window.Title } catch {}
try { Apply-CustomWindowChrome -Window $window } catch {}
try { Enable-SoftWindowShadow -Window $window } catch {}
try { Update-WindowShadowByState -Window $window } catch {}
$window.Add_Closed({
  try { Save-UserPresetSettings } catch {}
  try { if ($script:CreateTargetDropBrokerPollTimer) { $script:CreateTargetDropBrokerPollTimer.Stop() } } catch {}
  try { $script:CreateTargetDropBrokerStarted = $false } catch {}
  try {
    $xf = ''
    try { $xf = [string]$script:CreateTargetDropBrokerExchange } catch { $xf = '' }
    if (-not [string]::IsNullOrWhiteSpace($xf) -and (Test-Path -LiteralPath $xf)) {
      Remove-Item -LiteralPath $xf -Force -ErrorAction SilentlyContinue
    }
  } catch {}
  try { Close-StartupSplash } catch {}
  try { Stop-EmbeddedCharMap } catch {}
  try { [System.Windows.Threading.Dispatcher]::CurrentDispatcher.InvokeShutdown() } catch { }
})

if (-not (Test-Path variable:script:UserPresetFileName)) { $script:UserPresetFileName = 'user-presets.json' }

function Get-UserPresetFilePath {
  try {
    $root = ''
    try { $root = [string]$PSScriptRoot } catch { $root = '' }
    if ([string]::IsNullOrWhiteSpace($root)) {
      try { $root = Split-Path -Parent $PSCommandPath } catch { $root = '' }
    }
    if ([string]::IsNullOrWhiteSpace($root)) {
      try { $root = (Get-Location).Path } catch { $root = '.' }
    }
    $dir = Join-Path $root 'User Settings'
    return (Join-Path $dir $script:UserPresetFileName)
  } catch { return $null }
}

function Get-FirstLaunchGuideTipMarkerPaths {
  try {
    $out = New-Object System.Collections.Generic.List[string]
    $addPath = {
      param([string]$PathValue)
      try {
        $p = [string]$PathValue
        if ([string]::IsNullOrWhiteSpace($p)) { return }
        $pn = ''
        try { $pn = [string]([System.IO.Path]::GetFullPath($p)).Trim() } catch { $pn = $p.Trim() }
        if ([string]::IsNullOrWhiteSpace($pn)) { return }
        foreach ($ep in @($out.ToArray())) {
          try {
            if ([string]$ep -ieq [string]$pn) { return }
          } catch {}
        }
        [void]$out.Add($pn)
      } catch {}
    }

    try {
      $commonData = [string][Environment]::GetFolderPath([Environment+SpecialFolder]::CommonApplicationData)
      if (-not [string]::IsNullOrWhiteSpace($commonData)) {
        $machineDir = Join-Path $commonData 'Start Menu Lite Tools'
        $machineFlag = Join-Path $machineDir 'first-launch-guide-tip.shown'
        & $addPath $machineFlag
      }
    } catch {}

    try {
      $presetPath = [string](Get-UserPresetFilePath)
      if (-not [string]::IsNullOrWhiteSpace($presetPath)) {
        $presetDir = ''
        try { $presetDir = Split-Path -Parent $presetPath } catch { $presetDir = '' }
        if (-not [string]::IsNullOrWhiteSpace($presetDir)) {
          $fallbackFlag = Join-Path $presetDir 'first-launch-guide-tip.shown'
          & $addPath $fallbackFlag
        }
      }
    } catch {}

    return @($out.ToArray())
  } catch {
    return @()
  }
}

function Test-FirstLaunchGuideTipAlreadyShown {
  try {
    foreach ($fp in @(Get-FirstLaunchGuideTipMarkerPaths)) {
      if ([string]::IsNullOrWhiteSpace([string]$fp)) { continue }
      try {
        if (Test-Path -LiteralPath $fp -PathType Leaf) { return $true }
      } catch {}
    }
  } catch {}
  return $false
}

function Set-FirstLaunchGuideTipShown {
  try {
    foreach ($fp in @(Get-FirstLaunchGuideTipMarkerPaths)) {
      if ([string]::IsNullOrWhiteSpace([string]$fp)) { continue }
      try {
        $dir = ''
        try { $dir = Split-Path -Parent $fp } catch { $dir = '' }
        if (-not [string]::IsNullOrWhiteSpace($dir) -and -not (Test-Path -LiteralPath $dir -PathType Container)) {
          [void](New-Item -ItemType Directory -Path $dir -Force -ErrorAction Stop)
        }
        [System.IO.File]::WriteAllText($fp, '1', [System.Text.Encoding]::ASCII)
      } catch {}
    }
  } catch {}
}

function Show-FirstLaunchGuideTipIfNeeded {
  param(
    [Parameter(Mandatory=$false)][System.Windows.Window]$OwnerWindow = $null
  )
  try {
    if ([bool]$script:FirstLaunchGuideTipHandled) { return }
    $script:FirstLaunchGuideTipHandled = $true
  } catch {}

  $alwaysShow = $false
  try { $alwaysShow = [bool]$script:FirstLaunchGuideTipAlwaysShow } catch { $alwaysShow = $false }

  try {
    if ((-not $alwaysShow) -and (Test-FirstLaunchGuideTipAlreadyShown)) { return }
  } catch {}

  try {
    $dlg = New-Object System.Windows.Window
    $dlg.Title = 'Welcome'
    $dlg.SizeToContent = [System.Windows.SizeToContent]::WidthAndHeight
    $dlg.WindowStyle = [System.Windows.WindowStyle]::SingleBorderWindow
    $dlg.ResizeMode = [System.Windows.ResizeMode]::NoResize
    $dlg.ShowInTaskbar = $false
    $dlg.Topmost = $true
    if ($OwnerWindow) {
      try { $dlg.Owner = $OwnerWindow } catch {}
      try { $dlg.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterOwner } catch {}
    } else {
      try { $dlg.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterScreen } catch {}
    }

    $isDark = $false
    try { $isDark = ([string]$script:UiThemeMode -ieq 'Dark') } catch { $isDark = $false }
    $bgHex = if ($isDark) { '#202020' } else { '#F2F2F2' }
    $fgHex = if ($isDark) { '#D4D4D4' } else { '#202020' }
    $bdHex = if ($isDark) { '#3A3A3A' } else { '#BEBEBE' }
    $bgBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($bgHex))
    $fgBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($fgHex))
    $bdBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($bdHex))
    $dlg.Background = $bgBrush
    $dlg.Foreground = $fgBrush

    $rootBorder = New-Object System.Windows.Controls.Border
    $rootBorder.Padding = [System.Windows.Thickness]::new(12)
    $rootBorder.BorderThickness = [System.Windows.Thickness]::new(1)
    $rootBorder.BorderBrush = $bdBrush
    $rootBorder.Background = $bgBrush

    $panel = New-Object System.Windows.Controls.StackPanel
    $panel.Orientation = [System.Windows.Controls.Orientation]::Vertical

    $msg = New-Object System.Windows.Controls.TextBlock
    $msg.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $msg.MaxWidth = 250
    $msg.Margin = [System.Windows.Thickness]::new(0,0,0,14)
    $msg.Foreground = $fgBrush
    $msg.FontSize = 14
    [void]$msg.Inlines.Add((New-Object System.Windows.Documents.Run('Hi! Please use the ')))

    $guideIcon = $null
    try {
      $explorerPath = Join-Path $env:WINDIR 'explorer.exe'
      $guideIcon = Get-ImageSourceFromIcon -IconPath $explorerPath -IconIndex 5 -FallbackExePath $explorerPath
    } catch { $guideIcon = $null }
    if ($guideIcon) {
      $img = New-Object System.Windows.Controls.Image
      $img.Source = $guideIcon
      $img.Width = 16
      $img.Height = 16
      $img.Stretch = [System.Windows.Media.Stretch]::Uniform
      $img.Margin = [System.Windows.Thickness]::new(0,0,4,-2)
      $inline = New-Object System.Windows.Documents.InlineUIContainer
      $inline.Child = $img
      [void]$msg.Inlines.Add($inline)
    }

    $guideRun = New-Object System.Windows.Documents.Run('Guide')
    $guideRun.FontWeight = [System.Windows.FontWeights]::SemiBold
    [void]$msg.Inlines.Add($guideRun)
    [void]$msg.Inlines.Add((New-Object System.Windows.Documents.Run(' (top right of the window) to familiarize yourself with the function of this program.')))

    $okBtn = New-Object System.Windows.Controls.Button
    $okBtn.Content = 'OK'
    $okBtn.MinWidth = 70
    $okBtn.Height = 40
    $okBtn.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
    $okBtn.Background = $bgBrush
    $okBtn.Foreground = $fgBrush
    $okBtn.BorderBrush = $bdBrush
    $okHoverHex = if ($isDark) { '#6A6A6A' } else { '#D2D2D2' }
    $okPressHex = if ($isDark) { '#5A5A5A' } else { '#C4C4C4' }
    $okBtnStyleXaml = @"
<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'
       xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml'
       TargetType='{x:Type Button}'>
  <Setter Property='Background' Value='$bgHex'/>
  <Setter Property='Foreground' Value='$fgHex'/>
  <Setter Property='BorderBrush' Value='$bdHex'/>
  <Setter Property='BorderThickness' Value='1'/>
  <Setter Property='Padding' Value='12,5,12,5'/>
  <Setter Property='Template'>
    <Setter.Value>
      <ControlTemplate TargetType='{x:Type Button}'>
        <Border x:Name='Bd'
                Background='{TemplateBinding Background}'
                BorderBrush='{TemplateBinding BorderBrush}'
                BorderThickness='{TemplateBinding BorderThickness}'
                CornerRadius='2'>
          <ContentPresenter HorizontalAlignment='Center'
                            VerticalAlignment='Center'
                            RecognizesAccessKey='True'/>
        </Border>
        <ControlTemplate.Triggers>
          <Trigger Property='IsMouseOver' Value='True'>
            <Setter TargetName='Bd' Property='Background' Value='$okHoverHex'/>
            <Setter TargetName='Bd' Property='BorderBrush' Value='$okHoverHex'/>
          </Trigger>
          <Trigger Property='IsPressed' Value='True'>
            <Setter TargetName='Bd' Property='Background' Value='$okPressHex'/>
            <Setter TargetName='Bd' Property='BorderBrush' Value='$okPressHex'/>
          </Trigger>
          <Trigger Property='IsEnabled' Value='False'>
            <Setter TargetName='Bd' Property='Opacity' Value='0.6'/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>
"@
    try { $okBtn.Style = [Windows.Markup.XamlReader]::Parse($okBtnStyleXaml) } catch {}
    $okBtn.Add_Click({
      param($s,$e)
      try { $dlg.DialogResult = $true } catch {}
      try { $dlg.Close() } catch {}
    })

    [void]$panel.Children.Add($msg)
    [void]$panel.Children.Add($okBtn)
    $rootBorder.Child = $panel
    $dlg.Content = $rootBorder

    try { [void]$dlg.ShowDialog() } catch {}
    if (-not $alwaysShow) {
      try { Set-FirstLaunchGuideTipShown } catch {}
    }
  } catch {}
}

function Load-UserPresetSettings {
  try {
    $presetPath = Get-UserPresetFilePath
    if ([string]::IsNullOrWhiteSpace([string]$presetPath)) { return }
    if (-not (Test-Path -LiteralPath $presetPath -PathType Leaf)) { return }
    $raw = ''
    try { $raw = [string](Get-Content -LiteralPath $presetPath -Raw -ErrorAction Stop) } catch { return }
    if ([string]::IsNullOrWhiteSpace($raw)) { return }
    $obj = $null
    try { $obj = $raw | ConvertFrom-Json -ErrorAction Stop } catch { return }
    if (-not $obj) { return }
    if ($obj.PSObject.Properties.Match('SortMode').Count -gt 0) {
      $m = [string]$obj.SortMode
      if ($m -in @('FoldersFirst','ItemsFirst','Mixed')) { $script:SortMode = $m }
    }
    if ($obj.PSObject.Properties.Match('ShowSeparators').Count -gt 0) { $script:ShowAlphaSeparators = [bool]$obj.ShowSeparators }
    if ($obj.PSObject.Properties.Match('ShowNestedFolders').Count -gt 0) { $script:ShowNestedFolderRows = [bool]$obj.ShowNestedFolders }
    if ($obj.PSObject.Properties.Match('ShowStartupFolder').Count -gt 0) { $script:ShowStartupFolder = [bool]$obj.ShowStartupFolder }
    if ($obj.PSObject.Properties.Match('ShowEmptyFolders').Count -gt 0) { $script:ShowEmptyFolders = [bool]$obj.ShowEmptyFolders }
    if ($obj.PSObject.Properties.Match('ExpandAllFolders').Count -gt 0) { $script:ExpandAllFolders = [bool]$obj.ExpandAllFolders }
    if ($obj.PSObject.Properties.Match('BlurGridWallpaper').Count -gt 0) { $script:GridWallpaperBlurEnabled = [bool]$obj.BlurGridWallpaper }
    if ($obj.PSObject.Properties.Match('MatchGridWallpaper').Count -gt 0) { $script:GridWallpaperMatchScreenResolution = [bool]$obj.MatchGridWallpaper }
    if ($obj.PSObject.Properties.Match('RemoveBackgroundImage').Count -gt 0) { $script:GridWallpaperDesktopPassthrough = [bool]$obj.RemoveBackgroundImage }
    if ($obj.PSObject.Properties.Match('DisableDuplicateShortcutFlagging').Count -gt 0) { $script:DisableDuplicateShortcutFlagging = [bool]$obj.DisableDuplicateShortcutFlagging }
    if ($obj.PSObject.Properties.Match('SystemIconSelectedCategories').Count -gt 0) {
      $script:SystemIconSelectedCategoriesPresetDefined = $true
      $tmpSel = New-Object System.Collections.Generic.List[string]
      try {
        foreach ($n in @($obj.SystemIconSelectedCategories)) {
          $cn = Normalize-SystemIconCategoryName -Name ([string]$n)
          if ([string]::IsNullOrWhiteSpace($cn)) { continue }
          if (-not $tmpSel.Contains($cn)) { [void]$tmpSel.Add($cn) }
        }
      } catch {}
      $script:SystemIconSelectedCategoriesPresetNames = @($tmpSel.ToArray())
    }
    if ($obj.PSObject.Properties.Match('UiThemeMode').Count -gt 0) {
      $t = [string]$obj.UiThemeMode
      if ($t -in @('Light','Dark')) { $script:UiThemeMode = $t }
    }
  } catch {}
}

function Save-UserPresetSettings {
  try {
    $presetPath = Get-UserPresetFilePath
    if ([string]::IsNullOrWhiteSpace([string]$presetPath)) { return }
    $presetDir = ''
    try { $presetDir = Split-Path -Parent $presetPath } catch { $presetDir = '' }
    if (-not [string]::IsNullOrWhiteSpace($presetDir)) {
      try { [void](New-Item -ItemType Directory -Path $presetDir -Force -ErrorAction Stop) } catch {}
    }
    $sortModeValue = [string]$script:SortMode
    try {
      if ($sortModeBox -and $sortModeBox.SelectedItem -and $sortModeBox.SelectedItem.Tag) {
        $sortModeValue = [string]$sortModeBox.SelectedItem.Tag
      }
    } catch {}
    if ($sortModeValue -notin @('FoldersFirst','ItemsFirst','Mixed')) { $sortModeValue = 'Mixed' }
    $showSeparators = [bool]$script:ShowAlphaSeparators
    $showNested = [bool]$script:ShowNestedFolderRows
    $showStartup = [bool]$script:ShowStartupFolder
    $showEmpty = [bool]$script:ShowEmptyFolders
    $expandAll = [bool]$script:ExpandAllFolders
    $blurWall = [bool]$script:GridWallpaperBlurEnabled
    $matchWall = [bool]$script:GridWallpaperMatchScreenResolution
    $removeWall = [bool]$script:GridWallpaperDesktopPassthrough
    $disableDupFlag = [bool]$script:DisableDuplicateShortcutFlagging
    $systemIconSelCats = @()
    $themeMode = [string]$script:UiThemeMode
    try { if ($showAlphaSeparatorsBox) { $showSeparators = [bool]$showAlphaSeparatorsBox.IsChecked } } catch {}
    try { if ($showNestedFoldersBox) { $showNested = [bool]$showNestedFoldersBox.IsChecked } } catch {}
    try { if ($showStartupFolderBox) { $showStartup = [bool]$showStartupFolderBox.IsChecked } } catch {}
    try { if ($showEmptyFoldersBox) { $showEmpty = [bool]$showEmptyFoldersBox.IsChecked } } catch {}
    try { if ($expandAllFoldersBox) { $expandAll = [bool]$expandAllFoldersBox.IsChecked } } catch {}
    try { if ($miscBlurGridWallpaperBox) { $blurWall = [bool]$miscBlurGridWallpaperBox.IsChecked } } catch {}
    try { if ($miscMatchScreenWallpaperBox) { $matchWall = [bool]$miscMatchScreenWallpaperBox.IsChecked } } catch {}
    try { if ($miscDesktopPassthroughBox) { $removeWall = [bool]$miscDesktopPassthroughBox.IsChecked } } catch {}
    try { if ($miscDisableDuplicateFlaggingBox) { $disableDupFlag = [bool]$miscDisableDuplicateFlaggingBox.IsChecked } } catch {}
    try {
      $selKeys = New-Object System.Collections.Generic.List[string]
      if ($script:SystemIconSelectedCategories) {
        foreach ($k in @($script:SystemIconSelectedCategories.Keys)) {
          $cn = Normalize-SystemIconCategoryName -Name ([string]$k)
          if ([string]::IsNullOrWhiteSpace($cn)) { continue }
          if (-not $selKeys.Contains($cn)) { [void]$selKeys.Add($cn) }
        }
      }
      $systemIconSelCats = @($selKeys.ToArray() | Sort-Object)
    } catch { $systemIconSelCats = @() }
    if ($themeMode -notin @('Light','Dark')) { $themeMode = 'Light' }
    $payload = [ordered]@{
      SortMode = $sortModeValue
      ShowSeparators = [bool]$showSeparators
      ShowNestedFolders = [bool]$showNested
      ShowStartupFolder = [bool]$showStartup
      ShowEmptyFolders = [bool]$showEmpty
      ExpandAllFolders = [bool]$expandAll
      BlurGridWallpaper = [bool]$blurWall
      MatchGridWallpaper = [bool]$matchWall
      RemoveBackgroundImage = [bool]$removeWall
      DisableDuplicateShortcutFlagging = [bool]$disableDupFlag
      SystemIconSelectedCategories = @($systemIconSelCats)
      UiThemeMode = $themeMode
      SavedAt = (Get-Date).ToString('o')
    }
    $json = $payload | ConvertTo-Json -Depth 5
    [System.IO.File]::WriteAllText($presetPath, [string]$json, [System.Text.Encoding]::UTF8)
  } catch {}
}

function Get-RegistryAccentBrushRaw {
  $fbColor = [System.Windows.Media.Color]::FromArgb(255,32,32,32) # #202020
  $fallback = New-Object System.Windows.Media.SolidColorBrush($fbColor)
  try { $fallback.Freeze() } catch {}
  try {
    $accentValue = $null
    try {
      $acc = Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent' -ErrorAction Stop
      if ($acc.PSObject.Properties.Match('AccentColorMenu').Count -gt 0) {
        $accentValue = [uint32]$acc.AccentColorMenu
      } elseif ($acc.PSObject.Properties.Match('StartColorMenu').Count -gt 0) {
        $accentValue = [uint32]$acc.StartColorMenu
      }
    } catch {}
    if ($null -eq $accentValue) {
      try {
        $dwm = Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\DWM' -ErrorAction Stop
        if ($dwm.PSObject.Properties.Match('ColorizationColor').Count -gt 0) {
          $accentValue = [uint32]$dwm.ColorizationColor
        }
      } catch {}
    }
    if ($null -eq $accentValue) {
      return $fallback
    }
    $v = [uint32]$accentValue
    # Explorer\Accent DWORD is stored as AABBGGRR, not AARRGGBB.
    $a = [byte](($v -shr 24) -band 0xFF)
    $b = [byte](($v -shr 16) -band 0xFF)
    $g = [byte](($v -shr 8)  -band 0xFF)
    $r = [byte]( $v          -band 0xFF)
    if ($a -eq 0) { $a = 255 }
    $picked = [System.Windows.Media.Color]::FromArgb($a, $r, $g, $b)
    $brush = New-Object System.Windows.Media.SolidColorBrush($picked)
    try { $brush.Freeze() } catch {}
    return $brush
  } catch {
    return $fallback
  }
}

function Get-IsWindowsBuildAbove1809Runtime {
  try {
    $cv = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop
    $b = ''
    try { if ($cv.PSObject.Properties.Match('CurrentBuild').Count -gt 0) { $b = [string]$cv.CurrentBuild } } catch {}
    if ([string]::IsNullOrWhiteSpace($b)) {
      try { if ($cv.PSObject.Properties.Match('CurrentBuildNumber').Count -gt 0) { $b = [string]$cv.CurrentBuildNumber } } catch {}
    }
    $n = 0
    if ([int]::TryParse($b, [ref]$n)) {
      $isNew = ($n -gt 17763)
      try { $script:IsWindowsBuildAbove1809 = [bool]$isNew } catch {}
      return [bool]$isNew
    }
  } catch {}
  try {
    $v = [Environment]::OSVersion.Version
    if ($v) {
      $isNew = ([int]$v.Build -gt 17763)
      try { $script:IsWindowsBuildAbove1809 = [bool]$isNew } catch {}
      return [bool]$isNew
    }
  } catch {}
  try { return [bool]$script:IsWindowsBuildAbove1809 } catch { return $false }
}

function Get-IsWindowsBuildAtLeast19044Runtime {
  try {
    $cv = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop
    $b = ''
    try { if ($cv.PSObject.Properties.Match('CurrentBuild').Count -gt 0) { $b = [string]$cv.CurrentBuild } } catch {}
    if ([string]::IsNullOrWhiteSpace($b)) {
      try { if ($cv.PSObject.Properties.Match('CurrentBuildNumber').Count -gt 0) { $b = [string]$cv.CurrentBuildNumber } } catch {}
    }
    $n = 0
    if ([int]::TryParse($b, [ref]$n)) { return ($n -ge 19044) }
  } catch {}
  try {
    $v = [Environment]::OSVersion.Version
    if ($v) { return ([int]$v.Build -ge 19044) }
  } catch {}
  return $false
}

function Get-CurrentUserAccentBrush {
  $fbColor = [System.Windows.Media.Color]::FromArgb(255,32,32,32) # #202020
  $fallback = New-Object System.Windows.Media.SolidColorBrush($fbColor)
  try { $fallback.Freeze() } catch {}
  $lightOverrideColor = [System.Windows.Media.Color]::FromArgb(255,228,228,228) # #e4e4e4
  $lightOverride = New-Object System.Windows.Media.SolidColorBrush($lightOverrideColor)
  try { $lightOverride.Freeze() } catch {}
  try { $script:IsLightAccentOverrideActive = $false } catch {}
  try {
    # Read Windows mode directly from registry each time so UI mode-dependent colors stay in sync.
    $sysLight = Get-IsSystemLightMode
    $allowLightOverride = $false
    try { $allowLightOverride = [bool](Get-IsWindowsBuildAbove1809Runtime) } catch { $allowLightOverride = $false }
    try { $script:IsLightAccentOverrideActive = ([bool]$sysLight -and [bool]$allowLightOverride) } catch {}
    # Windows versions above 1809 only: if Windows mode is Light,
    # force program accent to #e4e4e4.
    if ($sysLight -and $allowLightOverride) {
      return $lightOverride
    }
    if ($sysLight -and -not $allowLightOverride) {
    }
    # Honor Windows setting: "Show accent color on Start, taskbar, and action center".
    # If disabled, force script fallback accent.
    try {
      $accentOnStart = $false
      $per = Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -ErrorAction Stop
      if ($per -and $per.PSObject.Properties.Match('ColorPrevalence').Count -gt 0) {
        $cp = 0
        if ([int]::TryParse([string]$per.ColorPrevalence, [ref]$cp) -and $cp -eq 1) {
          $accentOnStart = $true
        }
      }
      if (-not $accentOnStart) {
        return $fallback
      }
    } catch {
      return $fallback
    }
    return (Get-RegistryAccentBrushRaw)
  } catch {
    return $fallback
  }
}

function Get-IsSystemLightMode {
  try {
    # On Windows 10 build 1809 and below, ignore light/dark mode changes entirely.
    # This keeps legacy behavior stable and prevents theme-driven visual remapping.
    $allowThemeDrivenMode = $false
    try { $allowThemeDrivenMode = [bool](Get-IsWindowsBuildAbove1809Runtime) } catch { $allowThemeDrivenMode = $false }
    if (-not $allowThemeDrivenMode) {
      try { $script:IsLightAccentOverrideActive = $false } catch {}
      return $false
    }
    $perTheme = Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -ErrorAction Stop
    $hasSystem = ($perTheme -and $perTheme.PSObject.Properties.Match('SystemUsesLightTheme').Count -gt 0)
    $hasApps = ($perTheme -and $perTheme.PSObject.Properties.Match('AppsUseLightTheme').Count -gt 0)
    if ($hasSystem) {
      $v = 0
      if ([int]::TryParse([string]$perTheme.SystemUsesLightTheme, [ref]$v)) { return ($v -eq 1) }
    }
    if ($hasApps) {
      $v2 = 0
      if ([int]::TryParse([string]$perTheme.AppsUseLightTheme, [ref]$v2)) { return ($v2 -eq 1) }
    }
  } catch {}
  try { return [bool]$script:IsLightAccentOverrideActive } catch { return $false }
}

function Get-IsSystemLightModeRaw {
  try {
    $perTheme = Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -ErrorAction Stop
    if ($perTheme -and $perTheme.PSObject.Properties.Match('SystemUsesLightTheme').Count -gt 0) {
      $v = 0
      if ([int]::TryParse([string]$perTheme.SystemUsesLightTheme, [ref]$v)) { return ($v -eq 1) }
    }
    if ($perTheme -and $perTheme.PSObject.Properties.Match('AppsUseLightTheme').Count -gt 0) {
      $v2 = 0
      if ([int]::TryParse([string]$perTheme.AppsUseLightTheme, [ref]$v2)) { return ($v2 -eq 1) }
    }
  } catch {}
  try { return [bool]$script:LastKnownSystemLightMode } catch { return $false }
}

function Get-ThemeModeStateKeyRaw {
  try {
    $sys = -1
    $app = -1
    $perTheme = Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -ErrorAction Stop
    if ($perTheme -and $perTheme.PSObject.Properties.Match('SystemUsesLightTheme').Count -gt 0) {
      [void][int]::TryParse([string]$perTheme.SystemUsesLightTheme, [ref]$sys)
    }
    if ($perTheme -and $perTheme.PSObject.Properties.Match('AppsUseLightTheme').Count -gt 0) {
      [void][int]::TryParse([string]$perTheme.AppsUseLightTheme, [ref]$app)
    }
    return ("SYS={0};APP={1}" -f $sys, $app)
  } catch {
    return ''
  }
}

function Sync-ThemeContrastResources {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Window]$Window,
    [Parameter(Mandatory=$true)][bool]$IsLight
  )
  try {
    $nameTextColor = if ($IsLight) { [System.Windows.Media.Color]::FromArgb(255,0,0,0) } else { [System.Windows.Media.Color]::FromArgb(255,255,255,255) }
    $checkBorderColor = if ($IsLight) { [System.Windows.Media.Color]::FromArgb(200,90,90,90) } else { [System.Windows.Media.Color]::FromArgb(168,255,255,255) }
    $checkGlyphColor  = if ($IsLight) { [System.Windows.Media.Color]::FromArgb(220,70,70,70) } else { [System.Windows.Media.Color]::FromArgb(204,255,255,255) }
    $caretColor = if ($IsLight) { [System.Windows.Media.Color]::FromArgb(220,85,85,85) } else { [System.Windows.Media.Color]::FromArgb(204,255,255,255) }
    $scrollGlyphColor = if ($IsLight) { [System.Windows.Media.Color]::FromArgb(230,85,85,85) } else { [System.Windows.Media.Color]::FromArgb(255,255,255,255) }
    $nameTextRes = $Window.Resources['NameColumnTextBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($nameTextRes) { $nameTextRes.Color = $nameTextColor }
    $checkBorderRes = $Window.Resources['SelectCheckboxBorderBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($checkBorderRes) { $checkBorderRes.Color = $checkBorderColor }
    $checkGlyphRes = $Window.Resources['SelectCheckboxGlyphBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($checkGlyphRes) { $checkGlyphRes.Color = $checkGlyphColor }
    $caretRes = $Window.Resources['FolderCaretBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($caretRes) { $caretRes.Color = $caretColor }
    $scrollGlyphRes = $Window.Resources['MidScrollGlyphBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($scrollGlyphRes) { $scrollGlyphRes.Color = $scrollGlyphColor }
  } catch {}
}

function Get-DesktopBackgroundMode {
  try {
    $mode = 'Picture'
    try {
      $wpInfo = Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers' -ErrorAction Stop
      if ($wpInfo -and $wpInfo.PSObject.Properties.Match('BackgroundType').Count -gt 0) {
        switch ([int]$wpInfo.BackgroundType) {
          1 { $mode = 'SolidColor' }
          2 { $mode = 'Slideshow'  }
          default { $mode = 'Picture' }
        }
      }
    } catch {}
    return $mode
  } catch {
    return 'Picture'
  }
}

function Get-TranscodedWallpaperOriginalPath {
  try {
    $tic = (Get-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -Name TranscodedImageCache -ErrorAction Stop).TranscodedImageCache
    if ($tic -isnot [byte[]] -or $tic.Length -le 0) { return '' }
    $decoded = [System.Text.Encoding]::Unicode.GetString($tic)
    $decoded = $decoded.Trim([char]0)
    if ([string]::IsNullOrWhiteSpace($decoded)) { return '' }
    # Extract drive-qualified path from binary-decoded string blob.
    $m = [regex]::Match($decoded, '[A-Za-z]:\\[^\\/:*?""<>|]+(?:\\[^\\/:*?""<>|]+)*')
    if ($m.Success) { return [string]$m.Value }
  } catch {}
  return ''
}

function Get-CurrentDesktopSolidColorBrush {
  try {
    $raw = (Get-ItemProperty -Path 'HKCU:\Control Panel\Colors' -Name Background -ErrorAction Stop).Background
    $parts = @([string]$raw -split '\s+')
    if ($parts.Count -ge 3) {
      $r = [byte][Math]::Max(0,[Math]::Min(255,[int]$parts[0]))
      $g = [byte][Math]::Max(0,[Math]::Min(255,[int]$parts[1]))
      $b = [byte][Math]::Max(0,[Math]::Min(255,[int]$parts[2]))
      $br = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb(255,$r,$g,$b))
      try { $br.Freeze() } catch {}
      return $br
    }
  } catch {}
  return $null
}

function Test-PreferSolidGridBackground {
  try {
    $mode = Get-DesktopBackgroundMode
    if ($mode -eq 'SolidColor') { return $true }
    $desk = $null
    try { $desk = Get-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -ErrorAction Stop } catch {}
    $direct = ''
    try {
      if ($desk -and $desk.PSObject.Properties.Match('WallPaper').Count -gt 0) {
        $direct = [string]$desk.WallPaper
      }
    } catch {}
    # Fallback for systems where BackgroundType is stale/missing for solid color.
    if ([string]::IsNullOrWhiteSpace($direct)) { return $true }
  } catch {}
  return $false
}

function Get-CurrentUserWallpaperPath {
  try {
    $mode = Get-DesktopBackgroundMode
    $script:GridWallpaperMode = $mode
    if (Test-PreferSolidGridBackground) { return '' }
    $desk = $null
    try { $desk = Get-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -ErrorAction Stop } catch {}
    # Method 1 (direct registry): picture/single-image path.
    $direct = ''
    try {
      if ($desk -and $desk.PSObject.Properties.Match('WallPaper').Count -gt 0) {
        $direct = [string]$desk.WallPaper
      }
    } catch {}
    if ($mode -eq 'Picture' -and -not [string]::IsNullOrWhiteSpace($direct) -and (Test-Path -LiteralPath $direct)) {
      return $direct
    }
    # Method 2 (TranscodedImageCache): slideshow/cached picture source.
    $transcodedOriginal = Get-TranscodedWallpaperOriginalPath
    if (-not [string]::IsNullOrWhiteSpace($transcodedOriginal) -and (Test-Path -LiteralPath $transcodedOriginal)) {
      return $transcodedOriginal
    }
    # Direct path fallback for any mode.
    if (-not [string]::IsNullOrWhiteSpace($direct) -and (Test-Path -LiteralPath $direct)) {
      return $direct
    }
    # Cached current wallpaper file used by Windows.
    $transcoded = Join-Path $env:APPDATA 'Microsoft\Windows\Themes\TranscodedWallpaper'
    if (Test-Path -LiteralPath $transcoded) { return $transcoded }
    $cachedDir = Join-Path $env:APPDATA 'Microsoft\Windows\Themes\CachedFiles'
    if (Test-Path -LiteralPath $cachedDir) {
      $cand = Get-ChildItem -LiteralPath $cachedDir -File -ErrorAction SilentlyContinue |
        Sort-Object LastWriteTime -Descending | Select-Object -First 1
      if ($cand -and (Test-Path -LiteralPath $cand.FullName)) { return [string]$cand.FullName }
    }
  } catch {}
  return ''
}

function New-BlurredWallpaperImageSource {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Media.ImageSource]$Source,
    [double]$Scale = 0.35
  )
  try {
    if (-not ($Source -is [System.Windows.Media.Imaging.BitmapSource])) { return $Source }
    $src = [System.Windows.Media.Imaging.BitmapSource]$Source
    $w = 0; $h = 0
    try { $w = [int]$src.PixelWidth } catch { $w = 0 }
    try { $h = [int]$src.PixelHeight } catch { $h = 0 }
    if ($w -le 0 -or $h -le 0) { return $Source }
    if ($Scale -lt 0.0 -or $Scale -gt 1.0) { $Scale = 0.35 }
    # Strong Gaussian blur pass. Lower scale means stronger blur.
    $radius1 = [double]([Math]::Max(10.0, [Math]::Min(150.0, (12.0 + (1.0 - $Scale) * 84.0))))
    $radius2 = [double]([Math]::Max(8.0, [Math]::Min(64.0, ($radius1 * 0.70))))
    $applyPass = {
      param([System.Windows.Media.ImageSource]$passSource, [double]$passRadius)
      $imgCtrl = New-Object System.Windows.Controls.Image
      $imgCtrl.Source = $passSource
      $imgCtrl.Width = [double]$w
      $imgCtrl.Height = [double]$h
      $imgCtrl.Stretch = [System.Windows.Media.Stretch]::Fill
      $fx = New-Object System.Windows.Media.Effects.BlurEffect
      $fx.Radius = $passRadius
      try { $fx.KernelType = [System.Windows.Media.Effects.KernelType]::Gaussian } catch {}
      $imgCtrl.Effect = $fx
      $sz = New-Object System.Windows.Size([double]$w, [double]$h)
      $imgCtrl.Measure($sz)
      $imgCtrl.Arrange([System.Windows.Rect]::new(0.0,0.0,[double]$w,[double]$h))
      $imgCtrl.UpdateLayout()
      $rt = New-Object System.Windows.Media.Imaging.RenderTargetBitmap($w, $h, 96, 96, [System.Windows.Media.PixelFormats]::Pbgra32)
      $rt.Render($imgCtrl)
      return $rt
    }
    $pass1 = & $applyPass $src $radius1
    $pass2 = & $applyPass $pass1 $radius2
    try { $pass2.Freeze() } catch {}
    return $pass2
  } catch {
    return $Source
  }
}

function New-GridFauxBlurBackdropBrush {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Media.ImageSource]$Source,
    [double]$Scale = 0.35,
    [string]$CacheKey = '',
    [bool]$MatchScreen = $false
  )
  try {
    if (-not ($Source -is [System.Windows.Media.Imaging.BitmapSource])) { return $null }
    $src = [System.Windows.Media.Imaging.BitmapSource]$Source
    $w = [int]$src.PixelWidth
    $h = [int]$src.PixelHeight
    if ($w -le 0 -or $h -le 0) { return $null }
    $s = [Math]::Max(0.0, [Math]::Min(1.0, [double]$Scale))
    $strength = [Math]::Max(0.0, [Math]::Min(1.0, 1.0 - $s))
    # Strong faux blur: much lower downsample floor for substantial blur at high strength.
    $down = [double]([Math]::Max(0.05, [Math]::Min(0.07, 0.07 - (0.90 * $strength))))
    $k = "{0}|{1}x{2}|{3:N4}|ms={4}|p=8|r=2" -f $CacheKey,$w,$h,$down,([int]([bool]$MatchScreen))
    if ($script:GridWallpaperFauxBlurBrush -and ([string]$script:GridWallpaperFauxBlurKey -eq $k)) {
      return $script:GridWallpaperFauxBlurBrush
    }
    $ib = New-Object System.Windows.Media.ImageBrush
    # Apply the faux box blur twice: pass 2 is applied to pass 1 output.
    # Increase effective blur radius per pass by downsampling more aggressively.
    $downSafe = [double]([Math]::Max(0.04, [Math]::Min(0.42, (0.42 - (0.65 * $strength)))))
    $buildFauxPass = {
      param(
        [Parameter(Mandatory=$true)][System.Windows.Media.ImageSource]$PassSource,
        [bool]$UpscaleBack = $false
      )
      $tbSmall = New-Object System.Windows.Media.Imaging.TransformedBitmap
      $tbSmall.BeginInit()
      $tbSmall.Source = $PassSource
      $tbSmall.Transform = New-Object System.Windows.Media.ScaleTransform($downSafe, $downSafe)
      $tbSmall.EndInit()
      try { $tbSmall.Freeze() } catch {}
      if (-not $UpscaleBack) { return $tbSmall }
      $up = [double](1.0 / $downSafe)
      $tbSoft = New-Object System.Windows.Media.Imaging.TransformedBitmap
      $tbSoft.BeginInit()
      $tbSoft.Source = $tbSmall
      $tbSoft.Transform = New-Object System.Windows.Media.ScaleTransform($up, $up)
      $tbSoft.EndInit()
      try { $tbSoft.Freeze() } catch {}
      return $tbSoft
    }
    # Double blur strength again by running 8 upscale-style passes.
    $pass1 = & $buildFauxPass $src $true
    $pass2 = & $buildFauxPass $pass1 $true
    $pass3 = & $buildFauxPass $pass2 $true
    $pass4 = & $buildFauxPass $pass3 $true
    $pass5 = & $buildFauxPass $pass4 $true
    $pass6 = & $buildFauxPass $pass5 $true
    $pass7 = & $buildFauxPass $pass6 $true
    $pass8 = & $buildFauxPass $pass7 $true
    $ib.ImageSource = $pass8
    if ($MatchScreen) {
      $ib.Stretch = [System.Windows.Media.Stretch]::None
    } else {
      $ib.Stretch = [System.Windows.Media.Stretch]::UniformToFill
    }
    $ib.AlignmentX = [System.Windows.Media.AlignmentX]::Left
    $ib.AlignmentY = [System.Windows.Media.AlignmentY]::Bottom
    $ib.TileMode = [System.Windows.Media.TileMode]::None
    $ib.ViewportUnits = [System.Windows.Media.BrushMappingMode]::RelativeToBoundingBox
    try { [System.Windows.Media.RenderOptions]::SetBitmapScalingMode($ib, [System.Windows.Media.BitmapScalingMode]::LowQuality) } catch {}
    try { $ib.Freeze() } catch {}
    $script:GridWallpaperFauxBlurKey = $k
    $script:GridWallpaperFauxBlurBrush = $ib
    return $ib
  } catch {
    return $null
  }
}

function New-GridFauxNoiseTileBrush {
  param(
    [double]$NoiseOpacity = 0.05,
    [double]$TintOpacity = 0.02
  )
  try {
    $nop = [Math]::Max(0.0, [Math]::Min(0.20, [double]$NoiseOpacity))
    $top = [Math]::Max(0.0, [Math]::Min(0.08, [double]$TintOpacity))
    $cacheSig = [Math]::Round(($nop * 1000.0) + ($top * 100000.0), 0)
    if ($script:GridWallpaperFauxNoiseBrush -and ([Math]::Abs(([double]$script:GridWallpaperFauxNoiseOpacity - $cacheSig)) -lt 0.5)) {
      return $script:GridWallpaperFauxNoiseBrush
    }
    $dg = New-Object System.Windows.Media.DrawingGroup
    $ta = [byte][Math]::Round([Math]::Max(0.0, [Math]::Min(255.0, 255.0 * $top)))
    # Keep tint neutral/dark so faux blur does not look like a white wash.
    $tintBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb($ta, 0, 0, 0))
    $tintRect = New-Object System.Windows.Media.RectangleGeometry ([System.Windows.Rect]::new(0.0,0.0,40.0,18.0))
    $dg.Children.Add((New-Object System.Windows.Media.GeometryDrawing($tintBrush, $null, $tintRect)))
    $dots = @(
      @{ X=2;  Y=3;  A=220; C='W' }, @{ X=8;  Y=5;  A=180; C='B' }, @{ X=13; Y=2;  A=220; C='W' },
      @{ X=17; Y=9;  A=170; C='B' }, @{ X=22; Y=4;  A=210; C='W' }, @{ X=27; Y=7;  A=190; C='B' },
      @{ X=31; Y=2;  A=220; C='W' }, @{ X=35; Y=10; A=170; C='B' }, @{ X=4;  Y=12; A=200; C='W' },
      @{ X=10; Y=14; A=180; C='B' }, @{ X=15; Y=13; A=210; C='W' }, @{ X=21; Y=15; A=170; C='B' },
      @{ X=26; Y=12; A=210; C='W' }, @{ X=32; Y=14; A=180; C='B' }, @{ X=36; Y=13; A=220; C='W' }
    )
    foreach ($d in $dots) {
      $baseA = [int]$d.A
      $a = [byte][Math]::Round([Math]::Max(0.0, [Math]::Min(255.0, $baseA * $nop)))
      if ($a -le 0) { continue }
      if ([string]$d.C -eq 'B') {
        $c = [System.Windows.Media.Color]::FromArgb($a, 0, 0, 0)
      } else {
        $c = [System.Windows.Media.Color]::FromArgb($a, 255, 255, 255)
      }
      $b = New-Object System.Windows.Media.SolidColorBrush($c)
      $g = New-Object System.Windows.Media.RectangleGeometry ([System.Windows.Rect]::new([double]$d.X,[double]$d.Y,1.0,1.0))
      $dg.Children.Add((New-Object System.Windows.Media.GeometryDrawing($b, $null, $g)))
    }
    $db = New-Object System.Windows.Media.DrawingBrush($dg)
    $db.Viewport = [System.Windows.Rect]::new(0.0,0.0,40.0,18.0)
    $db.ViewportUnits = [System.Windows.Media.BrushMappingMode]::Absolute
    $db.TileMode = [System.Windows.Media.TileMode]::Tile
    $db.Stretch = [System.Windows.Media.Stretch]::None
    try { $db.Freeze() } catch {}
    $script:GridWallpaperFauxNoiseOpacity = $cacheSig
    $script:GridWallpaperFauxNoiseBrush = $db
    return $db
  } catch {
    return $null
  }
}

function Set-GridWallpaperFauxBlurOverlay {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Controls.DataGrid]$Grid,
    [bool]$Enable = $false,
    [bool]$SolidMode = $false,
    [System.Windows.Media.ImageSource]$WallpaperSource = $null,
    [string]$WallpaperKey = ''
  )
  try {
    $tint = $script:GridWallpaperFauxTintOverlay
    $noise = $script:GridWallpaperFauxNoiseOverlay
    if (-not $tint -or -not $noise) { return }
    if (-not $Enable -or $SolidMode) {
      $tint.Background = [System.Windows.Media.Brushes]::Transparent
      $noise.Background = [System.Windows.Media.Brushes]::Transparent
      return
    }
    $scale = 0.35
    try { $scale = [double]$script:GridWallpaperBlurScale } catch { $scale = 0.35 }
    $scale = [Math]::Max(0.0, [Math]::Min(1.0, $scale))
    $strength = [Math]::Max(0.0, [Math]::Min(1.0, 1.0 - $scale))
    $blurBrush = $null
    if ($WallpaperSource) {
      $matchScreen = $false
      try { $matchScreen = [bool]$script:GridWallpaperMatchScreenResolution } catch { $matchScreen = $false }
      $blurBrush = New-GridFauxBlurBackdropBrush -Source $WallpaperSource -Scale $scale -CacheKey $WallpaperKey -MatchScreen:$matchScreen
    }
    if ($blurBrush) {
      $tint.Background = $blurBrush
    } else {
      $tint.Background = [System.Windows.Media.Brushes]::Transparent
    }
    $nOpacity = [Math]::Max(0.003, [Math]::Min(0.035, 0.004 + (0.03 * $strength)))
    $tOpacity = [Math]::Max(0.0, [Math]::Min(0.03, 0.002 + (0.028 * $strength)))
    $noiseBrush = New-GridFauxNoiseTileBrush -NoiseOpacity $nOpacity -TintOpacity $tOpacity
    if ($noiseBrush) {
      $noise.Background = $noiseBrush
    } else {
      $noise.Background = [System.Windows.Media.Brushes]::Transparent
    }
  } catch {}
}

function Get-PrimaryScreenResolutionPx {
  try {
    $w = 0
    $h = 0
    try {
      $b = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
      if ($b) {
        $w = [int]$b.Width
        $h = [int]$b.Height
      }
    } catch {}
    if ($w -le 0 -or $h -le 0) {
      try { $w = [int][Math]::Round([double][System.Windows.SystemParameters]::PrimaryScreenWidth) } catch { $w = 0 }
      try { $h = [int][Math]::Round([double][System.Windows.SystemParameters]::PrimaryScreenHeight) } catch { $h = 0 }
    }
    if ($w -le 0 -or $h -le 0) { return $null }
    return [pscustomobject]@{ Width = $w; Height = $h }
  } catch {
    return $null
  }
}

function Try-ResizeWallpaperSourceToScreen {
  param([object]$Source)
  try {
    if (-not [bool]$script:GridWallpaperMatchScreenResolution) { return $Source }
    $bmp = $Source -as [System.Windows.Media.Imaging.BitmapSource]
    if (-not $bmp) { return $Source }
    $pw = 0.0; $ph = 0.0
    try { $pw = [double]$bmp.PixelWidth } catch { $pw = 0.0 }
    try { $ph = [double]$bmp.PixelHeight } catch { $ph = 0.0 }
    if ($pw -le 0.0 -or $ph -le 0.0) { return $Source }
    $res = Get-PrimaryScreenResolutionPx
    if (-not $res) { return $Source }
    $tw = [double]$res.Width
    $th = [double]$res.Height
    if ($tw -le 0.0 -or $th -le 0.0) { return $Source }
    $sx = ($tw / $pw)
    $sy = ($th / $ph)
    if ([Math]::Abs($sx - 1.0) -lt 0.01 -and [Math]::Abs($sy - 1.0) -lt 0.01) { return $Source }
    $tb = New-Object System.Windows.Media.Imaging.TransformedBitmap
    $tb.BeginInit()
    $tb.Source = $bmp
    $tb.Transform = New-Object System.Windows.Media.ScaleTransform($sx, $sy)
    $tb.EndInit()
    try { $tb.Freeze() } catch {}
    return $tb
  } catch {
    return $Source
  }
}

function Get-ElementScreenRectPx {
  param([System.Windows.FrameworkElement]$Element)
  try {
    if (-not $Element) { return $null }
    $wDip = 0.0
    $hDip = 0.0
    try { $wDip = [double]$Element.ActualWidth } catch { $wDip = 0.0 }
    try { $hDip = [double]$Element.ActualHeight } catch { $hDip = 0.0 }
    if ($wDip -le 1.0 -or $hDip -le 1.0) { return $null }
    $pt = $Element.PointToScreen([System.Windows.Point]::new(0.0, 0.0))
    $sx = 1.0; $sy = 1.0
    try {
      $ps = [System.Windows.PresentationSource]::FromVisual($Element)
      if ($ps -and $ps.CompositionTarget) {
        $m = $ps.CompositionTarget.TransformToDevice
        $sx = [double]$m.M11
        $sy = [double]$m.M22
        if ($sx -le 0.0) { $sx = 1.0 }
        if ($sy -le 0.0) { $sy = 1.0 }
      }
    } catch {}
    $x = [int][Math]::Round([double]$pt.X * $sx)
    $y = [int][Math]::Round([double]$pt.Y * $sy)
    $w = [int][Math]::Max(1, [int][Math]::Round($wDip * $sx))
    $h = [int][Math]::Max(1, [int][Math]::Round($hDip * $sy))
    return [pscustomobject]@{ X = $x; Y = $y; Width = $w; Height = $h }
  } catch {
    return $null
  }
}

function New-DesktopCaptureImageBrushForElement {
  param(
    [System.Windows.FrameworkElement]$Element,
    [switch]$HideMainWindowDuringCapture
  )
  try {
    $rc = Get-ElementScreenRectPx -Element $Element
    if (-not $rc) { return $null }
    $bmp = New-Object System.Drawing.Bitmap([int]$rc.Width, [int]$rc.Height, [System.Drawing.Imaging.PixelFormat]::Format32bppPArgb)
    $g = $null
    $ms = $null
    $mainWindow = $null
    $mainWindowOpacityPrev = 1.0
    $mainWindowHidden = $false
    try {
      if ($HideMainWindowDuringCapture) {
        try { $mainWindow = Get-Variable -Name window -Scope Script -ValueOnly -ErrorAction Stop } catch { $mainWindow = $null }
        if ($mainWindow -and ($mainWindow -is [System.Windows.Window])) {
          try {
            $mainWindowOpacityPrev = [double]$mainWindow.Opacity
            $mainWindow.Opacity = 0.0
            try { $mainWindow.UpdateLayout() } catch {}
            try { $mainWindow.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render) } catch {}
            $mainWindowHidden = $true
          } catch {}
        }
      }
      $g = [System.Drawing.Graphics]::FromImage($bmp)
      $g.CopyFromScreen([int]$rc.X, [int]$rc.Y, 0, 0, [System.Drawing.Size]::new([int]$rc.Width, [int]$rc.Height), [System.Drawing.CopyPixelOperation]::SourceCopy)
      $ms = New-Object System.IO.MemoryStream
      $bmp.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png)
      $ms.Position = 0
      $bi = New-Object System.Windows.Media.Imaging.BitmapImage
      $bi.BeginInit()
      $bi.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
      $bi.StreamSource = $ms
      $bi.EndInit()
      try { $bi.Freeze() } catch {}
      $ib = New-Object System.Windows.Media.ImageBrush
      $ib.ImageSource = $bi
      $ib.Stretch = [System.Windows.Media.Stretch]::Fill
      $ib.AlignmentX = [System.Windows.Media.AlignmentX]::Left
      $ib.AlignmentY = [System.Windows.Media.AlignmentY]::Top
      $ib.TileMode = [System.Windows.Media.TileMode]::None
      $ib.ViewportUnits = [System.Windows.Media.BrushMappingMode]::RelativeToBoundingBox
      $ib.Opacity = 1.0
      try { $ib.Freeze() } catch {}
      return $ib
    } finally {
      if ($mainWindowHidden -and $mainWindow) {
        try {
          $mainWindow.Opacity = [double]$mainWindowOpacityPrev
          try { $mainWindow.UpdateLayout() } catch {}
          try { $mainWindow.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render) } catch {}
        } catch {}
      }
      if ($g) { try { $g.Dispose() } catch {} }
      if ($ms) { try { $ms.Dispose() } catch {} }
      if ($bmp) { try { $bmp.Dispose() } catch {} }
    }
  } catch {
    return $null
  }
}

function Set-GridWallpaperBackground {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Controls.DataGrid]$Grid
  )
  try {
    $desktopPass = $false
    try { $desktopPass = [bool]$script:GridWallpaperDesktopPassthrough } catch { $desktopPass = $false }
    if ($desktopPass) {
      # Simple "remove background image" mode: force a fixed neutral background color.
      try { Set-GridWallpaperFauxBlurOverlay -Grid $Grid -Enable:$false -SolidMode:$false -WallpaperSource:$null -WallpaperKey:'' } catch {}
      $gridHost = $null
      try { $gridHost = [System.Windows.Media.VisualTreeHelper]::GetParent($Grid) } catch {}
      while ($gridHost -and -not ($gridHost -is [System.Windows.Controls.Border]) -and -not ($gridHost -is [System.Windows.Controls.Panel])) {
        try { $gridHost = [System.Windows.Media.VisualTreeHelper]::GetParent($gridHost) } catch { $gridHost = $null }
      }
      $flatBrush = $null
      try {
        $flatColor = [System.Windows.Media.Color]::FromRgb(0x69,0x6D,0x7F) # #696d7f
        $flatBrush = New-Object System.Windows.Media.SolidColorBrush($flatColor)
        try { $flatBrush.Freeze() } catch {}
      } catch { $flatBrush = [System.Windows.Media.Brushes]::DarkSlateGray }
      if ($gridHost -is [System.Windows.Controls.Border]) {
        try { $gridHost.Background = $flatBrush } catch {}
      } elseif ($gridHost -is [System.Windows.Controls.Panel]) {
        try { $gridHost.Background = $flatBrush } catch {}
      }
      try { $Grid.Background = [System.Windows.Media.Brushes]::Transparent } catch {}
      try { $Grid.RowBackground = [System.Windows.Media.Brushes]::Transparent } catch {}
      try { $Grid.AlternatingRowBackground = [System.Windows.Media.Brushes]::Transparent } catch {}
      try {
        # Keep internal DataGrid surfaces transparent so the select/name accent band
        # can remain visible in empty bottom rows.
        $q = New-Object System.Collections.Queue
        $q.Enqueue($Grid)
        while ($q.Count -gt 0) {
          $n = [System.Windows.DependencyObject]$q.Dequeue()
          $cc = 0
          try { $cc = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($n) } catch { $cc = 0 }
          for ($i=0; $i -lt $cc; $i++) {
            $ch = [System.Windows.Media.VisualTreeHelper]::GetChild($n,$i)
            if ($ch -is [System.Windows.Controls.ScrollViewer]) {
              try { $ch.Background = [System.Windows.Media.Brushes]::Transparent } catch {}
            } elseif ($ch -is [System.Windows.Controls.Panel]) {
              try {
                if ($ch -is [System.Windows.Controls.Primitives.DataGridRowsPresenter] -or
                    $ch -is [System.Windows.Controls.Primitives.DataGridCellsPresenter]) {
                  $ch.Background = [System.Windows.Media.Brushes]::Transparent
                }
              } catch {}
            }
            $q.Enqueue($ch)
          }
        }
      } catch {}
      return
    }
    if (-not $script:GridWallpaperEnabled) { return }
    $fauxWallpaperSource = $null
    $fauxWallpaperKey = ''
    $useFauxBlur = $false
    try { $useFauxBlur = [bool]$script:GridWallpaperBlurEnabled } catch { $useFauxBlur = $false }
    $mode = Get-DesktopBackgroundMode
    $preferSolid = $false
    try { $preferSolid = [bool](Test-PreferSolidGridBackground) } catch { $preferSolid = $false }
    if ($preferSolid) { $mode = 'SolidColor' }
    $script:GridWallpaperMode = $mode
    $wp = ''
    if (-not $preferSolid) {
      $wp = Get-CurrentUserWallpaperPath
    }
    $brush = $null
    if ($mode -eq 'SolidColor') {
      $solid = Get-CurrentDesktopSolidColorBrush
      if ($solid) { $brush = $solid }
    }
    if (-not $brush -and -not [string]::IsNullOrWhiteSpace($wp) -and (Test-Path -LiteralPath $wp)) {
      $img = $null
      $fs = $null
      try {
        # Stream-based decode handles TranscodedWallpaper and files without extension.
        $fs = [System.IO.File]::Open($wp, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        $img = [System.Windows.Media.Imaging.BitmapFrame]::Create($fs, [System.Windows.Media.Imaging.BitmapCreateOptions]::PreservePixelFormat, [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad)
      } catch {
        # Fallback URI decode for normal image files.
        try {
          $bi = New-Object System.Windows.Media.Imaging.BitmapImage
          $bi.BeginInit()
          $bi.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
          $bi.UriSource = New-Object System.Uri($wp, [System.UriKind]::Absolute)
          $bi.EndInit()
          $img = $bi
        } catch {}
      } finally {
        if ($fs) { try { $fs.Dispose() } catch {} }
      }
      if ($img) {
        try { $img = Try-ResizeWallpaperSourceToScreen -Source $img } catch {}
        $fauxWallpaperSource = $img
        $fauxWallpaperKey = [string]$wp
        # Faux blur path: keep wallpaper sharp and overlay cheap tint/noise layers.
        try { $img.Freeze() } catch {}
        $ib = New-Object System.Windows.Media.ImageBrush
        $ib.ImageSource = $img
        $matchScreen = $false
        try { $matchScreen = [bool]$script:GridWallpaperMatchScreenResolution } catch { $matchScreen = $false }
        if ($matchScreen) {
          # Preserve screen-sized wallpaper geometry (crop naturally in smaller grid area)
          # instead of scaling to fit grid bounds.
          $ib.Stretch = [System.Windows.Media.Stretch]::None
        } else {
          $ib.Stretch = [System.Windows.Media.Stretch]::UniformToFill
        }
        $ib.AlignmentX = [System.Windows.Media.AlignmentX]::Left
        $ib.AlignmentY = [System.Windows.Media.AlignmentY]::Bottom
        $ib.TileMode = [System.Windows.Media.TileMode]::None
        $ib.ViewportUnits = [System.Windows.Media.BrushMappingMode]::RelativeToBoundingBox
        $ib.Opacity = 1.0
        try { $ib.Freeze() } catch {}
        $brush = $ib
      }
    }
    if (-not $brush) {
      try { Set-GridWallpaperFauxBlurOverlay -Grid $Grid -Enable:$false -SolidMode:($mode -eq 'SolidColor') -WallpaperSource:$null -WallpaperKey:'' } catch {}
      return
    }
    # Put wallpaper/solid-color on the grid host container so DataGrid can remain transparent.
    $gridHost = $null
    try { $gridHost = [System.Windows.Media.VisualTreeHelper]::GetParent($Grid) } catch {}
    while ($gridHost -and -not ($gridHost -is [System.Windows.Controls.Border]) -and -not ($gridHost -is [System.Windows.Controls.Panel])) {
      try { $gridHost = [System.Windows.Media.VisualTreeHelper]::GetParent($gridHost) } catch { $gridHost = $null }
    }
    if ($gridHost -is [System.Windows.Controls.Border]) {
      $gridHost.Background = $brush
    } elseif ($gridHost -is [System.Windows.Controls.Panel]) {
      $gridHost.Background = $brush
    } else {
      $Grid.Background = $brush
    }
    try {
      # Allow blur + match-screen to stack: if both toggles are on,
      # apply faux blur overlay to the screen-matched source.
      $enableOverlay = ($useFauxBlur -and ($mode -ne 'SolidColor'))
      Set-GridWallpaperFauxBlurOverlay -Grid $Grid -Enable:$enableOverlay -SolidMode:($mode -eq 'SolidColor') -WallpaperSource $fauxWallpaperSource -WallpaperKey $fauxWallpaperKey
    } catch {}
    $Grid.Background = [System.Windows.Media.Brushes]::Transparent
    $Grid.RowBackground = [System.Windows.Media.Brushes]::Transparent
    $Grid.AlternatingRowBackground = [System.Windows.Media.Brushes]::Transparent
    try {
      # Ensure DataGrid internal surface is transparent too.
      $q = New-Object System.Collections.Queue
      $q.Enqueue($Grid)
      while ($q.Count -gt 0) {
        $n = [System.Windows.DependencyObject]$q.Dequeue()
        $cc = 0
        try { $cc = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($n) } catch { $cc = 0 }
        for ($i=0; $i -lt $cc; $i++) {
          $ch = [System.Windows.Media.VisualTreeHelper]::GetChild($n,$i)
          if ($ch -is [System.Windows.Controls.ScrollViewer]) {
            try { $ch.Background = [System.Windows.Media.Brushes]::Transparent } catch {}
          } elseif ($ch -is [System.Windows.Controls.Panel]) {
            try {
              if ($ch -is [System.Windows.Controls.Primitives.DataGridRowsPresenter] -or
                  $ch -is [System.Windows.Controls.Primitives.DataGridCellsPresenter]) {
                $ch.Background = [System.Windows.Media.Brushes]::Transparent
              }
            } catch {}
          }
          $q.Enqueue($ch)
        }
      }
    } catch {}
    $script:GridWallpaperPath = $wp
  } catch {
  }
}

function Resolve-WpfBrush {
  param(
    [Parameter(Mandatory=$false)][object]$Value,
    [System.Windows.Media.Brush]$Fallback = $null
  )
  try {
    $v = $Value
    for ($guard = 0; $guard -lt 8; $guard++) {
      if ($null -eq $v) { break }
      $next = $null
      try { $next = ([System.Management.Automation.PSObject]::AsPSObject($v)).BaseObject } catch { $next = $null }
      if ($null -eq $next) { break }
      if ([object]::ReferenceEquals($next, $v)) { break }
      $v = $next
    }
    if ($v -is [System.Windows.Media.Brush]) { return $v }
    if ($v -is [System.Windows.Media.Color]) {
      $b = New-Object System.Windows.Media.SolidColorBrush($v)
      try { $b.Freeze() } catch {}
      return $b
    }
    if ($null -ne $Fallback) { return $Fallback }
    throw "Value is not a WPF Brush."
  } catch {
    if ($null -ne $Fallback) { return $Fallback }
    throw
  }
}

function New-DarkenedAccentBrush {
  param(
    [Parameter(Mandatory=$true)][object]$Brush,
    [double]$Factor = 0.84
  )
  try {
    $baseBrush = Resolve-WpfBrush -Value $Brush
    $sb = $baseBrush -as [System.Windows.Media.SolidColorBrush]
    if ($null -eq $sb) { return $baseBrush }
    $f = [Math]::Max(0.0, [Math]::Min(1.0, [double]$Factor))
    $c = $sb.Color
    $r = [byte][Math]::Round([double]$c.R * $f)
    $g = [byte][Math]::Round([double]$c.G * $f)
    $b = [byte][Math]::Round([double]$c.B * $f)
    $out = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb($c.A, $r, $g, $b))
    try { $out.Freeze() } catch {}
    return $out
  } catch {
    return (Resolve-WpfBrush -Value $Brush)
  }
}

function Convert-RgbToHsv {
  param(
    [byte]$R,
    [byte]$G,
    [byte]$B
  )
  try {
    $rf = [double]$R / 255.0
    $gf = [double]$G / 255.0
    $bf = [double]$B / 255.0
    $max = [Math]::Max($rf, [Math]::Max($gf, $bf))
    $min = [Math]::Min($rf, [Math]::Min($gf, $bf))
    $delta = $max - $min
    $h = 0.0
    if ($delta -gt 0.0) {
      if ($max -eq $rf) {
        $h = 60.0 * ((($gf - $bf) / $delta) % 6.0)
      } elseif ($max -eq $gf) {
        $h = 60.0 * ((($bf - $rf) / $delta) + 2.0)
      } else {
        $h = 60.0 * ((($rf - $gf) / $delta) + 4.0)
      }
    }
    if ($h -lt 0.0) { $h += 360.0 }
    $s = 0.0
    if ($max -gt 0.0) { $s = $delta / $max }
    $v = $max
    return [pscustomobject]@{
      H = [double]$h
      S = [double]$s
      V = [double]$v
    }
  } catch {
    return [pscustomobject]@{ H = 0.0; S = 0.0; V = 0.0 }
  }
}

function Convert-HsvToColor {
  param(
    [double]$H,
    [double]$S,
    [double]$V,
    [byte]$A = 255
  )
  $h = [double]$H
  $s = [double]$S
  $v = [double]$V
  while ($h -lt 0.0) { $h += 360.0 }
  while ($h -ge 360.0) { $h -= 360.0 }
  if ($s -lt 0.0) { $s = 0.0 }
  if ($s -gt 1.0) { $s = 1.0 }
  if ($v -lt 0.0) { $v = 0.0 }
  if ($v -gt 1.0) { $v = 1.0 }
  if ($s -le 0.0) {
    $c = [byte][Math]::Round($v * 255.0)
    return [System.Windows.Media.Color]::FromArgb($A, $c, $c, $c)
  }
  $hPrime = $h / 60.0
  $i = [int][Math]::Floor($hPrime)
  $f = $hPrime - $i
  $p = $v * (1.0 - $s)
  $q = $v * (1.0 - ($s * $f))
  $t = $v * (1.0 - ($s * (1.0 - $f)))
  $r = 0.0; $g = 0.0; $b = 0.0
  switch ($i % 6) {
    0 { $r = $v; $g = $t; $b = $p }
    1 { $r = $q; $g = $v; $b = $p }
    2 { $r = $p; $g = $v; $b = $t }
    3 { $r = $p; $g = $q; $b = $v }
    4 { $r = $t; $g = $p; $b = $v }
    default { $r = $v; $g = $p; $b = $q }
  }
  return [System.Windows.Media.Color]::FromArgb(
    $A,
    [byte][Math]::Round($r * 255.0),
    [byte][Math]::Round($g * 255.0),
    [byte][Math]::Round($b * 255.0)
  )
}

function New-DeepenedAccentBrush {
  param(
    [Parameter(Mandatory=$true)][object]$Brush,
    [double]$Factor = 0.84,
    [double]$SaturationBoost = 0.0
  )
  try {
    $baseBrush = Resolve-WpfBrush -Value $Brush
    $sb = $baseBrush -as [System.Windows.Media.SolidColorBrush]
    if ($null -eq $sb) { return $baseBrush }
    $f = [Math]::Max(0.0, [Math]::Min(1.0, [double]$Factor))
    $satBoost = [Math]::Max(0.0, [Math]::Min(1.0, [double]$SaturationBoost))
    $c = $sb.Color
    $hsv = Convert-RgbToHsv -R $c.R -G $c.G -B $c.B
    $newV = [Math]::Max(0.0, [Math]::Min(1.0, ([double]$hsv.V * $f)))
    $newS = [Math]::Max(0.0, [Math]::Min(1.0, ([double]$hsv.S + ($satBoost * (1.0 - [double]$hsv.S)))))
    $outColor = Convert-HsvToColor -H ([double]$hsv.H) -S $newS -V $newV -A $c.A
    $out = New-Object System.Windows.Media.SolidColorBrush($outColor)
    try { $out.Freeze() } catch {}
    return $out
  } catch {
    return (New-DarkenedAccentBrush -Brush $Brush -Factor $Factor)
  }
}

function Get-BrushColor {
  param(
    [Parameter(Mandatory=$true)][object]$BrushLike,
    [System.Windows.Media.Color]$FallbackColor = ([System.Windows.Media.Color]::FromArgb(255,30,60,98))
  )
  try {
    $b = Resolve-WpfBrush -Value $BrushLike
    $sb = $b -as [System.Windows.Media.SolidColorBrush]
    if ($null -ne $sb) { return $sb.Color }
    return $FallbackColor
  } catch {
    return $FallbackColor
  }
}

function Set-AccentBrushResources {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Window]$Window,
    [Parameter(Mandatory=$true)][object]$ExactBrush,
    [Parameter(Mandatory=$true)][object]$DarkBrush
  )
  try {
    $exactColor = Get-BrushColor -BrushLike $ExactBrush
    $darkColor  = Get-BrushColor -BrushLike $DarkBrush -FallbackColor $exactColor
    $iconBoxBrushLike = $ExactBrush
    try {
      if ([bool]$script:EnableNameIconAccentBoxes) {
        $iconBoxBrushLike = Get-RegistryAccentBrushRaw
      }
    } catch {}
    $iconBoxColor = Get-BrushColor -BrushLike $iconBoxBrushLike -FallbackColor $exactColor
    $exactRes = $Window.Resources['SelectNameAccentBrushExact'] -as [System.Windows.Media.SolidColorBrush]
    if ($null -eq $exactRes) {
      $exactRes = New-Object System.Windows.Media.SolidColorBrush($exactColor)
      $Window.Resources['SelectNameAccentBrushExact'] = $exactRes
    } else {
      $exactRes.Color = $exactColor
    }
    $darkRes = $Window.Resources['SelectNameAccentBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($null -eq $darkRes) {
      $darkRes = New-Object System.Windows.Media.SolidColorBrush($darkColor)
      $Window.Resources['SelectNameAccentBrush'] = $darkRes
    } else {
      $darkRes.Color = $darkColor
    }
    $iconBoxRes = $Window.Resources['NameIconBoxAccentBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($null -eq $iconBoxRes) {
      $iconBoxRes = New-Object System.Windows.Media.SolidColorBrush($iconBoxColor)
      $Window.Resources['NameIconBoxAccentBrush'] = $iconBoxRes
    } else {
      $iconBoxRes.Color = $iconBoxColor
    }
    $useDarkUiText = $false
    try { $useDarkUiText = Get-IsSystemLightMode } catch { $useDarkUiText = $false }
    try { $script:IsLightAccentOverrideActive = [bool]$useDarkUiText } catch {}
    $nameTextColor = if ($useDarkUiText) { [System.Windows.Media.Color]::FromArgb(255,0,0,0) } else { [System.Windows.Media.Color]::FromArgb(255,255,255,255) }
    $checkBorderColor = if ($useDarkUiText) { [System.Windows.Media.Color]::FromArgb(200,90,90,90) } else { [System.Windows.Media.Color]::FromArgb(168,255,255,255) }
    $checkGlyphColor  = if ($useDarkUiText) { [System.Windows.Media.Color]::FromArgb(220,70,70,70) } else { [System.Windows.Media.Color]::FromArgb(204,255,255,255) }
    $nameTextRes = $Window.Resources['NameColumnTextBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($null -eq $nameTextRes) {
      $nameTextRes = New-Object System.Windows.Media.SolidColorBrush($nameTextColor)
      $Window.Resources['NameColumnTextBrush'] = $nameTextRes
    } else {
      $nameTextRes.Color = $nameTextColor
    }
    $checkBorderRes = $Window.Resources['SelectCheckboxBorderBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($null -eq $checkBorderRes) {
      $checkBorderRes = New-Object System.Windows.Media.SolidColorBrush($checkBorderColor)
      $Window.Resources['SelectCheckboxBorderBrush'] = $checkBorderRes
    } else {
      $checkBorderRes.Color = $checkBorderColor
    }
    $checkGlyphRes = $Window.Resources['SelectCheckboxGlyphBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($null -eq $checkGlyphRes) {
      $checkGlyphRes = New-Object System.Windows.Media.SolidColorBrush($checkGlyphColor)
      $Window.Resources['SelectCheckboxGlyphBrush'] = $checkGlyphRes
    } else {
      $checkGlyphRes.Color = $checkGlyphColor
    }
    $caretColor = if ($useDarkUiText) { [System.Windows.Media.Color]::FromArgb(220,85,85,85) } else { [System.Windows.Media.Color]::FromArgb(204,255,255,255) }
    $scrollGlyphColor = if ($useDarkUiText) { [System.Windows.Media.Color]::FromArgb(230,85,85,85) } else { [System.Windows.Media.Color]::FromArgb(255,255,255,255) }
    $caretRes = $Window.Resources['FolderCaretBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($null -eq $caretRes) {
      $caretRes = New-Object System.Windows.Media.SolidColorBrush($caretColor)
      $Window.Resources['FolderCaretBrush'] = $caretRes
    } else {
      $caretRes.Color = $caretColor
    }
    $scrollGlyphRes = $Window.Resources['MidScrollGlyphBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($null -eq $scrollGlyphRes) {
      $scrollGlyphRes = New-Object System.Windows.Media.SolidColorBrush($scrollGlyphColor)
      $Window.Resources['MidScrollGlyphBrush'] = $scrollGlyphRes
    } else {
      $scrollGlyphRes.Color = $scrollGlyphColor
    }
    $bottomFactor = 0.72
    try { $bottomFactor = [double]$script:BottomFrameAccentDarkenFactor } catch { $bottomFactor = 0.72 }
    if ($bottomFactor -lt 0.05) { $bottomFactor = 0.05 }
    if ($bottomFactor -gt 1.0) { $bottomFactor = 1.0 }
    $bottomBrush = New-DarkenedAccentBrush -Brush $ExactBrush -Factor $bottomFactor
    $bottomColor = Get-BrushColor -BrushLike $bottomBrush -FallbackColor $darkColor
    $bottomRes = $Window.Resources['BottomFrameAccentBrush'] -as [System.Windows.Media.SolidColorBrush]
    if ($null -eq $bottomRes) {
      $bottomRes = New-Object System.Windows.Media.SolidColorBrush($bottomColor)
      $Window.Resources['BottomFrameAccentBrush'] = $bottomRes
    } else {
      $bottomRes.Color = $bottomColor
    }
    # Keep brushes mutable so Refresh can update icon-box and column accent colors live.
  } catch {}
}

