if (-not (Test-Path variable:script:AccentLuminanceDarkenRatio)) { $script:AccentLuminanceDarkenRatio = 0.15 }
if (-not (Test-Path variable:script:AccentLuminanceMinDarkenFactor)) { $script:AccentLuminanceMinDarkenFactor = 0.46 }
