if (-not (Test-Path variable:script:AccentLuminanceThresholdScale)) { $script:AccentLuminanceThresholdScale = 0.70 }
if (-not (Test-Path variable:script:BottomStripBarDarkenScale)) { $script:BottomStripBarDarkenScale = 0.75 }
if (-not (Test-Path variable:script:BottomStripLogoBoxDarkenScale)) { $script:BottomStripLogoBoxDarkenScale = 0.75 }

function Get-RelativeLuminanceFromColor {
  param([Parameter(Mandatory=$true)][System.Windows.Media.Color]$Color)
  try {
    $toLin = {
      param([double]$c)
      if ($c -le 0.04045) { return ($c / 12.92) }
      return [Math]::Pow((($c + 0.055) / 1.055), 2.4)
    }
    $r = & $toLin ([double]$Color.R / 255.0)
    $g = & $toLin ([double]$Color.G / 255.0)
    $b = & $toLin ([double]$Color.B / 255.0)
    return (0.2126 * $r + 0.7152 * $g + 0.0722 * $b)
  } catch {
    return 0.0
  }
}

function Update-AccentFactorsForTheme {
  try {
    $baseDark = [double]$script:BaseSelectNameAccentDarkenFactor
    $baseBottomDark = [double]$script:BaseBottomFrameAccentDarkenFactor
    $baseHover = [double]$script:BaseSelectNameAccentHoverBrightenFactor
    $baseSel = [double]$script:BaseSelectNameAccentSelectedBrightenFactor
    $baseMid = [double]$script:BaseGridMidAccentBrightenFactor
    $baseDarkBoost = [double]$script:AccentBaseDarkenBoost
    if ($baseDarkBoost -lt 0.0) { $baseDarkBoost = 0.0 }
    if ($baseDarkBoost -gt 3.0) { $baseDarkBoost = 3.0 }
    # Increase baseline darkening strength by boost (default 1.20 => +20%).
    $baseDark = 1.0 - ((1.0 - [double]$baseDark) * [double]$baseDarkBoost)
    if ($baseDark -lt 0.0) { $baseDark = 0.0 }
    if ($baseDark -gt 1.0) { $baseDark = 1.0 }
    $script:SelectNameAccentDarkenFactor = $baseDark
    $script:BottomFrameAccentDarkenFactor = $baseBottomDark
    $script:SelectNameAccentHoverBrightenFactor = $baseHover
    $script:SelectNameAccentSelectedBrightenFactor = $baseSel
    $script:GridMidAccentBrightenFactor = $baseMid
    $light = $false
    try { $light = Get-IsSystemLightMode } catch { $light = $false }
    try { $script:IsLightAccentOverrideActive = [bool]$light } catch {}
    if ($light) {
      # In light override mode, keep base accent exact (#e4e4e4 path): no darken/saturation tinting.
      $script:SelectNameAccentDarkenFactor = 1.0
      $script:BottomFrameAccentDarkenFactor = 1.0
      # Keep interaction feedback, but less aggressive than dark mode path.
      $script:SelectNameAccentHoverBrightenFactor = 1.0 + (($baseHover - 1.0) * 1.8)
      $script:SelectNameAccentSelectedBrightenFactor = 1.0 + (($baseSel - 1.0) * 1.8)
      $script:GridMidAccentBrightenFactor = 1.0 + (($baseMid - 1.0) * 1.8)
    }
    $script:NameAccentSaturationBoost = 0.0
    # Extra darkening + saturation boost for very light accents, based on relative luminance.
    # Skip this in light override mode so #e4e4e4 stays exact.
    if (-not $light) {
      try {
        $exactColor = Get-BrushColor -BrushLike $script:SelectNameAccentBrushExact -FallbackColor ([System.Windows.Media.Color]::FromArgb(255,32,32,32))
        $lum = [double](Get-RelativeLuminanceFromColor -Color $exactColor)
        $thr = [double]$script:AccentLuminanceThreshold
        $ratio = [double]$script:AccentLuminanceDarkenRatio
        $minDark = [double]$script:AccentLuminanceMinDarkenFactor
        $satRatio = [double]$script:AccentLuminanceSaturationBoostRatio
        $fxBoost = [double]$script:AccentLuminanceEffectBoost
        $thrScale = [double]$script:AccentLuminanceThresholdScale
        if ($thr -lt 0.0) { $thr = 0.0 }
        if ($thr -gt 1.0) { $thr = 1.0 }
        if ($thrScale -lt 0.0) { $thrScale = 0.0 }
        if ($thrScale -gt 1.0) { $thrScale = 1.0 }
        # Lower threshold floor by scale (default 0.70 => starts 30% earlier).
        $thr = [double]$thr * [double]$thrScale
        if ($ratio -lt 0.0) { $ratio = 0.0 }
        if ($ratio -gt 1.0) { $ratio = 1.0 }
        if ($satRatio -lt 0.0) { $satRatio = 0.0 }
        if ($satRatio -gt 1.0) { $satRatio = 1.0 }
        if ($fxBoost -lt 0.0) { $fxBoost = 0.0 }
        if ($fxBoost -gt 3.0) { $fxBoost = 3.0 }
        if ($minDark -lt 0.0) { $minDark = 0.0 }
        if ($minDark -gt 1.0) { $minDark = 1.0 }
        if ($lum -gt $thr) {
          $span = [Math]::Max(0.0001, (1.0 - $thr))
          $t = ($lum - $thr) / $span
          if ($t -lt 0.0) { $t = 0.0 }
          if ($t -gt 1.0) { $t = 1.0 }
          $ratioEff = [double]$ratio * [double]$fxBoost
          $satEff = [double]$satRatio * [double]$fxBoost
          if ($ratioEff -gt 1.0) { $ratioEff = 1.0 }
          if ($satEff -gt 1.0) { $satEff = 1.0 }
          $script:SelectNameAccentDarkenFactor = [double]$script:SelectNameAccentDarkenFactor - ([double]$ratioEff * [double]$t)
          $script:NameAccentSaturationBoost = [double]$satEff * [double]$t
        }
        if ($script:SelectNameAccentDarkenFactor -lt $minDark) { $script:SelectNameAccentDarkenFactor = $minDark }
      } catch {}
    }
    if ($script:NameAccentSaturationBoost -lt 0.0) { $script:NameAccentSaturationBoost = 0.0 }
    if ($script:NameAccentSaturationBoost -gt 1.0) { $script:NameAccentSaturationBoost = 1.0 }
    if ($script:SelectNameAccentDarkenFactor -lt 0.0) { $script:SelectNameAccentDarkenFactor = 0.0 }
    if ($script:SelectNameAccentDarkenFactor -gt 1.0) { $script:SelectNameAccentDarkenFactor = 1.0 }
    if ($script:BottomFrameAccentDarkenFactor -lt 0.0) { $script:BottomFrameAccentDarkenFactor = 0.0 }
    if ($script:BottomFrameAccentDarkenFactor -gt 1.0) { $script:BottomFrameAccentDarkenFactor = 1.0 }
    if ($script:SelectNameAccentHoverBrightenFactor -lt 1.0) { $script:SelectNameAccentHoverBrightenFactor = 1.0 }
    if ($script:SelectNameAccentHoverBrightenFactor -gt 2.0) { $script:SelectNameAccentHoverBrightenFactor = 2.0 }
    if ($script:SelectNameAccentSelectedBrightenFactor -lt 1.0) { $script:SelectNameAccentSelectedBrightenFactor = 1.0 }
    if ($script:SelectNameAccentSelectedBrightenFactor -gt 2.0) { $script:SelectNameAccentSelectedBrightenFactor = 2.0 }
    if ($script:GridMidAccentBrightenFactor -lt 1.0) { $script:GridMidAccentBrightenFactor = 1.0 }
    if ($script:GridMidAccentBrightenFactor -gt 2.0) { $script:GridMidAccentBrightenFactor = 1.2 }
  } catch {}
}

