function Set-SelectNameColumnAccentStyle {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Controls.DataGrid]$Grid,
    [Parameter(Mandatory=$true)][object]$Brush
  )
  try {
    $bg = Resolve-WpfBrush -Value $Brush
    $bgHover = $bg
    $bgSelected = $bg
    try { $bgHover = Resolve-WpfBrush -Value (New-BrightenedAccentBrush -Brush $bg -Factor ([double]$script:SelectNameAccentHoverBrightenFactor)) -Fallback $bg } catch { $bgHover = $bg }
    try { $bgSelected = Resolve-WpfBrush -Value (New-BrightenedAccentBrush -Brush $bg -Factor ([double]$script:SelectNameAccentSelectedBrightenFactor)) -Fallback $bgHover } catch { $bgSelected = $bgHover }
    $white = [System.Windows.Media.Brushes]::White
    $nameFg = $white
    try { $nameFg = Resolve-WpfBrush -Value $window.Resources['NameColumnTextBrush'] -Fallback $white } catch { $nameFg = $white }
    foreach ($hdr in @('Select','Name')) {
      $col = $Grid.Columns | Where-Object { [string]$_.Header -eq $hdr } | Select-Object -First 1
      if ($null -eq $col) { continue }
      $fg = if ($hdr -eq 'Name') { $nameFg } else { $white }
      $st = New-Object System.Windows.Style ([System.Windows.Controls.DataGridCell])
      [void]$st.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BackgroundProperty, $bg)))
      [void]$st.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::ForegroundProperty, $fg)))
      [void]$st.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderBrushProperty, [System.Windows.Media.Brushes]::Transparent)))
      [void]$st.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderThicknessProperty, (New-Object System.Windows.Thickness 0))))
      [void]$st.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::FocusVisualStyleProperty, $null)))
      if ($hdr -eq 'Name') {
        $trHover = New-Object System.Windows.Trigger
        $trHover.Property = [System.Windows.Controls.DataGridCell]::IsMouseOverProperty
        $trHover.Value = $true
        [void]$trHover.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BackgroundProperty, $bgHover)))
        [void]$trHover.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::ForegroundProperty, $nameFg)))
        [void]$st.Triggers.Add($trHover)
        $trSel = New-Object System.Windows.Trigger
        $trSel.Property = [System.Windows.Controls.DataGridCell]::IsSelectedProperty
        $trSel.Value = $true
        [void]$trSel.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BackgroundProperty, $bgSelected)))
        [void]$trSel.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::ForegroundProperty, $nameFg)))
        [void]$st.Triggers.Add($trSel)
        # Keep A-Z separator rows static (no hover/selection shading).
        $trSep = New-Object System.Windows.DataTrigger
        $trSep.Binding = New-Object System.Windows.Data.Binding('IsAlphaSeparator')
        $trSep.Value = $true
        [void]$trSep.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BackgroundProperty, $bg)))
        [void]$trSep.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::ForegroundProperty, $nameFg)))
        [void]$st.Triggers.Add($trSep)
      } else {
        # Select column: explicitly suppress selected-cell borders.
        $trSelSelect = New-Object System.Windows.Trigger
        $trSelSelect.Property = [System.Windows.Controls.DataGridCell]::IsSelectedProperty
        $trSelSelect.Value = $true
        [void]$trSelSelect.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BackgroundProperty, $bg)))
        [void]$trSelSelect.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::ForegroundProperty, $fg)))
        [void]$trSelSelect.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderBrushProperty, [System.Windows.Media.Brushes]::Transparent)))
        [void]$trSelSelect.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderThicknessProperty, (New-Object System.Windows.Thickness 0))))
        [void]$st.Triggers.Add($trSelSelect)
      }
      $col.CellStyle = $st
    }
  } catch {}
}
