function Apply-MidGridScrollBarAccentStyle {
  param(
    [Parameter(Mandatory=$false)][System.Windows.Controls.Primitives.ScrollBar]$ScrollBar = $script:GridMidScrollBar,
    [Parameter(Mandatory=$false)][object]$AccentBrush = $script:SelectNameAccentBrushExact
  )
  try {
    if (-not $ScrollBar) { return }
    $baseSource = $AccentBrush
    try {
      if ($null -eq $baseSource -and $window -and $window.Resources -and $window.Resources.Contains('SelectNameAccentBrushExact')) {
        $baseSource = $window.Resources['SelectNameAccentBrushExact']
      }
    } catch {}
    if ($null -eq $baseSource) { $baseSource = $script:SelectNameAccentBrushExact }
    $base = Resolve-WpfBrush -Value $baseSource
    $bright = New-BrightenedAccentBrush -Brush $base -Factor ([double]$script:GridMidAccentBrightenFactor)
    $hoverBright = New-BrightenedAccentBrush -Brush $base -Factor ([double]$script:GridMidAccentBrightenFactor + 0.28)
    $dragBright  = New-BrightenedAccentBrush -Brush $base -Factor ([double]$script:GridMidAccentBrightenFactor + 0.50)
    $bc = Get-BrushColor -BrushLike $bright -FallbackColor ([System.Windows.Media.Color]::FromArgb(255,23,23,23))
    $hc = Get-BrushColor -BrushLike $hoverBright -FallbackColor $bc
    $dc = Get-BrushColor -BrushLike $dragBright -FallbackColor $hc
    $useDarkUiText = $false
    try { $useDarkUiText = Get-IsSystemLightMode } catch { $useDarkUiText = $false }
    try { $script:IsLightAccentOverrideActive = [bool]$useDarkUiText } catch {}
    if ($useDarkUiText) {
      $bc = [System.Windows.Media.Color]::FromArgb(255,82,82,82)
      $hc = [System.Windows.Media.Color]::FromArgb(255,102,102,102)
      $dc = [System.Windows.Media.Color]::FromArgb(255,122,122,122)
    }
#--- scrollbar transparancy control ---
    $thumb = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb(240, $bc.R, $bc.G, $bc.B))
    $thumbHover = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb(242, $hc.R, $hc.G, $hc.B))
    $thumbDrag  = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb(245, $dc.R, $dc.G, $dc.B))
    $trackAlpha = 150
    try { $trackAlpha = [int]$script:GridMidTrackAlpha } catch { $trackAlpha = 150 }
    if ($trackAlpha -lt 0) { $trackAlpha = 0 }
    if ($trackAlpha -gt 255) { $trackAlpha = 255 }
    $track = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb([byte]$trackAlpha, $bc.R, $bc.G, $bc.B))
    $ScrollBar.Foreground = $thumb
    $ScrollBar.Background = $track
    $ScrollBar.Opacity = 0.80
    try {
      $tpl = $ScrollBar.Template
      if ($tpl) {
        $trackBorder = $tpl.FindName('MidScrollBarTrack', $ScrollBar)
        $lineUp = $tpl.FindName('MidScrollBarLineUpButton', $ScrollBar)
        $lineDown = $tpl.FindName('MidScrollBarLineDownButton', $ScrollBar)
        $thumbPart = $tpl.FindName('MidScrollBarThumb', $ScrollBar)
        $upGlyph = $tpl.FindName('MidScrollBarUpGlyph', $ScrollBar)
        $downGlyph = $tpl.FindName('MidScrollBarDownGlyph', $ScrollBar)
        $btnNormal = $track
        $btnHoverAlpha = [int]([Math]::Min(255, ($trackAlpha + 34)))
        $btnPressAlpha = [int]([Math]::Min(255, ($trackAlpha + 58)))
        $btnHover = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb([byte]$btnHoverAlpha, $hc.R, $hc.G, $hc.B))
        $btnPress = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb([byte]$btnPressAlpha, $dc.R, $dc.G, $dc.B))
        $btnBorderNormal = [System.Windows.Media.Brushes]::Transparent
        $btnBorderHot = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb(208, 255, 255, 255))
        $wireLineButton = {
          param($btn)
          if (-not $btn) { return }
          $btn.Background = $btnNormal
          $btn.BorderBrush = $btnBorderNormal
          $btn.BorderThickness = New-Object System.Windows.Thickness 0
          $btn.Tag = [pscustomobject]@{
            Normal   = $btnNormal
            Hover    = $btnHover
            Pressed  = $btnPress
            BorderN  = $btnBorderNormal
            BorderH  = $btnBorderHot
            Pressing = $false
          }
          $btnKey = ''
          try { $btnKey = [string]$btn.GetHashCode() } catch { $btnKey = '' }
          if (-not $btnKey) { return }
          if ($script:GridMidLineButtonEventWired.ContainsKey($btnKey)) { return }
          $btn.Add_MouseEnter({
            param($sender, $e)
            try {
              $st = $sender.Tag
              if ($st -and -not $st.Pressing) {
                if ($st.Hover) { $sender.Background = $st.Hover }
                if ($st.BorderH) { $sender.BorderBrush = $st.BorderH }
              }
            } catch {}
          })
          $btn.Add_MouseLeave({
            param($sender, $e)
            try {
              $st = $sender.Tag
              if ($st -and -not $st.Pressing) {
                if ($st.Normal) { $sender.Background = $st.Normal }
                if ($st.BorderN) { $sender.BorderBrush = $st.BorderN }
              }
            } catch {}
          })
          $btn.Add_PreviewMouseLeftButtonDown({
            param($sender, $e)
            try {
              $st = $sender.Tag
              if ($st) {
                $st.Pressing = $true
                if ($st.Pressed) { $sender.Background = $st.Pressed }
                if ($st.BorderH) { $sender.BorderBrush = $st.BorderH }
              }
            } catch {}
          })
          $btn.Add_PreviewMouseLeftButtonUp({
            param($sender, $e)
            try {
              $st = $sender.Tag
              if ($st) {
                $st.Pressing = $false
                if ($sender.IsMouseOver) {
                  if ($st.Hover) { $sender.Background = $st.Hover }
                  if ($st.BorderH) { $sender.BorderBrush = $st.BorderH }
                } else {
                  if ($st.Normal) { $sender.Background = $st.Normal }
                  if ($st.BorderN) { $sender.BorderBrush = $st.BorderN }
                }
              }
            } catch {}
          })
          $btn.Add_LostMouseCapture({
            param($sender, $e)
            try {
              $st = $sender.Tag
              if ($st) {
                $st.Pressing = $false
                if ($sender.IsMouseOver) {
                  if ($st.Hover) { $sender.Background = $st.Hover }
                  if ($st.BorderH) { $sender.BorderBrush = $st.BorderH }
                } else {
                  if ($st.Normal) { $sender.Background = $st.Normal }
                  if ($st.BorderN) { $sender.BorderBrush = $st.BorderN }
                }
              }
            } catch {}
          })
          $script:GridMidLineButtonEventWired[$btnKey] = $true
        }
        if ($trackBorder) { $trackBorder.Background = $track }
        & $wireLineButton $lineUp
        & $wireLineButton $lineDown
        if ($thumbPart) {
          $thumbPart.Background = $thumb
          $thumbPart.Tag = [pscustomobject]@{
            Normal   = $thumb
            Hover    = $thumbHover
            Drag     = $thumbDrag
            Dragging = $false
          }
          $thumbKey = ''
          try { $thumbKey = [string]$thumbPart.GetHashCode() } catch { $thumbKey = '' }
          if ($thumbKey -and -not $script:GridMidThumbEventWired.ContainsKey($thumbKey)) {
            $thumbPart.Add_MouseEnter({
              param($sender, $e)
              try {
                $st = $sender.Tag
                if ($st -and -not $st.Dragging -and $st.Hover) { $sender.Background = $st.Hover }
              } catch {}
            })
            $thumbPart.Add_MouseLeave({
              param($sender, $e)
              try {
                $st = $sender.Tag
                if ($st -and -not $st.Dragging -and $st.Normal) { $sender.Background = $st.Normal }
              } catch {}
            })
            $thumbPart.Add_DragStarted({
              param($sender, $e)
              try {
                $st = $sender.Tag
                if ($st) {
                  $st.Dragging = $true
                  if ($st.Drag) { $sender.Background = $st.Drag }
                }
              } catch {}
            })
            $thumbPart.Add_DragCompleted({
              param($sender, $e)
              try {
                $st = $sender.Tag
                if ($st) {
                  $st.Dragging = $false
                  if ($sender.IsMouseOver -and $st.Hover) { $sender.Background = $st.Hover }
                  elseif ($st.Normal) { $sender.Background = $st.Normal }
                }
              } catch {}
            })
            $script:GridMidThumbEventWired[$thumbKey] = $true
          }
        }
        if ($upGlyph) {
          $upGlyph.Fill = [System.Windows.Media.Brushes]::Transparent
          try { $upGlyph.Stroke = Resolve-WpfBrush -Value $window.Resources['MidScrollGlyphBrush'] -Fallback ([System.Windows.Media.Brushes]::White) } catch { $upGlyph.Stroke = [System.Windows.Media.Brushes]::White }
        }
        if ($downGlyph) {
          $downGlyph.Fill = [System.Windows.Media.Brushes]::Transparent
          try { $downGlyph.Stroke = Resolve-WpfBrush -Value $window.Resources['MidScrollGlyphBrush'] -Fallback ([System.Windows.Media.Brushes]::White) } catch { $downGlyph.Stroke = [System.Windows.Media.Brushes]::White }
        }
      }
    } catch {}
    try { $ScrollBar.InvalidateVisual() } catch {}
  } catch {}
}

try { Apply-MidGridScrollBarAccentStyle -ScrollBar $script:GridMidScrollBar -AccentBrush $script:SelectNameAccentBrushExact } catch {}

function Refresh-SelectNameAccentStyle {
  try { $script:SelectNameAccentBrushExact = Get-CurrentUserAccentBrush } catch {}
  try { Update-AccentFactorsForTheme } catch {}
  try { $script:SelectNameAccentBrush = New-DeepenedAccentBrush -Brush $script:SelectNameAccentBrushExact -Factor $script:SelectNameAccentDarkenFactor -SaturationBoost $script:NameAccentSaturationBoost } catch { $script:SelectNameAccentBrush = $script:SelectNameAccentBrushExact }
  try { Set-AccentBrushResources -Window $window -ExactBrush $script:SelectNameAccentBrushExact -DarkBrush $script:SelectNameAccentBrush } catch {}
  try { Sync-ThemeContrastResources -Window $window -IsLight (Get-IsSystemLightMode) } catch {}
  try { Sync-BottomStripAccentStyle } catch {}
  try { Set-GridWallpaperBackground -Grid $grid } catch {}
  try { Set-SelectNameColumnAccentStyle -Grid $grid -Brush $script:SelectNameAccentBrush } catch {}
  try { Update-GridSelectNameBandLayout } catch {}
  try { Apply-MidGridScrollBarAccentStyle -ScrollBar $script:GridMidScrollBar -AccentBrush $script:SelectNameAccentBrushExact } catch {}
  try { $grid.InvalidateVisual() } catch {}
  try {
    $ce = ($script:SelectNameAccentBrushExact -as [System.Windows.Media.SolidColorBrush]).Color
    $cd = ($script:SelectNameAccentBrush -as [System.Windows.Media.SolidColorBrush]).Color
  } catch {}
}

$window.Add_ContentRendered({
  try { $script:StartupBindingPhase = $false } catch {}
  try { Set-StartupSplashStatus -Status "Ready" -Value 100 } catch {}
  try { Close-StartupSplash } catch {}
  try { $script:LastKnownSystemLightMode = Get-IsSystemLightMode } catch {}
  try { $script:LastKnownThemeModeStateKey = Get-ThemeModeStateKeyRaw } catch {}
  try { Set-WindowTitleWithWindowsVersion -Force } catch {}
  try { Refresh-SelectNameAccentStyle } catch {}
  try { Sync-BottomStripAccentStyle } catch {}
  try { Set-WindowTitleBarTheme -Window $window -Mode ([string]$script:UiThemeMode) } catch {}
  try { Apply-CustomTitleBarForeground -Mode ([string]$script:UiThemeMode) } catch {}
  try { Enable-SoftWindowShadow -Window $window } catch {}
  try { Update-WindowShadowByState -Window $window } catch {}
  try {
    $window.Dispatcher.BeginInvoke([Action]{
      try { Start-CreateCharMapGlyphCacheWarmup } catch {}
    }, [System.Windows.Threading.DispatcherPriority]::Background) | Out-Null
  } catch {}
  try {
    $window.Dispatcher.BeginInvoke([Action]{
      try { Apply-MidGridScrollBarAccentStyle -ScrollBar $script:GridMidScrollBar -AccentBrush $window.Resources['SelectNameAccentBrushExact'] } catch {}
      try { Update-GridTopDataSpacerLayout } catch {}
      try { Update-GridTopOverlayLayout } catch {}
      try { Update-GridSelectNameBandLayout } catch {}
      try { Update-GridTopMaskResizeThumbLayout } catch {}
    }, [System.Windows.Threading.DispatcherPriority]::Background) | Out-Null
  } catch {}
  try {
    if (-not [bool]$script:FirstLaunchGuideTipHandled) {
      $window.Dispatcher.BeginInvoke([Action]{
        try { Show-FirstLaunchGuideTipIfNeeded -OwnerWindow $window } catch {}
      }, [System.Windows.Threading.DispatcherPriority]::ApplicationIdle) | Out-Null
    }
  } catch {}
})

# Editing is allowed for AppsFolder proxy rows.
# Rename/Delete are applied through special handling during Apply.

# ================================================================================================
# DEBUG: Grid / Name / Rename / Pending tripwires
# ================================================================================================

function Find-VisualChild {
  param([Parameter(Mandatory=$true)][System.Windows.DependencyObject]$Parent,[Parameter(Mandatory=$true)][Type]$Type)
  if ($null -eq $Parent) { return $null }
  $count = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($Parent)
  for ($i=0; $i -lt $count; $i++) {
    $child = [System.Windows.Media.VisualTreeHelper]::GetChild($Parent, $i)
    if ($child -is $Type) { return $child }
    $found = Find-VisualChild -Parent $child -Type $Type
    if ($found) { return $found }
  }
  return $null
}

function Get-GridCellText {
  param([Parameter(Mandatory=$true)][System.Windows.Controls.DataGrid]$Grid,[Parameter(Mandatory=$true)][object]$Item,[Parameter(Mandatory=$true)][string]$ColumnHeader)
  try {
    $col = $Grid.Columns | Where-Object { $_.Header -eq $ColumnHeader } | Select-Object -First 1
    if (-not $col) { return "<no-col>" }
    $Grid.ScrollIntoView($Item, $col)
    $row = $Grid.ItemContainerGenerator.ContainerFromItem($Item)
    if (-not $row) { $Grid.UpdateLayout(); $Grid.ScrollIntoView($Item, $col); $row = $Grid.ItemContainerGenerator.ContainerFromItem($Item) }
    if (-not $row) { return "<no-row>" }
    $presenter = Find-VisualChild -Parent $row -Type ([System.Windows.Controls.Primitives.DataGridCellsPresenter])
    if (-not $presenter) { $row.ApplyTemplate(); $presenter = Find-VisualChild -Parent $row -Type ([System.Windows.Controls.Primitives.DataGridCellsPresenter]) }
    if (-not $presenter) { return "<no-presenter>" }
    $cell = $presenter.ItemContainerGenerator.ContainerFromIndex($col.DisplayIndex)
    if (-not $cell) { return "<no-cell>" }
    $tb = Find-VisualChild -Parent $cell -Type ([System.Windows.Controls.TextBlock])
    if ($tb) { return [string]$tb.Text }
    return "<no-textblock>"
  } catch {
    return "<err>"
  }
}

$grid.Add_PreparingCellForEdit({
  param($s,$e)
  try {
    $item = $e.Row.Item
  } catch {}
})

$grid.Add_CellEditEnding({
  param($s,$e)
  try {
    $item = $e.Row.Item
    $tb = $e.EditingElement
    $txt = if ($tb -is [System.Windows.Controls.TextBox]) { [string]$tb.Text } else { "<no-tb>" }
  } catch {}
})

$grid.Add_CurrentCellChanged({
  try {
    try { [void](Invoke-CommitActiveInlineRenameIfNeeded -Reason 'GridCurrentCellChanged') } catch {}
    try { Sync-CreateEditSelectedFields } catch {}
    try {
      $null = $window.Dispatcher.BeginInvoke(
        [Action]{ try { Sync-CreateEditSelectedFields } catch {} },
        [System.Windows.Threading.DispatcherPriority]::Background
      )
    } catch {}
  } catch {}
})
$grid.Add_SelectionChanged({ })

function Find-VisualParent {
  param(
    [Parameter(Mandatory=$true)][System.Windows.DependencyObject]$Child,
    [Parameter(Mandatory=$true)][Type]$Type
  )
  try {
    $d = $Child
    while ($d -and -not ($d -is $Type)) {
      $d = [System.Windows.Media.VisualTreeHelper]::GetParent($d)
    }
    return $d
  } catch {
    return $null
  }
}

function Get-DefaultWindowsFolderPrepareClass {
  param([Parameter(Mandatory=$true)][object]$Row)
  try {
    $candidates = @()
    foreach ($pn in @('ViewName','VisualDisplayName','Name','OriginalName')) {
      try {
        if ($Row.PSObject.Properties.Match($pn).Count -gt 0) {
          $v = [string]$Row.$pn
          if (-not [string]::IsNullOrWhiteSpace($v)) { $candidates += $v }
        }
      } catch {}
    }
    try {
      $p = [string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback '')
      if (-not [string]::IsNullOrWhiteSpace($p)) {
        $leaf = [System.IO.Path]::GetFileName(($p.TrimEnd('\')))
        if (-not [string]::IsNullOrWhiteSpace($leaf)) { $candidates += $leaf }
      }
    } catch {}
    foreach ($nm in @($candidates)) {
      $k = Normalize-VisualKey ([string]$nm)
      if ([string]::IsNullOrWhiteSpace($k)) { continue }
      if ($k -in @('windows administrative tools','administrative tools','windows administration tools','administration tools')) { return 'Admin' }
      if ($k -in @('windows accessories','accessories','windows ease of access','accessibility','windows system','system tools','windows powershell')) { return 'Core' }
    }
    return ''
  } catch {
    return ''
  }
}

function Test-StartMenuPreparedForDefaultFolderRenames {
  param([object]$Row = $null)
  try {
    $allUsersRoot = [string]$scopeRoots['AllUsers']
    if ([string]::IsNullOrWhiteSpace($allUsersRoot)) { return $false }
    if (-not (Test-Path -LiteralPath $allUsersRoot -PathType Container)) { return $false }

    $prepareClass = ''
    try { if ($Row) { $prepareClass = [string](Get-DefaultWindowsFolderPrepareClass -Row $Row) } } catch { $prepareClass = '' }

    if ($prepareClass -eq 'Admin') {
      $approvedAdmin = $false
      try { $approvedAdmin = [bool]$script:PrepareStartMenuApprovedAdminSession } catch { $approvedAdmin = $false }
      if (-not $approvedAdmin) { return $false }
      $pAdmin = Join-Path $allUsersRoot 'Windows Administration Tools'
      return (Test-Path -LiteralPath $pAdmin -PathType Container)
    }

    $approvedCore = $false
    try { $approvedCore = [bool]$script:PrepareStartMenuApprovedCoreSession } catch { $approvedCore = $false }
    if (-not $approvedCore) {
      # Backward compatibility for existing sessions that only set the legacy gate.
      try { $approvedCore = [bool]$script:PrepareStartMenuApprovedSession } catch { $approvedCore = $false }
    }
    if (-not $approvedCore) { return $false }

    foreach ($nm in @('Windows Accessories','Windows Ease of Access','Windows PowerShell','Windows System')) {
      $p = Join-Path $allUsersRoot $nm
      if (-not (Test-Path -LiteralPath $p -PathType Container)) { return $false }
    }
    return $true
  } catch {
    return $false
  }
}

function Test-IsDefaultWindowsFolderRenameTargetRow {
  param([Parameter(Mandatory=$true)][object]$Row)
  try {
    $rk = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback '')
    if ($rk -ne 'Folder') { return $false }
    $candidates = @()
    foreach ($pn in @('ViewName','VisualDisplayName','Name','OriginalName')) {
      try {
        if ($Row.PSObject.Properties.Match($pn).Count -gt 0) {
          $v = [string]$Row.$pn
          if (-not [string]::IsNullOrWhiteSpace($v)) { $candidates += $v }
        }
      } catch {}
    }
    try {
      $p = [string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback '')
      if (-not [string]::IsNullOrWhiteSpace($p)) {
        $leaf = [System.IO.Path]::GetFileName(($p.TrimEnd('\')))
        if (-not [string]::IsNullOrWhiteSpace($leaf)) { $candidates += $leaf }
      }
    } catch {}
    foreach ($nm in @($candidates)) {
      $k = Normalize-VisualKey ([string]$nm)
      if ([string]::IsNullOrWhiteSpace($k)) { continue }
      # Default Windows folder families that need "Prepare Start Menu" for consistent rename behavior.
      if ($k -in @('windows accessories','accessories')) { return $true }
      if ($k -in @('windows administrative tools','administrative tools')) { return $true }
      if ($k -in @('windows ease of access','accessibility')) { return $true }
      if ($k -in @('windows system','system tools')) { return $true }
    }
    return $false
  } catch {
    return $false
  }
}

function Show-PrepareStartMenuRenameWarningDialog {
  param([Parameter(Mandatory=$true)][System.Windows.Window]$OwnerWindow)
  try {
    [xml]$x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Prepare Start Menu (recommended)"
        WindowStartupLocation="CenterOwner"
        ResizeMode="NoResize"
        SizeToContent="WidthAndHeight"
        ShowInTaskbar="False">
  <Border Padding="14">
    <Grid>
      <Grid.RowDefinitions>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="Auto"/>
      </Grid.RowDefinitions>
      <TextBlock Grid.Row="0" Width="400" TextWrapping="Wrap"
                 Text="If you plan to rename any of the default Windows folders:&#x0a;- Windows Accessories&#x0a;- *Windows Administrative Tools&#x0a;- Windows Ease of Access&#x0a;- Windows System&#x0a;&#x0a;You must first run 'Prepare Start Menu' to consolidate folders across multiple profiles for consistent renaming."/>
      <StackPanel Grid.Row="1" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,14,0,0">
        <Button Name="PrepareBtn" Content="Prepare Start Menu" MinWidth="165" Margin="0,0,8,0"/>
        <Button Name="CancelBtn" Content="Cancel" MinWidth="90"/>
      </StackPanel>
    </Grid>
  </Border>
</Window>
"@
    $reader = New-Object System.Xml.XmlNodeReader $x
    $dlg = [Windows.Markup.XamlReader]::Load($reader)
    if ($OwnerWindow) { try { $dlg.Owner = $OwnerWindow } catch {} }
    $prepare = $dlg.FindName("PrepareBtn")
    $cancel  = $dlg.FindName("CancelBtn")
    if (-not $prepare -or -not $cancel) { return $false }
    try { $dlg.Tag = 'Cancel' } catch {}
    $prepare.Add_Click({
      try { $dlg.Tag = 'Prepare' } catch {}
      try { $dlg.DialogResult = $true } catch {}
      try { $dlg.Close() } catch {}
    })
    $cancel.Add_Click({
      try { $dlg.Tag = 'Cancel' } catch {}
      try { $dlg.DialogResult = $false } catch {}
      try { $dlg.Close() } catch {}
    })
    [void]$dlg.ShowDialog()
    try { return ([string]$dlg.Tag -eq 'Prepare') } catch { return $false }
  } catch {
    return $false
  }
}

$script:PrepareStartMenuPromptGateUntil = [datetime]::MinValue
$script:SkipPrepareDialogOnce = $false
if (-not (Test-Path variable:script:PrepareStartMenuApprovedSession)) { $script:PrepareStartMenuApprovedSession = $false }
if (-not (Test-Path variable:script:PrepareStartMenuApprovedCoreSession)) { $script:PrepareStartMenuApprovedCoreSession = $false }
if (-not (Test-Path variable:script:PrepareStartMenuApprovedAdminSession)) { $script:PrepareStartMenuApprovedAdminSession = $false }

function Invoke-PrepareStartMenuRequirementPrompt {
  param([switch]$FromRightClick)
  try {
    $now = Get-Date
    if ($script:PrepareStartMenuPromptGateUntil -gt $now) { return $false }
    $script:PrepareStartMenuPromptGateUntil = $now.AddMilliseconds(900)
  } catch {}
  if ($FromRightClick) {
    # A right-click can also trigger BeginningEdit; suppress the immediate second prompt.
    $script:SkipPrepareDialogOnce = $true
  }
  $goPrepare = $false
  try { $goPrepare = Show-PrepareStartMenuRenameWarningDialog -OwnerWindow $window } catch { $goPrepare = $false }
  if ($goPrepare) {
    try {
      Invoke-PrepareStartMenuFlow -SkipIntro
    } catch {
    }
  }
  return [bool]$goPrepare
}

function Confirm-ShellAppRenameAtEditStart {
  param([Parameter(Mandatory=$true)][object]$Row)
  try {
    if (-not $Row) { return $true }
    # Windows Security special proxy.
    $isWinSecProxy = $false
    try { $isWinSecProxy = ($Row.PSObject.Properties.Match('IsWindowsSecurityProxy').Count -gt 0 -and [bool]$Row.IsWindowsSecurityProxy) } catch {}
    if ($isWinSecProxy) {
      # If editable shortcut already exists, do not allow editing this proxy row.
      $dupExists = $false
      try { $dupExists = [bool](Test-WindowsSecurityEditableShortcutExists) } catch { $dupExists = $false }
      if ($dupExists) { return $false }
      $alreadyOk = $false
      try { $alreadyOk = ($Row.PSObject.Properties.Match('WinSecRenameConfirmed').Count -gt 0 -and [bool]$Row.WinSecRenameConfirmed) } catch { $alreadyOk = $false }
      if (-not $alreadyOk) {
        $msg = @(
          'This Start Menu item cannot be renamed directly.'
          ''
          'Would you like to create an editable duplicate shortcut?'
        ) -join "`n"
        $res = [System.Windows.MessageBox]::Show(
          $msg,
          'Windows Security',
          [System.Windows.MessageBoxButton]::YesNo,
          [System.Windows.MessageBoxImage]::Question
        )
        if ($res -ne [System.Windows.MessageBoxResult]::Yes) { return $false }
        try { Set-PropSafeGlobal -Obj $Row -Name 'WinSecRenameConfirmed' -Value $true } catch {}
      }
      return $true
    }
    # Generic AppsFolder/ShellApp proxies.
    $isAppsProxy = $false
    try { $isAppsProxy = ($Row.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderProxy) } catch {}
    if (-not $isAppsProxy) {
      try { $isAppsProxy = ($Row.PSObject.Properties.Match('IsAppsFolderDisplayProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderDisplayProxy) } catch {}
    }
    if ($isAppsProxy) {
      $alreadyOk = $false
      try { $alreadyOk = ($Row.PSObject.Properties.Match('AppsFolderRenameConfirmed').Count -gt 0 -and [bool]$Row.AppsFolderRenameConfirmed) } catch { $alreadyOk = $false }
      if (-not $alreadyOk) {
        $title = [string](Get-PropString -Obj $Row -Names @('OriginalName','Name') -Fallback 'System App')
        $msg = @(
          'This Start Menu item cannot be renamed directly.'
          ''
          'Would you like to create an editable duplicate shortcut?'
        ) -join "`n"
        $res = [System.Windows.MessageBox]::Show(
          $msg,
          $title,
          [System.Windows.MessageBoxButton]::YesNo,
          [System.Windows.MessageBoxImage]::Question
        )
        if ($res -ne [System.Windows.MessageBoxResult]::Yes) { return $false }
        try { Set-PropSafeGlobal -Obj $Row -Name 'AppsFolderRenameConfirmed' -Value $true } catch {}
      }
    }
    return $true
  } catch {
    return $false
  }
}

# Warn early if user right-clicks default Windows folders without preparing Start Menu first.
# This fires before any rename commit/pending state mutation.
if (-not (Test-Path variable:script:PrepareStartMenuWarnWired) -or -not $script:PrepareStartMenuWarnWired) {
  $script:PrepareStartMenuWarnWired = $true
  $grid.Add_PreviewMouseRightButtonDown({
    param($s, $e)
    try {
      $src = $e.OriginalSource -as [System.Windows.DependencyObject]
      if (-not $src) { return }

      # Ignore select checkbox clicks (Tag='SelectCascade').
      $tb = Find-VisualParent -Child $src -Type ([System.Windows.Controls.Primitives.ToggleButton])
      if ($tb -and ([string]$tb.Tag -eq 'SelectCascade')) { return }

      $dgRow = Find-VisualParent -Child $src -Type ([System.Windows.Controls.DataGridRow])
      if (-not $dgRow) { return }

      $row = $dgRow.Item
      if (-not $row) { return }
      if (Test-IsAlphaSeparatorRow -Row $row) { return }
      if (-not (Test-IsDefaultWindowsFolderRenameTargetRow -Row $row)) { return }
      if (Test-StartMenuPreparedForDefaultFolderRenames -Row $row) { return }

      $e.Handled = $true
      [void](Invoke-PrepareStartMenuRequirementPrompt -FromRightClick)
    } catch {}
  })
}

# Strict rename-start gate:
# Only allow entering Name edit mode when explicitly armed by right-click, Rename button, or F2.
if (-not (Test-Path variable:script:StrictRenameStartGateWired) -or -not $script:StrictRenameStartGateWired) {
  $script:StrictRenameStartGateWired = $true
  $grid.Add_BeginningEdit({
    param($s, $e)
    try {
      if (-not $e) { return }
      if (-not $e.Column) { return }
      if ($e.Column.Header -ne 'Name') { return }
      if (-not $e.Row) { try { $e.Cancel = $true } catch {}; return }

      $row = $e.Row.Item
      if (-not $row) { try { $e.Cancel = $true } catch {}; return }
      if (Test-IsAlphaSeparatorRow -Row $row) { try { $e.Cancel = $true } catch {}; return }

      $allowed = $false
      try { $allowed = [bool](Test-AndConsume-RenameBeginEditGate -Row $row) } catch { $allowed = $false }
      if (-not $allowed) {
        try { $e.Cancel = $true } catch {}
      }
    } catch {}
  })
}

# Absolute gate: for default Windows folder families, block entering rename edit until prepared.
if (-not (Test-Path variable:script:PrepareStartMenuBeginEditGateWired) -or -not $script:PrepareStartMenuBeginEditGateWired) {
  $script:PrepareStartMenuBeginEditGateWired = $true
  $grid.Add_BeginningEdit({
    param($s, $e)
    try {
      if (-not $e) { return }
      if (-not $e.Row) { return }
      if (-not $e.Column) { return }
      if ($e.Column.Header -ne 'Name') { return }

      $row = $e.Row.Item
      if (-not $row) { return }
      if (Test-IsAlphaSeparatorRow -Row $row) { try { $e.Cancel = $true } catch {}; return }
      if (-not (Test-IsDefaultWindowsFolderRenameTargetRow -Row $row)) { return }
      if (Test-StartMenuPreparedForDefaultFolderRenames -Row $row) { return }

      if ($script:SkipPrepareDialogOnce) {
        $script:SkipPrepareDialogOnce = $false
        try { $e.Cancel = $true } catch {}
        return
      }

      # Block edit and show the same prepare warning/action dialog.
      try { $e.Cancel = $true } catch {}
      [void](Invoke-PrepareStartMenuRequirementPrompt)
      return

      # ShellApp rename prompt must fire before user starts typing.
      # If user declines, block entering edit mode.
    } catch {}
  })
}

# Edit-start gate for ShellApp rows: show rename warning BEFORE edit text entry.
if (-not (Test-Path variable:script:ShellAppBeginEditGateWired) -or -not $script:ShellAppBeginEditGateWired) {
  $script:ShellAppBeginEditGateWired = $true
  $grid.Add_BeginningEdit({
    param($s, $e)
    try {
      if (-not $e) { return }
      if (-not $e.Row) { return }
      if (-not $e.Column) { return }
      if ($e.Column.Header -ne 'Name') { return }

      $row = $e.Row.Item
      if (-not $row) { return }
      if (Test-IsAlphaSeparatorRow -Row $row) { try { $e.Cancel = $true } catch {}; return }
      if ([string]$row.Action -eq 'Delete') { return }

      $isShellLike = $false
      try { $isShellLike = ($row.PSObject.Properties.Match('IsWindowsSecurityProxy').Count -gt 0 -and [bool]$row.IsWindowsSecurityProxy) } catch {}
      if (-not $isShellLike) {
        try { $isShellLike = ($row.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$row.IsAppsFolderProxy) } catch {}
      }
      if (-not $isShellLike) {
        try { $isShellLike = ($row.PSObject.Properties.Match('IsAppsFolderDisplayProxy').Count -gt 0 -and [bool]$row.IsAppsFolderDisplayProxy) } catch {}
      }
      if (-not $isShellLike) { return }

      $ok = $false
      try { $ok = [bool](Confirm-ShellAppRenameAtEditStart -Row $row) } catch { $ok = $false }
      if (-not $ok) {
        try { $e.Cancel = $true } catch {}
        return
      }
    } catch {}
  })
}

try { Set-StartupSplashStatus -Status "Binding controls..." -Value 52 } catch {}
$script:SearchBox = $window.FindName("SearchBox")
$searchFieldIcon  = $window.FindName("SearchFieldIcon")
$searchCaptionText = $window.FindName("SearchCaptionText")
$viewCaptionText = $window.FindName("ViewCaptionText")
$selectAll        = $window.FindName("SelectAllBox")
$undoBtn          = $window.FindName("UndoBtn")
$redoBtn          = $window.FindName("RedoBtn")
$undoBtnIcon      = $window.FindName("UndoBtnIcon")
$redoBtnIcon      = $window.FindName("RedoBtnIcon")
$mockDeleteBtnIcon = $window.FindName("MockDeleteBtnIcon")
$unDeleteBtnIcon  = $window.FindName("UnDeleteBtnIcon")
$resetBtnIconMain = $window.FindName("ResetBtnIcon")
$applyBtnIconMain = $window.FindName("ApplyBtnIcon")
$saveProfileBtnIcon = $window.FindName("SaveProfileBtnIcon")
$savePendingStatesBtnIcon = $window.FindName("SavePendingStatesBtnIcon")
$loadProfileBtnIcon = $window.FindName("LoadProfileBtnIcon")
$restoreBackupBtnIcon = $window.FindName("RestoreBackupBtnIcon")
$prepareStartMenuBtnIcon = $window.FindName("PrepareStartMenuBtnIcon")
$refreshBtnIconMain = $window.FindName("RefreshBtnIcon")
$infoBtn = $window.FindName("InfoBtn")
$infoBtnIcon = $window.FindName("InfoBtnIcon")
$uiThemeToggleBtn = $window.FindName("UiThemeToggleBtn")
$uiThemeToggleIcon = $window.FindName("UiThemeToggleIcon")
$resetBtn         = $window.FindName("ResetBtn")
$mockDeleteBtn    = $window.FindName("MockDeleteBtn")
$unDeleteBtn      = $window.FindName("UnDeleteBtn")
$applyBtn         = $window.FindName("ApplyBtn")
$saveProfileBtn   = $window.FindName("SaveProfileBtn")
$savePendingStatesBtn = $window.FindName("SavePendingStatesBtn")
$loadProfileBtn   = $window.FindName("LoadProfileBtn")
$restoreBackupBtn = $window.FindName("RestoreBackupBtn")
$bottomStripBar = $window.FindName("BottomStripBar")
$bottomStripLogoAccentBox = $window.FindName("BottomStripLogoAccentBox")
$bottomStripLogoPath = $window.FindName("BottomStripLogoPath")
$script:AppTitleBar = $window.FindName("AppTitleBar")
$script:AppTitleBarLayoutGrid = $window.FindName("AppTitleBarLayoutGrid")
$script:AppTitleBarIcon = $window.FindName("AppTitleBarIcon")
$script:AppTitleBarText = $window.FindName("AppTitleBarText")
$script:AppMinButton = $window.FindName("AppMinButton")
$script:AppMaxButton = $window.FindName("AppMaxButton")
$script:AppCloseButton = $window.FindName("AppCloseButton")
$script:AppMinGlyphText = $window.FindName("AppMinGlyphText")
$script:AppMaxGlyphText = $window.FindName("AppMaxGlyphText")
$script:AppCloseGlyphText = $window.FindName("AppCloseGlyphText")
try { if ($script:AppTitleBarIcon -and $window.Icon) { $script:AppTitleBarIcon.Source = $window.Icon } } catch {}

if (-not (Test-Path variable:script:TitleBarDragPending)) { $script:TitleBarDragPending = $false }
if (-not (Test-Path variable:script:TitleBarDragStartXRatio)) { $script:TitleBarDragStartXRatio = 0.5 }

try {
  if ($script:AppTitleBar -and $window) {
    $script:AppTitleBar.Add_MouseLeftButtonDown({
      param($sender, $e)
      try {
        if ($e.ChangedButton -ne [System.Windows.Input.MouseButton]::Left) { return }
      } catch {}
      try {
        if ($e.ClickCount -ge 2) {
          if ($window.WindowState -eq [System.Windows.WindowState]::Maximized) {
            $window.WindowState = [System.Windows.WindowState]::Normal
          } else {
            $window.WindowState = [System.Windows.WindowState]::Maximized
          }
          try { $script:TitleBarDragPending = $false } catch {}
          try { Update-CustomTitleBarMaxGlyph } catch {}
          $e.Handled = $true
          return
        }
      } catch {}
      try {
        $script:TitleBarDragPending = $true
        $pos = $e.GetPosition($script:AppTitleBar)
        $aw = [double]$script:AppTitleBar.ActualWidth
        if ($aw -lt 1.0) { $aw = 1.0 }
        $ratio = [double]$pos.X / $aw
        if ($ratio -lt 0.0) { $ratio = 0.0 }
        if ($ratio -gt 1.0) { $ratio = 1.0 }
        $script:TitleBarDragStartXRatio = $ratio
        try { $script:AppTitleBar.CaptureMouse() | Out-Null } catch {}
        $e.Handled = $true
      } catch {}
    })

    $script:AppTitleBar.Add_MouseMove({
      param($sender, $e)
      try {
        if (-not [bool]$script:TitleBarDragPending) { return }
        if ($e.LeftButton -ne [System.Windows.Input.MouseButtonState]::Pressed) { return }
      } catch { return }

      try { $script:TitleBarDragPending = $false } catch {}
      try { $script:AppTitleBar.ReleaseMouseCapture() } catch {}

      try {
        if ($window.WindowState -eq [System.Windows.WindowState]::Maximized) {
          $mp = [System.Windows.Forms.Control]::MousePosition
          $rb = $window.RestoreBounds
          $rw = 0.0
          try { $rw = [double]$rb.Width } catch { $rw = 0.0 }
          if ($rw -lt 300.0) { try { $rw = [double]$window.Width } catch { $rw = 900.0 } }
          if ($rw -lt 300.0) { $rw = 900.0 }
          $ratio = 0.5
          try { $ratio = [double]$script:TitleBarDragStartXRatio } catch { $ratio = 0.5 }
          if ($ratio -lt 0.0) { $ratio = 0.0 }
          if ($ratio -gt 1.0) { $ratio = 1.0 }
          $newLeft = [double]$mp.X - ($rw * $ratio)
          $newTop = [double]$mp.Y - 10.0
          if ($newTop -lt 0.0) { $newTop = 0.0 }
          $window.WindowState = [System.Windows.WindowState]::Normal
          $window.Left = $newLeft
          $window.Top = $newTop
          try { Update-CustomTitleBarMaxGlyph } catch {}
        }
      } catch {}

      try {
        $window.DragMove()
      } catch {}
    })

    $script:AppTitleBar.Add_MouseLeftButtonUp({
      try { $script:TitleBarDragPending = $false } catch {}
      try { $script:AppTitleBar.ReleaseMouseCapture() } catch {}
    })
  }
} catch {}

try {
  if ($script:AppMinButton -and $window) {
    $script:AppMinButton.Add_Click({
      try { $window.WindowState = [System.Windows.WindowState]::Minimized } catch {}
    })
  }
} catch {}

try {
  if ($script:AppMaxButton -and $window) {
    $script:AppMaxButton.Add_Click({
      try {
        if ($window.WindowState -eq [System.Windows.WindowState]::Maximized) {
          $window.WindowState = [System.Windows.WindowState]::Normal
        } else {
          $window.WindowState = [System.Windows.WindowState]::Maximized
        }
      } catch {}
      try { Update-CustomTitleBarMaxGlyph } catch {}
    })
  }
} catch {}

try {
  if ($script:AppCloseButton -and $window) {
    $script:AppCloseButton.Add_Click({ try { $window.Close() } catch {} })
  }
} catch {}

try { Update-CustomTitleBarMaxGlyph } catch {}
try { Sync-CustomTitleBarText } catch {}
try { Apply-CustomTitleBarForeground -Mode ([string]$script:UiThemeMode) } catch {}

function Update-WindowMaximizedInsets {
  try {
    if (-not $window) { return }
    $isMax = ($window.WindowState -eq [System.Windows.WindowState]::Maximized)
    $inset = if ($isMax) { 10.0 } else { 0.0 }
    $topInset = 0.0
    try {
      if ($script:AppTitleBarLayoutGrid) {
        $script:AppTitleBarLayoutGrid.Margin = New-Object System.Windows.Thickness($inset,$topInset,$inset,0)
      }
    } catch {}
    try {
      $tp = $null
      try { $tp = $window.FindName("TopUiPanel") } catch { $tp = $null }
      if ($tp) {
        $tp.Margin = New-Object System.Windows.Thickness($inset,0,$inset,10)
      }
    } catch {}
  } catch {}
}

function Update-WindowShadowByState {
  param(
    [Parameter(Mandatory=$false)][System.Windows.Window]$Window = $script:window
  )
  try {
    if (-not $Window) { return }
    $wc = $null
    try { $wc = [System.Windows.Shell.WindowChrome]::GetWindowChrome($Window) } catch { $wc = $null }
    if (-not $wc) { return }
    $isMax = $false
    try { $isMax = ($Window.WindowState -eq [System.Windows.WindowState]::Maximized) } catch { $isMax = $false }
    if ($isMax) {
      # Disable outer glass frame while maximized so the window snaps cleanly
      # to the monitor work area (no shadow bleed into taskbar).
      try { $wc.GlassFrameThickness = New-Object System.Windows.Thickness 0 } catch {}
      try { $wc.ResizeBorderThickness = New-Object System.Windows.Thickness(5,0,5,5) } catch {}
      try {
        if ("DwmTitleBarNative" -as [type]) {
          $hwnd = Get-WpfWindowHandle -Window $Window
          if ($hwnd -ne [IntPtr]::Zero) {
            $ncrpDisabled = 1  # DWMNCRP_DISABLED
            $cb = 4
            try { [void][DwmTitleBarNative]::DwmSetWindowAttribute($hwnd, 2, [ref]$ncrpDisabled, $cb) } catch {}
          }
        }
      } catch {}
    } else {
      $frameThicknessPx = 1.0
      try { if (Get-IsWindowsBuildAtLeast19044Runtime) { $frameThicknessPx = 0.0 } } catch {}
      try { $wc.GlassFrameThickness = New-Object System.Windows.Thickness($frameThicknessPx) } catch {}
      try { $wc.ResizeBorderThickness = New-Object System.Windows.Thickness 5 } catch {}
      try {
        if ("DwmTitleBarNative" -as [type]) {
          $hwnd = Get-WpfWindowHandle -Window $Window
          if ($hwnd -ne [IntPtr]::Zero) {
            $ncrpEnabled = 2  # DWMNCRP_ENABLED
            $cb = 4
            try { [void][DwmTitleBarNative]::DwmSetWindowAttribute($hwnd, 2, [ref]$ncrpEnabled, $cb) } catch {}
          }
        }
      } catch {}
    }
  } catch {}
}

function Update-BottomStripVisibilityByWindowState {
  try {
    if (-not $bottomStripBar -or -not $window) { return }
    $isMax = $false
    try {
      $isMax = ($window.WindowState -eq [System.Windows.WindowState]::Maximized)
    } catch { $isMax = $false }
    # In maximized mode, keep the strip hidden so the window behaves like a normal
    # work-area maximize and does not intrude into taskbar space.
    if ($isMax) {
      if ($bottomStripBar.Visibility -ne [System.Windows.Visibility]::Collapsed) {
        $bottomStripBar.Visibility = [System.Windows.Visibility]::Collapsed
      }
    } else {
      if ($bottomStripBar.Visibility -ne [System.Windows.Visibility]::Visible) {
        $bottomStripBar.Visibility = [System.Windows.Visibility]::Visible
      }
    }
  } catch {}
}

function Bring-TaskbarToFrontIfMaximized {
  try {
    if (-not $window) { return }
    $isMax = $false
    try { $isMax = ($window.WindowState -eq [System.Windows.WindowState]::Maximized) } catch { $isMax = $false }
    if (-not $isMax) { return }
    if (-not ("CharMapHostNative" -as [type])) { return }
    $SWP_NOMOVE = 0x0002
    $SWP_NOSIZE = 0x0001
    $SWP_NOACTIVATE = 0x0010
    $SWP_SHOWWINDOW = 0x0040
    $flags = [uint32]($SWP_NOMOVE -bor $SWP_NOSIZE -bor $SWP_NOACTIVATE -bor $SWP_SHOWWINDOW)
    $HWND_TOP = [IntPtr]::Zero
    $HWND_TOPMOST = [IntPtr]::new(-1)
    $HWND_NOTOPMOST = [IntPtr]::new(-2)
    $taskbar = [IntPtr]::Zero
    try { $taskbar = [CharMapHostNative]::FindWindow("Shell_TrayWnd", $null) } catch { $taskbar = [IntPtr]::Zero }
    if ($taskbar -ne [IntPtr]::Zero) {
      try { [void][CharMapHostNative]::SetWindowPos($taskbar, $HWND_TOPMOST, 0, 0, 0, 0, $flags) } catch {}
      try { [void][CharMapHostNative]::SetWindowPos($taskbar, $HWND_NOTOPMOST, 0, 0, 0, 0, $flags) } catch {}
      try { [void][CharMapHostNative]::SetWindowPos($taskbar, $HWND_TOP, 0, 0, 0, 0, $flags) } catch {}
    }
    # Secondary taskbars on multi-monitor setups.
    $secondary = [IntPtr]::Zero
    try { $secondary = [CharMapHostNative]::FindWindow("Shell_SecondaryTrayWnd", $null) } catch { $secondary = [IntPtr]::Zero }
    if ($secondary -ne [IntPtr]::Zero) {
      try { [void][CharMapHostNative]::SetWindowPos($secondary, $HWND_TOPMOST, 0, 0, 0, 0, $flags) } catch {}
      try { [void][CharMapHostNative]::SetWindowPos($secondary, $HWND_NOTOPMOST, 0, 0, 0, 0, $flags) } catch {}
      try { [void][CharMapHostNative]::SetWindowPos($secondary, $HWND_TOP, 0, 0, 0, 0, $flags) } catch {}
    }
  } catch {}
}

function Apply-BottomStripBehindTaskbarByWindowState {
  try {
    if (-not $window -or -not $bottomStripBar) { return }
    $isMax = $false
    try { $isMax = ($window.WindowState -eq [System.Windows.WindowState]::Maximized) } catch { $isMax = $false }
    $wa = $null
    try { $wa = [System.Windows.SystemParameters]::WorkArea } catch { $wa = $null }
    if (-not $wa) { return }
    $screenW = 0.0; $screenH = 0.0
    try { $screenW = [double][System.Windows.SystemParameters]::PrimaryScreenWidth } catch { $screenW = 0.0 }
    try { $screenH = [double][System.Windows.SystemParameters]::PrimaryScreenHeight } catch { $screenH = 0.0 }
    $eps = 2.0
    $taskbarBottom = $false
    try {
      $taskbarBottom = (
        ([double]$wa.Top -le $eps) -and
        ([Math]::Abs([double]$wa.Left) -le $eps) -and
        ([double]$wa.Width -ge ($screenW - $eps)) -and
        ([double]$wa.Height -lt ($screenH - $eps))
      )
    } catch { $taskbarBottom = $false }
    if ($isMax -and $taskbarBottom) {
      $stripH = 35.0
      try { $stripH = [double]$bottomStripBar.ActualHeight } catch { $stripH = 35.0 }
      if ($stripH -lt 8.0) {
        try { $stripH = [double]$bottomStripBar.Height } catch { $stripH = 35.0 }
      }
      if ($stripH -lt 8.0) { $stripH = 35.0 }
      $extra = [Math]::Ceiling($stripH + 7.0)
      try { $window.MaxWidth = ([double]$wa.Width + 6.0) } catch {}
      try { $window.MaxHeight = ([double]$wa.Height + [double]$extra) } catch {}
    } elseif ($isMax) {
      # Non-bottom taskbar: preserve standard maximized fit.
      try { $window.MaxWidth = ([double]$wa.Width + 6.0) } catch {}
      try { $window.MaxHeight = [double]$wa.Height } catch {}
    } else {
      # Restore unrestricted max bounds for normal state.
      try { $window.MaxWidth = [double]::PositiveInfinity } catch {}
      try { $window.MaxHeight = [double]::PositiveInfinity } catch {}
    }
  } catch {}
}

function Sync-BottomStripAccentStyle {
  try {
    if ($window -and $bottomStripBar) {
      $base = $null
      try { $base = Resolve-WpfBrush -Value $script:SelectNameAccentBrushExact } catch { $base = $null }
      if ($null -eq $base) { try { $base = Resolve-WpfBrush -Value $window.Resources['SelectNameAccentBrushExact'] } catch { $base = $null } }
      $lightOverride = $false
      try { $lightOverride = Get-IsSystemLightMode } catch { $lightOverride = $false }
      try { $script:IsLightAccentOverrideActive = [bool]$lightOverride } catch {}
      $bb = $null
      if ($lightOverride) {
        try { $bb = Resolve-WpfBrush -Value (New-BrightenedAccentBrush -Brush $base -Factor 1.50) } catch { $bb = $null }
      } else {
        $factor = 0.77
        try { $factor = [double]$script:BottomFrameAccentDarkenFactor } catch { $factor = 0.77 }
        $barScale = 0.50
        try { $barScale = [double]$script:BottomStripBarDarkenScale } catch { $barScale = 0.50 }
        if ($barScale -lt 0.0) { $barScale = 0.0 }
        if ($barScale -gt 1.0) { $barScale = 1.0 }
        $factor = [double]$factor * [double]$barScale
        if ($factor -lt 0.0) { $factor = 0.0 }
        if ($factor -gt 1.0) { $factor = 1.0 }
        try { $bb = Resolve-WpfBrush -Value (New-DarkenedAccentBrush -Brush $base -Factor $factor) } catch { $bb = $null }
      }
      if ($null -eq $bb) { try { $bb = Resolve-WpfBrush -Value $window.Resources['BottomFrameAccentBrush'] } catch { $bb = $null } }
      if ($bb) { $bottomStripBar.Background = $bb }
    }
  } catch {}
  try {
    if ($window -and $bottomStripLogoAccentBox) {
      $lb = $null
      try { $lb = Resolve-WpfBrush -Value $script:SelectNameAccentBrushExact } catch { $lb = $null }
      if ($null -eq $lb) { try { $lb = Resolve-WpfBrush -Value $window.Resources['SelectNameAccentBrushExact'] } catch { $lb = $null } }
      if ($lb) {
        $lightOverride = $false
        try { $lightOverride = Get-IsSystemLightMode } catch { $lightOverride = $false }
        try { $script:IsLightAccentOverrideActive = [bool]$lightOverride } catch {}
        $lbDark = $null
        if ($lightOverride) {
          try { $lbDark = Resolve-WpfBrush -Value (New-BrightenedAccentBrush -Brush $lb -Factor 1.50) } catch { $lbDark = $null }
        } else {
          $logoScale = 0.20
          try { $logoScale = [double]$script:BottomStripLogoBoxDarkenScale } catch { $logoScale = 0.15 }
          if ($logoScale -lt 0.0) { $logoScale = 0.0 }
          if ($logoScale -gt 1.0) { $logoScale = 1.0 }
          try { $lbDark = Resolve-WpfBrush -Value (New-DarkenedAccentBrush -Brush $lb -Factor $logoScale) } catch { $lbDark = $null }
        }
        if ($null -eq $lbDark) { $lbDark = $lb }
        $bottomStripLogoAccentBox.Background = $lbDark
      }
    }
  } catch {}
  try {
    if ($bottomStripLogoPath) {
      $logoFill = $null
      $lightMode = $false
      try { $lightMode = Get-IsSystemLightMode } catch { $lightMode = $false }
      if ($lightMode) {
        try { $logoFill = Resolve-WpfBrush -Value ([System.Windows.Media.Brushes]::Black) } catch { $logoFill = $null }
      } else {
        try { $logoFill = Resolve-WpfBrush -Value ([System.Windows.Media.Brushes]::White) } catch { $logoFill = $null }
      }
      if ($logoFill) { $bottomStripLogoPath.Fill = $logoFill }
    }
  } catch {}
}

