function Refresh-DesktopPassthroughIfEnabled {
  try {
    $enabled = $false
    try { $enabled = [bool]$script:GridWallpaperDesktopPassthrough } catch { $enabled = $false }
    if (-not $enabled) {
      try {
        if ($script:GridWallpaperDesktopPassRefreshTimer -and ($script:GridWallpaperDesktopPassRefreshTimer -is [System.Windows.Threading.DispatcherTimer])) {
          $script:GridWallpaperDesktopPassRefreshTimer.Stop()
        }
      } catch {}
      return
    }
    try { Queue-DesktopPassthroughRefresh } catch {}
  } catch {}
}

function Invoke-DesktopPassthroughRefreshNow {
  try {
    $enabled = $false
    try { $enabled = [bool]$script:GridWallpaperDesktopPassthrough } catch { $enabled = $false }
    if (-not $enabled) { return }
    if ([bool]$script:GridWallpaperDesktopPassRefreshInFlight) { return }
    $script:GridWallpaperDesktopPassRefreshInFlight = $true
    try {
      if ($grid) {
        try { Set-GridWallpaperBackground -Grid $grid } catch {}
        try { $grid.InvalidateVisual() } catch {}
      }
    } finally {
      $script:GridWallpaperDesktopPassRefreshInFlight = $false
    }
  } catch {}
}

function Queue-DesktopPassthroughRefresh {
  param([switch]$Immediate)
  try {
    $enabled = $false
    try { $enabled = [bool]$script:GridWallpaperDesktopPassthrough } catch { $enabled = $false }
    if (-not $enabled) { return }
    if ($Immediate) {
      try { Invoke-DesktopPassthroughRefreshNow } catch {}
      return
    }
    if (-not ($script:GridWallpaperDesktopPassRefreshTimer -and ($script:GridWallpaperDesktopPassRefreshTimer -is [System.Windows.Threading.DispatcherTimer]))) {
      $t = New-Object System.Windows.Threading.DispatcherTimer
      $ms = 260.0
      try { $ms = [double]$script:GridWallpaperDesktopPassRefreshDebounceMs } catch { $ms = 260.0 }
      if ($ms -lt 80.0) { $ms = 80.0 }
      if ($ms -gt 1200.0) { $ms = 1200.0 }
      try { $t.Interval = [TimeSpan]::FromMilliseconds($ms) } catch { $t.Interval = [TimeSpan]::FromMilliseconds(260.0) }
      $t.Add_Tick({
        try { if ($script:GridWallpaperDesktopPassRefreshTimer) { $script:GridWallpaperDesktopPassRefreshTimer.Stop() } } catch {}
        try { Invoke-DesktopPassthroughRefreshNow } catch {}
      })
      $script:GridWallpaperDesktopPassRefreshTimer = $t
    }
    try {
      $script:GridWallpaperDesktopPassRefreshTimer.Stop()
      $script:GridWallpaperDesktopPassRefreshTimer.Start()
    } catch {}
  } catch {}
}

try { $window.Add_LocationChanged({ try { Queue-DesktopPassthroughRefresh } catch {} }) } catch {}
try { $window.Add_SizeChanged({ try { Queue-DesktopPassthroughRefresh } catch {} }) } catch {}

function Update-RenameButtonState {
  try {
    $iconEnabled = $false
    try {
      foreach ($r in @($script:CurrentView)) {
        if (-not $r) { continue }
        $sel = $false
        try { $sel = [bool]$r.Selected } catch { $sel = $false }
        if (-not $sel) { continue }
        $isAlpha = $false
        try { $isAlpha = (Test-IsAlphaSeparatorRow -Row $r) } catch {}
        if ($isAlpha) { continue }
        $isFolder = $false
        try { $isFolder = ([string](Get-PropString -Obj $r -Names @('RowKind') -Fallback '') -eq 'Folder') } catch {}
        if ($isFolder) { continue }
        $isPendingCreate = $false
        try { $isPendingCreate = ($r.PSObject.Properties.Match('IsPendingCreate').Count -gt 0 -and [bool]$r.IsPendingCreate) } catch {}
        if ($isPendingCreate) { continue }
        $act = ''
        try { $act = [string](Get-PropString -Obj $r -Names @('Action') -Fallback '') } catch { $act = '' }
        if ($act -eq 'Delete') { continue }
        $p = Resolve-ExistingShortcutPathForRow -Row $r
        if ([string]::IsNullOrWhiteSpace($p)) { continue }
        $iconEnabled = $true
        break
      }
    } catch {}
    if (-not $iconEnabled) {
      $row = $null
      try { $row = $grid.SelectedItem } catch {}
      if ($row -and (Test-IsIconChangeEligibleRow -Row $row)) { $iconEnabled = $true }
    }
  } catch {}
}

function Apply-DefaultGridColumnOrder {
  if (-not $grid) { return }
  $desired = @('Select','Name','Pending','Type','Target','Path')
  for ($i = 0; $i -lt $desired.Count; $i++) {
    $hdr = [string]$desired[$i]
    foreach ($c in @($grid.Columns)) {
      if (-not $c) { continue }
      $ch = ''
      try { $ch = [string]$c.Header } catch { $ch = '' }
      if ($ch -eq $hdr) {
        try { $c.DisplayIndex = $i } catch {}
        break
      }
    }
  }
}

if ($grid) {
  if (-not (Test-Path variable:script:GridSeparatorSelectionGuard)) { $script:GridSeparatorSelectionGuard = $false }
  $grid.Add_SelectionChanged({
    try {
      if (-not [bool]$script:GridSeparatorSelectionGuard) {
        $separatorRows = @()
        try {
          foreach ($it in @($grid.SelectedItems)) {
            if (Test-IsAlphaSeparatorRow -Row $it) { $separatorRows += $it }
          }
        } catch {}

        if ($separatorRows.Count -gt 0) {
          $anchor = $null
          try {
            foreach ($ai in @($e.AddedItems)) {
              if (Test-IsAlphaSeparatorRow -Row $ai) { $anchor = $ai; break }
            }
          } catch {}
          if (-not $anchor) { $anchor = $separatorRows[0] }

          $anchorIndex = -1
          try { $anchorIndex = $grid.Items.IndexOf($anchor) } catch {}
          if ($anchorIndex -lt 0) {
            try {
              $items = @($grid.ItemsSource)
              for ($i = 0; $i -lt $items.Count; $i++) {
                if ([object]::ReferenceEquals($items[$i], $anchor)) { $anchorIndex = $i; break }
              }
            } catch {}
          }

          foreach ($sep in @($separatorRows)) {
            try { [void]$grid.SelectedItems.Remove($sep) } catch {}
          }

          $fallback = $null
          try { $fallback = Get-NearestNonSeparatorGridRow -AnchorIndex $anchorIndex } catch {}
          if ($fallback) {
            $script:GridSeparatorSelectionGuard = $true
            try {
              $grid.SelectedItem = $fallback
              try {
                $nameCol = Get-GridNameColumn
                if ($nameCol) {
                  $grid.CurrentCell = New-Object System.Windows.Controls.DataGridCellInfo($fallback, $nameCol)
                }
              } catch {}
              try { $grid.ScrollIntoView($fallback) } catch {}
            } finally {
              $script:GridSeparatorSelectionGuard = $false
            }
          } else {
            try { $grid.UnselectAll() } catch {}
          }
        }
      }
    } catch {}

    try { [void](Invoke-CommitActiveInlineRenameIfNeeded -Reason 'GridSelectionChanged') } catch {}
    try { [void](Invoke-CommitEditPanelPreviewOnRowSwitch -Reason 'EditPanelRowSwitch') } catch {}
    Update-RenameButtonState
    try { Sync-CreateEditSelectedFields } catch {}
  })
}
