function Show-BusyOverlay {
  param([string]$Status = "Working...")
  try {
    $depth = 0
    try { $depth = [int]$script:BusyOverlayDepth } catch { $depth = 0 }
    $depth++
    if ($depth -lt 1) { $depth = 1 }
    $script:BusyOverlayDepth = $depth
    try { if ($script:BusyOverlayStatusText) { $script:BusyOverlayStatusText.Text = [string]$Status } } catch {}
    try { if ($script:BusyOverlayHost) { $script:BusyOverlayHost.Visibility = [System.Windows.Visibility]::Visible } } catch {}
    try { if ($window) { $window.Cursor = [System.Windows.Input.Cursors]::Wait } } catch {}
    try {
      if ($window -and $window.Dispatcher) {
        $null = $window.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
      }
    } catch {}
  } catch {}
}
function Hide-BusyOverlay {
  try {
    $depth = 0
    try { $depth = [int]$script:BusyOverlayDepth } catch { $depth = 0 }
    $depth--
    if ($depth -gt 0) {
      $script:BusyOverlayDepth = $depth
      return
    }
    $script:BusyOverlayDepth = 0
    try { if ($script:BusyOverlayHost) { $script:BusyOverlayHost.Visibility = [System.Windows.Visibility]::Collapsed } } catch {}
    try { if ($window) { $window.Cursor = $null } } catch {}
    try {
      if ($window -and $window.Dispatcher) {
        $null = $window.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
      }
    } catch {}
  } catch {}
}
function Invoke-WithBusyOverlay {
  param(
    [string]$Status = "Working...",
    [scriptblock]$Action
  )
  if (-not $Action) { return }
  Show-BusyOverlay -Status $Status
  try { & $Action } finally { Hide-BusyOverlay }
}

if (-not (Test-Path variable:script:MainPanelMinLeftPx)) { $script:MainPanelMinLeftPx = 330.0 }
if (-not (Test-Path variable:script:MainPanelMinRightPx)) { $script:MainPanelMinRightPx = 330.0 }
if (-not (Test-Path variable:script:MainPanelPinnedRightWidthPx)) { $script:MainPanelPinnedRightWidthPx = 0.0 }
if (-not (Test-Path variable:script:MainPanelBaseWindowMinWidthPx)) { $script:MainPanelBaseWindowMinWidthPx = 700.0 }
if (-not (Test-Path variable:script:MainPanelBaseWindowMinHeightPx)) { $script:MainPanelBaseWindowMinHeightPx = 500.0 }

function Enforce-MainPanelSplitterBounds {
  param([switch]$CaptureCurrentRightWidth)
  try {
    $host = $null
    try { $host = $rootUiGrid -as [System.Windows.Controls.Grid] } catch { $host = $null }
    $leftCol = $mainLeftHostCol
    $splitCol = $mainSplitterCol
    $rightCol = $mainRightPanelCol
    if (-not $leftCol -or -not $splitCol -or -not $rightCol) {
      if (-not $mainPanelsSplitter) { return }
      try { $host = $mainPanelsSplitter.Parent -as [System.Windows.Controls.Grid] } catch { $host = $null }
      if (-not $host) { return }
      if ($host.ColumnDefinitions.Count -lt 3) { return }
      $leftCol = $host.ColumnDefinitions[0]
      $splitCol = $host.ColumnDefinitions[1]
      $rightCol = $host.ColumnDefinitions[2]
    }
    if (-not $host -or -not $leftCol -or -not $splitCol -or -not $rightCol) { return }
    $minLeftBase = 330.0
    $minRightBase = 330.0
    try { $minLeftBase = [double]$script:MainPanelMinLeftPx } catch { $minLeftBase = 330.0 }
    try { $minRightBase = [double]$script:MainPanelMinRightPx } catch { $minRightBase = 330.0 }
    $hostW = 0.0
    try { $hostW = [double]$host.ActualWidth } catch { $hostW = 0.0 }
    if ($hostW -le 0.0) { return }
    $splitW = 0.0
    try { $splitW = [double]$mainPanelsSplitter.ActualWidth } catch { $splitW = 0.0 }
    if ($splitW -le 0.0) { try { $splitW = [double]$splitCol.ActualWidth } catch { $splitW = 0.0 } }
    if ($splitW -lt 0.0) { $splitW = 0.0 }
    if ($CaptureCurrentRightWidth) {
      $probe = 0.0
      try { $probe = [double]$rightCol.ActualWidth } catch { $probe = 0.0 }
      if ($probe -le 0.0) {
        try { $probe = [double]$rightCol.Width.Value } catch { $probe = 0.0 }
      }
      if ($probe -gt 0.0) {
        try { $script:MainPanelPinnedRightWidthPx = $probe } catch {}
      }
    }
    $desiredRight = 0.0
    try { $desiredRight = [double]$script:MainPanelPinnedRightWidthPx } catch { $desiredRight = 0.0 }
    if ($desiredRight -le 0.0) {
      try { $desiredRight = [double]$rightCol.ActualWidth } catch { $desiredRight = 0.0 }
      if ($desiredRight -le 0.0) {
        try { $desiredRight = [double]$rightCol.Width.Value } catch { $desiredRight = 0.0 }
      }
      if ($desiredRight -le 0.0) { $desiredRight = $minRight }
      try { $script:MainPanelPinnedRightWidthPx = $desiredRight } catch {}
    }
    if ($desiredRight -lt $minRight) { $desiredRight = $minRight }
    $baseMinW = 700.0
    $baseMinH = 500.0
    try { $baseMinW = [double]$script:MainPanelBaseWindowMinWidthPx } catch { $baseMinW = 700.0 }
    try { $baseMinH = [double]$script:MainPanelBaseWindowMinHeightPx } catch { $baseMinH = 500.0 }
    $chromeW = 0.0
    try { $chromeW = [Math]::Max(0.0, ([double]$window.ActualWidth - [double]$hostW)) } catch { $chromeW = 0.0 }
    $needW = [Math]::Ceiling([double]$minLeftBase + [double]$splitW + [double]$desiredRight + [double]$chromeW)
    if ($needW -lt $baseMinW) { $needW = $baseMinW }
    try { if ([double]$window.MinWidth -lt [double]$needW) { $window.MinWidth = [double]$needW } } catch {}
    try { $window.MinHeight = [double]$baseMinH } catch {}
    if ((-not $CaptureCurrentRightWidth) -and ([double]$window.Width -lt [double]$needW)) {
      try { $window.Width = [double]$needW } catch {}
      return
    }
    $available = $hostW - $splitW
    if ($available -le 0.0) { return }
    $rightW = $desiredRight
    $leftW = $available - $rightW
    if ($leftW -lt $minLeftBase) {
      $leftW = $minLeftBase
      $rightW = [Math]::Max($minRightBase, ($available - $leftW))
    }
    if ($rightW -lt $minRightBase) { $rightW = $minRightBase }
    try { $leftCol.MinWidth = [double]$minLeftBase } catch {}
    try { $rightCol.MinWidth = [double]$minRightBase } catch {}
    try { $leftCol.Width = New-Object System.Windows.GridLength($leftW, [System.Windows.GridUnitType]::Pixel) } catch {}
    try { $rightCol.Width = New-Object System.Windows.GridLength($rightW, [System.Windows.GridUnitType]::Pixel) } catch {}
    try { $splitCol.Width = New-Object System.Windows.GridLength($splitW, [System.Windows.GridUnitType]::Pixel) } catch {}
    if ($CaptureCurrentRightWidth) {
      try { $script:MainPanelPinnedRightWidthPx = [double]$rightW } catch {}
    }
  } catch {}
}

