if (-not (Test-Path variable:script:TopUiHoverWiredByHash)) { $script:TopUiHoverWiredByHash = @{} }

function Get-TopUiButtonHoverBrush {
  try {
    $isDark = $false
    try {
      $b = $null
      try { if ($window) { $b = $window.Background } } catch {}
      if (-not $b) {
        try { if ($window) { $b = $window.Resources['UiSurfaceBrush'] } } catch {}
      }
      try { $b = ([System.Management.Automation.PSObject]::AsPSObject($b)).BaseObject } catch {}
      $sb = $b -as [System.Windows.Media.SolidColorBrush]
      if ($sb) {
        $c = $sb.Color
        $lum = ((0.2126 * [double]$c.R) + (0.7152 * [double]$c.G) + (0.0722 * [double]$c.B)) / 255.0
        $isDark = ($lum -lt 0.45)
      } else {
        $isDark = (([string]$script:UiThemeMode) -ieq 'Dark')
      }
    } catch {
      $isDark = (([string]$script:UiThemeMode) -ieq 'Dark')
    }
    $hex = if ($isDark) { '#373737' } else { '#d0d0d0' }
    return (New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($hex)))
  } catch {
    return (New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString('#939393')))
  }
}

function Apply-TopUiButtonHoverTheme {
  try {
    $topButtons = @(
      $undoBtn,$redoBtn,$mockDeleteBtn,$unDeleteBtn,$prepareStartMenuBtn,$saveProfileBtn,$restoreBackupBtn,
      $savePendingStatesBtn,$loadProfileBtn,$refreshBtn,$resetBtn,$applyBtn,$infoBtn,$uiThemeToggleBtn
    )
    foreach ($btn in $topButtons) {
      if (-not $btn) { continue }
      $k = ''
      try { $k = [string]$btn.GetHashCode() } catch { $k = '' }
      if (-not [string]::IsNullOrWhiteSpace($k) -and -not $script:TopUiHoverWiredByHash.ContainsKey($k)) {
        $btn.Add_MouseEnter({
          param($sender, $e)
          try {
            if (-not $sender.IsEnabled) { return }
            $sender.Background = Get-TopUiButtonHoverBrush
          } catch {}
        })
        $btn.Add_MouseLeave({
          param($sender, $e)
          try { $sender.ClearValue([System.Windows.Controls.Control]::BackgroundProperty) } catch {}
        })
        $btn.Add_PreviewMouseLeftButtonDown({
          param($sender, $e)
          try {
            if (-not $sender.IsEnabled) { return }
            $sender.Background = Get-TopUiButtonHoverBrush
          } catch {}
        })
        $btn.Add_PreviewMouseLeftButtonUp({
          param($sender, $e)
          try {
            if ($sender.IsMouseOver) {
              $sender.Background = Get-TopUiButtonHoverBrush
            } else {
              $sender.ClearValue([System.Windows.Controls.Control]::BackgroundProperty)
            }
          } catch {}
        })
        $btn.Add_LostMouseCapture({
          param($sender, $e)
          try {
            if ($sender.IsMouseOver) {
              $sender.Background = Get-TopUiButtonHoverBrush
            } else {
              $sender.ClearValue([System.Windows.Controls.Control]::BackgroundProperty)
            }
          } catch {}
        })
        $script:TopUiHoverWiredByHash[$k] = $true
      }
      try {
        if (-not $btn.IsEnabled) {
          $btn.ClearValue([System.Windows.Controls.Control]::BackgroundProperty)
        } elseif ($btn.IsMouseOver) {
          $btn.Background = Get-TopUiButtonHoverBrush
        } else {
          $btn.ClearValue([System.Windows.Controls.Control]::BackgroundProperty)
        }
      } catch {}
    }
  } catch {}
}

