function Apply-GridHeaderTheme {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Media.Brush]$BackgroundBrush,
    [Parameter(Mandatory=$true)][System.Windows.Media.Brush]$ForegroundBrush,
    [Parameter(Mandatory=$true)][System.Windows.Media.Brush]$BorderBrush
  )
  try {
    if (-not $grid) { return }
    $hp = $null
    try { $hp = Find-VisualChild -Parent $grid -Type ([System.Windows.Controls.Primitives.DataGridColumnHeadersPresenter]) } catch { $hp = $null }
    if (-not $hp) { return }
    try { $hp.Background = $BackgroundBrush } catch {}
    try {
      $isDark = ($script:UiThemeMode -ieq 'Dark')
      $hdrShadow = New-Object System.Windows.Media.Effects.DropShadowEffect
      $hdrShadow.Color = [System.Windows.Media.Color]::FromArgb(255,0,0,0)
      $hdrShadow.BlurRadius = 12
      $hdrShadow.ShadowDepth = 2
      $hdrShadow.Direction = 270
      $hdrShadow.Opacity = if ($isDark) { 0.30 } else { 0.20 }
      $hdrShadow.RenderingBias = [System.Windows.Media.Effects.RenderingBias]::Performance
      $hp.Effect = $hdrShadow
    } catch {}
    try {
      if ($script:GridHeaderShadowBand) {
        $isDark = ($script:UiThemeMode -ieq 'Dark')
        $headerHeight = 38.0
        try {
          if ($hp.ActualHeight -gt 0) { $headerHeight = [double]$hp.ActualHeight }
        } catch {}
        $shadowHeight = if ($isDark) { 16.0 } else { 14.0 }
        $shadowTopA = if ($isDark) { 120 } else { 88 }
        $shadowMidA = if ($isDark) { 56 } else { 36 }
        $g = New-Object System.Windows.Media.LinearGradientBrush
        $g.StartPoint = New-Object System.Windows.Point(0,0)
        $g.EndPoint   = New-Object System.Windows.Point(0,1)
        $cTop = [System.Windows.Media.Color]::FromArgb([byte]$shadowTopA,0,0,0)
        $cMid = [System.Windows.Media.Color]::FromArgb([byte]$shadowMidA,0,0,0)
        $cBot = [System.Windows.Media.Color]::FromArgb(0,0,0,0)
        [void]$g.GradientStops.Add((New-Object System.Windows.Media.GradientStop($cTop, 0.00)))
        [void]$g.GradientStops.Add((New-Object System.Windows.Media.GradientStop($cMid, 0.30)))
        [void]$g.GradientStops.Add((New-Object System.Windows.Media.GradientStop($cBot, 0.80)))
        $script:GridHeaderShadowBand.Background = $g
        $script:GridHeaderShadowBand.Height = $shadowHeight
        $script:GridHeaderShadowBand.Margin = New-Object System.Windows.Thickness(0,[double]$headerHeight,0,0)
        $script:GridHeaderShadowBand.Opacity = 1.0
        try { [System.Windows.Controls.Panel]::SetZIndex($script:GridHeaderShadowBand, 2) } catch {}
      }
    } catch {}
    try {
      $hp.Resources[[System.Windows.SystemColors]::ControlDarkBrushKey] = ([System.Management.Automation.PSObject]::AsPSObject($BorderBrush)).BaseObject
      $hp.Resources[[System.Windows.SystemColors]::ActiveBorderBrushKey] = ([System.Management.Automation.PSObject]::AsPSObject($BorderBrush)).BaseObject
      $hp.Resources[[System.Windows.SystemColors]::InactiveBorderBrushKey] = ([System.Management.Automation.PSObject]::AsPSObject($BorderBrush)).BaseObject
    } catch {}
    $stack = New-Object 'System.Collections.Generic.Stack[System.Windows.DependencyObject]'
    $stack.Push($hp)
    while ($stack.Count -gt 0) {
      $node = $stack.Pop()
      try {
        if ($node -is [System.Windows.Controls.Primitives.DataGridColumnHeader]) {
          $node.Background = $BackgroundBrush
          $node.Foreground = $ForegroundBrush
          $node.BorderBrush = $BorderBrush
          try {
            $node.SetValue([System.Windows.Controls.Primitives.DataGridColumnHeader]::SeparatorBrushProperty, $BorderBrush)
          } catch {}
          try {
            $node.Resources[[System.Windows.SystemColors]::ControlDarkBrushKey] = ([System.Management.Automation.PSObject]::AsPSObject($BorderBrush)).BaseObject
            $node.Resources[[System.Windows.SystemColors]::ActiveBorderBrushKey] = ([System.Management.Automation.PSObject]::AsPSObject($BorderBrush)).BaseObject
            $node.Resources[[System.Windows.SystemColors]::InactiveBorderBrushKey] = ([System.Management.Automation.PSObject]::AsPSObject($BorderBrush)).BaseObject
          } catch {}
        } elseif ($node -is [System.Windows.Controls.Border]) {
          $bt = $null
          try { $bt = $node.BorderThickness } catch { $bt = $null }
          if ($bt) {
            $hasBorder = $false
            try {
              $hasBorder = (([double]$bt.Left -gt 0.0) -or ([double]$bt.Top -gt 0.0) -or ([double]$bt.Right -gt 0.0) -or ([double]$bt.Bottom -gt 0.0))
            } catch { $hasBorder = $false }
            if ($hasBorder) {
              try { $node.BorderBrush = $BorderBrush } catch {}
            }
          }
        }
      } catch {}
      $cc = 0
      try { $cc = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($node) } catch { $cc = 0 }
      for ($i = 0; $i -lt $cc; $i++) {
        try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($node, $i)) } catch {}
      }
    }
  } catch {}
}

function Apply-GridHeaderSeparatorTheme {
  try {
    if (-not $grid) { return }
    $hp = $null
    try { $hp = Find-VisualChild -Parent $grid -Type ([System.Windows.Controls.Primitives.DataGridColumnHeadersPresenter]) } catch { $hp = $null }
    if (-not $hp) { return }
    $sepHex = if (([string]$script:UiThemeMode -ieq 'Dark')) { '#3A3A3A' } else { '#c0c0c0' }
    $sepBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($sepHex))
    $stack = New-Object 'System.Collections.Generic.Stack[System.Windows.DependencyObject]'
    $stack.Push($hp)
    while ($stack.Count -gt 0) {
      $node = $stack.Pop()
      try {
        if ($node -is [System.Windows.Controls.Primitives.DataGridColumnHeader]) {
          try { $node.SetValue([System.Windows.Controls.Primitives.DataGridColumnHeader]::SeparatorBrushProperty, $sepBrush) } catch {}
          try { $node.BorderBrush = $sepBrush } catch {}
        } elseif ($node -is [System.Windows.Shapes.Rectangle]) {
          $w = 0.0
          try { $w = [double]$node.Width } catch { $w = 0.0 }
          if ($w -le 1.5 -and $w -gt 0.0) {
            try { $node.Fill = $sepBrush } catch {}
          }
        } elseif ($node -is [System.Windows.Controls.Border]) {
          $bt = $null
          try { $bt = $node.BorderThickness } catch { $bt = $null }
          if ($bt) {
            $hasBorder = $false
            try { $hasBorder = (([double]$bt.Left -gt 0.0) -or ([double]$bt.Right -gt 0.0)) } catch { $hasBorder = $false }
            if ($hasBorder) { try { $node.BorderBrush = $sepBrush } catch {} }
          }
        }
      } catch {}
      $cc = 0
      try { $cc = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($node) } catch { $cc = 0 }
      for ($i = 0; $i -lt $cc; $i++) {
        try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($node, $i)) } catch {}
      }
    }
  } catch {}
}

function Apply-ExplicitUiPanelTabColors {
  param(
    [Parameter(Mandatory=$false)][ValidateSet('Light','Dark')][string]$Mode = ''
  )
  try {
    if ([string]::IsNullOrWhiteSpace($Mode)) {
      try { $Mode = [string]$script:UiThemeMode } catch { $Mode = 'Light' }
    }
    $isDark = ($Mode -ieq 'Dark')
    $idleHex = if ($isDark) { '#202020' } else { '#E4E4E4' }
    $activeHex = if ($isDark) { '#2A2A2A' } else { '#FFFFFF' }
    $textHex = if ($isDark) { '#7c7c7c' } else { '#202020' }
    $borderHex = if ($isDark) { '#3A3A3A' } else { '#DDDDDD' }
    $idleBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($idleHex))
    $activeBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($activeHex))
    $textBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($textHex))
    $borderBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($borderHex))
    $tabStyle = $null
    try { $tabStyle = $window.Resources['UiPanelTabItemStyle'] -as [System.Windows.Style] } catch { $tabStyle = $null }
    try { Apply-UiPanelTabPositionParity } catch {}
    foreach ($tc in @($rightPanelTabs, $createIconTabs)) {
      try {
        if (-not $tc) { continue }
        try { $tc.Resources['UiTabIdleBrush']   = ([System.Management.Automation.PSObject]::AsPSObject($idleBrush)).BaseObject } catch {}
        try { $tc.Resources['UiTabActiveBrush'] = ([System.Management.Automation.PSObject]::AsPSObject($activeBrush)).BaseObject } catch {}
        try { $tc.Resources['UiTextBrush']      = ([System.Management.Automation.PSObject]::AsPSObject($textBrush)).BaseObject } catch {}
        try { $tc.Resources['UiBorderBrush']    = ([System.Management.Automation.PSObject]::AsPSObject($borderBrush)).BaseObject } catch {}
        try { if ($tabStyle) { $tc.ItemContainerStyle = $tabStyle } } catch {}
        try { $tc.Background = $idleBrush } catch {}
        try { $tc.Foreground = $textBrush } catch {}
        foreach ($it in @($tc.Items)) {
          $ti = $it -as [System.Windows.Controls.TabItem]
          if (-not $ti) { continue }
          $isSel = $false
          try { $isSel = [bool]$ti.IsSelected } catch { $isSel = $false }
          $tabBg = $(if ($isSel) { $activeBrush } else { $idleBrush })
          try { if ($tabStyle) { $ti.Style = $tabStyle } } catch {}
          try { $ti.Resources['UiTabIdleBrush']   = ([System.Management.Automation.PSObject]::AsPSObject($idleBrush)).BaseObject } catch {}
          try { $ti.Resources['UiTabActiveBrush'] = ([System.Management.Automation.PSObject]::AsPSObject($activeBrush)).BaseObject } catch {}
          try { $ti.Resources['UiTextBrush']      = ([System.Management.Automation.PSObject]::AsPSObject($textBrush)).BaseObject } catch {}
          try { $ti.Resources['UiBorderBrush']    = ([System.Management.Automation.PSObject]::AsPSObject($borderBrush)).BaseObject } catch {}
          try { $ti.Background = $tabBg } catch {}
          try { $ti.Foreground = $textBrush } catch {}
          try { $ti.BorderBrush = $borderBrush } catch {}
          try { $ti.BorderThickness = New-Object System.Windows.Thickness(1) } catch {}
          try {
            $null = $ti.ApplyTemplate()
            $hdr = $ti.Template.FindName('TabHeaderBorder', $ti)
            if ($hdr -is [System.Windows.Controls.Border]) {
              $hdr.Background = $tabBg
              $hdr.BorderBrush = $borderBrush
              $hdr.BorderThickness = New-Object System.Windows.Thickness(1)
            }
          } catch {}
          try { $ti.InvalidateVisual() } catch {}
          try { $ti.UpdateLayout() } catch {}
        }
        try { $tc.InvalidateVisual() } catch {}
        try { $tc.UpdateLayout() } catch {}
      } catch {}
    }
    # Force the named right-panel tabs explicitly to avoid any default system style bleed-through.
    foreach ($ti in @($profilesTab, $createTab, $miscTab, $createSystemIconsTab, $createCustomIconTab, $createCharMapTab)) {
      try {
        if (-not $ti) { continue }
        $isSel = $false
        try { $isSel = [bool]$ti.IsSelected } catch { $isSel = $false }
        $tabBg = $(if ($isSel) { $activeBrush } else { $idleBrush })
        try { if ($tabStyle) { $ti.Style = $tabStyle } } catch {}
        try { $ti.Background = $tabBg } catch {}
        try { $ti.Foreground = $textBrush } catch {}
        try { $ti.BorderBrush = $borderBrush } catch {}
        try { $ti.BorderThickness = New-Object System.Windows.Thickness(1) } catch {}
        try {
          $null = $ti.ApplyTemplate()
          $hdr = $ti.Template.FindName('TabHeaderBorder', $ti)
          if ($hdr -is [System.Windows.Controls.Border]) {
            $hdr.Background = $tabBg
            $hdr.BorderBrush = $borderBrush
          }
        } catch {}
      } catch {}
    }
  } catch {}
}

function Apply-UiPanelTabPositionParity {
  try {
    $ctrlMargin = New-Object System.Windows.Thickness(-6,-4,0,0)
    $ctrlPadding = New-Object System.Windows.Thickness(0)
    if ($rightPanelTabs) {
      try { $rightPanelTabs.Margin = $ctrlMargin } catch {}
      try { $rightPanelTabs.Padding = $ctrlPadding } catch {}
    }
    if ($createIconTabs) {
      try { $createIconTabs.Margin = New-Object System.Windows.Thickness(-8,0,-8,-8) } catch {}
      try { $createIconTabs.Padding = $ctrlPadding } catch {}
      try { $createIconTabs.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Stretch } catch {}
      try { $createIconTabs.VerticalAlignment = [System.Windows.VerticalAlignment]::Stretch } catch {}
    }
    if ($profilesTab)          { try { $profilesTab.Margin = New-Object System.Windows.Thickness(0,0,0,-1) } catch {} }
    if ($createTab)            { try { $createTab.Margin = New-Object System.Windows.Thickness(-2,0,2,-1) } catch {} }
    if ($miscTab)              { try { $miscTab.Margin = New-Object System.Windows.Thickness(2,0,-2,-1) } catch {} }
    if ($createSystemIconsTab) { try { $createSystemIconsTab.Margin = New-Object System.Windows.Thickness(-2,0,2,-1) } catch {} }
    if ($createCustomIconTab)  { try { $createCustomIconTab.Margin = New-Object System.Windows.Thickness(0,0,0,-1) } catch {} }
    if ($createCharMapTab)     { try { $createCharMapTab.Margin = New-Object System.Windows.Thickness(2,0,-2,-1) } catch {} }
  } catch {}
}

function Apply-SystemIconNavButtonTheme {
  try {
    $isDark = ($script:UiThemeMode -ieq 'Dark')
    $baseHex = if ($isDark) { '#2A2A2A' } else { '#E4E4E4' }
    $hoverHex = if ($isDark) { '#373737' } else { '#c8c8c8' }
    $borderHex = if ($isDark) { '#3A3A3A' } else { '#BEBEBE' }
    $textHex = if ($isDark) { '#7c7c7c' } else { '#202020' }
    $baseBtnBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($baseHex))
    $hoverBtnBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($hoverHex))
    $baseBorderBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($borderHex))
    $textBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($textHex))
    foreach ($btn in @($createSystemIconCategoryFilterBtn, $createSystemIconPrevPageBtn, $createSystemIconNextPageBtn, $createSystemIconSelectAllBtn, $createSystemIconClearAllBtn)) {
      try {
        if (-not $btn) { continue }
        if ($btn -is [System.Windows.Controls.Primitives.ToggleButton]) {
          try { $btn.Style = $window.Resources['RightPanelNavToggleStyle'] } catch {}
        } else {
          try { $btn.Style = $window.Resources['RightPanelNavButtonStyle'] } catch {}
        }
        $btn.Background = $baseBtnBrush
        $btn.BorderBrush = $baseBorderBrush
        $btn.Foreground = $textBrush
        try { $btn.Opacity = if ($btn.IsEnabled) { 1.0 } else { 0.6 } } catch {}
        try {
          $null = $btn.ApplyTemplate()
          $bd = $null
          try { $bd = $btn.Template.FindName('BtnBorder', $btn) } catch {}
          if (-not $bd) { try { $bd = $btn.Template.FindName('TglBorder', $btn) } catch {} }
          if ($bd -is [System.Windows.Controls.Border]) {
            $bd.Background = $baseBtnBrush
            $bd.BorderBrush = $baseBorderBrush
          }
        } catch {}
        try {
          $btn.Tag = @{
            BaseBrush   = $baseBtnBrush
            HoverBrush  = $hoverBtnBrush
            BorderBrush = $baseBorderBrush
          }
        } catch {}
      } catch {}
    }
  } catch {}
}

