function Set-UiThemeMode {
  param(
    [Parameter(Mandatory=$true)][ValidateSet('Light','Dark')][string]$Mode
  )
  try {
    $script:UiThemeMode = if ($Mode -ieq 'Dark') { 'Dark' } else { 'Light' }
    $surfaceHex = if ($script:UiThemeMode -ieq 'Dark') { '#202020' } else { '#E1E1E1' }
    $panelHex   = if ($script:UiThemeMode -ieq 'Dark') { '#202020' } else { '#E1E1E1' }
    $textHex    = if ($script:UiThemeMode -ieq 'Dark') { '#7c7c7c' } else { '#202020' }
