    function Set-Brush {
      param([string]$Key,[string]$Hex)
      try {
        $colorObj = [System.Windows.Media.ColorConverter]::ConvertFromString($Hex)
        $color = [System.Windows.Media.Color]$colorObj
        $existing = $null
        try { $existing = $window.Resources[$Key] } catch { $existing = $null }
        try { $existing = ([System.Management.Automation.PSObject]::AsPSObject($existing)).BaseObject } catch {}
        $brush = $existing -as [System.Windows.Media.SolidColorBrush]
        if (-not $brush -or $brush.IsFrozen) {
          $newBrush = New-Object System.Windows.Media.SolidColorBrush($color)
          $rawBrush = ([System.Management.Automation.PSObject]::AsPSObject($newBrush)).BaseObject
          $window.Resources[$Key] = $rawBrush
        } else {
          $brush.Color = $color
        }
      } catch {}
    }
