    Set-Brush -Key 'UiPanelButtonBorderBrush' -Hex $panelBtnBorderHex
    Set-Brush -Key 'UiApplyBorderBrush' -Hex $applyBtnBorderHex
    Set-Brush -Key 'UiSortComboBgBrush'    -Hex $sortComboBgHex
