    $addonsPanelBorderBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($addonsPanelBorderHex))
    $sortBgBrush  = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($sortComboBgHex))
    $sortPopupBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($sortComboPopupHex))
    $sortHoverBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($sortComboHoverHex))
    $uiPanelScrollTrackBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($uiPanelScrollTrackHex))
    $uiPanelScrollThumbBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($uiPanelScrollThumbHex))
    $inputBgHex   = if ($script:UiThemeMode -ieq 'Dark') { '#2f2f2f' } else { '#FFFFFF' }
    $inputBgBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($inputBgHex))
    try { if ($window)             { $window.Background = $surfaceBrush } } catch {}
    try { if ($window)             { $window.Foreground = $textBrush } } catch {}
    try { if ($rootUiGrid)         { $rootUiGrid.Background = $surfaceBrush } } catch {}
    try {
      if ($script:AppTitleBar) {
        $tbBg = Resolve-WpfBrush -Value $window.Resources['UiTitleBarBrush'] -Fallback $surfaceBrush
        $script:AppTitleBar.Background = $tbBg
        $script:AppTitleBar.BorderBrush = [System.Windows.Media.Brushes]::Transparent
      }
    } catch {}
    try {
