        try { if ($script:AppCloseButton) { $script:AppCloseButton.Foreground = $tbFg } } catch {}
      }
    } catch {}
    try { if ($topUiPanel)         { $topUiPanel.Background = $surfaceBrush; $topUiPanel.Foreground = $textBrush } } catch {}
    try {
      $topSepBrush = Resolve-WpfBrush -Value $window.Resources['UiTopSeparatorBrush'] -Fallback $borderBrush
      foreach ($sep in @($topUiSep1,$topUiSep2,$topUiSep3,$topUiSep4,$topUiSep5,$topUiSep6,$topUiSep7)) {
        if (-not $sep) { continue }
        $sep.Background = $topSepBrush
