    } catch {}
    try { if ($rightPanelTabs)     { $rightPanelTabs.Background = $surfaceBrush; $rightPanelTabs.Foreground = $textBrush } } catch {}
    try { if ($createShortcutPanel){ $createShortcutPanel.Background = $surfaceBrush; $createShortcutPanel.BorderBrush = $borderBrush } } catch {}
    try { if ($profilesPanelBorder){ $profilesPanelBorder.Background = $panelBrush; $profilesPanelBorder.BorderBrush = $borderBrush } } catch {}
    try { if ($miscPanelBorder)    { $miscPanelBorder.Background = $surfaceBrush; $miscPanelBorder.BorderBrush = $borderBrush } } catch {}
    try { if ($miscAddonsPanelBorder) { $miscAddonsPanelBorder.Background = $panelBrush; $miscAddonsPanelBorder.BorderBrush = $addonsPanelBorderBrush } } catch {}
    try { if ($createIconTabs)     { $createIconTabs.Background = $surfaceBrush } } catch {}
    try { if ($createSystemIconCategoryPopupBorder) { $createSystemIconCategoryPopupBorder.Background = $panelBrush; $createSystemIconCategoryPopupBorder.BorderBrush = $borderBrush; $createSystemIconCategoryPopupBorder.Opacity = 1.0 } } catch {}
    try { Apply-CreateSystemIconsTopRuleTheme } catch {}
    try { if ($createSystemIconListBox) { $createSystemIconListBox.Background = $panelBrush } } catch {}
    try { if ($createCharMapListBox)    { $createCharMapListBox.Background = $panelBrush } } catch {}
    try { if ($tree)               { $tree.Background = $panelBrush; $tree.Foreground = $textBrush } } catch {}
    try { if ($searchCaptionText)  { $searchCaptionText.Foreground = $textBrush } } catch {}
    try { if ($viewCaptionText)    { $viewCaptionText.Foreground = $textBrush } } catch {}
    try { if ($miscAddonsSearchLabel) { $miscAddonsSearchLabel.Foreground = $textBrush } } catch {}
    try {
      if ($miscAddonsSearchBox) {
        $miscAddonsSearchBox.Foreground = $textBrush
        $miscAddonsSearchBox.Background = $inputBgBrush
        $miscAddonsSearchBox.BorderBrush = $borderBrush
      }
    } catch {}
    try { Apply-SystemIconNavButtonTheme } catch {}
    try { Apply-RightPanelActionButtonTheme } catch {}
    $uiPanelScrollRepeatButtonStyle = $null
    $uiPanelScrollThumbStyle = $null
    $uiPanelScrollRepeatButtonTemplate = $null
    $uiPanelScrollThumbTemplate = $null
    try {
      $rbTplXaml = @"
<ControlTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
                 xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
                 TargetType="{x:Type RepeatButton}">
  <Grid SnapsToDevicePixels="True">
    <Border Background="{TemplateBinding Background}"
            BorderBrush="{TemplateBinding BorderBrush}"
            BorderThickness="{TemplateBinding BorderThickness}"/>
    <ContentPresenter HorizontalAlignment="Center"
                      VerticalAlignment="Center"
                      RecognizesAccessKey="True"/>
  </Grid>
</ControlTemplate>
"@
      $uiPanelScrollRepeatButtonTemplate = [System.Windows.Markup.XamlReader]::Parse($rbTplXaml)
    } catch {}
    try {
      $thTplXaml = @"
<ControlTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
                 xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
                 TargetType="{x:Type Thumb}">
  <Border Background="{TemplateBinding Background}"
          BorderBrush="{TemplateBinding BorderBrush}"
          BorderThickness="{TemplateBinding BorderThickness}"
          SnapsToDevicePixels="True"/>
</ControlTemplate>
"@
      $uiPanelScrollThumbTemplate = [System.Windows.Markup.XamlReader]::Parse($thTplXaml)
    } catch {}
    try {
      $uiPanelScrollRepeatButtonStyle = New-Object System.Windows.Style([System.Windows.Controls.Primitives.RepeatButton])
      [void]$uiPanelScrollRepeatButtonStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BackgroundProperty, $uiPanelScrollTrackBrush)))
      [void]$uiPanelScrollRepeatButtonStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderBrushProperty, $uiPanelScrollTrackBrush)))
      [void]$uiPanelScrollRepeatButtonStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderThicknessProperty, (New-Object System.Windows.Thickness 0))))
      [void]$uiPanelScrollRepeatButtonStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::ForegroundProperty, $uiPanelScrollThumbBrush)))
      [void]$uiPanelScrollRepeatButtonStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.FrameworkElement]::FocusVisualStyleProperty, $null)))
      [void]$uiPanelScrollRepeatButtonStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::OverridesDefaultStyleProperty, $true)))
      if ($uiPanelScrollRepeatButtonTemplate) {
        [void]$uiPanelScrollRepeatButtonStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::TemplateProperty, $uiPanelScrollRepeatButtonTemplate)))
      }
      $rbTrHover = New-Object System.Windows.Trigger
      $rbTrHover.Property = [System.Windows.Controls.Control]::IsMouseOverProperty
      $rbTrHover.Value = $true
      [void]$rbTrHover.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BackgroundProperty, $uiPanelScrollTrackBrush)))
      [void]$rbTrHover.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderBrushProperty, $uiPanelScrollTrackBrush)))
      [void]$uiPanelScrollRepeatButtonStyle.Triggers.Add($rbTrHover)
      $rbTrPressed = New-Object System.Windows.Trigger
      $rbTrPressed.Property = [System.Windows.Controls.Primitives.ButtonBase]::IsPressedProperty
      $rbTrPressed.Value = $true
      [void]$rbTrPressed.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BackgroundProperty, $uiPanelScrollTrackBrush)))
      [void]$rbTrPressed.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderBrushProperty, $uiPanelScrollTrackBrush)))
      [void]$uiPanelScrollRepeatButtonStyle.Triggers.Add($rbTrPressed)
    } catch {}
    try {
      $uiPanelScrollThumbStyle = New-Object System.Windows.Style([System.Windows.Controls.Primitives.Thumb])
      [void]$uiPanelScrollThumbStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BackgroundProperty, $uiPanelScrollThumbBrush)))
      [void]$uiPanelScrollThumbStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderBrushProperty, $uiPanelScrollThumbBrush)))
      [void]$uiPanelScrollThumbStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderThicknessProperty, (New-Object System.Windows.Thickness 0))))
      [void]$uiPanelScrollThumbStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.FrameworkElement]::FocusVisualStyleProperty, $null)))
      [void]$uiPanelScrollThumbStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::OverridesDefaultStyleProperty, $true)))
      if ($uiPanelScrollThumbTemplate) {
        [void]$uiPanelScrollThumbStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::TemplateProperty, $uiPanelScrollThumbTemplate)))
      }
      $thTrHover = New-Object System.Windows.Trigger
      $thTrHover.Property = [System.Windows.Controls.Control]::IsMouseOverProperty
      $thTrHover.Value = $true
      [void]$thTrHover.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BackgroundProperty, $uiPanelScrollThumbBrush)))
      [void]$thTrHover.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderBrushProperty, $uiPanelScrollThumbBrush)))
      [void]$uiPanelScrollThumbStyle.Triggers.Add($thTrHover)
      $thTrDrag = New-Object System.Windows.Trigger
      $thTrDrag.Property = [System.Windows.Controls.Primitives.Thumb]::IsDraggingProperty
      $thTrDrag.Value = $true
      [void]$thTrDrag.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BackgroundProperty, $uiPanelScrollThumbBrush)))
      [void]$thTrDrag.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderBrushProperty, $uiPanelScrollThumbBrush)))
      [void]$uiPanelScrollThumbStyle.Triggers.Add($thTrDrag)
    } catch {}
    function Apply-UiPanelScrollBarThemeToSubtree {
      param([Parameter(Mandatory=$false)][System.Windows.DependencyObject]$Root)
      try {
        if (-not $Root) { return }
        $isDarkMode = $false
        try { $isDarkMode = ([string]$script:UiThemeMode -ieq 'Dark') } catch { $isDarkMode = $false }
        $applyScrollBarParts = {
          param(
            [Parameter(Mandatory=$false)][System.Windows.Controls.Primitives.ScrollBar]$SB,
            [Parameter(Mandatory=$true)][bool]$DarkMode
          )
          try {
            if (-not $SB) { return }
            try { if ($uiPanelScrollRepeatButtonStyle) { $SB.Resources[[System.Windows.Controls.Primitives.RepeatButton]] = $uiPanelScrollRepeatButtonStyle } } catch {}
            try { if ($uiPanelScrollThumbStyle) { $SB.Resources[[System.Windows.Controls.Primitives.Thumb]] = $uiPanelScrollThumbStyle } } catch {}
            try { $SB.ApplyTemplate() | Out-Null } catch {}
            $vstack = New-Object 'System.Collections.Generic.Stack[System.Windows.DependencyObject]'
            $vstack.Push($SB)
            while ($vstack.Count -gt 0) {
              $vnode = $vstack.Pop()
              try {
                if ($vnode -is [System.Windows.Controls.Primitives.RepeatButton]) {
                  $cmd = $null
                  try { $cmd = $vnode.Command } catch { $cmd = $null }
                  $isLineUp = $false
                  $isLineDown = $false
                  try { $isLineUp = [object]::ReferenceEquals($cmd, [System.Windows.Controls.Primitives.ScrollBar]::LineUpCommand) } catch {}
                  try { $isLineDown = [object]::ReferenceEquals($cmd, [System.Windows.Controls.Primitives.ScrollBar]::LineDownCommand) } catch {}
                  try {
                    if ($uiPanelScrollRepeatButtonStyle) { $vnode.Style = $uiPanelScrollRepeatButtonStyle }
                    if ($uiPanelScrollRepeatButtonTemplate) {
                      $vnode.Template = $uiPanelScrollRepeatButtonTemplate
                      $vnode.OverridesDefaultStyle = $true
                    }
                    $vnode.ApplyTemplate() | Out-Null
                  } catch {}
                  $vnode.Background = $uiPanelScrollTrackBrush
                  $vnode.BorderBrush = $uiPanelScrollTrackBrush
                  $vnode.Foreground = $uiPanelScrollThumbBrush
                  try { $vnode.Content = $null } catch {}
                  try {
                    $purge = New-Object 'System.Collections.Generic.Stack[System.Windows.DependencyObject]'
                    $purge.Push($vnode)
                    while ($purge.Count -gt 0) {
                      $pn = $purge.Pop()
                      try {
                        if ($pn -is [System.Windows.Shapes.Shape]) {
                          try { $pn.Visibility = [System.Windows.Visibility]::Collapsed } catch {}
                        } elseif ($pn -is [System.Windows.Controls.TextBlock]) {
                          try { $pn.Visibility = [System.Windows.Visibility]::Collapsed } catch {}
                        }
                      } catch {}
                      $pc = 0
                      try { $pc = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($pn) } catch { $pc = 0 }
                      for ($pi = 0; $pi -lt $pc; $pi++) {
                        try { $purge.Push([System.Windows.Media.VisualTreeHelper]::GetChild($pn, $pi)) } catch {}
                      }
                    }
                  } catch {}
                  if ($isLineUp -or $isLineDown) {
                    try {
                      $glyphPath = New-Object System.Windows.Shapes.Path
                      $glyphPath.StrokeThickness = 1.5
                      $glyphPath.StrokeStartLineCap = [System.Windows.Media.PenLineCap]::Round
                      $glyphPath.StrokeEndLineCap = [System.Windows.Media.PenLineCap]::Round
                      $glyphPath.StrokeLineJoin = [System.Windows.Media.PenLineJoin]::Round
                      $glyphPath.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
                      $glyphPath.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
                      $glyphPath.Width = 8
                      $glyphPath.Height = 5
                      if ($isLineUp) {
                        $glyphPath.Data = [System.Windows.Media.Geometry]::Parse("M 0 4 L 4 0 L 8 4")
                      } else {
                        $glyphPath.Data = [System.Windows.Media.Geometry]::Parse("M 0 0 L 4 4 L 8 0")
                      }
                      if ($DarkMode) {
                        $glyphPath.Stroke = $uiPanelScrollThumbBrush
                      } else {
                        $glyphPath.Stroke = (New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString('#6F6F6F')))
                      }
                      $vnode.HorizontalContentAlignment = [System.Windows.HorizontalAlignment]::Center
                      $vnode.VerticalContentAlignment = [System.Windows.VerticalAlignment]::Center
                      $vnode.Content = $glyphPath
                    } catch {}
                  }
                } elseif ($vnode -is [System.Windows.Controls.Primitives.Thumb]) {
                  try { if ($uiPanelScrollThumbStyle) { $vnode.Style = $uiPanelScrollThumbStyle } } catch {}
                  $vnode.Background = $uiPanelScrollThumbBrush
                  $vnode.BorderBrush = $uiPanelScrollThumbBrush
                  try {
                    $thumbChildren = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($vnode)
                    for ($ti = 0; $ti -lt $thumbChildren; $ti++) {
                      $tch = $null
                      try { $tch = [System.Windows.Media.VisualTreeHelper]::GetChild($vnode, $ti) } catch { $tch = $null }
                      if ($tch -is [System.Windows.Controls.Border]) {
                        $tch.Background = $uiPanelScrollThumbBrush
                        $tch.BorderBrush = $uiPanelScrollThumbBrush
                      }
                    }
                  } catch {}
                }
              } catch {}
              $vcc = 0
              try { $vcc = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($vnode) } catch { $vcc = 0 }
              for ($vi = 0; $vi -lt $vcc; $vi++) {
                try { $vstack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($vnode, $vi)) } catch {}
              }
            }
          } catch {}
        }
        $stack = New-Object 'System.Collections.Generic.Stack[System.Windows.DependencyObject]'
        $stack.Push($Root)
        while ($stack.Count -gt 0) {
          $node = $stack.Pop()
          try {
            if ($node -is [System.Windows.Controls.Primitives.ScrollBar]) {
              $node.Background = $uiPanelScrollTrackBrush
              $node.Foreground = $uiPanelScrollThumbBrush
              $node.BorderBrush = $uiPanelScrollTrackBrush
              try { $node.ApplyTemplate() | Out-Null } catch {}
              try { & $applyScrollBarParts -SB $node -DarkMode:$isDarkMode } catch {}
              try {
                $tpl = $node.Template
                if ($tpl) {
                  $partTrack = $tpl.FindName('PART_Track', $node)
                  if ($partTrack -is [System.Windows.Controls.Primitives.Track]) {
                    try {
                      if ($partTrack.Thumb -is [System.Windows.Controls.Primitives.Thumb]) {
                        $partTrack.Thumb.Background = $uiPanelScrollThumbBrush
                        $partTrack.Thumb.BorderBrush = $uiPanelScrollThumbBrush
                      }
                    } catch {}
                    try {
                      foreach ($rb in @($partTrack.DecreaseRepeatButton, $partTrack.IncreaseRepeatButton)) {
                        if (-not $rb) { continue }
                        $rb.Background = $uiPanelScrollTrackBrush
                        $rb.BorderBrush = $uiPanelScrollTrackBrush
                      }
                    } catch {}
                  }
                }
              } catch {}
            } elseif ($node -is [System.Windows.Controls.Primitives.Thumb]) {
              $node.Background = $uiPanelScrollThumbBrush
              $node.BorderBrush = $uiPanelScrollThumbBrush
            }
          } catch {}
          $cc = 0
          try { $cc = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($node) } catch { $cc = 0 }
          for ($i = 0; $i -lt $cc; $i++) {
            try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($node, $i)) } catch {}
          }
        }
      } catch {}
    }
    try {
      foreach ($combo in @($sortModeBox, $createCharMapFontBox, $createCharMapCharacterSetBox, $createCharMapGroupByBox)) {
        if (-not $combo) { continue }
        $effectiveBgBrush = $sortBgBrush
        $effectivePopupBrush = $sortPopupBrush
        $effectiveHoverBrush = $sortHoverBrush
        try {
          $comboStyle = $null
          if ($combo -eq $createCharMapFontBox -or $combo -eq $sortModeBox) {
            try { $comboStyle = $window.Resources['CharMapFontStaticComboStyle'] } catch {}
          } else {
            try {
              if ($topUiPanel -and $topUiPanel.Resources -and $topUiPanel.Resources['TopUiSortModeComboStyle']) {
                $comboStyle = $topUiPanel.Resources['TopUiSortModeComboStyle']
              }
            } catch {}
            if (-not $comboStyle) {
              try { if ($sortModeBox -and $sortModeBox.Style) { $comboStyle = $sortModeBox.Style } } catch {}
            }
          }
          if ($comboStyle) {
            $combo.Style = $comboStyle
          }
        } catch {}
        $combo.Background = $effectiveBgBrush
        $combo.BorderBrush = $borderBrush
        $combo.Foreground = $textBrush
        $combo.Resources[[System.Windows.SystemColors]::WindowBrushKey] = ([System.Management.Automation.PSObject]::AsPSObject($effectivePopupBrush)).BaseObject
        $combo.Resources[[System.Windows.SystemColors]::ControlBrushKey] = ([System.Management.Automation.PSObject]::AsPSObject($effectiveBgBrush)).BaseObject
        $combo.Resources[[System.Windows.SystemColors]::WindowTextBrushKey] = ([System.Management.Automation.PSObject]::AsPSObject($textBrush)).BaseObject
