    function Apply-UiTextToSubtree {
      param([Parameter(Mandatory=$false)][System.Windows.DependencyObject]$Root)
      try {
        if (-not $Root) { return }
        $stack = New-Object 'System.Collections.Generic.Stack[System.Windows.DependencyObject]'
        $stack.Push($Root)
        while ($stack.Count -gt 0) {
          $node = $stack.Pop()
          try {
            if ($node -is [System.Windows.Controls.TextBlock]) {
              $node.Foreground = $textBrush
            } elseif ($node -is [System.Windows.Controls.CheckBox]) {
              $node.Foreground = $uiCbGlyphBrush
              $node.Background = $uiCbFillBrush
              $node.BorderBrush = $uiCbBorderBrush
              try { $node.ApplyTemplate() | Out-Null } catch {}
              try {
                $tpl = $node.Template
                if ($tpl) {
                  $box = $tpl.FindName('UiCbBox', $node)
                  if ($box -is [System.Windows.Controls.Border]) {
                    $box.Background = $uiCbFillBrush
                    $box.BorderBrush = $uiCbBorderBrush
                  }
                  $mark = $tpl.FindName('UiCbMark', $node)
                  if ($mark -is [System.Windows.Shapes.Path]) {
                    $mark.Stroke = $uiCbGlyphBrush
                  }
                  $selBox = $tpl.FindName('SelectBox', $node)
                  if ($selBox -is [System.Windows.Controls.Border]) {
                    $selBox.Background = $selCbFillBrush
                    $selBox.BorderBrush = $selCbBorderBrush
                  }
                  $selMark = $tpl.FindName('SelectCheck', $node)
                  if ($selMark -is [System.Windows.Shapes.Path]) {
                    $selMark.Stroke = $selCbGlyphBrush
                  }
                }
              } catch {}
            } elseif ($node -is [System.Windows.Controls.Control]) {
              $node.Foreground = $textBrush
            }
          } catch {}
          $cc = 0
          try { $cc = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($node) } catch { $cc = 0 }
          for ($i = 0; $i -lt $cc; $i++) {
            try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($node, $i)) } catch {}
          }
        }
      } catch {}
    }
    try { Apply-UiTextToSubtree -Root $topUiPanel } catch {}
    try { Apply-UiTextToSubtree -Root $rightPanelTabs } catch {}
    try { Apply-UiPanelScrollBarThemeToSubtree -Root $topUiPanel } catch {}
    try { Apply-UiPanelScrollBarThemeToSubtree -Root $rightPanelTabs } catch {}
    function Apply-UiCheckBoxThemeToControl {
      param(
        [Parameter(Mandatory=$false)][object]$CheckBoxControl
      )
      try {
        $cb = $CheckBoxControl -as [System.Windows.Controls.CheckBox]
        if (-not $cb) { return }
        $tagText = ''
        try { $tagText = [string]$cb.Tag } catch { $tagText = '' }
        if ($tagText -eq 'SelectCascade') { return }
        try {
          if ($cb.Name -in @('ShowAlphaSeparatorsBox','ShowNestedFoldersBox','ShowStartupFolderBox','ShowEmptyFoldersBox','ExpandAllFoldersBox','SelectAllBox')) {
            if ($window.Resources['TopUiCheckBoxStyle']) { $cb.Style = $window.Resources['TopUiCheckBoxStyle'] }
          } elseif ($window.Resources['UiCheckBoxStyle']) {
            $cb.Style = $window.Resources['UiCheckBoxStyle']
          }
        } catch {}
        $cb.Foreground = $uiCbGlyphBrush
        $cb.Background = $uiCbFillBrush
        $cb.BorderBrush = $uiCbBorderBrush
        try { $cb.ApplyTemplate() | Out-Null } catch {}
        try {
          $tpl = $cb.Template
          if ($tpl) {
            $box = $tpl.FindName('UiCbBox', $cb)
            if ($box -is [System.Windows.Controls.Border]) {
              $box.Background = $uiCbFillBrush
              $box.BorderBrush = $uiCbBorderBrush
            }
            $mark = $tpl.FindName('UiCbMark', $cb)
            if ($mark -is [System.Windows.Shapes.Path]) {
              $mark.Stroke = $uiCbGlyphBrush
            }
          }
        } catch {}
      } catch {}
    }
    function Apply-UiCheckBoxThemeToSubtree {
      param([Parameter(Mandatory=$false)][System.Windows.DependencyObject]$Root)
      try {
        if (-not $Root) { return }
        $stack = New-Object 'System.Collections.Generic.Stack[System.Windows.DependencyObject]'
        $stack.Push($Root)
        while ($stack.Count -gt 0) {
          $node = $stack.Pop()
          try {
            if ($node -is [System.Windows.Controls.CheckBox]) {
              Apply-UiCheckBoxThemeToControl -CheckBoxControl $node
            }
          } catch {}
          $cc = 0
          try { $cc = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($node) } catch { $cc = 0 }
          for ($i = 0; $i -lt $cc; $i++) {
            try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($node, $i)) } catch {}
          }
        }
      } catch {}
    }
    try {
      foreach ($cb in @(
        $showAlphaSeparatorsBox,$showNestedFoldersBox,$showStartupFolderBox,$showEmptyFoldersBox,$expandAllFoldersBox,$selectAll,
        $miscBlurGridWallpaperBox,$miscMatchScreenWallpaperBox,$miscDesktopPassthroughBox,$miscDisableDuplicateFlaggingBox
      )) {
        if (-not $cb) { continue }
        Apply-UiCheckBoxThemeToControl -CheckBoxControl $cb
      }
    } catch {}
    try { Apply-UiCheckBoxThemeToSubtree -Root $topUiPanel } catch {}
    try { Apply-UiCheckBoxThemeToSubtree -Root $rightPanelTabs } catch {}
    try { Apply-ExplicitUiPanelTabColors -Mode $script:UiThemeMode } catch {}
    # Force column header bar + header text update on theme toggle.4.73105
    $hdrBg = $surfaceBrush
    $hdrFg = $textBrush
    $hdrSep = $null
    try { $hdrSep = Resolve-WpfBrush -Value $window.Resources['UiSeparatorBrush'] -Fallback $borderBrush } catch { $hdrSep = $borderBrush }
    try { Apply-GridHeaderTheme -BackgroundBrush $hdrBg -ForegroundBrush $hdrFg -BorderBrush $hdrSep } catch {}
    try { Apply-GridHeaderSeparatorTheme } catch {}
    try {
      if ($grid -and $grid.Dispatcher) {
        $null = $grid.Dispatcher.BeginInvoke(
          [Action]{
            try {
              $b = Resolve-WpfBrush -Value $window.Resources['UiSurfaceBrush'] -Fallback $hdrBg
              $f = Resolve-WpfBrush -Value $window.Resources['GridHeaderTextBrush'] -Fallback $hdrFg
              $s = Resolve-WpfBrush -Value $window.Resources['UiSeparatorBrush'] -Fallback $hdrSep
              Apply-GridHeaderTheme -BackgroundBrush $b -ForegroundBrush $f -BorderBrush $s
              Apply-GridHeaderSeparatorTheme
            } catch {}
          },
          [System.Windows.Threading.DispatcherPriority]::Render
        )
      }
    } catch {}
    try { Set-WindowTitleBarTheme -Window $window -Mode $script:UiThemeMode } catch {}
    try { Apply-TopUiButtonHoverTheme } catch {}
    try { Apply-CustomTitleBarForeground -Mode $script:UiThemeMode } catch {}
    try { Update-CustomTitleBarMaxGlyph } catch {}
    try { Sync-CustomTitleBarText } catch {}
    try { Set-UiThemeToggleIcon -Mode $script:UiThemeMode } catch {}
    try { Apply-MiscAddonTilesTheme } catch {}
    try { Apply-UiInteriorPanelShadows -Mode $script:UiThemeMode } catch {}
  } catch {}
}

function Apply-UiInteriorPanelShadows {
  param(
    [Parameter(Mandatory=$false)][ValidateSet('Light','Dark')][string]$Mode = $script:UiThemeMode
  )
  try {
    $isDark = ([string]$Mode -ieq 'Dark')
    $shadowColor = [System.Windows.Media.Color]::FromArgb(255,0,0,0)
    $rightOpacity = if ($isDark) { 0.32 } else { 0.20 }
    if ($topUiPanel) {
      try { $topUiPanel.Effect = $null } catch {}
      try { [System.Windows.Controls.Panel]::SetZIndex($topUiPanel, 40) } catch {}
    }
    if ($rightPanelTabs) {
      $rightShadow = New-Object System.Windows.Media.Effects.DropShadowEffect
      $rightShadow.Color = $shadowColor
      $rightShadow.BlurRadius = 16
      $rightShadow.ShadowDepth = 3
      $rightShadow.Direction = 180
      $rightShadow.Opacity = $rightOpacity
      $rightShadow.RenderingBias = [System.Windows.Media.Effects.RenderingBias]::Performance
      try { $rightPanelTabs.Effect = $rightShadow } catch {}
      try { [System.Windows.Controls.Panel]::SetZIndex($rightPanelTabs, 30) } catch {}
    }
  } catch {}
}

function Queue-UiThemeReapplyAfterTabSwitch {
  try {
    if (-not $window -or -not $window.Dispatcher) { return }
    try { if (-not $window.IsVisible) { return } } catch {}
    if ($script:UiThemeDeferredApplyPending) { return }
    $script:UiThemeDeferredApplyPending = $true
    $null = $window.Dispatcher.BeginInvoke(
      [Action]{
        try {
          $script:UiThemeDeferredApplyPending = $false
          Set-UiThemeMode -Mode ([string]$script:UiThemeMode)
        } catch {
          try { $script:UiThemeDeferredApplyPending = $false } catch {}
        }
      },
      [System.Windows.Threading.DispatcherPriority]::Render
    )
  } catch {
    try { $script:UiThemeDeferredApplyPending = $false } catch {}
  }
}

function Apply-UiThemeToRightPanelSelectedTab {
  try {
    if (-not $rightPanelTabs) { return }
    $ti = $null
    try { $ti = $rightPanelTabs.SelectedItem -as [System.Windows.Controls.TabItem] } catch { $ti = $null }
    if (-not $ti) { return }
    $textBrush = $null
    $panelBrush = $null
    $borderBrush = $null
    $uiCbFillBrush = $null
    $uiCbGlyphBrush = $null
    $uiCbBorderBrush = $null
    $uiPanelScrollTrackBrush = $null
    $uiPanelScrollThumbBrush = $null
    $inputBrush = $null
    try { $textBrush = Resolve-WpfBrush -Value $window.Resources['UiTextBrush'] -Fallback $null } catch {}
    try { $panelBrush = Resolve-WpfBrush -Value $window.Resources['UiPanelBrush'] -Fallback $null } catch {}
    try { $borderBrush = Resolve-WpfBrush -Value $window.Resources['UiBorderBrush'] -Fallback $null } catch {}
    try { $uiCbFillBrush = Resolve-WpfBrush -Value $window.Resources['UiCheckBoxFillBrush'] -Fallback ([System.Windows.Media.Brushes]::Transparent) } catch { $uiCbFillBrush = [System.Windows.Media.Brushes]::Transparent }
    try { $uiCbGlyphBrush = Resolve-WpfBrush -Value $window.Resources['UiCheckBoxGlyphBrush'] -Fallback $textBrush } catch { $uiCbGlyphBrush = $textBrush }
    try { $uiCbBorderBrush = Resolve-WpfBrush -Value $window.Resources['UiCheckBoxBorderBrush'] -Fallback $borderBrush } catch { $uiCbBorderBrush = $borderBrush }
    try { $uiPanelScrollTrackBrush = Resolve-WpfBrush -Value $window.Resources['UiPanelScrollTrackBrush'] -Fallback $panelBrush } catch { $uiPanelScrollTrackBrush = $panelBrush }
    try { $uiPanelScrollThumbBrush = Resolve-WpfBrush -Value $window.Resources['UiPanelScrollThumbBrush'] -Fallback $borderBrush } catch { $uiPanelScrollThumbBrush = $borderBrush }
    try {
      $inputHex = if (([string]$script:UiThemeMode) -ieq 'Dark') { '#2f2f2f' } else { '#FFFFFF' }
      $inputBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($inputHex))
    } catch {}
    if (-not $textBrush) { return }
    $root = $null
    try { $root = $ti.Content -as [System.Windows.DependencyObject] } catch { $root = $null }
    if (-not $root) { return }
    $stack = New-Object 'System.Collections.Generic.Stack[System.Windows.DependencyObject]'
    $stack.Push($root)
    while ($stack.Count -gt 0) {
      $node = $stack.Pop()
      try {
        if ($node -is [System.Windows.Controls.TextBlock]) {
          $node.Foreground = $textBrush
        } elseif ($node -is [System.Windows.Controls.Label]) {
          $node.Foreground = $textBrush
        } elseif ($node -is [System.Windows.Controls.TextBox]) {
          $node.Foreground = $textBrush
          if ($inputBrush) { $node.Background = $inputBrush }
          if ($borderBrush) { $node.BorderBrush = $borderBrush }
        } elseif ($node -is [System.Windows.Controls.ListBox]) {
          $node.Foreground = $textBrush
          if ($panelBrush) { $node.Background = $panelBrush }
        } elseif ($node -is [System.Windows.Controls.Primitives.ScrollBar]) {
          if ($uiPanelScrollTrackBrush) { $node.Background = $uiPanelScrollTrackBrush; $node.BorderBrush = $uiPanelScrollTrackBrush }
          if ($uiPanelScrollThumbBrush) { $node.Foreground = $uiPanelScrollThumbBrush }
          try { $node.ApplyTemplate() | Out-Null } catch {}
        } elseif ($node -is [System.Windows.Controls.Primitives.Thumb]) {
          if ($uiPanelScrollThumbBrush) { $node.Background = $uiPanelScrollThumbBrush; $node.BorderBrush = $uiPanelScrollThumbBrush }
        } elseif ($node -is [System.Windows.Controls.CheckBox]) {
          if ($uiCbGlyphBrush) { $node.Foreground = $uiCbGlyphBrush }
          if ($uiCbFillBrush) { $node.Background = $uiCbFillBrush }
          if ($uiCbBorderBrush) { $node.BorderBrush = $uiCbBorderBrush }
          try { $node.ApplyTemplate() | Out-Null } catch {}
          try {
            $tpl = $node.Template
            if ($tpl) {
              $box = $tpl.FindName('UiCbBox', $node)
              if ($box -is [System.Windows.Controls.Border]) {
                if ($uiCbFillBrush) { $box.Background = $uiCbFillBrush }
                if ($uiCbBorderBrush) { $box.BorderBrush = $uiCbBorderBrush }
              }
              $mark = $tpl.FindName('UiCbMark', $node)
              if ($mark -is [System.Windows.Shapes.Path]) {
                if ($uiCbGlyphBrush) { $mark.Stroke = $uiCbGlyphBrush }
              }
            }
          } catch {}
        } elseif ($node -is [System.Windows.Controls.Control]) {
          # Default control text fallback for controls that do not have an explicit brush.
          $node.Foreground = $textBrush
        }
      } catch {}
      $cc = 0
      try { $cc = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($node) } catch { $cc = 0 }
      for ($i = 0; $i -lt $cc; $i++) {
        try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($node, $i)) } catch {}
      }
    }
  } catch {}
}

function Get-DefaultFolderIconLocationSpec {
  # Returns static icon location for folder visuals:
  # - Build <= 1809: dmdskres.dll,11
  # - Build  > 1809: mmcndmgr.dll,0
  try {
    $isNewBuild = $false
    try { $isNewBuild = [bool](Get-IsWindowsBuildAbove1809Runtime) } catch { $isNewBuild = $false }
    if ($isNewBuild) {
      $p = Join-Path $env:WINDIR "System32\mmcndmgr.dll"
      return [pscustomobject]@{
        IconPath  = [string]$p
        IconIndex = 0
      }
    } else {
      $p = Join-Path $env:WINDIR "System32\dmdskres.dll"
      return [pscustomobject]@{
        IconPath  = [string]$p
        IconIndex = 11
      }
    }
  } catch {
    return [pscustomobject]@{
      IconPath  = ''
      IconIndex = 0
    }
  }
}

