function Set-CreateNameBoxTextSafe {
  param([string]$Text)
  try {
    if (-not $createNameBox) { return }
    $script:RenameLiveSyncSuspend = $true
    try { $createNameBox.Text = [string]$Text } finally { $script:RenameLiveSyncSuspend = $false }
  } catch {}
}

function Get-CharMapTextDelta {
  param(
    [string]$Previous,
    [string]$Current
  )
  if ([string]::IsNullOrWhiteSpace([string]$Current)) { return '' }
  $p = [string]$Previous
  $c = [string]$Current
  if ([string]::IsNullOrEmpty($p)) { return $c }
  if ($c.StartsWith($p, [System.StringComparison]::Ordinal)) {
    try { return $c.Substring($p.Length) } catch { return '' }
  }
  if ($p.StartsWith($c, [System.StringComparison]::Ordinal)) { return '' }
  return $c
}

function Test-IsLikelyCharMapSelectionText {
  param([string]$Text)
  $t = [string]$Text
  if ([string]::IsNullOrWhiteSpace($t)) { return $false }
  $t = $t.Trim()
  if ($t.Length -gt 256) { return $false }
  if ($t -match '^U\+[0-9A-Fa-f]{4,}') { return $false }
  if ($t -match '^[A-Za-z ]{3,}\s*:') { return $false }
  if ($t -match '^[A-Za-z0-9 _\-]{6,}$') { return $false }
  return $true
}

function Insert-CreateNameBoxText {
  param([Parameter(Mandatory=$true)][string]$Text)
  try {
    if (-not $createNameBox) { return $false }
    if (-not $createNameBox.IsEnabled) { return $false }
    if ([string]::IsNullOrEmpty([string]$Text)) { return $false }
    $txt = ''
    try { $txt = [string]$createNameBox.Text } catch { $txt = '' }
    $start = 0
    $len = 0
    try { $start = [int]$createNameBox.SelectionStart } catch { $start = 0 }
    try { $len = [int]$createNameBox.SelectionLength } catch { $len = 0 }
    if ($start -lt 0) { $start = 0 }
    if ($start -gt $txt.Length) { $start = $txt.Length }
    if ($len -lt 0) { $len = 0 }
    if (($start + $len) -gt $txt.Length) { $len = $txt.Length - $start }
    $left = ''
    $right = ''
    try { $left = $txt.Substring(0, $start) } catch { $left = $txt }
    try { $right = $txt.Substring($start + $len) } catch { $right = '' }
    $createNameBox.Text = ($left + [string]$Text + $right)
    $newPos = $start + ([string]$Text).Length
    try { $createNameBox.SelectionStart = $newPos } catch {}
    try { $createNameBox.SelectionLength = 0 } catch {}
    return $true
  } catch {
    return $false
  }
}

function Get-CreateCharMapCodePointRanges {
  return @(
    @(0x0021, 0x007E),
    @(0x00A1, 0x00FF),
    @(0x0100, 0x017F),
    @(0x0180, 0x024F),
    @(0x02B0, 0x02FF),
    @(0x2000, 0x206F),
    @(0x20A0, 0x20CF),
    @(0x2100, 0x214F),
    @(0x2190, 0x21FF),
    @(0x2200, 0x22FF),
    @(0x2300, 0x23FF),
    @(0x2460, 0x24FF),
    @(0x2500, 0x257F),
    @(0x2580, 0x259F),
    @(0x25A0, 0x25FF),
    @(0x2600, 0x26FF),
    @(0x2700, 0x27BF),
    @(0x2B00, 0x2BFF),
    @(0x1F300, 0x1F5FF),
    @(0x1F600, 0x1F64F),
    @(0x1F680, 0x1F6FF),
    @(0x1F900, 0x1F9FF)
  )
}

function Get-CreateCharMapGlyphTypeface {
  param([string]$FontName)
  try {
    if ([string]::IsNullOrWhiteSpace([string]$FontName)) { return $null }
    $ff = New-Object System.Windows.Media.FontFamily([string]$FontName)
    foreach ($tf in @($ff.GetTypefaces())) {
      $gt = $null
      if ($tf.TryGetGlyphTypeface([ref]$gt) -and $gt) {
        return $gt
      }
    }
    return $null
  } catch {
    return $null
  }
}

function Get-CreateCharMapItemsForFont {
  param([string]$FontName)
  $name = [string]$FontName
  if ([string]::IsNullOrWhiteSpace($name)) { $name = 'Segoe UI Symbol' }
  if (-not ($script:CreateCharMapCharCache -is [hashtable])) { $script:CreateCharMapCharCache = @{} }
  if ($script:CreateCharMapCharCache.ContainsKey($name)) {
    try { return @($script:CreateCharMapCharCache[$name]) } catch {}
  }
  $items = New-Object System.Collections.Generic.List[object]
  $gt = Get-CreateCharMapGlyphTypeface -FontName $name
  $glyphMap = $null
  try { if ($gt) { $glyphMap = $gt.CharacterToGlyphMap } } catch { $glyphMap = $null }
  foreach ($range in @(Get-CreateCharMapCodePointRanges)) {
    if (-not $range -or @($range).Count -lt 2) { continue }
    $from = [int]$range[0]
    $to = [int]$range[1]
    if ($to -lt $from) { continue }
    for ($cp = $from; $cp -le $to; $cp++) {
      if ($cp -gt 0x10FFFF) { continue }
      if ($glyphMap -and (-not $glyphMap.ContainsKey([int]$cp))) { continue }
      $ch = ''
      if ($cp -le 0xFFFF) {
        $c = [char]$cp
        if ([char]::IsControl($c)) { continue }
        $ch = [string]$c
      } else {
        try { $ch = [char]::ConvertFromUtf32($cp) } catch { $ch = '' }
      }
      if ([string]::IsNullOrEmpty($ch)) { continue }
      $codeHex = ('U+{0:X4}' -f $cp)
      [void]$items.Add([pscustomobject]@{
        Char       = [string]$ch
        CodePoint  = [int]$cp
        CodeHex    = [string]$codeHex
        FontFamily = [string]$name
      })
    }
  }
  $result = @($items.ToArray())
  $script:CreateCharMapCharCache[$name] = $result
  return $result
}

function Start-CreateCharMapGlyphCacheWarmup {
  try {
    if ([bool]$script:CreateCharMapCacheWarmStarted) { return }
    $script:CreateCharMapCacheWarmStarted = $true
    if (-not ($script:CreateCharMapViewCache -is [hashtable])) { $script:CreateCharMapViewCache = @{} }
    $fonts = @('Segoe UI Emoji','Segoe UI Symbol','Segoe UI')
    if ($createCharMapFontBox -and $createCharMapFontBox.SelectedItem) {
      try {
        $sel = [string]$createCharMapFontBox.SelectedItem
        if (-not [string]::IsNullOrWhiteSpace($sel)) {
          $fonts = @($sel) + @($fonts | Where-Object { $_ -ne $sel })
        }
      } catch {}
    }
    foreach ($f in @($fonts)) {
      if ([string]::IsNullOrWhiteSpace([string]$f)) { continue }
      try {
        $fn = [string]$f
        $all = @(Get-CreateCharMapItemsForFont -FontName $fn)
        $script:CreateCharMapViewCache[("{0}|" -f $fn)] = $all
      } catch {}
    }
  } catch {}
}

function Add-CreateCharMapTextToCopyBox {
  param([string]$Text)
  try {
    if ([string]::IsNullOrEmpty([string]$Text)) { return $false }
    if (-not $createCharMapCopyBox) { return $false }
    $insertToCopy = $false
    try {
      $insertToCopy = ([string]$script:CreateCharMapInsertTarget -eq 'Copy')
    } catch { $insertToCopy = $false }
    $script:CreateCharMapApplyingText = $true
    try {
      if ($insertToCopy) {
        $cur = ''
        try { $cur = [string]$createCharMapCopyBox.Text } catch { $cur = '' }
        $newVal = [string]($cur + [string]$Text)
        $createCharMapCopyBox.Text = $newVal
        try { $createCharMapCopyBox.SelectionStart = $newVal.Length } catch {}
        try { $createCharMapCopyBox.SelectionLength = 0 } catch {}
        $script:CreateCharMapLastCopyText = $newVal
        try {
          if ($window -and $window.Dispatcher) {
            [void]$window.Dispatcher.BeginInvoke([Action]{
              try {
                $script:CreateCharMapInsertTarget = 'Copy'
                [void]$createCharMapCopyBox.Focus()
                $createCharMapCopyBox.SelectionStart = $createCharMapCopyBox.Text.Length
                $createCharMapCopyBox.SelectionLength = 0
              } catch {}
            }, [System.Windows.Threading.DispatcherPriority]::Input)
          }
        } catch {}
      } else {
        # Keep this field unchanged unless the user explicitly focuses/selects it.
        try { $script:CreateCharMapLastCopyText = [string]$createCharMapCopyBox.Text } catch { $script:CreateCharMapLastCopyText = '' }
        [void](Insert-CreateNameBoxText -Text ([string]$Text))
      }
    } finally {
      $script:CreateCharMapApplyingText = $false
    }
    return $true
  } catch {
    return $false
  }
}

function Sync-CreateCharMapCopyBoxDeltaToName {
  try {
    if (-not $createCharMapCopyBox) { return }
    $insertToCopy = $false
    try { $insertToCopy = ([string]$script:CreateCharMapInsertTarget -eq 'Copy') } catch { $insertToCopy = $false }
    if ($insertToCopy) {
      try { $script:CreateCharMapLastCopyText = [string]$createCharMapCopyBox.Text } catch { $script:CreateCharMapLastCopyText = '' }
      return
    }
    $cur = ''
    try { $cur = [string]$createCharMapCopyBox.Text } catch { $cur = '' }
    $prev = ''
    try { $prev = [string]$script:CreateCharMapLastCopyText } catch { $prev = '' }
    $script:CreateCharMapLastCopyText = $cur
    if ([bool]$script:CreateCharMapApplyingText) { return }
    $delta = Get-CharMapTextDelta -Previous $prev -Current $cur
    if ([string]::IsNullOrEmpty($delta)) { return }
    [void](Insert-CreateNameBoxText -Text ([string]$delta))
  } catch {}
}

function Apply-CreateCharMapFilter {
  try {
    if (-not $createCharMapListBox) { return }
    try { Sync-CreateCharMapGlyphTheme } catch {}
    $fontName = 'Segoe UI Symbol'
    try {
      if ($createCharMapFontBox -and $createCharMapFontBox.SelectedItem) {
        $fontName = [string]$createCharMapFontBox.SelectedItem
      }
    } catch {}
    if ([string]::IsNullOrWhiteSpace($fontName)) { $fontName = 'Segoe UI Symbol' }
    $script:CreateCharMapCurrentFont = $fontName
    $query = ''
    try { if ($createCharMapSearchBox) { $query = [string]$createCharMapSearchBox.Text } } catch { $query = '' }
    $maxItems = 0
    try { $maxItems = [int]$script:CreateCharMapMaxVisibleItems } catch { $maxItems = 0 }
    if ($maxItems -lt 0) { $maxItems = 0 }
    $sigQuery = ''
    try { $sigQuery = [string]$query } catch { $sigQuery = '' }
    if (-not [string]::IsNullOrWhiteSpace($sigQuery)) { try { $sigQuery = $sigQuery.Trim() } catch {} }
    $sig = ("{0}|{1}|{2}" -f $fontName, $sigQuery, $maxItems)
    try {
      if (($script:CreateCharMapLastFilterSignature -eq $sig) -and $createCharMapListBox.ItemsSource) {
        Render-CreateCharMapRowView
        return
      }
    } catch {}
    if (-not ($script:CreateCharMapViewCache -is [hashtable])) { $script:CreateCharMapViewCache = @{} }
    $viewKey = ("{0}|{1}" -f $fontName, $sigQuery)
    $view = @()
    $hasCachedView = $false
    try { $hasCachedView = $script:CreateCharMapViewCache.ContainsKey($viewKey) } catch { $hasCachedView = $false }
    if ($hasCachedView) {
      try { $view = @($script:CreateCharMapViewCache[$viewKey]) } catch { $view = @() }
    } else {
      $all = @()
      $allKey = ("{0}|" -f $fontName)
      $hasAllCached = $false
      try { $hasAllCached = $script:CreateCharMapViewCache.ContainsKey($allKey) } catch { $hasAllCached = $false }
      if ($hasAllCached) {
        try { $all = @($script:CreateCharMapViewCache[$allKey]) } catch { $all = @() }
      } else {
        $all = @(Get-CreateCharMapItemsForFont -FontName $fontName)
        try { $script:CreateCharMapViewCache[$allKey] = $all } catch {}
      }
      $view = $all
      if (-not [string]::IsNullOrWhiteSpace($sigQuery)) {
        $q = $sigQuery
        $ql = $q.ToLowerInvariant()
        $view = @($all | Where-Object {
          $it = $_
          $m = $false
          try { if ([string]$it.Char -eq $q) { $m = $true } } catch {}
          if (-not $m) { try { if (([string]$it.CodeHex).ToLowerInvariant().Contains($ql)) { $m = $true } } catch {} }
          if (-not $m) { try { if (([string]$it.CodePoint).Contains($q)) { $m = $true } } catch {} }
          $m
        })
      }
      try { $script:CreateCharMapViewCache[$viewKey] = $view } catch {}
    }
    if (($maxItems -gt 0) -and (@($view).Count -gt $maxItems)) {
      try { $view = @($view | Select-Object -First $maxItems) } catch {}
    }
    try { $script:CreateCharMapCurrentFilteredView = @($view) } catch { $script:CreateCharMapCurrentFilteredView = @() }
    try { $script:CreateCharMapLastFilterSignature = $sig } catch {}
    try { $script:CreateCharMapLastRenderSignature = '' } catch {}
    Render-CreateCharMapRowView -Force
    if ($createCharMapCodePointText) {
      $first = $null
      try { if (@($script:CreateCharMapCurrentFilteredView).Count -gt 0) { $first = $script:CreateCharMapCurrentFilteredView[0] } } catch { $first = $null }
      if ($first) {
        try { $createCharMapCodePointText.Text = [string]$first.CodeHex } catch { $createCharMapCodePointText.Text = '' }
      } else {
        $createCharMapCodePointText.Text = ''
      }
    }
  } catch {}
}

function Ensure-CreateCharMapUi {
  try {
    if (-not $createCharMapFontBox -or -not $createCharMapListBox) { return }
    if (-not [bool]$script:CreateCharMapInitialized) {
      $lang = [System.Windows.Markup.XmlLanguage]::GetLanguage('en-us')
      $set = @{}
      $names = New-Object System.Collections.Generic.List[string]
      foreach ($fam in @([System.Windows.Media.Fonts]::SystemFontFamilies)) {
        $nm = ''
        try {
          if ($fam.FamilyNames.ContainsKey($lang)) {
            $nm = [string]$fam.FamilyNames[$lang]
          } else {
            $en = $fam.FamilyNames.GetEnumerator()
            if ($en.MoveNext()) { $nm = [string]$en.Current.Value }
          }
        } catch { $nm = '' }
        if ([string]::IsNullOrWhiteSpace($nm)) { continue }
        if ($set.ContainsKey($nm)) { continue }
        $set[$nm] = $true
        [void]$names.Add($nm)
      }
      $preferred = @('Segoe UI Emoji','Segoe UI Symbol','Segoe UI')
      $ordered = New-Object System.Collections.Generic.List[string]
      foreach ($pf in @($preferred)) {
        if ($set.ContainsKey([string]$pf)) {
          [void]$ordered.Add([string]$pf)
          $set.Remove([string]$pf)
        }
      }
      $rest = @($set.Keys | Sort-Object)
      foreach ($n in @($rest)) { [void]$ordered.Add([string]$n) }
      $createCharMapFontBox.ItemsSource = @($ordered.ToArray())
      $seed = 'Segoe UI Emoji'
      if (-not (@($ordered.ToArray()) -contains $seed)) { $seed = 'Segoe UI Symbol' }
      if (-not (@($ordered.ToArray()) -contains $seed) -and @($ordered.ToArray()).Count -gt 0) { $seed = [string]$ordered[0] }
      if (-not [string]::IsNullOrWhiteSpace($seed)) { $createCharMapFontBox.SelectedItem = $seed }
      if ($createCharMapAdvancedPanel) { $createCharMapAdvancedPanel.Visibility = 'Visible' }
      $script:CreateCharMapLastCopyText = ''
      $script:CreateCharMapLastFilterSignature = ''
      $script:CreateCharMapLastRenderSignature = ''
      $script:CreateCharMapCurrentFilteredView = @()
      $script:CreateCharMapRowViewCache = @{}
      $script:CreateCharMapInitialized = $true
    }
    try { Start-CreateCharMapGlyphCacheWarmup } catch {}
    try { Sync-CreateCharMapGlyphTheme } catch {}
    Apply-CreateCharMapFilter
  } catch {}
}

function Get-CreateCharMapColumnCount {
  try {
    $pitch = 30.0
    try { $pitch = [double]$script:CreateCharMapCellPitchPx } catch { $pitch = 30.0 }
    if ($pitch -lt 18.0) { $pitch = 18.0 }
    $w = 0.0
    try { $w = [double]$createCharMapListBox.ActualWidth } catch { $w = 0.0 }
    if ($w -lt 80.0) { return 10 }
    # Keep a small gutter for scrollbar/edge.
    $usable = [Math]::Max(1.0, ($w - 8.0))
    $cols = [int][Math]::Floor($usable / $pitch)
    if ($cols -lt 1) { $cols = 1 }
    if ($cols -gt 64) { $cols = 64 }
    return $cols
  } catch {
    return 10
  }
}

function Convert-CreateCharMapItemsToRows {
  param(
    [Parameter(Mandatory=$true)][object[]]$Items,
    [Parameter(Mandatory=$true)][int]$Columns
  )
  try {
    $cols = [int]$Columns
    if ($cols -lt 1) { $cols = 1 }
    $rows = New-Object System.Collections.Generic.List[object]
    $i = 0
    $n = @($Items).Count
    while ($i -lt $n) {
      $cells = New-Object System.Collections.Generic.List[object]
      for ($c = 0; $c -lt $cols -and $i -lt $n; $c++) {
        [void]$cells.Add($Items[$i])
        $i++
      }
      [void]$rows.Add([pscustomobject]@{
        Columns = $cols
        Cells   = @($cells.ToArray())
      })
    }
    return @($rows.ToArray())
  } catch {
    return @()
  }
}

function Render-CreateCharMapRowView {
  param([switch]$Force)
  try {
    if (-not $createCharMapListBox) { return }
    $flat = @()
    try { $flat = @($script:CreateCharMapCurrentFilteredView) } catch { $flat = @() }
    $cols = Get-CreateCharMapColumnCount
    $sig = ''
    try { $sig = [string]$script:CreateCharMapLastFilterSignature } catch { $sig = '' }
    $renderSig = ("{0}|cols={1}" -f $sig, $cols)
    if (-not $Force) {
      $hasSource = $false
      try { $hasSource = ($null -ne $createCharMapListBox.ItemsSource) } catch { $hasSource = $false }
      if ($hasSource -and ($script:CreateCharMapLastRenderSignature -eq $renderSig)) { return }
    }
    if (-not ($script:CreateCharMapRowViewCache -is [hashtable])) { $script:CreateCharMapRowViewCache = @{} }
    if (@($script:CreateCharMapRowViewCache.Keys).Count -gt 48) {
      try { $script:CreateCharMapRowViewCache = @{} } catch {}
    }
    $rows = @()
    if ($script:CreateCharMapRowViewCache.ContainsKey($renderSig)) {
      try { $rows = @($script:CreateCharMapRowViewCache[$renderSig]) } catch { $rows = @() }
    } else {
      $rows = Convert-CreateCharMapItemsToRows -Items $flat -Columns $cols
      try { $script:CreateCharMapRowViewCache[$renderSig] = $rows } catch {}
    }
    $createCharMapListBox.ItemsSource = $rows
    try { $script:CreateCharMapLastRenderSignature = $renderSig } catch {}
  } catch {}
}

function Sync-CreateCharMapGlyphTheme {
  try {
    if (-not $createCharMapListBox) { return }
    $bg = $null
    try { $bg = $createCharMapListBox.Background } catch { $bg = $null }
    try { $bg = Resolve-WpfBrush -Value $bg -Fallback $null } catch { $bg = $null }
    if (-not $bg) {
      $bgHex = '#E1E1E1'
      try { if (([string]$script:UiThemeMode) -ieq 'Dark') { $bgHex = '#202020' } } catch {}
      try { $bg = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($bgHex)) } catch { $bg = $null }
    }
    $fgHex = '#202020'
    try {
      $sb = $bg -as [System.Windows.Media.SolidColorBrush]
      if ($sb) {
        $c = $sb.Color
        $lum = ((0.2126 * [double]$c.R) + (0.7152 * [double]$c.G) + (0.0722 * [double]$c.B)) / 255.0
        $fgHex = if ($lum -lt 0.45) { '#7c7c7c' } else { '#202020' }
      } else {
        $fgHex = if (([string]$script:UiThemeMode) -ieq 'Dark') { '#b8b8b8' } else { '#202020' }
      }
    } catch {
      $fgHex = if (([string]$script:UiThemeMode) -ieq 'Dark') { '#b8b8b8' } else { '#202020' }
    }
    $fg = $null
    try { $fg = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($fgHex)) } catch { $fg = $null }
    if (-not $fg) { return }
    try { $createCharMapListBox.Foreground = $fg } catch {}
    try { $createCharMapListBox.Resources['UiTextBrush'] = ([System.Management.Automation.PSObject]::AsPSObject($fg)).BaseObject } catch {}
    # Force currently realized visuals to same foreground so resize/layout cannot hide glyphs.
    try {
      $stack = New-Object 'System.Collections.Generic.Stack[System.Windows.DependencyObject]'
      $stack.Push($createCharMapListBox)
      while ($stack.Count -gt 0) {
        $node = $stack.Pop()
        try {
          if ($node -is [System.Windows.Controls.TextBlock]) { $node.Foreground = $fg }
          elseif ($node -is [System.Windows.Controls.Button]) { $node.Foreground = $fg }
        } catch {}
        $cc = 0
        try { $cc = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($node) } catch { $cc = 0 }
        for ($i = 0; $i -lt $cc; $i++) {
          try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($node, $i)) } catch {}
        }
      }
    } catch {}
  } catch {}
}

