function Update-CreateIconTabsAvailability {
  param(
    [switch]$AllowSystemAndCustom,
    [switch]$SelectCharMap,
    [switch]$PreferSystemIcons
  )
  try {
    if ($createSystemIconsTab) { $createSystemIconsTab.IsEnabled = [bool]$AllowSystemAndCustom }
    if ($createCustomIconTab) { $createCustomIconTab.IsEnabled = [bool]$AllowSystemAndCustom }
    if ($createCharMapTab) { $createCharMapTab.IsEnabled = $true }
    if ($createIconTabs) {
      $createIconTabs.Visibility = 'Visible'
      if ($SelectCharMap -and $createCharMapTab) {
        try { $createIconTabs.SelectedItem = $createCharMapTab } catch {}
      } elseif ($AllowSystemAndCustom -and $PreferSystemIcons -and $createSystemIconsTab) {
        try { $createIconTabs.SelectedItem = $createSystemIconsTab } catch {}
      }
    }
    if ($SelectCharMap) {
      try { $script:CreateCharMapLastAppliedText = '' } catch {}
    }
  } catch {}
}

function Test-IsCreateEditEligibleRow {
  param([object]$Row)
  if (-not $Row) { return $false }
  try { if (Test-IsAlphaSeparatorRow -Row $Row) { return $false } } catch {}
  $rk = ''
  try { $rk = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback '') } catch { $rk = '' }
  if ($rk -ne 'Folder' -and $rk -ne 'Item') { return $false }
  $act = ''
  try { $act = [string](Get-PropString -Obj $Row -Names @('Action') -Fallback '') } catch { $act = '' }
  if ($act -eq 'Delete') { return $false }
  return $true
}

function Get-CreateEditSelectionRows {
  $byId = @{}
  foreach ($r in @($script:CurrentView)) {
    if (-not $r) { continue }
    $sel = $false
    try { $sel = [bool]$r.Selected } catch { $sel = $false }
    if (-not $sel) { continue }
    if (-not (Test-IsCreateEditEligibleRow -Row $r)) { continue }
    $rid = ''
    try { $rid = [string](Get-PropString -Obj $r -Names @('Id') -Fallback '') } catch { $rid = '' }
    if ([string]::IsNullOrWhiteSpace($rid)) { continue }
    if (-not $byId.ContainsKey($rid)) { $byId[$rid] = $r }
  }
  if ($byId.Count -eq 0) {
    $r0 = $null
    try { $r0 = $grid.SelectedItem } catch { $r0 = $null }
    if (-not $r0) { try { $r0 = $grid.CurrentItem } catch { $r0 = $null } }
    if ($r0 -and (Test-IsCreateEditEligibleRow -Row $r0)) {
      $rid0 = ''
      try { $rid0 = [string](Get-PropString -Obj $r0 -Names @('Id') -Fallback '') } catch { $rid0 = '' }
      if (-not [string]::IsNullOrWhiteSpace($rid0)) { $byId[$rid0] = $r0 }
    }
  }
  return @($byId.Values)
}

function Clear-EditPanelNamePreview {
  try {
    $rid = ''
    try { $rid = [string]$script:EditPanelPreviewRowId } catch { $rid = '' }
    if ([string]::IsNullOrWhiteSpace($rid)) { return }
    $r = $null
    try { $r = Find-ItemById -Id $rid } catch { $r = $null }
    if ($r) {
      $nm = ''
      try { $nm = [string](Get-PropString -Obj $r -Names @('Name') -Fallback '') } catch { $nm = '' }
      try { Set-PropSafeGlobal -Obj $r -Name 'ViewName' -Value $nm } catch {}
      try { Set-PendingState -it $r } catch {}
      try { Refresh-UIAsync -Priority ([System.Windows.Threading.DispatcherPriority]::Render) } catch {}
    }
  } catch {} finally {
    try { $script:EditPanelPreviewRowId = '' } catch {}
    try { $script:EditPanelPreviewLiveRowId = '' } catch {}
    try { $script:EditPanelPreviewLiveChanged = $false } catch {}
  }
}

function Find-FirstVisualChildByType {
  param(
    [System.Windows.DependencyObject]$Root,
    [Type]$Type
  )
  try {
    if (-not $Root -or -not $Type) { return $null }
    $count = 0
    try { $count = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($Root) } catch { $count = 0 }
    for ($i = 0; $i -lt $count; $i++) {
      $child = $null
      try { $child = [System.Windows.Media.VisualTreeHelper]::GetChild($Root, $i) } catch { $child = $null }
      if (-not $child) { continue }
      $isMatch = $false
      try { $isMatch = [bool]$Type.IsAssignableFrom($child.GetType()) } catch { $isMatch = $false }
      if ($isMatch) { return $child }
      $found = Find-FirstVisualChildByType -Root $child -Type $Type
      if ($found) { return $found }
    }
    return $null
  } catch {
    return $null
  }
}

function Get-GridNameColumnDisplayIndex {
  try {
    if (-not $grid) { return -1 }
    foreach ($col in @($grid.Columns)) {
      if (-not $col) { continue }
      $hdr = ''
      try { $hdr = [string]$col.Header } catch { $hdr = '' }
      if ($hdr -eq 'Name') {
        try { return [int]$col.DisplayIndex } catch { return -1 }
      }
    }
    return -1
  } catch {
    return -1
  }
}

function Try-UpdateGridNameCellVisual {
  param(
    [object]$Row,
    [string]$Text
  )
  try {
    if (-not $grid -or -not $Row) { return $false }
    $rowVisual = $null
    try { $rowVisual = $grid.ItemContainerGenerator.ContainerFromItem($Row) } catch { $rowVisual = $null }
    if (-not ($rowVisual -is [System.Windows.Controls.DataGridRow])) { return $false }
    $nameDisplayIndex = Get-GridNameColumnDisplayIndex
    if ($nameDisplayIndex -lt 0) { return $false }
    $presenter = Find-FirstVisualChildByType -Root $rowVisual -Type ([System.Windows.Controls.Primitives.DataGridCellsPresenter])
    if (-not $presenter) { return $false }
    $cell = $null
    try { $cell = $presenter.ItemContainerGenerator.ContainerFromIndex([int]$nameDisplayIndex) } catch { $cell = $null }
    if (-not ($cell -is [System.Windows.Controls.DataGridCell])) {
      for ($idx = 0; $idx -lt @($grid.Columns).Count; $idx++) {
        $c2 = $null
        try { $c2 = $presenter.ItemContainerGenerator.ContainerFromIndex([int]$idx) } catch { $c2 = $null }
        if (-not ($c2 -is [System.Windows.Controls.DataGridCell])) { continue }
        $okCol = $false
        try { $okCol = ([string]$c2.Column.Header -eq 'Name') } catch { $okCol = $false }
        if ($okCol) { $cell = $c2; break }
      }
      if (-not ($cell -is [System.Windows.Controls.DataGridCell])) { return $false }
    }
    $tb = $null
    try {
      if ($cell.Content -is [System.Windows.Controls.TextBlock]) {
        $tb = [System.Windows.Controls.TextBlock]$cell.Content
      }
    } catch {}
    if (-not $tb) {
      $tb = Find-FirstVisualChildByType -Root $cell -Type ([System.Windows.Controls.TextBlock])
    }
    if ($tb) {
      try { $tb.Text = [string]$Text } catch {}
      return $true
    }
    return $false
  } catch {
    return $false
  }
}

function Queue-EditPanelPreviewRefresh {
  try {
    if ([bool]$script:EditPanelPreviewLiteRefreshQueued) { return }
    $script:EditPanelPreviewLiteRefreshQueued = $true
    if ($window -and $window.Dispatcher) {
      [void]$window.Dispatcher.BeginInvoke([Action]{
        try {
          try { $grid.Items.Refresh() } catch {}
        } finally {
          try { $script:EditPanelPreviewLiteRefreshQueued = $false } catch {}
        }
      }, [System.Windows.Threading.DispatcherPriority]::Render)
    } else {
      try { $grid.Items.Refresh() } catch {}
      $script:EditPanelPreviewLiteRefreshQueued = $false
    }
  } catch {
    try { $script:EditPanelPreviewLiteRefreshQueued = $false } catch {}
  }
}

function Invoke-CommitEditPanelPreviewOnRowSwitch {
  param([string]$Reason = 'EditPanelRowSwitch')
  try {
    $mode = ''
    try { $mode = [string]$script:CreatePanelMode } catch { $mode = '' }
    if ($mode -ne 'EditSelected') { return $false }
    if (-not $createNameBox) { return $false }
    $rid = ''
    try { $rid = [string]$script:EditPanelPreviewRowId } catch { $rid = '' }
    if ([string]::IsNullOrWhiteSpace($rid)) { return $false }
    $row = $null
    try { $row = Find-ItemById -Id $rid } catch { $row = $null }
    if (-not $row) { return $false }
    $newName = ''
    try { $newName = [string]$createNameBox.Text } catch { $newName = '' }
    $newName = (Trim-NameInputPreserveNbsp -Text $newName)
    if (-not (Test-ValidFileName -Name $newName)) { return $false }
    $oldName = ''
    try { $oldName = [string](Get-PropString -Obj $row -Names @('Name') -Fallback '') } catch { $oldName = '' }
    if ([string]::Equals($newName, $oldName, [System.StringComparison]::Ordinal)) {
      try { $script:EditPanelPreviewRowId = '' } catch {}
      try { $script:EditPanelPreviewLiveRowId = '' } catch {}
      try { $script:EditPanelPreviewLiveChanged = $false } catch {}
      return $false
    }
    Invoke-RenameCommit -Row $row -NewName $newName -Reason $Reason
    try { $script:EditPanelPreviewRowId = '' } catch {}
    try { $script:EditPanelPreviewLiveRowId = '' } catch {}
    try { $script:EditPanelPreviewLiveChanged = $false } catch {}
    return $true
  } catch {
    try { $script:EditPanelPreviewLiveRowId = '' } catch {}
    try { $script:EditPanelPreviewLiveChanged = $false } catch {}
    return $false
  }
}

function Invoke-CommitEditSelectedRenameFromPanel {
  param(
    [string]$Reason = 'EditPanelCommit',
    [switch]$Interactive
  )
  try {
    $mode = ''
    try { $mode = [string]$script:CreatePanelMode } catch { $mode = '' }
    if ($mode -ne 'EditSelected') { return $false }
    $rows = @()
    try { $rows = @(Get-CreateEditSelectionRows) } catch { $rows = @() }
    if ($rows.Count -eq 0) {
      if ($Interactive) { [System.Windows.MessageBox]::Show("Select one or more item rows first.", "Edit Selected") | Out-Null }
      return $false
    }
    if ($rows.Count -gt 1) {
      if ($Interactive) { [System.Windows.MessageBox]::Show("Name editing is disabled for multiple selections.", "Edit Selected") | Out-Null }
      return $false
    }
    $row = $rows[0]
    if (-not $row) { return $false }
    $newName = ''
    try { $newName = [string]$createNameBox.Text } catch { $newName = '' }
    $newName = (Trim-NameInputPreserveNbsp -Text $newName)
    if (-not (Test-ValidFileName -Name $newName)) {
      if ($Interactive) {
        [System.Windows.MessageBox]::Show("Enter a valid name.", "Edit Selected") | Out-Null
      } else {
        $curName = ''
        try { $curName = [string](Get-PropString -Obj $row -Names @('Name') -Fallback '') } catch { $curName = '' }
        Set-CreateNameBoxTextSafe -Text $curName
      }
      return $false
    }
    $oldName = ''
    try { $oldName = [string](Get-PropString -Obj $row -Names @('Name') -Fallback '') } catch { $oldName = '' }
    if ([string]::Equals($newName, $oldName, [System.StringComparison]::Ordinal)) { return $false }
    Invoke-RenameCommit -Row $row -NewName $newName -Reason $Reason
    try { $script:EditPanelPreviewRowId = '' } catch {}
    try { $script:EditPanelPreviewLiveRowId = '' } catch {}
    try { $script:EditPanelPreviewLiveChanged = $false } catch {}
    try { Sync-CreateEditSelectedFields } catch {}
    return $true
  } catch {
    try { $script:EditPanelPreviewLiveRowId = '' } catch {}
    try { $script:EditPanelPreviewLiveChanged = $false } catch {}
    return $false
  }
}

function Invoke-CommitEditSelectedTargetFromPanel {
  param(
    [string]$Reason = 'EditPanelTargetCommit',
    [switch]$Interactive
  )
  try {
    $mode = ''
    try { $mode = [string]$script:CreatePanelMode } catch { $mode = '' }
    if ($mode -ne 'EditSelected') { return $false }
    $rows = @()
    try { $rows = @(Get-CreateEditSelectionRows) } catch { $rows = @() }
    if ($rows.Count -eq 0) {
      if ($Interactive) { [System.Windows.MessageBox]::Show("Select one shortcut row first.", "Edit Selected") | Out-Null }
      return $false
    }
    if ($rows.Count -gt 1) {
      if ($Interactive) { [System.Windows.MessageBox]::Show("Target editing is disabled for multiple selections.", "Edit Selected") | Out-Null }
      return $false
    }
    $row = $rows[0]
    if (-not $row) { return $false }
    if (-not (Test-IsIconChangeEligibleRow -Row $row)) {
      if ($Interactive) { [System.Windows.MessageBox]::Show("Target editing is available for shortcut rows only.", "Edit Selected") | Out-Null }
      return $false
    }
    $newTarget = ''
    try { $newTarget = [string]$createTargetBox.Text } catch { $newTarget = '' }
    $newTarget = Normalize-Path $newTarget
    if ([string]::IsNullOrWhiteSpace($newTarget) -or -not (Test-Path -LiteralPath $newTarget)) {
      if ($Interactive) {
        [System.Windows.MessageBox]::Show("Select a valid target path (file or folder).", "Edit Selected") | Out-Null
      } else {
        $curTarget = ''
        try { $curTarget = [string](Get-PropString -Obj $row -Names @('PendingTargetPath','Target') -Fallback '') } catch { $curTarget = '' }
        try { if ($createTargetBox) { $createTargetBox.Text = [string]$curTarget } } catch {}
      }
      return $false
    }
    $isPendingCreate = $false
    try { $isPendingCreate = ($row.PSObject.Properties.Match('IsPendingCreate').Count -gt 0 -and [bool]$row.IsPendingCreate) } catch { $isPendingCreate = $false }
    if ($isPendingCreate) {
      $ck = ''
      try { $ck = [string](Get-PropString -Obj $row -Names @('CreateKind') -Fallback '') } catch { $ck = '' }
      if ($ck -eq 'Shortcut') {
        try { Set-PropSafeGlobal -Obj $row -Name 'Target' -Value ([string]$newTarget) } catch {}
        try { Set-PropSafeGlobal -Obj $row -Name 'CreateTargetPath' -Value ([string]$newTarget) } catch {}
        try { if ($createTargetBox) { $createTargetBox.Text = [string]$newTarget } } catch {}
        try { Touch-VisualRuntimeState -Reason "EditSelected.PendingCreateTarget" } catch {}
        return $true
      }
    }
    $oldTarget = ''
    try { $oldTarget = Normalize-Path ([string](Get-PropString -Obj $row -Names @('Target') -Fallback '')) } catch { $oldTarget = '' }
    if ([string]::IsNullOrWhiteSpace($oldTarget)) { return $false }
    if (Test-PathEqualsCI -A $newTarget -B $oldTarget) {
      try { Set-PropSafeGlobal -Obj $row -Name 'PendingTargetPath' -Value '' } catch {}
      try { Set-PendingState -it $row } catch {}
      try { Sync-CreateEditSelectedFields } catch {}
      return $false
    }
    try { Set-PropSafeGlobal -Obj $row -Name 'PendingTargetPath' -Value ([string]$newTarget) } catch {}
    try { Set-PendingState -it $row -BumpLabels @('Target Edit') } catch {}
    try { Sync-CreateEditSelectedFields } catch {}
    return $true
  } catch {
    return $false
  }
}

function Update-CreateCharMapInsertBlankButtonState {
  try {
    if (-not $createCharMapInsertBlankBtn) { return }
    $enabled = $true
    $tooltipEnabled = 'Insert a non-breaking space (NBSP) into the Name field.'
    $tooltipDisabled = 'Cannot assign NBSP to folders'
    $mode = ''
    try { $mode = [string]$script:CreatePanelMode } catch { $mode = '' }
    if ($mode -eq 'Folder') {
      $enabled = $false
    } elseif ($mode -eq 'EditSelected') {
      $rows = @()
      try { $rows = @(Get-CreateEditSelectionRows) } catch { $rows = @() }
      if ($rows.Count -ne 1) {
        $enabled = $false
      } else {
        $r = $rows[0]
        $rk = ''
        $tp = ''
        try { $rk = [string](Get-PropString -Obj $r -Names @('RowKind') -Fallback '') } catch { $rk = '' }
        try { $tp = [string](Get-PropString -Obj $r -Names @('Type') -Fallback '') } catch { $tp = '' }
        if ($rk -eq 'Folder' -or $tp -eq 'Folder') { $enabled = $false }
      }
    }
    try {
      if ($createNameBox -and (-not [bool]$createNameBox.IsEnabled)) {
        if ($mode -ne 'Shortcut') { $enabled = $false }
      }
    } catch {}
    try { $createCharMapInsertBlankBtn.IsEnabled = [bool]$enabled } catch {}
    try { if ($enabled) { $createCharMapInsertBlankBtn.ToolTip = $null } else { $createCharMapInsertBlankBtn.ToolTip = $tooltipDisabled } } catch {}
  } catch {}
}

function Set-CreateModeUi {
  param([ValidateSet('Folder','Shortcut','EditSelected')][string]$Mode)
  try { $script:CreatePanelMode = [string]$Mode } catch {}
  $isFolder = ($Mode -eq 'Folder')
  $isShortcut = ($Mode -eq 'Shortcut')
  $isEdit = ($Mode -eq 'EditSelected')
  try { if ($createModeFolderRadio)   { $createModeFolderRadio.IsChecked = $isFolder } } catch {}
  try { if ($createModeShortcutRadio) { $createModeShortcutRadio.IsChecked = $isShortcut } } catch {}
  try { if ($createModeEditRadio)     { $createModeEditRadio.IsChecked = $isEdit } } catch {}
  try { $script:ChangeIconPanelModeActive = $isEdit } catch {}
  if (-not $isEdit) {
    try { $script:ChangeIconPanelSnapshot = @() } catch {}
    try { Clear-EditPanelNamePreview } catch {}
    try { $script:CreateEditLastSelectionSig = '' } catch {}
  }
  try { if ($createTargetRow) { $createTargetRow.Visibility = $(if ($isShortcut -or $isEdit) { 'Visible' } else { 'Collapsed' }) } } catch {}
  try {
    if ($createTargetBox) {
      $createTargetBox.ToolTip = "Browse / paste path / drag and drop target item"
      if ($isShortcut) {
        $createTargetBox.IsEnabled = $true
      } elseif (-not $isEdit) {
        $createTargetBox.IsEnabled = $false
      }
    }
  } catch {}
  $showIconPreviewArea = ($isShortcut -or $isEdit)
  try { if ($createIconLabel) { $createIconLabel.Text = 'Icon'; $createIconLabel.Visibility = $(if ($showIconPreviewArea) { 'Visible' } else { 'Collapsed' }) } } catch {}
  try { if ($createIconPreviewBorder) { $createIconPreviewBorder.Visibility = $(if ($showIconPreviewArea) { 'Visible' } else { 'Collapsed' }) } } catch {}
  try {
    if ($createIconValueCol) {
      if ($showIconPreviewArea) { $createIconValueCol.Width = [System.Windows.GridLength]::Auto }
      else { $createIconValueCol.Width = [System.Windows.GridLength]::new(0) }
    }
  } catch {}
  try {
    if ($createIconSpacerCol) {
      if ($showIconPreviewArea) { $createIconSpacerCol.Width = [System.Windows.GridLength]::new(8) }
      else { $createIconSpacerCol.Width = [System.Windows.GridLength]::new(0) }
    }
  } catch {}
  try { if ($createIconTabs) { $createIconTabs.Visibility = 'Visible' } } catch {}
  if ($isFolder) {
    try { Update-CreateIconTabsAvailability -SelectCharMap } catch {}
  } elseif ($isShortcut) {
    try { Update-CreateIconTabsAvailability -AllowSystemAndCustom -PreferSystemIcons } catch {}
  }
  try { if ($createNameLabel) { $createNameLabel.Visibility = 'Visible' } } catch {}
  try { if ($createNameBox) { $createNameBox.Visibility = 'Visible' } } catch {}
  try {
    if ($createQueueBtn) {
      if ($isEdit) {
        $createQueueBtn.Visibility = 'Collapsed'
      } else {
        $createQueueBtn.Visibility = 'Visible'
        $createQueueBtn.Content = 'Create'
      }
    }
  } catch {}
  if ($isEdit) {
    try { Sync-CreateEditSelectedFields } catch {}
  } else {
    try {
      if ($createNameBox) {
        $createNameBox.IsEnabled = $true
        $draft = ''
        if ($isFolder) {
          try { $draft = [string]$script:CreateFolderDraftName } catch { $draft = '' }
        } else {
          try { $draft = [string]$script:CreateShortcutDraftName } catch { $draft = '' }
        }
        Set-CreateNameBoxTextSafe -Text $draft
      }
    } catch {}
  }
  try { Update-CreateCharMapInsertBlankButtonState } catch {}
}

function Update-CreatePanelContext {
  $mode = 'Folder'
  try { $mode = [string]$script:CreatePanelMode } catch { $mode = 'Folder' }
  if ($mode -eq 'EditSelected') {
    try { Sync-CreateEditSelectedFields } catch {}
  }
}

function Sync-CreateEditSelectedFields {
  $mode = ''
  try { $mode = [string]$script:CreatePanelMode } catch { $mode = '' }
  if ($mode -ne 'EditSelected') { return }
  $rows = @()
  try { $rows = @(Get-CreateEditSelectionRows) } catch { $rows = @() }
  try { Update-CreateCharMapInsertBlankButtonState } catch {}
  $prevSelSig = ''
  try { $prevSelSig = [string]$script:CreateEditLastSelectionSig } catch { $prevSelSig = '' }
  $curSelSig = ''
  try {
    $ids = @($rows | ForEach-Object { [string](Get-PropString -Obj $_ -Names @('Id') -Fallback '') } | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Sort-Object)
    $curSelSig = (@($ids) -join '|')
  } catch { $curSelSig = '' }
  $selectionChanged = $false
  try { $selectionChanged = (-not [string]::Equals($curSelSig, $prevSelSig, [System.StringComparison]::Ordinal)) } catch { $selectionChanged = ($curSelSig -ne $prevSelSig) }
  $iconRows = @()
  try { $iconRows = @($rows | Where-Object { Test-IsIconChangeEligibleRow -Row $_ }) } catch { $iconRows = @() }
  $canIconEdit = (@($iconRows).Count -gt 0)
  try { $script:ChangeIconPanelSnapshot = @(New-IconChangeSnapshotFromRows -Rows $iconRows) } catch { $script:ChangeIconPanelSnapshot = @() }
  if ($rows.Count -le 0) {
    try { Clear-EditPanelNamePreview } catch {}
    try { Set-CreateSelectedIcon -IconPath '' -IconIndex 0 -Image $null -Label '(select a start menu item)' } catch {}
    try {
      if ($createNameBox) {
        $createNameBox.IsEnabled = $false
        Set-CreateNameBoxTextSafe -Text 'select a start menu item...'
      }
    } catch {}
    try { Update-CreateIconTabsAvailability } catch {}
    try { if ($createSystemIconSummaryText) { $createSystemIconSummaryText.Text = 'Select one or more items' } } catch {}
    try {
      if ($createTargetRow) { $createTargetRow.Visibility = 'Collapsed' }
      if ($createTargetBox) {
        $createTargetBox.IsEnabled = $false
        $createTargetBox.Text = ''
      }
    } catch {}
    try { $script:CreateEditLastSelectionSig = '' } catch {}
    return
  }
  $first = $rows[0]
  $iconSeedRow = $null
  if ($canIconEdit) { $iconSeedRow = $iconRows[0] }
  $iconPath = ''
  $iconIndex = 0
  $iconImage = $null
  if ($iconSeedRow) {
    try {
      if (Test-RowHasPendingIconChange -Row $iconSeedRow) {
        $iconPath = Normalize-Path ([string](Get-PropString -Obj $iconSeedRow -Names @('PendingIconPath') -Fallback ''))
        try { $iconIndex = [int](Get-PropString -Obj $iconSeedRow -Names @('PendingIconIndex') -Fallback '0') } catch { $iconIndex = 0 }
      }
    } catch {}
    if ([string]::IsNullOrWhiteSpace($iconPath)) {
      try {
        $isPendingCreateSeed = $false
        try { $isPendingCreateSeed = ($iconSeedRow.PSObject.Properties.Match('IsPendingCreate').Count -gt 0 -and [bool]$iconSeedRow.IsPendingCreate) } catch { $isPendingCreateSeed = $false }
        if ($isPendingCreateSeed) {
          $iconPath = Normalize-Path ([string](Get-PropString -Obj $iconSeedRow -Names @('CreateIconPath') -Fallback ''))
          try { $iconIndex = [int](Get-PropString -Obj $iconSeedRow -Names @('CreateIconIndex') -Fallback '0') } catch { $iconIndex = 0 }
          if ([string]::IsNullOrWhiteSpace($iconPath)) {
            $iconPath = Normalize-Path ([string](Get-PropString -Obj $iconSeedRow -Names @('Target','CreateTargetPath') -Fallback ''))
            $iconIndex = 0
          }
        }
      } catch {}
    }
    if ([string]::IsNullOrWhiteSpace($iconPath)) {
      try {
        $lnk = Resolve-ExistingShortcutPathForRow -Row $iconSeedRow
        if (-not [string]::IsNullOrWhiteSpace($lnk)) {
          $spec = Get-ShortcutIconLocationSpecFromLink -LnkPath $lnk
          if ($spec) {
            $iconPath = [string]$spec.IconPath
            $iconIndex = [int]$spec.IconIndex
          }
        }
      } catch {}
    }
    try { $iconImage = $iconSeedRow.Icon } catch { $iconImage = $null }
    if (-not $iconImage -and -not [string]::IsNullOrWhiteSpace($iconPath)) {
      try { $iconImage = Get-ImageSourceFromIcon -IconPath $iconPath -IconIndex $iconIndex -FallbackExePath $iconPath } catch { $iconImage = $null }
    }
    $iconLabel = '(selected)'
    if (-not [string]::IsNullOrWhiteSpace($iconPath)) {
      try { $iconLabel = ([System.IO.Path]::GetFileName([string]$iconPath) + ',' + [string]$iconIndex) } catch {}
    }
    try { Set-CreateSelectedIcon -IconPath $iconPath -IconIndex $iconIndex -Image $iconImage -Label $iconLabel } catch {}
  } else {
    try { Set-CreateSelectedIcon -IconPath '' -IconIndex 0 -Image $null -Label '   (folder selected)' } catch {}
  }
  if ($rows.Count -eq 1) {
    $nm = ''
    try { $nm = [string](Get-PropString -Obj $first -Names @('Name') -Fallback '') } catch { $nm = '' }
    try {
      $prevRid = ''
      try { $prevRid = [string]$script:EditPanelPreviewRowId } catch { $prevRid = '' }
      $curRid = [string](Get-PropString -Obj $first -Names @('Id') -Fallback '')
      if (-not [string]::IsNullOrWhiteSpace($prevRid) -and $prevRid -ne $curRid) {
        Clear-EditPanelNamePreview
      }
      Set-PropSafeGlobal -Obj $first -Name 'ViewName' -Value $nm
      $script:EditPanelPreviewRowId = ''
    } catch {}
    try {
      if ($createNameBox) {
        $createNameBox.IsEnabled = $true
        Set-CreateNameBoxTextSafe -Text $nm
      }
    } catch {}
    try {
      $canTargetEdit = $false
      try { $canTargetEdit = [bool](Test-IsIconChangeEligibleRow -Row $first) } catch { $canTargetEdit = $false }
      if ($createTargetRow) { $createTargetRow.Visibility = $(if ($canTargetEdit) { 'Visible' } else { 'Collapsed' }) }
      if ($createTargetBox) {
        $createTargetBox.IsEnabled = $canTargetEdit
        if ($canTargetEdit) {
          $targetText = ''
          try { $targetText = [string](Get-PropString -Obj $first -Names @('PendingTargetPath','Target','CreateTargetPath') -Fallback '') } catch { $targetText = '' }
          $createTargetBox.Text = [string]$targetText
        } else {
          $createTargetBox.Text = ''
        }
      }
    } catch {}
    if ($canIconEdit) {
      $preferSystem = $false
      try { $preferSystem = [bool]$selectionChanged } catch { $preferSystem = $false }
      try { Update-CreateIconTabsAvailability -AllowSystemAndCustom -PreferSystemIcons:$preferSystem } catch {}
      try { if ($createSystemIconSummaryText) { $createSystemIconSummaryText.Text = ("1 shortcut selected.") } } catch {}
    } else {
      try { Update-CreateIconTabsAvailability -SelectCharMap } catch {}
      try { if ($createSystemIconSummaryText) { $createSystemIconSummaryText.Text = ("1 folder selected. Only renaming available") } } catch {}
    }
  } else {
    try { Clear-EditPanelNamePreview } catch {}
    try {
      if ($createNameBox) {
        $createNameBox.IsEnabled = $false
        Set-CreateNameBoxTextSafe -Text 'multiple items selected...'
      }
    } catch {}
    try {
      if ($createTargetRow) { $createTargetRow.Visibility = 'Collapsed' }
      if ($createTargetBox) {
        $createTargetBox.IsEnabled = $false
        $createTargetBox.Text = ''
      }
    } catch {}
    if ($canIconEdit) {
      try { Update-CreateIconTabsAvailability -AllowSystemAndCustom } catch {}
      try { if ($createSystemIconSummaryText) { $createSystemIconSummaryText.Text = ("{0} items selected. Only icon changes are applied to multiple selections." -f $rows.Count) } } catch {}
    } else {
      try { Update-CreateIconTabsAvailability -SelectCharMap } catch {}
      try { if ($createSystemIconSummaryText) { $createSystemIconSummaryText.Text = ("{0} folders selected. Renaming is disabled for multiple selections." -f $rows.Count) } } catch {}
    }
  }
  try { $script:CreateEditLastSelectionSig = [string]$curSelSig } catch {}
}

function Set-CreateSelectedIcon {
  param(
    [string]$IconPath,
    [int]$IconIndex = 0,
    [object]$Image = $null,
    [string]$Label = '(none)'
  )
  $script:CreateSelectedIconPath = [string]$IconPath
  $script:CreateSelectedIconIndex = [int]$IconIndex
  $script:CreateSelectedIconImage = $Image
  try { $createSelectedIconPreview.Source = $Image } catch {}
  try { $createSelectedIconText.Text = [string]$Label } catch {}
}

function Get-SystemIconSelectedCategorySet {
  if (-not $script:SystemIconSelectedCategories) { $script:SystemIconSelectedCategories = @{} }
  $set = @{}
  foreach ($k in @($script:SystemIconSelectedCategories.Keys)) {
    $n = [string]$k
    if (-not [string]::IsNullOrWhiteSpace($n)) { $set[$n] = $true }
  }
  return $set
}

function Apply-SystemIconCategoryPresetSelection {
  try {
    if (-not [bool]$script:SystemIconSelectedCategoriesPresetDefined) { return }
    $presetNames = @($script:SystemIconSelectedCategoriesPresetNames)
    $newSel = @{}
    foreach ($cat in @($script:SystemIconCategoryList)) {
      $cn = Normalize-SystemIconCategoryName -Name ([string]$cat)
      if ([string]::IsNullOrWhiteSpace($cn)) { continue }
      if (@($presetNames) -contains $cn) { $newSel[$cn] = $true }
    }
    $script:SystemIconSelectedCategories = $newSel
    $script:SystemIconCategorySelectionInitialized = $true
  } catch {}
}

function Ensure-SystemIconCategorySelectionDefaults {
  if (-not $script:SystemIconSelectedCategories) { $script:SystemIconSelectedCategories = @{} }
  if (-not [bool]$script:SystemIconCategorySelectionInitialized) {
    if (@($script:SystemIconSelectedCategories.Keys).Count -eq 0) {
      foreach ($c in @($script:SystemIconCategoryList)) {
        if ([string]::IsNullOrWhiteSpace([string]$c)) { continue }
        $script:SystemIconSelectedCategories[[string]$c] = $true
      }
    }
    $script:SystemIconCategorySelectionInitialized = $true
  }
}

function New-BrightenedAccentBrush {
  param(
    [Parameter(Mandatory=$true)][object]$Brush,
    [double]$Factor = 1.16
  )
  try {
    $baseBrush = Resolve-WpfBrush -Value $Brush
    $sb = $baseBrush -as [System.Windows.Media.SolidColorBrush]
    if ($null -eq $sb) { return $baseBrush }
    $f = [double]$Factor
    if ($f -lt 1.0) { $f = 1.0 }
    if ($f -gt 2.0) { $f = 2.0 }
    $t = [Math]::Max(0.0, [Math]::Min(1.0, ($f - 1.0)))
    $c = $sb.Color
    $r = [byte][Math]::Round([double]$c.R + ((255.0 - [double]$c.R) * $t))
    $g = [byte][Math]::Round([double]$c.G + ((255.0 - [double]$c.G) * $t))
    $b = [byte][Math]::Round([double]$c.B + ((255.0 - [double]$c.B) * $t))
    $out = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb($c.A, $r, $g, $b))
    try { $out.Freeze() } catch {}
    return $out
  } catch {
    return (Resolve-WpfBrush -Value $Brush)
  }
}

function Update-SystemIconCategoryButtonCaption {
  try {
    if (-not $createSystemIconCategoryFilterBtn) { return }
    $createSystemIconCategoryFilterBtn.Content = " Categories "
  } catch {}
}

function Rebuild-SystemIconCategoryChecklistUi {
  if (-not $createSystemIconCategoryChecklist) { return }
  Ensure-SystemIconCategorySelectionDefaults
  $selectedSet = Get-SystemIconSelectedCategorySet
  try { $createSystemIconCategoryChecklist.Children.Clear() } catch {}
  foreach ($cat in @($script:SystemIconCategoryList)) {
    $c = [string]$cat
    if ([string]::IsNullOrWhiteSpace($c)) { continue }
    $cb = New-Object System.Windows.Controls.CheckBox
    $cb.Content = $c
    $cb.Tag = $c
    $cb.Margin = '0,0,14,4'
    try { $cb.Style = $window.FindResource('UiCheckBoxStyle') } catch {}
    $cb.IsChecked = $selectedSet.ContainsKey($c)
    $cb.Add_Checked({
      param($s,$e)
      try {
        $name = [string]$s.Tag
        if (-not [string]::IsNullOrWhiteSpace($name)) { $script:SystemIconSelectedCategories[$name] = $true }
        $script:SystemIconCurrentPage = 1
        Update-SystemIconCategoryButtonCaption
        Save-UserPresetSettings
      } catch {}
      Queue-CreateSystemIconRefresh -Immediate
    })
    $cb.Add_Unchecked({
      param($s,$e)
      try {
        $name = [string]$s.Tag
        if (-not [string]::IsNullOrWhiteSpace($name) -and $script:SystemIconSelectedCategories.ContainsKey($name)) {
          [void]$script:SystemIconSelectedCategories.Remove($name)
        }
        $script:SystemIconCurrentPage = 1
        Update-SystemIconCategoryButtonCaption
        Save-UserPresetSettings
      } catch {}
      Queue-CreateSystemIconRefresh -Immediate
    })
    try { [void]$createSystemIconCategoryChecklist.Children.Add($cb) } catch {}
  }
  Update-SystemIconCategoryButtonCaption
}

function Refresh-CreateSystemIconList {
  if (-not $createSystemIconListBox) { return }
  try { Ensure-SystemIconCatalogLoaded } catch {}
  $all = @($script:SystemIconCatalogAll)
  Ensure-SystemIconCategorySelectionDefaults
  $selectedSet = Get-SystemIconSelectedCategorySet
  $selectedCategories = @($selectedSet.Keys)
  $q = ''
  try { if ($createSystemIconSearchBox) { $q = [string]$createSystemIconSearchBox.Text } } catch { $q = '' }
  try { $script:SystemIconSearchQuery = [string]$q } catch {}
  $filtered = @()
  try { $filtered = @(Get-SystemIconFilteredRows -SelectedCategories $selectedCategories -Query $q) } catch { $filtered = @() }
  $filteredCount = @($filtered).Count
  $pageSize = 700
  try { $pageSize = [Math]::Max(1, [int]$script:SystemIconPageSize) } catch { $pageSize = 700 }
  $totalPages = 1
  if ($filteredCount -gt 0) {
    try { $totalPages = [Math]::Max(1, [int][Math]::Ceiling(([double]$filteredCount / [double]$pageSize))) } catch { $totalPages = 1 }
  }
  $page = 1
  try { $page = [int]$script:SystemIconCurrentPage } catch { $page = 1 }
  if ($page -lt 1) { $page = 1 }
  if ($page -gt $totalPages) { $page = $totalPages }
  $script:SystemIconCurrentPage = $page
  $src = @()
  if ($filteredCount -gt 0) {
    $skip = ($page - 1) * $pageSize
    if ($skip -lt 0) { $skip = 0 }
    $src = @($filtered | Select-Object -Skip $skip -First $pageSize)
  }
  try { $createSystemIconListBox.ItemsSource = $src } catch {}
  try {
    if ($createSystemIconPrevPageBtn) { $createSystemIconPrevPageBtn.IsEnabled = ($page -gt 1) }
    if ($createSystemIconNextPageBtn) { $createSystemIconNextPageBtn.IsEnabled = ($page -lt $totalPages) }
    if ($createSystemIconPageText) { $createSystemIconPageText.Text = ("Page {0}/{1}" -f $page, $totalPages) }
  } catch {}
  try { Apply-SystemIconNavButtonTheme } catch {}
  if ($createSystemIconSummaryText) {
    try {
      $totalCats = @($script:SystemIconCategoryList).Count
      $selCats = @($selectedCategories).Count
      $catText = (" Categories: {0}/{1} selected." -f $selCats, $totalCats)
      if ($filteredCount -gt 0) {
        $start = (($page - 1) * $pageSize) + 1
        $end = $start + @($src).Count - 1
        $createSystemIconSummaryText.Text = ("Showing {0}-{1} of {2} icons.{3}" -f $start, $end, $filteredCount, $catText)
      } else {
        $createSystemIconSummaryText.Text = ("Showing 0 icons.{0}" -f $catText)
      }
    } catch {}
  }
}

function Test-PendingCreatePathExists {
  param([Parameter(Mandatory=$true)][string]$Path)
  $k = ''
  try { $k = [string](Normalize-Path ([string]$Path)) } catch { $k = '' }
  try { $k = $k.ToLowerInvariant() } catch {}
  if ([string]::IsNullOrWhiteSpace($k)) { return $false }
  foreach ($r in @(Get-PendingCreateRows)) {
    if (-not $r) { continue }
    $rp = ''
    try { $rp = [string](Normalize-Path ([string]$r.Path)) } catch { $rp = '' }
    try { $rp = $rp.ToLowerInvariant() } catch {}
    if ($rp -eq $k) { return $true }
  }
  return $false
}


function New-PendingCreateGridRow {
  param(
    [ValidateSet('Folder','Shortcut')][string]$Kind,
    [Parameter(Mandatory=$true)][string]$Name,
    [Parameter(Mandatory=$true)][string]$DestPath,
    [string]$TargetPath = '',
    [string]$IconPath = '',
    [int]$IconIndex = 0,
    [object]$IconImage = $null
  )
  $effectiveIconPath = [string]$IconPath
  $effectiveIconIndex = [int]$IconIndex
  $effectiveIconImage = $IconImage
  # Folder creates must never inherit prior shortcut icon state.
  if ($Kind -eq 'Folder') {
    $effectiveIconPath = ''
    $effectiveIconIndex = 0
    $effectiveIconImage = $null
  }
  $img = $effectiveIconImage
  if ($Kind -eq 'Folder') {
    $img = Get-FolderRowIcon
  } elseif (-not $img) {
    $img = Get-ImageSourceFromIcon -IconPath $effectiveIconPath -IconIndex $effectiveIconIndex -FallbackExePath $TargetPath
    if (-not $img) { $img = Get-GenericAppIconImageSource }
  }
  return [pscustomobject]@{
    Id              = [guid]::NewGuid().ToString()
    Selected        = $false
    Action          = 'Create'
    PendingLabel    = 'Created'
    PendingLabelRows= @([pscustomobject]@{ Text = 'Created'; Color = '#ffffff' })
    OriginalName    = [string]$Name
    Name            = [string]$Name
    Type            = $(if ($Kind -eq 'Folder') { 'Folder' } else { 'Shortcut' })
    Scope           = 'CurrentUser'
    Target          = [string]$TargetPath
    Arguments       = ''
    Path            = [string]$DestPath
    OriginalPath    = [string]$DestPath
    Icon            = $img
    RowKind         = $(if ($Kind -eq 'Folder') { 'Folder' } else { 'Item' })
    IsPendingCreate = $true
    CreateKind      = [string]$Kind
    CreateTargetPath= [string]$TargetPath
    CreateIconPath  = [string]$effectiveIconPath
    CreateIconIndex = [int]$effectiveIconIndex
  }
}

if ($createModeFolderRadio) {
  $createModeFolderRadio.Add_Checked({ Set-CreateModeUi -Mode 'Folder' })
}
if ($createModeShortcutRadio) {
  $createModeShortcutRadio.Add_Checked({ Set-CreateModeUi -Mode 'Shortcut' })
}
if ($createModeEditRadio) {
  $createModeEditRadio.Add_Checked({ Set-CreateModeUi -Mode 'EditSelected' })
}

if ($createCharMapFontBox) {
  $createCharMapFontBox.Add_SelectionChanged({
    try { Apply-CreateCharMapFilter } catch {}
  })
}

