          $src = $e.OriginalSource
          $btn = $null
          $d = $src -as [System.Windows.DependencyObject]
          while ($d) {
            if ($d -is [System.Windows.Controls.Button]) { $btn = $d; break }
            try { $d = [System.Windows.Media.VisualTreeHelper]::GetParent($d) } catch { break }
          }
          if (-not $btn) { return }

          $it = $null
          try { $it = $btn.Tag } catch { $it = $null }
          if (-not $it) { return }
          $ch = ''
          $hex = ''
          try { $ch = [string]$it.Char } catch { $ch = '' }
          try { $hex = [string]$it.CodeHex } catch { $hex = '' }
          if ([string]::IsNullOrEmpty($ch)) { return }
          if (-not [string]::IsNullOrWhiteSpace($hex) -and $createCharMapCodePointText) {
            try { $createCharMapCodePointText.Text = $hex } catch {}
          }
          [void](Add-CreateCharMapTextToCopyBox -Text $ch)
          $e.Handled = $true
        } catch {}
      },
      $true
    )
  } catch {}
}

if ($createNameBox) {
  $createNameBox.Add_GotKeyboardFocus({
    try { $script:CreateCharMapInsertTarget = 'Name' } catch {}
  })
  $createNameBox.Add_PreviewMouseDown({
    try { $script:CreateCharMapInsertTarget = 'Name' } catch {}
  })
  $createNameBox.Add_TextChanged({
    try {
      if ([bool]$script:RenameLiveSyncSuspend) { return }
      $newText = ''
      try { $newText = [string]$createNameBox.Text } catch { $newText = '' }

      $mode = ''
      try { $mode = [string]$script:CreatePanelMode } catch { $mode = '' }
      if ($mode -eq 'Folder') {
        try { $script:CreateFolderDraftName = $newText } catch {}
      } elseif ($mode -eq 'Shortcut') {
        try { $script:CreateShortcutDraftName = $newText } catch {}
      }

      if ($mode -ne 'EditSelected') { return }

      $script:RenameLiveSyncSuspend = $true
      try {
        # Mirror to active inline rename textbox only while it is still the live editor.
        $tb = $null
        try { $tb = $script:ActiveRenameTextBox } catch { $tb = $null }
        $tbLive = $false
        if ($tb) {
          try { $tbLive = [bool]$tb.IsKeyboardFocusWithin } catch { $tbLive = $false }
        }
        if ($tb -and $tbLive) {
          $curText = ''
          try { $curText = [string]$tb.Text } catch { $curText = '' }
          if ($curText -ne $newText) {
            $tb.Text = $newText
            try { $tb.CaretIndex = $tb.Text.Length } catch {}
          }
        }

        # Live panel->grid preview when editing from panel (single selection).
        if (-not $tbLive) {
          $r = $null
          $rid = ''

          # Fast path: resolve preview row from cached row id first.
          try { $rid = [string]$script:EditPanelPreviewRowId } catch { $rid = '' }
          if (-not [string]::IsNullOrWhiteSpace($rid)) {
            try { $r = Find-ItemById -Id $rid } catch { $r = $null }
          }
          if (-not $r) {
            $r0 = $null
            try { $r0 = $grid.SelectedItem } catch { $r0 = $null }
            if ($r0 -and (Test-IsCreateEditEligibleRow -Row $r0)) {
              $r = $r0
              try { $rid = [string](Get-PropString -Obj $r -Names @('Id') -Fallback '') } catch { $rid = '' }
            }
          }
          if (-not $r) {
            $rows = @()
            try { $rows = @(Get-CreateEditSelectionRows) } catch { $rows = @() }
            if ($rows.Count -eq 1) {
              $r = $rows[0]
              try { $rid = [string](Get-PropString -Obj $r -Names @('Id') -Fallback '') } catch { $rid = '' }
            }
          }

          if ($r) {
            $prevRid = ''
            try { $prevRid = [string]$script:EditPanelPreviewRowId } catch { $prevRid = '' }
            if (-not [string]::IsNullOrWhiteSpace($prevRid) -and $prevRid -ne $rid) {
              try {
                $prevRow = Find-ItemById -Id $prevRid
                if ($prevRow) { Set-PendingState -it $prevRow }
              } catch {}
              try { Clear-EditPanelNamePreview } catch {}
            }
            try { Set-PropSafeGlobal -Obj $r -Name 'ViewName' -Value $newText } catch {}
            try { $script:EditPanelPreviewRowId = $rid } catch {}
            try {
              $wasChanged = $false
              $liveRid = ''
              try { $liveRid = [string]$script:EditPanelPreviewLiveRowId } catch { $liveRid = '' }
              if (-not [string]::IsNullOrWhiteSpace($liveRid) -and $liveRid -eq $rid) {
                try { $wasChanged = [bool]$script:EditPanelPreviewLiveChanged } catch { $wasChanged = $false }
              }
              $isChangedNow = $false
              try {
                $previewTrim = [string]$newText
                if ($null -ne $previewTrim) { $previewTrim = $previewTrim.Trim() }
                $baseName = [string](Get-PropString -Obj $r -Names @('_EditOldName','Name') -Fallback '')
                $isChangedNow = (-not [string]::Equals($previewTrim, $baseName, [System.StringComparison]::Ordinal))
              } catch { $isChangedNow = $false }
              if ($isChangedNow) {
                if (-not $wasChanged) {
                  Set-PendingState -it $r -PreviewName $newText -BumpLabels @('Renamed')
                } else {
                  Set-PendingState -it $r -PreviewName $newText
                }
              } else {
                Set-PendingState -it $r -PreviewName $newText
              }
              $script:EditPanelPreviewLiveRowId = [string]$rid
              $script:EditPanelPreviewLiveChanged = [bool]$isChangedNow
            } catch {}

            try { Queue-EditPanelPreviewRefresh } catch {}
          } else {
            try { Clear-EditPanelNamePreview } catch {}
          }
        }
      } finally {
        $script:RenameLiveSyncSuspend = $false
      }
    } catch {}
  })

  $createNameBox.Add_LostFocus({
    try { [void](Invoke-CommitEditSelectedRenameFromPanel -Reason 'EditPanelLostFocus') } catch {}
  })

  $createNameBox.Add_PreviewKeyDown({
    param($s,$e)
    try {
      if ($e.Key -ne [System.Windows.Input.Key]::Enter) { return }
      $mode = ''
      try { $mode = [string]$script:CreatePanelMode } catch { $mode = '' }
      if ($mode -ne 'EditSelected') { return }
      $e.Handled = $true
      [void](Invoke-CommitEditSelectedRenameFromPanel -Reason 'EditPanelEnter')
    } catch {}
  })
}

if ($rightPanelTabs) {
