    param($sender, $e)
    try {
      try { Apply-ExplicitUiPanelTabColors -Mode $script:UiThemeMode } catch {}
      try { Queue-UiThemeReapplyAfterTabSwitch } catch {}
      try { Apply-CreateSystemIconsTopRuleTheme } catch {}
      if (-not $sender) { return }
