          if ($tabSel -and [object]::ReferenceEquals($tabSel, $createCharMapTab)) {
            Ensure-EmbeddedCharMap
          }
        }
      } catch {}
    } finally {
      try { $window.Cursor = [System.Windows.Input.Cursors]::Arrow } catch {}
    }
  })
}

function Update-CreateSystemIconCategoryPopupBounds {
  try {
    if (-not $createSystemIconCategoryPopup -or -not $createSystemIconCategoryFilterBtn -or -not $window) { return }
    if (-not [bool]$createSystemIconCategoryPopup.IsOpen) { return }
    $child = $null
    try { $child = $createSystemIconCategoryPopup.Child } catch { $child = $null }
    if (-not $child) { return }
    try { $createSystemIconCategoryPopup.HorizontalOffset = 0 } catch {}
    try { $createSystemIconCategoryPopup.VerticalOffset = 0 } catch {}
    try { $child.UpdateLayout() } catch {}
    $popupW = 0.0
    try { $popupW = [double]$child.ActualWidth } catch { $popupW = 0.0 }
    if ($popupW -le 1.0) { try { $popupW = [double]$child.RenderSize.Width } catch { $popupW = 0.0 } }
    if ($popupW -le 1.0) { return }
    $winW = 0.0
    try { $winW = [double]$window.ActualWidth } catch { $winW = 0.0 }
    if ($winW -le 1.0) { return }
    $anchorLeft = 0.0
    try {
      $pt = $createSystemIconCategoryFilterBtn.TranslatePoint((New-Object System.Windows.Point(0,0)), $window)
      $anchorLeft = [double]$pt.X
    } catch { $anchorLeft = 0.0 }
    $minLeft = 0.0
    $maxLeft = [Math]::Max(0.0, $winW - $popupW - 2.0)
    $targetLeft = [Math]::Min($maxLeft, [Math]::Max($minLeft, $anchorLeft))
    $dx = $targetLeft - $anchorLeft
    try { $createSystemIconCategoryPopup.HorizontalOffset = [double]$dx } catch {}
  } catch {}
}

