    } catch {}
  })
  try {
    $window.Add_SizeChanged({
      try { if ($createSystemIconCategoryPopup -and [bool]$createSystemIconCategoryPopup.IsOpen) { Update-CreateSystemIconCategoryPopupBounds } } catch {}
    })
  } catch {}
