if ($createSystemIconListBox) {
  try { if (-not (Test-Path variable:script:CreateSystemIconClickItem)) { $script:CreateSystemIconClickItem = $null } } catch {}
  try { if (-not (Test-Path variable:script:CreateSystemIconClickWasSelected)) { $script:CreateSystemIconClickWasSelected = $false } } catch {}

  $applyCreateSystemIconSelection = {
    param($sel)
    if (-not $sel) { return }
    $ip = ''
    $ii = 0
    $im = $null
    $lb = ''
    try { $ip = [string]$sel.IconPath } catch {}
    try { $ii = [int]$sel.IconIndex } catch {}
    try { $im = $sel.Icon } catch {}
    try { $lb = [string]$sel.Label } catch {}
    Set-CreateSelectedIcon -IconPath $ip -IconIndex $ii -Image $im -Label $lb
    if ($script:ChangeIconPanelModeActive) {
      [void](Invoke-ApplyIconChangeFromPanel -IconPath $ip -IconIndex $ii -IconImage $im)
    }
  }

  $createSystemIconListBox.Add_PreviewMouseLeftButtonDown({
    param($sender, $e)
    try {
      $clicked = $null
      $dep = $null
      try { $dep = $e.OriginalSource -as [System.Windows.DependencyObject] } catch { $dep = $null }
      if ($dep) {
        $lbi = $null
        try { $lbi = Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.ListBoxItem]) } catch { $lbi = $null }
        if ($lbi) {
          try { $clicked = $lbi.DataContext } catch { $clicked = $null }
        }
      }
      $script:CreateSystemIconClickItem = $clicked
      $isSame = $false
      if ($clicked) {
        try { $isSame = [object]::ReferenceEquals($clicked, $createSystemIconListBox.SelectedItem) } catch { $isSame = $false }
      }
      $script:CreateSystemIconClickWasSelected = [bool]$isSame
    } catch {}
  })

  $createSystemIconListBox.Add_PreviewMouseLeftButtonUp({
    param($sender, $e)
    try {
      if (-not $script:ChangeIconPanelModeActive) { return }
      $wasSelected = $false
      $clicked = $null
      try { $wasSelected = [bool]$script:CreateSystemIconClickWasSelected } catch { $wasSelected = $false }
      try { $clicked = $script:CreateSystemIconClickItem } catch { $clicked = $null }
      if (-not $wasSelected -or -not $clicked) { return }
      & $applyCreateSystemIconSelection $clicked
      $e.Handled = $true
    } catch {} finally {
      try { $script:CreateSystemIconClickItem = $null } catch {}
      try { $script:CreateSystemIconClickWasSelected = $false } catch {}
    }
  })

  $createSystemIconListBox.Add_PreviewMouseWheel({
    param($sender, $e)
    try {
      $sv = Find-VisualChild -Parent $sender -Type ([System.Windows.Controls.ScrollViewer])
      if (-not $sv) { return }
      $step = 96.0
      $delta = 0.0
      try { $delta = [double]$e.Delta } catch { $delta = 0.0 }
      $newOffset = $sv.VerticalOffset - (($delta / 120.0) * $step)
      if ($newOffset -lt 0) { $newOffset = 0 }
      $sv.ScrollToVerticalOffset($newOffset)
      $e.Handled = $true
    } catch {}
  })

  $createSystemIconListBox.Add_SelectionChanged({
    $sel = $null
    try { $sel = $createSystemIconListBox.SelectedItem } catch {}
    if (-not $sel) { return }
    & $applyCreateSystemIconSelection $sel
  })
}

if ($grid) {
  $grid.Add_PreviewMouseWheel({
    param($sender, $e)
    try {
      if ([bool]$script:GridDragInProgress -or [bool]$script:GridSmoothSuspendByDrag) { return }
      if (-not $sender) { return }
      $sv = Find-VisualChild -Parent $sender -Type ([System.Windows.Controls.ScrollViewer])
      if (-not $sv) { return }

      $delta = 0.0
      try { $delta = [double]$e.Delta } catch { $delta = 0.0 }
      if ($delta -eq 0.0) { return }
      Queue-GridSmoothWheelScroll -ScrollViewer $sv -WheelDelta $delta
      $e.Handled = $true
    } catch {}
  })
}

function Apply-CreateShortcutTargetSelection {
  param([string]$PickedPath)
  try {
    $pickedNorm = Normalize-Path ([string]$PickedPath)
    if ([string]::IsNullOrWhiteSpace($pickedNorm)) { $pickedNorm = [string]$PickedPath }
    if ([string]::IsNullOrWhiteSpace($pickedNorm)) { return }
    if (-not (Test-Path -LiteralPath $pickedNorm)) { return }
    try { if ($createTargetBox) { $createTargetBox.Text = [string]$pickedNorm } } catch {}
    $modeNow = ''
    try { $modeNow = [string]$script:CreatePanelMode } catch { $modeNow = '' }
    if ($modeNow -eq 'EditSelected') {
      try { [void](Invoke-CommitEditSelectedTargetFromPanel -Reason 'EditPanelTargetPick') } catch {}
      return
    }
    if ($modeNow -ne 'Shortcut') { return }
    $pickedName = ''
    $isFolder = $false
    try { $isFolder = Test-Path -LiteralPath $pickedNorm -PathType Container } catch { $isFolder = $false }
    if ($isFolder) {
      try { $pickedName = [string][System.IO.Path]::GetFileName([string]$pickedNorm) } catch { $pickedName = '' }
    } else {
      try { $pickedName = [string][System.IO.Path]::GetFileNameWithoutExtension([string]$pickedNorm) } catch { $pickedName = '' }
      if ([string]::IsNullOrWhiteSpace($pickedName)) {
        try { $pickedName = [string][System.IO.Path]::GetFileName([string]$pickedNorm) } catch { $pickedName = '' }
      }
    }
    if (-not [string]::IsNullOrWhiteSpace($pickedName)) {
      try { Set-CreateNameBoxTextSafe -Text $pickedName } catch {}
      try { $script:CreateShortcutDraftName = [string]$pickedName } catch {}
    }
    $pickedImg = $null
    $pickedIconPath = [string]$pickedNorm
    $pickedIconIndex = 0
    if ($isFolder) {
      try { $pickedImg = Get-SystemFolderIconImageSource -Size Small } catch { $pickedImg = $null }
      try {
        $folderSpec = Get-DefaultFolderIconLocationSpec
        if ($folderSpec -and -not [string]::IsNullOrWhiteSpace([string]$folderSpec.IconPath)) {
          $pickedIconPath = [string]$folderSpec.IconPath
          try { $pickedIconIndex = [int]$folderSpec.IconIndex } catch { $pickedIconIndex = 0 }
        }
      } catch {}
    }
    if (-not $pickedImg) {
      try { $pickedImg = Get-ImageSourceFromIcon -IconPath $pickedIconPath -IconIndex $pickedIconIndex -FallbackExePath $pickedNorm } catch { $pickedImg = $null }
    }
    if (-not $pickedImg) {
      try { $pickedImg = Get-GenericAppIconImageSource } catch { $pickedImg = $null }
    }
    $pickedLabel = ''
    try { $pickedLabel = ([System.IO.Path]::GetFileName($pickedIconPath) + ',' + [string]$pickedIconIndex) } catch { $pickedLabel = ($pickedIconPath + ',' + [string]$pickedIconIndex) }
    try { Set-CreateSelectedIcon -IconPath $pickedIconPath -IconIndex $pickedIconIndex -Image $pickedImg -Label $pickedLabel } catch {}
  } catch {}
}

function Get-PathFromLooseText {
  param([string]$Text)
  try {
    if ([string]::IsNullOrWhiteSpace($Text)) { return '' }
    foreach ($line in @([string]$Text -split "`r?`n")) {
      $s = [string]$line
      if ([string]::IsNullOrWhiteSpace($s)) { continue }
      $s = $s.Trim()
      if ($s.StartsWith('"') -and $s.EndsWith('"') -and $s.Length -ge 2) { $s = $s.Substring(1, $s.Length - 2) }
      if (Test-Path -LiteralPath $s) { return [string]$s }
    }
  } catch {}
  return ''
}

function Get-CreateTargetPathFromClipboardOrExplorer {
  param([switch]$PreferForegroundExplorer)
  try {
    # 1) Clipboard text fallback (supports manually copied "Object name" path)
    $clipText = ''
    try { $clipText = [string][System.Windows.Forms.Clipboard]::GetText() } catch { $clipText = '' }
    $cp = Get-PathFromLooseText -Text $clipText
    if (-not [string]::IsNullOrWhiteSpace($cp)) { return [string]$cp }
    # 2) Explorer selection fallback
    $fg = [IntPtr]::Zero
    if ($PreferForegroundExplorer) {
      try { $fg = [HotkeyNative]::GetForegroundWindow() } catch { $fg = [IntPtr]::Zero }
    }
    $sh = New-Object -ComObject Shell.Application
    $wins = @($sh.Windows())
    $passes = @($true, $false)
    foreach ($passPrefer in $passes) {
      foreach ($w in $wins) {
        try {
          if (-not $w) { continue }
          $full = ''
          try { $full = [string]$w.FullName } catch { $full = '' }
          if ([string]::IsNullOrWhiteSpace($full)) { continue }
          $leaf = ''
          try { $leaf = [System.IO.Path]::GetFileName($full) } catch { $leaf = $full }
          if ([string]::IsNullOrWhiteSpace($leaf) -or $leaf.ToLowerInvariant() -ne 'explorer.exe') { continue }
          $wh = [IntPtr]::Zero
          try { $wh = [IntPtr]([int64]$w.HWND) } catch { $wh = [IntPtr]::Zero }
          if ($passPrefer -and $PreferForegroundExplorer -and $fg -ne [IntPtr]::Zero -and $wh -ne $fg) { continue }
          $doc = $null
          try { $doc = $w.Document } catch { $doc = $null }
          if (-not $doc) { continue }
          $sel = @()
          try { $sel = @($doc.SelectedItems()) } catch { $sel = @() }
          foreach ($it in $sel) {
            $p = ''
            try { $p = [string]$it.Path } catch { $p = '' }
            if (-not [string]::IsNullOrWhiteSpace($p) -and (Test-Path -LiteralPath $p)) { return [string]$p }
          }
          # If foreground Explorer has no selection, use current folder path.
          if ($passPrefer -and $PreferForegroundExplorer) {
            $fp = ''
            try { $fp = [string]$doc.Folder.Self.Path } catch { $fp = '' }
            if (-not [string]::IsNullOrWhiteSpace($fp) -and (Test-Path -LiteralPath $fp)) { return [string]$fp }
          }
        } catch {}
      }
    }
  } catch {}
  return ''
}

function Write-CreateTargetDropDiag {
  param([string]$Message)
  try {
    $log = Join-Path $PSScriptRoot 'StartMenuTool.dropbridge.log'
    $ts = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss.fff')
    Add-Content -LiteralPath $log -Value ("[{0}] {1}" -f $ts, [string]$Message) -Encoding UTF8
  } catch {}
}

function Resolve-CreateTargetDropBrokerHelperPath {
  param([string]$HelperFileName = 'CreateTargetDropBroker.ps1')
  $dirs = New-Object 'System.Collections.Generic.List[string]'
  $seen = @{}
  function Add-DirCandidate {
    param([string]$DirPath)
    if ([string]::IsNullOrWhiteSpace($DirPath)) { return }
    $full = $DirPath
    try { $full = [System.IO.Path]::GetFullPath($DirPath) } catch {}
    $k = ([string]$full).ToLowerInvariant()
    if ($seen.ContainsKey($k)) { return }
    $seen[$k] = $true
    [void]$dirs.Add([string]$full)
  }
  try { Add-DirCandidate -DirPath $PSScriptRoot } catch {}
  try {
    if ($PSCommandPath) {
      Add-DirCandidate -DirPath (Split-Path -Parent $PSCommandPath)
    }
  } catch {}
  try {
    if ($MyInvocation -and $MyInvocation.MyCommand -and $MyInvocation.MyCommand.Path) {
      Add-DirCandidate -DirPath (Split-Path -Parent $MyInvocation.MyCommand.Path)
    }
  } catch {}
  try { Add-DirCandidate -DirPath ((Get-Location).Path) } catch {}
  # Handle both folder naming variants: "StartMenuTool" and "StartMenu Tool"
  $seedDirs = @($dirs.ToArray())
  foreach ($d in $seedDirs) {
    if ([string]::IsNullOrWhiteSpace($d)) { continue }
    if ($d -match '\\StartMenu Tool(\\|$)') {
      try { Add-DirCandidate -DirPath ($d -replace '\\StartMenu Tool(\\|$)', '\StartMenuTool$1') } catch {}
    }
    if ($d -match '\\StartMenuTool(\\|$)') {
      try { Add-DirCandidate -DirPath ($d -replace '\\StartMenuTool(\\|$)', '\StartMenu Tool$1') } catch {}
    }
  }
  foreach ($d in $dirs) {
    try {
      $p = Join-Path -Path $d -ChildPath $HelperFileName
      if (Test-Path -LiteralPath $p -PathType Leaf) { return [string]$p }
    } catch {}
  }
  try { return [string](Join-Path $PSScriptRoot $HelperFileName) } catch { return [string]$HelperFileName }
}

function Get-CreateTargetDropBrokerHelperTemplate {
  @'
param(
  [Parameter(Mandatory=$true)][string]$ExchangeFile,
  [Parameter(Mandatory=$true)][string]$SessionToken,
  [Parameter(Mandatory=$true)][int]$AppPid
)

Set-StrictMode -Version Latest
Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase | Out-Null

function Test-AppAlive {
  try {
    if ($AppPid -le 0) { return $false }
    return [bool](Get-Process -Id $AppPid -ErrorAction SilentlyContinue)
  } catch { return $false }
}

function Get-FirstDroppedPath {
  param($Data)
  try {
    if (-not $Data) { return '' }
    if ($Data.GetDataPresent([System.Windows.DataFormats]::FileDrop)) {
      foreach ($v in @($Data.GetData([System.Windows.DataFormats]::FileDrop))) {
        $p = [string]$v
        if (-not [string]::IsNullOrWhiteSpace($p) -and (Test-Path -LiteralPath $p)) { return $p }
      }
    }
    foreach ($fmt in @('FileNameW','FileName',[System.Windows.DataFormats]::UnicodeText,[System.Windows.DataFormats]::Text,[System.Windows.DataFormats]::StringFormat)) {
      try {
        if (-not $Data.GetDataPresent($fmt)) { continue }
        $val = $Data.GetData($fmt)
        foreach ($line in @(([string]$val) -split "`r?`n")) {
          $p = [string]$line
          if ([string]::IsNullOrWhiteSpace($p)) { continue }
          $p = $p.Trim([char[]]@(0x20,0x09,0x0D,0x0A))
          if ($p.StartsWith('"') -and $p.EndsWith('"') -and $p.Length -ge 2) { $p = $p.Substring(1, $p.Length - 2) }
          if (Test-Path -LiteralPath $p) { return $p }
        }
      } catch {}
    }
  } catch {}
  return ''
}

function Publish-DroppedPath {
  param([string]$Path)
  try {
    if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)) { return }
    $seq = 0
    try {
      if (Test-Path -LiteralPath $ExchangeFile -PathType Leaf) {
        $obj = Get-Content -LiteralPath $ExchangeFile -Raw | ConvertFrom-Json -ErrorAction Stop
        try { $seq = [int]$obj.seq } catch { $seq = 0 }
      }
    } catch { $seq = 0 }
    $seq++
    [pscustomobject]@{
      session = $SessionToken
      appPid  = $AppPid
      seq     = $seq
      path    = [string]$Path
      ts      = (Get-Date).ToString('o')
    } | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $ExchangeFile -Encoding UTF8
  } catch {}
}

if (-not (Test-AppAlive)) { exit 0 }

[xml]$xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Path Drop Broker"
        Width="420" Height="98"
        WindowStartupLocation="CenterScreen"
        ResizeMode="NoResize"
        Topmost="True"
        ShowInTaskbar="True"
        Background="#F0F0F0">
  <Border Margin="8" CornerRadius="6" BorderThickness="1" BorderBrush="#B0B0B0" Background="#FAFAFA" AllowDrop="True" Name="DropHost">
    <Grid>
      <TextBlock Name="HintText"
                 Text="Drop file or folder here to set Create Shortcut target path"
                 Margin="10"
                 VerticalAlignment="Center"
                 TextWrapping="Wrap"
                 Foreground="#202020"/>
    </Grid>
  </Border>
</Window>
"@

$reader = New-Object System.Xml.XmlNodeReader $xaml
$w = [Windows.Markup.XamlReader]::Load($reader)
$host = $w.FindName('DropHost')
$hint = $w.FindName('HintText')

$over = {
  param($s,$e)
  try {
    $p = Get-FirstDroppedPath -Data $e.Data
    if (-not [string]::IsNullOrWhiteSpace($p)) {
      $e.Effects = [System.Windows.DragDropEffects]::Copy
      if ($hint) { $hint.Text = ("Release to set path:`n" + [string]$p) }
    } else {
      $e.Effects = [System.Windows.DragDropEffects]::None
      if ($hint) { $hint.Text = "Drop file or folder here to set Create Shortcut target path" }
    }
    $e.Handled = $true
  } catch {}
}

$drop = {
  param($s,$e)
  try {
    $p = Get-FirstDroppedPath -Data $e.Data
    if (-not [string]::IsNullOrWhiteSpace($p)) {
      Publish-DroppedPath -Path $p
      if ($hint) { $hint.Text = ("Path sent:`n" + [string]$p) }
    }
    $e.Handled = $true
  } catch {}
}

if ($host) {
  $host.Add_PreviewDragOver($over)
  $host.Add_Drop($drop)
}
$w.Add_PreviewDragOver($over)
$w.Add_Drop($drop)

$tm = New-Object System.Windows.Threading.DispatcherTimer
$tm.Interval = [TimeSpan]::FromSeconds(1)
$tm.Add_Tick({
  try {
    if (-not (Test-AppAlive)) {
      try { $tm.Stop() } catch {}
      try { $w.Close() } catch {}
    }
  } catch {}
})
$tm.Start()

[void]$w.ShowDialog()
'@
}

function Ensure-CreateTargetDropBrokerHelper {
  param(
    [string]$PreferredPath,
    [string]$HelperFileName = 'CreateTargetDropBroker.ps1'
  )
  try {
    if (-not [string]::IsNullOrWhiteSpace($PreferredPath) -and (Test-Path -LiteralPath $PreferredPath -PathType Leaf)) {
      return [string]$PreferredPath
    }
    $desktop = ''
    try { $desktop = [Environment]::GetFolderPath('Desktop') } catch { $desktop = '' }
    $candidateFiles = @()
    try { $candidateFiles += (Join-Path $PSScriptRoot $HelperFileName) } catch {}
    if (-not [string]::IsNullOrWhiteSpace($desktop)) {
      try { $candidateFiles += (Join-Path (Join-Path $desktop 'StartMenu Tool') $HelperFileName) } catch {}
      try { $candidateFiles += (Join-Path (Join-Path $desktop 'StartMenuTool') $HelperFileName) } catch {}
    }
    try { if ($PSCommandPath) { $candidateFiles += (Join-Path (Split-Path -Parent $PSCommandPath) $HelperFileName) } } catch {}
    try { $candidateFiles += (Join-Path ((Get-Location).Path) $HelperFileName) } catch {}
    $source = ''
    foreach ($f in @($candidateFiles | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Select-Object -Unique)) {
      try {
        if (Test-Path -LiteralPath $f -PathType Leaf) { $source = [string]$f; break }
      } catch {}
    }
    if ([string]::IsNullOrWhiteSpace($PreferredPath)) {
      try { $PreferredPath = Join-Path $PSScriptRoot $HelperFileName } catch { $PreferredPath = $HelperFileName }
    }
    if (-not [string]::IsNullOrWhiteSpace($source) -and -not [string]::Equals($source, $PreferredPath, [System.StringComparison]::OrdinalIgnoreCase)) {
      try {
        Copy-Item -LiteralPath $source -Destination $PreferredPath -Force
      } catch {}
    }
    if (Test-Path -LiteralPath $PreferredPath -PathType Leaf) { return [string]$PreferredPath }
    # Last resort: create helper script in place.
    $tpl = Get-CreateTargetDropBrokerHelperTemplate
    if (-not [string]::IsNullOrWhiteSpace($tpl)) {
      try { Set-Content -LiteralPath $PreferredPath -Value $tpl -Encoding UTF8 -Force } catch {}
    }
    if (Test-Path -LiteralPath $PreferredPath -PathType Leaf) { return [string]$PreferredPath }
  } catch {}
  return ''
}

function Start-CreateTargetDropBroker {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Window]$Window,
    [Parameter(Mandatory=$true)]$TargetBox
  )
  try {
    if (-not $Window -or -not $TargetBox) { return $false }
    if (-not (Test-IsElevated)) { return $false } # broker only needed for elevated app
    $alreadyStarted = $false
    try { $alreadyStarted = [bool]$script:CreateTargetDropBrokerStarted } catch { $alreadyStarted = $false }
    if ($alreadyStarted) { return $true }
    $helperPath = Resolve-CreateTargetDropBrokerHelperPath -HelperFileName 'CreateTargetDropBroker.ps1'
    $helperPath = Ensure-CreateTargetDropBrokerHelper -PreferredPath $helperPath -HelperFileName 'CreateTargetDropBroker.ps1'
    if (-not (Test-Path -LiteralPath $helperPath -PathType Leaf)) {
      Write-CreateTargetDropDiag ("Broker helper not found: " + [string]$helperPath)
      return $false
    }
    Write-CreateTargetDropDiag ("Broker helper resolved: " + [string]$helperPath)
    $session = [Guid]::NewGuid().ToString('N')
    $exchange = Join-Path $env:TEMP ("StartMenuTool.DropBroker.{0}.json" -f $session)
    $init = [pscustomobject]@{
      session = $session
      appPid  = $PID
      seq     = 0
      path    = ''
      ts      = (Get-Date).ToString('o')
    }
    $init | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $exchange -Encoding UTF8
    $psExe = Join-Path $PSHOME 'powershell.exe'
    if (-not (Test-Path -LiteralPath $psExe -PathType Leaf)) { $psExe = 'powershell.exe' }
    $argLine = ('-NoProfile -ExecutionPolicy Bypass -File "{0}" -ExchangeFile "{1}" -SessionToken "{2}" -AppPid {3}' -f [string]$helperPath, [string]$exchange, [string]$session, [int]$PID)
    # Launch via shell so broker runs unelevated under explorer context.
    $sh = New-Object -ComObject Shell.Application
    $helperDir = $PSScriptRoot
    try {
      $helperDirCandidate = Split-Path -Parent $helperPath
      if (-not [string]::IsNullOrWhiteSpace($helperDirCandidate)) { $helperDir = $helperDirCandidate }
    } catch {}
    $sh.ShellExecute($psExe, $argLine, $helperDir, 'open', 1)
    $script:CreateTargetDropBrokerExchange = [string]$exchange
    $script:CreateTargetDropBrokerSession = [string]$session
    $script:CreateTargetDropBrokerLastSeq = 0
    $script:CreateTargetDropBrokerStarted = $true
    Write-CreateTargetDropDiag ("Broker launched. exchange=" + [string]$exchange)
    if (-not ($script:CreateTargetDropBrokerPollTimer -and ($script:CreateTargetDropBrokerPollTimer -is [System.Windows.Threading.DispatcherTimer]))) {
      $tm = New-Object System.Windows.Threading.DispatcherTimer
      $tm.Interval = [TimeSpan]::FromMilliseconds(250)
      $tm.Add_Tick({
        try {
          $xf = ''
          try { $xf = [string]$script:CreateTargetDropBrokerExchange } catch { $xf = '' }
          if ([string]::IsNullOrWhiteSpace($xf) -or -not (Test-Path -LiteralPath $xf -PathType Leaf)) { return }
          $raw = ''
          try { $raw = [string](Get-Content -LiteralPath $xf -Raw -ErrorAction Stop) } catch { return }
          if ([string]::IsNullOrWhiteSpace($raw)) { return }
          $obj = $null
          try { $obj = $raw | ConvertFrom-Json -ErrorAction Stop } catch { return }
          if (-not $obj) { return }
          $sess = ''
          try { $sess = [string]$obj.session } catch { $sess = '' }
          if ([string]::IsNullOrWhiteSpace($sess) -or $sess -ne [string]$script:CreateTargetDropBrokerSession) { return }
          $seq = 0
          try { $seq = [int]$obj.seq } catch { $seq = 0 }
          $last = 0
          try { $last = [int]$script:CreateTargetDropBrokerLastSeq } catch { $last = 0 }
          if ($seq -le $last) { return }
          $script:CreateTargetDropBrokerLastSeq = $seq
          $p = ''
          try { $p = [string]$obj.path } catch { $p = '' }
          if ([string]::IsNullOrWhiteSpace($p)) { return }
          if (-not (Test-Path -LiteralPath $p)) { return }
          if (-not $createTargetBox -or -not [bool]$createTargetBox.IsEnabled) { return }
          $modeNow = ''
          try { $modeNow = [string]$script:CreatePanelMode } catch { $modeNow = '' }
          if ($modeNow -ne 'Shortcut' -and $modeNow -ne 'EditSelected') { return }
          Apply-CreateShortcutTargetSelection -PickedPath $p
          Write-CreateTargetDropDiag ("Broker path applied seq=" + [string]$seq + " path=" + [string]$p)
        } catch {}
      })
      $script:CreateTargetDropBrokerPollTimer = $tm
    }
    try { $script:CreateTargetDropBrokerPollTimer.Start() } catch {}
    return $true
  } catch {
    Write-CreateTargetDropDiag ("Broker launch error: " + [string]$_.Exception.Message)
    return $false
  }
}

function Enable-CreateTargetExternalDropBridge {
  param(
    [Parameter(Mandatory=$true)][System.Windows.Window]$Window,
    [Parameter(Mandatory=$true)]$TargetBox
  )
  try {
    if (-not $Window -or -not $TargetBox) { return $false }
    if ($script:CreateTargetDropBridgeInstalled) { return $true }
    $hwnd = [IntPtr]::Zero
    try { $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper($Window)).Handle } catch { $hwnd = [IntPtr]::Zero }
    if ($hwnd -eq [IntPtr]::Zero) { return $false }
    # Allow legacy shell drop messages into elevated window (UIPI-compatible path bridge).
    try { [DragDropUipiNative]::DragAcceptFiles($hwnd, $true) } catch {}
    Write-CreateTargetDropDiag ("WM bridge init hwnd=" + [string]$hwnd.ToInt64())
    try {
      $cfs = New-Object DragDropUipiNative+CHANGEFILTERSTRUCT
      $cfs.cbSize = [uint32][Runtime.InteropServices.Marshal]::SizeOf([type]'DragDropUipiNative+CHANGEFILTERSTRUCT')
      [void][DragDropUipiNative]::ChangeWindowMessageFilterEx($hwnd, 0x0233, 1, [ref]$cfs) # WM_DROPFILES
      [void][DragDropUipiNative]::ChangeWindowMessageFilterEx($hwnd, 0x0049, 1, [ref]$cfs) # WM_COPYGLOBALDATA
      [void][DragDropUipiNative]::ChangeWindowMessageFilterEx($hwnd, 0x004A, 1, [ref]$cfs) # WM_COPYDATA
      Write-CreateTargetDropDiag "WM bridge filter registration attempted"
    } catch {}
    $src = $null
    try { $src = [System.Windows.Interop.HwndSource]::FromHwnd($hwnd) } catch { $src = $null }
    if (-not $src) { return $false }
    $script:CreateTargetDropBridgeHook = [System.Windows.Interop.HwndSourceHook]{
      param([IntPtr]$hWnd, [int]$msg, [IntPtr]$wParam, [IntPtr]$lParam, [ref]$handled)
      try {
        if ($msg -ne 0x0233) { return [IntPtr]::Zero } # WM_DROPFILES
        Write-CreateTargetDropDiag "WM_DROPFILES received"
        $picked = ''
        try {
          $count = [uint32]0
          try { $count = [uint32]([DragDropUipiNative]::DragQueryFile($wParam, [uint32]0xFFFFFFFF, $null, [uint32]0)) } catch { $count = 0 }
          if ($count -gt 0) {
            $len = [uint32]0
            try { $len = [uint32]([DragDropUipiNative]::DragQueryFile($wParam, [uint32]0, $null, [uint32]0)) } catch { $len = 0 }
            if ($len -gt 0) {
              $sb = New-Object System.Text.StringBuilder([int]$len + 2)
              [void][DragDropUipiNative]::DragQueryFile($wParam, [uint32]0, $sb, [uint32]$sb.Capacity)
              $cand = [string]$sb.ToString()
              if (-not [string]::IsNullOrWhiteSpace($cand) -and (Test-Path -LiteralPath $cand)) {
                $picked = [string]$cand
                Write-CreateTargetDropDiag ("WM_DROPFILES extracted path: " + [string]$picked)
              }
            }
          }
        } catch {}
        finally {
          try { [DragDropUipiNative]::DragFinish($wParam) } catch {}
        }
        if (-not [string]::IsNullOrWhiteSpace($picked)) {
          try { $script:CreateTargetDropBridgePickedPath = [string]$picked } catch {}
          try {
            $null = $window.Dispatcher.BeginInvoke([Action]{
              try {
                if (-not $createTargetBox -or -not [bool]$createTargetBox.IsEnabled) { return }
                $modeNow = ''
                try { $modeNow = [string]$script:CreatePanelMode } catch { $modeNow = '' }
                if ($modeNow -ne 'Shortcut' -and $modeNow -ne 'EditSelected') { return }
                $pp = ''
                try { $pp = [string]$script:CreateTargetDropBridgePickedPath } catch { $pp = '' }
                if ([string]::IsNullOrWhiteSpace($pp) -or -not (Test-Path -LiteralPath $pp)) { return }
                Apply-CreateShortcutTargetSelection -PickedPath $pp
                Write-CreateTargetDropDiag ("WM bridge path applied: " + [string]$pp)
              } catch {}
            }, [System.Windows.Threading.DispatcherPriority]::Input)
          } catch {}
        }
        $handled.Value = $true
      } catch {}
      return [IntPtr]::Zero
    }
    try { $src.AddHook($script:CreateTargetDropBridgeHook) } catch { return $false }
    $script:CreateTargetDropBridgeInstalled = $true
    return $true
  } catch {
    return $false
  }
}

if ($createTargetBrowseFileBtn) {
  $createTargetBrowseFileBtn.Add_Click({
    try {
      $dlg = New-Object System.Windows.Forms.OpenFileDialog
      $dlg.Title = "Select shortcut target file"
      $dlg.Filter = "All files (*.*)|*.*|Programs and files (*.exe;*.cmd;*.bat;*.com;*.msc;*.lnk)|*.exe;*.cmd;*.bat;*.com;*.msc;*.lnk"
      $dlg.Multiselect = $false
      $dlg.CheckFileExists = $true
      $dr = $dlg.ShowDialog()
      if ($dr -eq [System.Windows.Forms.DialogResult]::OK) {
        Apply-CreateShortcutTargetSelection -PickedPath ([string]$dlg.FileName)
      }
    } catch {}
  })
}

if ($createTargetBrowseFolderBtn) {
  $createTargetBrowseFolderBtn.Add_Click({
    try {
      $seed = ''
      try { $seed = [string]$createTargetBox.Text } catch { $seed = '' }
      if ([string]::IsNullOrWhiteSpace($seed)) {
        try { $seed = [string]$scopeRoots['CurrentUser'] } catch { $seed = '' }
      }
      $pickedFolder = Select-FolderDialog -Title "Select shortcut target folder" -InitialPath $seed -SuggestedName "[Select Folder]" -StrictFolderPicker
      if (-not [string]::IsNullOrWhiteSpace([string]$pickedFolder)) {
        Apply-CreateShortcutTargetSelection -PickedPath ([string]$pickedFolder)
      }
    } catch {}
  })
}

if ($createTargetBox) {
  $createTargetBox.Add_PreviewDragOver({
    param($sender, $e)
    try {
      $modeNow = ''
      try { $modeNow = [string]$script:CreatePanelMode } catch { $modeNow = '' }
      if ($modeNow -ne 'Shortcut' -and $modeNow -ne 'EditSelected') {
        $e.Effects = [System.Windows.DragDropEffects]::None
        $e.Handled = $true
        return
      }
      if ($modeNow -eq 'EditSelected') {
        $rows = @()
        try { $rows = @(Get-CreateEditSelectionRows) } catch { $rows = @() }
        if ($rows.Count -ne 1 -or -not (Test-IsIconChangeEligibleRow -Row $rows[0])) {
          $e.Effects = [System.Windows.DragDropEffects]::None
          $e.Handled = $true
          return
        }
      }
      if ($e.Data.GetDataPresent([System.Windows.DataFormats]::FileDrop)) {
        $arr = @($e.Data.GetData([System.Windows.DataFormats]::FileDrop))
        $p = ''
        if ($arr.Count -gt 0) { $p = [string]$arr[0] }
        if (-not [string]::IsNullOrWhiteSpace($p) -and (Test-Path -LiteralPath $p)) {
          $e.Effects = [System.Windows.DragDropEffects]::Copy
        } else {
          $e.Effects = [System.Windows.DragDropEffects]::None
        }
      } else {
        # Elevated drag can be blocked by UIPI on newer Windows builds; allow drop cue if fallback is available.
        $fallback = ''
        try { $fallback = Get-CreateTargetPathFromClipboardOrExplorer -PreferForegroundExplorer } catch { $fallback = '' }
        if (-not [string]::IsNullOrWhiteSpace($fallback) -and (Test-Path -LiteralPath $fallback)) {
          $e.Effects = [System.Windows.DragDropEffects]::Copy
        } else {
          $e.Effects = [System.Windows.DragDropEffects]::None
        }
      }
      $e.Handled = $true
    } catch {}
  })

  $createTargetBox.Add_Drop({
    param($sender, $e)
    try {
      $modeNow = ''
      try { $modeNow = [string]$script:CreatePanelMode } catch { $modeNow = '' }
      if ($modeNow -ne 'Shortcut' -and $modeNow -ne 'EditSelected') { return }
      if ($modeNow -eq 'EditSelected') {
        $rows = @()
        try { $rows = @(Get-CreateEditSelectionRows) } catch { $rows = @() }
        if ($rows.Count -ne 1 -or -not (Test-IsIconChangeEligibleRow -Row $rows[0])) { return }
      }
      $p = ''
      if ($e.Data.GetDataPresent([System.Windows.DataFormats]::FileDrop)) {
        $arr = @($e.Data.GetData([System.Windows.DataFormats]::FileDrop))
        if ($arr.Count -gt 0) { $p = [string]$arr[0] }
      }
      if ([string]::IsNullOrWhiteSpace($p) -or -not (Test-Path -LiteralPath $p)) {
        try { $p = Get-CreateTargetPathFromClipboardOrExplorer -PreferForegroundExplorer } catch { $p = '' }
      }
      if ([string]::IsNullOrWhiteSpace($p) -or -not (Test-Path -LiteralPath $p)) { return }
      Apply-CreateShortcutTargetSelection -PickedPath $p
      $e.Handled = $true
    } catch {}
  })

  $createTargetBox.Add_LostFocus({
    try { [void](Invoke-CommitEditSelectedTargetFromPanel -Reason 'EditPanelTargetLostFocus') } catch {}
  })

  $createTargetBox.Add_PreviewKeyDown({
    param($s,$e)
    try {
      if ($e.Key -ne [System.Windows.Input.Key]::Enter) { return }
      $mode = ''
      try { $mode = [string]$script:CreatePanelMode } catch { $mode = '' }
      if ($mode -ne 'EditSelected') { return }
      $e.Handled = $true
      [void](Invoke-CommitEditSelectedTargetFromPanel -Reason 'EditPanelTargetEnter' -Interactive)
    } catch {}
  })
}

try {
  [void](Enable-CreateTargetExternalDropBridge -Window $window -TargetBox $createTargetBox)
  $window.Add_SourceInitialized({
    try { [void](Enable-CreateTargetExternalDropBridge -Window $window -TargetBox $createTargetBox) } catch {}
  })
  $window.Add_ContentRendered({
    try { [void](Enable-CreateTargetExternalDropBridge -Window $window -TargetBox $createTargetBox) } catch {}
  })
} catch {}

if ($createCustomIconBrowseBtn) {
  $createCustomIconBrowseBtn.Add_Click({
    try {
      $dlg = New-Object System.Windows.Forms.OpenFileDialog
      $dlg.Title = "Select custom icon source"
      $dlg.Filter = "Icon sources (*.ico;*.exe;*.dll)|*.ico;*.exe;*.dll|All files (*.*)|*.*"
      $dlg.Multiselect = $false
      $dlg.CheckFileExists = $true
      $dr = $dlg.ShowDialog()
      if ($dr -eq [System.Windows.Forms.DialogResult]::OK) {
        $p = [string]$dlg.FileName
        $createCustomIconPathBox.Text = $p
        $img = Get-ImageSourceFromIcon -IconPath $p -IconIndex 0 -FallbackExePath $p
        if ($img) {
          Set-CreateSelectedIcon -IconPath $p -IconIndex 0 -Image $img -Label ([System.IO.Path]::GetFileName($p) + ',0')
          if ($script:ChangeIconPanelModeActive) {
            [void](Invoke-ApplyIconChangeFromPanel -IconPath $p -IconIndex 0 -IconImage $img)
          }
        }
      }
    } catch {}
  })
}

if ($createQueueBtn) {
  $createQueueBtn.Add_Click({
    try {
      $mode = 'Folder'
      try { $mode = [string]$script:CreatePanelMode } catch { $mode = 'Folder' }

      if ($mode -eq 'EditSelected') {
        [void](Invoke-CommitEditSelectedRenameFromPanel -Reason 'EditPanelButton' -Interactive)
        return
      }

      $kind = if ($mode -eq 'Shortcut') { 'Shortcut' } else { 'Folder' }

      $nm = ''
      try { $nm = [string]$createNameBox.Text } catch {}
      $nm = (Trim-NameInputPreserveNbsp -Text $nm)
      if (-not (Test-ValidFileName -Name $nm)) {
        [System.Windows.MessageBox]::Show("Enter a valid name.", "Create Shortcut") | Out-Null
        return
      }

      $root = [string]$scopeRoots['CurrentUser']
      if ([string]::IsNullOrWhiteSpace($root)) {
        [System.Windows.MessageBox]::Show("CurrentUser Start Menu root was not found.", "Create Shortcut") | Out-Null
        return
      }

      $target = ''
      if ($kind -eq 'Shortcut') {
        try { $target = [string]$createTargetBox.Text } catch {}
        $target = (Normalize-Path $target)
        if ([string]::IsNullOrWhiteSpace($target) -or -not (Test-Path -LiteralPath $target)) {
          [System.Windows.MessageBox]::Show("Select a valid shortcut target path.", "Create Shortcut") | Out-Null
          return
        }
      }

      $dest = if ($kind -eq 'Folder') { Join-Path $root $nm } else { Join-Path $root ($nm + '.lnk') }
      if ((Test-Path -LiteralPath $dest) -or (Test-PendingCreatePathExists -Path $dest)) {
        [System.Windows.MessageBox]::Show("An item with that destination already exists (or is already pending). Choose a different name.", "Create Shortcut") | Out-Null
        return
      }

      $iconPath = ''
      $iconIndex = 0
      $iconImage = $null
      if ($kind -eq 'Shortcut') {
        $iconPath = [string]$script:CreateSelectedIconPath
        $iconIndex = [int]$script:CreateSelectedIconIndex
        $iconImage = $script:CreateSelectedIconImage
        $targetIsFolder = $false
        try { $targetIsFolder = (Test-Path -LiteralPath $target -PathType Container) } catch { $targetIsFolder = $false }
        if ($targetIsFolder) {
          # Folder-target shortcuts should default to the configured folder icon spec,
          # not to the target path icon location.
          if ([string]::IsNullOrWhiteSpace($iconPath) -or [string]::Equals((Normalize-Path $iconPath), (Normalize-Path $target), [System.StringComparison]::OrdinalIgnoreCase)) {
            try {
              $folderSpec = Get-DefaultFolderIconLocationSpec
              if ($folderSpec -and -not [string]::IsNullOrWhiteSpace([string]$folderSpec.IconPath)) {
                $iconPath = [string]$folderSpec.IconPath
                try { $iconIndex = [int]$folderSpec.IconIndex } catch { $iconIndex = 0 }
              }
            } catch {}
          }
        } elseif ([string]::IsNullOrWhiteSpace($iconPath)) {
          $iconPath = [string]$target
          $iconIndex = 0
        }
        if (-not $iconImage -and -not [string]::IsNullOrWhiteSpace($iconPath)) {
          try { $iconImage = Get-ImageSourceFromIcon -IconPath $iconPath -IconIndex $iconIndex -FallbackExePath $iconPath } catch { $iconImage = $null }
        }
      }

      $row = New-PendingCreateGridRow -Kind $kind -Name $nm -DestPath $dest -TargetPath $target -IconPath $iconPath -IconIndex $iconIndex -IconImage $iconImage
      Add-PendingCreateRow -Row $row

      try { $row.Selected = $false } catch {}
      if ($kind -eq 'Shortcut') {
        try { $script:CreateShortcutDraftName = '' } catch {}
      } else {
        try { $script:CreateFolderDraftName = '' } catch {}
      }
      try { Set-CreateNameBoxTextSafe -Text '' } catch {}
      if ($kind -eq 'Shortcut') {
        try { $createTargetBox.Text = '' } catch {}
        try { if ($createCustomIconPathBox) { $createCustomIconPathBox.Text = '' } } catch {}
        try { Set-CreateSelectedIcon -IconPath '' -IconIndex 0 -Image $null -Label '(none)' } catch {}
      }
      try {
        if ($grid) {
          $grid.UnselectAll()
          $grid.SelectedItem = $null
          $grid.CurrentCell = [System.Windows.Controls.DataGridCellInfo]::new()
        }
      } catch {}
      try {
        if ($window) {
          $null = $window.Dispatcher.BeginInvoke(
            [Action]{
              try {
                if ($grid) {
                  $grid.UnselectAll()
                  $grid.SelectedItem = $null
                  $grid.CurrentCell = [System.Windows.Controls.DataGridCellInfo]::new()
                }
                if ($createNameBox) { $createNameBox.Focus() | Out-Null }
              } catch {}
            },
            [System.Windows.Threading.DispatcherPriority]::Background
          )
        }
      } catch {}
      try { Queue-RebuildVisibleRows } catch {}
      try { Refresh-UIAsync } catch {}
    } catch {
      [System.Windows.MessageBox]::Show([string]$_.Exception.Message, "Create Shortcut Error") | Out-Null
    }
  })
}

