}
# Selection checkbox cascade (folders -> descendant items)
# ==============================================================================
$grid.AddHandler(
  [System.Windows.Controls.Primitives.ToggleButton]::ClickEvent,
  [System.Windows.RoutedEventHandler]{
    param($s, $e)

    $chk = $e.OriginalSource -as [System.Windows.Controls.Primitives.ToggleButton]
    if (-not $chk) { return }

    # Only handle the SELECT checkbox
    if ([string]$chk.Tag -ne 'SelectCascade') { return }

    $row = $chk.DataContext
    if (-not $row) { return }
    if (Test-IsAlphaSeparatorRow -Row $row) {
      try { $row.Selected = $false } catch {}
      try { $chk.IsChecked = $false } catch {}
      $e.Handled = $true
      return
    }

    # Windows Security proxy row is non-actionable; don't allow selection/cascade.
    try {
      $isWinSec = ($row.PSObject.Properties.Match('IsWindowsSecurityProxy').Count -gt 0 -and [bool]$row.IsWindowsSecurityProxy)
      $isSettings = ($row.PSObject.Properties.Match('IsSettingsProxy').Count -gt 0 -and [bool]$row.IsSettingsProxy)
      if (-not $isSettings) {
        try { $isSettings = (Test-IsSettingsAppsFolderRow -Row $row) } catch {}
      }
      if ($isWinSec -or $isSettings) {
        try { $row.Selected = $false } catch {}
        try { $chk.IsChecked = $false } catch {}
        $e.Handled = $true
        return
      }
    } catch {}

    $wantSelected = [bool]$chk.IsChecked

    # Always set the row itself (binding already does this, but keep it explicit)
    try { $row.Selected = $wantSelected } catch {}

    # If it's a folder row, cascade to ALL descendant ITEMS (links)
    $isFolder = $false
    try { $isFolder = ($row.PSObject.Properties.Match('RowKind').Count -gt 0 -and $row.RowKind -eq 'Folder') } catch {}

if ($isFolder) {

  foreach ($f in (Get-DescendantFolderRowsForFolderRow -FolderRow $row)) {
    try { $f.Selected = $wantSelected } catch {}
  }

  foreach ($it in (Get-DescendantItemsForFolderRow -FolderRow $row)) {
    try { $it.Selected = $wantSelected } catch {}
  }
}

    Refresh-UIAsync
    try { Sync-CreateEditSelectedFields } catch {}
    $e.Handled = $true
  },
  $true
)

