# ==============================================================================
# Folder expand/collapse (single click)
# + Right-click starts rename (all rows)
# + Context menu suppressed COMPLETELY (keyboard shortcuts only)
# ==============================================================================

# --- Queue rebuild flag (keep as-is) ---
$script:RebuildQueued = $false

function Queue-RebuildVisibleRows {
  if ($script:RebuildQueued) {
    return
  }
  $script:RebuildQueued = $true
  try {
    $null = $window.Dispatcher.BeginInvoke(
      [Action]{
        try {
          Rebuild-VisibleRows
          try { Ensure-MidGridScrollBarWiring } catch {}
          try { Queue-MidGridScrollBarSync -LayoutUpdate:$true } catch {}
        }
        finally {
          $script:RebuildQueued = $false
          try {
            if ([bool]$script:DuplicateTargetExpandPendingRebuild) {
              $script:DuplicateTargetExpandPendingRebuild = $false
              Queue-RebuildVisibleRows
            }
          } catch {}
        }
      },
      [System.Windows.Threading.DispatcherPriority]::Background
    )
  } catch {
    $script:RebuildQueued = $false
  }
}

# --- Visual ancestor helper (KEEP ONE COPY IN ENTIRE SCRIPT) ---
function Find-VisualAncestor {
  param(
    [Parameter(Mandatory=$true)]$Start,
    [Parameter(Mandatory=$true)][type]$Type
  )
  $cur = $Start
  while ($cur -ne $null) {
    if ($cur -is $Type) { return $cur }
    try { $cur = [System.Windows.Media.VisualTreeHelper]::GetParent($cur) } catch { return $null }
  }
  return $null
}

function Get-GridNameColumn {
  # Prefer stable identifiers over Header text when possible.
  try {
    foreach ($c in $grid.Columns) {
      if (-not $c) { continue }
      $hdr = ""
      try { $hdr = [string]$c.Header } catch {}
      $smp = ""
      try { $smp = [string]$c.SortMemberPath } catch {}
      if ($smp -eq "Name") { return $c }
      if ($hdr -eq "Name") { return $c }
    }
  } catch {}
  return $null
}

function Get-GridColumnByHeader {
  param([string]$Header)
  try {
    if (-not $grid -or [string]::IsNullOrWhiteSpace($Header)) { return $null }
    foreach ($c in @($grid.Columns)) {
      if (-not $c) { continue }
      $h = ''
      try { $h = [string]$c.Header } catch { $h = '' }
      if ($h -eq $Header) { return $c }
    }
  } catch {}
  return $null
}

function Measure-GridTextWidthPx {
  param(
    [string]$Text,
    [double]$FontSizePx = 12.0
  )
  try {
    if ([string]::IsNullOrWhiteSpace([string]$Text)) { return 0.0 }
    $ff = [single]$FontSizePx
    $font = $null
    try { $font = $script:GridTextMeasureFont } catch { $font = $null }
    if (($null -eq $font) -or ([Math]::Abs([double]$font.Size - [double]$ff) -gt 0.01)) {
      try { if ($font) { $font.Dispose() } } catch {}
      $script:GridTextMeasureFont = New-Object System.Drawing.Font('Segoe UI', $ff, [System.Drawing.FontStyle]::Regular, [System.Drawing.GraphicsUnit]::Pixel)
      $font = $script:GridTextMeasureFont
    }
    $flags = [System.Windows.Forms.TextFormatFlags]::NoPadding -bor [System.Windows.Forms.TextFormatFlags]::SingleLine
    $sz = [System.Windows.Forms.TextRenderer]::MeasureText([string]$Text, $font, [System.Drawing.Size]::new(32767, 32767), $flags)
    return [double]$sz.Width
  } catch {
    try { return ([double]([string]$Text).Length * 7.0) } catch { return 0.0 }
  }
}

function Get-GridMaxContentWidthPx {
  param(
    [Parameter(Mandatory=$true)][string]$PropertyName,
    [double]$FontSizePx = 12.0
  )
  $maxW = 0.0
  try {
    $rows = @()
    try { $rows = @($script:VisibleRows) } catch { $rows = @() }
    if ($rows.Count -le 0) {
      try { $rows = @($grid.ItemsSource) } catch { $rows = @() }
    }
    foreach ($r in @($rows)) {
      if (-not $r) { continue }
      try { if (Test-IsAlphaSeparatorRow -Row $r) { continue } } catch {}
      $txt = ''
      try { $txt = [string](Get-PropString -Obj $r -Names @($PropertyName) -Fallback '') } catch { $txt = '' }
      if ([string]::IsNullOrWhiteSpace($txt)) { continue }
      $w = 0.0
      try { $w = Measure-GridTextWidthPx -Text $txt -FontSizePx $FontSizePx } catch { $w = 0.0 }
      if ($w -gt $maxW) { $maxW = [double]$w }
    }
  } catch {}
  return [double]$maxW
}

function Apply-GridColumnWidthConstraints {
  param([switch]$RecomputeContentMax)
  try {
    if (-not $grid) { return }
    $fixedW = 55.0
    $minTargetPath = 100.0
    $textPad = 28.0
    $layoutPad = 24.0
    try { $fixedW = [double]$script:GridPendingTypeFixedWidthPx } catch { $fixedW = 55.0 }
    try { $minTargetPath = [double]$script:GridTargetPathMinWidthPx } catch { $minTargetPath = 100.0 }
    try { $textPad = [double]$script:GridTargetPathTextPaddingPx } catch { $textPad = 28.0 }
    if ($fixedW -lt 20.0) { $fixedW = 20.0 }
    if ($minTargetPath -lt 50.0) { $minTargetPath = 50.0 }
    if ($textPad -lt 0.0) { $textPad = 0.0 }
    $selectCol = Get-GridColumnByHeader -Header 'Select'
    $nameCol = Get-GridColumnByHeader -Header 'Name'
    $pendingCol = Get-GridColumnByHeader -Header 'Pending'
    $typeCol = Get-GridColumnByHeader -Header 'Type'
    $targetCol = Get-GridColumnByHeader -Header 'Target'
    $pathCol = Get-GridColumnByHeader -Header 'Path'
    if (-not $targetCol -or -not $pathCol) { return }
    foreach ($c in @($pendingCol, $typeCol)) {
      if (-not $c) { continue }
      try { $c.CanUserResize = $false } catch {}
      try { $c.MinWidth = [double]$fixedW } catch {}
      try { $c.MaxWidth = [double]$fixedW } catch {}
      try { $c.Width = [System.Windows.Controls.DataGridLength]::new([double]$fixedW, [System.Windows.Controls.DataGridLengthUnitType]::Pixel) } catch {}
    }
    $targetMax = 0.0
    $pathMax = 0.0
    try { $targetMax = [double]$script:GridTargetMaxAllowedPx } catch { $targetMax = 0.0 }
    try { $pathMax = [double]$script:GridPathMaxAllowedPx } catch { $pathMax = 0.0 }
    if ($RecomputeContentMax -or $targetMax -le 0.0) {
      $m = 0.0
      try { $m = Get-GridMaxContentWidthPx -PropertyName 'Target' -FontSizePx 12.0 } catch { $m = 0.0 }
      $targetMax = [double]$m + [double]$textPad
      if ($targetMax -lt $minTargetPath) { $targetMax = $minTargetPath }
      try { $script:GridTargetMaxAllowedPx = [double]$targetMax } catch {}
    }
    if ($RecomputeContentMax -or $pathMax -le 0.0) {
      $m = 0.0
      try { $m = Get-GridMaxContentWidthPx -PropertyName 'Path' -FontSizePx 12.0 } catch { $m = 0.0 }
      $pathMax = [double]$m + [double]$textPad
      if ($pathMax -lt $minTargetPath) { $pathMax = $minTargetPath }
      try { $script:GridPathMaxAllowedPx = [double]$pathMax } catch {}
    }
    try { $targetCol.MinWidth = [double]$minTargetPath } catch {}
    try { $pathCol.MinWidth = [double]$minTargetPath } catch {}
    $gridW = 0.0
    try { $gridW = [double]$grid.ActualWidth } catch { $gridW = 0.0 }
    if ($gridW -le 0.0) { return }
    $selectW = 65.0
    $nameW = 256.0
    $pendingW = $fixedW
    $typeW = $fixedW
    try { if ($selectCol) { $selectW = [double]$selectCol.ActualWidth } } catch {}
    try {
      if ($nameCol) {
        $nameW = [double]$nameCol.ActualWidth
        if ($nameW -le 0.0) { $nameW = [double]$nameCol.Width.DisplayValue }
      }
    } catch {}
    if ($selectW -le 0.0) { $selectW = 65.0 }
    if ($nameW -le 0.0) { $nameW = 256.0 }
    $nonTargetPathW = [double]$selectW + [double]$nameW + [double]$pendingW + [double]$typeW + [double]$layoutPad
    $available = [double]$gridW - [double]$nonTargetPathW
    if ($available -lt ([double]$minTargetPath * 2.0)) { $available = [double]$minTargetPath * 2.0 }
    $targetCap = [Math]::Max([double]$minTargetPath, [double]$targetMax)
    $pathCap = [Math]::Max([double]$minTargetPath, [double]$pathMax)
    $targetW = [double]$minTargetPath
    $pathW = [double]$minTargetPath
    try {
      $targetW = [double]$targetCol.ActualWidth
      if ($targetW -le 0.0) { $targetW = [double]$targetCol.Width.DisplayValue }
    } catch { $targetW = [double]$minTargetPath }
    try {
      $pathW = [double]$pathCol.ActualWidth
      if ($pathW -le 0.0) { $pathW = [double]$pathCol.Width.DisplayValue }
    } catch { $pathW = [double]$minTargetPath }
    if ($targetW -lt $minTargetPath) { $targetW = [double]$minTargetPath }
    if ($pathW -lt $minTargetPath) { $pathW = [double]$minTargetPath }
    if ($targetW -gt $targetCap) { $targetW = [double]$targetCap }
    if ($pathW -gt $pathCap) { $pathW = [double]$pathCap }
    # Anchor behavior: whichever of Target/Path is rightmost always fills the remaining width
    # up to the right-panel splitter (swap-aware by DisplayIndex).
    $rightIsPath = $true
    try {
      if ([int]$targetCol.DisplayIndex -gt [int]$pathCol.DisplayIndex) { $rightIsPath = $false }
    } catch {}
    $leftCap = if ($rightIsPath) { [double]$targetCap } else { [double]$pathCap }
    $rightCap = if ($rightIsPath) { [double]$pathCap } else { [double]$targetCap }
    # Keep manual divider behavior: preserve current left/right ratio on resize,
    # while still enforcing min widths and content caps.
    $leftCurrent = if ($rightIsPath) { [double]$targetW } else { [double]$pathW }
    $rightCurrent = if ($rightIsPath) { [double]$pathW } else { [double]$targetW }
    $ratio = 0.5
    $sumCurrent = [double]$leftCurrent + [double]$rightCurrent
    if ($sumCurrent -gt 1.0) {
      $ratio = [double]$leftCurrent / $sumCurrent
      if ($ratio -lt 0.05 -or $ratio -gt 0.95) { $ratio = 0.5 }
    }
    $leftW = [double]$available * $ratio
    $rightW = [double]$available - [double]$leftW
    if ($leftW -lt $minTargetPath) {
      $leftW = [double]$minTargetPath
      $rightW = [double]$available - [double]$leftW
    }
    if ($rightW -lt $minTargetPath) {
      $rightW = [double]$minTargetPath
      $leftW = [double]$available - [double]$rightW
    }
    if ($leftW -gt $leftCap) {
      $leftW = [double]$leftCap
      $rightW = [double]$available - [double]$leftW
    }
    if ($rightW -gt $rightCap) {
      $rightW = [double]$rightCap
      $leftW = [double]$available - [double]$rightW
    }
    if ($leftW -lt $minTargetPath) { $leftW = [double]$minTargetPath }
    if ($rightW -lt $minTargetPath) { $rightW = [double]$minTargetPath }
    $targetDynamicMax = [double]$targetCap
    $pathDynamicMax = [double]$pathCap
    if ($rightIsPath) {
      $targetW = [double]$leftW
      $pathW = [double]$rightW
      # allow rightmost to expand with splitter so the right edge stays anchored
      $pathDynamicMax = [Math]::Max([double]$pathCap, [double]$pathW)
    } else {
      $pathW = [double]$leftW
      $targetW = [double]$rightW
      # allow rightmost to expand with splitter so the right edge stays anchored
      $targetDynamicMax = [Math]::Max([double]$targetCap, [double]$targetW)
    }
    if ($targetW -lt $minTargetPath) { $targetW = [double]$minTargetPath }
    if ($pathW -lt $minTargetPath) { $pathW = [double]$minTargetPath }
    try { $targetCol.MaxWidth = [double]$targetDynamicMax } catch {}
    try { $pathCol.MaxWidth = [double]$pathDynamicMax } catch {}
    try { $targetCol.Width = [System.Windows.Controls.DataGridLength]::new([double]$targetW, [System.Windows.Controls.DataGridLengthUnitType]::Pixel) } catch {}
    try { $pathCol.Width = [System.Windows.Controls.DataGridLength]::new([double]$pathW, [System.Windows.Controls.DataGridLengthUnitType]::Pixel) } catch {}
  } catch {}
}

function Invoke-GridColumnWidthConstraintsSafe {
  param([switch]$RecomputeContentMax)
  try {
    if ([bool]$script:GridColumnConstraintApplying) { return }
    $script:GridColumnConstraintApplying = $true
    try {
      if ($RecomputeContentMax) { Apply-GridColumnWidthConstraints -RecomputeContentMax }
      else { Apply-GridColumnWidthConstraints }
    } finally {
      $script:GridColumnConstraintApplying = $false
    }
  } catch {
    try { $script:GridColumnConstraintApplying = $false } catch {}
  }
}

function Ensure-GridTargetPathWidthHooks {
  try {
    if (-not $grid) { return }
    if (-not $script:GridColumnWidthDescriptor) {
      try {
        $script:GridColumnWidthDescriptor = [System.ComponentModel.DependencyPropertyDescriptor]::FromProperty(
          [System.Windows.Controls.DataGridColumn]::WidthProperty,
          [System.Windows.Controls.DataGridColumn]
        )
      } catch {
        $script:GridColumnWidthDescriptor = $null
      }
    }
    if (-not $script:GridColumnWidthChangedHandler) {
      $script:GridColumnWidthChangedHandler = [System.EventHandler]{
        param($sender, $e)
        try { Invoke-GridColumnWidthConstraintsSafe } catch {}
      }
    }
    $targetCol = Get-GridColumnByHeader -Header 'Target'
    $pathCol = Get-GridColumnByHeader -Header 'Path'
    if (-not $targetCol -or -not $pathCol) { return }
    if ($script:GridColumnWidthDescriptor) {
      try {
        if ($script:GridTargetWidthHookedColumn -and ($script:GridTargetWidthHookedColumn -ne $targetCol)) {
          $script:GridColumnWidthDescriptor.RemoveValueChanged($script:GridTargetWidthHookedColumn, $script:GridColumnWidthChangedHandler)
          $script:GridTargetWidthHookedColumn = $null
        }
      } catch {}
      try {
        if ($script:GridPathWidthHookedColumn -and ($script:GridPathWidthHookedColumn -ne $pathCol)) {
          $script:GridColumnWidthDescriptor.RemoveValueChanged($script:GridPathWidthHookedColumn, $script:GridColumnWidthChangedHandler)
          $script:GridPathWidthHookedColumn = $null
        }
      } catch {}
      try {
        if (-not $script:GridTargetWidthHookedColumn) {
          $script:GridColumnWidthDescriptor.AddValueChanged($targetCol, $script:GridColumnWidthChangedHandler)
          $script:GridTargetWidthHookedColumn = $targetCol
        }
      } catch {}
      try {
        if (-not $script:GridPathWidthHookedColumn) {
          $script:GridColumnWidthDescriptor.AddValueChanged($pathCol, $script:GridColumnWidthChangedHandler)
          $script:GridPathWidthHookedColumn = $pathCol
        }
      } catch {}
    }
    if (-not [bool]$script:GridColumnReorderedWired) {
      try {
        $grid.Add_ColumnReordered({
          param($sender, $e)
          try { Ensure-GridTargetPathWidthHooks } catch {}
          try { Invoke-GridColumnWidthConstraintsSafe } catch {}
        })
        $script:GridColumnReorderedWired = $true
      } catch {}
    }
  } catch {}
}

function Test-GridNameColumnResizeGripHit {
  param(
    [System.Windows.DependencyObject]$Dep,
    [object]$MouseEvent
  )
  try {
    if (-not $Dep -or -not $MouseEvent) { return $false }
    $cell = Find-VisualAncestor -Start $Dep -Type ([System.Windows.Controls.DataGridCell])
    if (-not $cell) { return $false }
    $nameCol = Get-GridNameColumn
    if (-not $nameCol) { return $false }
    if ($cell.Column -ne $nameCol) { return $false }
    $cw = 0.0
    try { $cw = [double]$cell.ActualWidth } catch { $cw = 0.0 }
    if ($cw -le 0.0) {
      try { $cw = [double]$nameCol.ActualWidth } catch { $cw = 0.0 }
    }
    if ($cw -le 0.0) { return $false }
    $pt = [System.Windows.Point]::new(0.0, 0.0)
    try { $pt = $MouseEvent.GetPosition($cell) } catch { return $false }
    $grip = 8.0
    try { $grip = [double]$script:GridNameResizeGripPx } catch { $grip = 8.0 }
    if ($grip -lt 3.0) { $grip = 3.0 }
    if ($grip -gt 24.0) { $grip = 24.0 }
    return ([double]$pt.X -ge ([double]$cw - [double]$grip))
  } catch {
    return $false
  }
}

function Start-GridNameColumnResizeDrag {
  param([object]$MouseEvent)
  try {
    if (-not $grid -or -not $MouseEvent) { return $false }
    $nameCol = Get-GridNameColumn
    if (-not $nameCol) { return $false }
    $w0 = 0.0
    try { $w0 = [double]$nameCol.ActualWidth } catch { $w0 = 0.0 }
    if ($w0 -le 0.0) {
      try { $w0 = [double]$nameCol.Width.DisplayValue } catch { $w0 = 0.0 }
    }
    if ($w0 -le 0.0) { $w0 = 256.0 }
    $p = [System.Windows.Point]::new(0.0, 0.0)
    try { $p = $MouseEvent.GetPosition($grid) } catch {}
    $script:GridNameColResizeActive = $true
    $script:GridNameColResizeStartX = [double]$p.X
    $script:GridNameColResizeStartWidth = [double]$w0
    $script:GridNameColResizeColumn = $nameCol
    try { $grid.CaptureMouse() } catch {}
    try { if ($window) { $window.Cursor = [System.Windows.Input.Cursors]::SizeWE } } catch {}
    return $true
  } catch {
    return $false
  }
}

function Stop-GridNameColumnResizeDrag {
  try { $script:GridNameColResizeActive = $false } catch {}
  try { $script:GridNameColResizeColumn = $null } catch {}
  try { if ($grid -and $grid.IsMouseCaptured) { $grid.ReleaseMouseCapture() } } catch {}
  try { if ($window) { $window.Cursor = [System.Windows.Input.Cursors]::Arrow } } catch {}
}

function Update-GridNameColumnResizeDrag {
  param([object]$MouseEvent)
  try {
    if (-not [bool]$script:GridNameColResizeActive) { return }
    if (-not $grid -or -not $MouseEvent) { return }
    $nameCol = $null
    try { $nameCol = $script:GridNameColResizeColumn } catch { $nameCol = $null }
    if (-not $nameCol) { $nameCol = Get-GridNameColumn }
    if (-not $nameCol) { return }
    $p = [System.Windows.Point]::new(0.0, 0.0)
    try { $p = $MouseEvent.GetPosition($grid) } catch {}
    $startX = 0.0
    $startW = 256.0
    try { $startX = [double]$script:GridNameColResizeStartX } catch { $startX = 0.0 }
    try { $startW = [double]$script:GridNameColResizeStartWidth } catch { $startW = 256.0 }
    $dx = ([double]$p.X - [double]$startX)
    $newW = [double]$startW + [double]$dx
    $minW = 256.0
    try { $minW = [double]$script:GridNameMinWidthPx } catch { $minW = 256.0 }
    if ($minW -lt 32.0) { $minW = 32.0 }
    if ($newW -lt $minW) { $newW = $minW }
    try { if ([double]$nameCol.MinWidth -lt $minW) { $nameCol.MinWidth = [double]$minW } } catch {}
    $curW = 0.0
    try { $curW = [double]$nameCol.ActualWidth } catch { $curW = 0.0 }
    if ([Math]::Abs(([double]$newW - [double]$curW)) -lt 0.15) { return }
    $nameCol.Width = [System.Windows.Controls.DataGridLength]::new([double]$newW, [System.Windows.Controls.DataGridLengthUnitType]::Pixel)
    try { Invoke-GridColumnWidthConstraintsSafe } catch {}
    try { Update-GridSelectNameBandLayout } catch {}
    try { Update-GridTopMaskResizeThumbLayout } catch {}
    try { Update-MidGridScrollBarLayout } catch {}
    try { Sync-MidGridScrollBarFromViewer -LayoutUpdate:$false } catch {}
  } catch {}
}

if (-not (Test-Path variable:script:RenameBeginEditGate)) {
  $script:RenameBeginEditGate = @{
    Armed  = $false
    RowId  = ''
    Source = ''
    AtUtc  = [datetime]::MinValue
  }
}

function Get-RowRenameGateId {
  param([object]$Row)
  try {
    if (-not $Row) { return '' }
    $id = [string](Get-PropString -Obj $Row -Names @('Id') -Fallback '')
    if (-not [string]::IsNullOrWhiteSpace($id)) { return $id }
  } catch {}
  return ''
}

function Clear-RenameBeginEditGate {
  try {
    $script:RenameBeginEditGate.Armed  = $false
    $script:RenameBeginEditGate.RowId  = ''
    $script:RenameBeginEditGate.Source = ''
    $script:RenameBeginEditGate.AtUtc  = [datetime]::MinValue
  } catch {}
}

function Arm-RenameBeginEditGate {
  param(
    [Parameter(Mandatory=$true)][object]$Row,
    [string]$Source = 'Unknown'
  )
  try {
    $script:RenameBeginEditGate.Armed  = $true
    $script:RenameBeginEditGate.RowId  = [string](Get-RowRenameGateId -Row $Row)
    $script:RenameBeginEditGate.Source = [string]$Source
    $script:RenameBeginEditGate.AtUtc  = [datetime]::UtcNow
  } catch {}
}

function Test-AndConsume-RenameBeginEditGate {
  param([object]$Row)
  try {
    if (-not $script:RenameBeginEditGate) { return $false }
    if (-not [bool]$script:RenameBeginEditGate.Armed) { return $false }
    $age = [datetime]::UtcNow - [datetime]$script:RenameBeginEditGate.AtUtc
    if ($age.TotalSeconds -gt 8) {
      Clear-RenameBeginEditGate
      return $false
    }
    $expected = [string]$script:RenameBeginEditGate.RowId
    $actual   = [string](Get-RowRenameGateId -Row $Row)
    if (-not [string]::IsNullOrWhiteSpace($expected) -and -not [string]::IsNullOrWhiteSpace($actual) -and $expected -ne $actual) {
      Clear-RenameBeginEditGate
      return $false
    }
    $src = [string]$script:RenameBeginEditGate.Source
    Clear-RenameBeginEditGate
    return $true
  } catch {
    Clear-RenameBeginEditGate
    return $false
  }
}

function Test-IsCreatedPendingRow {
  param([object]$Row)
  try {
    if (-not $Row) { return $false }
    $isPendingCreate = $false
    try { $isPendingCreate = ($Row.PSObject.Properties.Match('IsPendingCreate').Count -gt 0 -and [bool]$Row.IsPendingCreate) } catch { $isPendingCreate = $false }
    if ($isPendingCreate) { return $true }
    try {
      if ($Row.PSObject.Properties.Match('PendingLabelRows').Count -gt 0 -and $Row.PendingLabelRows) {
        foreach ($lbl in @($Row.PendingLabelRows)) {
          if (-not $lbl) { continue }
          $txt = ''
          try { $txt = [string]$lbl.Text } catch { $txt = '' }
          if ([string]::IsNullOrWhiteSpace($txt)) { continue }
          if ([string]::Equals($txt.Trim(), 'Created', [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
        }
      }
    } catch {}
    $pl = ''
    try { $pl = [string](Get-PropString -Obj $Row -Names @('PendingLabel') -Fallback '') } catch { $pl = '' }
    if (-not [string]::IsNullOrWhiteSpace($pl)) {
      foreach ($raw in @($pl -split "`r?`n")) {
        $tok = ([string]$raw).Trim()
        if ([string]::IsNullOrWhiteSpace($tok)) { continue }
        if ([string]::Equals($tok, 'Created', [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
      }
    }
  } catch {}
  return $false
}

function Start-RenameForRow {
  param([Parameter(Mandatory=$true)][object]$Row)
  try {
    if (-not $Row) { return }
    if (Test-IsAlphaSeparatorRow -Row $Row) { return }
    if (Test-IsCreatedPendingRow -Row $Row) { return }
    $nameCol = Get-GridNameColumn
    if (-not $nameCol) { return }
    # IMPORTANT (virtualization + right-click rename):
    # If another row is currently being edited, selecting a new row here can cause the edit value
    # to "jump" to the new row (classic DataGrid recycling/binding hazard).
    # Commit the current edit BEFORE changing selection/current cell to keep the rename attached
    # to the correct row.
    try {
      [void]$grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Cell, $true)
      [void]$grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row,  $true)
    } catch {}
    # Do not rename deleted rows (matches your existing edit guard style)
    try {
      if ($Row.PSObject.Properties.Match('Action').Count -gt 0 -and $Row.Action -eq "Delete") { return }
    } catch {}
    Arm-RenameBeginEditGate -Row $Row -Source 'Start-RenameForRow'
    # Select row and set current cell to Name
    try { $grid.SelectedItem = $Row } catch {}
    try { $grid.CurrentItem  = $Row } catch {}
    try { $grid.CurrentCell  = New-Object System.Windows.Controls.DataGridCellInfo($Row, $nameCol) } catch {}
    # BeginEdit on dispatcher to avoid fighting selection/focus churn
    $null = $grid.Dispatcher.BeginInvoke(
      [Action]{
        try {
          $grid.Focus() | Out-Null
          [void]$grid.BeginEdit()
        } catch {}
      },
      [System.Windows.Threading.DispatcherPriority]::Input
    )
  } catch {}
}

function Test-IsDraggableLinkRow {
  param([object]$Row)
  try {
    if (-not $Row) { return $false }
    if (Test-IsAlphaSeparatorRow -Row $Row) { return $false }
    $rk = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback '')
    if ($rk -ne 'Item') { return $false }
    $act = [string](Get-PropString -Obj $Row -Names @('Action') -Fallback '')
    if ($act -eq 'Delete') { return $false }
    $isPendingCreate = $false
    try { $isPendingCreate = ($Row.PSObject.Properties.Match('IsPendingCreate').Count -gt 0 -and [bool]$Row.IsPendingCreate) } catch { $isPendingCreate = $false }
    if ($isPendingCreate) { return $false }
    $isProxy = $false
    try { $isProxy = ($Row.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderProxy) } catch {}
    if (-not $isProxy) {
      try { $isProxy = ($Row.PSObject.Properties.Match('IsAppsFolderDisplayProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderDisplayProxy) } catch {}
    }
    if (-not $isProxy) {
      try { $isProxy = ($Row.PSObject.Properties.Match('IsWindowsSecurityProxy').Count -gt 0 -and [bool]$Row.IsWindowsSecurityProxy) } catch {}
    }
    if ($isProxy) { return $false }
    $tp = [string](Get-PropString -Obj $Row -Names @('Type') -Fallback '')
    if ($tp -ne 'Shortcut' -and $tp -ne 'Url') { return $false }
    $p = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback ''))
    if ([string]::IsNullOrWhiteSpace($p)) { return $false }
    if ($p.StartsWith('shell:', [System.StringComparison]::OrdinalIgnoreCase)) { return $false }
    return $true
  } catch {
    return $false
  }
}

function Test-IsFolderDropTargetRow {
  param([object]$Row)
  try {
    if (-not $Row) { return $false }
    if (Test-IsAlphaSeparatorRow -Row $Row) { return $false }
    $rk = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback '')
    if ($rk -ne 'Folder') { return $false }
    $act = [string](Get-PropString -Obj $Row -Names @('Action') -Fallback '')
    if ($act -eq 'Delete') { return $false }
    return $true
  } catch {
    return $false
  }
}

function Resolve-DropTargetFolderForSource {
  param(
    [Parameter(Mandatory=$true)][object]$TargetFolderRow,
    [Parameter(Mandatory=$true)][object]$SourceRow
  )
  try {
    if (-not (Test-IsFolderDropTargetRow -Row $TargetFolderRow)) { return $null }
    if (-not (Test-IsDraggableLinkRow -Row $SourceRow)) { return $null }
    $srcScope = [string](Get-PropString -Obj $SourceRow -Names @('Scope') -Fallback '')
    $srcOriginalPath = Normalize-Path ([string](Get-PropString -Obj $SourceRow -Names @('OriginalPath') -Fallback ''))
    $srcOriginalParent = ''
    try { if (-not [string]::IsNullOrWhiteSpace($srcOriginalPath)) { $srcOriginalParent = Normalize-Path (Split-Path -Path $srcOriginalPath -Parent) } } catch { $srcOriginalParent = '' }
    $targetScope = [string](Get-PropString -Obj $TargetFolderRow -Names @('Scope') -Fallback '')
    $targetPath  = Normalize-Path ([string](Get-PropString -Obj $TargetFolderRow -Names @('Path','FullPath','OriginalPath') -Fallback ''))
    # VisualMenu merged folders can represent multiple physical source folders.
    $sources = @()
    try {
      if ($TargetFolderRow.PSObject.Properties.Match('VisualSources').Count -gt 0 -and $TargetFolderRow.VisualSources) {
        $sources = @($TargetFolderRow.VisualSources)
      }
    } catch { $sources = @() }
    if ($sources.Count -gt 0) {
      # Flattened view mapping:
      # when nested folders are hidden, users still drag over a visible parent folder row.
      # If the dragged row has an OriginalPath under that parent subtree, route drop back
      # to that actual original nested folder path instead of the visible parent bucket.
      if ((-not [bool]$script:ShowNestedFolderRows) -and (-not [string]::IsNullOrWhiteSpace($srcOriginalParent))) {
        foreach ($s in @($sources)) {
          if (-not $s) { continue }
          $sc = [string](Get-PropString -Obj $s -Names @('Scope') -Fallback '')
          $fp = Normalize-Path ([string](Get-PropString -Obj $s -Names @('FullPath','Path') -Fallback ''))
          if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($fp)) { continue }
          if (-not [string]::IsNullOrWhiteSpace($srcScope) -and $sc -ne $srcScope) { continue }
          $rootN = ''
          $parentN = ''
          try { $rootN = [string]$fp.TrimEnd('\') } catch { $rootN = [string]$fp }
          try { $parentN = [string]$srcOriginalParent.TrimEnd('\') } catch { $parentN = [string]$srcOriginalParent }
          if ([string]::IsNullOrWhiteSpace($rootN) -or [string]::IsNullOrWhiteSpace($parentN)) { continue }
          $under = $false
          try {
            if ($parentN.Equals($rootN, [System.StringComparison]::OrdinalIgnoreCase)) { $under = $true }
            elseif ($parentN.StartsWith(($rootN + '\'), [System.StringComparison]::OrdinalIgnoreCase)) { $under = $true }
          } catch { $under = $false }
          if (-not $under) { continue }
          if (-not (Test-Path -LiteralPath $parentN -PathType Container)) { continue }
          $retScope = $sc
          if (-not [string]::IsNullOrWhiteSpace($srcScope)) { $retScope = $srcScope }
          return [pscustomobject]@{ Scope = $retScope; FolderPath = $parentN }
        }
      }

      # First choice: exact original parent path for true return-to-origin drags.
      foreach ($s in @($sources)) {
        if (-not $s) { continue }
        $sc = [string](Get-PropString -Obj $s -Names @('Scope') -Fallback '')
        $fp = Normalize-Path ([string](Get-PropString -Obj $s -Names @('FullPath','Path') -Fallback ''))
        if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($fp)) { continue }
        if ([string]::IsNullOrWhiteSpace($srcOriginalParent)) { continue }
        if (Test-PathEqualsCI -A $fp -B $srcOriginalParent) {
          if (-not (Test-Path -LiteralPath $fp -PathType Container)) { continue }
          return [pscustomobject]@{ Scope = $sc; FolderPath = $fp }
        }
      }
      # First choice for merged folders: destination source in the same scope as dragged row.
      foreach ($s in @($sources)) {
        if (-not $s) { continue }
        $sc = [string](Get-PropString -Obj $s -Names @('Scope') -Fallback '')
        $fp = Normalize-Path ([string](Get-PropString -Obj $s -Names @('FullPath','Path') -Fallback ''))
        if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($fp)) { continue }
        if ([string]::IsNullOrWhiteSpace($srcScope) -or $sc -ne $srcScope) { continue }
        if (-not (Test-Path -LiteralPath $fp -PathType Container)) { continue }
        return [pscustomobject]@{ Scope = $sc; FolderPath = $fp }
      }
      # Prefer the physical source that matches the visible row's own scope/path.
      foreach ($s in @($sources)) {
        if (-not $s) { continue }
        $sc = [string](Get-PropString -Obj $s -Names @('Scope') -Fallback '')
        $fp = Normalize-Path ([string](Get-PropString -Obj $s -Names @('FullPath','Path') -Fallback ''))
        if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($fp)) { continue }
        if (-not [string]::IsNullOrWhiteSpace($targetScope) -and $sc -ne $targetScope) { continue }
        if (-not [string]::IsNullOrWhiteSpace($targetPath) -and -not (Test-PathEqualsCI -A $fp -B $targetPath)) { continue }
        if (-not (Test-Path -LiteralPath $fp -PathType Container)) { continue }
        return [pscustomobject]@{ Scope = $sc; FolderPath = $fp }
      }
      # Fallback: first valid physical folder source from VisualSources.
      foreach ($s in @($sources)) {
        if (-not $s) { continue }
        $sc = [string](Get-PropString -Obj $s -Names @('Scope') -Fallback '')
        $fp = Normalize-Path ([string](Get-PropString -Obj $s -Names @('FullPath','Path') -Fallback ''))
        if ([string]::IsNullOrWhiteSpace($sc)) { continue }
        if ([string]::IsNullOrWhiteSpace($fp)) { continue }
        if (-not (Test-Path -LiteralPath $fp -PathType Container)) { continue }
        return [pscustomobject]@{ Scope = $sc; FolderPath = $fp }
      }
      return $null
    }
    if ([string]::IsNullOrWhiteSpace($targetPath)) { return $null }
    if (-not (Test-Path -LiteralPath $targetPath -PathType Container)) { return $null }
    return [pscustomobject]@{ Scope = $targetScope; FolderPath = $targetPath }
  } catch {
    return $null
  }
}

function Resolve-RootDropTargetForSource {
  param(
    [Parameter(Mandatory=$true)][object]$SourceRow
  )
  try {
    if (-not (Test-IsDraggableLinkRow -Row $SourceRow)) { return $null }
    $srcScope = [string](Get-PropString -Obj $SourceRow -Names @('Scope') -Fallback '')
    if ([string]::IsNullOrWhiteSpace($srcScope)) { return $null }
    $rootPath = Normalize-Path ([string]$scopeRoots[$srcScope])
    if ([string]::IsNullOrWhiteSpace($rootPath)) { return $null }
    if (-not (Test-Path -LiteralPath $rootPath -PathType Container)) { return $null }
    $srcPath = Normalize-Path ([string](Get-PropString -Obj $SourceRow -Names @('Path','OriginalPath') -Fallback ''))
    if ([string]::IsNullOrWhiteSpace($srcPath)) { return $null }
    $srcDir = Normalize-Path (Split-Path -Path $srcPath -Parent)
    if (-not [string]::IsNullOrWhiteSpace($srcDir) -and (Test-PathEqualsCI -A $srcDir -B $rootPath)) { return $null }
    return [pscustomobject]@{ Scope = $srcScope; FolderPath = $rootPath }
  } catch {
    return $null
  }
}

function Test-DragDropModelPathConflict {
  param(
    [Parameter(Mandatory=$true)][string]$Scope,
    [Parameter(Mandatory=$true)][string]$Path,
    [string]$ExcludeId = ''
  )
  try {
    $sc = [string]$Scope
    $pp = Normalize-Path ([string]$Path)
    if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($pp)) { return $false }

    foreach ($kv in @($script:NodeMap.GetEnumerator())) {
      $n = $kv.Value
      if (-not $n -or -not $n.Items) { continue }
      foreach ($it in @($n.Items)) {
        if (-not $it) { continue }
        $id = ''
        try { $id = [string](Get-PropString -Obj $it -Names @('Id') -Fallback '') } catch { $id = '' }
        if (-not [string]::IsNullOrWhiteSpace($ExcludeId) -and $id -eq $ExcludeId) { continue }
        $isc = ''
        try { $isc = [string](Get-PropString -Obj $it -Names @('Scope') -Fallback '') } catch { $isc = '' }
        if ($isc -ne $sc) { continue }
        $ip = ''
        try { $ip = Normalize-Path ([string](Get-PropString -Obj $it -Names @('Path','OriginalPath') -Fallback '')) } catch { $ip = '' }
        if ([string]::IsNullOrWhiteSpace($ip)) { continue }
        if (Test-PathEqualsCI -A $ip -B $pp) { return $true }
      }
    }

    foreach ($cr in @($script:PendingCreateRows)) {
      if (-not $cr) { continue }
      $id = ''
      try { $id = [string](Get-PropString -Obj $cr -Names @('Id') -Fallback '') } catch { $id = '' }
      if (-not [string]::IsNullOrWhiteSpace($ExcludeId) -and $id -eq $ExcludeId) { continue }
      $csc = ''
      try { $csc = [string](Get-PropString -Obj $cr -Names @('Scope') -Fallback '') } catch { $csc = '' }
      if ($csc -ne $sc) { continue }
      $cp = ''
      try { $cp = Normalize-Path ([string](Get-PropString -Obj $cr -Names @('Path','OriginalPath') -Fallback '')) } catch { $cp = '' }
      if ([string]::IsNullOrWhiteSpace($cp)) { continue }
      if (Test-PathEqualsCI -A $cp -B $pp) { return $true }
    }
  } catch {}
  return $false
}

function Get-ExpandedAncestorFolderDropTargetRow {
  param([object]$Row)
  try {
    if (-not $Row) { return $null }
    if (-not $script:VisibleRows) { return $null }
    $idx = Get-VisibleRowIndexByRef -Row $Row
    if ($idx -lt 0) { return $null }
    $lvl = Get-VisibleRowLevel -Row $Row -Default 0
    if ($lvl -le 0) { return $null }
    for ($i = ($idx - 1); $i -ge 0; $i--) {
      $cand = $script:VisibleRows[$i]
      if (-not $cand) { continue }
      $candLvl = Get-VisibleRowLevel -Row $cand -Default 0
      if ($candLvl -ge $lvl) { continue }
      if (Test-IsFolderDropTargetRow -Row $cand) {
        $isExpanded = $false
        try { $isExpanded = ($cand.PSObject.Properties.Match('IsExpanded').Count -gt 0 -and [bool]$cand.IsExpanded) } catch { $isExpanded = $false }
        if ($isExpanded) { return $cand }
      }
      $lvl = $candLvl
      if ($lvl -le 0) { break }
    }
    return $null
  } catch {
    return $null
  }
}

function Get-DragDropTargetContext {
  param([System.Windows.DependencyObject]$Start)
  try {
    $ctx = [pscustomobject]@{
      Mode      = 'Root' # Root or Folder
      TargetRow = $null
    }
    if (-not $Start) { return $ctx }
    $rowContainer = Find-VisualAncestor -Start $Start -Type ([System.Windows.Controls.DataGridRow])
    if (-not $rowContainer) { return $ctx }
    $targetRow = $rowContainer.Item
    if (-not $targetRow) { return $ctx }
    # Treat the entire folder row as a folder drop target.
    # This avoids hover flicker when pointer transitions between icon/text/empty areas.
    if (Test-IsFolderDropTargetRow -Row $targetRow) {
      $ctx.Mode = 'Folder'
      $ctx.TargetRow = $targetRow
    } else {
      # If cursor is over nested content inside an expanded folder, map drop target
      # to the nearest expanded ancestor folder row.
      $ancestorFolder = Get-ExpandedAncestorFolderDropTargetRow -Row $targetRow
      if ($ancestorFolder) {
        $ctx.Mode = 'Folder'
        $ctx.TargetRow = $ancestorFolder
      }
    }
    return $ctx
  } catch {
    return [pscustomobject]@{ Mode = 'Root'; TargetRow = $null }
  }
}

function Get-DragDropTargetContextFromGridPoint {
  param([System.Windows.Point]$GridPoint)
  try {
    $ctxDefault = [pscustomobject]@{ Mode = 'Root'; TargetRow = $null }
    if (-not $grid) { return $ctxDefault }
    $hit = $null
    try { $hit = $grid.InputHitTest($GridPoint) } catch { $hit = $null }
    $dep = $hit -as [System.Windows.DependencyObject]
    if (-not $dep) { return $ctxDefault }
    return (Get-DragDropTargetContext -Start $dep)
  } catch {
    return [pscustomobject]@{ Mode = 'Root'; TargetRow = $null }
  }
}

function Move-ModelRowToPath {
  param(
    [Parameter(Mandatory=$true)][object]$Row,
    [Parameter(Mandatory=$true)][string]$NewScope,
    [Parameter(Mandatory=$true)][string]$NewPath
  )
  $newPathN = Normalize-Path $NewPath
  if ([string]::IsNullOrWhiteSpace($newPathN)) { return $false }
  $oldScope = [string](Get-PropString -Obj $Row -Names @('Scope') -Fallback '')
  $oldPath  = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback ''))
  if ([string]::IsNullOrWhiteSpace($oldPath)) { return $false }
  $oldParent = Split-Path -Path $oldPath -Parent
  $newParent = Split-Path -Path $newPathN -Parent
  if ([string]::IsNullOrWhiteSpace($newParent)) { return $false }
  $rowId = [string](Get-PropString -Obj $Row -Names @('Id') -Fallback '')
  if ([string]::IsNullOrWhiteSpace($rowId)) { return $false }
  $srcNode = $null
  $dstNode = $null
  try { $srcNode = Get-NodeByScopePath -Scope $oldScope -FullPath $oldParent } catch { $srcNode = $null }
  try { $dstNode = Get-NodeByScopePath -Scope $NewScope -FullPath $newParent } catch { $dstNode = $null }
  if (-not $dstNode) { return $false }
  # Robust cleanup: remove this row from every node item list first,
  # so it cannot remain rendered at the old location in VisualMenu.
  try {
    foreach ($kv in $script:NodeMap.GetEnumerator()) {
      $n = $kv.Value
      if (-not $n) { continue }
      if ($n.PSObject.Properties.Match('Items').Count -eq 0 -or -not $n.Items) { continue }
      for ($i = $n.Items.Count - 1; $i -ge 0; $i--) {
        $cur = $n.Items[$i]
        if (-not $cur) { continue }
        $cid = ''
        try { $cid = [string](Get-PropString -Obj $cur -Names @('Id') -Fallback '') } catch { $cid = '' }
        if (-not [string]::IsNullOrWhiteSpace($cid) -and $cid -eq $rowId) {
          $n.Items.RemoveAt($i)
        }
      }
    }
  } catch {}
  try {
    if ($srcNode -and $srcNode.Items) {
      for ($i = $srcNode.Items.Count - 1; $i -ge 0; $i--) {
        $cur = $srcNode.Items[$i]
        if ($cur -and ([string](Get-PropString -Obj $cur -Names @('Id') -Fallback '') -eq $rowId)) {
          $srcNode.Items.RemoveAt($i)
          break
        }
      }
    }
  } catch {}
  $alreadyThere = $false
  try {
    foreach ($cur in @($dstNode.Items)) {
      if (-not $cur) { continue }
      if ([string](Get-PropString -Obj $cur -Names @('Id') -Fallback '') -eq $rowId) { $alreadyThere = $true; break }
    }
  } catch { $alreadyThere = $false }
  if (-not $alreadyThere) {
    try { [void]$dstNode.Items.Add($Row) } catch {}
  }
  try { Set-PropSafeGlobal -Obj $Row -Name 'Scope' -Value $NewScope } catch {}
  try { Set-PropSafeGlobal -Obj $Row -Name 'Path' -Value $newPathN } catch {}
  return $true
}

function Apply-DragMoveSnapshot {
  param(
    [Parameter(Mandatory=$true)][object[]]$Snapshot,
    [ValidateSet('Do','Undo')][string]$Direction = 'Do'
  )
  foreach ($s in @($Snapshot)) {
    if (-not $s) { continue }
    $x = Find-ItemById -Id ([string]$s.Id)
    if (-not $x) { continue }
    if ($Direction -eq 'Do') {
      $ok = Move-ModelRowToPath -Row $x -NewScope ([string]$s.NewScope) -NewPath ([string]$s.NewPath)
      if (-not $ok) { continue }
      try { Set-PropSafeGlobal -Obj $x -Name 'Selected' -Value $false } catch {}
      try { Set-PendingState -it $x -BumpLabels @('Moved') } catch {}
    } else {
      $ok = Move-ModelRowToPath -Row $x -NewScope ([string]$s.PrevScope) -NewPath ([string]$s.PrevPath)
      if (-not $ok) { continue }
      try { Set-PropSafeGlobal -Obj $x -Name 'Action' -Value ([string]$s.PrevAction) } catch {}
      try { Set-PropSafeGlobal -Obj $x -Name 'PendingLabel' -Value ([string]$s.PrevPending) } catch {}
      try {
        if (-not $x.PSObject.Properties.Match('PendingLabelRows').Count) {
          $x | Add-Member -NotePropertyName 'PendingLabelRows' -NotePropertyValue (@()) -Force
        }
        $rows = New-Object System.Collections.Generic.List[object]
        foreach ($raw in @(([string]$s.PrevPending -split "`r?`n"))) {
          $tok = [string]$raw
          if ([string]::IsNullOrWhiteSpace($tok)) { continue }
          if ([string]::Equals($tok.Trim(), 'Icon Changed', [System.StringComparison]::OrdinalIgnoreCase)) { $tok = 'Icon Edit' } else { $tok = $tok.Trim() }
          $clr = '#fdfb70'
          if ([string]::Equals($tok, 'Moved', [System.StringComparison]::OrdinalIgnoreCase)) { $clr = '#57c8eb' }
          elseif ([string]::Equals($tok, 'Renamed', [System.StringComparison]::OrdinalIgnoreCase)) { $clr = '#4ee077' }
          elseif ([string]::Equals($tok, 'Icon Edit', [System.StringComparison]::OrdinalIgnoreCase)) { $clr = '#ffbc6b' }
          elseif ([string]::Equals($tok, 'Deleted', [System.StringComparison]::OrdinalIgnoreCase)) { $clr = '#ff3a3a' }
          [void]$rows.Add([pscustomobject]@{ Text = $tok; Color = $clr })
        }
        $x.PendingLabelRows = @($rows.ToArray())
      } catch {}
      try { Set-PropSafeGlobal -Obj $x -Name 'Selected' -Value ([bool]$s.PrevSelected) } catch {}
    }
  }
  try { Touch-VisualRuntimeState -Reason ("DragDropMove." + $Direction) } catch {}
  try { Queue-RebuildVisibleRows } catch {}
  try { Refresh-UIAsync } catch {}
}

function Invoke-DragDropMove {
  param(
    [Parameter(Mandatory=$true)][object[]]$SourceRows,
    [Parameter(Mandatory=$true)][object]$TargetFolderRow
  )
  $snapshot = New-Object System.Collections.Generic.List[object]
  $moved = 0
  foreach ($srcRow in @($SourceRows)) {
    if (-not (Test-IsDraggableLinkRow -Row $srcRow)) { continue }
    $srcPath = Normalize-Path ([string](Get-PropString -Obj $srcRow -Names @('Path','OriginalPath') -Fallback ''))
    if ([string]::IsNullOrWhiteSpace($srcPath)) { continue }
    $dstFolder = Resolve-DropTargetFolderForSource -TargetFolderRow $TargetFolderRow -SourceRow $srcRow
    if (-not $dstFolder) { continue }
    $srcScope = [string](Get-PropString -Obj $srcRow -Names @('Scope') -Fallback '')
    $dstScope = [string]$dstFolder.Scope
    $srcDir = Split-Path -Path $srcPath -Parent
    if (Test-PathEqualsCI -A $srcDir -B ([string]$dstFolder.FolderPath)) { continue }
    $ext = ''
    try { $ext = [string][IO.Path]::GetExtension($srcPath) } catch { $ext = '' }
    $newBase = (Trim-NameInputPreserveNbsp -Text ([string](Get-PropString -Obj $srcRow -Names @('Name') -Fallback '')))
    if (-not [string]::IsNullOrWhiteSpace($ext) -and $newBase.ToLowerInvariant().EndsWith($ext.ToLowerInvariant())) {
      $newBase = (Trim-NameInputPreserveNbsp -Text $newBase.Substring(0, $newBase.Length - $ext.Length))
    }
    if (-not (Test-ValidFileName -Name $newBase)) { continue }
    $newPath = Join-Path ([string]$dstFolder.FolderPath) ($newBase + $ext)
    if (Test-PathEqualsCI -A $newPath -B $srcPath) { continue }
    $srcId = [string](Get-PropString -Obj $srcRow -Names @('Id') -Fallback '')
    $origPath = Normalize-Path ([string](Get-PropString -Obj $srcRow -Names @('OriginalPath') -Fallback ''))
    $isReturnToOrigin = $false
    try { $isReturnToOrigin = (-not [string]::IsNullOrWhiteSpace($origPath) -and (Test-PathEqualsCI -A $newPath -B $origPath)) } catch { $isReturnToOrigin = $false }
    if ((Test-DragDropModelPathConflict -Scope ([string]$dstScope) -Path ([string]$newPath) -ExcludeId $srcId) -and (-not $isReturnToOrigin)) { continue }
    $prevSel = $false
    try {
      if ($srcRow.PSObject.Properties.Match('Selected').Count -gt 0) { $prevSel = [bool]$srcRow.Selected }
    } catch { $prevSel = $false }
    [void]$snapshot.Add([pscustomobject]@{
      Id           = [string](Get-PropString -Obj $srcRow -Names @('Id') -Fallback '')
      PrevPath     = [string]$srcPath
      PrevScope    = [string]$srcScope
      PrevAction   = [string](Get-PropString -Obj $srcRow -Names @('Action') -Fallback 'None')
      PrevPending  = [string](Get-PropString -Obj $srcRow -Names @('PendingLabel') -Fallback '')
      PrevSelected = [bool]$prevSel
      NewPath      = [string]$newPath
      NewScope     = [string]$dstScope
    })
    $moved++
  }
  if ($moved -le 0) { return 0 }
  # Make destination folder visibly expanded so moved rows appear indented immediately.
  try {
    if (Test-IsFolderDropTargetRow -Row $TargetFolderRow) {
      Set-PropSafeGlobal -Obj $TargetFolderRow -Name 'IsExpanded' -Value $true
      try { Sync-RowFolderChevronMeta -Row $TargetFolderRow } catch {}
      try { Refresh-RowFolderChevronBinding -Row $TargetFolderRow } catch {}
      if ($script:CurrentNode -and ([string]$script:CurrentNode.Scope -eq 'VisualMenu')) {
        $vk = Get-VisualFolderStateKey -Row $TargetFolderRow
        if ($vk) { $script:VisualExpandedState[$vk] = $true }
      }
    }
  } catch {}
  $snapArr = @($snapshot.ToArray())
  $op = [pscustomobject]@{
    Type = "DragDropMove"
    Snapshot = @($snapArr)
    Do = {
      param($snap)
      Apply-DragMoveSnapshot -Snapshot @($snap) -Direction Do
    }
    Undo = {
      param($snap)
      Apply-DragMoveSnapshot -Snapshot @($snap) -Direction Undo
    }
    DoArgs = ,@($snapArr)
    UndoArgs = ,@($snapArr)
  }
  Apply-DragMoveSnapshot -Snapshot @($snapArr) -Direction Do
  Push-UndoOp -op $op
  return $moved
}

function Invoke-DragDropMoveToRoot {
  param(
    [Parameter(Mandatory=$true)][object[]]$SourceRows
  )
  $snapshot = New-Object System.Collections.Generic.List[object]
  $moved = 0
  foreach ($srcRow in @($SourceRows)) {
    if (-not (Test-IsDraggableLinkRow -Row $srcRow)) { continue }
    $srcPath = Normalize-Path ([string](Get-PropString -Obj $srcRow -Names @('Path','OriginalPath') -Fallback ''))
    if ([string]::IsNullOrWhiteSpace($srcPath)) { continue }
    $dstFolder = Resolve-RootDropTargetForSource -SourceRow $srcRow
    if (-not $dstFolder) { continue }
    $srcScope = [string](Get-PropString -Obj $srcRow -Names @('Scope') -Fallback '')
    $dstScope = [string]$dstFolder.Scope
    if ($srcScope -ne $dstScope) { continue }
    $ext = ''
    try { $ext = [string][IO.Path]::GetExtension($srcPath) } catch { $ext = '' }
    $newBase = (Trim-NameInputPreserveNbsp -Text ([string](Get-PropString -Obj $srcRow -Names @('Name') -Fallback '')))
    if (-not [string]::IsNullOrWhiteSpace($ext) -and $newBase.ToLowerInvariant().EndsWith($ext.ToLowerInvariant())) {
      $newBase = (Trim-NameInputPreserveNbsp -Text $newBase.Substring(0, $newBase.Length - $ext.Length))
    }
    if (-not (Test-ValidFileName -Name $newBase)) { continue }
    $newPath = Join-Path ([string]$dstFolder.FolderPath) ($newBase + $ext)
    if (Test-PathEqualsCI -A $newPath -B $srcPath) { continue }
    $srcId = [string](Get-PropString -Obj $srcRow -Names @('Id') -Fallback '')
    $origPath = Normalize-Path ([string](Get-PropString -Obj $srcRow -Names @('OriginalPath') -Fallback ''))
    $isReturnToOrigin = $false
    try { $isReturnToOrigin = (-not [string]::IsNullOrWhiteSpace($origPath) -and (Test-PathEqualsCI -A $newPath -B $origPath)) } catch { $isReturnToOrigin = $false }
    if ((Test-DragDropModelPathConflict -Scope ([string]$dstScope) -Path ([string]$newPath) -ExcludeId $srcId) -and (-not $isReturnToOrigin)) { continue }
    $prevSel = $false
    try {
      if ($srcRow.PSObject.Properties.Match('Selected').Count -gt 0) { $prevSel = [bool]$srcRow.Selected }
    } catch { $prevSel = $false }
    [void]$snapshot.Add([pscustomobject]@{
      Id           = [string](Get-PropString -Obj $srcRow -Names @('Id') -Fallback '')
      PrevPath     = [string]$srcPath
      PrevScope    = [string]$srcScope
      PrevAction   = [string](Get-PropString -Obj $srcRow -Names @('Action') -Fallback 'None')
      PrevPending  = [string](Get-PropString -Obj $srcRow -Names @('PendingLabel') -Fallback '')
      PrevSelected = [bool]$prevSel
      NewPath      = [string]$newPath
      NewScope     = [string]$dstScope
    })
    $moved++
  }
  if ($moved -le 0) { return 0 }
  $snapArr = @($snapshot.ToArray())
  $op = [pscustomobject]@{
    Type = "DragDropMoveRoot"
    Snapshot = @($snapArr)
    Do = {
      param($snap)
      Apply-DragMoveSnapshot -Snapshot @($snap) -Direction Do
    }
    Undo = {
      param($snap)
      Apply-DragMoveSnapshot -Snapshot @($snap) -Direction Undo
    }
    DoArgs = ,@($snapArr)
    UndoArgs = ,@($snapArr)
  }
  Apply-DragMoveSnapshot -Snapshot @($snapArr) -Direction Do
  Push-UndoOp -op $op
  return $moved
}

function Get-GridMainScrollViewer {
  try {
    if ($script:GridMainScrollViewer -and ($script:GridMainScrollViewer -is [System.Windows.Controls.ScrollViewer])) {
      return $script:GridMainScrollViewer
    }
  } catch {}
  try {
    $sv = Find-VisualChild -Parent $grid -Type ([System.Windows.Controls.ScrollViewer])
    if ($sv) {
      try {
        if ($sv.HorizontalScrollBarVisibility -ne [System.Windows.Controls.ScrollBarVisibility]::Hidden) {
          $sv.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Hidden
        }
      } catch {}
      $script:GridMainScrollViewer = $sv
    }
    return $sv
  } catch {
    return $null
  }
}

function Get-GridColumnActualWidthByHeader {
  param([Parameter(Mandatory=$true)][string]$Header)
  try {
    if (-not $grid -or -not $grid.Columns) { return 0.0 }
    foreach ($c in @($grid.Columns)) {
      if (-not $c) { continue }
      $h = ''
      try { $h = [string]$c.Header } catch { $h = '' }
      if ($h -ne $Header) { continue }
      $w = 0.0
      try { $w = [double]$c.ActualWidth } catch { $w = 0.0 }
      if ($w -le 0.0) {
        try { $w = [double]$c.Width.DisplayValue } catch { $w = 0.0 }
      }
      return [double]$w
    }
  } catch {}
  return 0.0
}

function Update-GridSelectNameBandLayout {
  try {
    $band = $script:GridSelectNameBand
    if (-not $band) { return }
    if (-not $grid) { return }
    $headerH = 26.0
    $hp = $null
    try {
      $hp = Find-VisualChild -Parent $grid -Type ([System.Windows.Controls.Primitives.DataGridColumnHeadersPresenter])
      if ($hp -and $hp.ActualHeight -gt 0) { $headerH = [double]$hp.ActualHeight }
    } catch {}
    $left = 0.0
    try {
      if ($hp) {
        $pt = $hp.TranslatePoint([System.Windows.Point]::new(0.0, 0.0), $grid)
        $left = [double]$pt.X
      }
    } catch { $left = 0.0 }
    if ($left -lt 0.0) { $left = 0.0 }
    $selectStart = 0.0
    $nameEnd = 0.0
    $x = 0.0
    $foundSelect = $false
    $foundName = $false
    try {
      $ordered = @($grid.Columns | Sort-Object -Property DisplayIndex)
      foreach ($c in $ordered) {
        if (-not $c) { continue }
        $cw = 0.0
        try { $cw = [double]$c.ActualWidth } catch { $cw = 0.0 }
        if ($cw -le 0.0) { try { $cw = [double]$c.Width.DisplayValue } catch { $cw = 0.0 } }
        $hdr = ''
        try { $hdr = [string]$c.Header } catch { $hdr = '' }
        if (-not $foundSelect -and $hdr -eq 'Select') { $selectStart = $x; $foundSelect = $true }
        $x += [double]$cw
        if ($hdr -eq 'Name') { $nameEnd = $x; $foundName = $true }
      }
    } catch {}
    if (-not $foundName) {
      try { $band.Visibility = [System.Windows.Visibility]::Collapsed } catch {}
      return
    }
    if (-not $foundSelect) { $selectStart = 0.0 }
    $bandW = [double]([Math]::Max(0.0, ([double]$nameEnd - [double]$selectStart)))
    if ($bandW -lt 1.0) {
      try { $band.Visibility = [System.Windows.Visibility]::Collapsed } catch {}
      return
    }
    $bandLeft = [double]$left + [double]$selectStart
    if ($bandLeft -lt 0.0) { $bandLeft = 0.0 }
    $gridW = 0.0
    try { $gridW = [double]$grid.ActualWidth } catch { $gridW = 0.0 }
    if ($gridW -gt 0.0 -and (($bandLeft + $bandW) -gt $gridW)) {
      $bandW = [double]([Math]::Max(0.0, ([double]$gridW - [double]$bandLeft)))
    }
    $maskTop = [double]([Math]::Max(0.0, ([double]$headerH + [double]$script:GridTopOverlayTopPadPx)))
    $maskH = 0.0
    try { $maskH = [double]$script:GridTopMaskHeightPx } catch { $maskH = 0.0 }
    if ($maskH -lt 0.0) { $maskH = 0.0 }
    $top = [double]([Math]::Max(0.0, ([double]$maskTop + [double]$maskH)))
    $bottom = 0.0
    try {
      $sv = Get-GridMainScrollViewer
      if ($sv -and $sv.ComputedHorizontalScrollBarVisibility -eq [System.Windows.Visibility]::Visible) {
        $bottom = [double][SystemParameters]::HorizontalScrollBarHeight
      }
    } catch {}
    try {
      $band.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Left
      $band.VerticalAlignment = [System.Windows.VerticalAlignment]::Stretch
      $band.Margin = [System.Windows.Thickness]::new([double]$bandLeft, [double]$top, 0.0, [double]$bottom)
      $band.Width = [double]$bandW
      $band.Visibility = [System.Windows.Visibility]::Visible
    } catch {}
  } catch {}
}

function Update-GridTopDataSpacerLayout {
  try {
    if (-not $grid) { return }
    $sv = $null
    try { $sv = Get-GridMainScrollViewer } catch { $sv = $null }
    $rowsPresenter = $null
    try {
      $rowsPresenter = Find-VisualChild -Parent $grid -Type ([System.Windows.Controls.Primitives.DataGridRowsPresenter])
    } catch {}
    if (-not $rowsPresenter -and -not $sv) { return }
    $maskH = 40.0
    try { $maskH = [double]$script:GridTopMaskHeightPx } catch { $maskH = 40.0 }
    if ($maskH -lt 0.0) { $maskH = 0.0 }
    # Keep ScrollViewer padding neutral (some DataGrid templates ignore it for rows).
    try {
      if ($sv) {
        $pm = $sv.Padding
        $pl = 0.0; $pt = 0.0; $pr = 0.0; $pb = 0.0
        try { $pl = [double]$pm.Left } catch {}
        try { $pt = [double]$pm.Top } catch {}
        try { $pr = [double]$pm.Right } catch {}
        try { $pb = [double]$pm.Bottom } catch {}
        if ([Math]::Abs(([double]$pt - 0.0)) -gt 0.1) {
          $sv.Padding = [System.Windows.Thickness]::new($pl, 0.0, $pr, $pb)
        }
      }
    } catch {}
    # Apply visual-only offset to scroll content so rows stay below mask without layout feedback.
    $contentY = [double]$maskH
    try { $contentY += [double]$script:GridTopMaskContentOffsetPx } catch {}
    if ($contentY -lt 0.0) { $contentY = 0.0 }
    $scp = $null
    try { $scp = Find-VisualChild -Parent $grid -Type ([System.Windows.Controls.ScrollContentPresenter]) } catch {}
    if ($scp) {
      try {
        $mScp = $scp.Margin
        $lScp = 0.0; $tScp = 0.0; $rScp = 0.0; $bScp = 0.0
        try { $lScp = [double]$mScp.Left } catch {}
        try { $tScp = [double]$mScp.Top } catch {}
        try { $rScp = [double]$mScp.Right } catch {}
        try { $bScp = [double]$mScp.Bottom } catch {}
        if ([Math]::Abs(([double]$tScp - [double]$contentY)) -gt 0.1) {
          $scp.Margin = [System.Windows.Thickness]::new($lScp, [double]$contentY, $rScp, $bScp)
        }
      } catch {}
      try {
        $rtScp = $scp.RenderTransform
        if ($rtScp -is [System.Windows.Media.TranslateTransform]) {
          if ([Math]::Abs(([double]$rtScp.Y - 0.0)) -gt 0.1) { $rtScp.Y = 0.0 }
        }
      } catch {}
      try { $scp.Clip = $null } catch {}
    }
    # Keep rows presenter neutral (no additional offset here).
    if ($rowsPresenter) {
      $m = $rowsPresenter.Margin
      $left = 0.0; $right = 0.0; $bottom = 0.0; $top = 0.0
      try { $left = [double]$m.Left } catch {}
      try { $top = [double]$m.Top } catch {}
      try { $right = [double]$m.Right } catch {}
      try { $bottom = [double]$m.Bottom } catch {}
      if ([Math]::Abs(([double]$top - 0.0)) -gt 0.1) {
        $rowsPresenter.Margin = [System.Windows.Thickness]::new($left, 0.0, $right, $bottom)
      }
      try {
        $rt = $rowsPresenter.RenderTransform
        if ($rt -is [System.Windows.Media.TranslateTransform]) {
          if ([Math]::Abs(([double]$rt.Y - 0.0)) -gt 0.1) { $rt.Y = 0.0 }
        }
      } catch {}
      try { $rowsPresenter.Clip = $null } catch {}
    }
  } catch {}
}

function Update-GridTopOverlayLayout {
  try {
    $ov = $script:GridTopOverlay
    if (-not $ov) { return }
    if (-not $grid) { return }
    $headerH = 26.0
    $hp = $null
    try {
      $hp = Find-VisualChild -Parent $grid -Type ([System.Windows.Controls.Primitives.DataGridColumnHeadersPresenter])
      if ($hp -and $hp.ActualHeight -gt 0) { $headerH = [double]$hp.ActualHeight }
    } catch {}
    $rowH = 40.0
    try { $rowH = [double]$script:GridTopMaskHeightPx } catch { $rowH = 40.0 }
    if ($rowH -lt 0.0) { $rowH = 0.0 }
    $top = 0.0
    try { $top = [Math]::Max(0.0, ([double]$headerH + [double]$script:GridTopOverlayTopPadPx)) } catch { $top = [double]$headerH }
    $bottom = 0.0
    try { $bottom = [Math]::Max(0.0, [double]$script:GridTopOverlayBottomPadPx) } catch { $bottom = 0.0 }
    $left = 0.0
    $viewportW = 0.0
    try {
      if ($hp) {
        $pt = $hp.TranslatePoint([System.Windows.Point]::new(0.0, 0.0), $grid)
        $left = [double]$pt.X
      }
    } catch { $left = 0.0 }
    if ($left -lt 0.0) { $left = 0.0 }
    try {
      if ($hp -and $hp.ActualWidth -gt 0) { $viewportW = [double]$hp.ActualWidth }
    } catch {}
    if ($viewportW -le 0.0) {
      try { $viewportW = [double]$grid.ActualWidth } catch { $viewportW = 0.0 }
      try {
        $sv = Get-GridMainScrollViewer
        if ($sv -and $sv.ComputedVerticalScrollBarVisibility -eq [System.Windows.Visibility]::Visible) {
          $viewportW = [Math]::Max(0.0, ([double]$viewportW - [double][SystemParameters]::VerticalScrollBarWidth))
        }
      } catch {}
    }
    # Cover full visible grid viewport width.
    $overlayW = 0.0
    try { $overlayW = [double]$viewportW } catch { $overlayW = 0.0 }
    if ($overlayW -le 0.0) {
      try { $overlayW = [double]$grid.ActualWidth } catch { $overlayW = 0.0 }
    }
    $gridW = 0.0
    try { $gridW = [double]$grid.ActualWidth } catch { $gridW = 0.0 }
    if ($gridW -gt 0.0 -and (($left + $overlayW) -gt $gridW)) {
      $overlayW = [Math]::Max(0.0, ([double]$gridW - [double]$left))
    }
    if ($viewportW -gt 0.0 -and $overlayW -gt $viewportW) {
      $overlayW = [double]$viewportW
    }
    try {
      $ov.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Left
      $ov.VerticalAlignment = [System.Windows.VerticalAlignment]::Top
      $ov.IsHitTestVisible = $false
      $ov.Width = [double]$overlayW
      $ov.Height = [double]$rowH
      $ov.Margin = [System.Windows.Thickness]::new([double]$left, [double]$top, 0, [double]$bottom)
    } catch {}
  } catch {}
}

function Update-GridTopMaskResizeThumbLayout {
  try {
    $th = $script:GridTopMaskResizeThumb
    if (-not $th) { return }
    if (-not $grid) { return }
    $headerH = 26.0
    $hp = $null
    try {
      $hp = Find-VisualChild -Parent $grid -Type ([System.Windows.Controls.Primitives.DataGridColumnHeadersPresenter])
      if ($hp -and $hp.ActualHeight -gt 0) { $headerH = [double]$hp.ActualHeight }
    } catch {}
    $left = 0.0
    try {
      if ($hp) {
        $pt = $hp.TranslatePoint([System.Windows.Point]::new(0.0, 0.0), $grid)
        $left = [double]$pt.X
      }
    } catch { $left = 0.0 }
    if ($left -lt 0.0) { $left = 0.0 }
    $selectStart = 0.0
    $nameEnd = 0.0
    $x = 0.0
    $foundSelect = $false
    $foundName = $false
    try {
      $ordered = @($grid.Columns | Sort-Object -Property DisplayIndex)
      foreach ($c in $ordered) {
        if (-not $c) { continue }
        $cw = 0.0
        try { $cw = [double]$c.ActualWidth } catch { $cw = 0.0 }
        if ($cw -le 0.0) { try { $cw = [double]$c.Width.DisplayValue } catch { $cw = 0.0 } }
        $hdr = ''
        try { $hdr = [string]$c.Header } catch { $hdr = '' }
        if (-not $foundSelect -and $hdr -eq 'Select') { $selectStart = $x; $foundSelect = $true }
        $x += [double]$cw
        if ($hdr -eq 'Name') { $nameEnd = $x; $foundName = $true }
      }
    } catch {}
    if (-not $foundName) { return }
    if (-not $foundSelect) { $selectStart = 0.0 }
    $thumbW = [double]([Math]::Max(0.0, ([double]$nameEnd - [double]$selectStart)))
    if ($thumbW -lt 40.0) { $thumbW = 40.0 }
    $left = [double]$left + [double]$selectStart
    if ($left -lt 0.0) { $left = 0.0 }
    $maskH = 40.0
    try { $maskH = [double]$script:GridTopMaskHeightPx } catch { $maskH = 40.0 }
    if ($maskH -lt 0.0) { $maskH = 0.0 }
    $top = 0.0
    try { $top = [Math]::Max(0.0, ([double]$headerH + [double]$script:GridTopOverlayTopPadPx + [double]$maskH - 3.0)) } catch { $top = [double]$headerH }
    $gridW = 0.0
    try { $gridW = [double]$grid.ActualWidth } catch { $gridW = 0.0 }
    if ($gridW -gt 0.0 -and (($left + $thumbW) -gt $gridW)) {
      $thumbW = [Math]::Max(0.0, ([double]$gridW - [double]$left))
    }
    try {
      $th.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Left
      $th.VerticalAlignment = [System.Windows.VerticalAlignment]::Top
      $th.Width = [double]$thumbW
      $th.Height = 6.0
      $th.Margin = [System.Windows.Thickness]::new([double]$left, [double]$top, 0.0, 0.0)
      $th.Cursor = [System.Windows.Input.Cursors]::SizeNS
    } catch {}
  } catch {}
}

if ($script:GridTopMaskResizeThumb) {
  $script:GridTopMaskResizeThumb.Add_DragDelta({
    param($sender, $e)
    try {
      $cur = 40.0
      try { $cur = [double]$script:GridTopMaskHeightPx } catch { $cur = 40.0 }
      $next = [double]$cur + [double]$e.VerticalChange

      $minH = 8.0
      $maxH = 180.0
      try { $minH = [double]$script:GridTopMaskMinHeightPx } catch { $minH = 8.0 }
      try {
        # Interpret GridTopMaskMaxHeightPx as minimum remaining height from the BOTTOM
        # of the rows viewport, not as a top-based max mask height.
        $bottomClear = [double]$script:GridTopMaskMaxHeightPx
        if ($bottomClear -lt 0.0) { $bottomClear = 0.0 }
        # Stable max mask height from grid geometry (independent of scrolling/padding feedback).
        $rowsAreaH = 0.0
        try {
          $headerH = 26.0
          $hp = Find-VisualChild -Parent $grid -Type ([System.Windows.Controls.Primitives.DataGridColumnHeadersPresenter])
          if ($hp -and $hp.ActualHeight -gt 0) { $headerH = [double]$hp.ActualHeight }
          $gH = 0.0
          try { $gH = [double]$grid.ActualHeight } catch { $gH = 0.0 }
          if ($gH -gt 0.0) { $rowsAreaH = [double]([Math]::Max(0.0, ([double]$gH - [double]$headerH))) }
        } catch { $rowsAreaH = 0.0 }
        if ($rowsAreaH -gt 0.0) {
          $maxH = [double]([Math]::Max([double]$minH, ([double]$rowsAreaH - [double]$bottomClear)))
        } else {
          # Fallback if not measured yet.
          $maxH = [double]$script:GridTopMaskMaxHeightPx
        }
      } catch { $maxH = 180.0 }
      if ($maxH -lt $minH) { $maxH = $minH }

      if ($next -lt $minH) { $next = $minH }
      if ($next -gt $maxH) { $next = $maxH }
      $eps = 0.05
      # If clamped value did not actually change, do nothing; avoids max-boundary jitter.
      if ([Math]::Abs(([double]$next - [double]$cur)) -lt $eps) { return }
      $script:GridTopMaskHeightPx = [double]$next

      try { Update-GridTopDataSpacerLayout } catch {}
      try { Update-GridTopOverlayLayout } catch {}
      try { Update-GridSelectNameBandLayout } catch {}
      try { Update-GridTopMaskResizeThumbLayout } catch {}
      try { Update-MidGridScrollBarLayout } catch {}
      try { Sync-MidGridScrollBarFromViewer -LayoutUpdate:$false } catch {}
      try { if ($script:GridMidScrollBar) { $script:GridMidScrollBar.InvalidateMeasure(); $script:GridMidScrollBar.InvalidateArrange() } } catch {}
      try { if ($grid) { $grid.InvalidateVisual() } } catch {}
      try { Queue-MidGridSync -NeedLayout:$true } catch {}
    } catch {}
  })
}

if ($script:GridNameResizeThumb) {
  $script:GridNameResizeThumb.Add_DragDelta({
    param($sender, $e)
    try {
      $nameCol = Get-GridNameColumn
      if (-not $nameCol) { return }

      $curW = 0.0
      try { $curW = [double]$nameCol.ActualWidth } catch { $curW = 0.0 }
      if ($curW -le 0.0) {
        try { $curW = [double]$nameCol.Width.DisplayValue } catch { $curW = 0.0 }
      }
      if ($curW -le 0.0) { $curW = 256.0 }

      $minW = 256.0
      try { $minW = [double]$script:GridNameMinWidthPx } catch { $minW = 256.0 }
      if ($minW -lt 32.0) { $minW = 32.0 }
      try { if ([double]$nameCol.MinWidth -lt $minW) { $nameCol.MinWidth = [double]$minW } } catch {}

      $nextW = [double]$curW + [double]$e.HorizontalChange
      if ($nextW -lt $minW) { $nextW = $minW }

      $nameCol.Width = [System.Windows.Controls.DataGridLength]::new([double]$nextW, [System.Windows.Controls.DataGridLengthUnitType]::Pixel)

      try { Update-GridSelectNameBandLayout } catch {}
      try { Update-GridTopMaskResizeThumbLayout } catch {}
      try { Update-MidGridScrollBarLayout } catch {}
      try { Update-GridNameResizeThumbLayout } catch {}
      try { Sync-MidGridScrollBarFromViewer -LayoutUpdate:$false } catch {}
      try { if ($grid) { $grid.InvalidateVisual() } } catch {}
    } catch {}
  })
}

function Ensure-MidGridScrollBarSlideTransform {
  try {
    $sb = $script:GridMidScrollBar
    if (-not $sb) { return $null }
    $tx = $script:GridMidScrollBarSlideTransform -as [System.Windows.Media.TranslateTransform]
    if (-not $tx) {
      try {
        $rt = $sb.RenderTransform
        if ($rt -is [System.Windows.Media.TransformGroup]) {
          foreach ($child in @($rt.Children)) {
            if ($child -is [System.Windows.Media.TranslateTransform]) { $tx = $child; break }
          }
        } elseif ($rt -is [System.Windows.Media.TranslateTransform]) {
          $tx = $rt
        }
      } catch {}
    }
    if (-not $tx) {
      $grp = New-Object System.Windows.Media.TransformGroup
      $sc = New-Object System.Windows.Media.ScaleTransform(0.80, 1.0)
      $tx = New-Object System.Windows.Media.TranslateTransform
      $tx.X = 0.0
      [void]$grp.Children.Add($sc)
      [void]$grp.Children.Add($tx)
      $sb.RenderTransform = $grp
      $sb.RenderTransformOrigin = [System.Windows.Point]::new(0.5, 0.5)
    }
    $script:GridMidScrollBarSlideTransform = $tx
    return $tx
  } catch {
    return $null
  }
}

function Ensure-MidGridScrollBarScaleTransform {
  try {
    $sb = $script:GridMidScrollBar
    if (-not $sb) { return $null }
    $sc = $script:GridMidScrollBarScaleTransform -as [System.Windows.Media.ScaleTransform]
    if (-not $sc) {
      try {
        $rt = $sb.RenderTransform
        if ($rt -is [System.Windows.Media.TransformGroup]) {
          foreach ($child in @($rt.Children)) {
            if ($child -is [System.Windows.Media.ScaleTransform]) { $sc = $child; break }
          }
        } elseif ($rt -is [System.Windows.Media.ScaleTransform]) {
          $sc = $rt
        }
      } catch {}
    }
    if (-not $sc) {
      $grp = New-Object System.Windows.Media.TransformGroup
      $sc = New-Object System.Windows.Media.ScaleTransform(0.80, 1.0)
      $tx = New-Object System.Windows.Media.TranslateTransform
      $tx.X = 0.0
      [void]$grp.Children.Add($sc)
      [void]$grp.Children.Add($tx)
      $sb.RenderTransform = $grp
      $sb.RenderTransformOrigin = [System.Windows.Point]::new(1.0, 0.5)
      $script:GridMidScrollBarSlideTransform = $tx
    } else {
      try { $sb.RenderTransformOrigin = [System.Windows.Point]::new(1.0, 0.5) } catch {}
    }
    $script:GridMidScrollBarScaleTransform = $sc
    return $sc
  } catch {
    return $null
  }
}

function Get-MidGridScrollBarHideOffsetPx {
  try {
    $manual = 0.0
    try { $manual = [double]$script:GridMidScrollBarSlideHideOffsetPx } catch { $manual = 0.0 }
    if ($manual -gt 0.0) { return [double]$manual }
    $w = 5.0
    try { $w = [double]$script:GridMidScrollBarWidthPx } catch { $w = 5.0 }
    if ($w -lt 1.0) { $w = 1.0 }
    $off = 11.0
    try { $off = [Math]::Abs([double]$script:GridMidScrollBarOffsetXPx) } catch { $off = 11.0 }
    $auto = [double]$w + [double]$off
    if ($auto -lt 8.0) { $auto = 8.0 }
    return $auto
  } catch {
    return 16.0
  }
}

function Test-MidGridScrollBarNeeded {
  param([System.Windows.Controls.ScrollViewer]$ScrollViewer = $null)
  try {
    $sv = $ScrollViewer
    if (-not $sv) { $sv = Get-GridMainScrollViewer }
    if (-not $sv) { return $false }
    $scrollable = 0.0
    try { $scrollable = [double]$sv.ScrollableHeight } catch { $scrollable = 0.0 }
    if ($scrollable -lt 0.0) { $scrollable = 0.0 }
    $extentDelta = 0.0
    try { $extentDelta = [double]$sv.ExtentHeight - [double]$sv.ViewportHeight } catch { $extentDelta = 0.0 }
    if ($extentDelta -lt 0.0) { $extentDelta = 0.0 }
    $rawScrollable = [Math]::Max([double]$scrollable, [double]$extentDelta)
    $maskAdj = 0.0
    try { $maskAdj = [Math]::Max(0.0, [double]$script:GridTopMaskHeightPx) } catch { $maskAdj = 0.0 }
    $effectiveScrollable = [Math]::Max(0.0, ([double]$rawScrollable - [double]$maskAdj))
    $threshold = 1.0
    try { $threshold = [double]$script:GridMidScrollBarShowThresholdPx } catch { $threshold = 1.0 }
    if ($threshold -lt 0.0) { $threshold = 0.0 }
    return ($effectiveScrollable -gt $threshold)
  } catch {
    return $false
  }
}

function Set-MidGridScrollBarAnimatedVisibility {
  param([bool]$Show)
  try {
    $sb = $script:GridMidScrollBar
    if (-not $sb) { return }
    $sc = Ensure-MidGridScrollBarScaleTransform
    $script:GridMidScrollBarDesiredVisible = [bool]$Show
    $targetVisibleOpacity = 0.90
    try { $targetVisibleOpacity = [double]$script:GridMidScrollBarVisibleOpacity } catch { $targetVisibleOpacity = 0.90 }
    if ($targetVisibleOpacity -lt 0.0) { $targetVisibleOpacity = 0.0 }
    if ($targetVisibleOpacity -gt 1.0) { $targetVisibleOpacity = 1.0 }
    $fullW = 5.0
    try { $fullW = [double]$script:GridMidScrollBarWidthPx } catch { $fullW = 5.0 }
    if ($fullW -lt 1.0) { $fullW = 1.0 }
    $minW = 1.0
    try { $minW = [double]$script:GridMidScrollBarMinVisualWidthPx } catch { $minW = 1.0 }
    if ($minW -lt 0.5) { $minW = 0.5 }
    if ($minW -gt $fullW) { $minW = $fullW }
    $visibleScale = 0.80
    try { $visibleScale = [double]$script:GridMidScrollBarVisibleScaleX } catch { $visibleScale = 0.80 }
    if ($visibleScale -lt 0.05) { $visibleScale = 0.05 }
    if ($visibleScale -gt 1.50) { $visibleScale = 1.50 }
    $collapsedScale = 0.08
    try { $collapsedScale = [double]$script:GridMidScrollBarCollapsedScaleX } catch { $collapsedScale = 0.08 }
    if ($collapsedScale -lt 0.01) { $collapsedScale = 0.01 }
    if ($collapsedScale -gt $visibleScale) { $collapsedScale = [Math]::Max(0.01, ($visibleScale * 0.2)) }
    try { if ($sb.RenderTransformOrigin.X -ne 1.0 -or $sb.RenderTransformOrigin.Y -ne 0.5) { $sb.RenderTransformOrigin = [System.Windows.Point]::new(1.0, 0.5) } } catch {}
    $visVisible = [System.Windows.Visibility]::Visible
    $visCollapsed = [System.Windows.Visibility]::Collapsed
    $sameState = $false
    try { $sameState = ($script:GridMidScrollBarLastVisibleState -eq [bool]$Show) } catch { $sameState = $false }
    if ($sameState) {
      if ($Show) {
        if ($sb.Visibility -ne $visVisible) { try { $sb.Visibility = $visVisible } catch {} }
        if (-not [bool]$script:GridMidScrollBarWidthAnimating) {
          try { $sb.Width = [double]$fullW } catch {}
          if ($sc) { try { $sc.ScaleX = [double]$visibleScale } catch {} }
        }
        try { $sb.Opacity = [double]$targetVisibleOpacity } catch {}
        try { $sb.IsHitTestVisible = $true } catch {}
      } else {
        if (-not [bool]$script:GridMidScrollBarWidthAnimating) {
          try { $sb.Width = [double]$minW } catch {}
          if ($sc) { try { $sc.ScaleX = [double]$collapsedScale } catch {} }
          try { $sb.Opacity = 0.0 } catch {}
          try { $sb.Visibility = $visCollapsed } catch {}
          try { $sb.IsHitTestVisible = $false } catch {}
        }
      }
      return
    }
    $script:GridMidScrollBarLastVisibleState = [bool]$Show
    $fromW = [double]$minW
    try {
      $probe = [double]$sb.Width
      if ($probe -gt 0.0) { $fromW = $probe }
    } catch {}
    if ($fromW -lt $minW) { $fromW = [double]$minW }
    if ($fromW -gt $fullW) { $fromW = [double]$fullW }
    $toW = if ($Show) { [double]$fullW } else { [double]$minW }
    $fromScale = if ($Show) { [double]$collapsedScale } else { [double]$visibleScale }
    if ($sc) {
      try { $fromScale = [double]$sc.ScaleX } catch { $fromScale = if ($Show) { [double]$collapsedScale } else { [double]$visibleScale } }
    }
    $toScale = if ($Show) { [double]$visibleScale } else { [double]$collapsedScale }
    $startOpacity = 0.12
    try { $startOpacity = [double]$script:GridMidScrollBarAppearStartOpacity } catch { $startOpacity = 0.12 }
    if ($startOpacity -lt 0.0) { $startOpacity = 0.0 }
    if ($startOpacity -gt $targetVisibleOpacity) { $startOpacity = $targetVisibleOpacity }
    if ($Show) {
      if ($sb.Visibility -ne $visVisible) {
        try { $sb.Width = [double]$minW } catch {}
        if ($sc) { try { $sc.ScaleX = [double]$collapsedScale } catch {} }
        try { $sb.Opacity = [double]$startOpacity } catch {}
        try { $sb.Visibility = $visVisible } catch {}
        $fromW = [double]$minW
        $fromScale = [double]$collapsedScale
      }
      try { $sb.IsHitTestVisible = $true } catch {}
    } else {
      try { $sb.IsHitTestVisible = $false } catch {}
      if ($sb.Visibility -ne $visVisible) {
        try { $sb.Width = [double]$minW } catch {}
        if ($sc) { try { $sc.ScaleX = [double]$collapsedScale } catch {} }
        try { $sb.Opacity = 0.0 } catch {}
        try { $sb.Visibility = $visCollapsed } catch {}
        return
      }
    }
    if ([Math]::Abs(([double]$fromW - [double]$toW)) -le 0.05) {
      try { $sb.Width = [double]$toW } catch {}
      if ($sc) { try { $sc.ScaleX = [double]$toScale } catch {} }
      if ($Show) {
        try { $sb.Opacity = [double]$targetVisibleOpacity } catch {}
      } else {
        try { $sb.Opacity = 0.0 } catch {}
      }
      if (-not $Show) {
        try { $sb.Visibility = $visCollapsed } catch {}
      }
      return
    }
    try { $script:GridMidScrollBarAnimToken = [int]$script:GridMidScrollBarAnimToken + 1 } catch { $script:GridMidScrollBarAnimToken = 1 }
    $token = [int]$script:GridMidScrollBarAnimToken
    $durMs = 700.0
    try { $durMs = [double]$script:GridMidScrollBarSlideDurationMs } catch { $durMs = 700.0 }
    if ($durMs -lt 1.0) { $durMs = 1.0 }
    $anim = New-Object System.Windows.Media.Animation.DoubleAnimation
    $anim.From = [double]$fromW
    $anim.To = [double]$toW
    $anim.Duration = New-Object System.Windows.Duration([TimeSpan]::FromMilliseconds($durMs))
    $anim.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::HoldEnd
    $ease = New-Object System.Windows.Media.Animation.CubicEase
    $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    $anim.EasingFunction = $ease
    $script:GridMidScrollBarWidthAnimating = $true
    $anim.Add_Completed({
      try {
        $script:GridMidScrollBarWidthAnimating = $false
        if ([int]$script:GridMidScrollBarAnimToken -ne [int]$token) { return }
        if (-not [bool]$script:GridMidScrollBarDesiredVisible -and $sb) {
          try { $sb.Width = [double]$minW } catch {}
          if ($sc) { try { $sc.ScaleX = [double]$collapsedScale } catch {} }
          try { $sb.Opacity = 0.0 } catch {}
          try { $sb.Visibility = $visCollapsed } catch {}
        } elseif ($sb) {
          try { $sb.Width = [double]$fullW } catch {}
          if ($sc) { try { $sc.ScaleX = [double]$visibleScale } catch {} }
          try { $sb.Opacity = [double]$targetVisibleOpacity } catch {}
          try { $sb.Visibility = $visVisible } catch {}
        }
      } catch {}
    })
    $sb.BeginAnimation([System.Windows.FrameworkElement]::WidthProperty, $anim, [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
    if ($sc) {
      $sAnim = New-Object System.Windows.Media.Animation.DoubleAnimation
      $sAnim.From = [double]$fromScale
      $sAnim.To = [double]$toScale
      $sAnim.Duration = New-Object System.Windows.Duration([TimeSpan]::FromMilliseconds($durMs))
      $sAnim.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::HoldEnd
      $sAnim.EasingFunction = $ease
      $sc.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $sAnim, [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
    }
    $fromOpacity = if ($Show) { [double]$startOpacity } else { [double]$targetVisibleOpacity }
    $toOpacity = if ($Show) { [double]$targetVisibleOpacity } else { 0.0 }
    $opAnim = New-Object System.Windows.Media.Animation.DoubleAnimation
    $opAnim.From = [double]$fromOpacity
    $opAnim.To = [double]$toOpacity
    $opAnim.Duration = New-Object System.Windows.Duration([TimeSpan]::FromMilliseconds($durMs))
    $opAnim.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::HoldEnd
    $opAnim.EasingFunction = $ease
    $sb.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $opAnim, [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
  } catch {}
}

function Update-MidGridScrollBarLayout {
  try {
    $sb = $script:GridMidScrollBar
    if (-not $sb) { return }
    if (-not $grid) { return }
    try {
      $need = Test-MidGridScrollBarNeeded
      Set-MidGridScrollBarAnimatedVisibility -Show:[bool]$need
      if (-not $need) { return }
    } catch {}
    $w = 5.0
    try { $w = [double]$script:GridMidScrollBarWidthPx } catch { $w = 5.0 }
    if ($w -lt 1.0) { $w = 1.0 }
    # Place at the trailing edge of Name column (inside Name),
    # based on actual display order.
    $nameBoundary = 0.0
    try {
      $nameCol = $null
      foreach ($c in @($grid.Columns)) {
        if ([string]$c.Header -eq 'Name') { $nameCol = $c; break }
      }
      if ($nameCol) {
        $ordered = @($grid.Columns | Sort-Object -Property DisplayIndex)
        foreach ($c in $ordered) {
          $cw = 0.0
          try { $cw = [double]$c.ActualWidth } catch { $cw = 0.0 }
          if ($cw -le 0.0) {
            try { $cw = [double]$c.Width.DisplayValue } catch { $cw = 0.0 }
          }
          $nameBoundary += [double]$cw
          if ($c -eq $nameCol) { break }
        }
      }
    } catch { $nameBoundary = 0.0 }
    if ($nameBoundary -le 0.0) {
      $nameBoundary += (Get-GridColumnActualWidthByHeader -Header 'Select')
      $nameBoundary += (Get-GridColumnActualWidthByHeader -Header 'Pending')
      $nameBoundary += (Get-GridColumnActualWidthByHeader -Header 'Name')
    }
    $left = [double]$nameBoundary - [double]$w
    try { $left += [double]$script:GridMidScrollBarOffsetXPx } catch { $left -= 1.0 }
    if ($left -lt 0) { $left = 0.0 }
    $headerH = 26.0
    try {
      $hp = Find-VisualChild -Parent $grid -Type ([System.Windows.Controls.Primitives.DataGridColumnHeadersPresenter])
      if ($hp -and $hp.ActualHeight -gt 0) { $headerH = [double]$hp.ActualHeight }
    } catch {}
    $topPad = 0.0
    try { $topPad = [Math]::Max(0.0, ([double]$headerH + [double]$script:GridMidScrollBarTopPadPx)) } catch { $topPad = [Math]::Max(0.0, ($headerH + 1.0)) }
    try {
      $maskTop = [Math]::Max(0.0, ([double]$headerH + [double]$script:GridTopOverlayTopPadPx))
      $maskH = 0.0
      try { $maskH = [double]$script:GridTopMaskHeightPx } catch { $maskH = 0.0 }
      if ($maskH -lt 0.0) { $maskH = 0.0 }
      $maskBottom = [double]$maskTop + [double]$maskH
      if ($topPad -lt $maskBottom) { $topPad = $maskBottom }
    } catch {}
    $bottomPad = 2.0
    try { $bottomPad = [double]$script:GridMidScrollBarBottomPadPx } catch { $bottomPad = 2.0 }
    try {
      $sv = Get-GridMainScrollViewer
      if ($sv -and $sv.ComputedHorizontalScrollBarVisibility -eq [System.Windows.Visibility]::Visible) {
        $bottomPad += [double][SystemParameters]::HorizontalScrollBarHeight
      }
    } catch {}
    try {
      $allowDirectWidth = $true
      try { $allowDirectWidth = -not [bool]$script:GridMidScrollBarWidthAnimating } catch { $allowDirectWidth = $true }
      if ($allowDirectWidth -and [bool]$script:GridMidScrollBarDesiredVisible -and $sb.Visibility -eq [System.Windows.Visibility]::Visible) {
        if ([Math]::Abs(([double]$sb.Width - [double]$w)) -gt 0.05) { $sb.Width = [double]$w }
      }
      # Keep fixed visible opacity only while in visible mode; hide/show animation controls opacity otherwise.
      $isVisibleMode = $false
      try { $isVisibleMode = [bool]$script:GridMidScrollBarDesiredVisible } catch { $isVisibleMode = $false }
      if ($isVisibleMode) {
        $visOp = 0.90
        try { $visOp = [double]$script:GridMidScrollBarVisibleOpacity } catch { $visOp = 0.90 }
        if ($visOp -lt 0.0) { $visOp = 0.0 }
        if ($visOp -gt 1.0) { $visOp = 1.0 }
        if ([Math]::Abs(([double]$sb.Opacity - [double]$visOp)) -gt 0.01) { $sb.Opacity = [double]$visOp }
      }
      $curM = $sb.Margin
      $newM = [System.Windows.Thickness]::new([double]$left, [double]$topPad, 0, [double]$bottomPad)
      $sameM = $false
      try {
        $sameM =
          ([Math]::Abs(([double]$curM.Left   - [double]$newM.Left  )) -lt 0.1) -and
          ([Math]::Abs(([double]$curM.Top    - [double]$newM.Top   )) -lt 0.1) -and
          ([Math]::Abs(([double]$curM.Right  - [double]$newM.Right )) -lt 0.1) -and
          ([Math]::Abs(([double]$curM.Bottom - [double]$newM.Bottom)) -lt 0.1)
      } catch { $sameM = $false }
      if (-not $sameM) { $sb.Margin = $newM }
      try { Update-GridSelectNameBandLayout } catch {}
      try { Update-GridNameResizeThumbLayout } catch {}
    } catch {}
  } catch {}
}

function Update-GridNameResizeThumbLayout {
  try {
    $th = $script:GridNameResizeThumb
    if (-not $th) { return }
    if (-not $grid) { return }
    $w = 10.0
    try { $w = [double]$script:GridNameResizeThumbWidthPx } catch { $w = 10.0 }
    if ($w -lt 4.0) { $w = 4.0 }
    # Name trailing boundary by display order.
    $nameBoundary = 0.0
    try {
      $nameCol = $null
      foreach ($c in @($grid.Columns)) {
        if ([string]$c.Header -eq 'Name') { $nameCol = $c; break }
      }
      if ($nameCol) {
        $ordered = @($grid.Columns | Sort-Object -Property DisplayIndex)
        foreach ($c in $ordered) {
          $cw = 0.0
          try { $cw = [double]$c.ActualWidth } catch { $cw = 0.0 }
          if ($cw -le 0.0) {
            try { $cw = [double]$c.Width.DisplayValue } catch { $cw = 0.0 }
          }
          $nameBoundary += [double]$cw
          if ($c -eq $nameCol) { break }
        }
      }
    } catch { $nameBoundary = 0.0 }
    if ($nameBoundary -le 0.0) { return }
    # Shift handle mostly into the Pending column so it doesn't compete for Name-column scrollbar space.
    $left = [double]$nameBoundary - ([double]$w * 0.15)
    if ($left -lt 0.0) { $left = 0.0 }
    $headerH = 26.0
    try {
      $hp = Find-VisualChild -Parent $grid -Type ([System.Windows.Controls.Primitives.DataGridColumnHeadersPresenter])
      if ($hp -and $hp.ActualHeight -gt 0) { $headerH = [double]$hp.ActualHeight }
    } catch {}
    # Start below the bottom of the top mask row and track it live as user resizes that row.
    $maskTopPad = 0.0
    try { $maskTopPad = [Math]::Max(0.0, [double]$script:GridTopOverlayTopPadPx) } catch { $maskTopPad = 0.0 }
    $maskH = 40.0
    try { $maskH = [double]$script:GridTopMaskHeightPx } catch { $maskH = 40.0 }
    if ($maskH -lt 0.0) { $maskH = 0.0 }
    $topPad = [Math]::Max(0.0, ([double]$headerH + [double]$maskTopPad + [double]$maskH))
    $bottomPad = 2.0
    try {
      $sv = Get-GridMainScrollViewer
      if ($sv -and $sv.ComputedHorizontalScrollBarVisibility -eq [System.Windows.Visibility]::Visible) {
        $bottomPad += [double][SystemParameters]::HorizontalScrollBarHeight
      }
    } catch {}
    try {
      $th.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Left
      $th.VerticalAlignment = [System.Windows.VerticalAlignment]::Stretch
      $th.Width = [double]$w
      $th.Margin = [System.Windows.Thickness]::new([double]$left, [double]$topPad, 0.0, [double]$bottomPad)
      $th.Cursor = [System.Windows.Input.Cursors]::SizeWE
      $th.Visibility = [System.Windows.Visibility]::Visible
    } catch {}
  } catch {}
}

function Ensure-MidGridVisualTimer {
  try {
    if ($script:GridMidVisualTimer -and ($script:GridMidVisualTimer -is [System.Windows.Threading.DispatcherTimer])) {
      return
    }
    $t = New-Object System.Windows.Threading.DispatcherTimer
    $t.Interval = [TimeSpan]::FromMilliseconds(16)
    $t.Add_Tick({
      try {
        $sb = $script:GridMidScrollBar
        if (-not $sb) { try { $script:GridMidVisualTimer.Stop() } catch {}; return }
        $target = 0.0
        try { $target = [double]$script:GridMidVisualTargetOffset } catch { $target = 0.0 }
        $mx = 0.0
        try { $mx = [Math]::Max(0.0, [double]$sb.Maximum) } catch { $mx = 0.0 }
        if ($target -lt 0.0) { $target = 0.0 }
        if ($target -gt $mx) { $target = $mx }
        $cur = 0.0
        try { $cur = [double]$sb.Value } catch { $cur = 0.0 }
        $delta = ($target - $cur)
        $absDelta = [Math]::Abs($delta)
        $snap = 0.35
        try { $snap = [double]$script:GridMidVisualSnapEpsPx } catch { $snap = 0.35 }
        if ($snap -lt 0.05) { $snap = 0.05 }
        if ($absDelta -le $snap) {
          $script:GridMidScrollBarSyncing = $true
          try { $sb.Value = [double]$target } finally { $script:GridMidScrollBarSyncing = $false }
          try { $script:GridMidVisualTimer.Stop() } catch {}
          return
        }
        $ease = 0.40
        try { $ease = [double]$script:GridMidVisualEaseFactor } catch { $ease = 0.40 }
        if ($ease -lt 0.05) { $ease = 0.05 }
        if ($ease -gt 0.95) { $ease = 0.95 }
        $step = $delta * $ease
        $minStep = 0.45
        try { $minStep = [double]$script:GridMidVisualMinStepPx } catch { $minStep = 0.45 }
        if ($minStep -lt 0.05) { $minStep = 0.05 }
        if ($absDelta -le $minStep) {
          $step = $delta
        } elseif ([Math]::Abs($step) -lt $minStep) {
          $step = [Math]::Sign($delta) * $minStep
        }
        $next = $cur + $step
        if (($delta -gt 0.0 -and $next -gt $target) -or ($delta -lt 0.0 -and $next -lt $target)) {
          $next = $target
        }
        if ($next -lt 0.0) { $next = 0.0 }
        if ($next -gt $mx) { $next = $mx }
        $script:GridMidScrollBarSyncing = $true
        try { $sb.Value = [double]$next } finally { $script:GridMidScrollBarSyncing = $false }
      } catch {
        try { $script:GridMidVisualTimer.Stop() } catch {}
      }
    })
    $script:GridMidVisualTimer = $t
  } catch {}
}

function Start-MidGridVisualAnimation {
  param([double]$TargetOffset)
  try {
    $t = [double]$TargetOffset
    if ($t -lt 0.0) { $t = 0.0 }
    $script:GridMidVisualTargetOffset = $t
    Ensure-MidGridVisualTimer
    if ($script:GridMidVisualTimer -and -not $script:GridMidVisualTimer.IsEnabled) {
      $script:GridMidVisualTimer.Start()
    }
  } catch {}
}

function Queue-MidGridScrollBarSync {
  param([bool]$LayoutUpdate = $false)
  try {
    if ($LayoutUpdate) { $script:GridMidSyncNeedLayout = $true }
    if ([bool]$script:GridMidSyncQueued) { return }
    $script:GridMidSyncQueued = $true
    if ($window -and $window.Dispatcher) {
      [void]$window.Dispatcher.BeginInvoke(
        [Action]{
          try {
            $lu = $false
            try { $lu = [bool]$script:GridMidSyncNeedLayout } catch { $lu = $false }
            $script:GridMidSyncNeedLayout = $false
            Sync-MidGridScrollBarFromViewer -LayoutUpdate:$lu
          } finally {
            $script:GridMidSyncQueued = $false
          }
        },
        [System.Windows.Threading.DispatcherPriority]::Background
      )
    } else {
      $lu = $false
      try { $lu = [bool]$script:GridMidSyncNeedLayout } catch { $lu = $false }
      $script:GridMidSyncNeedLayout = $false
      Sync-MidGridScrollBarFromViewer -LayoutUpdate:$lu
      $script:GridMidSyncQueued = $false
    }
  } catch {
    try { $script:GridMidSyncQueued = $false } catch {}
  }
}

function Sync-MidGridScrollBarFromViewer {
  param([bool]$LayoutUpdate = $false)
  try {
    $sb = $script:GridMidScrollBar
    if (-not $sb) { return }
    $sv = Get-GridMainScrollViewer
    if (-not $sv) { return }
    if ($LayoutUpdate) {
      try { Update-GridTopDataSpacerLayout } catch {}
      try { Update-MidGridScrollBarLayout } catch {}
      try { Update-GridTopOverlayLayout } catch {}
      try { Update-GridSelectNameBandLayout } catch {}
      try { Update-GridTopMaskResizeThumbLayout } catch {}
    }
    $max = 0.0
    $vp = 0.0
    $off = 0.0
    try { $max = [Math]::Max(0.0, ([double]$sv.ExtentHeight - [double]$sv.ViewportHeight)) } catch { $max = 0.0 }
    try { $vp = [Math]::Max(0.0, [double]$sv.ViewportHeight) } catch { $vp = 0.0 }
    try { $off = [double]$sv.VerticalOffset } catch { $off = 0.0 }
    if ($off -lt 0.0) { $off = 0.0 }
    if ($off -gt $max) { $off = $max }
    $showMidScroll = $false
    try {
      $threshold = 1.0
      try { $threshold = [double]$script:GridMidScrollBarShowThresholdPx } catch { $threshold = 1.0 }
      $maskAdj = 0.0
      try { $maskAdj = [Math]::Max(0.0, [double]$script:GridTopMaskHeightPx) } catch { $maskAdj = 0.0 }
      $effectiveMax = [Math]::Max(0.0, ([double]$max - [double]$maskAdj))
      $showMidScroll = (($effectiveMax -gt $threshold) -or (Test-MidGridScrollBarNeeded -ScrollViewer $sv))
    } catch { $showMidScroll = ($max -gt 0.5) }
    try { Set-MidGridScrollBarAnimatedVisibility -Show:$showMidScroll } catch {}
    if (-not $showMidScroll) {
      try { if ($script:GridMidVisualTimer -and $script:GridMidVisualTimer.IsEnabled) { $script:GridMidVisualTimer.Stop() } } catch {}
    }
    $script:GridMidScrollBarSyncing = $true
    try {
      if ([Math]::Abs(([double]$sb.Minimum - 0.0)) -gt 0.0001) { $sb.Minimum = 0.0 }
      if ([Math]::Abs(([double]$sb.Maximum - [double]$max)) -gt 0.05) { $sb.Maximum = [double]$max }
      if ([Math]::Abs(([double]$sb.ViewportSize - [double]$vp)) -gt 0.05) { $sb.ViewportSize = [double]$vp }
      if ([Math]::Abs(([double]$sb.SmallChange - 24.0)) -gt 0.05) { $sb.SmallChange = 24.0 }
      $lg = [Math]::Max(24.0, ($vp * 0.9))
      if ([Math]::Abs(([double]$sb.LargeChange - [double]$lg)) -gt 0.05) { $sb.LargeChange = [double]$lg }
      $valEps = 4.0
      try { $valEps = [double]$script:GridMidValueSyncEpsilonPx } catch { $valEps = 4.0 }
      if ($valEps -lt 0.05) { $valEps = 0.05 }
      $script:GridMidVisualTargetOffset = [double]$off
      if ($showMidScroll -and [Math]::Abs(([double]$sb.Value - [double]$off)) -gt $valEps) {
        Start-MidGridVisualAnimation -TargetOffset ([double]$off)
      } elseif ($script:GridMidVisualTimer -and $script:GridMidVisualTimer.IsEnabled) {
        try { $script:GridMidVisualTimer.Stop() } catch {}
      }
    } finally {
      $script:GridMidScrollBarSyncing = $false
    }
  } catch {}
}

function Ensure-MidGridScrollBarWiring {
  try {
    $sb = $script:GridMidScrollBar
    if (-not $sb) { return }
    $sv = Get-GridMainScrollViewer
    if (-not $sv) { return }
    if (-not [object]::ReferenceEquals($script:GridMidScrollBarViewer, $sv)) {
      try {
        if ($script:GridMidScrollBarViewer -and $script:GridMidScrollBarViewerHandler) {
          $script:GridMidScrollBarViewer.Remove_ScrollChanged($script:GridMidScrollBarViewerHandler)
        }
      } catch {}
      if (-not $script:GridMidScrollBarViewerHandler) {
        $script:GridMidScrollBarViewerHandler = [System.Windows.Controls.ScrollChangedEventHandler]{
          param($sender, $e)
          try {
            $needLayout = $false
            try {
              $needLayout =
                ([Math]::Abs([double]$e.HorizontalChange) -gt 0.01) -or
                ([Math]::Abs([double]$e.ExtentWidthChange) -gt 0.01) -or
                ([Math]::Abs([double]$e.ViewportWidthChange) -gt 0.01)
            } catch { $needLayout = $false }
            if (-not $needLayout) {
              try {
                if ([bool]$script:GridMidSuspendWhileSmoothScroll -and $script:GridSmoothTimer -and $script:GridSmoothTimer.IsEnabled) {
                  return
                }
              } catch {}
            }
            $doSync = $true
            if (-not $needLayout) {
              $minMs = 33.0
              try { $minMs = [double]$script:GridMidSyncMinIntervalMs } catch { $minMs = 33.0 }
              if ($minMs -lt 0.0) { $minMs = 0.0 }
              $nowTick = [Environment]::TickCount
              $lastTick = 0
              try { $lastTick = [int]$script:GridMidLastSyncTick } catch { $lastTick = 0 }
              $dt = [Math]::Abs([int]($nowTick - $lastTick))
              if ($dt -lt [int][Math]::Round($minMs)) {
                $doSync = $false
              } else {
                $script:GridMidLastSyncTick = $nowTick
              }
            } else {
              try { $script:GridMidLastSyncTick = [Environment]::TickCount } catch {}
            }
            if ($doSync) {
              Queue-MidGridScrollBarSync -LayoutUpdate:$needLayout
            }
          } catch {}
        }
      }
      try { $sv.Add_ScrollChanged($script:GridMidScrollBarViewerHandler) } catch {}
      $script:GridMidScrollBarViewer = $sv
    }
    if (-not [bool]$script:GridMidScrollBarWired) {
      $script:GridMidScrollBarWired = $true
      $sb.Add_ValueChanged({
        param($sender, $e)
        try {
          if ([bool]$script:GridMidScrollBarSyncing) { return }
          try { if ($script:GridMidVisualTimer -and $script:GridMidVisualTimer.IsEnabled) { $script:GridMidVisualTimer.Stop() } } catch {}
          $sv2 = Get-GridMainScrollViewer
          if (-not $sv2) { return }
          $newOffset = 0.0
          try { $newOffset = [double]$sender.Value } catch { $newOffset = 0.0 }
          if ($newOffset -lt 0.0) { $newOffset = 0.0 }
          try {
            $mx = [Math]::Max(0.0, ([double]$sv2.ExtentHeight - [double]$sv2.ViewportHeight))
            if ($newOffset -gt $mx) { $newOffset = $mx }
          } catch {}
          $sv2.ScrollToVerticalOffset($newOffset)
          try { $script:GridSmoothTargetOffset = [double]$newOffset } catch {}
          try { $script:GridMidVisualTargetOffset = [double]$newOffset } catch {}
        } catch {}
      })
      try {
        if ($grid) {
          $grid.Add_SizeChanged({
            try { Invoke-GridColumnWidthConstraintsSafe } catch {}
            try { Queue-MidGridScrollBarSync -LayoutUpdate:$true } catch {}
          })
        }
      } catch {}
    }
    Queue-MidGridScrollBarSync -LayoutUpdate:$true
  } catch {}
}

function Scroll-GridByPixels {
  param([double]$DeltaPixels)
  try {
    $sv = Get-GridMainScrollViewer
    if (-not $sv) { return $false }
    $newOffset = [double]$sv.VerticalOffset + [double]$DeltaPixels
    if ($newOffset -lt 0) { $newOffset = 0 }
    $max = 0.0
    try { $max = [Math]::Max(0.0, ($sv.ExtentHeight - $sv.ViewportHeight)) } catch { $max = 0.0 }
    if ($newOffset -gt $max) { $newOffset = $max }
    $sv.ScrollToVerticalOffset($newOffset)
    return $true
  } catch {
    return $false
  }
}

function Ensure-GridDragAutoScrollTimer {
  try {
    if ($script:GridDragAutoScrollTimer -and ($script:GridDragAutoScrollTimer -is [System.Windows.Threading.DispatcherTimer])) {
      return
    }
    if (-not (Test-Path variable:script:GridDragAutoScrollNearPx)) { $script:GridDragAutoScrollNearPx = 150.0 }
    if (-not (Test-Path variable:script:GridDragAutoScrollMinStepPx)) { $script:GridDragAutoScrollMinStepPx = 6.0 }
    if (-not (Test-Path variable:script:GridDragAutoScrollMaxStepPx)) { $script:GridDragAutoScrollMaxStepPx = 24.0 }
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(16)
    $timer.Add_Tick({
      try {
        if (-not [bool]$script:GridDragInProgress) { return }
        if (-not $grid) { return }
        if (-not $grid.IsVisible) { return }
        $mp = [System.Windows.Forms.Control]::MousePosition
        $pt = $grid.PointFromScreen([System.Windows.Point]::new([double]$mp.X, [double]$mp.Y))
        $h = 0.0
        $w = 0.0
        try { $h = [double]$grid.ActualHeight } catch { $h = 0.0 }
        try { $w = [double]$grid.ActualWidth } catch { $w = 0.0 }
        if ($h -le 0 -or $w -le 0) { return }
        # Only auto-scroll when pointer is over the grid width.
        if ($pt.X -lt 0 -or $pt.X -gt $w) { return }
        $near = [double]$script:GridDragAutoScrollNearPx
        $minStep = [double]$script:GridDragAutoScrollMinStepPx
        $maxStep = [double]$script:GridDragAutoScrollMaxStepPx
        if ($near -lt 1) { $near = 1 }
        if ($maxStep -lt $minStep) { $maxStep = $minStep }
        $step = 0.0
        if ($pt.Y -lt $near) {
          $ratio = 1.0 - ([Math]::Max(0.0, $pt.Y) / $near)  # 0..1 toward top edge
          $step = -($minStep + (($maxStep - $minStep) * $ratio))
        } elseif ($pt.Y -gt ($h - $near)) {
          $dist = [Math]::Max(0.0, ($h - $pt.Y))
          $ratio = 1.0 - ($dist / $near) # 0..1 toward bottom edge
          $step = ($minStep + (($maxStep - $minStep) * $ratio))
        }
        if ([Math]::Abs($step) -gt 0.01) {
          [void](Scroll-GridByPixels -DeltaPixels $step)
        }
      } catch {}
    })
    $script:GridDragAutoScrollTimer = $timer
  } catch {}
}

function Start-GridDragAutoScroll {
  try {
    Suspend-GridSmoothScrollForDrag -Suspend $true
    Ensure-GridDragAutoScrollTimer
    if ($script:GridDragAutoScrollTimer) { $script:GridDragAutoScrollTimer.Start() }
  } catch {}
}

function Stop-GridDragAutoScroll {
  try {
    if ($script:GridDragAutoScrollTimer) { $script:GridDragAutoScrollTimer.Stop() }
    Suspend-GridSmoothScrollForDrag -Suspend $false
  } catch {}
}

function Get-DragDropRowIds {
  param([Parameter(Mandatory=$true)]$DataObject)
  $ids = New-Object System.Collections.Generic.List[string]
  $seen = @{}
  try {
    if (-not $DataObject) { return @() }
    $rawText = $null
    try {
      if ($DataObject.GetDataPresent('StartMenuTool.RowIdsText')) { $rawText = $DataObject.GetData('StartMenuTool.RowIdsText') }
    } catch {}
    if ($rawText) {
      foreach ($line in @(([string]$rawText -split "`r?`n"))) {
        $s = ([string]$line).Trim()
        if ([string]::IsNullOrWhiteSpace($s)) { continue }
        if ($seen.ContainsKey($s)) { continue }
        $seen[$s] = $true
        [void]$ids.Add($s)
      }
      if ($ids.Count -gt 0) { return @($ids.ToArray()) }
    }
    if (-not $DataObject.GetDataPresent('StartMenuTool.RowIds')) { return @() }
    $raw = $DataObject.GetData('StartMenuTool.RowIds')
    $append = {
      param($v)
      if ($null -eq $v) { return }
      if ($v -is [string]) {
        $s = [string]$v
        if ([string]::Equals($s, 'System.String[]', [System.StringComparison]::OrdinalIgnoreCase)) { return }
        if (-not [string]::IsNullOrWhiteSpace($s) -and -not $seen.ContainsKey($s)) {
          $seen[$s] = $true
          [void]$ids.Add($s)
        }
        return
      }
      if ($v -is [System.Collections.IEnumerable]) {
        foreach ($x in $v) { & $append $x }
        return
      }
      $s2 = [string]$v
      if (-not [string]::IsNullOrWhiteSpace($s2) -and -not $seen.ContainsKey($s2)) {
        $seen[$s2] = $true
        [void]$ids.Add($s2)
      }
    }
    & $append $raw
  } catch {}
  return @($ids.ToArray())
}

function Stop-GridDragGhost {
  try {
    $pop = $script:GridDragGhostPopup
    if ($pop -and ($pop -is [System.Windows.Controls.Primitives.Popup])) {
      try { $pop.IsOpen = $false } catch {}
      try { $pop.Child = $null } catch {}
    }
  } catch {}
  try { $script:GridDragGhostPopup = $null } catch {}
}

function Update-GridDragGhostPosition {
  param(
    [Parameter(Mandatory=$true)][object]$Grid,
    [Parameter(Mandatory=$true)][System.Windows.Point]$Position
  )
  try {
    $pop = $script:GridDragGhostPopup
    if (-not $pop) { return }
    if (-not ($pop -is [System.Windows.Controls.Primitives.Popup])) { return }
    if ($pop.PlacementTarget -ne $Grid) { $pop.PlacementTarget = $Grid }
    $pop.HorizontalOffset = [double]$Position.X + 14.0
    $pop.VerticalOffset   = [double]$Position.Y + 12.0
  } catch {}
}

function Start-GridDragGhost {
  param(
    [Parameter(Mandatory=$true)][object]$Grid,
    [Parameter(Mandatory=$true)][object[]]$Rows,
    [Parameter(Mandatory=$true)][System.Windows.Point]$StartPoint
  )
  try {
    Stop-GridDragGhost
    if (-not $Grid) { return }
    if (-not $Rows -or @($Rows).Count -eq 0) { return }
    $row = @($Rows)[0]
    $label = [string](Get-PropString -Obj $row -Names @('ViewName','Name','OriginalName') -Fallback 'Item')
    if ([string]::IsNullOrWhiteSpace($label)) { $label = 'Item' }
    if (@($Rows).Count -gt 1) { $label = ('{0}  (+{1})' -f $label, ((@($Rows).Count) - 1)) }
    $iconSource = $null
    try {
      $prop = $row.PSObject.Properties['Icon']
      if ($prop) { $iconSource = $prop.Value }
    } catch {}
    $root = New-Object System.Windows.Controls.Border
    $root.CornerRadius = New-Object System.Windows.CornerRadius(2)
    $root.Padding = New-Object System.Windows.Thickness(7,4,7,4)
    $root.Background = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb(205, 24, 24, 24))
    $stack = New-Object System.Windows.Controls.StackPanel
    $stack.Orientation = [System.Windows.Controls.Orientation]::Horizontal
    $stack.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    if ($iconSource) {
      $img = New-Object System.Windows.Controls.Image
      $img.Width = 16
      $img.Height = 16
      $img.Margin = New-Object System.Windows.Thickness(0,0,6,0)
      $img.Source = $iconSource
      try { [System.Windows.Media.RenderOptions]::SetBitmapScalingMode($img, [System.Windows.Media.BitmapScalingMode]::Fant) } catch {}
      [void]$stack.Children.Add($img)
    }
    $tb = New-Object System.Windows.Controls.TextBlock
    $tb.Text = $label
    $tb.Foreground = [System.Windows.Media.Brushes]::White
    $tb.FontSize = 12.0
    $tb.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $tb.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis
    [void]$stack.Children.Add($tb)
    $root.Child = $stack
    $pop = New-Object System.Windows.Controls.Primitives.Popup
    $pop.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Relative
    $pop.PlacementTarget = $Grid
    $pop.AllowsTransparency = $true
    $pop.StaysOpen = $true
    $pop.IsHitTestVisible = $false
    $pop.Child = $root
    try { [System.Windows.Controls.Panel]::SetZIndex($root, 99999) } catch {}
    $script:GridDragGhostPopup = $pop
    Update-GridDragGhostPosition -Grid $Grid -Position $StartPoint
    $pop.IsOpen = $true
  } catch {}
}

function Get-GridNameCellForRowItem {
  param([Parameter(Mandatory=$true)][object]$RowItem)
  try {
    if (-not $grid -or -not $RowItem) { return $null }
    $rowContainer = $grid.ItemContainerGenerator.ContainerFromItem($RowItem)
    if (-not $rowContainer) { return $null }
    if (-not ($rowContainer -is [System.Windows.Controls.DataGridRow])) { return $null }
    $presenter = Find-FirstVisualChildByType -Root $rowContainer -Type ([System.Windows.Controls.Primitives.DataGridCellsPresenter])
    if (-not $presenter) { return $null }
    $nameDisplayIndex = Get-GridNameColumnDisplayIndex
    $cell = $null
    if ($nameDisplayIndex -ge 0) {
      try { $cell = $presenter.ItemContainerGenerator.ContainerFromIndex([int]$nameDisplayIndex) } catch { $cell = $null }
      $isName = $false
      try { $isName = ($cell -is [System.Windows.Controls.DataGridCell] -and [string]$cell.Column.Header -eq 'Name') } catch { $isName = $false }
      if (-not $isName) { $cell = $null }
    }
    if (-not ($cell -is [System.Windows.Controls.DataGridCell])) {
      for ($idx = 0; $idx -lt @($grid.Columns).Count; $idx++) {
        $c2 = $null
        try { $c2 = $presenter.ItemContainerGenerator.ContainerFromIndex([int]$idx) } catch { $c2 = $null }
        if (-not ($c2 -is [System.Windows.Controls.DataGridCell])) { continue }
        $okCol = $false
        try { $okCol = ([string]$c2.Column.Header -eq 'Name') } catch { $okCol = $false }
        if ($okCol) { $cell = $c2; break }
      }
    }
    if ($cell -is [System.Windows.Controls.DataGridCell]) { return $cell }
    return $null
  } catch {
    return $null
  }
}

function Test-IsGridPointInsideCurrentDragHoverNameCell {
  param([System.Windows.Point]$GridPoint)
  try {
    if (-not $grid) { return $false }
    $cell = $null
    try { $cell = $script:GridDragHoverNameCell } catch { $cell = $null }
    if (-not ($cell -is [System.Windows.Controls.DataGridCell])) { return $false }
    $p = $null
    try { $p = $grid.TranslatePoint($GridPoint, $cell) } catch { $p = $null }
    if (-not $p) { return $false }
    if ($p.X -lt 0 -or $p.Y -lt 0) { return $false }
    if ($p.X -gt $cell.ActualWidth -or $p.Y -gt $cell.ActualHeight) { return $false }
    return $true
  } catch {
    return $false
  }
}

function Clear-GridDragHoverFolderVisual {
  try {
    $cell = $null
    try { $cell = $script:GridDragHoverNameCell } catch {}
    if ($cell) {
      try { $cell.ClearValue([System.Windows.Controls.Control]::BackgroundProperty) } catch {}
      try { $cell.ClearValue([System.Windows.Controls.Control]::BorderBrushProperty) } catch {}
      try { $cell.ClearValue([System.Windows.Controls.Control]::BorderThicknessProperty) } catch {}
    }
  } catch {}
  try { $script:GridDragHoverNameCell = $null } catch {}
  try { $script:GridDragHoverRowId = '' } catch {}
}

function Set-GridDragHoverFolderVisual {
  param([Parameter(Mandatory=$false)][object]$TargetRow = $null)
  try {
    $targetId = ''
    if ($TargetRow) {
      try { $targetId = [string](Get-PropString -Obj $TargetRow -Names @('Id') -Fallback '') } catch { $targetId = '' }
    }
    $currentId = ''
    try { $currentId = [string]$script:GridDragHoverRowId } catch { $currentId = '' }
    if ($TargetRow -and -not [string]::IsNullOrWhiteSpace($targetId) -and $targetId -eq $currentId) { return }
    Clear-GridDragHoverFolderVisual
    if (-not $TargetRow) { return }
    if (-not (Test-IsFolderDropTargetRow -Row $TargetRow)) { return }
    $cell = Get-GridNameCellForRowItem -RowItem $TargetRow
    if (-not $cell) { return }
    $overlayBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb(80, 50, 210, 90))
    $overlayBorder = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb(165, 110, 255, 150))
    try { $overlayBrush.Freeze() } catch {}
    try { $overlayBorder.Freeze() } catch {}
    $cell.Background = $overlayBrush
    $cell.BorderBrush = $overlayBorder
    $cell.BorderThickness = New-Object System.Windows.Thickness(0)
    $script:GridDragHoverNameCell = $cell
    $script:GridDragHoverRowId = $targetId
  } catch {}
}

# --------------------------
# Drag & Drop: move link items into folders (mock-only until Apply)
# --------------------------
if (-not (Test-Path variable:script:GridDragDropWired) -or -not $script:GridDragDropWired) {
  $script:GridDragDropWired = $true
  $script:GridDragStartPoint = [System.Windows.Point]::new(0,0)
  $script:GridDragSourceId = ''
  $script:GridDragInProgress = $false
  $script:GridDragRowIds = @()
  $script:GridDragSeedIds = @()
  $script:GridDragHoverNameCell = $null
  $script:GridDragHoverRowId = ''
  if (-not (Test-Path variable:script:GridDragAutoScrollTimer)) { $script:GridDragAutoScrollTimer = $null }
  if (-not (Test-Path variable:script:GridDragGhostPopup)) { $script:GridDragGhostPopup = $null }
  try { $grid.AllowDrop = $true } catch {}

  $grid.Add_PreviewMouseLeftButtonDown({
    param($s, $e)
    try {
      $script:GridDragSourceId = ''
      $script:GridDragSeedIds = @()
      $script:GridDragStartPoint = $e.GetPosition($grid)

      $dep = $e.OriginalSource -as [System.Windows.DependencyObject]
      if (-not $dep) {
        try { $grid.UnselectAll() } catch {}
        try { $grid.SelectedItem = $null } catch {}
        try { $grid.CurrentCell = [System.Windows.Controls.DataGridCellInfo]::new() } catch {}
        return
      }
      if (Test-GridNameColumnResizeGripHit -Dep $dep -MouseEvent $e) {
        if (Start-GridNameColumnResizeDrag -MouseEvent $e) {
          $e.Handled = $true
          return
        }
      }
      # Clicking blank area in the grid should clear row highlight/selection.
      $rowContainer = Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.DataGridRow])
      if (-not $rowContainer) {
        $hitHeader = $null
        $hitScroll = $null
        try { $hitHeader = Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.Primitives.DataGridColumnHeader]) } catch { $hitHeader = $null }
        try { $hitScroll = Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.Primitives.ScrollBar]) } catch { $hitScroll = $null }
        if (-not $hitHeader -and -not $hitScroll) {
          try { $grid.UnselectAll() } catch {}
          try { $grid.SelectedItem = $null } catch {}
          try { $grid.CurrentCell = [System.Windows.Controls.DataGridCellInfo]::new() } catch {}
        }
        return
      }
      if (Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.TextBox])) { return }
      if (Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.Primitives.ToggleButton])) { return }
      if (Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.CheckBox])) { return }
      $row = $rowContainer.Item
      if (Test-IsAlphaSeparatorRow -Row $row) {
        try { $grid.UnselectAll() } catch {}
        try { $grid.SelectedItem = $null } catch {}
        try { $grid.CurrentCell = [System.Windows.Controls.DataGridCellInfo]::new() } catch {}
        try { $e.Handled = $true } catch {}
        return
      }
      $cell = Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.DataGridCell])
      if (-not $cell) { return }
      $nameCol = Get-GridNameColumn
      if (-not $nameCol) { return }
      if ($cell.Column -ne $nameCol) { return }
      if (-not (Test-IsDraggableLinkRow -Row $row)) { return }

      $script:GridDragSourceId = [string](Get-PropString -Obj $row -Names @('Id') -Fallback '')
      $seed = New-Object System.Collections.Generic.List[string]
      $seedSeen = @{}
      # IMPORTANT: do not seed from DataGrid.SelectedItems here.
      # PreviewMouseLeftButtonDown fires before selection updates, which can pull in a previously
      # clicked row and cause unintended multi-move. Seed from checkbox selection + drag source only.
      foreach ($it in @($script:CurrentView)) {
        if (-not $it) { continue }
        $isChecked = $false
        try { $isChecked = ($it.PSObject.Properties.Match('Selected').Count -gt 0 -and [bool]$it.Selected) } catch { $isChecked = $false }
        if (-not $isChecked) { continue }
        if (-not (Test-IsDraggableLinkRow -Row $it)) { continue }
        $id = [string](Get-PropString -Obj $it -Names @('Id') -Fallback '')
        if ([string]::IsNullOrWhiteSpace($id) -or $seedSeen.ContainsKey($id)) { continue }
        $seedSeen[$id] = $true
        [void]$seed.Add($id)
      }
      foreach ($it in @($script:VisibleRows)) {
        if (-not $it) { continue }
        $isChecked = $false
        try { $isChecked = ($it.PSObject.Properties.Match('Selected').Count -gt 0 -and [bool]$it.Selected) } catch { $isChecked = $false }
        if (-not $isChecked) { continue }
        if (-not (Test-IsDraggableLinkRow -Row $it)) { continue }
        $id = [string](Get-PropString -Obj $it -Names @('Id') -Fallback '')
        if ([string]::IsNullOrWhiteSpace($id) -or $seedSeen.ContainsKey($id)) { continue }
        $seedSeen[$id] = $true
        [void]$seed.Add($id)
      }
      if (-not [string]::IsNullOrWhiteSpace([string]$script:GridDragSourceId) -and -not $seedSeen.ContainsKey([string]$script:GridDragSourceId)) {
        [void]$seed.Add([string]$script:GridDragSourceId)
      }
      $script:GridDragSeedIds = @($seed.ToArray())
    } catch {}
  })

  $grid.Add_PreviewMouseLeftButtonUp({
    param($s, $e)
    try {
      if ([bool]$script:GridNameColResizeActive) {
        Stop-GridNameColumnResizeDrag
        $e.Handled = $true
      }
    } catch {}
    try { Stop-GridDragGhost } catch {}
    try { Clear-GridDragHoverFolderVisual } catch {}
    # Keep drag IDs/source alive until Drop finishes; otherwise multi-drag can collapse to 1 id.
    try {
      if (-not [bool]$script:GridDragInProgress) {
        $script:GridDragRowIds = @()
        $script:GridDragSourceId = ''
        $script:GridDragSeedIds = @()
      }
    } catch {}
  })

  $grid.Add_PreviewMouseMove({
    param($s, $e)
    try {
      if ([bool]$script:GridNameColResizeActive) {
        if ($e.LeftButton -eq [System.Windows.Input.MouseButtonState]::Pressed) {
          Update-GridNameColumnResizeDrag -MouseEvent $e
        } else {
          Stop-GridNameColumnResizeDrag
        }
        $e.Handled = $true
        return
      }

      if ([string]::IsNullOrWhiteSpace([string]$script:GridDragSourceId)) { return }
      if ($e.LeftButton -ne [System.Windows.Input.MouseButtonState]::Pressed) {
        $script:GridDragSourceId = ''
        $script:GridDragSeedIds = @()
        return
      }

      $p = $e.GetPosition($grid)
      $dx = [Math]::Abs($p.X - $script:GridDragStartPoint.X)
      $dy = [Math]::Abs($p.Y - $script:GridDragStartPoint.Y)
      if ($dx -lt 4 -and $dy -lt 4) { return }

      $rows = New-Object System.Collections.Generic.List[object]
      $seen = @{}
      $seedIds = @()
      try { $seedIds = @($script:GridDragSeedIds) } catch { $seedIds = @() }
      foreach ($sid in @($seedIds)) {
        $id = [string]$sid
        if ([string]::IsNullOrWhiteSpace($id) -or $seen.ContainsKey($id)) { continue }
        $src = Find-ItemById -Id $id
        if (-not (Test-IsDraggableLinkRow -Row $src)) { continue }
        $seen[$id] = $true
        [void]$rows.Add($src)
      }
      # Include checkbox-selected rows from the current view.
      foreach ($it in @($script:CurrentView)) {
        if (-not $it) { continue }
        $isChecked = $false
        try { $isChecked = ($it.PSObject.Properties.Match('Selected').Count -gt 0 -and [bool]$it.Selected) } catch { $isChecked = $false }
        if (-not $isChecked) { continue }
        if (-not (Test-IsDraggableLinkRow -Row $it)) { continue }
        $id = [string](Get-PropString -Obj $it -Names @('Id') -Fallback '')
        if ([string]::IsNullOrWhiteSpace($id) -or $seen.ContainsKey($id)) { continue }
        $seen[$id] = $true
        [void]$rows.Add($it)
      }
      foreach ($it in @($script:VisibleRows)) {
        if (-not $it) { continue }
        $isChecked = $false
        try { $isChecked = ($it.PSObject.Properties.Match('Selected').Count -gt 0 -and [bool]$it.Selected) } catch { $isChecked = $false }
        if (-not $isChecked) { continue }
        if (-not (Test-IsDraggableLinkRow -Row $it)) { continue }
        $id = [string](Get-PropString -Obj $it -Names @('Id') -Fallback '')
        if ([string]::IsNullOrWhiteSpace($id) -or $seen.ContainsKey($id)) { continue }
        $seen[$id] = $true
        [void]$rows.Add($it)
      }
      if ($rows.Count -eq 0) {
        $r0 = Find-ItemById -Id $script:GridDragSourceId
        if ($r0 -and (Test-IsDraggableLinkRow -Row $r0)) { [void]$rows.Add($r0) }
      }
      if ($rows.Count -eq 0) { return }

      $ids = @()
      foreach ($r in @($rows.ToArray())) {
        $id = [string](Get-PropString -Obj $r -Names @('Id') -Fallback '')
        if (-not [string]::IsNullOrWhiteSpace($id)) { $ids += $id }
      }
      if (@($ids).Count -eq 0) { return }
      try { $script:GridDragRowIds = @($ids) } catch { $script:GridDragRowIds = @() }

      $data = New-Object System.Windows.DataObject
      try { $data.SetData('StartMenuTool.RowIds', $false, [string[]]@($ids)) } catch { $data.SetData('StartMenuTool.RowIds', @($ids)) }
      try { $data.SetData('StartMenuTool.RowIdsText', ([string]::Join("`n", @($ids)))) } catch {}
      $script:GridDragInProgress = $true
      Start-GridDragAutoScroll
      Start-GridDragGhost -Grid $grid -Rows @($rows.ToArray()) -StartPoint $p
      [void][System.Windows.DragDrop]::DoDragDrop($grid, $data, [System.Windows.DragDropEffects]::Move)
      Stop-GridDragAutoScroll
      Stop-GridDragGhost
      Clear-GridDragHoverFolderVisual
      $script:GridDragInProgress = $false
      $script:GridDragRowIds = @()
      $script:GridDragSeedIds = @()
      $script:GridDragSourceId = ''
    } catch {
      try { Stop-GridDragAutoScroll } catch {}
      try { Stop-GridDragGhost } catch {}
      try { Clear-GridDragHoverFolderVisual } catch {}
      try { $script:GridDragInProgress = $false } catch {}
      try { $script:GridDragRowIds = @() } catch {}
      try { $script:GridDragSeedIds = @() } catch {}
      try { $script:GridDragSourceId = '' } catch {}
    }
  })

  $grid.Add_DragOver({
    param($s, $e)
    try {
      $e.Effects = [System.Windows.DragDropEffects]::None
      if ((-not $e.Data.GetDataPresent('StartMenuTool.RowIds')) -and (-not $e.Data.GetDataPresent('StartMenuTool.RowIdsText'))) { $e.Handled = $true; return }
      $pp = [System.Windows.Point]::new(0,0)
      try {
        $pp = $e.GetPosition($grid)
        Update-GridDragGhostPosition -Grid $grid -Position $pp
      } catch {}
      $ctx = Get-DragDropTargetContextFromGridPoint -GridPoint $pp
      if ([string]$ctx.Mode -ne 'Folder' -or -not $ctx.TargetRow) {
        $dep = $e.OriginalSource -as [System.Windows.DependencyObject]
        $ctxAlt = Get-DragDropTargetContext -Start $dep
        if ([string]$ctxAlt.Mode -eq 'Folder' -and $ctxAlt.TargetRow) { $ctx = $ctxAlt }
      }

      $rawIds = @()
      try { $rawIds = @($script:GridDragRowIds) } catch { $rawIds = @() }
      $seedIds = @()
      try { $seedIds = @($script:GridDragSeedIds) } catch { $seedIds = @() }
      if (@($seedIds).Count -gt @($rawIds).Count) { $rawIds = @($seedIds) }
      if (@($rawIds).Count -eq 0) { $rawIds = @(Get-DragDropRowIds -DataObject $e.Data) }
      $hasValid = $false
      foreach ($id in @($rawIds)) {
        $src = Find-ItemById -Id ([string]$id)
        if (-not (Test-IsDraggableLinkRow -Row $src)) { continue }
        $dst = $null
        if ([string]$ctx.Mode -eq 'Folder') {
          $dst = Resolve-DropTargetFolderForSource -TargetFolderRow $ctx.TargetRow -SourceRow $src
        } else {
          $dst = Resolve-RootDropTargetForSource -SourceRow $src
        }
        if ($dst) { $hasValid = $true; break }
      }
      if ($hasValid) { $e.Effects = [System.Windows.DragDropEffects]::Move }
      if ($hasValid -and [string]$ctx.Mode -eq 'Folder' -and $ctx.TargetRow) {
        Set-GridDragHoverFolderVisual -TargetRow $ctx.TargetRow
      } else {
        $keepCurrentHover = $false
        try { $keepCurrentHover = Test-IsGridPointInsideCurrentDragHoverNameCell -GridPoint $pp } catch { $keepCurrentHover = $false }
        if (-not $keepCurrentHover) { Clear-GridDragHoverFolderVisual }
      }
      $e.Handled = $true
    } catch {
      try { Clear-GridDragHoverFolderVisual } catch {}
      try { $e.Effects = [System.Windows.DragDropEffects]::None } catch {}
      try { $e.Handled = $true } catch {}
    }
  })

  $grid.Add_DragLeave({
    param($s, $e)
    try {
      $p = [System.Windows.Point]::new(-1,-1)
      try { $p = $e.GetPosition($grid) } catch {}
      $inside = ($p.X -ge 0 -and $p.Y -ge 0 -and $p.X -le $grid.ActualWidth -and $p.Y -le $grid.ActualHeight)
      if (-not $inside) { Clear-GridDragHoverFolderVisual }
    } catch {
      try { Clear-GridDragHoverFolderVisual } catch {}
    }
  })

  $grid.Add_Drop({
    param($s, $e)
    try {
      if ((-not $e.Data.GetDataPresent('StartMenuTool.RowIds')) -and (-not $e.Data.GetDataPresent('StartMenuTool.RowIdsText'))) { return }

      $dep = $e.OriginalSource -as [System.Windows.DependencyObject]
      $ctx = Get-DragDropTargetContext -Start $dep

      $rawIds = @()
      try { $rawIds = @($script:GridDragRowIds) } catch { $rawIds = @() }
      $seedIds = @()
      try { $seedIds = @($script:GridDragSeedIds) } catch { $seedIds = @() }
      if (@($seedIds).Count -gt @($rawIds).Count) { $rawIds = @($seedIds) }
      if (@($rawIds).Count -eq 0) { $rawIds = @(Get-DragDropRowIds -DataObject $e.Data) }
      $sourceRows = New-Object System.Collections.Generic.List[object]
      $seen = @{}
      foreach ($id in @($rawIds)) {
        $sid = [string]$id
        if ([string]::IsNullOrWhiteSpace($sid) -or $seen.ContainsKey($sid)) { continue }
        $seen[$sid] = $true
        $src = Find-ItemById -Id $sid
        if (-not (Test-IsDraggableLinkRow -Row $src)) { continue }
        [void]$sourceRows.Add($src)
      }
      # Fallback: if payload unexpectedly collapses to one id, recover the full
      # checkbox-selected draggable set so bulk move is one undo action.
      if ($sourceRows.Count -le 1) {
        $fallbackRows = New-Object System.Collections.Generic.List[object]
        $fallbackSeen = @{}
        foreach ($it in @($script:CurrentView)) {
          if (-not $it) { continue }
          $isChecked = $false
          try { $isChecked = ($it.PSObject.Properties.Match('Selected').Count -gt 0 -and [bool]$it.Selected) } catch { $isChecked = $false }
          if (-not $isChecked) { continue }
          if (-not (Test-IsDraggableLinkRow -Row $it)) { continue }
          $fid = [string](Get-PropString -Obj $it -Names @('Id') -Fallback '')
          if ([string]::IsNullOrWhiteSpace($fid) -or $fallbackSeen.ContainsKey($fid)) { continue }
          $fallbackSeen[$fid] = $true
          [void]$fallbackRows.Add($it)
        }
        foreach ($it in @($script:VisibleRows)) {
          if (-not $it) { continue }
          $isChecked = $false
          try { $isChecked = ($it.PSObject.Properties.Match('Selected').Count -gt 0 -and [bool]$it.Selected) } catch { $isChecked = $false }
          if (-not $isChecked) { continue }
          if (-not (Test-IsDraggableLinkRow -Row $it)) { continue }
          $fid = [string](Get-PropString -Obj $it -Names @('Id') -Fallback '')
          if ([string]::IsNullOrWhiteSpace($fid) -or $fallbackSeen.ContainsKey($fid)) { continue }
          $fallbackSeen[$fid] = $true
          [void]$fallbackRows.Add($it)
        }
        if ($fallbackRows.Count -gt $sourceRows.Count) {
          $sourceRows = $fallbackRows
        }
      }

      $moved = 0
      if ([string]$ctx.Mode -eq 'Folder' -and $ctx.TargetRow) {
        $moved = Invoke-DragDropMove -SourceRows @($sourceRows.ToArray()) -TargetFolderRow $ctx.TargetRow
      } else {
        $moved = Invoke-DragDropMoveToRoot -SourceRows @($sourceRows.ToArray())
      }
    } catch {}
    finally {
      try { Stop-GridDragGhost } catch {}
      try { Clear-GridDragHoverFolderVisual } catch {}
      try { $script:GridDragRowIds = @() } catch {}
      try { $script:GridDragSeedIds = @() } catch {}
      try { $e.Handled = $true } catch {}
    }
  })
}

# --------------------------
# LEFT click: single-click expand/collapse on folder Name cell
# (Does NOT interfere with rename editing)
# --------------------------
$grid.AddHandler(
  [System.Windows.UIElement]::PreviewMouseLeftButtonDownEvent,
  [System.Windows.Input.MouseButtonEventHandler]{
    param($s, $e)

    try {
      $dep = $e.OriginalSource -as [System.Windows.DependencyObject]
      if (-not $dep) { return }
      if ([bool]$script:GridNameColResizeActive) { return }
      if (Test-GridNameColumnResizeGripHit -Dep $dep -MouseEvent $e) { return }

      # If click is inside an editor, don't hijack
      if (Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.TextBox])) { return }

      # Ignore clicks on interactive controls inside cells
      if (Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.Primitives.ButtonBase])) { return }
      if (Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.Primitives.ToggleButton])) { return }
      if (Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.CheckBox])) { return }

      $cell = Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.DataGridCell])
      if (-not $cell) { return }

      # Only react when clicking the Name column (robust)
      $nameCol = Get-GridNameColumn
      if (-not $nameCol) { return }
      if ($cell.Column -ne $nameCol) { return }

      $rowContainer = Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.DataGridRow])
      if (-not $rowContainer) { return }

      $rowItem = $rowContainer.Item
      if (-not $rowItem) { return }
      if (Test-IsAlphaSeparatorRow -Row $rowItem) {
        try { $e.Handled = $true } catch {}
        return
      }

      # Only for Folder rows
      $isFolder = $false
      try { $isFolder = ($rowItem.PSObject.Properties.Match('RowKind').Count -gt 0 -and $rowItem.RowKind -eq 'Folder') } catch {}
      if (-not $isFolder) { return }

      # Must support IsExpanded
      if ($rowItem.PSObject.Properties.Match('IsExpanded').Count -eq 0) { return }

      # Toggle
      $rowItem.IsExpanded = -not [bool]$rowItem.IsExpanded
      try { Sync-RowFolderChevronMeta -Row $rowItem } catch {}
      try { Refresh-RowFolderChevronBinding -Row $rowItem } catch {}

      if ($script:CurrentNode -and ([string]$script:CurrentNode.Scope -eq 'VisualMenu')) {
        $vk = Get-VisualFolderStateKey -Row $rowItem
        if ($vk) { $script:VisualExpandedState[$vk] = [bool]$rowItem.IsExpanded }
      }

      $didFastToggle = $false
      try { $didFastToggle = (Try-ToggleFolderRowsFast -FolderRow $rowItem) } catch { $didFastToggle = $false }
      if (-not $didFastToggle) {
        Queue-RebuildVisibleRows
      }
      $e.Handled = $true
    } catch {}
  },
  $true
)

# --------------------------
# Right-click behavior (RELIABLE):
# - Target/Path cells: custom text-selection context menu
# - All other cells: PreviewMouseRightButtonDown starts rename
# --------------------------

function Get-TargetPathCellFromDep {
  param([System.Windows.DependencyObject]$Dep)
  try {
    if (-not $Dep) { return $null }
    $cell = Find-VisualAncestor -Start $Dep -Type ([System.Windows.Controls.DataGridCell])
    if (-not $cell) { return $null }
    $ownerGrid = Find-VisualAncestor -Start $cell -Type ([System.Windows.Controls.DataGrid])
    if (-not $ownerGrid -or -not [object]::ReferenceEquals($ownerGrid, $grid)) { return $null }
    $hdr = ''
    try { $hdr = [string]$cell.Column.Header } catch { $hdr = '' }
    if ($hdr -ne 'Target' -and $hdr -ne 'Path') { return $null }
    return $cell
  } catch {
    return $null
  }
}

function Get-TargetPathLeafToken {
  param([string]$Text)
  $t = ''
  try { $t = [string]$Text } catch { $t = '' }
  if ([string]::IsNullOrWhiteSpace($t)) { return '' }
  $leaf = ''
  try { $leaf = [System.IO.Path]::GetFileName($t) } catch { $leaf = '' }
  if ([string]::IsNullOrWhiteSpace($leaf)) {
    try {
      $parts = $t -split '[\\/]'
      if ($parts -and $parts.Count -gt 0) { $leaf = [string]$parts[$parts.Count - 1] }
    } catch { $leaf = '' }
  }
  return [string]$leaf
}

function Select-TargetPathCellText {
  param(
    [Parameter(Mandatory=$true)][object]$Cell,
    [switch]$ItemNameOnly
  )
  try {
    $tb = Find-VisualChild -Parent $Cell -Type ([System.Windows.Controls.TextBox])
    if (-not $tb) { return }
    $txt = ''
    try { $txt = [string]$tb.Text } catch { $txt = '' }
    if ([string]::IsNullOrWhiteSpace($txt)) { return }
    [void]$tb.Focus()
    if (-not $ItemNameOnly) {
      try { $tb.SelectAll() } catch {}
      return
    }
    $leaf = Get-TargetPathLeafToken -Text $txt
    if ([string]::IsNullOrWhiteSpace($leaf)) {
      try { $tb.SelectAll() } catch {}
      return
    }
    $start = -1
    try { $start = $txt.LastIndexOf($leaf, [System.StringComparison]::OrdinalIgnoreCase) } catch { $start = -1 }
    if ($start -lt 0) {
      try { $start = $txt.LastIndexOf($leaf) } catch { $start = -1 }
    }
    if ($start -ge 0) {
      try { $tb.Select([int]$start, [int]$leaf.Length) } catch { try { $tb.SelectAll() } catch {} }
    } else {
      try { $tb.SelectAll() } catch {}
    }
  } catch {}
}

function Get-TargetPathContextRowFromCell {
  param([Parameter(Mandatory=$true)][object]$Cell)
  try {
    $rowContainer = Find-VisualAncestor -Start $Cell -Type ([System.Windows.Controls.DataGridRow])
    if (-not $rowContainer) { return $null }
    try { return $rowContainer.Item } catch { return $null }
  } catch {
    return $null
  }
}

function Get-TargetPathCellTextRaw {
  param([Parameter(Mandatory=$true)][object]$Cell)
  try {
    $tb = Find-VisualChild -Parent $Cell -Type ([System.Windows.Controls.TextBox])
    if (-not $tb) { return '' }
    try { return [string]$tb.Text } catch { return '' }
  } catch {
    return ''
  }
}

function Test-ShortcutRowBrokenTarget {
  param([object]$Row)
  try {
    if (-not $Row) { return $false }
    $tp = ''
    try { $tp = [string](Get-PropString -Obj $Row -Names @('Type') -Fallback '') } catch { $tp = '' }
    if ($tp -ne 'Shortcut') { return $false }

    $targetRaw = ''
    try { $targetRaw = [string](Get-PropString -Obj $Row -Names @('Target') -Fallback '') } catch { $targetRaw = '' }
    if ([string]::IsNullOrWhiteSpace($targetRaw)) { return $false }

    $targetNorm = Normalize-Path $targetRaw
    if ([string]::IsNullOrWhiteSpace($targetNorm)) { $targetNorm = $targetRaw }
    $tl = ''
    try { $tl = [string]$targetNorm.Trim().ToLowerInvariant() } catch { $tl = [string]$targetNorm }
    if ([string]::IsNullOrWhiteSpace($tl)) { return $false }

    # Non-filesystem launch targets should not be treated as broken.
    if ($tl.StartsWith('shell:')) { return $false }
    if ($tl.StartsWith('ms-settings:')) { return $false }
    if ($tl.StartsWith('windowsdefender:')) { return $false }
    if ($tl.StartsWith('http://') -or $tl.StartsWith('https://') -or $tl.StartsWith('mailto:')) { return $false }

    $targetResolved = Resolve-ExistingPathLenient -Path $targetNorm
    if ([string]::IsNullOrWhiteSpace($targetResolved)) { $targetResolved = $targetNorm }
    if (-not [string]::IsNullOrWhiteSpace($targetResolved) -and (Test-Path -LiteralPath $targetResolved)) { return $false }

    # Allow plain command names resolvable via PATH.
    try {
      $cmd = Get-Command -Name $targetRaw -ErrorAction SilentlyContinue | Select-Object -First 1
      if ($cmd) { return $false }
    } catch {}
    return $true
  } catch {
    return $false
  }
}

function Prompt-MarkBrokenShortcutPendingDelete {
  param([object]$Row)
  try {
    if (-not $Row) { return $false }
    $ok = Show-ContinueCancelDialog `
      -Title 'Broken Shortcut' `
      -Message "Shortcut isn't linked to anything. Would you like to mark it as pending Deletion?" `
      -ContinueText 'Mark it' `
      -CancelText 'Cancel'
    if (-not $ok) { return $false }
    try { Set-PropSafeGlobal -Obj $Row -Name 'Selected' -Value $true } catch { try { $Row.Selected = $true } catch {} }
    try {
      Apply-MockDeleteCascade -Row $Row -IsDelete $true
    } catch {
      try { Set-RowMockDeleteState -Row $Row -IsDelete $true } catch {}
      try { Refresh-UIAsync } catch {}
    }
    return $true
  } catch {
    return $false
  }
}

function Open-PathLocationFromTargetPathCell {
  param([Parameter(Mandatory=$true)][object]$Cell)
  try {
    $row = Get-TargetPathContextRowFromCell -Cell $Cell
    if ($row -and (Test-ShortcutRowBrokenTarget -Row $row)) {
      [void](Prompt-MarkBrokenShortcutPendingDelete -Row $row)
      return
    }
    $txt = Get-TargetPathCellTextRaw -Cell $Cell
    if ([string]::IsNullOrWhiteSpace($txt)) { return }
    $p = Normalize-Path $txt
    $pr = Resolve-ExistingPathLenient -Path $p
    if ([string]::IsNullOrWhiteSpace($pr)) { $pr = $p }
    if ([string]::IsNullOrWhiteSpace($pr)) { return }

    if (Test-Path -LiteralPath $pr -PathType Container) {
      Start-Process -FilePath (Join-Path $env:WINDIR 'explorer.exe') -ArgumentList @("`"$pr`"") | Out-Null
      return
    }
    if (Test-Path -LiteralPath $pr -PathType Leaf) {
      Start-Process -FilePath (Join-Path $env:WINDIR 'explorer.exe') -ArgumentList @("/select,`"$pr`"") | Out-Null
      return
    }
  } catch {}
}

function Run-TargetFromTargetPathCell {
  param([Parameter(Mandatory=$true)][object]$Cell)
  try {
    $row = Get-TargetPathContextRowFromCell -Cell $Cell
    if (-not $row) { return }
    if (Test-ShortcutRowBrokenTarget -Row $row) {
      [void](Prompt-MarkBrokenShortcutPendingDelete -Row $row)
      return
    }

    $targetRaw = ''
    $args = ''
    try { $targetRaw = [string](Get-PropString -Obj $row -Names @('Target') -Fallback '') } catch { $targetRaw = '' }
    try { $args = [string](Get-PropString -Obj $row -Names @('Arguments','Args') -Fallback '') } catch { $args = '' }
    if ([string]::IsNullOrWhiteSpace($targetRaw)) { return }

    $targetNorm = Normalize-Path $targetRaw
    $targetResolved = Resolve-ExistingPathLenient -Path $targetNorm
    if ([string]::IsNullOrWhiteSpace($targetResolved)) { $targetResolved = $targetNorm }

    if (-not [string]::IsNullOrWhiteSpace($targetResolved) -and (Test-Path -LiteralPath $targetResolved -PathType Container)) {
      Start-Process -FilePath (Join-Path $env:WINDIR 'explorer.exe') -ArgumentList @("`"$targetResolved`"") | Out-Null
      return
    }

    if (-not [string]::IsNullOrWhiteSpace($targetResolved) -and (Test-Path -LiteralPath $targetResolved -PathType Leaf)) {
      if ([string]::IsNullOrWhiteSpace($args)) {
        Start-Process -FilePath $targetResolved | Out-Null
      } else {
        Start-Process -FilePath $targetResolved -ArgumentList $args | Out-Null
      }
      return
    }

    if ([string]::IsNullOrWhiteSpace($args)) {
      Start-Process -FilePath $targetRaw | Out-Null
    } else {
      Start-Process -FilePath $targetRaw -ArgumentList $args | Out-Null
    }
  } catch {}
}

function Ensure-TargetPathContextMenu {
  try {
    if (Test-Path variable:script:TargetPathContextMenu) {
      if ($script:TargetPathContextMenu) { return }
    }
    $script:TargetPathContextCell = $null
    $cm = New-Object System.Windows.Controls.ContextMenu
    $miOpenPath = New-Object System.Windows.Controls.MenuItem
    $miOpenPath.Header = 'Open path'
    $miOpenPath.Add_Click({
      try {
        if ($script:TargetPathContextCell) {
          Open-PathLocationFromTargetPathCell -Cell $script:TargetPathContextCell
        }
      } catch {}
    })
    $miRunTarget = New-Object System.Windows.Controls.MenuItem
    $miRunTarget.Header = 'Run'
    $miRunTarget.Add_Click({
      try {
        if ($script:TargetPathContextCell) {
          Run-TargetFromTargetPathCell -Cell $script:TargetPathContextCell
        }
      } catch {}
    })
    $miAll = New-Object System.Windows.Controls.MenuItem
    $miAll.Header = 'Select full text'
    $miAll.Add_Click({
      try {
        if ($script:TargetPathContextCell) {
          Select-TargetPathCellText -Cell $script:TargetPathContextCell
        }
      } catch {}
    })
    $miLeaf = New-Object System.Windows.Controls.MenuItem
    $miLeaf.Header = 'Select name'
    $miLeaf.Add_Click({
      try {
        if ($script:TargetPathContextCell) {
          Select-TargetPathCellText -Cell $script:TargetPathContextCell -ItemNameOnly
        }
      } catch {}
    })
    [void]$cm.Items.Add($miOpenPath)
    [void]$cm.Items.Add($miRunTarget)
    [void]$cm.Items.Add((New-Object System.Windows.Controls.Separator))
    [void]$cm.Items.Add($miAll)
    [void]$cm.Items.Add($miLeaf)
    $cm.Add_Closed({
      try { $script:TargetPathContextCell = $null } catch {}
    })
    $script:TargetPathContextMenu = $cm
  } catch {}
}

# Ensure the grid itself doesn't define its own menu
try { $grid.ContextMenu = $null } catch {}

# Suppress default context menus except Target/Path cells (manual menu handled below).
$grid.AddHandler(
  [System.Windows.FrameworkElement]::ContextMenuOpeningEvent,
  [System.Windows.Controls.ContextMenuEventHandler]{
    param($s, $e)
    try {
      $dep = $e.OriginalSource -as [System.Windows.DependencyObject]
      $tpCell = $null
      try { $tpCell = Get-TargetPathCellFromDep -Dep $dep } catch { $tpCell = $null }
      if ($tpCell) { return }
      $e.Handled = $true
    } catch { try { $e.Handled = $true } catch {} }
  },
  $true
)

# Target/Path cells: show custom selection context menu.
# Other cells: right-click rename.
$grid.AddHandler(
  [System.Windows.UIElement]::PreviewMouseRightButtonDownEvent,
  [System.Windows.Input.MouseButtonEventHandler]{
    param($s, $e)

    try {
      $dep = $e.OriginalSource -as [System.Windows.DependencyObject]
      if (-not $dep) { return }

      $rowContainer = Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.DataGridRow])
      $row = $null
      if ($rowContainer) {
        try { $row = $rowContainer.Item } catch { $row = $null }
      }
      if ($row -and (Test-IsCreatedPendingRow -Row $row)) {
        $e.Handled = $true
        return
      }

      $tpCell = $null
      try { $tpCell = Get-TargetPathCellFromDep -Dep $dep } catch { $tpCell = $null }
      if ($tpCell) {
        Ensure-TargetPathContextMenu
        try { $script:TargetPathContextCell = $tpCell } catch {}
        try {
          if ($script:TargetPathContextMenu) {
            $script:TargetPathContextMenu.PlacementTarget = $tpCell
            $script:TargetPathContextMenu.Placement = [System.Windows.Controls.Primitives.PlacementMode]::MousePoint
            $script:TargetPathContextMenu.IsOpen = $true
          }
        } catch {}
        try { $e.Handled = $true } catch {}
        return
      }

      # If inside editing TextBox, don't restart editing, but still suppress menu
      if (Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.TextBox])) {
        $e.Handled = $true
        return
      }

      if (-not $rowContainer) { return }
      if (-not $row) { return }

      Start-RenameForRow -Row $row

      # Suppress default right-click behavior that can trigger menu
      $e.Handled = $true
    } catch {
      try { $e.Handled = $true } catch {}
    }
  },
  $true
)

# Belt + suspenders: eat RightButtonUp too (some templates still try to open menus there)
$grid.AddHandler(
  [System.Windows.UIElement]::PreviewMouseRightButtonUpEvent,
  [System.Windows.Input.MouseButtonEventHandler]{
    param($s, $e)
    try { $e.Handled = $true } catch {}
  },
  $true
)

# ==============================================================================
# Safe edit end + refresh
# ==============================================================================
function End-GridEditTransaction {
  try {
    [void]$grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Cell, $true)
    [void]$grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row,  $true)
    [void]$grid.CancelEdit([System.Windows.Controls.DataGridEditingUnit]::Cell)
    [void]$grid.CancelEdit([System.Windows.Controls.DataGridEditingUnit]::Row)
    [void]$window.Focus()
    [void][System.Windows.Input.Keyboard]::ClearFocus()
  } catch {}
}

function Refresh-UIAsync {
  param(
    [System.Windows.Threading.DispatcherPriority]$Priority = [System.Windows.Threading.DispatcherPriority]::Background
  )
  try {
    $null = $grid.Dispatcher.BeginInvoke(
      [Action]{
        try { $grid.Items.Refresh() } catch { }
        try { if ($script:CurrentView) { $script:CurrentView.Refresh() } } catch { }
        try { Ensure-MidGridScrollBarWiring } catch {}
        try { Queue-MidGridScrollBarSync -LayoutUpdate:$true } catch {}
      },
      $Priority
    )
  } catch {}
}

function Refresh-UI {
  try {
    $grid.Dispatcher.Invoke([Action]{
      try { if ($script:CurrentView) { $script:CurrentView.Refresh() } } catch { }
      try { $grid.Items.Refresh() } catch { }
      try { $grid.InvalidateVisual() } catch { }
      try { $grid.UpdateLayout() } catch { }
      try { Ensure-MidGridScrollBarWiring } catch {}
      try { Queue-MidGridScrollBarSync -LayoutUpdate:$true } catch {}
    }, [System.Windows.Threading.DispatcherPriority]::Send)
  } catch {}
}

function Resolve-OpArgs {
  param($maybeArgs)
  if ($null -eq $maybeArgs) { return $null }
  if ($maybeArgs -is [System.Array]) { return ,@($maybeArgs) }
  return ,@($maybeArgs)
}

function Push-UndoOp {
  param([object]$op)
  [void]$script:UndoStack.Add($op)
  while ($script:UndoStack.Count -gt 20) { $script:UndoStack.RemoveAt(0) }
  $script:RedoStack.Clear()
}

function Undo {
  if ($script:UndoStack.Count -le 0) { return }
  $op = $script:UndoStack[$script:UndoStack.Count - 1]
  $script:UndoStack.RemoveAt($script:UndoStack.Count - 1)
  try {
    $isDragMoveOp = $false
    try { $isDragMoveOp = ([string]$op.Type -eq 'DragDropMove' -or [string]$op.Type -eq 'DragDropMoveRoot') } catch { $isDragMoveOp = $false }
    if ($isDragMoveOp -and $op.PSObject.Properties.Match('Snapshot').Count -gt 0 -and $op.Snapshot) {
      Apply-DragMoveSnapshot -Snapshot @($op.Snapshot) -Direction Undo
    } else {
      $argsToPass = Resolve-OpArgs $op.UndoArgs
      if ($null -ne $argsToPass) { & $op.Undo @argsToPass } else { & $op.Undo }
    }
  } catch {
  }
  [void]$script:RedoStack.Add($op)
}

function Redo {
  if ($script:RedoStack.Count -le 0) { return }
  $op = $script:RedoStack[$script:RedoStack.Count - 1]
  $script:RedoStack.RemoveAt($script:RedoStack.Count - 1)
  try {
    $isDragMoveOp = $false
    try { $isDragMoveOp = ([string]$op.Type -eq 'DragDropMove' -or [string]$op.Type -eq 'DragDropMoveRoot') } catch { $isDragMoveOp = $false }
    if ($isDragMoveOp -and $op.PSObject.Properties.Match('Snapshot').Count -gt 0 -and $op.Snapshot) {
      Apply-DragMoveSnapshot -Snapshot @($op.Snapshot) -Direction Do
    } else {
      $argsToPass = Resolve-OpArgs $op.DoArgs
      if ($null -ne $argsToPass) { & $op.Do @argsToPass } else { & $op.Do }
    }
  } catch {
  }
  [void]$script:UndoStack.Add($op)
}

# ==============================================================================
# Load initial state
# ==============================================================================
try { Set-StartupSplashStatus -Status "Scanning Start Menu items..." -Value 66 } catch {}
$script:StartupInventory = @(Get-Inventory)
try { Invalidate-LaunchDuplicateCaches } catch {}
try { Set-StartupSplashStatus -Status "Building tree model..." -Value 78 } catch {}
$model = Build-Model -inventoryItems $script:StartupInventory
$script:TreeRoots = $model.TreeRoots
$script:NodeMap   = $model.NodeMap
$tree.ItemsSource = $script:TreeRoots
try { Set-StartupSplashStatus -Status "Preparing first view..." -Value 88 } catch {}

# ==============================================================================
# Tree-like grid view (visible rows list)
# ==============================================================================
$script:VisibleRows = [System.Collections.ObjectModel.ObservableCollection[object]]::new()

function Get-VisibleRowLevel {
  param(
    [Parameter(Mandatory=$true)][object]$Row,
    [int]$Default = 0
  )
  try {
    if ($Row -and $Row.PSObject.Properties.Match('Level').Count -gt 0) {
      return [int]$Row.Level
    }
  } catch {}
  return [int]$Default
}

function Get-VisibleRowIndexByRef {
  param([Parameter(Mandatory=$true)][object]$Row)
  try {
    if (-not $script:VisibleRows) { return -1 }
    for ($i = 0; $i -lt $script:VisibleRows.Count; $i++) {
      try {
        if ([object]::ReferenceEquals($script:VisibleRows[$i], $Row)) { return $i }
      } catch {}
    }
  } catch {}
  return -1
}

function Remove-VisibleDescendantSlice {
  param(
    [Parameter(Mandatory=$true)][int]$ParentIndex,
    [Parameter(Mandatory=$true)][int]$ParentLevel
  )
  $removed = 0
  try {
    if (-not $script:VisibleRows) { return 0 }
    $i = $ParentIndex + 1
    while ($i -lt $script:VisibleRows.Count) {
      $r = $script:VisibleRows[$i]
      $lvl = Get-VisibleRowLevel -Row $r -Default 0
      if ($lvl -le $ParentLevel) { break }
      $script:VisibleRows.RemoveAt($i)
      $removed++
    }
  } catch {}
  return $removed
}

function Get-FastExpandedRowsForFolder {
  param(
    [Parameter(Mandatory=$true)][object]$FolderRow,
    [Parameter(Mandatory=$true)][int]$BaseLevel
  )
  $origRows = $script:VisibleRows
  $tmpRows = [System.Collections.ObjectModel.ObservableCollection[object]]::new()
  $script:VisibleRows = $tmpRows
  try {
    $mode = 'Mixed'
    try { $mode = [string]$script:SortMode } catch {}
    if ([string]::IsNullOrWhiteSpace($mode)) { $mode = 'Mixed' }
    if ($script:CurrentNode -and ([string]$script:CurrentNode.Scope -eq 'VisualMenu')) {
      $srcsArr = @()
      try { $srcsArr = @(Get-VisualSourcesForFolderRow -Row $FolderRow) } catch { $srcsArr = @() }
      if ($srcsArr.Count -gt 0) {
        if ([bool]$script:ShowNestedFolderRows) {
          Build-VisibleRowsForVisualSources -Sources $srcsArr -Level $BaseLevel -Mode $mode
        } else {
          Add-DescendantItemsFlattenedForVisualSources -Sources $srcsArr -FixedLevel $BaseLevel -Mode $mode
        }
      } else {
        $scope = [string](Get-PropString -Obj $FolderRow -Names @('Scope') -Fallback '')
        $path  = [string](Get-PropString -Obj $FolderRow -Names @('Path','FullPath','OriginalPath') -Fallback '')
        if (-not [string]::IsNullOrWhiteSpace($scope) -and -not [string]::IsNullOrWhiteSpace($path)) {
          $childNode = Get-NodeByScopePath -Scope $scope -FullPath $path
          if ($childNode) {
            if ([bool]$script:ShowNestedFolderRows) { Build-VisibleRowsForNode -Node $childNode -Level $BaseLevel }
            else { Add-DescendantItemsFlattened -Node $childNode -FixedLevel $BaseLevel }
          }
        }
      }
    } else {
      $scope = [string](Get-PropString -Obj $FolderRow -Names @('Scope') -Fallback '')
      $path  = [string](Get-PropString -Obj $FolderRow -Names @('Path','FullPath','OriginalPath') -Fallback '')
      if (-not [string]::IsNullOrWhiteSpace($scope) -and -not [string]::IsNullOrWhiteSpace($path)) {
        $childNode = Get-NodeByScopePath -Scope $scope -FullPath $path
        if ($childNode) {
          if ([bool]$script:ShowNestedFolderRows) { Build-VisibleRowsForNode -Node $childNode -Level $BaseLevel }
          else { Add-DescendantItemsFlattened -Node $childNode -FixedLevel $BaseLevel }
        }
      }
    }
    return @($tmpRows)
  } finally {
    $script:VisibleRows = $origRows
  }
}

function Try-ToggleFolderRowsFast {
  param([Parameter(Mandatory=$true)][object]$FolderRow)
  try {
    if (-not $FolderRow) { return $false }
    if (-not $script:VisibleRows) { return $false }
    $parentIndex = Get-VisibleRowIndexByRef -Row $FolderRow
    if ($parentIndex -lt 0) { return $false }
    $parentLevel = Get-VisibleRowLevel -Row $FolderRow -Default 0
    [void](Remove-VisibleDescendantSlice -ParentIndex $parentIndex -ParentLevel $parentLevel)
    if ([bool]$FolderRow.IsExpanded) {
      $insertRows = @(Get-FastExpandedRowsForFolder -FolderRow $FolderRow -BaseLevel ($parentLevel + 1))
      if ($insertRows.Count -gt 0) {
        $insertAt = $parentIndex + 1
        foreach ($r in $insertRows) {
          $script:VisibleRows.Insert($insertAt, $r)
          $insertAt++
        }
      }
    }
    try { Ensure-MidGridScrollBarWiring } catch {}
    try { Queue-MidGridScrollBarSync -LayoutUpdate:$true } catch {}
    return $true
  } catch {
    return $false
  }
}

function Try-SetAllFoldersExpandedFast {
  param([Parameter(Mandatory=$true)][bool]$Expanded)
  try {
    if (-not $script:VisibleRows) { return $false }
    if ($script:VisibleRows.Count -le 0) { return $true }
    $i = 0
    while ($i -lt $script:VisibleRows.Count) {
      $row = $script:VisibleRows[$i]
      $rk = ''
      try { $rk = [string](Get-PropString -Obj $row -Names @('RowKind') -Fallback '') } catch { $rk = '' }
      if ($rk -ne 'Folder') { $i++; continue }
      $lvl = Get-VisibleRowLevel -Row $row -Default 0
      [void](Remove-VisibleDescendantSlice -ParentIndex $i -ParentLevel $lvl)
      if ($Expanded) {
        $insertRows = @(Get-FastExpandedRowsForFolder -FolderRow $row -BaseLevel ($lvl + 1))
        if ($insertRows.Count -gt 0) {
          $insertAt = $i + 1
          foreach ($r in $insertRows) {
            $script:VisibleRows.Insert($insertAt, $r)
            $insertAt++
          }
          # Descendant subtree is already injected in final state; skip across it.
          $i = $insertAt
          continue
        }
      }
      $i++
    }
    try { Ensure-MidGridScrollBarWiring } catch {}
    try { Queue-MidGridScrollBarSync -LayoutUpdate:$true } catch {}
    return $true
  } catch {
    return $false
  }
}

function Add-DescendantItemsFlattened {
  param(
    [Parameter(Mandatory=$true)][FolderNode]$Node,
    [Parameter(Mandatory=$true)][int]$FixedLevel
  )
  if (-not $Node) { return }
  # Items directly in this node ? ALWAYS same fixed indent
  if ($Node.Items) {
    foreach ($it in $Node.Items) {
      Add-RowIndentMeta -Row $it -Level $FixedLevel
      [void]$script:VisibleRows.Add($it)
    }
  }
  # Recurse WITHOUT increasing indent
  if ($Node.Children) {
    foreach ($ch in $Node.Children) {
      Add-DescendantItemsFlattened -Node $ch -FixedLevel $FixedLevel
    }
  }
}

function Add-DescendantItemsFlattenedForVisualSources {
  param(
    [Parameter(Mandatory=$true)][object[]]$Sources,
    [Parameter(Mandatory=$true)][int]$FixedLevel,
    [Parameter(Mandatory=$true)][string]$Mode,
    [hashtable]$Visited = $null
  )
  # Flattened view for VisualMenu expansion:
  # - Merge immediate children across AllUsers + CurrentUser (like Get-VisualMergedImmediateRowsForSources)
  # - Emit only items at a fixed indent
  # - Recurse into folders (also merged) without changing indent
  # IMPORTANT: nested folders are NOT shown in flattened mode, so we must always traverse them
  # (do not require per-folder IsExpanded).
  if (-not $Visited) { $Visited = @{} }
  try {
    $srcKeyParts = @()
    foreach ($s in @($Sources)) {
      if (-not $s) { continue }
      $sc = ''; $fp = ''
      try { $sc = [string]$s.Scope } catch {}
      try { $fp = [string]$s.FullPath } catch {}
      if (-not [string]::IsNullOrWhiteSpace($sc) -and -not [string]::IsNullOrWhiteSpace($fp)) {
        $srcKeyParts += (($sc.Trim().ToLowerInvariant()) + '|' + ($fp.TrimEnd('\').ToLowerInvariant()))
      }
    }
    if ($srcKeyParts.Count -gt 0) {
      $k = ($srcKeyParts | Sort-Object) -join ';'
      if ($Visited.ContainsKey($k)) { return }
      $Visited[$k] = $true
    }
  } catch {}
  $m = $null
  try { $m = Get-VisualMergedImmediateRowsForSources -Sources $Sources } catch { $m = $null }
  if (-not $m) { return }
  $folderRows = @($m.Folders)
  $itemRows   = @($m.Items)
  $ordered = @()
  try { $ordered = Get-OrderedImmediateRows -FolderRows $folderRows -ItemRows $itemRows -Mode $Mode } catch { $ordered = @() }
  foreach ($entry in $ordered) {
    $row = $entry.Row
    if (-not $row) { continue }
    if ($entry.Kind -eq 'Item') {
      Add-RowIndentMeta -Row $row -Level $FixedLevel
      Apply-FolderIconIfNeeded -Row $row
      Ensure-RowIconIfMissing -Row $row
      [void]$script:VisibleRows.Add($row)
      continue
    }
    # Folder entry: recurse (always), but do not emit folder row in flattened mode.
    if ($entry.Kind -eq 'Folder') {
      $srcs = Get-VisualSourcesForFolderRow -Row $row
      $srcsArr = @($srcs)
      if ($srcsArr.Count -gt 0) {
        Add-DescendantItemsFlattenedForVisualSources -Sources $srcsArr -FixedLevel $FixedLevel -Mode $Mode -Visited $Visited
      } else {
        # Fallback: single physical node by scope/path
        $childNode = $null
        try { $childNode = Get-NodeByScopePath -Scope ([string]$row.Scope) -FullPath ([string]$row.Path) } catch { $childNode = $null }
        if ($childNode) { Add-DescendantItemsFlattened -Node $childNode -FixedLevel $FixedLevel }
      }
    }
  }
}

function Get-NodeByScopePath {
  param(
    [Parameter(Mandatory=$true)][string]$Scope,
    [Parameter(Mandatory=$true)][string]$FullPath
  )
  $p = ([string]$FullPath).TrimEnd('\')
  $k = "$Scope|$p"
  if ($script:NodeMap -and $script:NodeMap.ContainsKey($k)) { return $script:NodeMap[$k] }
  if (-not $script:NodeMap) { return $null }
  # Unicode normalization fallback (e.g., symbol/emoji folder names that differ by form).
  foreach ($pv in @(Get-StringNormalizationVariants -Text $p)) {
    $kv = ("{0}|{1}" -f $Scope, ([string]$pv).TrimEnd('\'))
    if ($script:NodeMap.ContainsKey($kv)) { return $script:NodeMap[$kv] }
  }
  # Last resort: compare normalized path forms against keys in this scope only.
  try {
    $targetForms = @(Get-StringNormalizationVariants -Text $p)
    $prefix = ([string]$Scope + '|')
    foreach ($entry in @($script:NodeMap.GetEnumerator())) {
      $ek = ''
      try { $ek = [string]$entry.Key } catch { $ek = '' }
      if ([string]::IsNullOrWhiteSpace($ek)) { continue }
      if (-not $ek.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
      $ep = ''
      try { $ep = $ek.Substring($prefix.Length).TrimEnd('\') } catch { $ep = '' }
      if ([string]::IsNullOrWhiteSpace($ep)) { continue }
      $entryForms = @(Get-StringNormalizationVariants -Text $ep)
      $hit = $false
      foreach ($tf in $targetForms) {
        foreach ($ef in $entryForms) {
          if ($tf.Equals($ef, [System.StringComparison]::OrdinalIgnoreCase)) { $hit = $true; break }
        }
        if ($hit) { break }
      }
      if ($hit) { return $entry.Value }
    }
  } catch {}
  return $null
}

# ------------------------------------------------------------
# META MERGE helpers (dedupe folders/items across profiles by Path)
# ------------------------------------------------------------
function Get-PropString {
  param(
    [Parameter(Mandatory=$true)][object]$Obj,
    [Parameter(Mandatory=$true)][string[]]$Names,
    [string]$Fallback = ""
  )
  foreach ($n in $Names) {
    $p = $Obj.PSObject.Properties[$n]
    if ($p) {
      $v = [string]$p.Value
      if (-not [string]::IsNullOrWhiteSpace($v)) { return $v }
    }
  }
  return $Fallback
}

function Dedup-RowsByPath {
  param(
    [Parameter(Mandatory)][object[]]$Rows,
    [string]$Scope = ''
  )
  $seen = @{}
  $out  = New-Object System.Collections.Generic.List[object]
  foreach ($r in $Rows) {
    if ($null -eq $r) { continue }
    $kind = ''
    foreach ($pn in @('RowKind','Kind','Type')) {
      if ($r.PSObject.Properties.Match($pn).Count -gt 0) {
        $kind = [string]$r.$pn
        break
      }
    }
    # Default: dedupe by absolute path (safe, but doesn't merge across profiles)
    $path = ''
    foreach ($pn in @('FullPath','Path')) {
      if ($r.PSObject.Properties.Match($pn).Count -gt 0) {
        $path = [string]$r.$pn
        break
      }
    }
    if ($null -eq $path) { $path = '' }
    $path = ([string]$path).TrimEnd('\\')
    # Meta view: folders from different profile roots should converge into ONE folder row.
    # Using absolute paths will never dedupe because roots differ.
    # Use a STABLE key: relative path under the scope root (so mock renames do not create duplicates).
    if ($Scope -eq 'Meta' -and $kind -eq 'Folder') {
      $relKey = ''
      try {
        $rowScope = ''
        if ($r.PSObject.Properties.Match('Scope').Count -gt 0) { $rowScope = [string]$r.Scope }
        if (-not [string]::IsNullOrWhiteSpace($rowScope) -and $script:ScopeRoots -and $script:ScopeRoots.ContainsKey($rowScope)) {
          $root = [string]$script:ScopeRoots[$rowScope]
          if (-not [string]::IsNullOrWhiteSpace($root)) {
            $rootN = ([string]$root).TrimEnd('\')
            if (-not [string]::IsNullOrWhiteSpace($rootN) -and $path.StartsWith($rootN, [System.StringComparison]::OrdinalIgnoreCase)) {
              $relKey = $path.Substring($rootN.Length).TrimStart('\')
            }
          }
        }
      } catch {}
      if (-not [string]::IsNullOrWhiteSpace($relKey)) {
        $key = ("FREL\|" + ([string]$relKey).Trim().ToLowerInvariant())
      } else {
        # Fallback: use display/name key
        $nameKey = ''
        foreach ($pn in @('DisplayName','Name','Label')) {
          if ($r.PSObject.Properties.Match($pn).Count -gt 0) {
            $nameKey = [string]$r.$pn
            break
          }
        }
        if ([string]::IsNullOrWhiteSpace($nameKey)) {
          if (-not [string]::IsNullOrWhiteSpace($path)) {
            $nameKey = [IO.Path]::GetFileName($path)
          }
        }
        if ($null -eq $nameKey) { $nameKey = '' }
        $key = ("FNAME\|" + ([string]$nameKey).Trim().ToLowerInvariant())
      }
    }
    else {
      $prefix = if ($kind) { $kind.ToUpperInvariant() } else { 'ROW' }
      $key = ("{0}|{1}" -f $prefix, $path.ToLowerInvariant())
    }
    if (-not $seen.ContainsKey($key)) {
      $seen[$key] = $true
      $out.Add($r) | Out-Null
    }
  }
  return ,$out.ToArray()
}

function New-MergedNodeFromNodes {
  param(
    [Parameter(Mandatory=$true)][object[]]$Nodes,
    [Parameter(Mandatory=$true)][string]$Scope,
    [Parameter(Mandatory=$true)][string]$FullPath,
    [Parameter(Mandatory=$true)][string]$Name
  )
  # FolderNode ctor is (name, fullPath, scope)
  $n = [FolderNode]::new($Name, $FullPath, $Scope)
  # Merge immediate folder rows
  $allFolderRows = @()
  foreach ($node in $Nodes) {
    if ($node -and $node.PSObject.Properties.Match('Folders').Count) {
      $allFolderRows += @($node.Folders)
    }
  }
  if (-not $allFolderRows -or $allFolderRows.Count -eq 0) {
    $folderRows = @()
  } else {
    $folderRows = Dedup-RowsByPath -Rows $allFolderRows -Scope $Scope
  }
  foreach ($fr in $folderRows) { $null = $n.Folders.Add($fr) }
  # Merge immediate item rows
  $allItemRows = @()
  foreach ($node in $Nodes) {
    if ($node -and $node.PSObject.Properties.Match('Items').Count) {
      $allItemRows += @($node.Items)
    }
  }
  if (-not $allItemRows -or $allItemRows.Count -eq 0) {
    $itemRows = @()
  } else {
    $itemRows = Dedup-RowsByPath -Rows $allItemRows -Scope $Scope
  }
  foreach ($ir in $itemRows) { $null = $n.Items.Add($ir) }
  # Merge children FolderNodes (by FullPath)
  $childPathSet = New-Object 'System.Collections.Generic.HashSet[string]'
  foreach ($fr in $folderRows) {
    $p = (Get-PropString -Obj $fr -Names @('Path','FullPath','OriginalPath') -Fallback '').TrimEnd('\')
    if (-not [string]::IsNullOrWhiteSpace($p)) { $null = $childPathSet.Add($p) }
  }
  foreach ($childPath in $childPathSet) {
    $childNodes = @()
    foreach ($node in $Nodes) {
      if (-not $node) { continue }
      foreach ($ch in @($node.Children)) {
        if ($ch -and (([string]$ch.FullPath).TrimEnd('\') -eq ([string]$childPath).TrimEnd('\'))) {
          $childNodes += $ch
        }
      }
    }
    if ($childNodes.Count -gt 0) {
      $childName = [string]$childNodes[0].Name
      if ([string]::IsNullOrWhiteSpace($childName)) { $childName = [System.IO.Path]::GetFileName($childPath) }
      $mergedChild = New-MergedNodeFromNodes -Nodes $childNodes -Scope $Scope -FullPath $childPath -Name $childName
      $null = $n.Children.Add($mergedChild)
    }
  }
  return $n
}

if (-not (Test-Path variable:script:SystemStartupFolderPathSetCache)) { $script:SystemStartupFolderPathSetCache = @() }

function Get-SystemStartupFolderPathSet {
  try {
    $cached = @()
    try { $cached = @($script:SystemStartupFolderPathSetCache) } catch { $cached = @() }
    if ($cached.Count -gt 0) { return $cached }
    $out = New-Object System.Collections.Generic.List[string]
    foreach ($scope in @('CurrentUser','AllUsers')) {
      $root = ''
      try {
        if ($script:ScopeRoots -and $script:ScopeRoots.ContainsKey($scope)) {
          $root = [string]$script:ScopeRoots[$scope]
        }
      } catch { $root = '' }
      if ([string]::IsNullOrWhiteSpace($root)) { continue }
      $startupPath = ''
      try { $startupPath = Normalize-Path (Join-Path $root 'Startup') } catch { $startupPath = '' }
      if ([string]::IsNullOrWhiteSpace($startupPath)) { continue }
      $norm = $startupPath.TrimEnd('\').ToLowerInvariant()
      if (-not [string]::IsNullOrWhiteSpace($norm) -and -not $out.Contains($norm)) {
        [void]$out.Add($norm)
      }
    }
    $arr = @($out.ToArray())
    try { $script:SystemStartupFolderPathSetCache = $arr } catch {}
    return $arr
  } catch {
    return @()
  }
}

function Test-IsStartupFolderPath {
  param([string]$Path)
  try {
    $p = Normalize-Path ([string]$Path)
    if ([string]::IsNullOrWhiteSpace($p)) { return $false }
    $pNorm = $p.TrimEnd('\').ToLowerInvariant()
    if ([string]::IsNullOrWhiteSpace($pNorm)) { return $false }
    $set = @(Get-SystemStartupFolderPathSet)
    foreach ($sp in @($set)) {
      if ([string]::IsNullOrWhiteSpace([string]$sp)) { continue }
      if ($pNorm -eq ([string]$sp).TrimEnd('\').ToLowerInvariant()) { return $true }
    }
  } catch {}
  return $false
}

function Test-IsStartupFolderRow {
  param([object]$Row)
  try {
    if (-not $Row) { return $false }
    $rk = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback '')
    $tp = [string](Get-PropString -Obj $Row -Names @('Type') -Fallback '')
    if ($rk -ne 'Folder' -and $tp -ne 'Folder') { return $false }
    $paths = New-Object System.Collections.Generic.List[string]
    foreach ($pn in @('Path','FullPath','OriginalPath')) {
      $pv = ''
      try { $pv = [string](Get-PropString -Obj $Row -Names @($pn) -Fallback '') } catch { $pv = '' }
      if ([string]::IsNullOrWhiteSpace($pv)) { continue }
      [void]$paths.Add($pv)
    }
    try {
      if ($Row.PSObject.Properties.Match('VisualSources').Count -gt 0 -and @($Row.VisualSources).Count -gt 0) {
        foreach ($src in @($Row.VisualSources)) {
          if (-not $src) { continue }
          $sp = [string](Get-PropString -Obj $src -Names @('FullPath','Path') -Fallback '')
          if ([string]::IsNullOrWhiteSpace($sp)) { continue }
          [void]$paths.Add($sp)
        }
      }
    } catch {}
    foreach ($p in @($paths.ToArray())) {
      if (Test-IsStartupFolderPath -Path ([string]$p)) { return $true }
    }
  } catch {}
  return $false
}

function Add-RowIndentMeta {
  param(
    [Parameter(Mandatory=$true)][object]$Row,
    [Parameter(Mandatory=$true)][int]$Level
  )
  # Level
  if ($Row.PSObject.Properties.Match('Level').Count -eq 0) {
    $Row | Add-Member -NotePropertyName Level -NotePropertyValue $Level -Force
  } else {
    $Row.Level = $Level
  }
  # Indent margin (16px per level)
  $indent = [System.Windows.Thickness]::new(($Level * 16), 0, 0, 0)
  if ($Row.PSObject.Properties.Match('IndentMargin').Count -eq 0) {
    $Row | Add-Member -NotePropertyName IndentMargin -NotePropertyValue $indent -Force
  } else {
    $Row.IndentMargin = $indent
  }
  # IsExpanded (default false)
  if ($Row.PSObject.Properties.Match('IsExpanded').Count -eq 0) {
    $Row | Add-Member -NotePropertyName IsExpanded -NotePropertyValue $false -Force
  }
  # RowKind default
  if ($Row.PSObject.Properties.Match('RowKind').Count -eq 0) {
    $Row | Add-Member -NotePropertyName RowKind -NotePropertyValue 'Item' -Force
  }
  $isStartupFolderRow = $false
  try { $isStartupFolderRow = (Test-IsStartupFolderRow -Row $Row) } catch { $isStartupFolderRow = $false }
  if ($Row.PSObject.Properties.Match('IsStartupFolderRow').Count -eq 0) {
    $Row | Add-Member -NotePropertyName IsStartupFolderRow -NotePropertyValue ([bool]$isStartupFolderRow) -Force
  } else {
    $Row.IsStartupFolderRow = [bool]$isStartupFolderRow
  }
  # Name-column icon accent box visibility (disabled on builds newer than 1809).
  if ($Row.PSObject.Properties.Match('ShowNameIconAccentBox').Count -eq 0) {
    $Row | Add-Member -NotePropertyName ShowNameIconAccentBox -NotePropertyValue ([bool]$script:EnableNameIconAccentBoxes) -Force
  } else {
    $Row.ShowNameIconAccentBox = [bool]$script:EnableNameIconAccentBoxes
  }
  # Visual hint for Type column: filesystem shortcut that replaces a ShellApp launch entry.
  $isShellReplacement = $false
  try {
    $rowKind = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback '')
    $tp = [string](Get-PropString -Obj $Row -Names @('Type') -Fallback '')
    $isAppsProxy = $false
    try { $isAppsProxy = ($Row.PSObject.Properties.Match('IsAppsFolderDisplayProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderDisplayProxy) } catch { $isAppsProxy = $false }
    if ($rowKind -ne 'Folder' -and $tp -eq 'Shortcut' -and -not $isAppsProxy) {
      $tgt = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('Target') -Fallback ''))
      $arg = ''
      try { $arg = ([string](Get-PropString -Obj $Row -Names @('Arguments') -Fallback '')).ToLowerInvariant() } catch { $arg = [string](Get-PropString -Obj $Row -Names @('Arguments') -Fallback '') }
      $isExplorer = $false
      try { $isExplorer = (-not [string]::IsNullOrWhiteSpace($tgt) -and $tgt -match '(?i)\\explorer\.exe$') } catch { $isExplorer = $false }
      if ($isExplorer -and ($arg -like '*shell:appsfolder\\*' -or $arg -like '*windowsdefender:*')) {
        $isShellReplacement = $true
      }
    }
  } catch { $isShellReplacement = $false }
  if ($Row.PSObject.Properties.Match('IsShellAppReplacementShortcut').Count -eq 0) {
    $Row | Add-Member -NotePropertyName IsShellAppReplacementShortcut -NotePropertyValue $isShellReplacement -Force
  } else {
    $Row.IsShellAppReplacementShortcut = $isShellReplacement
  }
  if ($Row.PSObject.Properties.Match('IsTargetTextDuplicate').Count -eq 0) {
    $Row | Add-Member -NotePropertyName IsTargetTextDuplicate -NotePropertyValue $false -Force
  }
  if ($Row.PSObject.Properties.Match('DuplicateTargetOverlayIcon').Count -eq 0) {
    $Row | Add-Member -NotePropertyName DuplicateTargetOverlayIcon -NotePropertyValue (Get-DuplicateTargetOverlayIconSource) -Force
  } elseif (-not $Row.DuplicateTargetOverlayIcon) {
    $Row.DuplicateTargetOverlayIcon = Get-DuplicateTargetOverlayIconSource
  }
  if ($Row.PSObject.Properties.Match('IsBrokenTarget').Count -eq 0) {
    $Row | Add-Member -NotePropertyName IsBrokenTarget -NotePropertyValue $false -Force
  }
  if ($Row.PSObject.Properties.Match('BrokenLinkOverlayIcon').Count -eq 0) {
    $Row | Add-Member -NotePropertyName BrokenLinkOverlayIcon -NotePropertyValue (Get-BrokenLinkOverlayIconSource) -Force
  } elseif (-not $Row.BrokenLinkOverlayIcon) {
    $Row.BrokenLinkOverlayIcon = Get-BrokenLinkOverlayIconSource
  }
  # ViewName (UI-only display name). Reset on every rebuild so VisualMenu overrides don't leak.
  $vn = [string]$Row.Name
  try {
    if ($script:InVisualMenuRebuild) {
      $canOverride = $true
      try {
        if ($Row.PSObject.Properties.Match('Action').Count -gt 0) {
          $a = [string]$Row.Action
          if ($a -eq 'Rename' -or $a -eq 'Delete') { $canOverride = $false }
        }
      } catch {}
      if ($canOverride -and $Row.PSObject.Properties.Match('VisualDisplayName').Count -gt 0) {
        $tmp = [string]$Row.VisualDisplayName
        if (-not [string]::IsNullOrWhiteSpace($tmp)) { $vn = $tmp }
      }
      # Item aliases for visual profile only.
      if ($canOverride -and ($Row.RowKind -ne 'Folder')) {
        $nk = Normalize-VisualKey ([string](Get-PropString -Obj $Row -Names @('Name','OriginalName') -Fallback ''))
        if ($nk -eq 'computer' -or $nk -eq 'this pc') { $vn = 'My PC' }
      }
    }
  } catch {}
  if ($Row.PSObject.Properties.Match('ViewName').Count -eq 0) {
    $Row | Add-Member -NotePropertyName ViewName -NotePropertyValue $vn -Force
  } else {
    $Row.ViewName = $vn
  }
  try { Sync-RowFolderChevronMeta -Row $Row } catch {}
}

function Sync-RowFolderChevronMeta {
  param([Parameter(Mandatory=$true)][object]$Row)
  try {
    if (-not $Row) { return }
    if (Test-IsAlphaSeparatorRow -Row $Row) { return }
    $showFolderChevron = $false
    try {
      $rk = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback '')
      $tp = [string](Get-PropString -Obj $Row -Names @('Type') -Fallback '')
      $showFolderChevron = ($rk -eq 'Folder' -or $tp -eq 'Folder')
    } catch { $showFolderChevron = $false }
    if ($Row.PSObject.Properties.Match('ShowFolderChevron').Count -eq 0) {
      $Row | Add-Member -NotePropertyName ShowFolderChevron -NotePropertyValue $showFolderChevron -Force
    } else {
      $Row.ShowFolderChevron = $showFolderChevron
    }
    $isExpanded = $false
    try {
      if ($Row.PSObject.Properties.Match('IsExpanded').Count -gt 0) {
        $isExpanded = [bool]$Row.IsExpanded
      }
    } catch { $isExpanded = $false }
    $chevronData = if ($showFolderChevron -and $isExpanded) { 'M 4 10 L 7 7 L 10 10' } else { 'M 4 7 L 7 10 L 10 7' }
    if ($Row.PSObject.Properties.Match('FolderChevronData').Count -eq 0) {
      $Row | Add-Member -NotePropertyName FolderChevronData -NotePropertyValue $chevronData -Force
    } else {
      $Row.FolderChevronData = $chevronData
    }
  } catch {}
}

function Refresh-VisibleRowVisual {
  param([object]$Row)
  try {
    if (-not $Row) { return }
    if (-not $script:VisibleRows) { return }
    $idx = -1
    try { $idx = Get-VisibleRowIndexByRef -Row $Row } catch { $idx = -1 }
    if ($idx -lt 0) {
      try { $idx = $script:VisibleRows.IndexOf($Row) } catch { $idx = -1 }
    }
    if ($idx -ge 0) {
      # Force a lightweight row binding refresh (same object, replace event).
      try { $script:VisibleRows[$idx] = $script:VisibleRows[$idx] } catch {}
    }
    try {
      $rc = $null
      if ($grid) { $rc = $grid.ItemContainerGenerator.ContainerFromItem($Row) -as [System.Windows.Controls.DataGridRow] }
      if ($rc) {
        $rc.InvalidateVisual()
        $rc.InvalidateArrange()
        $rc.InvalidateMeasure()
      }
    } catch {}
  } catch {}
}

function Find-FirstVisualChildByName {
  param(
    [System.Windows.DependencyObject]$Root,
    [string]$Name,
    [Type]$Type = $null
  )
  try {
    if (-not $Root) { return $null }
    if ([string]::IsNullOrWhiteSpace($Name)) { return $null }
    $count = 0
    try { $count = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($Root) } catch { $count = 0 }
    for ($i = 0; $i -lt $count; $i++) {
      $child = $null
      try { $child = [System.Windows.Media.VisualTreeHelper]::GetChild($Root, $i) } catch { $child = $null }
      if (-not $child) { continue }
      $okType = $true
      if ($Type) {
        try { $okType = [bool]$Type.IsAssignableFrom($child.GetType()) } catch { $okType = $false }
      }
      if ($okType -and ($child -is [System.Windows.FrameworkElement])) {
        try {
          if ([string]$child.Name -eq $Name) { return $child }
        } catch {}
      }
      $found = Find-FirstVisualChildByName -Root $child -Name $Name -Type $Type
      if ($found) { return $found }
    }
  } catch {}
  return $null
}

function Refresh-RowFolderChevronBinding {
  param([object]$Row)
  try {
    if (-not $grid -or -not $Row) { return }
    $rowVisual = $null
    try { $rowVisual = $grid.ItemContainerGenerator.ContainerFromItem($Row) } catch { $rowVisual = $null }
    if (-not ($rowVisual -is [System.Windows.Controls.DataGridRow])) { return }
    $path = $null
    try { $path = Find-FirstVisualChildByName -Root $rowVisual -Name 'FolderChevronPath' -Type ([System.Windows.Shapes.Path]) } catch { $path = $null }
    if (-not ($path -is [System.Windows.Shapes.Path])) { return }
    $be = $null
    try { $be = [System.Windows.Data.BindingOperations]::GetBindingExpression($path, [System.Windows.Shapes.Path]::DataProperty) } catch { $be = $null }
    if ($be) {
      try { $be.UpdateTarget() } catch {}
      return
    }
    $d = ''
    try { $d = [string](Get-PropString -Obj $Row -Names @('FolderChevronData') -Fallback '') } catch { $d = '' }
    if (-not [string]::IsNullOrWhiteSpace($d)) {
      try { $path.Data = [System.Windows.Media.Geometry]::Parse($d) } catch {}
    }
  } catch {}
}

function Test-IsAlphaSeparatorRow {
  param([object]$Row)
  try {
    if (-not $Row) { return $false }
    return ($Row.PSObject.Properties.Match('IsAlphaSeparator').Count -gt 0 -and [bool]$Row.IsAlphaSeparator)
  } catch {
    return $false
  }
}

function Get-NearestNonSeparatorGridRow {
  param([int]$AnchorIndex = -1)
  try {
    if (-not $grid) { return $null }
    $items = @($grid.ItemsSource)
    if ($items.Count -le 0) { return $null }
    if ($AnchorIndex -lt 0) { $AnchorIndex = 0 }
    if ($AnchorIndex -ge $items.Count) { $AnchorIndex = $items.Count - 1 }
    for ($offset = 0; $offset -lt $items.Count; $offset++) {
      $down = $AnchorIndex + $offset
      if ($down -ge 0 -and $down -lt $items.Count) {
        $candDown = $items[$down]
        if (-not (Test-IsAlphaSeparatorRow -Row $candDown)) { return $candDown }
      }
      if ($offset -gt 0) {
        $up = $AnchorIndex - $offset
        if ($up -ge 0 -and $up -lt $items.Count) {
          $candUp = $items[$up]
          if (-not (Test-IsAlphaSeparatorRow -Row $candUp)) { return $candUp }
        }
      }
    }
  } catch {}
  return $null
}

function Get-StartMenuAlphaBucketKey {
  param([string]$Name)
  try {
    if ($null -eq $Name) { return '' }
    $s = [string]$Name
    # Trim only regular ASCII leading whitespace.
    # Intentionally DO NOT trim U+00A0 (NBSP) so names like "NBSP+Blender"
    # are bucketed as special-character entries ("&"), not under "B".
    try { $s = [regex]::Replace($s, '^[\u0009\u000A\u000D\u0020]+', '') } catch {}
    if ([string]::IsNullOrEmpty($s)) { return '' }
    $ch = $s[0]
    $cat = [System.Globalization.CharUnicodeInfo]::GetUnicodeCategory($ch)
    if ($cat -eq [System.Globalization.UnicodeCategory]::UppercaseLetter -or
        $cat -eq [System.Globalization.UnicodeCategory]::LowercaseLetter -or
        $cat -eq [System.Globalization.UnicodeCategory]::TitlecaseLetter -or
        $cat -eq [System.Globalization.UnicodeCategory]::ModifierLetter -or
        $cat -eq [System.Globalization.UnicodeCategory]::OtherLetter) {
      return ([string]([char]::ToUpperInvariant($ch)))
    }
    if ([char]::IsDigit($ch)) { return '#' }
    return '&'
  } catch {
    return '&'
  }
}
function New-AlphaSeparatorRow {
  param([Parameter(Mandatory=$true)][string]$Label)
  $row = [pscustomobject]@{
    Id               = ("SEP|" + $Label + "|" + [guid]::NewGuid().ToString())
    Selected         = $false
    Action           = 'None'
    PendingLabel     = ''
    OriginalName     = [string]$Label
    Name             = [string]$Label
    Type             = ''
    Scope            = ''
    Target           = ''
    Arguments        = ''
    Path             = ''
    OriginalPath     = ''
    Icon             = $null
    RowKind          = 'Separator'
    IsAlphaSeparator = $true
  }
  Add-RowIndentMeta -Row $row -Level 0
  try { Set-PropSafeGlobal -Obj $row -Name 'ViewName' -Value ([string]$Label) } catch {}
  return $row
}

function Inject-AlphaSeparatorsIntoVisibleRows {
  try {
    if (-not [bool]$script:ShowAlphaSeparators) { return }
    if (-not $script:VisibleRows -or $script:VisibleRows.Count -le 0) { return }
    if (-not $script:CurrentNode) { return }
    $scope = ''
    try { $scope = [string]$script:CurrentNode.Scope } catch { $scope = '' }
    # Support separators in Simulated Start Menu and profile views.
    if ($scope -notin @('VisualMenu','Meta','DefaultProfile','AllUsers','CurrentUser')) { return }

    $source = @($script:VisibleRows)
    $pendingTop = New-Object System.Collections.Generic.List[object]
    $normal = New-Object System.Collections.Generic.List[object]
    foreach ($r in $source) {
      if (-not $r) { continue }
      $isPendingCreate = $false
      try { $isPendingCreate = ($r.PSObject.Properties.Match('IsPendingCreate').Count -gt 0 -and [bool]$r.IsPendingCreate) } catch { $isPendingCreate = $false }
      if ($isPendingCreate) { [void]$pendingTop.Add($r); continue }
      [void]$normal.Add($r)
    }

    $out = New-Object System.Collections.Generic.List[object]
    $currentBucket = ''
    $currentBucketRows = New-Object System.Collections.Generic.List[object]

    $flushBucket = {
      param([string]$bucketLabel, [System.Collections.Generic.List[object]]$bucketRows)
      if ([string]::IsNullOrWhiteSpace($bucketLabel)) { return }
      if (-not $bucketRows -or $bucketRows.Count -le 0) { return }
      [void]$out.Add((New-AlphaSeparatorRow -Label $bucketLabel))
      if ($bucketLabel -eq '&') {
        foreach ($br in @($bucketRows.ToArray())) {
          if (Test-StartsWithNbspAfterAsciiTrim -Name ([string](Get-PropString -Obj $br -Names @('ViewName','Name','OriginalName') -Fallback ''))) {
            [void]$out.Add($br)
          }
        }
        foreach ($br in @($bucketRows.ToArray())) {
          if (-not (Test-StartsWithNbspAfterAsciiTrim -Name ([string](Get-PropString -Obj $br -Names @('ViewName','Name','OriginalName') -Fallback '')))) {
            [void]$out.Add($br)
          }
        }
      } else {
        foreach ($br in @($bucketRows.ToArray())) { [void]$out.Add($br) }
      }
    }

    foreach ($r in @($normal.ToArray())) {
      if (-not $r) { continue }
      if (Test-IsAlphaSeparatorRow -Row $r) { continue }

      $level = 0
      try {
        if ($r.PSObject.Properties.Match('Level').Count -gt 0) { $level = [int]$r.Level }
      } catch { $level = 0 }

      # Only top-level entries get A-Z separators. Expanded folder children do not.
      if ($level -eq 0) {
        $name = [string](Get-PropString -Obj $r -Names @('ViewName','Name','OriginalName') -Fallback '')
        $bucket = Get-StartMenuAlphaBucketKey -Name $name

        if ([string]::IsNullOrWhiteSpace($bucket)) {
          & $flushBucket $currentBucket $currentBucketRows
          $currentBucket = ''
          $currentBucketRows = New-Object System.Collections.Generic.List[object]
          [void]$out.Add($r)
          continue
        }

        if ($bucket -ne $currentBucket) {
          & $flushBucket $currentBucket $currentBucketRows
          $currentBucket = $bucket
          $currentBucketRows = New-Object System.Collections.Generic.List[object]
        }

        [void]$currentBucketRows.Add($r)
        continue
      }

      # Nested rows: flush any pending top-level bucket first, then append as-is.
      & $flushBucket $currentBucket $currentBucketRows
      $currentBucket = ''
      $currentBucketRows = New-Object System.Collections.Generic.List[object]
      [void]$out.Add($r)
    }

    # Flush final bucket.
    & $flushBucket $currentBucket $currentBucketRows

    if ($out.Count -gt 0 -or $pendingTop.Count -gt 0) {
      $script:VisibleRows.Clear()
      foreach ($r in @($pendingTop.ToArray())) { [void]$script:VisibleRows.Add($r) }
      foreach ($r in @($out.ToArray())) { [void]$script:VisibleRows.Add($r) }
    }
  } catch {}
}
function Ensure-SystemFolderIconSmall {
  # Creates or repairs $script:SystemFolderIconSmall (handles null cache safely).
  $needsRefresh = $true
  if (Test-Path variable:script:SystemFolderIconSmall) {
    try { $needsRefresh = ($null -eq $script:SystemFolderIconSmall) } catch { $needsRefresh = $true }
  }
  if ($needsRefresh) {
    $tmp = Get-SystemFolderIconImageSource -Size Small
    if ($tmp) {
      $script:SystemFolderIconSmall = $tmp
    } else {
      try { Remove-Variable -Name SystemFolderIconSmall -Scope Script -ErrorAction Stop } catch {}
    }
  }
}

function Apply-FolderIconIfNeeded {
  param([Parameter(Mandatory=$true)][object]$Row)
  # Only for folders
  if ($Row.PSObject.Properties.Match('RowKind').Count -gt 0 -and $Row.RowKind -eq 'Folder') {
    $shouldRotateFolderIcon = $false
    try { $shouldRotateFolderIcon = [bool](Get-IsWindowsBuildAbove1809Runtime) } catch { $shouldRotateFolderIcon = $false }
    try { Set-PropSafeGlobal -Obj $Row -Name 'RotateFolderIcon' -Value ([bool]$shouldRotateFolderIcon) } catch {}
    Ensure-SystemFolderIconSmall
    $iconSrc = $null
    if (Test-Path variable:script:SystemFolderIconSmall) {
      try { $iconSrc = $script:SystemFolderIconSmall } catch { $iconSrc = $null }
    }
    if (-not $iconSrc) {
      try { $iconSrc = Get-FolderRowIcon } catch { $iconSrc = $null }
      if ($iconSrc) { try { $script:SystemFolderIconSmall = $iconSrc } catch {} }
    }
    if ($iconSrc) {
      # Set Icon only if missing/empty
      if ($Row.PSObject.Properties.Match('Icon').Count -eq 0 -or -not $Row.Icon) {
        $Row | Add-Member -NotePropertyName Icon -NotePropertyValue $iconSrc -Force
      }
    }
  }
}

function Ensure-RowIconIfMissing {
  param([Parameter(Mandatory=$true)][object]$Row)
  try {
    if (-not $Row) { return }
    if ($Row.PSObject.Properties.Match('Icon').Count -gt 0 -and $Row.Icon) { return }
    $rk = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback 'Item')
    if ($rk -eq 'Folder') { Apply-FolderIconIfNeeded -Row $Row; return }
    $path = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('Path','OriginalPath','FullPath') -Fallback ''))
    $pathResolved = Resolve-ExistingPathLenient -Path $path
    if ([string]::IsNullOrWhiteSpace($pathResolved)) { $pathResolved = $path }
    $pathForChecks = $path
    if (-not [string]::IsNullOrWhiteSpace($pathResolved)) { $pathForChecks = $pathResolved }
    $typ  = [string](Get-PropString -Obj $Row -Names @('Type') -Fallback '')
    # AppsFolder/ShellApp rows: ask Shell for the icon by parsing name.
    if ($typ -eq 'ShellApp' -or $pathForChecks.StartsWith('shell:AppsFolder\\', [System.StringComparison]::OrdinalIgnoreCase) -or $pathForChecks.StartsWith('shell:AppsFolder\', [System.StringComparison]::OrdinalIgnoreCase)) {
      $pn = $pathForChecks
      # Some ShellApp rows store just the AppId (no shell: prefix). Normalize it.
      if (-not [string]::IsNullOrWhiteSpace($pn) -and -not $pn.StartsWith('shell:', [System.StringComparison]::OrdinalIgnoreCase)) {
        $pn = ('shell:AppsFolder\' + $pn.TrimStart('\'))
      }
      $img = Get-ImageSourceFromShellParsingName -ParsingName $pn
      if ($img) { Set-PropSafeGlobal -Obj $Row -Name 'Icon' -Value $img; return }
      # Targeted fallback: "This PC" is commonly missing when shell parsing fails.
      try {
        $nm = [string](Get-PropString -Obj $Row -Names @('ViewName','Name','OriginalName') -Fallback '')
        if ($nm -eq 'This PC' -or ($pn -match 'Microsoft\.Windows\.Computer') -or ($pn -match 'MyComputerFolder')) {
          $imageres = Join-Path $env:WINDIR 'System32\imageres.dll'
          if (Test-Path -LiteralPath $imageres) {
            $imgPC = Get-ImageSourceFromIcon -IconPath $imageres -IconIndex 109 -FallbackExePath $imageres
            if ($imgPC) { Set-PropSafeGlobal -Obj $Row -Name 'Icon' -Value $imgPC; return }
          }
        }
      } catch {}
    }
    # For filesystem shortcuts, read icon directly from the .lnk path.
    if ($typ -eq 'Shortcut' -or $pathForChecks.EndsWith('.lnk', [System.StringComparison]::OrdinalIgnoreCase)) {
      $imgFromLnk = $null
      $lnkPath = $null
      try {
        if (-not [string]::IsNullOrWhiteSpace($pathResolved) -and $pathResolved.EndsWith('.lnk', [System.StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $pathResolved)) {
          $lnkPath = $pathResolved
        } elseif (-not [string]::IsNullOrWhiteSpace($path) -and $path.EndsWith('.lnk', [System.StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $path)) {
          $lnkPath = $path
        }
        if (-not [string]::IsNullOrWhiteSpace($lnkPath)) {
          $fallbackTarget = [string](Get-PropString -Obj $Row -Names @('Target') -Fallback '')
          $imgFromLnk = Get-ImageSourceFromIcon -IconPath $lnkPath -IconIndex 0 -FallbackExePath $fallbackTarget
        }
      } catch { $imgFromLnk = $null }
      if ($imgFromLnk) { Set-PropSafeGlobal -Obj $Row -Name 'Icon' -Value $imgFromLnk; return }
    }
    # Normal shortcuts: if the icon location failed, try the target path directly.
    $tN = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('Target') -Fallback ''))
    $tResolved = Resolve-ExistingPathLenient -Path $tN
    if ([string]::IsNullOrWhiteSpace($tResolved)) { $tResolved = $tN }
    $aN = [string](Get-PropString -Obj $Row -Names @('Arguments') -Fallback '')
    try {
      if (-not [string]::IsNullOrWhiteSpace($tResolved) -and $tResolved -match '(?i)\\explorer\.exe$' -and $aN -match '(?i)(MyComputerFolder|Microsoft\.Windows\.Computer)') {
        $imageres3 = Join-Path $env:WINDIR 'System32\imageres.dll'
        if (Test-Path -LiteralPath $imageres3) {
          $imgPC3 = Get-ImageSourceFromIcon -IconPath $imageres3 -IconIndex 109 -FallbackExePath $imageres3
          if ($imgPC3) { Set-PropSafeGlobal -Obj $Row -Name 'Icon' -Value $imgPC3; return }
        }
      }
    } catch {}
    if (-not [string]::IsNullOrWhiteSpace($tResolved) -and (Test-Path -LiteralPath $tResolved)) {
      $img2 = Get-ImageSourceFromIcon -IconPath $tResolved -IconIndex 0 -FallbackExePath $tResolved
      if ($img2) { Set-PropSafeGlobal -Obj $Row -Name 'Icon' -Value $img2; return }
    }
    if (-not [string]::IsNullOrWhiteSpace($tResolved)) {
      try {
        $imgAssoc = Get-ImageSourceFromAssociatedIconPath -Path $tResolved
        if ($imgAssoc) { Set-PropSafeGlobal -Obj $Row -Name 'Icon' -Value $imgAssoc; return }
      } catch {}
      try {
        $imgShell = Get-ImageSourceFromShellFileInfoPath -Path $tResolved -Size Small
        if ($imgShell) { Set-PropSafeGlobal -Obj $Row -Name 'Icon' -Value $imgShell; return }
      } catch {}
    }
    # Name-based fallback: "This PC" is often represented by a shortcut named "computer".
    try {
      $nm2 = [string](Get-PropString -Obj $Row -Names @('ViewName','Name','OriginalName') -Fallback '')
      $nk2 = Normalize-VisualKey $nm2
      if ($nk2 -eq 'this pc' -or $nk2 -eq 'computer') {
        $imageres2 = Join-Path $env:WINDIR 'System32\imageres.dll'
        if (Test-Path -LiteralPath $imageres2) {
          $imgPC2 = Get-ImageSourceFromIcon -IconPath $imageres2 -IconIndex 109 -FallbackExePath $imageres2
          if ($imgPC2) { Set-PropSafeGlobal -Obj $Row -Name 'Icon' -Value $imgPC2; return }
        }
      }
    } catch {}
    # Final fallback: generic application icon.
    $gen = Get-GenericAppIconImageSource
    if ($gen) { Set-PropSafeGlobal -Obj $Row -Name 'Icon' -Value $gen; return }
  } catch {}
}

function Test-FolderRowHasAnyContent {
  param([Parameter(Mandatory=$true)][object]$Row)
  try {
    if (-not $Row) { return $false }
    $rowKind = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback '')
    if ($rowKind -ne 'Folder') {
      $tp = [string](Get-PropString -Obj $Row -Names @('Type') -Fallback '')
      if ($tp -ne 'Folder') { return $true }
    }
    $srcs = @()
    try { $srcs = @(Get-VisualSourcesForFolderRow -Row $Row) } catch { $srcs = @() }
    if ($srcs -and $srcs.Count -gt 0) {
      $m = $null
      try { $m = Get-VisualMergedImmediateRowsForSources -Sources $srcs } catch { $m = $null }
      if ($m) {
        $ic = 0; $fc = 0
        try { if ($m.Items)   { $ic = @($m.Items).Count } } catch { $ic = 0 }
        try { if ($m.Folders) { $fc = @($m.Folders).Count } } catch { $fc = 0 }
        return (($ic + $fc) -gt 0)
      }
    }
    $scope = [string](Get-PropString -Obj $Row -Names @('Scope') -Fallback '')
    $path  = [string](Get-PropString -Obj $Row -Names @('Path','FullPath','OriginalPath') -Fallback '')
    if ([string]::IsNullOrWhiteSpace($scope) -or [string]::IsNullOrWhiteSpace($path)) { return $false }
    $node = $null
    try { $node = Get-NodeByScopePath -Scope $scope -FullPath $path } catch { $node = $null }
    if (-not $node) { return $false }
    $itemCount = 0
    $childCount = 0
    try { if ($node.Items) { $itemCount = $node.Items.Count } } catch { $itemCount = 0 }
    try { if ($node.Children) { $childCount = $node.Children.Count } } catch { $childCount = 0 }
    return (($itemCount + $childCount) -gt 0)
  } catch {
    return $false
  }
}

function Set-AllFoldersExpanded {
  param([Parameter(Mandatory=$true)][bool]$Expanded)
  try {
    if ($script:NodeMap) {
      foreach ($kv in $script:NodeMap.GetEnumerator()) {
        $node = $kv.Value
        if (-not $node -or -not $node.Folders) { continue }
        foreach ($fr in @($node.Folders)) {
          if (-not $fr) { continue }
          try { Set-PropSafeGlobal -Obj $fr -Name 'IsExpanded' -Value $Expanded } catch {}
          try { Sync-RowFolderChevronMeta -Row $fr } catch {}
          try { Refresh-RowFolderChevronBinding -Row $fr } catch {}
          try {
            $vk = Get-VisualFolderStateKey -Row $fr
            if ($vk) { $script:VisualExpandedState[$vk] = $Expanded }
          } catch {}
        }
      }
    }
  } catch {}
  try { Touch-VisualRuntimeState -Reason ("ExpandAllFolders=" + [string]$Expanded) } catch {}
  $didFastSetAll = $false
  try { $didFastSetAll = (Try-SetAllFoldersExpandedFast -Expanded $Expanded) } catch { $didFastSetAll = $false }
  if (-not $didFastSetAll) {
    try { Queue-RebuildVisibleRows } catch {}
  }
}

function Build-VisibleRowsForNode {
  param(
    [Parameter(Mandatory=$true)][FolderNode]$Node,
    [int]$Level = 0
  )
  if (-not $Node) { return }
  # Immediate contents ordering (folders/items) per SortMode
  $folderRows = @()
  $itemRows   = @()
  if ($Node.PSObject.Properties.Match('Folders').Count -gt 0 -and $Node.Folders) {
    $folderRows = @($Node.Folders)
  }
  if ($Node.PSObject.Properties.Match('Items').Count -gt 0 -and $Node.Items) {
    $itemRows = @($Node.Items)
  }
  $mode = 'FoldersFirst'
  try { $mode = [string]$script:SortMode } catch {}
  $ordered = Get-OrderedImmediateRows -FolderRows $folderRows -ItemRows $itemRows -Mode $mode
  foreach ($entry in $ordered) {
    $row  = $entry.Row
    $kind = $entry.Kind  # 'Folder' or 'Item'
    if ($kind -eq 'Folder') {
      if (Test-ShouldHideLegacyAdministrativeToolsFolderRow -Row $row) { continue }
      try { Sync-VisualFolderExpandedStateFromStore -Row $row } catch {}
      Add-RowIndentMeta -Row $row -Level $Level
      Apply-FolderIconIfNeeded -Row $row
      $hasContent = $true
      if (-not [bool]$script:ShowEmptyFolders) {
        $hasContent = Test-FolderRowHasAnyContent -Row $row
      }
      $shouldShowFolderRow = (($Level -eq 0) -or [bool]$script:ShowNestedFolderRows) -and $hasContent
      if ($shouldShowFolderRow) {
        [void]$script:VisibleRows.Add($row)
      }
      $hasPath  = ($row.PSObject.Properties.Match('Path').Count -gt 0)
      $hasScope = ($row.PSObject.Properties.Match('Scope').Count -gt 0)
      if ($hasPath -and $hasScope) {
        $isExpanded = $false
        if ($row.PSObject.Properties.Match('IsExpanded').Count -gt 0) {
          $isExpanded = [bool]$row.IsExpanded
        }
        if ($isExpanded) {
          $childNode = Get-NodeByScopePath -Scope $row.Scope -FullPath $row.Path
          if ($childNode) {
            try {
              $ic = 0; $cc = 0
              try { if ($childNode.Items) { $ic = $childNode.Items.Count } } catch {}
              try { if ($childNode.Children) { $cc = $childNode.Children.Count } } catch {}
            } catch {}
            if ([bool]$script:ShowNestedFolderRows) {
              Build-VisibleRowsForNode -Node $childNode -Level ($Level + 1)
            }
            else {
              Add-DescendantItemsFlattened -Node $childNode -FixedLevel ($Level + 1)
            }
          }
          else {
          }
        }
      }
    } else {
      Add-RowIndentMeta -Row $row -Level $Level
      Ensure-RowIconIfMissing -Row $row
      [void]$script:VisibleRows.Add($row)
    }
  }
}

function Normalize-VisualKey {
  param([string]$s)
  if ([string]::IsNullOrWhiteSpace($s)) { return '' }
  return (($s -replace '\s+',' ').Trim().ToLowerInvariant())
}

function Get-LegacyAdminToolsHideFlagPath {
  try {
    $presetPath = Get-UserPresetFilePath
    if ([string]::IsNullOrWhiteSpace([string]$presetPath)) { return $null }
    $dir = ''
    try { $dir = Split-Path -Parent $presetPath } catch { $dir = '' }
    if ([string]::IsNullOrWhiteSpace($dir)) { return $null }
    return (Join-Path $dir 'hide-legacy-admin-tools.flag')
  } catch { return $null }
}

function Get-LegacyAdministrativeToolsFolderPath {
  try {
    $allUsersRoot = [string]$scopeRoots['AllUsers']
    if ([string]::IsNullOrWhiteSpace($allUsersRoot)) { return $null }
    return (Join-Path $allUsersRoot 'Administrative Tools')
  } catch { return $null }
}

function Get-CurrentUserAdministrativeToolsFolderPath {
  try {
    $currentUserRoot = [string]$scopeRoots['CurrentUser']
    if ([string]::IsNullOrWhiteSpace($currentUserRoot)) { return $null }
    return (Join-Path $currentUserRoot 'Windows Administrative Tools')
  } catch { return $null }
}

function Get-PreparedAdministrativeToolsFolderPath {
  try {
    $allUsersRoot = [string]$scopeRoots['AllUsers']
    if ([string]::IsNullOrWhiteSpace($allUsersRoot)) { return $null }
    return (Join-Path $allUsersRoot 'Windows Administration Tools')
  } catch { return $null }
}

function Test-IsProtectedAdministrativeToolsPath {
  param([string]$PathText)
  try {
    if ([string]::IsNullOrWhiteSpace($PathText)) { return $false }
    $pNorm = ''
    try { $pNorm = (Normalize-Path $PathText).Trim().TrimEnd('\').ToLowerInvariant() } catch { try { $pNorm = [string]$PathText.Trim().TrimEnd('\').ToLowerInvariant() } catch { $pNorm = '' } }
    if ([string]::IsNullOrWhiteSpace($pNorm)) { return $false }
    $roots = New-Object System.Collections.Generic.List[string]
    try { [void]$roots.Add([string](Get-LegacyAdministrativeToolsFolderPath)) } catch {}
    try { [void]$roots.Add([string](Get-CurrentUserAdministrativeToolsFolderPath)) } catch {}
    try { [void]$roots.Add([string](Get-PreparedAdministrativeToolsFolderPath)) } catch {}
    try {
      $curRoot = [string]$scopeRoots['CurrentUser']
      if (-not [string]::IsNullOrWhiteSpace($curRoot)) {
        [void]$roots.Add((Join-Path $curRoot 'Administrative Tools'))
      }
    } catch {}
    foreach ($r in @($roots.ToArray())) {
      if ([string]::IsNullOrWhiteSpace($r)) { continue }
      $rNorm = ''
      try { $rNorm = (Normalize-Path $r).Trim().TrimEnd('\').ToLowerInvariant() } catch { try { $rNorm = [string]$r.Trim().TrimEnd('\').ToLowerInvariant() } catch { $rNorm = '' } }
      if ([string]::IsNullOrWhiteSpace($rNorm)) { continue }
      if ($pNorm -eq $rNorm) { return $true }
      if ($pNorm.StartsWith($rNorm + '\')) { return $true }
    }
    return $false
  } catch {
    return $false
  }
}

function Get-MirroredAdminToolsShortcutRelativeKey {
  param([string]$PathText)
  try {
    if ([string]::IsNullOrWhiteSpace($PathText)) { return '' }
    $pNorm = ''
    try { $pNorm = (Normalize-Path $PathText).Trim().TrimEnd('\').ToLowerInvariant() } catch { try { $pNorm = [string]$PathText.Trim().TrimEnd('\').ToLowerInvariant() } catch { $pNorm = '' } }
    if ([string]::IsNullOrWhiteSpace($pNorm)) { return '' }
    $roots = @(
      [string](Get-LegacyAdministrativeToolsFolderPath),
      [string](Get-CurrentUserAdministrativeToolsFolderPath)
    )
    foreach ($root in @($roots)) {
      if ([string]::IsNullOrWhiteSpace($root)) { continue }
      $rNorm = ''
      try { $rNorm = (Normalize-Path $root).Trim().TrimEnd('\').ToLowerInvariant() } catch { try { $rNorm = [string]$root.Trim().TrimEnd('\').ToLowerInvariant() } catch { $rNorm = '' } }
      if ([string]::IsNullOrWhiteSpace($rNorm)) { continue }
      $prefix = ($rNorm + '\')
      if (-not $pNorm.StartsWith($prefix)) { continue }
      $rel = ''
      try { $rel = [string]$pNorm.Substring($prefix.Length).TrimStart('\') } catch { $rel = '' }
      if (-not [string]::IsNullOrWhiteSpace($rel)) { return $rel }
    }
    return ''
  } catch {
    return ''
  }
}

function Get-DuplicateSignatureInstanceToken {
  param([string]$PathText)
  try {
    $relMirror = ''
    try { $relMirror = [string](Get-MirroredAdminToolsShortcutRelativeKey -PathText $PathText) } catch { $relMirror = '' }
    if (-not [string]::IsNullOrWhiteSpace($relMirror)) {
      return ('mirroradmin|' + $relMirror)
    }
    $pNorm = ''
    try { $pNorm = (Normalize-Path $PathText).Trim().TrimEnd('\').ToLowerInvariant() } catch { try { $pNorm = [string]$PathText.Trim().TrimEnd('\').ToLowerInvariant() } catch { $pNorm = '' } }
    if (-not [string]::IsNullOrWhiteSpace($pNorm)) { return ('path|' + $pNorm) }
    return ''
  } catch {
    return ''
  }
}

function Test-LegacyAdminToolsHideFlag {
  try {
    $fp = Get-LegacyAdminToolsHideFlagPath
    if ([string]::IsNullOrWhiteSpace([string]$fp)) { return $false }
    return (Test-Path -LiteralPath $fp -PathType Leaf)
  } catch { return $false }
}

function Set-LegacyAdminToolsHideFlag {
  param([Parameter(Mandatory=$true)][bool]$Hidden)
  try {
    $fp = Get-LegacyAdminToolsHideFlagPath
    if ([string]::IsNullOrWhiteSpace([string]$fp)) { return }
    $dir = ''
    try { $dir = Split-Path -Parent $fp } catch { $dir = '' }
    if (-not [string]::IsNullOrWhiteSpace($dir) -and -not (Test-Path -LiteralPath $dir -PathType Container)) {
      New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    if ($Hidden) {
      if (-not (Test-Path -LiteralPath $fp -PathType Leaf)) {
        [System.IO.File]::WriteAllText($fp, '1', [System.Text.Encoding]::ASCII)
      }
    } else {
      if (Test-Path -LiteralPath $fp -PathType Leaf) {
        Remove-Item -LiteralPath $fp -Force -ErrorAction SilentlyContinue
      }
    }
  } catch {}
}

function Test-IsLegacyAdministrativeToolsEffectivelyEmpty {
  try {
    $legacy = [string](Get-LegacyAdministrativeToolsFolderPath)
    if ([string]::IsNullOrWhiteSpace($legacy)) { return $false }
    if (-not (Test-Path -LiteralPath $legacy -PathType Container)) { return $false }
    $children = @()
    try { $children = @(Get-ChildItem -LiteralPath $legacy -Force -ErrorAction SilentlyContinue) } catch { $children = @() }
    foreach ($ch in @($children)) {
      if (-not $ch) { continue }
      $nm = ''
      try { $nm = [string]$ch.Name } catch { $nm = '' }
      if ($nm -match '^(?i)desktop\.ini$') { continue }
      return $false
    }
    return $true
  } catch {
    return $false
  }
}

function Sync-LegacyAdminToolsHideFlagFromFilesystem {
  try {
    $hide = $false
    try { $hide = [bool](Test-IsLegacyAdministrativeToolsEffectivelyEmpty) } catch { $hide = $false }
    try { Set-LegacyAdminToolsHideFlag -Hidden $hide } catch {}
    return [bool]$hide
  } catch {
    return $false
  }
}

function Test-IsLegacyAdministrativeToolsFolderRow {
  param([Parameter(Mandatory=$true)][object]$Row)
  try {
    $rk = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback '')
    if ($rk -ne 'Folder') { return $false }
    $legacyPath = [string](Get-LegacyAdministrativeToolsFolderPath)
    $rowPathRaw = [string](Get-PropString -Obj $Row -Names @('Path','OriginalPath','FullPath') -Fallback '')
    $rowPathNorm = ''
    $legacyPathNorm = ''
    try { $rowPathNorm = (Normalize-Path $rowPathRaw).Trim().ToLowerInvariant() } catch { try { $rowPathNorm = $rowPathRaw.Trim().ToLowerInvariant() } catch { $rowPathNorm = '' } }
    try { $legacyPathNorm = (Normalize-Path $legacyPath).Trim().ToLowerInvariant() } catch { try { $legacyPathNorm = [string]$legacyPath } catch { $legacyPathNorm = '' } }
    if (-not [string]::IsNullOrWhiteSpace($legacyPathNorm) -and -not [string]::IsNullOrWhiteSpace($rowPathNorm)) {
      if ($rowPathNorm -eq $legacyPathNorm) { return $true }
      if ($rowPathNorm.EndsWith(('\'+[System.IO.Path]::GetFileName($legacyPathNorm)), [System.StringComparison]::OrdinalIgnoreCase)) {
        if ($rowPathNorm.Contains('\programdata\microsoft\windows\start menu\programs\')) { return $true }
      }
    }
    $names = @()
    foreach ($pn in @('VisualDisplayName','Name','OriginalName')) {
      try {
        if ($Row.PSObject.Properties.Match($pn).Count -gt 0) {
          $v = [string]$Row.$pn
          if (-not [string]::IsNullOrWhiteSpace($v)) { $names += $v }
        }
      } catch {}
    }
    $p = [string](Get-PropString -Obj $Row -Names @('Path','OriginalPath','FullPath') -Fallback '')
    if (-not [string]::IsNullOrWhiteSpace($p)) {
      try {
        $leaf = [System.IO.Path]::GetFileName(($p.TrimEnd('\')))
        if (-not [string]::IsNullOrWhiteSpace($leaf)) { $names += $leaf }
      } catch {}
    }
    foreach ($nm in @($names)) {
      $k = Normalize-VisualKey ([string]$nm)
      if ($k -eq 'windows administration tools') { continue }
      if ($k -in @('windows administrative tools','administrative tools')) {
        # Name-only fallback must stay scoped to ProgramData/AllUsers so
        # CurrentUser Administrative Tools remains visible in the grid.
        if ($rowPathNorm.Contains('\programdata\microsoft\windows\start menu\programs\')) { return $true }
      }
    }
    return $false
  } catch {
    return $false
  }
}

function Test-ShouldHideLegacyAdministrativeToolsFolderRow {
  param([Parameter(Mandatory=$true)][object]$Row)
  try {
    if (-not (Test-LegacyAdminToolsHideFlag)) { return $false }
    if (Test-IsLegacyAdministrativeToolsFolderRow -Row $Row) { return $true }
    # Additional guard: when the legacy-hide flag is active, suppress any
    # empty "Windows Administrative Tools" visual row (regardless of source scope),
    # so Show empty folders cannot surface the placeholder again.
    $rk = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback '')
    if ($rk -ne 'Folder') { return $false }
    $nm = [string](Get-PropString -Obj $Row -Names @('VisualDisplayName','Name','OriginalName') -Fallback '')
    $nk = Normalize-VisualKey $nm
    if ($nk -in @('windows administrative tools','administrative tools')) {
      $hasAny = $true
      try { $hasAny = [bool](Test-FolderRowHasAnyContent -Row $Row) } catch { $hasAny = $true }
      if (-not $hasAny) { return $true }
    }
    return $false
  } catch { return $false }
}

function Get-VisualFolderAliasFamilies {
  return @(
    @('windows accessories','accessories'),
    @('windows administrative tools','administrative tools'),
    @('windows ease of access','accessibility'),
    @('windows system','system tools'),
    @('windows powershell')
  )
}

function Get-VisualFolderFamilyKeys {
  param([string]$Name)
  $nk = Normalize-VisualKey $Name
  if ([string]::IsNullOrWhiteSpace($nk)) { return @() }
  foreach ($fam in (Get-VisualFolderAliasFamilies)) {
    if (-not $fam) { continue }
    if ($fam -contains $nk) { return @($fam) }
  }
  return @($nk)
}

function Test-VisualNameInFamily {
  param(
    [string]$Name,
    [string[]]$FamilyKeys
  )
  $nk = Normalize-VisualKey $Name
  if ([string]::IsNullOrWhiteSpace($nk)) { return $false }
  foreach ($fk in @($FamilyKeys)) {
    if ([string]::IsNullOrWhiteSpace([string]$fk)) { continue }
    $f = [string]$fk
    if ($nk -eq $f) { return $true }
    # Tolerate minor suffix artifacts from previous rename tests (e.g., "...1", "...ll", "...``")
    if ($nk.StartsWith($f) -and (($nk.Length - $f.Length) -le 4)) { return $true }
  }
  return $false
}

function Get-VisualFolderCanonicalKey {
  param([string]$Name)
  $fam = @(Get-VisualFolderFamilyKeys -Name $Name)
  if ($fam -and $fam.Count -gt 0) {
    return ([string]$fam[0])
  }
  return (Normalize-VisualKey $Name)
}

function Merge-VisualRootFolderRowsByFamily {
  param([object[]]$FolderRows)
  if (-not $FolderRows -or $FolderRows.Count -eq 0) { return @() }
  $groups = @{}
  foreach ($r in @($FolderRows)) {
    if (-not $r) { continue }
    $nm = [string](Get-PropString -Obj $r -Names @('Name','OriginalName') -Fallback '')
    $k = Get-VisualFolderCanonicalKey -Name $nm
    if ([string]::IsNullOrWhiteSpace($k)) { continue }
    if (-not $groups.ContainsKey($k)) {
      $groups[$k] = [pscustomobject]@{
        Rep      = $null
        Best     = -1
        Rows     = New-Object System.Collections.Generic.List[object]
      }
    }
    [void]$groups[$k].Rows.Add($r)
    $score = 0
    $sc = [string](Get-PropString -Obj $r -Names @('Scope') -Fallback '')
    if ($sc -eq 'AllUsers') { $score += 50 }
    elseif ($sc -eq 'CurrentUser') { $score += 40 }
    $nk = Normalize-VisualKey $nm
    if ($nk -eq $k) { $score += 20 }
    $p = [string](Get-PropString -Obj $r -Names @('Path','FullPath') -Fallback '')
    if (-not [string]::IsNullOrWhiteSpace($p)) {
      try {
        $leaf = [System.IO.Path]::GetFileName($p)
        if ((Normalize-VisualKey $leaf) -eq $k) { $score += 10 }
      } catch {}
    }
    if ($score -gt [int]$groups[$k].Best) {
      $groups[$k].Best = $score
      $groups[$k].Rep  = $r
    }
  }
  $out = New-Object System.Collections.Generic.List[object]
  foreach ($g in @($groups.Values)) {
    if (-not $g -or -not $g.Rep) { continue }
    $sources = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    function _add {
      param([string]$S,[string]$P)
      if ([string]::IsNullOrWhiteSpace($S) -or [string]::IsNullOrWhiteSpace($P)) { return }
      $kk = (($S.Trim().ToLowerInvariant()) + '|' + ($P.TrimEnd('\').ToLowerInvariant()))
      if ($seen.ContainsKey($kk)) { return }
      $seen[$kk] = $true
      [void]$sources.Add([pscustomobject]@{ Scope=$S; FullPath=$P })
    }
    foreach ($r in @($g.Rows)) {
      if (-not $r) { continue }
      $sc = [string](Get-PropString -Obj $r -Names @('Scope') -Fallback '')
      $pp = [string](Get-PropString -Obj $r -Names @('Path','FullPath') -Fallback '')
      _add -S $sc -P $pp
    }
    try { Set-PropSafeGlobal -Obj $g.Rep -Name 'VisualSources' -Value @($sources.ToArray()) } catch {}
    [void]$out.Add($g.Rep)
  }
  return @($out.ToArray())
}

function Get-RelPathUnderScopeRoot {
  param(
    [Parameter(Mandatory=$true)][string]$Scope,
    [Parameter(Mandatory=$true)][string]$FullPath
  )
  try {
    if (-not $scopeRoots.ContainsKey($Scope)) { return $null }
    $root = [string]$scopeRoots[$Scope]
    if ([string]::IsNullOrWhiteSpace($root)) { return $null }
    $rootN = ([string]$root).TrimEnd('\')
    $pN    = ([string]$FullPath).TrimEnd('\')
    if ($pN.StartsWith($rootN, [System.StringComparison]::OrdinalIgnoreCase)) {
      return ($pN.Substring($rootN.Length).TrimStart('\'))
    }
    return $null
  } catch {
    return $null
  }
}

function Get-VisualSourcesForFolderRow {
  param([Parameter(Mandatory=$true)][object]$Row)
  try {
    if ($Row.PSObject.Properties.Match('VisualSources').Count -gt 0 -and $Row.VisualSources) {
      $arr = @($Row.VisualSources)
      if ($arr.Count -gt 0) { return $arr }
    }
  } catch {}
  $scope = [string](Get-PropString -Obj $Row -Names @('Scope') -Fallback '')
  $path  = [string](Get-PropString -Obj $Row -Names @('Path','FullPath','OriginalPath') -Fallback '')
  if ([string]::IsNullOrWhiteSpace($scope) -or [string]::IsNullOrWhiteSpace($path)) { return @() }
  return @([pscustomobject]@{ Scope=$scope; FullPath=$path })
}

function Ensure-VisualSourcesForRootFolderRows {
  param([Parameter(Mandatory=$true)][object[]]$FolderRows)
  foreach ($r in $FolderRows) {
    if (-not $r) { continue }
    try {
      # One-time resolution per row instance; avoid rescanning filesystem every rebuild.
      $existingSources = @()
      try {
        if ($r.PSObject.Properties.Match('VisualSources').Count -gt 0 -and $r.VisualSources) {
          $existingSources = @($r.VisualSources)
        }
      } catch { $existingSources = @() }
      if ($existingSources.Count -gt 0) { continue }
      $scope = [string](Get-PropString -Obj $r -Names @('Scope') -Fallback '')
      $path  = [string](Get-PropString -Obj $r -Names @('Path','FullPath') -Fallback '')
      if ([string]::IsNullOrWhiteSpace($scope) -or [string]::IsNullOrWhiteSpace($path)) { continue }
      $sources = New-Object System.Collections.Generic.List[object]
      $seen = @{}
      function _addSource {
        param([string]$S,[string]$P)
        if ([string]::IsNullOrWhiteSpace($S) -or [string]::IsNullOrWhiteSpace($P)) { return }
        $k = (($S.Trim().ToLowerInvariant()) + '|' + ($P.TrimEnd('\').ToLowerInvariant()))
        if ($seen.ContainsKey($k)) { return }
        $seen[$k] = $true
        [void]$sources.Add([pscustomobject]@{ Scope=$S; FullPath=$P })
      }
      _addSource -S $scope -P $path
      $rel = Get-RelPathUnderScopeRoot -Scope $scope -FullPath $path
      if (-not [string]::IsNullOrWhiteSpace($rel)) {
        foreach ($other in @('AllUsers','CurrentUser')) {
          if ($other -eq $scope) { continue }
          if (-not $scopeRoots.ContainsKey($other)) { continue }
          $root = [string]$scopeRoots[$other]
          if ([string]::IsNullOrWhiteSpace($root)) { continue }
          $op = (Join-Path $root $rel).TrimEnd('\')
          $k = "$other|$op"
          if ($script:NodeMap.ContainsKey($k)) {
            _addSource -S $other -P $op
          }
        }
      }
      # Fallback by canonical/default folder families (Windows System <-> System Tools, etc.).
      # This keeps merged-folder actions (select/delete/rename) consistent when physical names differ by scope.
      $rowName = [string](Get-PropString -Obj $r -Names @('Name','OriginalName') -Fallback '')
      $fam = @(Get-VisualFolderFamilyKeys -Name $rowName)
      if ($fam.Count -gt 0) {
        foreach ($sc in @('AllUsers','CurrentUser')) {
          if (-not $scopeRoots.ContainsKey($sc)) { continue }
          $root = [string]$scopeRoots[$sc]
          if ([string]::IsNullOrWhiteSpace($root) -or -not (Test-Path -LiteralPath $root -PathType Container)) { continue }
          foreach ($d in @(Get-ChildItem -LiteralPath $root -Directory -Force -ErrorAction SilentlyContinue)) {
            if (-not $d) { continue }
            if (Test-VisualNameInFamily -Name ([string]$d.Name) -FamilyKeys $fam) {
              _addSource -S $sc -P ([string]$d.FullName)
            }
          }
        }
      }
      Set-PropSafeGlobal -Obj $r -Name 'VisualSources' -Value @($sources.ToArray())
    } catch {}
  }
}

function Get-VisualMergedImmediateRowsForSources {
  param([Parameter(Mandatory=$true)][object[]]$Sources)
  # Cache key is based on normalized source set.
  $cacheKey = ''
  try {
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($src in @($Sources)) {
      if (-not $src) { continue }
      $sc = ''
      $fp = ''
      try { $sc = [string]$src.Scope } catch {}
      try { $fp = [string]$src.FullPath } catch {}
      if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($fp)) { continue }
      $norm = (($sc.Trim().ToLowerInvariant()) + '|' + ($fp.TrimEnd('\').ToLowerInvariant()))
      if (-not [string]::IsNullOrWhiteSpace($norm)) { [void]$parts.Add($norm) }
    }
    if ($parts.Count -gt 0) {
      $cacheKey = ((@($parts.ToArray()) | Sort-Object -Unique) -join ';')
    }
  } catch { $cacheKey = '' }
  if (-not [string]::IsNullOrWhiteSpace($cacheKey)) {
    try {
      if ($script:VisualImmediateMergeCache -and $script:VisualImmediateMergeCache.ContainsKey($cacheKey)) {
        $ce = $script:VisualImmediateMergeCache[$cacheKey]
        $ok = $false
        try {
          $ok = ($ce -and ($ce.NodeMapRef -eq $script:NodeMap) -and ([int]$ce.StateVersion -eq [int]$script:VisualRuntimeStateVersion))
        } catch { $ok = $false }
        if ($ok) {
          return [pscustomobject]@{
            Folders = @($ce.Folders)
            Items   = @($ce.Items)
          }
        }
      }
    } catch {}
  }
  $folderGroups = @{}
  $itemRows = New-Object System.Collections.Generic.List[object]
  $itemSeen = @{}
  foreach ($src in $Sources) {
    if (-not $src) { continue }
    $sc = ''
    $fp = ''
    try { $sc = [string]$src.Scope } catch {}
    try { $fp = [string]$src.FullPath } catch {}
    if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($fp)) { continue }
    $node = Get-NodeByScopePath -Scope $sc -FullPath $fp
    if (-not $node) { continue }
    foreach ($fr in @($node.Folders)) {
      if (-not $fr) { continue }
      $fname = [string](Get-PropString -Obj $fr -Names @('Name') -Fallback '')
      $nameKey = Normalize-VisualKey $fname
      if ([string]::IsNullOrWhiteSpace($nameKey)) { continue }
      if (-not $folderGroups.ContainsKey($nameKey)) {
        $folderGroups[$nameKey] = [pscustomobject]@{
          Rep     = $null
          Sources = New-Object System.Collections.Generic.List[object]
        }
      }
      $frScope = [string](Get-PropString -Obj $fr -Names @('Scope') -Fallback '')
      $frPath  = [string](Get-PropString -Obj $fr -Names @('Path','FullPath') -Fallback '')
      if (-not [string]::IsNullOrWhiteSpace($frScope) -and -not [string]::IsNullOrWhiteSpace($frPath)) {
        [void]$folderGroups[$nameKey].Sources.Add([pscustomobject]@{ Scope=$frScope; FullPath=$frPath })
      }
      if (-not $folderGroups[$nameKey].Rep) {
        $folderGroups[$nameKey].Rep = $fr
      } else {
        try {
          if ([string]$folderGroups[$nameKey].Rep.Scope -ne 'CurrentUser' -and [string]$fr.Scope -eq 'CurrentUser') {
            $folderGroups[$nameKey].Rep = $fr
          }
        } catch {}
      }
    }
    foreach ($it in @($node.Items)) {
      if (-not $it) { continue }
      try { if (Test-IsSettingsAliasShortcutRow -Row $it) { continue } } catch {}
      $dedupeKey = ''
      $itScope = [string](Get-PropString -Obj $it -Names @('Scope') -Fallback '')
      $itPath  = [string](Get-PropString -Obj $it -Names @('OriginalPath','Path','FullPath') -Fallback '')
      if (-not [string]::IsNullOrWhiteSpace($itScope) -and -not [string]::IsNullOrWhiteSpace($itPath)) {
        $dedupeKey = (($itScope.Trim().ToLowerInvariant()) + '|' + ($itPath.TrimEnd('\\').ToLowerInvariant()))
      } elseif (-not [string]::IsNullOrWhiteSpace($itPath)) {
        $dedupeKey = ('path|' + ($itPath.TrimEnd('\\').ToLowerInvariant()))
      } else {
        try {
          $rh = [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($it)
          $dedupeKey = ('ref|' + [string]$rh)
        } catch {
          $dedupeKey = ''
        }
      }
      if (-not [string]::IsNullOrWhiteSpace($dedupeKey)) {
        if ($itemSeen.ContainsKey($dedupeKey)) { continue }
        $itemSeen[$dedupeKey] = $true
      }
      [void]$itemRows.Add($it)
    }
  }
  $folderRows = New-Object System.Collections.Generic.List[object]
  foreach ($g in $folderGroups.Values) {
    if (-not $g -or -not $g.Rep) { continue }
    try { Set-PropSafeGlobal -Obj $g.Rep -Name 'VisualSources' -Value @($g.Sources.ToArray()) } catch {}
    [void]$folderRows.Add($g.Rep)
  }
  $resFolders = @($folderRows.ToArray())
  $resItems   = @($itemRows.ToArray())
  if (-not [string]::IsNullOrWhiteSpace($cacheKey)) {
    try {
      $script:VisualImmediateMergeCache[$cacheKey] = [pscustomobject]@{
        NodeMapRef    = $script:NodeMap
        StateVersion  = [int]$script:VisualRuntimeStateVersion
        Folders       = $resFolders
        Items         = $resItems
      }
    } catch {}
  }
  return [pscustomobject]@{
    Folders = $resFolders
    Items   = $resItems
  }
}

function Prewarm-VisualFolderExpandCache {
  param([switch]$Force)
  try {
    if (-not $script:NodeMap -or $script:NodeMap.Count -le 0) { return }
    if ((-not $Force) -and
        ($script:VisualExpandPrewarmNodeMapRef -eq $script:NodeMap) -and
        ([int]$script:VisualExpandPrewarmStateVersion -eq [int]$script:VisualRuntimeStateVersion)) {
      return
    }
    $script:VisualExpandPrewarmNodeMapRef = $script:NodeMap
    $script:VisualExpandPrewarmStateVersion = [int]$script:VisualRuntimeStateVersion
    $visited = @{}
    function _GetSourceKey {
      param([object[]]$Sources)
      $parts = New-Object System.Collections.Generic.List[string]
      foreach ($src in @($Sources)) {
        if (-not $src) { continue }
        $sc = ''; $fp = ''
        try { $sc = [string]$src.Scope } catch {}
        try { $fp = [string]$src.FullPath } catch {}
        if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($fp)) { continue }
        [void]$parts.Add((($sc.Trim().ToLowerInvariant()) + '|' + ($fp.TrimEnd('\').ToLowerInvariant())))
      }
      if ($parts.Count -le 0) { return '' }
      return ((@($parts.ToArray()) | Sort-Object -Unique) -join ';')
    }
    function _WarmSources {
      param([object[]]$Sources)
      $srcKey = _GetSourceKey -Sources $Sources
      if ([string]::IsNullOrWhiteSpace($srcKey)) { return }
      if ($visited.ContainsKey($srcKey)) { return }
      $visited[$srcKey] = $true
      $m = $null
      try { $m = Get-VisualMergedImmediateRowsForSources -Sources $Sources } catch { $m = $null }
      if (-not $m) { return }
      foreach ($fr in @($m.Folders)) {
        if (-not $fr) { continue }
        $nextSources = @()
        try { $nextSources = @(Get-VisualSourcesForFolderRow -Row $fr) } catch { $nextSources = @() }
        if ($nextSources.Count -gt 0) {
          _WarmSources -Sources $nextSources
        }
      }
    }
    # Start from merged Visual root folders (the same source used by the Name-column folder list).
    $roots = @()
    foreach ($scope in @('AllUsers','CurrentUser')) {
      $rp = $scopeRoots[$scope]
      if ([string]::IsNullOrWhiteSpace($rp)) { continue }
      $k = "$scope|$rp"
      if ($script:NodeMap.ContainsKey($k)) { $roots += $script:NodeMap[$k] }
    }
    if (-not $roots -or $roots.Count -le 0) { return }
    $mergedRoot = New-MergedNodeFromNodes -Nodes $roots -Scope 'Meta' -FullPath '::META::' -Name 'All Profiles'
    $rootFolders = @($mergedRoot.Folders)
    try { $rootFolders = @(Merge-VisualRootFolderRowsByFamily -FolderRows $rootFolders) } catch {}
    try { Ensure-VisualSourcesForRootFolderRows -FolderRows $rootFolders } catch {}
    foreach ($fr in @($rootFolders)) {
      if (-not $fr) { continue }
      $srcs = @()
      try { $srcs = @(Get-VisualSourcesForFolderRow -Row $fr) } catch { $srcs = @() }
      if ($srcs.Count -gt 0) { _WarmSources -Sources $srcs }
    }
  } catch {
  }
}

function Build-VisibleRowsForVisualSources {
  param(
    [Parameter(Mandatory=$true)][object[]]$Sources,
    [Parameter(Mandatory=$true)][int]$Level,
    [Parameter(Mandatory=$true)][string]$Mode
  )
  $m = Get-VisualMergedImmediateRowsForSources -Sources $Sources
  $folderRows = @($m.Folders)
  $itemRows   = @($m.Items)
  $ordered = Get-OrderedImmediateRows -FolderRows $folderRows -ItemRows $itemRows -Mode $Mode
  foreach ($entry in $ordered) {
    $row = $entry.Row
    if (-not $row) { continue }
    if ($entry.Kind -eq 'Folder' -and (Test-ShouldHideLegacyAdministrativeToolsFolderRow -Row $row)) { continue }
    if ($entry.Kind -eq 'Folder') {
      try { Sync-VisualFolderExpandedStateFromStore -Row $row } catch {}
    }
    if ($entry.Kind -eq 'Folder' -and -not [bool]$script:ShowEmptyFolders) {
      $hasContent = $false
      try { $hasContent = Test-FolderRowHasAnyContent -Row $row } catch { $hasContent = $false }
      if (-not $hasContent) { continue }
    }
    Add-RowIndentMeta -Row $row -Level $Level
    Apply-FolderIconIfNeeded -Row $row
    Ensure-RowIconIfMissing -Row $row
    [void]$script:VisibleRows.Add($row)
    if (($entry.Kind -eq 'Folder') -and [bool]$row.IsExpanded) {
      $srcs = Get-VisualSourcesForFolderRow -Row $row
      $srcsArr = @($srcs)
      if ($srcsArr.Count -gt 0) {
        Build-VisibleRowsForVisualSources -Sources $srcsArr -Level ($Level + 1) -Mode $Mode
      }
    }
  }
}

function Get-VisualFolderStateKey {
  param([Parameter(Mandatory=$true)][object]$Row)
  $scope = [string](Get-PropString -Obj $Row -Names @('Scope') -Fallback '')
  $path  = [string](Get-PropString -Obj $Row -Names @('Path','FullPath','OriginalPath') -Fallback '')
  if ([string]::IsNullOrWhiteSpace($scope) -or [string]::IsNullOrWhiteSpace($path)) { return $null }
  return ((($scope.Trim().ToLowerInvariant()) + '|' + ($path.TrimEnd('\').ToLowerInvariant())))
}

function Sync-VisualFolderExpandedStateFromStore {
  param([object]$Row)
  try {
    if (-not $Row) { return }
    $rk = ''
    try { $rk = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback '') } catch { $rk = '' }
    if ($rk -ne 'Folder') { return }
    if ($Row.PSObject.Properties.Match('IsExpanded').Count -eq 0) { return }
    $vk = $null
    try { $vk = Get-VisualFolderStateKey -Row $Row } catch { $vk = $null }
    if (-not [string]::IsNullOrWhiteSpace([string]$vk) -and $script:VisualExpandedState.ContainsKey([string]$vk)) {
      try { Set-PropSafeGlobal -Obj $Row -Name 'IsExpanded' -Value ([bool]$script:VisualExpandedState[[string]$vk]) } catch {}
    }
  } catch {}
}

function New-VisualRowClone {
  param(
    [Parameter(Mandatory=$true)][object]$Row,
    [string]$DisplayName
  )
  $name = if ([string]::IsNullOrWhiteSpace($DisplayName)) { [string](Get-PropString -Obj $Row -Names @('Name') -Fallback '') } else { $DisplayName }
  $origName = [string](Get-PropString -Obj $Row -Names @('OriginalName','Name') -Fallback $name)
  $rowKind = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback 'Item')
  $isExpanded = $false
  if ($rowKind -eq 'Folder') {
    $vk = Get-VisualFolderStateKey -Row $Row
    if ($vk -and $script:VisualExpandedState.ContainsKey($vk)) {
      $isExpanded = [bool]$script:VisualExpandedState[$vk]
    }
  }
  $clone = [pscustomobject]@{
    Id           = [guid]::NewGuid().ToString()
    Selected     = $false
    Action       = 'None'
    PendingLabel = ''
    OriginalName = $origName
    Name         = $name
    Type         = (Get-PropString -Obj $Row -Names @('Type') -Fallback '')
    Scope        = (Get-PropString -Obj $Row -Names @('Scope') -Fallback '')
    Target       = (Get-PropString -Obj $Row -Names @('Target') -Fallback '')
    Path         = (Get-PropString -Obj $Row -Names @('Path') -Fallback '')
    OriginalPath = (Get-PropString -Obj $Row -Names @('OriginalPath','Path') -Fallback '')
    Icon         = $Row.Icon
    RowKind      = $rowKind
    IsExpanded   = $isExpanded
    Level        = 0
    IndentMargin = [System.Windows.Thickness]::new(0,0,0,0)
  }
  if ($rowKind -eq 'Folder') { Apply-FolderIconIfNeeded -Row $clone }
  return $clone
}

function Build-VisualStartMenuRows {
  # VisualMenu should resemble the actual Win10 Start Menu list: a merge of AllUsers + CurrentUser
  # displayed in alphabetical order by what the user sees.
  function _FilterOutRedundantAppsFolderProxies {
    param([Parameter(Mandatory=$true)][object[]]$ItemRows)
    # If a filesystem-backed row exists (shortcut/url), do not show an AppsFolder proxy with the same
    # canonical name. This keeps the grid editable and avoids doubled names.
    $hasRealByKey = @{}
    $hasAnyEdgeLauncher = $false
    foreach ($r in @($ItemRows)) {
      if (-not $r) { continue }
      $isProxy = $false
      try { $isProxy = ($r.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$r.IsAppsFolderProxy) } catch {}
      if ($isProxy) { continue }
      $tp = [string](Get-PropString -Obj $r -Names @('Type') -Fallback '')
      if ($tp -ne 'Shortcut' -and $tp -ne 'Url') { continue }
      try { if (Test-IsSettingsAliasShortcutRow -Row $r) { continue } } catch {}
      # Edge-specific: the Start Menu often shows only the filesystem shortcut if it exists (even if renamed),
      # so suppress the Edge AppsFolder proxy whenever ANY shortcut appears to launch Edge.
      if (-not $hasAnyEdgeLauncher -and $tp -eq 'Shortcut') {
        try {
          $tgt = Normalize-Path ([string](Get-PropString -Obj $r -Names @('Target') -Fallback ''))
          $arg = [string](Get-PropString -Obj $r -Names @('Arguments') -Fallback '')
          $pth = [string](Get-PropString -Obj $r -Names @('Path','OriginalPath') -Fallback '')
          if (-not [string]::IsNullOrWhiteSpace($tgt) -and $tgt -match '(?i)\\msedge\\.exe$') { $hasAnyEdgeLauncher = $true }
          if (-not $hasAnyEdgeLauncher) {
            $a = ''
            try { $a = $arg.ToLowerInvariant() } catch { $a = [string]$arg }
            $p = ''
            try { $p = $pth.ToLowerInvariant() } catch { $p = [string]$pth }
            if ($a -match '(?i)shell:appsfolder\\+msedge') { $hasAnyEdgeLauncher = $true }
            elseif ($p -match '(?i)shell:appsfolder\\+msedge') { $hasAnyEdgeLauncher = $true }
            elseif ($a -match '(?i)shell:appsfolder\\+microsoft\\.microsoftedge_') { $hasAnyEdgeLauncher = $true }
            elseif ($p -match '(?i)shell:appsfolder\\+microsoft\\.microsoftedge_') { $hasAnyEdgeLauncher = $true }
          }
        } catch {}
      }
      foreach ($nm in @(
        [string](Get-PropString -Obj $r -Names @('OriginalName') -Fallback ''),
        [string](Get-PropString -Obj $r -Names @('Name') -Fallback '')
      )) {
        $k = Normalize-VisualKey $nm
        if (-not [string]::IsNullOrWhiteSpace($k)) { $hasRealByKey[$k] = $true }
      }
    }
    $out = New-Object System.Collections.Generic.List[object]
    foreach ($r in @($ItemRows)) {
      if (-not $r) { continue }
      $isProxy = $false
      try { $isProxy = ($r.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$r.IsAppsFolderProxy) } catch {}
      if ($isProxy -and $hasRealByKey.Count -gt 0) {
        # Extra guard: if ANY Edge shortcut exists, never show the Edge AppsFolder proxy (name-independent).
        if ($hasAnyEdgeLauncher) {
          $aid = ''
          try { $aid = [string](Get-PropString -Obj $r -Names @('AppsFolderId') -Fallback '') } catch {}
          $aidK = ''
          try { $aidK = $aid.Trim().ToLowerInvariant() } catch { $aidK = [string]$aid }
          $nm0 = [string](Get-PropString -Obj $r -Names @('OriginalName','Name') -Fallback '')
          $k0 = Normalize-VisualKey $nm0
          $isEdgeProxy = $false
          if ($k0 -eq 'microsoft edge') { $isEdgeProxy = $true }
          elseif (-not [string]::IsNullOrWhiteSpace($aidK) -and ($aidK -match '(^msedge$)' -or $aidK -match 'microsoftedge')) { $isEdgeProxy = $true }
          if ($isEdgeProxy) { continue }
        }
        $nm = [string](Get-PropString -Obj $r -Names @('OriginalName','Name') -Fallback '')
        $k = Normalize-VisualKey $nm
        if (-not [string]::IsNullOrWhiteSpace($k) -and $hasRealByKey.ContainsKey($k)) {
          continue
        }
      }
      [void]$out.Add($r)
    }
    # IMPORTANT: do NOT return a nested array (leading comma) because that becomes a single "row"
    # and breaks sorting/rename/expand logic.
    return $out.ToArray()
  }
  $roots = @()
  foreach ($scope in @('AllUsers','CurrentUser')) {
    $rp = $scopeRoots[$scope]
    if ([string]::IsNullOrWhiteSpace($rp)) { continue }
    $k = "$scope|$rp"
    if ($script:NodeMap.ContainsKey($k)) { $roots += $script:NodeMap[$k] }
  }
  if (-not $roots -or $roots.Count -eq 0) { return }
  if (($null -eq $script:VisualMergedRoot) -or
      ($script:VisualCacheNodeMapRef -ne $script:NodeMap) -or
      ([int]$script:VisualCacheStateVersion -ne [int]$script:VisualRuntimeStateVersion)) {
    $script:VisualMergedRoot = New-MergedNodeFromNodes -Nodes $roots -Scope 'Meta' -FullPath '::META::' -Name 'All Profiles'
    $script:VisualCacheNodeMapRef = $script:NodeMap
    $script:VisualCacheStateVersion = [int]$script:VisualRuntimeStateVersion
  }
  $mergedRoot = $script:VisualMergedRoot
  $folderRows = @($mergedRoot.Folders)
  $itemRows   = @($mergedRoot.Items)
  # Settings in the Start Menu should be represented by an AppsFolder display proxy.
  # The legacy filesystem shortcut "Immersive Control Panel.lnk" is blocked from rename and confuses the grid.
  try {
    if ($itemRows -and $itemRows.Count -gt 0) {
      $keep = New-Object System.Collections.Generic.List[object]
      foreach ($it in @($itemRows)) {
        if (-not $it) { continue }
        try { if (Test-IsSettingsAliasShortcutRow -Row $it) { continue } } catch {}
        [void]$keep.Add($it)
      }
      $itemRows = @($keep.ToArray())
    }
  } catch {}
  # Visual parity with Win10 Start list: suppress maintenance buckets not shown in All apps.
  # Startup can be optionally shown by user toggle.
  if ($folderRows -and $folderRows.Count -gt 0) {
    $hiddenRootFolderKeys = @('maintenance')
    if (-not [bool]$script:ShowStartupFolder) {
      $hiddenRootFolderKeys += @('startup','start up')
    }
    $keepFolders = New-Object System.Collections.Generic.List[object]
    foreach ($fr in @($folderRows)) {
      if (-not $fr) { continue }
      if (Test-ShouldHideLegacyAdministrativeToolsFolderRow -Row $fr) { continue }
      $fn = [string](Get-PropString -Obj $fr -Names @('Name','OriginalName') -Fallback '')
      $fk = Normalize-VisualKey $fn
      if ($hiddenRootFolderKeys -contains $fk) { continue }
      [void]$keepFolders.Add($fr)
    }
    $folderRows = @($keepFolders.ToArray())
  }
  # Collapse alias family duplicates at root (e.g. Accessories + Windows Accessories + Windows Accessories1).
  # One representative row is kept with VisualSources containing all physical sources.
  try { $folderRows = @(Merge-VisualRootFolderRowsByFamily -FolderRows $folderRows) } catch {}
  # Root folder rows are deduped across profiles; attach both physical sources so expansion can union contents.
  Ensure-VisualSourcesForRootFolderRows -FolderRows $folderRows
  # Optional: hide folders that have no immediate child folders/items.
  if (-not [bool]$script:ShowEmptyFolders -and $folderRows -and $folderRows.Count -gt 0) {
    $keepFolders = New-Object System.Collections.Generic.List[object]
    foreach ($fr in @($folderRows)) {
      if (-not $fr) { continue }
      $hasContent = $false
      try { $hasContent = Test-FolderRowHasAnyContent -Row $fr } catch { $hasContent = $false }
      if (-not $hasContent) { continue }
      [void]$keepFolders.Add($fr)
    }
    $folderRows = @($keepFolders.ToArray())
  }
  # Keep root items uncollapsed so duplicates remain visible and only the duplicate overlay flags them.
  $folderAliasToVisual = @{
    'accessories'          = 'Windows Accessories'
    'administrative tools' = 'Windows Administrative Tools'
    'accessibility'        = 'Windows Ease of Access'
    'system tools'         = 'Windows System'
    'windows powershell'   = 'Windows PowerShell'
  }
  # Pre-populate VisualDisplayName for folders so sorting matches what we display.
  foreach ($r in $folderRows) {
    if (-not $r) { continue }
    $display = [string](Get-PropString -Obj $r -Names @('Name') -Fallback '')
    $aliasKey = Normalize-VisualKey $display
    if ($folderAliasToVisual.ContainsKey($aliasKey)) {
      $display = [string]$folderAliasToVisual[$aliasKey]
    }
    Set-PropSafeGlobal -Obj $r -Name 'VisualDisplayName' -Value ([string]$display)
  }
  # Clear VisualDisplayName for non-folders (defensive).
  foreach ($r in $itemRows) {
    if (-not $r) { continue }
    try { Set-PropSafeGlobal -Obj $r -Name 'VisualDisplayName' -Value $null } catch {}
  }
  # If Windows Security exists as an AppsFolder ShellApp, surface a proxy row so it can be edited like a shortcut.
  Ensure-WindowsSecurityProxyRow
  if ($script:WindowsSecurityProxyRow) { $itemRows += $script:WindowsSecurityProxyRow }
  # AppsFolder (ShellApp) entries: build a complete proxy list and surface it in the Visual view.
  # The grid never shows Type=ShellApp; Rebuild-VisibleRows converts these to display-proxy rows.
  try { Ensure-VisualAppsFolderProxyRows } catch {}
  try {
    foreach ($r in @($script:VisualAppsFolderProxyRows)) {
      if (-not $r) { continue }
      # Avoid duplicating the dedicated Windows Security proxy row.
      $nk = ''
      try { $nk = Normalize-VisualKey ([string](Get-PropString -Obj $r -Names @('Name','OriginalName') -Fallback '')) } catch {}
      if ($nk -eq 'windows security') { continue }
      $itemRows += $r
    }
  } catch {}
  # Windows-like ordering: mixed folders/items, sorted by display name.
  $mode = 'Mixed'
  try { $mode = [string]$script:SortMode } catch {}
  if ([string]::IsNullOrWhiteSpace($mode)) { $mode = 'Mixed' }
  $rest = Get-OrderedImmediateRows -FolderRows $folderRows -ItemRows $itemRows -Mode $mode
  foreach ($entry in $rest) {
    $row = $entry.Row
    if (-not $row) { continue }
    # Apply display name overrides for the UI (does not create pending renames).
    if ($entry.Kind -eq 'Folder') {
      $display = [string](Get-PropString -Obj $row -Names @('VisualDisplayName','Name') -Fallback '')
      Set-PropSafeGlobal -Obj $row -Name 'VisualDisplayName' -Value ([string]$display)
      try { Sync-VisualFolderExpandedStateFromStore -Row $row } catch {}
    } else {
      try { Set-PropSafeGlobal -Obj $row -Name 'VisualDisplayName' -Value $null } catch {}
    }
    Add-RowIndentMeta -Row $row -Level 0
    Apply-FolderIconIfNeeded -Row $row
    Ensure-RowIconIfMissing -Row $row
    [void]$script:VisibleRows.Add($row)
    if (([string]$row.RowKind -eq 'Folder') -and [bool]$row.IsExpanded) {
      $srcs = Get-VisualSourcesForFolderRow -Row $row
      $srcsArr = @($srcs)
      if ($srcsArr.Count -gt 0) {
        try {
          $scopes = @()
          foreach ($s in $srcsArr) { try { if ($s -and $s.Scope) { $scopes += [string]$s.Scope } } catch {} }
        } catch {}
        if ([bool]$script:ShowNestedFolderRows) {
          Build-VisibleRowsForVisualSources -Sources $srcsArr -Level 1 -Mode $mode
        } else {
          Add-DescendantItemsFlattenedForVisualSources -Sources $srcsArr -FixedLevel 1 -Mode $mode
        }
      } else {
        # Fallback: single physical node
        $childNode = Get-NodeByScopePath -Scope ([string]$row.Scope) -FullPath ([string]$row.Path)
        if ($childNode) {
          if ([bool]$script:ShowNestedFolderRows) { Build-VisibleRowsForNode -Node $childNode -Level 1 }
          else { Add-DescendantItemsFlattened -Node $childNode -FixedLevel 1 }
        }
      }
    }
  }
}
function Get-NodeItemCountRecursive {
  param([object]$Node)
  if (-not $Node) { return 0 }
  $total = 0
  try {
    if ($Node.PSObject.Properties.Match('Items').Count -gt 0 -and $Node.Items) {
      $total += @($Node.Items).Count
    }
  } catch {}
  try {
    if ($Node.PSObject.Properties.Match('Children').Count -gt 0 -and $Node.Children) {
      foreach ($ch in @($Node.Children)) {
        $total += (Get-NodeItemCountRecursive -Node $ch)
      }
    }
  } catch {}
  return [int]$total
}
function Update-VisualMenuTreeCount {
  try {
    if (-not $script:TreeRoots) { return }
    $visualNode = $null
    foreach ($r in @($script:TreeRoots)) {
      try {
        if ($r -and ($r -is [FolderNode]) -and ([string]$r.Scope -eq 'VisualMenu')) {
          $visualNode = $r
          break
        }
      } catch {}
    }
    if (-not $visualNode) { return }
    $count = 0
    try {
      if ($script:VisualMergedRoot) {
        $count = Get-NodeItemCountRecursive -Node $script:VisualMergedRoot
      }
    } catch { $count = 0 }
    $visualNode.TotalItemCount = [int]$count
    $visualNode.DisplayName = ("{0} ({1})" -f $visualNode.Name, [int]$count)
    try { if ($tree) { $tree.Items.Refresh() } } catch {}
  } catch {}
}

function Get-FirstPathLikeTokenFromArgs {
  param([string]$Args)
  try {
    $a = [string]$Args
    if ([string]::IsNullOrWhiteSpace($a)) { return '' }

    $m = $null
    try { $m = [regex]::Match($a, '"(?<p>(?:[A-Za-z]:\\|\\\\)[^"\r\n]+)"') } catch { $m = $null }
    if ($m -and $m.Success) {
      $p = ''
      try { $p = [string]$m.Groups['p'].Value } catch { $p = '' }
      if (-not [string]::IsNullOrWhiteSpace($p)) { return $p.Trim() }
    }

    $m = $null
    try { $m = [regex]::Match($a, '(?<p>(?:[A-Za-z]:\\|\\\\)[^,\r\n]+)') } catch { $m = $null }
    if ($m -and $m.Success) {
      $p = ''
      try { $p = [string]$m.Groups['p'].Value } catch { $p = '' }
      if (-not [string]::IsNullOrWhiteSpace($p)) { return $p.Trim().Trim('"') }
    }

    $m = $null
    try { $m = [regex]::Match($a, '(?<p>shell:[^\s,]+)') } catch { $m = $null }
    if ($m -and $m.Success) {
      $p = ''
      try { $p = [string]$m.Groups['p'].Value } catch { $p = '' }
      if (-not [string]::IsNullOrWhiteSpace($p)) { return $p.Trim() }
    }
  } catch {}
  return ''
}

function Test-IsDuplicateTargetExemptEntry {
  param(
    [string]$TargetText,
    [string]$ArgumentsText,
    [string]$PathText
  )
  try {
    if ([string]::IsNullOrWhiteSpace($TargetText)) { return $false }
    $t = ''
    try { $t = Normalize-Path ([string]$TargetText) } catch { $t = [string]$TargetText }
    if ([string]::IsNullOrWhiteSpace($t)) { return $false }

    $p = ''
    try { $p = [string]$PathText } catch { $p = '' }

    $tl = ''
    $pl = ''
    try { $tl = $t.Trim().ToLowerInvariant() } catch { $tl = [string]$t }
    try { $pl = (Normalize-Path $p).Trim().ToLowerInvariant() } catch { try { $pl = $p.Trim().ToLowerInvariant() } catch { $pl = '' } }

    # Rule 1:
    # if Target == C:\Windows\explorer.exe AND Path contains immersive control panel AppsFolder id -> exempt
    if ($tl -eq 'c:\windows\explorer.exe' -and $pl.Contains('shell:appsfolder\windows.immersivecontrolpanel_cw5n1h2txyewy!microsoft.windows.immersivecontrolpanel')) { return $true }

    # Rule 2:
    # if Target == C:\Windows\explorer.exe AND Path contains WindowsBackup AppsFolder id -> exempt
    if ($tl -eq 'c:\windows\explorer.exe' -and $pl.Contains('shell:appsfolder\microsoftwindows.client.cbs_cw5n1h2txyewy!windowsbackup')) { return $true }

    # Rule 3:
    # if Target == C:\Windows\explorer.exe AND Path == ...\Programs\Windows Security.lnk -> exempt
    $pNorm2 = ''
    try { $pNorm2 = ($pl -replace '/', '\') } catch { $pNorm2 = $pl }
    $rule3Suffix = 'appdata\roaming\microsoft\windows\start menu\programs\windows security.lnk'
    if ($tl -eq 'c:\windows\explorer.exe' -and -not [string]::IsNullOrWhiteSpace($pNorm2)) {
      if ($pNorm2 -eq $rule3Suffix -or $pNorm2.EndsWith($rule3Suffix, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    }

    # Rule 4:
    # if Target == C:\Windows\explorer.exe AND Path contains Outlook AppsFolder id -> exempt
    if ($tl -eq 'c:\windows\explorer.exe' -and $pl.Contains('shell:appsfolder\microsoft.outlookforwindows_8wekyb3d8bbwe!microsoft.outlookforwindows')) { return $true }

    # Rule 5:
    # if Target == C:\Windows\system32\control.exe AND Path contains ...AppData\Roaming\...\Programs\Windows Administrative Tool.lnk -> exempt
    if ($tl -eq 'c:\windows\system32\control.exe' -and $pl.Contains('appdata\roaming\microsoft\windows\start menu\programs\windows administrative tool.lnk')) { return $true }

    # Rule 6:
    # if Target == C:\Windows\system32\control.exe AND Path == AppData\Roaming\...\Programs\System Tools\Administrative Tools.lnk -> exempt
    $pNorm = ''
    try { $pNorm = ($pl -replace '/', '\') } catch { $pNorm = $pl }
    $rule4Suffix = 'appdata\roaming\microsoft\windows\start menu\programs\system tools\administrative tools.lnk'
    if ($tl -eq 'c:\windows\system32\control.exe' -and -not [string]::IsNullOrWhiteSpace($pNorm)) {
      if ($pNorm -eq $rule4Suffix -or $pNorm.EndsWith($rule4Suffix, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    }

    return $false
  } catch {
    return $false
  }
}

function Test-IsDuplicateTargetExemptText {
  param([string]$TargetText)
  try {
    return (Test-IsDuplicateTargetExemptEntry -TargetText $TargetText -ArgumentsText '' -PathText '')
  } catch {
    return $false
  }
}

function Get-TargetDuplicateEffectiveKey {
  param([object]$Row)
  try {
    if (-not $Row) { return '' }
    $t = ''
    $a = ''
    $p = ''
    try { $t = [string](Get-PropString -Obj $Row -Names @('Target') -Fallback '') } catch { $t = '' }
    try { $a = [string](Get-PropString -Obj $Row -Names @('Arguments','Args') -Fallback '') } catch { $a = '' }
    try { $p = [string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback '') } catch { $p = '' }
    if ([string]::IsNullOrWhiteSpace($t)) { return '' }
    if (Test-IsDuplicateTargetExemptEntry -TargetText $t -ArgumentsText $a -PathText $p) { return '' }
    $kTarget = ''
    $kArgs = ''
    try { $kTarget = (Normalize-Path $t).Trim().ToLowerInvariant() } catch { try { $kTarget = $t.Trim().ToLowerInvariant() } catch { $kTarget = [string]$t } }
    try { $kArgs = ($a -replace '\s+',' ').Trim().ToLowerInvariant() } catch { try { $kArgs = [string]$a } catch { $kArgs = '' } }
    return ($kTarget + '|' + $kArgs)
  } catch {
    return ''
  }
}
function Refresh-VisibleTargetDuplicateOverlayFlags {
  try {
    if (-not $script:VisibleRows) { return }
    $disableDupFlag = $false
    try { $disableDupFlag = [bool]$script:DisableDuplicateShortcutFlagging } catch { $disableDupFlag = $false }

    $overlaySource = $null
    try { $overlaySource = Get-DuplicateTargetOverlayIconSource } catch { $overlaySource = $null }
    $brokenOverlaySource = $null
    try { $brokenOverlaySource = Get-BrokenLinkOverlayIconSource } catch { $brokenOverlaySource = $null }
    $dupSet = @{}
    try {
      if (-not $disableDupFlag) {
        [void](Get-LaunchShortcutDuplicateSummary)
        if ($script:DuplicateTargetPathSet) { $dupSet = $script:DuplicateTargetPathSet }
      } else {
        $dupSet = @{}
      }
    } catch { $dupSet = @{} }

    $effectiveDupSet = @{}
    try {
      foreach ($kv in @($dupSet.GetEnumerator())) {
        try { $effectiveDupSet[[string]$kv.Key] = $true } catch {}
      }
    } catch { $effectiveDupSet = @{} }

    if (-not $disableDupFlag) {
      $visibleCounts = @{}
      $visibleTokensByKey = @{}
      foreach ($vr in @($script:VisibleRows)) {
        if (-not $vr) { continue }
        try { if (Test-IsAlphaSeparatorRow -Row $vr) { continue } } catch {}
        $vt = ''
        try { $vt = [string](Get-PropString -Obj $vr -Names @('Type') -Fallback '') } catch { $vt = '' }
        if ($vt -ne 'Shortcut') { continue }
        $vk = ''
        try { $vk = [string](Get-TargetDuplicateEffectiveKey -Row $vr) } catch { $vk = '' }
        if ([string]::IsNullOrWhiteSpace($vk)) { continue }
        $vPath = ''
        try { $vPath = [string](Get-PropString -Obj $vr -Names @('Path','OriginalPath') -Fallback '') } catch { $vPath = '' }
        $vTok = ''
        try { $vTok = [string](Get-DuplicateSignatureInstanceToken -PathText $vPath) } catch { $vTok = '' }
        if ([string]::IsNullOrWhiteSpace($vTok)) {
          $fallbackToken = ''
          try { $fallbackToken = [string](Get-PropString -Obj $vr -Names @('Name','OriginalName') -Fallback '') } catch { $fallbackToken = '' }
          if ([string]::IsNullOrWhiteSpace($fallbackToken)) {
            try { $fallbackToken = ('row|' + [string][System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($vr)) } catch { $fallbackToken = 'row|unknown' }
          }
          $vTok = ('fallback|' + [string]$fallbackToken.ToLowerInvariant())
        }
        if (-not $visibleTokensByKey.ContainsKey($vk)) { $visibleTokensByKey[$vk] = @{} }
        try { $visibleTokensByKey[$vk][$vTok] = $true } catch {}
        if (-not $visibleCounts.ContainsKey($vk)) { $visibleCounts[$vk] = 0 }
        $visibleCounts[$vk] = [int]$visibleCounts[$vk] + 1
      }
      foreach ($kv in @($visibleTokensByKey.GetEnumerator())) {
        try {
          if ([int]$kv.Value.Count -gt 1) { $effectiveDupSet[[string]$kv.Key] = $true }
        } catch {}
      }
    }

    foreach ($r in @($script:VisibleRows)) {
      if (-not $r) { continue }

      try {
        if ($r.PSObject.Properties.Match('IsTargetTextDuplicate').Count -eq 0) {
          $r | Add-Member -NotePropertyName IsTargetTextDuplicate -NotePropertyValue $false -Force
        } else {
          $r.IsTargetTextDuplicate = $false
        }
      } catch {}

      try {
        if ($r.PSObject.Properties.Match('DuplicateTargetOverlayIcon').Count -eq 0) {
          $r | Add-Member -NotePropertyName DuplicateTargetOverlayIcon -NotePropertyValue $overlaySource -Force
        } else {
          $r.DuplicateTargetOverlayIcon = $overlaySource
        }
      } catch {}
      try {
        if ($r.PSObject.Properties.Match('IsBrokenTarget').Count -eq 0) {
          $r | Add-Member -NotePropertyName IsBrokenTarget -NotePropertyValue $false -Force
        } else {
          $r.IsBrokenTarget = $false
        }
      } catch {}
      try {
        if ($r.PSObject.Properties.Match('BrokenLinkOverlayIcon').Count -eq 0) {
          $r | Add-Member -NotePropertyName BrokenLinkOverlayIcon -NotePropertyValue $brokenOverlaySource -Force
        } else {
          $r.BrokenLinkOverlayIcon = $brokenOverlaySource
        }
      } catch {}

      try { if (Test-IsAlphaSeparatorRow -Row $r) { continue } } catch {}

      $tp = ''
      try { $tp = [string](Get-PropString -Obj $r -Names @('Type') -Fallback '') } catch { $tp = '' }
      if ($tp -ne 'Shortcut') { continue }

      try {
        if (Test-ShortcutRowBrokenTarget -Row $r) { $r.IsBrokenTarget = $true }
      } catch {}

      $k = ''
      try { $k = [string](Get-TargetDuplicateEffectiveKey -Row $r) } catch { $k = '' }
      if ([string]::IsNullOrWhiteSpace($k)) { continue }
      if ($effectiveDupSet.Count -gt 0) {
        try {
          if ($effectiveDupSet.ContainsKey($k)) { $r.IsTargetTextDuplicate = $true }
        } catch {}
      }
    }

    $needsRebuild = $false
    try { $needsRebuild = [bool]$script:DuplicateTargetExpandPendingRebuild } catch { $needsRebuild = $false }
    if ($needsRebuild) {
      try { Queue-RebuildVisibleRows } catch {}
    }
  } catch {}
}

function Get-DuplicateScanSourceRows {
  try {
    $out = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    $addRow = {
      param([object]$Row)
      try {
        if (-not $Row) { return }
        $tp = ''
        try { $tp = [string](Get-PropString -Obj $Row -Names @('Type') -Fallback '') } catch { $tp = '' }
        if ($tp -ne 'Shortcut') { return }
        $scope = ''
        try { $scope = [string](Get-PropString -Obj $Row -Names @('Scope') -Fallback '') } catch { $scope = '' }
        try { $scope = $scope.Trim().ToLowerInvariant() } catch { $scope = [string]$scope }
        $path = ''
        try { $path = [string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback '') } catch { $path = '' }
        $token = ''
        if (-not [string]::IsNullOrWhiteSpace($path)) {
          try { $token = ('path|' + (Normalize-Path $path).Trim().TrimEnd('\').ToLowerInvariant()) } catch { try { $token = ('path|' + [string]$path.Trim().TrimEnd('\').ToLowerInvariant()) } catch { $token = '' } }
        }
        if ([string]::IsNullOrWhiteSpace($token)) {
          try { $token = ('row|' + [string][System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($Row)) } catch { $token = 'row|unknown' }
        }
        $k = (([string]$scope) + '|' + [string]$token)
        if ($seen.ContainsKey($k)) { return }
        $seen[$k] = $true
        [void]$out.Add($Row)
      } catch {}
    }

    $usedLive = $false
    try {
      if ($script:NodeMap -and $script:NodeMap.Count -gt 0) {
        foreach ($kv in @($script:NodeMap.GetEnumerator())) {
          $node = $null
          try { $node = $kv.Value } catch { $node = $null }
          if (-not $node) { continue }
          $items = @()
          try { if ($node.PSObject.Properties.Match('Items').Count -gt 0 -and $node.Items) { $items = @($node.Items) } } catch { $items = @() }
          foreach ($it in @($items)) {
            try { & $addRow $it } catch {}
          }
        }
        if ($out.Count -gt 0) { $usedLive = $true }
      }
    } catch {}

    if (-not $usedLive) {
      foreach ($r in @($script:StartupInventory)) {
        try { & $addRow $r } catch {}
      }
    }

    return @($out.ToArray())
  } catch {
    try { return @($script:StartupInventory) } catch { return @() }
  }
}

function Get-LaunchShortcutDuplicateSummary {
  try {
    $disableDupFlag = $false
    try { $disableDupFlag = [bool]$script:DisableDuplicateShortcutFlagging } catch { $disableDupFlag = $false }
    if ($disableDupFlag) {
      try { $script:DuplicateTargetPathSet = @{} } catch {}
      try { $script:DuplicateTargetPathSetReady = $true } catch {}
      try { $script:LaunchDuplicateReadErrorItems = @() } catch {}
      try { $script:DuplicateTargetExpandPendingRebuild = $false } catch {}
      return [pscustomobject]@{
        TotalLnkScanned                  = 0
        DuplicateGroupsByTargetPath      = 0
        DuplicateGroupsByTargetSignature = 0
        ShortcutReadErrors               = 0
        ReadErrorItems                   = @()
      }
    }
    $rows = @()
    try { $rows = @(Get-DuplicateScanSourceRows) } catch { $rows = @() }
    if ($rows.Count -le 0) {
      try { $rows = @($script:StartupInventory) } catch { $rows = @() }
    }
    if ($rows.Count -le 0) {
      return [pscustomobject]@{
        TotalLnkScanned                 = 0
        DuplicateGroupsByTargetPath     = 0
        DuplicateGroupsByTargetSignature= 0
        ShortcutReadErrors              = 0
        ReadErrorItems                  = @()
      }
    }

    $byTarget = @{}
    $bySignature = @{}
    $bySignatureTokens = @{}
    $scanned = 0
    $readErrors = 0
    $readErrorItems = New-Object System.Collections.Generic.List[string]
    $expandedAnyDuplicateFolders = $false

    foreach ($r in @($rows)) {
      if (-not $r) { continue }

      $tp = ''
      try { $tp = [string](Get-PropString -Obj $r -Names @('Type') -Fallback '') } catch { $tp = '' }
      if ($tp -ne 'Shortcut') { continue }

      $path = ''
      try { $path = [string](Get-PropString -Obj $r -Names @('Path','OriginalPath') -Fallback '') } catch { $path = '' }
      if ([string]::IsNullOrWhiteSpace($path) -or -not ([string]$path).ToLowerInvariant().EndsWith('.lnk')) { continue }

      $scanned++

      $target = ''
      $args = ''
      try { $target = [string](Get-PropString -Obj $r -Names @('Target') -Fallback '') } catch { $target = '' }
      try { $args = [string](Get-PropString -Obj $r -Names @('Arguments','Args') -Fallback '') } catch { $args = '' }

      if ([string]::IsNullOrWhiteSpace($target)) {
        $readErrors++
        $scope = ''
        $name = ''
        try { $scope = [string](Get-PropString -Obj $r -Names @('Scope') -Fallback '') } catch { $scope = '' }
        try { $name = [string](Get-PropString -Obj $r -Names @('Name','OriginalName') -Fallback '') } catch { $name = '' }
        [void]$readErrorItems.Add(('[{0}] {1} -> {2}' -f [string]$scope, [string]$name, [string]$path))
        continue
      }
      if (Test-IsDuplicateTargetExemptEntry -TargetText $target -ArgumentsText $args -PathText $path) { continue }

      $kTarget = ''
      $kSig = ''
      try { $kSig = [string](Get-TargetDuplicateEffectiveKey -Row $r) } catch { $kSig = '' }
      if ([string]::IsNullOrWhiteSpace($kSig)) { continue }
      try {
        $parts = $kSig.Split('|', 2)
        if ($parts.Length -gt 0) { $kTarget = [string]$parts[0] }
      } catch { $kTarget = '' }
      if ([string]::IsNullOrWhiteSpace($kTarget)) { $kTarget = [string]$kSig }

      if (-not [string]::IsNullOrWhiteSpace($kTarget)) {
        if (-not $byTarget.ContainsKey($kTarget)) { $byTarget[$kTarget] = 0 }
        $byTarget[$kTarget] = [int]$byTarget[$kTarget] + 1
      }
      if (-not [string]::IsNullOrWhiteSpace($kSig)) {
        if (-not $bySignature.ContainsKey($kSig)) { $bySignature[$kSig] = 0 }
        $bySignature[$kSig] = [int]$bySignature[$kSig] + 1
        if (-not $bySignatureTokens.ContainsKey($kSig)) { $bySignatureTokens[$kSig] = @{} }
        $instToken = ''
        try { $instToken = [string](Get-DuplicateSignatureInstanceToken -PathText $path) } catch { $instToken = '' }
        if ([string]::IsNullOrWhiteSpace($instToken)) {
          $pathTok = ''
          try { $pathTok = (Normalize-Path $path).Trim().TrimEnd('\').ToLowerInvariant() } catch { try { $pathTok = [string]$path.Trim().TrimEnd('\').ToLowerInvariant() } catch { $pathTok = '' } }
          if (-not [string]::IsNullOrWhiteSpace($pathTok)) { $instToken = ('path|' + $pathTok) }
        }
        if ([string]::IsNullOrWhiteSpace($instToken)) {
          try { $instToken = ('row|' + [string]$scanned) } catch { $instToken = '' }
        }
        if (-not [string]::IsNullOrWhiteSpace($instToken)) {
          try { $bySignatureTokens[$kSig][[string]$instToken] = $true } catch {}
        }
      }
    }

    $dupTargetGroups = 0
    foreach ($kv in @($byTarget.GetEnumerator())) {
      try { if ([int]$kv.Value -gt 1) { $dupTargetGroups++ } } catch {}
    }
    $dupSigGroups = 0
    foreach ($kv in @($bySignatureTokens.GetEnumerator())) {
      try { if (@($kv.Value.Keys).Count -gt 1) { $dupSigGroups++ } } catch {}
    }
    $dupSet = @{}
    foreach ($kv in @($bySignatureTokens.GetEnumerator())) {
      try {
        if (@($kv.Value.Keys).Count -gt 1) { $dupSet[[string]$kv.Key] = $true }
      } catch {}
    }
    if ($dupSet.Count -gt 0) {
      foreach ($r in @($rows)) {
        if (-not $r) { continue }
        $tp = ''
        try { $tp = [string](Get-PropString -Obj $r -Names @('Type') -Fallback '') } catch { $tp = '' }
        if ($tp -ne 'Shortcut') { continue }

        $target = ''
        try { $target = [string](Get-PropString -Obj $r -Names @('Target') -Fallback '') } catch { $target = '' }
        if ([string]::IsNullOrWhiteSpace($target)) { continue }

        $lnkPath = ''
        try { $lnkPath = [string](Get-PropString -Obj $r -Names @('Path','OriginalPath') -Fallback '') } catch { $lnkPath = '' }
        if ([string]::IsNullOrWhiteSpace($lnkPath)) { continue }
        if (-not ([string]$lnkPath).ToLowerInvariant().EndsWith('.lnk')) { continue }
        $args = ''
        try { $args = [string](Get-PropString -Obj $r -Names @('Arguments','Args') -Fallback '') } catch { $args = '' }
        if (Test-IsDuplicateTargetExemptEntry -TargetText $target -ArgumentsText $args -PathText $lnkPath) { continue }
        $kSig = ''
        try { $kSig = [string](Get-TargetDuplicateEffectiveKey -Row $r) } catch { $kSig = '' }
        if ([string]::IsNullOrWhiteSpace($kSig)) { continue }
        if (-not $dupSet.ContainsKey($kSig)) { continue }

        $scopeKey = ''
        try { $scopeKey = [string](Get-PropString -Obj $r -Names @('Scope') -Fallback '') } catch { $scopeKey = '' }
        try { $scopeKey = $scopeKey.Trim().ToLowerInvariant() } catch { $scopeKey = [string]$scopeKey }

        $scopeRoot = ''
        if ($scopeKey -eq 'allusers') {
          try { $scopeRoot = [string]$scopeRoots['AllUsers'] } catch { $scopeRoot = '' }
        } elseif ($scopeKey -eq 'currentuser') {
          try { $scopeRoot = [string]$scopeRoots['CurrentUser'] } catch { $scopeRoot = '' }
        }
        try { $scopeRoot = $scopeRoot.Trim().TrimEnd('\').ToLowerInvariant() } catch {}

        if ([string]::IsNullOrWhiteSpace($scopeRoot)) {
          $lnkLower = ''
          try { $lnkLower = [string]$lnkPath.Trim().TrimEnd('\').ToLowerInvariant() } catch { $lnkLower = '' }
          foreach ($sc in @('AllUsers','CurrentUser')) {
            $sr = ''
            try { $sr = [string]$scopeRoots[$sc] } catch { $sr = '' }
            if ([string]::IsNullOrWhiteSpace($sr)) { continue }
            $srLower = ''
            try { $srLower = [string]$sr.Trim().TrimEnd('\').ToLowerInvariant() } catch { $srLower = '' }
            if ([string]::IsNullOrWhiteSpace($srLower)) { continue }
            if ($lnkLower.StartsWith($srLower)) {
              $scopeRoot = $srLower
              try { $scopeKey = [string]$sc.ToLowerInvariant() } catch { $scopeKey = [string]$sc }
              break
            }
          }
        }

        if ([string]::IsNullOrWhiteSpace($scopeKey) -or [string]::IsNullOrWhiteSpace($scopeRoot)) { continue }

        $parent = ''
        try { $parent = [System.IO.Path]::GetDirectoryName([string]$lnkPath) } catch { $parent = '' }
        if ([string]::IsNullOrWhiteSpace($parent)) {
          try { $parent = Split-Path -LiteralPath ([string]$lnkPath) -Parent } catch { $parent = '' }
        }
        if ([string]::IsNullOrWhiteSpace($parent)) { continue }

        $cur = ''
        try { $cur = [string]$parent.Trim().TrimEnd('\').ToLowerInvariant() } catch { $cur = '' }
        if ([string]::IsNullOrWhiteSpace($cur)) { continue }
        if (-not $cur.StartsWith($scopeRoot)) { continue }

        while ($true) {
          $rel = ''
          try {
            if ($cur.Length -ge $scopeRoot.Length) {
              $rel = [string]$cur.Substring($scopeRoot.Length).TrimStart('\')
            }
          } catch { $rel = '' }

          foreach ($sc2 in @('AllUsers','CurrentUser')) {
            $sr2 = ''
            try { $sr2 = [string]$scopeRoots[$sc2] } catch { $sr2 = '' }
            if ([string]::IsNullOrWhiteSpace($sr2)) { continue }
            try { $sr2 = [string]$sr2.Trim().TrimEnd('\').ToLowerInvariant() } catch { $sr2 = '' }
            if ([string]::IsNullOrWhiteSpace($sr2)) { continue }

            $cur2 = ''
            try {
              if ([string]::IsNullOrWhiteSpace($rel)) {
                $cur2 = $sr2
              } else {
                $cur2 = [string](Join-Path $sr2 $rel).Trim().TrimEnd('\').ToLowerInvariant()
              }
            } catch {
              $cur2 = $sr2
            }
            if ([string]::IsNullOrWhiteSpace($cur2)) { continue }

            $vk = ('{0}|{1}' -f [string]$sc2.ToLowerInvariant(), [string]$cur2)
            $alreadyExpanded = $false
            $hasKey = $false
            try {
              $hasKey = $script:VisualExpandedState.ContainsKey($vk)
              if ($hasKey) { $alreadyExpanded = [bool]$script:VisualExpandedState[$vk] }
            } catch {}
            if (-not $hasKey -or -not $alreadyExpanded) {
              try { $script:VisualExpandedState[$vk] = $true } catch {}
              $expandedAnyDuplicateFolders = $true
            }
          }

          if ($cur -eq $scopeRoot) { break }
          $next = ''
          try { $next = [System.IO.Path]::GetDirectoryName([string]$cur) } catch { $next = '' }
          if ([string]::IsNullOrWhiteSpace($next)) { break }
          try { $next = [string]$next.Trim().TrimEnd('\').ToLowerInvariant() } catch {}
          if ([string]::IsNullOrWhiteSpace($next)) { break }
          if ($next -eq $cur) { break }
          if (-not $next.StartsWith($scopeRoot)) { break }
          $cur = $next
        }
      }
    }
    try { $script:DuplicateTargetPathSet = $dupSet } catch {}
    try { $script:DuplicateTargetPathSetReady = $true } catch {}
    try { $script:LaunchDuplicateReadErrorItems = @($readErrorItems.ToArray()) } catch { $script:LaunchDuplicateReadErrorItems = @() }
    if ($expandedAnyDuplicateFolders) {
      try { Touch-VisualRuntimeState -Reason 'DuplicateTargetAutoExpand' } catch {}
      try { $script:DuplicateTargetExpandPendingRebuild = $true } catch {}
    }

    return [pscustomobject]@{
      TotalLnkScanned                  = [int]$scanned
      DuplicateGroupsByTargetPath      = [int]$dupTargetGroups
      DuplicateGroupsByTargetSignature = [int]$dupSigGroups
      ShortcutReadErrors               = [int]$readErrors
      ReadErrorItems                   = @($readErrorItems.ToArray())
    }
  } catch {
    try { $script:DuplicateTargetPathSet = @{} } catch {}
    try { $script:DuplicateTargetPathSetReady = $true } catch {}
    try { $script:LaunchDuplicateReadErrorItems = @() } catch {}
    try { $script:DuplicateTargetExpandPendingRebuild = $false } catch {}
    return [pscustomobject]@{
      TotalLnkScanned                  = 0
      DuplicateGroupsByTargetPath      = 0
      DuplicateGroupsByTargetSignature = 0
      ShortcutReadErrors               = 0
      ReadErrorItems                   = @()
    }
  }
}

function Try-ShowLaunchDuplicateSummaryPopup {
  try {
    if ([bool]$script:LaunchDuplicateSummaryPopupShown) { return }
    $cnt = 0
    try { $cnt = @($script:VisibleRows).Count } catch { $cnt = 0 }
    if ($cnt -le 0) { return }

    $script:LaunchDuplicateSummaryPopupShown = $true
    $action = [Action]{
      try {
        $s = Get-LaunchShortcutDuplicateSummary
        $msg = @(
          'Duplicate Shortcut Launch Summary'
          ''
          ('Total .lnk scanned: {0}' -f [int]$s.TotalLnkScanned)
          ('Duplicate groups by TargetPath: {0}' -f [int]$s.DuplicateGroupsByTargetPath)
          ('Duplicate groups by Target+Arguments signature: {0}' -f [int]$s.DuplicateGroupsByTargetSignature)
          ('Shortcut read errors: {0}' -f [int]$s.ShortcutReadErrors)
          ''
          'Read-error shortcuts:'
          $(if (@($s.ReadErrorItems).Count -gt 0) { (@($s.ReadErrorItems) -join "`n") } else { '(none)' })
        ) -join "`n"
        [System.Windows.MessageBox]::Show(
          $msg,
          'Duplicate Shortcut Summary',
          [System.Windows.MessageBoxButton]::OK,
          [System.Windows.MessageBoxImage]::Information
        ) | Out-Null
      } catch {}
    }

    if ($window -and $window.Dispatcher) {
      [void]$window.Dispatcher.BeginInvoke($action, [System.Windows.Threading.DispatcherPriority]::Background)
    } else {
      & $action
    }
  } catch {}
}

function Rebuild-VisibleRows {
  if (-not $script:CurrentNode) {
    return
  }
  # Used by Add-RowIndentMeta to decide whether to use VisualDisplayName for ViewName.
  $script:InVisualMenuRebuild = ([string]$script:CurrentNode.Scope -eq 'VisualMenu')
  if ($script:InVisualMenuRebuild) {
    try {
      $disableDupFlag = $false
      try { $disableDupFlag = [bool]$script:DisableDuplicateShortcutFlagging } catch { $disableDupFlag = $false }
      if (-not $disableDupFlag) {
        try { $script:DuplicateTargetPathSetReady = $false } catch {}
      } else {
        try { $script:DuplicateTargetPathSet = @{} } catch {}
        try { $script:DuplicateTargetPathSetReady = $true } catch {}
      }
    } catch {}
  }
  $script:VisibleRows.Clear()
  if ($script:CurrentNode.Scope -eq 'VisualMenu') {
    Build-VisualStartMenuRows
    Update-VisualMenuTreeCount
  }
  elseif ($script:CurrentNode.Scope -eq 'Meta') {
    # Primary: children under the clicked Meta node (Profiles)
    $roots = @()
    if ($script:CurrentNode.Children -and $script:CurrentNode.Children.Count -gt 0) {
      $roots = @($script:CurrentNode.Children | Where-Object { $_ -and $_.Scope -ne 'Meta' })
    }
    # Fallback: look up the known scope roots from NodeMap (works even if Tree/Children wiring is off)
    if (-not $roots -or $roots.Count -eq 0) {
      foreach ($scope in @('DefaultProfile','AllUsers','CurrentUser')) {
        $rp = $scopeRoots[$scope]
        if ([string]::IsNullOrWhiteSpace($rp)) { continue }
        $k = "$scope|$rp"
        if ($script:NodeMap.ContainsKey($k)) { $roots += $script:NodeMap[$k] }
      }
    }
    if (-not $roots -or $roots.Count -eq 0) {
      return
    }
    $mergedRoot = New-MergedNodeFromNodes -Nodes $roots -Scope 'Meta' -FullPath '::META::' -Name 'All Profiles'
    Build-VisibleRowsForNode -Node $mergedRoot -Level 0
  } else {
    Build-VisibleRowsForNode -Node $script:CurrentNode -Level 0
  }
  # Defensive: prevent the same row instance from appearing more than once in the grid.
  # This also prevents "rename once, two rows change" behavior when duplicates are accidental.
  try {
    if ($script:VisibleRows -and $script:VisibleRows.Count -gt 1) {
      $seen = @{}
      $uniq = New-Object System.Collections.Generic.List[object]
      foreach ($r in @($script:VisibleRows)) {
        if (-not $r) { continue }
        $key = $null
        try {
          $id = ''
          if ($r.PSObject.Properties.Match('Id').Count -gt 0) { $id = [string]$r.Id }
          if (-not [string]::IsNullOrWhiteSpace($id)) {
            $key = ('ID|' + $id)
          }
        } catch {}
        if (-not $key) {
          try {
            $rh = [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($r)
            $key = ('REF|' + [string]$rh)
          } catch {
            $key = ('REF|' + [string]($r.GetHashCode()))
          }
        }
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        [void]$uniq.Add($r)
      }
      if ($uniq.Count -ne $script:VisibleRows.Count) {
        $script:VisibleRows.Clear()
        foreach ($r in $uniq) { [void]$script:VisibleRows.Add($r) }
      }
    }
  } catch {}
  # Global rule: never show Type=ShellApp rows in the grid.
  # AppsFolder entries are surfaced as display-proxy rows (Type=Shortcut) by Ensure-VisualAppsFolderProxyRows.
  try {
    if ($script:VisibleRows -and $script:VisibleRows.Count -gt 0) {
      for ($i = ($script:VisibleRows.Count - 1); $i -ge 0; $i--) {
        $r = $script:VisibleRows[$i]
        if (-not $r) { continue }
        $tp = [string](Get-PropString -Obj $r -Names @('Type') -Fallback '')
        if ($tp -eq 'ShellApp') { $script:VisibleRows.RemoveAt($i) }
      }
    }
  } catch {}
  # Add pending "Create" rows at top-level VisualMenu (mock-only until Apply).
  try {
    if ($script:CurrentNode -and ([string]$script:CurrentNode.Scope -eq 'VisualMenu')) {
      Inject-PendingCreateRowsIntoVisible
    }
  } catch {}
  # Optional Start Menu-style A-Z separators in the grid.
  try { Inject-AlphaSeparatorsIntoVisibleRows } catch {}
  try { Refresh-VisibleTargetDuplicateOverlayFlags } catch {}
  try { Invoke-GridColumnWidthConstraintsSafe -RecomputeContentMax } catch {}
  try {
    if ($script:CurrentView) { $script:CurrentView.Refresh() }
    elseif ($grid) { $grid.Items.Refresh() }
  } catch {}
}

# ==============================================================================
# Folder selection + filtering
# ==============================================================================

$script:CurrentNode = $null
$script:CurrentView = $null

function Get-CurrentWindowsVersionLabel {
  try {
    $cv = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop
    $product = ''
    $display = ''
    $build = ''
    $ubr = ''
    try { if ($cv.PSObject.Properties.Match('ProductName').Count -gt 0) { $product = [string]$cv.ProductName } } catch {}
    try {
      if ($cv.PSObject.Properties.Match('DisplayVersion').Count -gt 0) { $display = [string]$cv.DisplayVersion }
      elseif ($cv.PSObject.Properties.Match('ReleaseId').Count -gt 0) { $display = [string]$cv.ReleaseId }
    } catch {}
    try { if ($cv.PSObject.Properties.Match('CurrentBuild').Count -gt 0) { $build = [string]$cv.CurrentBuild } } catch {}
    try { if ($cv.PSObject.Properties.Match('UBR').Count -gt 0) { $ubr = [string]$cv.UBR } } catch {}
    $parts = New-Object System.Collections.Generic.List[string]
    if (-not [string]::IsNullOrWhiteSpace($product)) { [void]$parts.Add($product) }
    if (-not [string]::IsNullOrWhiteSpace($display)) { [void]$parts.Add(("Version {0}" -f $display)) }
    if (-not [string]::IsNullOrWhiteSpace($build)) {
      if (-not [string]::IsNullOrWhiteSpace($ubr)) { [void]$parts.Add(("Build {0}.{1}" -f $build, $ubr)) }
      else { [void]$parts.Add(("Build {0}" -f $build)) }
    }
    if ($parts.Count -gt 0) { return ($parts -join " ") }
  } catch {}
  try {
    $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
    if ($os -and -not [string]::IsNullOrWhiteSpace([string]$os.Caption)) { return [string]$os.Caption }
  } catch {}
  return "Windows"
}

function Set-WindowTitleWithWindowsVersion {
  param([switch]$Force)
  try {
    if (-not $window) { return }
    if ([string]::IsNullOrWhiteSpace([string]$script:AppTitleBase)) {
      try { $script:AppTitleBase = [string]$window.Title } catch { $script:AppTitleBase = 'Start Menu Lite Tools (v0.6.56)' }
    }
    if ($Force -or [string]::IsNullOrWhiteSpace([string]$script:WindowsVersionLabel)) {
      try { $script:WindowsVersionLabel = Get-CurrentWindowsVersionLabel } catch {}
      if ([string]::IsNullOrWhiteSpace([string]$script:WindowsVersionLabel)) { $script:WindowsVersionLabel = 'Windows' }
    }
    $wv = [string]$script:WindowsVersionLabel
    $elevMode = 'Standard'
    try {
      if ([bool](Test-IsElevated)) { $elevMode = 'Admin' }
    } catch { $elevMode = 'Standard' }
    $elevSuffix = ("  |  Elevation: {0}" -f $elevMode)
    $titleText = ''
    if ([string]::IsNullOrWhiteSpace($wv)) {
      $titleText = [string]$script:AppTitleBase
    } else {
      $titleText = ("{0} - {1}" -f [string]$script:AppTitleBase, $wv)
    }
    $window.Title = ($titleText + $elevSuffix)
    try { Sync-CustomTitleBarText } catch {}
  } catch {}
}

function Set-CurrentFolder {
  param([FolderNode]$node)
  $script:CurrentNode = $node
  if (-not $node) {
    $grid.ItemsSource = $null
    return
  }
  # Build the visible “tree list” for the grid
  Rebuild-VisibleRows
  # VisualMenu is an ordered view of the real rows, so keep editing/actions enabled.
  if ($applyBtn)      { $applyBtn.IsEnabled      = $true }
  if ($mockDeleteBtn) { $mockDeleteBtn.IsEnabled = $true }
  if ($unDeleteBtn)   { $unDeleteBtn.IsEnabled   = $true }
  if ($selectAll)     { $selectAll.IsEnabled     = $true }
  if ($grid)          { $grid.IsReadOnly         = $false }
  $view = [System.Windows.Data.CollectionViewSource]::GetDefaultView($script:VisibleRows)
  $script:CurrentView = $view
  $view.Filter = {
    param($o)
    $q = $script:SearchBox.Text
    if ([string]::IsNullOrWhiteSpace($q)) { return $true }
    try { if (Test-IsAlphaSeparatorRow -Row $o) { return $false } } catch {}
    return ($o.Name -like "*$q*") -or ($o.Target -like "*$q*") -or ($o.Path -like "*$q*")
  }
  $grid.ItemsSource = $view
  try { Invoke-GridColumnWidthConstraintsSafe -RecomputeContentMax } catch {}
  Refresh-UIAsync
}

function Get-StartMenuVisualNode {
  foreach ($r in $script:TreeRoots) {
    try { if ($r -and ($r -is [FolderNode]) -and ([string]$r.Scope -eq 'VisualMenu')) { return $r } } catch {}
  }
  return $null
}

function Select-DefaultStartNode {
  try { Ensure-WindowsSecurityProxyRow } catch {}
  $n = Get-StartMenuVisualNode
  if (-not $n -and $script:TreeRoots -and $script:TreeRoots.Count -gt 0) { $n = $script:TreeRoots[0] }
  if (-not $n) { return }
  Set-CurrentFolder -node $n
  try { $tree.SelectedItem = $n } catch {}
}

$tree.Add_SelectedItemChanged({
  $sel = $tree.SelectedItem
  if ($sel -is [FolderNode]) { Set-CurrentFolder -node $sel }
})

$script:SearchBox.Add_TextChanged({ Refresh-UIAsync })

try { Set-StartupSplashStatus -Status "Caching folder contents..." -Value 90 } catch {}
try { Prewarm-VisualFolderExpandCache } catch {}
try { Set-StartupSplashStatus -Status "Selecting default folder..." -Value 93 } catch {}
Select-DefaultStartNode
try { Set-StartupSplashStatus -Status "Finalizing startup..." -Value 96 } catch {}

# ================================================================================================
# INLINE RENAME (FIXED)
# Why this exists:
# - DataGridTemplateColumn + UpdateSourceTrigger=LostFocus means CellEditEnding often fires BEFORE binding updates.
# - hook the actual TextBox in PreparingCellForEdit and commit on LostFocus/Enter.
# - also keep a CellEditEnding safety-net that runs at ContextIdle.
# ================================================================================================

function Invoke-RenameCommit {
  param(
    [Parameter(Mandatory=$true)][object]$Row,
    [Parameter(Mandatory=$true)][string]$NewName,
    [Parameter(Mandatory=$true)][string]$Reason,
    [object]$TextBox = $null
  )
  try {
    if ($script:IsUndoRedo) { return }
    if (-not $Row) { return }
    if (Test-IsAlphaSeparatorRow -Row $Row) { return }
    # Ensure global gate exists (prevents crashes if you forgot to init it elsewhere)
    if (-not (Test-Path variable:script:RenameCommitGateByRowId)) {
      $script:RenameCommitGateByRowId = @{}
    }
    # Block renaming deleted rows
    try {
      if ($Row.PSObject.Properties.Match('Action').Count -gt 0 -and $Row.Action -eq 'Delete') { return }
    } catch {}
    # Pending-created rows must keep their original create identity until Apply.
    try {
      if (Test-IsCreatedPendingRow -Row $Row) { return }
    } catch {}
    # Legacy Settings alias shortcuts are virtualized via AppsFolder proxy; block direct filesystem rename.
    try {
      if (Test-IsSettingsAliasShortcutRow -Row $Row) {
        return
      }
    } catch {}
    $rid  = [string]$Row.Id
    $now  = Get-Date
    $prev = if ($Row.PSObject.Properties.Match('_EditOldName').Count -gt 0) {
      [string]$Row._EditOldName
    } else {
      [string]$Row.Name
    }
    $next = (Trim-NameInputPreserveNbsp -Text ([string]$NewName))
    # ------------------------------------------------------------
    # COMMIT DEDUPE (Enter -> LostFocus -> CellEditEnding pipeline)
    # If we see the same "next" within 500ms, ignore it.
    # ------------------------------------------------------------
    $g = $null
    if ($script:RenameCommitGateByRowId.ContainsKey($rid)) {
      $g = $script:RenameCommitGateByRowId[$rid]
    }
    if ($g -and $g.Name -eq $next -and (($now - $g.At).TotalMilliseconds -lt 500)) {
      Refresh-UIAsync -Priority ([System.Windows.Threading.DispatcherPriority]::Render)
      return
    }
    # Store/refresh gate record (keep invalid dialog fields too)
    $script:RenameCommitGateByRowId[$rid] = [pscustomobject]@{
      At             = $now
      Name           = $next
      LastReason     = $Reason
      InvalidShownAt = ($(if($g){$g.InvalidShownAt}else{[datetime]::MinValue}))
      InvalidName    = ($(if($g){$g.InvalidName}else{[string]::Empty}))
    }
    if ($next -eq $prev) { return }
    # ------------------------------------------------------------
    # Guardrail: default Windows folder families must not be renamed
    # until Prepare Start Menu has been run.
    # ------------------------------------------------------------
    $isDefaultFolderRenameTarget = $false
    try { $isDefaultFolderRenameTarget = (Test-IsDefaultWindowsFolderRenameTargetRow -Row $Row) } catch { $isDefaultFolderRenameTarget = $false }
    if ($isDefaultFolderRenameTarget -and -not (Test-StartMenuPreparedForDefaultFolderRenames -Row $Row)) {
      try {
        $goPrepare = Show-PrepareStartMenuRenameWarningDialog -OwnerWindow $window
        if ($goPrepare) {
          try { Invoke-PrepareStartMenuFlow -SkipIntro } catch {}
        }
      } catch {}
      # Always block this rename attempt unless user retries after Prepare completes.
      try { if ($TextBox -and ($TextBox -is [System.Windows.Controls.TextBox])) { $TextBox.Text = $prev } } catch {}
      try { $Row.Name = $prev } catch {}
      try { Set-PropSafeGlobal -Obj $Row -Name 'ViewName' -Value ([string]$prev) } catch {}
      try { Set-PendingState -it $Row } catch {}
      Refresh-UIAsync -Priority ([System.Windows.Threading.DispatcherPriority]::Render)
      return
    }
    # ------------------------------------------------------------
    # INVALID NAME CHECK + INVALID DIALOG DEDUPE
    # Enter often triggers LostFocus right after, so we must dedupe dialog.
    # ------------------------------------------------------------
    if ([string]::IsNullOrWhiteSpace($next) -or -not (Test-ValidFileName -Name $next)) {
      $g = $script:RenameCommitGateByRowId[$rid]
      if ($g -and $g.InvalidName -eq $next -and (($now - $g.InvalidShownAt).TotalMilliseconds -lt 800)) {
        return
      }
      $g.InvalidShownAt = $now
      $g.InvalidName    = $next
      $script:RenameCommitGateByRowId[$rid] = $g
      [System.Windows.MessageBox]::Show(
        "That name can't be used as a Windows shortcut file name.`nRemove: \ / : * ? "" < > | and avoid trailing dot/space.",
        "Invalid name"
      ) | Out-Null
      # Revert UI/editor AND model
      try { if ($TextBox -and ($TextBox -is [System.Windows.Controls.TextBox])) { $TextBox.Text = $prev } } catch {}
      try { $Row.Name = $prev } catch {}
      try { Set-PendingState -it $Row } catch {}
      try { Set-PropSafeGlobal -Obj $Row -Name 'ViewName' -Value ([string]$prev) } catch {}
      Refresh-UIAsync -Priority ([System.Windows.Threading.DispatcherPriority]::Render)
      return
    }
    # ------------------------------------------------------------
    # Windows Security protected proxy row:
    # - The built-in Apps list entry can't be renamed.
    # - If user tries to rename it, offer to create an editable duplicate shortcut instead.
    # - Do NOT attempt to mask/hide/remove the built-in entry from Start.
    # ------------------------------------------------------------
    $isWinSecProxy = $false
    try { $isWinSecProxy = ($Row.PSObject.Properties.Match('IsWindowsSecurityProxy').Count -gt 0 -and [bool]$Row.IsWindowsSecurityProxy) } catch {}
    if ($isWinSecProxy) {
      $alreadyOk = $false
      try { $alreadyOk = ($Row.PSObject.Properties.Match('WinSecRenameConfirmed').Count -gt 0 -and [bool]$Row.WinSecRenameConfirmed) } catch { $alreadyOk = $false }
      # If a real shortcut already exists, don't prompt again; just keep this proxy unchanged.
      $dupExists = $false
      try { $dupExists = [bool](Test-WindowsSecurityEditableShortcutExists) } catch { $dupExists = $false }
      if ($dupExists) {
        try { if ($TextBox -and ($TextBox -is [System.Windows.Controls.TextBox])) { $TextBox.Text = $prev } } catch {}
        try { $Row.Name = $prev } catch {}
        try { Set-PropSafeGlobal -Obj $Row -Name 'ViewName' -Value ([string]$prev) } catch {}
        try { Set-PendingState -it $Row } catch {}
        Refresh-UIAsync -Priority ([System.Windows.Threading.DispatcherPriority]::Render)
        return
      }
      if (-not $alreadyOk) {
        $msg = @(
          'This Start Menu item cannot be renamed directly.'
          ''
          'Would you like to create an editable duplicate shortcut?'
        ) -join "`n"
        $res = [System.Windows.MessageBox]::Show(
          $msg,
          'Windows Security',
          [System.Windows.MessageBoxButton]::YesNo,
          [System.Windows.MessageBoxImage]::Question
        )
        if ($res -ne [System.Windows.MessageBoxResult]::Yes) {
          # User chose No: skip Windows Security entirely.
          try { if ($TextBox -and ($TextBox -is [System.Windows.Controls.TextBox])) { $TextBox.Text = $prev } } catch {}
          try { $Row.Name = $prev } catch {}
          try { Set-PropSafeGlobal -Obj $Row -Name 'ViewName' -Value ([string]$prev) } catch {}
          try { Set-PendingState -it $Row } catch {}
          Refresh-UIAsync -Priority ([System.Windows.Threading.DispatcherPriority]::Render)
          return
        }
        try { Set-PropSafeGlobal -Obj $Row -Name 'WinSecRenameConfirmed' -Value $true } catch {}
      }
    }
    # ------------------------------------------------------------
    # AppsFolder (ShellApp) proxy rows:
    # - These are not filesystem .lnk files.
    # - If user tries to rename, show a dialog and (if Yes) allow pending rename.
    # Apply will handle it as a special action.
    # ------------------------------------------------------------
    $isAppsProxy = $false
    try { $isAppsProxy = ($Row.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderProxy) } catch {}
    if (-not $isAppsProxy) {
      try { $isAppsProxy = ($Row.PSObject.Properties.Match('IsAppsFolderDisplayProxy').Count -gt 0 -and [bool]$Row.IsAppsFolderDisplayProxy) } catch {}
    }
    if ($isAppsProxy) {
      $alreadyOk = $false
      try { $alreadyOk = ($Row.PSObject.Properties.Match('AppsFolderRenameConfirmed').Count -gt 0 -and [bool]$Row.AppsFolderRenameConfirmed) } catch { $alreadyOk = $false }
      if (-not $alreadyOk) {
        $title = [string](Get-PropString -Obj $Row -Names @('OriginalName','Name') -Fallback 'System App')
        $msg = @(
          'This Start Menu item cannot be renamed directly.'
          ''
          'Would you like to create an editable duplicate shortcut?'
        ) -join "`n"
        $res = [System.Windows.MessageBox]::Show(
          $msg,
          $title,
          [System.Windows.MessageBoxButton]::YesNo,
          [System.Windows.MessageBoxImage]::Question
        )
        if ($res -ne [System.Windows.MessageBoxResult]::Yes) {
          # User chose No: skip this ShellApp entirely.
          try { if ($TextBox -and ($TextBox -is [System.Windows.Controls.TextBox])) { $TextBox.Text = $prev } } catch {}
          try { $Row.Name = $prev } catch {}
          try { Set-PropSafeGlobal -Obj $Row -Name 'ViewName' -Value ([string]$prev) } catch {}
          try { Set-PendingState -it $Row } catch {}
          Refresh-UIAsync -Priority ([System.Windows.Threading.DispatcherPriority]::Render)
          return
        }
        try { Set-PropSafeGlobal -Obj $Row -Name 'AppsFolderRenameConfirmed' -Value $true } catch {}
      }
    }
    # ------------------------------------------------------------
    # APPLY rename + pending
    # ------------------------------------------------------------
    $Row.Name = $next
    try { Set-PropSafeGlobal -Obj $Row -Name 'ViewName' -Value ([string]$next) } catch {}
    # Pending calculation (must NOT reset OriginalName)
    Set-PendingState -it $Row -BumpLabels @('Renamed')
    # If a folder is renamed, recompute pending for all descendants (keep existing behavior)
    try {
      if ($Row.PSObject.Properties.Match('IsFolder').Count -gt 0 -and [bool]$Row.IsFolder) {
        $stack = New-Object System.Collections.Generic.Stack[object]
        $stack.Push($Row.Id)
        while ($stack.Count -gt 0) {
          $pid = $stack.Pop()
          foreach ($child in $script:AllItems) {
            if ($child.ParentId -eq $pid) {
              Set-PendingState -it $child
              if ($child.IsFolder) { $stack.Push($child.Id) }
            }
          }
        }
      }
    } catch {}
    # Push undo op (rename)
    $id = [string]$Row.Id
    $op = [pscustomobject]@{
      Type = "Rename"
      Do = {
        param($rid, $toName)
        $x = Find-ItemById -Id $rid
        if (-not $x) { return }
        if ($x.Action -eq "Delete") { return }
        $x.Name = [string]$toName
        try { Set-PropSafeGlobal -Obj $x -Name 'ViewName' -Value ([string]$toName) } catch {}
        Set-PendingState -it $x -BumpLabels @('Renamed')
      }
      Undo = {
        param($rid, $toName)
        $x = Find-ItemById -Id $rid
        if (-not $x) { return }
        if ($x.Action -eq "Delete") { return }
        $x.Name = [string]$toName
        try { Set-PropSafeGlobal -Obj $x -Name 'ViewName' -Value ([string]$toName) } catch {}
        Set-PendingState -it $x -BumpLabels @('Renamed')
      }
      DoArgs   = @($id, $next)
      UndoArgs = @($id, $prev)
    }
    Push-UndoOp -op $op
    Refresh-UIAsync -Priority ([System.Windows.Threading.DispatcherPriority]::Render)
  } catch {
  }
}

function Invoke-CommitActiveInlineRenameIfNeeded {
  param([string]$Reason = 'InlineEditFocusChange')
  try {
    if ($script:IsUndoRedo) { return $false }
    $tb = $null
    try { $tb = $script:ActiveRenameTextBox } catch { $tb = $null }
    if (-not ($tb -is [System.Windows.Controls.TextBox])) { return $false }
    $rid = ''
    try { $rid = [string]$script:ActiveRenameRowId } catch { $rid = '' }
    if ([string]::IsNullOrWhiteSpace($rid)) {
      try { $rid = [string]$tb._RenRowId } catch { $rid = '' }
    }
    if ([string]::IsNullOrWhiteSpace($rid)) { return $false }
    $row = $null
    try { $row = Find-ItemById -Id $rid } catch { $row = $null }
    if (-not $row) { return $false }
    $next = ''
    try { $next = [string]$tb.Text } catch { $next = '' }
    Invoke-RenameCommit -Row $row -NewName $next -Reason $Reason -TextBox $tb
    return $true
  } catch {
    return $false
  }
}

# --- Capture old name at edit start (this event DOES fire reliably in your logs) ---

$grid.Add_PreparingCellForEdit({
  param($sender, $e)

  if ($e.Column.Header -ne "Name") { return }

  $row = $e.Row.Item
  if (-not $row) { return }
  if ($row.Action -eq "Delete") { return }

  # Remember old *displayed* name for this edit session (StrictMode-safe).
  # The grid displays ViewName (VisualMenu overrides), but the editor template binds to Name.
  # If we don't force the TextBox to start with the displayed name, users see "Accessories"
  # instead of "Windows Accessories" while editing.
  $old = ''
  try { if ($row.PSObject.Properties.Match("ViewName").Count -gt 0) { $old = [string]$row.ViewName } } catch {}
  if ([string]::IsNullOrWhiteSpace($old)) { $old = [string]$row.Name }
  if (-not $row.PSObject.Properties.Match("_EditOldName").Count) {
    $row | Add-Member -NotePropertyName "_EditOldName" -NotePropertyValue $old -Force
  } else {
    $row._EditOldName = $old
  }

  # Find the real TextBox inside the template root
  $tb = $null
  try { $tb = Find-VisualChild -Parent $e.EditingElement -Type ([System.Windows.Controls.TextBox]) } catch {}

  if (-not $tb) {
    return
  }

  # Force the editing UI to match what the user sees in the grid.
  try {
    $tb.Text = $old
    $tb.SelectAll()
  } catch {}

  # Track which row this TextBox is currently editing (virtualization-safe)
  try {
    if (-not $tb.PSObject.Properties.Match('_RenRowId').Count) {
      $tb | Add-Member -NotePropertyName '_RenRowId' -NotePropertyValue ([string]$row.Id) -Force
    } else {
      $tb._RenRowId = [string]$row.Id
    }
  } catch {}

  # Active inline rename context for live mirror with Create/Edit panel.
  try { $script:ActiveRenameTextBox = $tb } catch {}
  try { $script:ActiveRenameRowId = [string]$row.Id } catch {}
  try {
    if ($createNameBox) {
      $script:RenameLiveSyncSuspend = $true
      try { $createNameBox.Text = [string]$tb.Text } finally { $script:RenameLiveSyncSuspend = $false }
    }
  } catch {}

  # Hook once per TextBox instance
  if (-not $tb.PSObject.Properties.Match('_RenHooked').Count) {
    $tb | Add-Member -NotePropertyName "_RenHooked" -NotePropertyValue $true -Force

    # Guard flags to prevent double-commit (Enter -> LostFocus/CommitEdit pipeline)
    if (-not $tb.PSObject.Properties.Match("_RenCommitGate").Count) {
      $tb | Add-Member -NotePropertyName "_RenCommitGate" -NotePropertyValue $false -Force
    }
    if (-not $tb.PSObject.Properties.Match("_RenCommitGateAt").Count) {
      $tb | Add-Member -NotePropertyName "_RenCommitGateAt" -NotePropertyValue ([datetime]::MinValue) -Force
    }
    if (-not $tb.PSObject.Properties.Match("_RenLiveChanged").Count) {
      $tb | Add-Member -NotePropertyName "_RenLiveChanged" -NotePropertyValue $false -Force
    }

    # LostFocus commit (matches UpdateSourceTrigger=LostFocus)
    $tb.Add_LostFocus({
      param($s,$args)
      try {
        # If Enter just committed, LostFocus will follow. Skip it.
        if ($s._RenCommitGate -and (((Get-Date) - $s._RenCommitGateAt).TotalMilliseconds -lt 500)) {
          return
        }

        $rid = $null
        try { $rid = [string]$s._RenRowId } catch {}
        if ([string]::IsNullOrWhiteSpace($rid)) { return }

        $r = Find-ItemById -Id $rid
        if (-not $r) { return }

        Invoke-RenameCommit -Row $r -NewName ([string]$s.Text) -Reason "LostFocus" -TextBox $s
      } catch {}
      finally {
        try {
          $activeTb = $null
          try { $activeTb = $script:ActiveRenameTextBox } catch { $activeTb = $null }
          if ($activeTb -and [object]::ReferenceEquals($activeTb, $s)) {
            $script:ActiveRenameTextBox = $null
            $script:ActiveRenameRowId = ''
          }
        } catch {}
      }
    })

    # Enter commit (instant feedback)
    $tb.Add_PreviewKeyDown({
      param($s,$args)
      try {
        if ($args.Key -eq [System.Windows.Input.Key]::Enter) {
          $args.Handled = $true

          # Gate the follow-up LostFocus/commit churn
          $s._RenCommitGate   = $true
          $s._RenCommitGateAt = Get-Date
          $rid = $null
          try { $rid = [string]$s._RenRowId } catch {}
          if ([string]::IsNullOrWhiteSpace($rid)) {
            try { $s._RenCommitGate = $false } catch {}
            return
          }

          $r = Find-ItemById -Id $rid
          if (-not $r) {
            try { $s._RenCommitGate = $false } catch {}
            return
          }

          Invoke-RenameCommit -Row $r -NewName ([string]$s.Text) -Reason "EnterKey" -TextBox $s

          # End edit mode cleanly
          try { $grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Cell, $true) } catch {}
          try { $grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row,  $true) } catch {}

          # Clear the gate after WPF finishes its focus/commit chain
          try {
            $null = $grid.Dispatcher.BeginInvoke(
              [Action]{
                try { $s._RenCommitGate = $false } catch {}
                try {
                  $activeTb = $null
                  try { $activeTb = $script:ActiveRenameTextBox } catch { $activeTb = $null }
                  if ($activeTb -and [object]::ReferenceEquals($activeTb, $s)) {
                    $script:ActiveRenameTextBox = $null
                    $script:ActiveRenameRowId = ''
                  }
                } catch {}
              },
              [System.Windows.Threading.DispatcherPriority]::Background
            )
          } catch {
            try { $s._RenCommitGate = $false } catch {}
            try {
              $activeTb = $null
              try { $activeTb = $script:ActiveRenameTextBox } catch { $activeTb = $null }
              if ($activeTb -and [object]::ReferenceEquals($activeTb, $s)) {
                $script:ActiveRenameTextBox = $null
                $script:ActiveRenameRowId = ''
              }
            } catch {}
          }
        }
      } catch {}
    })

    # Live mirror: inline grid rename textbox -> Create/Edit name field.
    $tb.Add_TextChanged({
      param($s,$args)
      try {
        if ([bool]$script:RenameLiveSyncSuspend) { return }
        $rid = ''
        try { $rid = [string]$s._RenRowId } catch { $rid = '' }
        if ([string]::IsNullOrWhiteSpace($rid)) { return }

        $script:RenameLiveSyncSuspend = $true
        try {
          if ($createNameBox) {
            $txt = ''
            try { $txt = [string]$s.Text } catch { $txt = '' }
            if ([string]$createNameBox.Text -ne $txt) {
              $createNameBox.Text = $txt
            }
          }
        } finally {
          $script:RenameLiveSyncSuspend = $false
        }

        # Live pending-state preview for inline rename:
        # show "Renamed" as soon as text first differs, and clear when reverted.
        $r = $null
        try { $r = Find-ItemById -Id $rid } catch { $r = $null }
        if ($r) {
          $prev = ''
          try { $prev = [string](Get-PropString -Obj $r -Names @('_EditOldName','Name') -Fallback '') } catch { $prev = '' }
          $nowText = ''
          try { $nowText = [string]$s.Text } catch { $nowText = '' }
          $isChangedNow = (-not [string]::Equals((Trim-NameInputPreserveNbsp -Text $nowText), (Trim-NameInputPreserveNbsp -Text $prev), [System.StringComparison]::Ordinal))

          $wasChanged = $false
          try { $wasChanged = [bool]$s._RenLiveChanged } catch { $wasChanged = $false }

          # Keep model in sync so click-away always retains latest inline text.
          try { $r.Name = $nowText } catch {}
          try { Set-PropSafeGlobal -Obj $r -Name 'ViewName' -Value ([string]$nowText) } catch {}

          if ($isChangedNow) {
            # Only bump once when entering changed-state; otherwise preserve most recent
            # pending-label priority (e.g., Icon Edit applied during rename).
            if (-not $wasChanged) {
              try { Set-PendingState -it $r -BumpLabels @('Renamed') } catch {}
            } else {
              try { Set-PendingState -it $r } catch {}
            }
          } else {
            try { Set-PendingState -it $r } catch {}
          }

          if ($wasChanged -ne $isChangedNow) {
            try { $s._RenLiveChanged = [bool]$isChangedNow } catch {}
            try { Queue-EditPanelPreviewRefresh } catch {}
          }
        }
      } catch {}
    })
  }
})

# --- Safety net: after WPF finishes commit, compare and set pending anyway ---
$grid.Add_CellEditEnding({
  param($sender, $e)

  if ($script:IsUndoRedo) { return }
  if ($e.EditAction -ne [System.Windows.Controls.DataGridEditAction]::Commit) { return }
  if ($e.Column.Header -ne "Name") { return }

  $row = $e.Row.Item
  if (-not $row) { return }
  if ($row.Action -eq "Delete") { return }

  try {
    $activeRid = ''
    try { $activeRid = [string]$script:ActiveRenameRowId } catch { $activeRid = '' }
    if (-not [string]::IsNullOrWhiteSpace($activeRid) -and $activeRid -eq [string]$row.Id) {
      $script:ActiveRenameTextBox = $null
      $script:ActiveRenameRowId = ''
    }
  } catch {}

  $prev = if ($row.PSObject.Properties.Match('_EditOldName').Count -gt 0) { [string]$row._EditOldName } else { [string]$row.Name }

  $null = $grid.Dispatcher.BeginInvoke(
    [Action]{
      try {
        $now = (Trim-NameInputPreserveNbsp -Text ([string]$row.Name))
        if ($now -ne $prev) {
          Invoke-RenameCommit -Row $row -NewName $now -Reason "CellEditEnding(ContextIdle)"
        } else {
        }
      } catch {}
    },
    [System.Windows.Threading.DispatcherPriority]::ContextIdle
  )
})

# Select all / deselect all in CURRENT VIEW
# ==============================================================================
$selectAll.Add_Click({
  if (-not $script:CurrentView) { return }
  $val = [bool]$selectAll.IsChecked
  foreach ($o in $script:CurrentView) {
    if (-not $o) { continue }
    if (Test-IsAlphaSeparatorRow -Row $o) { continue }
    $isWinSec = $false
    try { $isWinSec = ($o.PSObject.Properties.Match('IsWindowsSecurityProxy').Count -gt 0 -and [bool]$o.IsWindowsSecurityProxy) } catch {}
    $isSettings = $false
    try { $isSettings = ($o.PSObject.Properties.Match('IsSettingsProxy').Count -gt 0 -and [bool]$o.IsSettingsProxy) } catch {}
    if (-not $isSettings) {
      try { $isSettings = (Test-IsSettingsAppsFolderRow -Row $o) } catch {}
    }
    if ($isWinSec -or $isSettings) { continue }
    try { $o.Selected = $val } catch {}
  }
  Refresh-UIAsync
  try { Update-RenameButtonState } catch {}
  try { Sync-CreateEditSelectedFields } catch {}
})

function Test-IsIconChangeEligibleRow {
  param([object]$Row)
  if (-not $Row) { return $false }
  try { if (Test-IsAlphaSeparatorRow -Row $Row) { return $false } } catch {}
  $rowKind = ''
  try { $rowKind = [string](Get-PropString -Obj $Row -Names @('RowKind') -Fallback '') } catch { $rowKind = '' }
  if ($rowKind -eq 'Folder') { return $false }
  $act = ''
  try { $act = [string](Get-PropString -Obj $Row -Names @('Action') -Fallback '') } catch { $act = '' }
  if ($act -eq 'Delete') { return $false }
  $isPendingCreate = $false
  try { $isPendingCreate = ($Row.PSObject.Properties.Match('IsPendingCreate').Count -gt 0 -and [bool]$Row.IsPendingCreate) } catch {}
  if ($isPendingCreate) {
    $ck = ''
    try { $ck = [string](Get-PropString -Obj $Row -Names @('CreateKind') -Fallback '') } catch { $ck = '' }
    if ($ck -eq 'Shortcut') { return $true }
    return $false
  }
  $lnk = Resolve-ExistingShortcutPathForRow -Row $Row
  return (-not [string]::IsNullOrWhiteSpace($lnk))
}

function Get-IconChangeSelectionRows {
  $byId = @{}
  foreach ($r in @($script:CurrentView)) {
    if (-not $r) { continue }
    $sel = $false
    try { $sel = [bool]$r.Selected } catch { $sel = $false }
    if (-not $sel) { continue }
    if (-not (Test-IsIconChangeEligibleRow -Row $r)) { continue }
    $rid = ''
    try { $rid = [string](Get-PropString -Obj $r -Names @('Id') -Fallback '') } catch { $rid = '' }
    if ([string]::IsNullOrWhiteSpace($rid)) { continue }
    if (-not $byId.ContainsKey($rid)) { $byId[$rid] = $r }
  }
  if ($byId.Count -eq 0) {
    $r0 = $null
    try { $r0 = $grid.SelectedItem } catch { $r0 = $null }
    if ($r0 -and (Test-IsIconChangeEligibleRow -Row $r0)) {
      $rid0 = ''
      try { $rid0 = [string](Get-PropString -Obj $r0 -Names @('Id') -Fallback '') } catch { $rid0 = '' }
      if (-not [string]::IsNullOrWhiteSpace($rid0)) { $byId[$rid0] = $r0 }
    }
  }
  return @($byId.Values)
}

function New-IconChangeSnapshotFromRows {
  param([object[]]$Rows)
  $snap = New-Object System.Collections.Generic.List[object]
  foreach ($r in @($Rows)) {
    if (-not $r) { continue }
    [void]$snap.Add([pscustomobject]@{
      Id                   = [string](Get-PropString -Obj $r -Names @('Id') -Fallback '')
      Scope                = [string](Get-PropString -Obj $r -Names @('Scope') -Fallback '')
      Path                 = [string](Get-PropString -Obj $r -Names @('Path') -Fallback '')
      OriginalPath         = [string](Get-PropString -Obj $r -Names @('OriginalPath') -Fallback '')
      SourceRow            = $r
      PrevPendingIconPath  = [string](Get-PropString -Obj $r -Names @('PendingIconPath') -Fallback '')
      PrevPendingIconIndex = [int](Get-PropString -Obj $r -Names @('PendingIconIndex') -Fallback '0')
      PrevSelected         = $(try { [bool]$r.Selected } catch { $false })
      PrevIcon             = $(try { $r.Icon } catch { $null })
    })
  }
  return @($snap.ToArray())
}

function New-PendingCreateIconSnapshotFromRows {
  param([object[]]$Rows)
  $snap = New-Object System.Collections.Generic.List[object]
  foreach ($r in @($Rows)) {
    if (-not $r) { continue }
    $isPendingCreate = $false
    try { $isPendingCreate = ($r.PSObject.Properties.Match('IsPendingCreate').Count -gt 0 -and [bool]$r.IsPendingCreate) } catch { $isPendingCreate = $false }
    if (-not $isPendingCreate) { continue }
    $ck = ''
    try { $ck = [string](Get-PropString -Obj $r -Names @('CreateKind') -Fallback '') } catch { $ck = '' }
    if ($ck -ne 'Shortcut') { continue }
    [void]$snap.Add([pscustomobject]@{
      Id                  = [string](Get-PropString -Obj $r -Names @('Id') -Fallback '')
      SourceRow           = $r
      PrevCreateIconPath  = [string](Get-PropString -Obj $r -Names @('CreateIconPath') -Fallback '')
      PrevCreateIconIndex = [int](Get-PropString -Obj $r -Names @('CreateIconIndex') -Fallback '0')
      PrevIcon            = $(try { $r.Icon } catch { $null })
    })
  }
  return @($snap.ToArray())
}

function Apply-PendingCreateIconSnapshot {
  param(
    [Parameter(Mandatory=$true)][object[]]$Snapshot,
    [ValidateSet('Do','Undo')][string]$Direction = 'Do',
    [string]$IconPath = '',
    [int]$IconIndex = 0
  )
  $preview = $null
  if ($Direction -eq 'Do') {
    try { $preview = Get-ImageSourceFromIcon -IconPath $IconPath -IconIndex $IconIndex -FallbackExePath $IconPath } catch { $preview = $null }
  }
  foreach ($s in @($Snapshot)) {
    if (-not $s) { continue }
    $r = $null
    try {
      if ($s.PSObject.Properties.Match('SourceRow').Count -gt 0) {
        $r = $s.SourceRow
      }
    } catch {}
    if (-not $r) {
      $sid = ''
      try { $sid = [string](Get-PropString -Obj $s -Names @('Id') -Fallback '') } catch { $sid = '' }
      if (-not [string]::IsNullOrWhiteSpace($sid)) {
        try { $r = Find-ItemById -Id $sid } catch { $r = $null }
        if (-not $r) {
          foreach ($pr in @(Get-PendingCreateRows)) {
            if (-not $pr) { continue }
            $rid = ''
            try { $rid = [string](Get-PropString -Obj $pr -Names @('Id') -Fallback '') } catch { $rid = '' }
            if ($rid -eq $sid) { $r = $pr; break }
          }
        }
      }
    }
    if (-not $r) { continue }
    if ($Direction -eq 'Do') {
      try { Set-PropSafeGlobal -Obj $r -Name 'CreateIconPath' -Value ([string]$IconPath) } catch {}
      try { Set-PropSafeGlobal -Obj $r -Name 'CreateIconIndex' -Value ([int]$IconIndex) } catch {}
      if ($preview) {
        try { Set-PropSafeGlobal -Obj $r -Name 'Icon' -Value $preview } catch {}
      }
    } else {
      try { Set-PropSafeGlobal -Obj $r -Name 'CreateIconPath' -Value ([string](Get-PropString -Obj $s -Names @('PrevCreateIconPath') -Fallback '')) } catch {}
      try { Set-PropSafeGlobal -Obj $r -Name 'CreateIconIndex' -Value ([int](Get-PropString -Obj $s -Names @('PrevCreateIconIndex') -Fallback '0')) } catch {}
      try {
        if ($s.PSObject.Properties.Match('PrevIcon').Count -gt 0) {
          Set-PropSafeGlobal -Obj $r -Name 'Icon' -Value $s.PrevIcon
        }
      } catch {}
    }
  }
  try { Touch-VisualRuntimeState -Reason ("ChangeIconPendingCreate." + $Direction) } catch {}
  try { Refresh-UIAsync } catch {}
  try { Update-RenameButtonState } catch {}
}

function Clear-ChangeIconPanelMode {
  try { $script:ChangeIconPanelModeActive = $false } catch {}
  try { $script:ChangeIconPanelSnapshot = @() } catch {}
  try {
    if ([string]$script:CreatePanelMode -eq 'EditSelected') {
      Set-CreateModeUi -Mode 'Shortcut'
    }
  } catch {}
}

function Enter-ChangeIconPanelMode {
  param([Parameter(Mandatory=$true)][object[]]$Rows)
  $snapArr = @(New-IconChangeSnapshotFromRows -Rows $Rows)
  if ($snapArr.Count -eq 0) { return $false }
  $seedPath = ''
  $seedIndex = 0
  try {
    $first = $Rows[0]
    if ($first -and (Test-RowHasPendingIconChange -Row $first)) {
      $seedPath = Normalize-Path ([string](Get-PropString -Obj $first -Names @('PendingIconPath') -Fallback ''))
      try { $seedIndex = [int](Get-PropString -Obj $first -Names @('PendingIconIndex') -Fallback '0') } catch { $seedIndex = 0 }
    }
    if ([string]::IsNullOrWhiteSpace($seedPath) -and $first) {
      $isPendingCreateFirst = $false
      try { $isPendingCreateFirst = ($first.PSObject.Properties.Match('IsPendingCreate').Count -gt 0 -and [bool]$first.IsPendingCreate) } catch { $isPendingCreateFirst = $false }
      if ($isPendingCreateFirst) {
        $seedPath = Normalize-Path ([string](Get-PropString -Obj $first -Names @('CreateIconPath') -Fallback ''))
        try { $seedIndex = [int](Get-PropString -Obj $first -Names @('CreateIconIndex') -Fallback '0') } catch { $seedIndex = 0 }
        if ([string]::IsNullOrWhiteSpace($seedPath)) {
          $seedPath = Normalize-Path ([string](Get-PropString -Obj $first -Names @('Target','CreateTargetPath') -Fallback ''))
          $seedIndex = 0
        }
      }
    }
    if ([string]::IsNullOrWhiteSpace($seedPath) -and $first) {
      $lnk = Resolve-ExistingShortcutPathForRow -Row $first
      if (-not [string]::IsNullOrWhiteSpace($lnk)) {
        $spec = Get-ShortcutIconLocationSpecFromLink -LnkPath $lnk
        if ($spec) {
          $seedPath = [string]$spec.IconPath
          $seedIndex = [int]$spec.IconIndex
        }
      }
    }
  } catch {}
  $seedImg = $null
  if (-not [string]::IsNullOrWhiteSpace($seedPath)) {
    try { $seedImg = Get-ImageSourceFromIcon -IconPath $seedPath -IconIndex $seedIndex -FallbackExePath $seedPath } catch { $seedImg = $null }
  }
  try {
    $seedLabel = if (-not [string]::IsNullOrWhiteSpace($seedPath)) { ([System.IO.Path]::GetFileName([string]$seedPath) + ',' + [string]$seedIndex) } else { '(pick icon)' }
    Set-CreateSelectedIcon -IconPath $seedPath -IconIndex $seedIndex -Image $seedImg -Label $seedLabel
  } catch {}
  try { $script:ChangeIconPanelSnapshot = $snapArr } catch {}
  try { $script:ChangeIconPanelModeActive = $true } catch {}
  try { Set-CreateModeUi -Mode 'EditSelected' } catch {}
  try { if ($rightPanelTabs -and $createTab) { $rightPanelTabs.SelectedItem = $createTab } } catch {}
  try { if ($createIconTabs) { $createIconTabs.SelectedIndex = 0 } } catch {}
  try { Refresh-CreateSystemIconList } catch {}
  try {
    if ($createSystemIconSummaryText) {
      $createSystemIconSummaryText.Text = ("Selected icon will apply to {0} selected item(s)." -f $snapArr.Count)
    }
  } catch {}
  try { Sync-CreateEditSelectedFields } catch {}
  return $true
}

function Invoke-ApplyIconChangeFromPanel {
  param(
    [Parameter(Mandatory=$true)][string]$IconPath,
    [int]$IconIndex = 0,
    [object]$IconImage = $null
  )
  if (-not $script:ChangeIconPanelModeActive) { return $false }
  $rows = @()
  try { $rows = @(Get-IconChangeSelectionRows) } catch { $rows = @() }
  if (@($rows).Count -eq 0) {
    [System.Windows.MessageBox]::Show("Select one or more shortcut rows first.", "Edit Selected") | Out-Null
    try { Sync-CreateEditSelectedFields } catch {}
    return $false
  }
  $preview = $IconImage
  if (-not $preview) {
    try { $preview = Get-ImageSourceFromIcon -IconPath ([string]$IconPath) -IconIndex ([int]$IconIndex) -FallbackExePath ([string]$IconPath) } catch { $preview = $null }
  }
  if (-not $preview) {
    [System.Windows.MessageBox]::Show("Unable to load the selected icon.", "Change Icon") | Out-Null
    return $false
  }
  $pendingCreateRows = New-Object System.Collections.Generic.List[object]
  $regularRows = New-Object System.Collections.Generic.List[object]
  foreach ($r in @($rows)) {
    if (-not $r) { continue }
    $isPendingCreate = $false
    try { $isPendingCreate = ($r.PSObject.Properties.Match('IsPendingCreate').Count -gt 0 -and [bool]$r.IsPendingCreate) } catch { $isPendingCreate = $false }
    if ($isPendingCreate) {
      $ck = ''
      try { $ck = [string](Get-PropString -Obj $r -Names @('CreateKind') -Fallback '') } catch { $ck = '' }
      if ($ck -eq 'Shortcut') {
        [void]$pendingCreateRows.Add($r)
        continue
      }
    }
    [void]$regularRows.Add($r)
  }
  $regularSnap = @(New-IconChangeSnapshotFromRows -Rows @($regularRows.ToArray()))
  $pendingCreateSnap = @(New-PendingCreateIconSnapshotFromRows -Rows @($pendingCreateRows.ToArray()))
  if (@($regularSnap).Count -le 0 -and @($pendingCreateSnap).Count -le 0) {
    [System.Windows.MessageBox]::Show("Select one or more shortcut rows first.", "Edit Selected") | Out-Null
    try { Sync-CreateEditSelectedFields } catch {}
    return $false
  }
  try { $script:ChangeIconPanelSnapshot = @($regularSnap) } catch {}
  $ctxDo = [pscustomobject]@{
    RegularSnapshot      = @($regularSnap)
    PendingCreateSnapshot= @($pendingCreateSnap)
    IconPath             = [string]$IconPath
    IconIndex            = [int]$IconIndex
  }
  $ctxUndo = [pscustomobject]@{
    RegularSnapshot      = @($regularSnap)
    PendingCreateSnapshot= @($pendingCreateSnap)
  }
  $op = [pscustomobject]@{
    Type = "ChangeIcon"
    Do = {
      param($ctx)
      if (-not $ctx) { return }
      if (@($ctx.RegularSnapshot).Count -gt 0) {
        Apply-PendingIconChangeSnapshot -Snapshot @($ctx.RegularSnapshot) -Direction Do -IconPath ([string]$ctx.IconPath) -IconIndex ([int]$ctx.IconIndex)
      }
      if (@($ctx.PendingCreateSnapshot).Count -gt 0) {
        Apply-PendingCreateIconSnapshot -Snapshot @($ctx.PendingCreateSnapshot) -Direction Do -IconPath ([string]$ctx.IconPath) -IconIndex ([int]$ctx.IconIndex)
      }
    }
    Undo = {
      param($ctx)
      if (-not $ctx) { return }
      if (@($ctx.RegularSnapshot).Count -gt 0) {
        Apply-PendingIconChangeSnapshot -Snapshot @($ctx.RegularSnapshot) -Direction Undo
      }
      if (@($ctx.PendingCreateSnapshot).Count -gt 0) {
        Apply-PendingCreateIconSnapshot -Snapshot @($ctx.PendingCreateSnapshot) -Direction Undo
      }
    }
    DoArgs   = $ctxDo
    UndoArgs = $ctxUndo
  }
  & $op.Do $op.DoArgs
  Push-UndoOp -op $op
  # Keep icon-edit mode active so create controls stay hidden until user exits explicitly.
  try { Update-CreatePanelContext } catch {}
  try { Sync-CreateEditSelectedFields } catch {}
  try {
    if ($createSystemIconSummaryText) {
      $createSystemIconSummaryText.Text = ("Icon applied to {0} selected item(s)." -f (@($regularSnap).Count + @($pendingCreateSnap).Count))
    }
  } catch {}
  return $true
}

function Try-UpdateActiveInlineRenameIconVisual {
  param(
    [Parameter(Mandatory=$true)][object]$Row,
    [object]$IconImage = $null
  )
  try {
    if (-not $Row) { return $false }
    if (-not $IconImage) { return $false }
    $tb = $null
    try { $tb = $script:ActiveRenameTextBox } catch { $tb = $null }
    if (-not ($tb -is [System.Windows.Controls.TextBox])) { return $false }
    $tbRid = ''
    try { $tbRid = [string]$tb._RenRowId } catch { $tbRid = '' }
    $rowRid = ''
    try { $rowRid = [string](Get-PropString -Obj $Row -Names @('Id') -Fallback '') } catch { $rowRid = '' }
    if ([string]::IsNullOrWhiteSpace($tbRid) -or [string]::IsNullOrWhiteSpace($rowRid) -or $tbRid -ne $rowRid) { return $false }
    $tbDep = $tb -as [System.Windows.DependencyObject]
    if (-not $tbDep) { return $false }
    $cell = Find-VisualAncestor -Start $tbDep -Type ([System.Windows.Controls.DataGridCell])
    if (-not $cell) { return $false }
    $img = Find-VisualChild -Parent $cell -Type ([System.Windows.Controls.Image])
    if (-not $img) { return $false }
    try { $img.Source = $IconImage } catch {}
    return $true
  } catch {
    return $false
  }
}

function Apply-PendingIconChangeSnapshot {
  param(
    [Parameter(Mandatory=$true)][object[]]$Snapshot,
    [ValidateSet('Do','Undo')][string]$Direction = 'Do',
    [string]$IconPath = '',
    [int]$IconIndex = 0
  )
  $preview = $null
  if ($Direction -eq 'Do') {
    try {
      $preview = Get-ImageSourceFromIcon -IconPath $IconPath -IconIndex $IconIndex -FallbackExePath $IconPath
    } catch { $preview = $null }
  }
  function _AddTargetRow {
    param([System.Collections.Generic.List[object]]$List, [hashtable]$Seen, [object]$Row)
    if (-not $Row) { return }
    $k = ''
    try { $k = [string](Get-PropString -Obj $Row -Names @('Id') -Fallback '') } catch { $k = '' }
    if ([string]::IsNullOrWhiteSpace($k)) {
      $sc = ''; $pp = ''
      try { $sc = [string](Get-PropString -Obj $Row -Names @('Scope') -Fallback '') } catch { $sc = '' }
      try { $pp = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback '')) } catch { $pp = '' }
      if (-not [string]::IsNullOrWhiteSpace($sc) -and -not [string]::IsNullOrWhiteSpace($pp)) {
        $k = ($sc.Trim().ToLowerInvariant() + '|' + $pp.TrimEnd('\').ToLowerInvariant())
      } else {
        try { $k = ("obj|" + [string]$Row.GetHashCode()) } catch { $k = ("obj|" + [guid]::NewGuid().ToString()) }
      }
    }
    $kk = $k.Trim().ToLowerInvariant()
    if ($Seen.ContainsKey($kk)) { return }
    $Seen[$kk] = $true
    [void]$List.Add($Row)
  }
  function _FindRowByScopePath {
    param([string]$Scope, [string]$PathA, [string]$PathB)
    if ([string]::IsNullOrWhiteSpace($Scope)) { return $null }
    $pa = Normalize-Path $PathA
    $pb = Normalize-Path $PathB
    foreach ($tr in @($script:TreeRoots)) {
      if (-not $tr) { continue }
      $stack = New-Object System.Collections.Generic.Stack[FolderNode]
      $stack.Push($tr)
      while ($stack.Count -gt 0) {
        $n = $stack.Pop()
        foreach ($it in @($n.Items)) {
          if (-not $it) { continue }
          $sc = [string](Get-PropString -Obj $it -Names @('Scope') -Fallback '')
          if ($sc -ne $Scope) { continue }
          $p1 = Normalize-Path ([string](Get-PropString -Obj $it -Names @('Path') -Fallback ''))
          $p2 = Normalize-Path ([string](Get-PropString -Obj $it -Names @('OriginalPath') -Fallback ''))
          if ((-not [string]::IsNullOrWhiteSpace($pa) -and ((Test-PathEqualsCI -A $p1 -B $pa) -or (Test-PathEqualsCI -A $p2 -B $pa))) -or
              (-not [string]::IsNullOrWhiteSpace($pb) -and ((Test-PathEqualsCI -A $p1 -B $pb) -or (Test-PathEqualsCI -A $p2 -B $pb)))) {
            return $it
          }
        }
        foreach ($ch in @($n.Children)) { if ($ch) { $stack.Push($ch) } }
      }
    }
    return $null
  }
  foreach ($s in @($Snapshot)) {
    if (-not $s) { continue }
    $targetRows = New-Object System.Collections.Generic.List[object]
    $seenTargets = @{}
    # 1) Row object captured at click time.
    try {
      if ($s.PSObject.Properties.Match('SourceRow').Count -gt 0) {
        _AddTargetRow -List $targetRows -Seen $seenTargets -Row $s.SourceRow
      }
    } catch {}
    # 2) Resolve by Id.
    $sid = ''
    try { $sid = [string](Get-PropString -Obj $s -Names @('Id') -Fallback '') } catch { $sid = '' }
    if (-not [string]::IsNullOrWhiteSpace($sid)) {
      $rById = $null
      try { $rById = Find-ItemById -Id $sid } catch { $rById = $null }
      if ($rById) { _AddTargetRow -List $targetRows -Seen $seenTargets -Row $rById }
    }
    # 3) Resolve by Scope + Path/OriginalPath as a fallback for Visual merged rows.
    $ssc = ''; $sp = ''; $sop = ''
    try { $ssc = [string](Get-PropString -Obj $s -Names @('Scope') -Fallback '') } catch { $ssc = '' }
    try { $sp = [string](Get-PropString -Obj $s -Names @('Path') -Fallback '') } catch { $sp = '' }
    try { $sop = [string](Get-PropString -Obj $s -Names @('OriginalPath') -Fallback '') } catch { $sop = '' }
    if (-not [string]::IsNullOrWhiteSpace($ssc)) {
      $rByPath = _FindRowByScopePath -Scope $ssc -PathA $sp -PathB $sop
      if ($rByPath) { _AddTargetRow -List $targetRows -Seen $seenTargets -Row $rByPath }
    }
    if ($targetRows.Count -eq 0) { continue }
    foreach ($r in @($targetRows.ToArray())) {
      if (-not $r) { continue }
      if ($Direction -eq 'Do') {
        try { Set-PropSafeGlobal -Obj $r -Name 'PendingIconPath' -Value ([string]$IconPath) } catch {}
        try { Set-PropSafeGlobal -Obj $r -Name 'PendingIconIndex' -Value ([int]$IconIndex) } catch {}
        if ($preview) {
          try { Set-PropSafeGlobal -Obj $r -Name 'Icon' -Value $preview } catch {}
          try { [void](Try-UpdateActiveInlineRenameIconVisual -Row $r -IconImage $preview) } catch {}
        }
      } else {
        try { Set-PropSafeGlobal -Obj $r -Name 'PendingIconPath' -Value ([string](Get-PropString -Obj $s -Names @('PrevPendingIconPath') -Fallback '')) } catch {}
        try { Set-PropSafeGlobal -Obj $r -Name 'PendingIconIndex' -Value ([int](Get-PropString -Obj $s -Names @('PrevPendingIconIndex') -Fallback '0')) } catch {}
        try {
          if ($s.PSObject.Properties.Match('PrevIcon').Count -gt 0) {
            Set-PropSafeGlobal -Obj $r -Name 'Icon' -Value $s.PrevIcon
            try { [void](Try-UpdateActiveInlineRenameIconVisual -Row $r -IconImage $s.PrevIcon) } catch {}
          }
        } catch {}
      }
      if ($Direction -eq 'Do') {
        try { Set-PendingState -it $r -BumpLabels @('Icon Edit') } catch {}
      } else {
        try { Set-PendingState -it $r } catch {}
      }
    }
  }
  try { Touch-VisualRuntimeState -Reason ("ChangeIcon." + $Direction) } catch {}
  # Do not rebuild here; rebuild can drop transient visual pending-state before Apply detects it.
  # We only refresh bindings and keep pending on the touched rows.
  try { Refresh-UIAsync } catch {}
  try { Update-RenameButtonState } catch {}
}

# ==============================================================================
# Undo / Redo / Reset
# ==============================================================================
function Invoke-UndoUiAction {
  $script:IsUndoRedo = $true
  try {
    End-GridEditTransaction
    Undo
    try { Touch-VisualRuntimeState -Reason "Undo" } catch {}
    Refresh-UI
    try { Clear-EditPanelNamePreview } catch {}
    try { Sync-CreateEditSelectedFields } catch {}
  } finally {
    $script:IsUndoRedo = $false
  }
}

function Invoke-RedoUiAction {
  $script:IsUndoRedo = $true
  try {
    End-GridEditTransaction
    Redo
    try { Touch-VisualRuntimeState -Reason "Redo" } catch {}
    Refresh-UI
    try { Clear-EditPanelNamePreview } catch {}
    try { Sync-CreateEditSelectedFields } catch {}
  } finally {
    $script:IsUndoRedo = $false
  }
}

$undoBtn.Add_Click({ Invoke-UndoUiAction })
$redoBtn.Add_Click({ Invoke-RedoUiAction })

function Invoke-UndoViaButtonClick {
  try {
    if ($undoBtn) {
      $undoBtn.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
      return
    }
  } catch {}
  Invoke-UndoUiAction
}

function Invoke-RedoViaButtonClick {
  try {
    if ($redoBtn) {
      $redoBtn.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
      return
    }
  } catch {}
  Invoke-RedoUiAction
}

$resetBtn.Add_Click({
  End-GridEditTransaction

  $pending = $null
  $pendingCreateRows = @()
  try { $pending = Get-PendingChanges } catch { $pending = $null }
  try { $pendingCreateRows = @(Get-PendingCreateRows) } catch { $pendingCreateRows = @() }
  $hasPending = $false
  try {
    if (@($pendingCreateRows).Count -gt 0) { $hasPending = $true }
    elseif ($pending) {
      if (@($pending.Renames).Count -gt 0) { $hasPending = $true }
      elseif (@($pending.Deletes).Count -gt 0) { $hasPending = $true }
      elseif (@($pending.IconChanges).Count -gt 0) { $hasPending = $true }
      elseif (@($pending.TargetChanges).Count -gt 0) { $hasPending = $true }
    }
  } catch { $hasPending = $false }
  if (-not $hasPending) {
    [System.Windows.MessageBox]::Show("No pending actions to clear.", "Clear Pending States") | Out-Null
    return
  }

  $res = [System.Windows.MessageBox]::Show(
    "Discard all pending changes?",
    "Clear Pending States",
    "YesNo",
    "Warning"
  )
  if ($res -ne "Yes") { return }

  Invoke-WithBusyOverlay -Action {
    # Reset discards mock changes; reflect current filesystem state instead of reusing a possibly-mutated startup snapshot.
    $script:StartupInventory = @(Get-Inventory)
    try { Invalidate-LaunchDuplicateCaches } catch {}
    $model = Build-Model -inventoryItems $script:StartupInventory
    $script:TreeRoots = $model.TreeRoots
    $script:NodeMap   = $model.NodeMap
    $tree.ItemsSource = $null
    $tree.ItemsSource = $script:TreeRoots
    $script:UndoStack.Clear()
    $script:RedoStack.Clear()
    $grid.ItemsSource = $null
    $script:CurrentNode = $null
    $script:CurrentView = $null
    Clear-VisualProxyCaches
    try { if ($script:PendingCreateRows) { $script:PendingCreateRows.Clear() } } catch {}
    Select-DefaultStartNode
  }
})

# ==============================================================================
# Mock Delete
# ==============================================================================
function Get-DescendantItemsForFolderRow {
  param(
    [Parameter(Mandatory=$true)][object]$FolderRow
  )
  $results = New-Object System.Collections.Generic.List[object]
  # Must be a folder row with Scope+Path
  $isFolder = $false
  try { $isFolder = ($FolderRow.PSObject.Properties.Match('RowKind').Count -gt 0 -and $FolderRow.RowKind -eq 'Folder') } catch {}
  if (-not $isFolder) { return @() }
  function _walkNode {
    param([FolderNode]$n)
    if (-not $n) { return }
    # items directly in this folder
    if ($n.PSObject.Properties.Match('Items').Count -gt 0 -and $n.Items) {
      foreach ($it in $n.Items) {
        if ($it) { $results.Add($it) }
      }
    }
    # recurse into children
    if ($n.PSObject.Properties.Match('Children').Count -gt 0 -and $n.Children) {
      foreach ($ch in $n.Children) {
        _walkNode -n $ch
      }
    }
  }
  $handledVisualSources = $false
  try {
    if ($FolderRow.PSObject.Properties.Match('VisualSources').Count -gt 0 -and @($FolderRow.VisualSources).Count -gt 0) {
      $handledVisualSources = $true
      foreach ($src in @($FolderRow.VisualSources)) {
        if (-not $src) { continue }
        $sc = [string](Get-PropString -Obj $src -Names @('Scope') -Fallback '')
        $fp = [string](Get-PropString -Obj $src -Names @('FullPath','Path') -Fallback '')
        if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($fp)) { continue }
        $n = Get-NodeByScopePath -Scope $sc -FullPath $fp
        if ($n) { _walkNode -n $n }
      }
    }
  } catch {}
  if (-not $handledVisualSources) {
    $hasScope = $false; $hasPath = $false
    try { $hasScope = ($FolderRow.PSObject.Properties.Match('Scope').Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$FolderRow.Scope)) } catch {}
    try { $hasPath  = ($FolderRow.PSObject.Properties.Match('Path').Count  -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$FolderRow.Path)) } catch {}
    if (-not ($hasScope -and $hasPath)) { return @() }
    $node = Get-NodeByScopePath -Scope ([string]$FolderRow.Scope) -FullPath ([string]$FolderRow.Path)
    if (-not $node) { return @() }
    _walkNode -n $node
  }
  $byId = @{}
  foreach ($it in $results) {
    if (-not $it) { continue }
    $id = ''
    try { $id = [string]$it.Id } catch {}
    if ([string]::IsNullOrWhiteSpace($id)) { continue }
    if (-not $byId.ContainsKey($id)) { $byId[$id] = $it }
  }
  return $byId.Values
}
function Get-DescendantFolderRowsForFolderRow {
  param([Parameter(Mandatory=$true)][object]$FolderRow)
  # Must be folder row with Scope+Path
  $isFolder = $false
  try { $isFolder = ($FolderRow.PSObject.Properties.Match('RowKind').Count -gt 0 -and $FolderRow.RowKind -eq 'Folder') } catch {}
  if (-not $isFolder) { return @() }
  $results = New-Object System.Collections.Generic.List[object]
  function _walkFolders {
    param([FolderNode]$n)
    if (-not $n) { return }
    # Add this node's immediate folder rows (child folders)
    if ($n.PSObject.Properties.Match('Folders').Count -gt 0 -and $n.Folders) {
      foreach ($fr in $n.Folders) {
        if ($fr) { $results.Add($fr) }
      }
    }
    # Recurse into child nodes
    if ($n.PSObject.Properties.Match('Children').Count -gt 0 -and $n.Children) {
      foreach ($ch in $n.Children) {
        _walkFolders -n $ch
      }
    }
  }
  $handledVisualSources = $false
  try {
    if ($FolderRow.PSObject.Properties.Match('VisualSources').Count -gt 0 -and @($FolderRow.VisualSources).Count -gt 0) {
      $handledVisualSources = $true
      foreach ($src in @($FolderRow.VisualSources)) {
        if (-not $src) { continue }
        $sc = [string](Get-PropString -Obj $src -Names @('Scope') -Fallback '')
        $fp = [string](Get-PropString -Obj $src -Names @('FullPath','Path') -Fallback '')
        if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($fp)) { continue }
        $n = Get-NodeByScopePath -Scope $sc -FullPath $fp
        if ($n) { _walkFolders -n $n }
      }
    }
  } catch {}
  if (-not $handledVisualSources) {
    $scope = $null
    $path  = $null
    try { $scope = [string]$FolderRow.Scope } catch {}
    try { $path  = [string]$FolderRow.Path  } catch {}
    if ([string]::IsNullOrWhiteSpace($scope) -or [string]::IsNullOrWhiteSpace($path)) { return @() }
    $rootNode = Get-NodeByScopePath -Scope $scope -FullPath $path
    if (-not $rootNode) { return @() }
    _walkFolders -n $rootNode
  }
  # Return unique by Id (folder rows have Id)
  $byId = @{}
  foreach ($x in $results) {
    $id = $null
    try { $id = [string]$x.Id } catch {}
    if ([string]::IsNullOrWhiteSpace($id)) { continue }
    if (-not $byId.ContainsKey($id)) { $byId[$id] = $x }
  }
  # Avoid @($dict.Values) which can throw in Windows PowerShell 5.1 for some collection types.
  return $byId.Values
}

function Set-RowMockDeleteState {
  param(
    [Parameter(Mandatory=$true)][object]$Row,
    [Parameter(Mandatory=$true)][bool]$IsDelete
  )
  if (-not $Row) { return }
  # You likely already use Action = "Delete" to represent mock delete
  if ($Row.PSObject.Properties.Match('Action').Count -eq 0) {
    $Row | Add-Member -NotePropertyName Action -NotePropertyValue "" -Force
  }
  if ($IsDelete) {
    $isFolder = $false
    try { $isFolder = ($Row.PSObject.Properties.Match('RowKind').Count -gt 0 -and [string]$Row.RowKind -eq 'Folder') } catch { $isFolder = $false }
    if ($isFolder) {
      $isStartupFolder = $false
      try { $isStartupFolder = (Test-IsStartupFolderRow -Row $Row) } catch { $isStartupFolder = $false }
      if ($isStartupFolder) {
        if ($Row.Action -eq "Delete") { $Row.Action = "None" }
        try { Set-PendingState -it $Row } catch {}
        return
      }
    }
  }
  if ($IsDelete) {
    $Row.Action = "Delete"
} else {
  # revert to canonical state
  if ($Row.Action -eq "Delete") { $Row.Action = "None" }
}
  if ($IsDelete) {
    try { Set-PendingState -it $Row -BumpLabels @('Deleted') } catch {}
  } else {
    try { Set-PendingState -it $Row } catch {}
  }
}

function Apply-MockDeleteCascade {
  param(
    [Parameter(Mandatory=$true)][object]$Row,
    [Parameter(Mandatory=$true)][bool]$IsDelete
  )
  if (-not $Row) { return }
  # If folder: don't mark the folder row itself as deleted (UI-only),
# only cascade to descendant items
$isFolder = $false
try { $isFolder = ($Row.PSObject.Properties.Match('RowKind').Count -gt 0 -and $Row.RowKind -eq 'Folder') } catch {}
if (-not $isFolder) {
  Set-RowMockDeleteState -Row $Row -IsDelete $IsDelete
}
  # If folder: cascade to ALL descendant items
  $isFolder = $false
  try { $isFolder = ($Row.PSObject.Properties.Match('RowKind').Count -gt 0 -and $Row.RowKind -eq 'Folder') } catch {}
  if ($isFolder) {
    $descItems = Get-DescendantItemsForFolderRow -FolderRow $Row
    foreach ($it in $descItems) {
      Set-RowMockDeleteState -Row $it -IsDelete $IsDelete
    }
  }
  # Refresh UI (you can pick one)
  try { Refresh-UIAsync } catch {}
  try { Queue-RebuildVisibleRows } catch {}
}

$mockDeleteBtn.Add_Click({
  End-GridEditTransaction
  if (-not $script:CurrentView) { return }

  # Collect selected rows from the current view
  $selected = @()
  foreach ($o in $script:CurrentView) {
    if (-not $o) { continue }
    $isWinSec = $false
    try { $isWinSec = ($o.PSObject.Properties.Match('IsWindowsSecurityProxy').Count -gt 0 -and [bool]$o.IsWindowsSecurityProxy) } catch {}
    $isSettings = $false
    try { $isSettings = ($o.PSObject.Properties.Match('IsSettingsProxy').Count -gt 0 -and [bool]$o.IsSettingsProxy) } catch {}
    if (-not $isSettings) {
      try { $isSettings = (Test-IsSettingsAppsFolderRow -Row $o) } catch {}
    }
    if ($isWinSec -or $isSettings) { continue }

    $isWinBackup = $false
    try { $isWinBackup = ($o.PSObject.Properties.Match('IsWindowsBackupProxy').Count -gt 0 -and [bool]$o.IsWindowsBackupProxy) } catch {}
    if (-not $isWinBackup) { try { $isWinBackup = (Test-IsWindowsBackupAppsFolderRow -Row $o) } catch {} }

    # Allow selecting Windows Backup even if already pending delete so the dialog can offer "Remove From Pending".
    if ($o.Selected -and ($o.Action -ne "Delete" -or $isWinBackup)) { $selected += $o }
  }

  if ($selected.Count -eq 0) {
    [System.Windows.MessageBox]::Show("No selected items to delete.", "Delete Selected") | Out-Null
    return
  }

  # Pending creates are mock-only rows; "delete" means remove from pending create queue.
  $removedCreateCount = 0
  $selected2 = New-Object System.Collections.Generic.List[object]
  foreach ($s in @($selected)) {
    if (-not $s) { continue }
    $isPendingCreate = $false
    try { $isPendingCreate = ($s.PSObject.Properties.Match('IsPendingCreate').Count -gt 0 -and [bool]$s.IsPendingCreate) } catch {}
    if ($isPendingCreate) {
      $sid = ''
      try { $sid = [string]$s.Id } catch {}
      if (-not [string]::IsNullOrWhiteSpace($sid)) {
        if (Remove-PendingCreateRowById -Id $sid) { $removedCreateCount++ }
      }
      continue
    }
    [void]$selected2.Add($s)
  }
  $selected = @($selected2.ToArray())
  if ($removedCreateCount -gt 0 -and $selected.Count -eq 0) {
    try { Queue-RebuildVisibleRows } catch {}
    try { Refresh-UIAsync } catch {}
    return
  }

  # Expand selection: if a folder is selected, include all descendant items
  $byId = @{}  # Id -> row
  foreach ($r in $selected) {
    $rid = ""
    try { $rid = [string]$r.Id } catch {}
    if ([string]::IsNullOrWhiteSpace($rid)) { continue }

    # If folder, add descendants
    $isFolder = $false
    try { $isFolder = ($r.PSObject.Properties.Match('RowKind').Count -gt 0 -and $r.RowKind -eq 'Folder') } catch {}
    $isStartupFolder = $false
    if ($isFolder) {
      try { $isStartupFolder = (Test-IsStartupFolderRow -Row $r) } catch { $isStartupFolder = $false }
    }
    if ((-not $isStartupFolder) -and (-not $byId.ContainsKey($rid))) { $byId[$rid] = $r }

    if ($isFolder) {
      $desc = Get-DescendantItemsForFolderRow -FolderRow $r
      foreach ($it in $desc) {
        if (-not $it) { continue }
        $iid = ""
        try { $iid = [string]$it.Id } catch {}
        if ([string]::IsNullOrWhiteSpace($iid)) { continue }
        if (-not $byId.ContainsKey($iid)) { $byId[$iid] = $it }
      }
    }
  }

  # Avoid @($dict.Values) which can throw in Windows PowerShell 5.1 for some collection types.
  $targets = @($byId.Values)
  if ($targets.Count -eq 0) {
    [System.Windows.MessageBox]::Show("No valid items found to delete.", "Delete Selected") | Out-Null
    return
  }

  # ShellApp delete dialog (single dialog for all selected AppsFolder/ShellApp proxies).
  # Windows Backup has its own special flow right after this dialog.
  $shellApps = @()
  foreach ($t in @($targets)) {
    if (-not $t) { continue }
    $isAppsProxy = $false
    try { $isAppsProxy = ($t.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$t.IsAppsFolderProxy) } catch {}
    if (-not $isAppsProxy) { try { $isAppsProxy = ($t.PSObject.Properties.Match('IsAppsFolderDisplayProxy').Count -gt 0 -and [bool]$t.IsAppsFolderDisplayProxy) } catch {} }
    if ($isAppsProxy) { $shellApps += $t }
  }
  if ($shellApps.Count -gt 0) {
    $names = New-Object System.Collections.Generic.List[string]
    foreach ($r in $shellApps) {
      if (-not $r) { continue }
      $nm = ''
      try { $nm = [string](Get-PropString -Obj $r -Names @('OriginalName','Name') -Fallback '') } catch {}
      if ([string]::IsNullOrWhiteSpace($nm)) { $nm = '<unnamed>' }
      [void]$names.Add($nm)
    }
    $msg = @(
      "Selection contains AppsFolder entries."
      "Deletion will be handled as special actions in the next prompts."
      ""
      "Selected System Apps detected:"
      ($names | Sort-Object | ForEach-Object { "- " + $_ })
      ""
      "Continue?"
    ) -join "`n"
    $ok = Show-ContinueCancelDialog -Title "System App Delete" -Message $msg -ContinueText "Proceed" -CancelText "Cancel"
    if (-not $ok) { return }
  }

  # Outlook ShellApp delete flow: warn user and require explicit force-delete confirmation.
  $outlookRows = @()
  foreach ($t in @($targets)) {
    if (-not $t) { continue }
    try {
      if (Test-IsOutlookAppsFolderRow -Row $t) { $outlookRows += $t }
    } catch {}
  }
  if ($outlookRows.Count -gt 0) {
    $warn = @(
      "Removing Outlook's shortcut is not advisable without uninstalling the actual application; in which case the app's buit-in uninstaller should be used."
      "Do you still wish to prosceed with forced deletion of Outlook anyway?"
    ) -join "`n"
    $goOutlookDelete = Show-ContinueCancelDialog `
      -Title "Outlook System App Delete" `
      -Message $warn `
      -ContinueText "Delete" `
      -CancelText "Cancel (recommended)"

    if ($goOutlookDelete) {
      foreach ($r in @($outlookRows)) {
        if (-not $r) { continue }
        try { Set-PropSafeGlobal -Obj $r -Name 'OutlookForceDeleteConfirmed' -Value $true } catch {}
      }
    } else {
      foreach ($r in @($outlookRows)) {
        if (-not $r) { continue }
        try { Set-PropSafeGlobal -Obj $r -Name 'OutlookForceDeleteConfirmed' -Value $false } catch {}
        try { Set-PropSafeGlobal -Obj $r -Name 'Selected' -Value $false } catch {}
      }
      $targets = @($targets | Where-Object { $_ -notin $outlookRows })
    }
  }

  # Windows Backup special flow: prompt now, but run uninstall only on Apply Changes.
  $wb = $null
  foreach ($t in @($targets)) {
    if (-not $t) { continue }
    $isWinBackup = $false
    try { $isWinBackup = ($t.PSObject.Properties.Match('IsWindowsBackupProxy').Count -gt 0 -and [bool]$t.IsWindowsBackupProxy) } catch {}
    if (-not $isWinBackup) { try { $isWinBackup = (Test-IsWindowsBackupAppsFolderRow -Row $t) } catch {} }
    if ($isWinBackup) { $wb = $t; break }
  }
  if ($wb) {
    $alreadyPending = $false
    try { $alreadyPending = ([string]$wb.Action -eq 'Delete') } catch { $alreadyPending = $false }

    # User request: "Remove From Pending" must always be available (never greyed out).
    $choice = Show-WindowsBackupMockDeleteDialog -ShowRemoveFromPending
    if ($choice -eq 'RemovePending') {
      try { Set-PropSafeGlobal -Obj $wb -Name 'Action' -Value 'None' } catch {}
      try { Set-PropSafeGlobal -Obj $wb -Name 'PendingLabel' -Value '' } catch {}
      try { Set-PropSafeGlobal -Obj $wb -Name 'PendingLabelRows' -Value (@()) } catch {}
      try { Set-PropSafeGlobal -Obj $wb -Name 'WindowsBackupPlannedPackageName' -Value '' } catch {}
      try { Set-PropSafeGlobal -Obj $wb -Name 'Selected' -Value $false } catch {}

      $targets = @($targets | Where-Object { $_ -ne $wb })
    } elseif ($choice -eq 'Cancel') {
      # Do not touch Windows Backup; delete other selected targets.
      $targets = @($targets | Where-Object { $_ -ne $wb })
    } elseif ($choice -eq 'Continue') {
      $pkgs = @(Get-WindowsBackupRemovalPackageCandidates)
      $pick = $null
      $removeWbFromTargets = $false
      if (-not $pkgs -or $pkgs.Count -le 0) {
        [System.Windows.MessageBox]::Show(
          "No uninstall package candidates were found right now.`n`nWindows Backup will still be marked as pending delete. Run 'Delete Selected' on it again later to choose a package.",
          "Remove Windows Backup"
        ) | Out-Null
      } else {
        $pick = Select-InstalledPackageDialog -Packages $pkgs -Title "Select UserExperience Package"
        if ([string]::IsNullOrWhiteSpace($pick)) {
          # User canceled package selection for Windows Backup only.
          $removeWbFromTargets = $true
        }
      }
      if ($removeWbFromTargets) {
        $targets = @($targets | Where-Object { $_ -ne $wb })
      } else {
        try { Set-PropSafeGlobal -Obj $wb -Name 'WindowsBackupPlannedPackageName' -Value ([string]$pick) } catch {}
        try { Set-PropSafeGlobal -Obj $wb -Name 'IsWindowsBackupProxy' -Value $true } catch {}
        try { Set-PropSafeGlobal -Obj $wb -Name 'IsAppsFolderProxy' -Value $true } catch {}
        try { Set-PropSafeGlobal -Obj $wb -Name 'IsAppsFolderDisplayProxy' -Value $true } catch {}
      }
    }
  }

  if (-not $targets -or @($targets).Count -eq 0) {
    # If Windows Backup was the only target and user canceled / removed from pending / didn't pick a package,
    # just exit quietly (no "error" popup).
    try { Refresh-UI } catch {}
    try { Queue-RebuildVisibleRows } catch {}
    return
  }

  # Snapshot EVERY affected row so Undo fully restores
  $snapshot = foreach ($t in $targets) {
    [pscustomobject]@{
      Id           = [string]$t.Id
      PrevAction   = [string]$t.Action
      PrevPending  = [string]$t.PendingLabel
      PrevSelected = [bool]$t.Selected
      PrevWBPlan   = $(
        $tmp = ''
        try {
          if ($t.PSObject.Properties.Match('WindowsBackupPlannedPackageName').Count -gt 0) { $tmp = [string]$t.WindowsBackupPlannedPackageName }
        } catch {}
        $tmp
      )
      PrevOutlookForceDelete = $(
        $tmp = $false
        try {
          if ($t.PSObject.Properties.Match('OutlookForceDeleteConfirmed').Count -gt 0) { $tmp = [bool]$t.OutlookForceDeleteConfirmed }
        } catch {}
        $tmp
      )
    }
  }

  $op = [pscustomobject]@{
    Type = "MockDelete"
    Do = {
      param($snap)

      foreach ($s in $snap) {
        $x = Find-ItemById -Id $s.Id
        if (-not $x) { continue }

        # Mark deleted
        Set-RowMockDeleteState -Row $x -IsDelete $true
      }

      Refresh-UI
    }

    Undo = {
      param($snap)

      foreach ($s in $snap) {
        $x = Find-ItemById -Id $s.Id
        if (-not $x) { continue }

        # Restore
        if ($x.PSObject.Properties.Match('Action').Count -eq 0) {
          $x | Add-Member -NotePropertyName Action -NotePropertyValue $s.PrevAction -Force
        } else {
          $x.Action = $s.PrevAction
        }

        if ($x.PSObject.Properties.Match('PendingLabel').Count -eq 0) {
          $x | Add-Member -NotePropertyName PendingLabel -NotePropertyValue $s.PrevPending -Force
        } else {
          $x.PendingLabel = $s.PrevPending
        }

        if ($x.PSObject.Properties.Match('Selected').Count -gt 0) {
          $x.Selected = [bool]$s.PrevSelected
        }

        try {
          if ($x.PSObject.Properties.Match('WindowsBackupPlannedPackageName').Count -gt 0) {
            $x.WindowsBackupPlannedPackageName = [string]$s.PrevWBPlan
          }
        } catch {}
        try {
          if ($x.PSObject.Properties.Match('OutlookForceDeleteConfirmed').Count -gt 0) {
            $x.OutlookForceDeleteConfirmed = [bool]$s.PrevOutlookForceDelete
          } else {
            $x | Add-Member -NotePropertyName OutlookForceDeleteConfirmed -NotePropertyValue ([bool]$s.PrevOutlookForceDelete) -Force
          }
        } catch {}

        try { Set-PendingState -it $x } catch {}
      }

      Refresh-UI
    }

    DoArgs   = @($snapshot)
    UndoArgs = @($snapshot)
  }

  & $op.Do @($op.DoArgs)
  Push-UndoOp -op $op
})

if ($unDeleteBtn) {
  $unDeleteBtn.Add_Click({
    End-GridEditTransaction
    if (-not $script:CurrentView) { return }

    $selected = @()
    foreach ($o in @($script:CurrentView)) {
      if (-not $o) { continue }
      if ($o.Selected) { $selected += $o }
    }
    if ($selected.Count -eq 0) {
      [System.Windows.MessageBox]::Show("No selected items to un-delete.", "Un-Delete Selected") | Out-Null
      return
    }

    $byId = @{}
    foreach ($r in @($selected)) {
      if (-not $r) { continue }
      $rid = ''
      try { $rid = [string]$r.Id } catch {}
      if (-not [string]::IsNullOrWhiteSpace($rid) -and -not $byId.ContainsKey($rid)) { $byId[$rid] = $r }

      $isFolder = $false
      try { $isFolder = ($r.PSObject.Properties.Match('RowKind').Count -gt 0 -and $r.RowKind -eq 'Folder') } catch {}
      if ($isFolder) {
        foreach ($it in @(Get-DescendantItemsForFolderRow -FolderRow $r)) {
          if (-not $it) { continue }
          $iid = ''
          try { $iid = [string]$it.Id } catch {}
          if (-not [string]::IsNullOrWhiteSpace($iid) -and -not $byId.ContainsKey($iid)) { $byId[$iid] = $it }
        }
        foreach ($fr in @(Get-DescendantFolderRowsForFolderRow -FolderRow $r)) {
          if (-not $fr) { continue }
          $fid = ''
          try { $fid = [string]$fr.Id } catch {}
          if (-not [string]::IsNullOrWhiteSpace($fid) -and -not $byId.ContainsKey($fid)) { $byId[$fid] = $fr }
        }
      }
    }

    $changed = 0
    foreach ($x in @($byId.Values)) {
      if (-not $x) { continue }
      $isDeletePending = $false
      try { $isDeletePending = ([string]$x.Action -eq 'Delete') } catch {}
      if (-not $isDeletePending) {
        $pl = [string](Get-PropString -Obj $x -Names @('PendingLabel') -Fallback '')
        if (-not [string]::IsNullOrWhiteSpace($pl)) {
          foreach ($raw in @($pl -split "`r?`n")) {
            $tok = ([string]$raw).Trim()
            if ([string]::IsNullOrWhiteSpace($tok)) { continue }
            if ([string]::Equals($tok, 'Deleted', [System.StringComparison]::OrdinalIgnoreCase)) { $isDeletePending = $true; break }
          }
        }
      }
      if (-not $isDeletePending) { continue }

      try { Set-RowMockDeleteState -Row $x -IsDelete $false } catch { try { Set-PendingState -it $x } catch {} }
      try {
        if ($x.PSObject.Properties.Match('WindowsBackupPlannedPackageName').Count -gt 0) {
          $x.WindowsBackupPlannedPackageName = ''
        }
      } catch {}
      try {
        if ($x.PSObject.Properties.Match('OutlookForceDeleteConfirmed').Count -gt 0) {
          $x.OutlookForceDeleteConfirmed = $false
        }
      } catch {}
      $changed++
    }

    if ($changed -le 0) {
      [System.Windows.MessageBox]::Show("No selected items are pending delete.", "Un-Delete Selected") | Out-Null
      return
    }

    try { Refresh-UIAsync } catch {}
    try { Queue-RebuildVisibleRows } catch {}
  })
}

# ==============================================================================
# Apply (Commit)
# ==============================================================================
function Get-PendingChanges {
  $pendingDeletes = New-Object System.Collections.Generic.List[object]
  $pendingRenames = New-Object System.Collections.Generic.List[object]
  $pendingIconChanges = New-Object System.Collections.Generic.List[object]
  $pendingTargetChanges = New-Object System.Collections.Generic.List[object]
  $deletedFolderMap = Get-DeletedFolderMap
  $pendingDeleteSeen = @{}
  $pendingRenameSeen = @{}
  $pendingIconSeen = @{}
  $pendingTargetSeen = @{}
  function Add-PendingDeleteRow {
    param([object]$Row)
    if (-not $Row) { return }
    $sc = [string](Get-PropString -Obj $Row -Names @('Scope') -Fallback '')
    $op = [string](Get-PropString -Obj $Row -Names @('OriginalPath','Path') -Fallback '')
    if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($op)) { return }
    $k = ($sc.Trim().ToLowerInvariant() + '|' + $op.TrimEnd('\').ToLowerInvariant())
    if ($pendingDeleteSeen.ContainsKey($k)) { return }
    $pendingDeleteSeen[$k] = $true
    [void]$pendingDeletes.Add($Row)
  }
  function Add-PendingRenameRow {
    param([object]$Row)
    if (-not $Row) { return }
    $sc = [string](Get-PropString -Obj $Row -Names @('Scope') -Fallback '')
    $op = [string](Get-PropString -Obj $Row -Names @('OriginalPath','Path') -Fallback '')
    if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($op)) { return }
    $k = ($sc.Trim().ToLowerInvariant() + '|' + $op.TrimEnd('\').ToLowerInvariant())
    if ($pendingRenameSeen.ContainsKey($k)) { return }
    $pendingRenameSeen[$k] = $true
    [void]$pendingRenames.Add($Row)
  }
  function Add-PendingIconRow {
    param([object]$Row)
    if (-not $Row) { return }
    if (-not (Test-RowHasPendingIconChange -Row $Row)) { return }
    $sc = [string](Get-PropString -Obj $Row -Names @('Scope') -Fallback '')
    $op = [string](Get-PropString -Obj $Row -Names @('OriginalPath','Path') -Fallback '')
    if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($op)) { return }
    $k = ($sc.Trim().ToLowerInvariant() + '|' + $op.TrimEnd('\').ToLowerInvariant())
    if ($pendingIconSeen.ContainsKey($k)) { return }
    $pendingIconSeen[$k] = $true
    [void]$pendingIconChanges.Add($Row)
  }
  function Add-PendingTargetRow {
    param([object]$Row)
    if (-not $Row) { return }
    if (-not (Test-RowHasPendingTargetChange -Row $Row)) { return }
    $sc = [string](Get-PropString -Obj $Row -Names @('Scope') -Fallback '')
    $op = [string](Get-PropString -Obj $Row -Names @('OriginalPath','Path') -Fallback '')
    if ([string]::IsNullOrWhiteSpace($sc) -or [string]::IsNullOrWhiteSpace($op)) { return }
    $k = ($sc.Trim().ToLowerInvariant() + '|' + $op.TrimEnd('\').ToLowerInvariant())
    if ($pendingTargetSeen.ContainsKey($k)) { return }
    $pendingTargetSeen[$k] = $true
    [void]$pendingTargetChanges.Add($Row)
  }
  foreach ($r in $script:TreeRoots) {
    $stack = New-Object System.Collections.Generic.Stack[FolderNode]
    $stack.Push($r)
    while ($stack.Count -gt 0) {
      $n = $stack.Pop()
      # Folder deletes (directories) live in $n.Folders (not $n.Items)
      # If a folder is marked Delete, we delete the directory itself (and everything under it).
      # Items under deleted folders are skipped below to avoid conflicting operations.
      foreach ($f in $n.Folders) {
        if (-not $f) { continue }
        if ($f.PSObject.Properties.Match('Action').Count -eq 0) { continue }
        if ($f.Action -eq "Delete") {
          try { if (Test-IsStartupFolderRow -Row $f) { continue } } catch {}
          # No deletes from Meta view, ever (Meta merge picks one physical instance and would be ambiguous).
          if (([string]$f.Scope -eq 'Meta') -or ($script:CurrentNode -and ([string]$script:CurrentNode.Scope -eq 'Meta'))) { continue }
          if (-not $f.OriginalPath) {
            try { Set-PropSafeGlobal -Obj $f -Name 'OriginalPath' -Value ([string]$f.Path) } catch {}
          }
          if (-not $f.Path) {
            try { Set-PropSafeGlobal -Obj $f -Name 'Path' -Value ([string]$f.OriginalPath) } catch {}
          }
          $expandedVisual = $false
          try {
            $vsrc = @($f.VisualSources)
            if ($vsrc.Count -gt 0) {
              foreach ($src in $vsrc) {
                if (-not $src) { continue }
                $scv = [string](Get-PropString -Obj $src -Names @('Scope') -Fallback '')
                $ppv = [string](Get-PropString -Obj $src -Names @('FullPath','Path') -Fallback '')
                if ([string]::IsNullOrWhiteSpace($scv) -or [string]::IsNullOrWhiteSpace($ppv)) { continue }
                if ($scv -eq 'Meta') { continue }
                $expandedVisual = $true
                Add-PendingDeleteRow -Row ([pscustomobject]@{
                  Scope        = $scv
                  Path         = $ppv
                  OriginalPath = $ppv
                  Type         = 'Folder'
                  Name         = [string]$f.Name
                  OriginalName = [string](Get-PropString -Obj $f -Names @('OriginalName','Name') -Fallback '')
                  Action       = 'Delete'
                })
              }
            }
          } catch {}
          if (-not $expandedVisual) { Add-PendingDeleteRow -Row $f }
          continue
        }
        if ([string]$f.Name -ne [string]$f.OriginalName) {
          # VisualMenu merged folders carry VisualSources; apply rename to every physical source.
          $expandedVisual = $false
          try {
            $vsrc = @($f.VisualSources)
            if ($vsrc.Count -gt 0) {
              foreach ($src in $vsrc) {
                if (-not $src) { continue }
                $scv = [string](Get-PropString -Obj $src -Names @('Scope') -Fallback '')
                $ppv = [string](Get-PropString -Obj $src -Names @('FullPath','Path') -Fallback '')
                if ([string]::IsNullOrWhiteSpace($scv) -or [string]::IsNullOrWhiteSpace($ppv)) { continue }
                if ($scv -eq 'Meta') { continue }
                $expandedVisual = $true
                Add-PendingRenameRow -Row ([pscustomobject]@{
                  Scope        = $scv
                  Path         = $ppv
                  OriginalPath = $ppv
                  Type         = 'Folder'
                  Name         = [string]$f.Name
                  OriginalName = [string](Get-PropString -Obj $f -Names @('OriginalName','Name') -Fallback '')
                  Action       = 'Rename'
                })
              }
            }
          } catch {}
          if ($expandedVisual) { continue }
          # Meta ("Profiles") selection: apply the same folder rename to each physical instance.
          if (([string]$f.Scope -eq 'Meta') -or ($script:CurrentNode -and ([string]$script:CurrentNode.Scope -eq 'Meta'))) {
            $targets = Expand-MetaRenameTargets -Row $f -ScopeRoots $script:ScopeRoots
            foreach ($t in @($targets)) { Add-PendingRenameRow -Row $t }
          } else {
            Add-PendingRenameRow -Row $f
          }
        }
      }
      foreach ($it in $n.Items) {
        if (-not $it.OriginalPath) { continue }
        # Virtual Windows Security proxy row is applied via special handler (not filesystem rename/delete).
        try {
          if ($it.PSObject.Properties.Match('IsWindowsSecurityProxy').Count -gt 0 -and [bool]$it.IsWindowsSecurityProxy) { continue }
        } catch {}
        # AppsFolder proxy rows are not filesystem-backed; handled via special Apply step (optional uninstall).
        try {
          if ($it.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$it.IsAppsFolderProxy) { continue }
        } catch {}
        # Skip items that live under folders marked Delete (prevents conflicting ops)
        if (Test-IsUnderDeletedFolder -Scope ([string]$it.Scope) -Path ([string]$it.Path) -DeletedFolderMap $deletedFolderMap) {
          continue
        }
        if ($it.Action -eq "Delete") {
          Add-PendingDeleteRow -Row $it
          continue
        }
        Add-PendingIconRow -Row $it
        Add-PendingTargetRow -Row $it
        $itemNameChanged = ([string]$it.Name -ne [string]$it.OriginalName)
        $itemPathChanged = $false
        try {
          $itPath = Normalize-Path ([string](Get-PropString -Obj $it -Names @('Path') -Fallback ''))
          $itOrig = Normalize-Path ([string](Get-PropString -Obj $it -Names @('OriginalPath','Path') -Fallback ''))
          if (-not [string]::IsNullOrWhiteSpace($itPath) -and -not [string]::IsNullOrWhiteSpace($itOrig)) {
            $itemPathChanged = (-not (Test-PathEqualsCI -A $itPath -B $itOrig))
          }
        } catch { $itemPathChanged = $false }
        if ($itemNameChanged -or $itemPathChanged) {
          # Meta ("Profiles") selection: apply the SAME rename to every physical instance
          # across AllUsers / CurrentUser / DefaultProfile. No deletions, ever.
          if (([string]$it.Scope -eq 'Meta') -or ($script:CurrentNode -and ([string]$script:CurrentNode.Scope -eq 'Meta'))) {
            $targets = Expand-MetaRenameTargets -Row $it -ScopeRoots $script:ScopeRoots
            foreach ($t in @($targets)) { Add-PendingRenameRow -Row $t }
          } else {
            Add-PendingRenameRow -Row $it
          }
        }
      }
      foreach ($ch in $n.Children) { $stack.Push($ch) }
    }
  }
  # Safety net: include visible rows carrying icon-only pending state in case
  # the selected visual representative differs from the underlying model row.
  foreach ($vr in @($script:VisibleRows)) { Add-PendingIconRow -Row $vr }
  foreach ($vr in @($script:VisibleRows)) { Add-PendingTargetRow -Row $vr }
  if ($script:CurrentView) {
    try {
      foreach ($vr in @($script:CurrentView)) { Add-PendingIconRow -Row $vr }
      foreach ($vr in @($script:CurrentView)) { Add-PendingTargetRow -Row $vr }
    } catch {}
  }
  [pscustomobject]@{
    Deletes     = $pendingDeletes.ToArray()
    Renames     = $pendingRenames.ToArray()
    IconChanges = $pendingIconChanges.ToArray()
    TargetChanges = $pendingTargetChanges.ToArray()
    Creates     = @(Get-PendingCreateRows)
  }
}

function Get-BackupsRoot {
  $root = Join-Path $PSScriptRoot 'Start Menu Backups'
  if (-not (Test-Path -LiteralPath $root)) {
    New-Item -ItemType Directory -Path $root -Force | Out-Null
  }
  return $root
}

function Get-BackupCategoryRoot {
  param([ValidateSet('Auto','Manual')][string]$Category = 'Auto')
  return (Get-BackupsRoot)
}

function Get-BackupStamp {
  return (Get-Date).ToString('yy.MM.dd_H.m.s')
}

function New-BackupFolder {
  param(
    [string]$BaseDir = $null,
    [ValidateSet('Auto','Manual')][string]$Category = 'Auto',
    [string]$Prefix = "auto",
    [string]$Name = $null
  )
  if ([string]::IsNullOrWhiteSpace($BaseDir)) {
    $BaseDir = Get-BackupsRoot
  } else {
    if (-not (Test-Path -LiteralPath $BaseDir)) {
      New-Item -ItemType Directory -Path $BaseDir -Force | Out-Null
    }
  }
  $name = if ([string]::IsNullOrWhiteSpace($Name)) {
    "{0}_{1}" -f $Prefix, (Get-BackupStamp)
  } else {
    [string]$Name
  }
  $path = Join-Path $BaseDir $name
  New-Item -ItemType Directory -Path $path -Force | Out-Null
  return $path
}

function Get-BackupArchivePathForRoot {
  param([Parameter(Mandatory=$true)][string]$BackupRoot)
  try {
    $rootPath = Normalize-Path ([string]$BackupRoot)
    if ([string]::IsNullOrWhiteSpace($rootPath)) { return $null }
    return ([string]$rootPath + '.zip')
  } catch {
    return $null
  }
}

function Ensure-ZipSupport {
  try { Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue } catch {}
  try { Add-Type -AssemblyName System.IO.Compression -ErrorAction SilentlyContinue } catch {}
  try { $null = [System.IO.Compression.ZipFile]; return $true } catch { return $false }
}

function Write-BackupArchiveFromRoot {
  param([Parameter(Mandatory=$true)][string]$BackupRoot)
  try {
    $rootPath = Normalize-Path ([string]$BackupRoot)
    if ([string]::IsNullOrWhiteSpace($rootPath) -or -not (Test-Path -LiteralPath $rootPath -PathType Container)) { return $null }
    $archivePath = Get-BackupArchivePathForRoot -BackupRoot $rootPath
    if ([string]::IsNullOrWhiteSpace([string]$archivePath)) { return $null }
    try { if (Test-Path -LiteralPath $archivePath) { Remove-Item -LiteralPath $archivePath -Force -ErrorAction Stop } } catch {}
    $primaryError = ''
    if (Ensure-ZipSupport) {
      try {
        [System.IO.Compression.ZipFile]::CreateFromDirectory(
          [string]$rootPath,
          [string]$archivePath,
          [System.IO.Compression.CompressionLevel]::Optimal,
          $false
        )
        if (Test-Path -LiteralPath $archivePath -PathType Leaf) { return $archivePath }
      } catch {
        $primaryError = [string]$_.Exception.Message
      }
    } else {
      $primaryError = 'System.IO.Compression.ZipFile unavailable.'
    }
    try {
      try { if (Test-Path -LiteralPath $archivePath) { Remove-Item -LiteralPath $archivePath -Force -ErrorAction Stop } } catch {}
      Compress-Archive -LiteralPath $rootPath -DestinationPath $archivePath -CompressionLevel Optimal -Force -ErrorAction Stop
      if (Test-Path -LiteralPath $archivePath -PathType Leaf) { return $archivePath }
    } catch {
      $fallbackError = [string]$_.Exception.Message
      $combined = ''
      if (-not [string]::IsNullOrWhiteSpace($primaryError)) {
        $combined = ("Primary ZIP failed: {0}; Fallback ZIP failed: {1}" -f $primaryError, $fallbackError)
      } else {
        $combined = ("Fallback ZIP failed: {0}" -f $fallbackError)
      }
      return $null
    }
    return $null
  } catch {
    return $null
  }
}

function Finalize-BackupArchivePackage {
  param(
    [Parameter(Mandatory=$true)][string]$BackupRoot,
    [switch]$DeleteSourceRootOnSuccess
  )
  $out = [pscustomobject]@{
    BackupRoot    = [string](Normalize-Path ([string]$BackupRoot))
    ArchivePath   = ''
    DeletedSource = $false
    Error         = ''
  }
  try {
    $rootPath = Normalize-Path ([string]$BackupRoot)
    if ([string]::IsNullOrWhiteSpace($rootPath) -or -not (Test-Path -LiteralPath $rootPath -PathType Container)) {
      return $out
    }
    $archivePath = Write-BackupArchiveFromRoot -BackupRoot $rootPath
    if ([string]::IsNullOrWhiteSpace([string]$archivePath) -or -not (Test-Path -LiteralPath $archivePath -PathType Leaf)) {
      $out.Error = 'Archive was not created.'
      return $out
    }
    $out.ArchivePath = [string]$archivePath
    if ($DeleteSourceRootOnSuccess) {
      try {
        if (Test-Path -LiteralPath $rootPath -PathType Container) {
          Remove-Item -LiteralPath $rootPath -Recurse -Force -ErrorAction Stop
          $out.DeletedSource = $true
        }
      } catch {
        $out.Error = [string]$_.Exception.Message
      }
    }
  } catch {
    $out.Error = [string]$_.Exception.Message
  }
  return $out
}

function Select-BackupArchiveFile {
  param([string]$InitialPath = $null)
  try {
    $dlg = New-Object System.Windows.Forms.OpenFileDialog
    $dlg.Title = "Select Start Menu backup archive"
    $dlg.Filter = "Start Menu Backup Archives (*.zip)|*.zip|Legacy Backup Archives (*.smbkp.zip)|*.smbkp.zip|All files (*.*)|*.*"
    $dlg.Multiselect = $false
    $dlg.CheckFileExists = $true
    $dlg.CheckPathExists = $true
    $seed = Normalize-Path ([string]$InitialPath)
    if (-not [string]::IsNullOrWhiteSpace($seed) -and (Test-Path -LiteralPath $seed)) {
      try { $dlg.InitialDirectory = [string]$seed } catch {}
    }
    $dr = $dlg.ShowDialog()
    if ($dr -ne [System.Windows.Forms.DialogResult]::OK) { return $null }
    $picked = Normalize-Path ([string]$dlg.FileName)
    if ([string]::IsNullOrWhiteSpace($picked) -or -not (Test-Path -LiteralPath $picked -PathType Leaf)) { return $null }
    return $picked
  } catch {
    return $null
  }
}

function Resolve-PreRestoreBackupPath {
  param(
    [string]$PreRestoreRoot = $null,
    [System.Collections.Generic.List[string]]$Errors = $null
  )
  $preOut = Normalize-Path ([string]$PreRestoreRoot)
  if ([string]::IsNullOrWhiteSpace($preOut)) { return $null }
  if (-not (Test-Path -LiteralPath $preOut -PathType Container)) { return $preOut }
  try {
    $finalized = Finalize-BackupArchivePackage -BackupRoot $preOut -DeleteSourceRootOnSuccess
    if ($finalized -and -not [string]::IsNullOrWhiteSpace([string]$finalized.ArchivePath)) {
      $zipPath = Normalize-Path ([string]$finalized.ArchivePath)
      if (-not [string]::IsNullOrWhiteSpace($zipPath) -and (Test-Path -LiteralPath $zipPath -PathType Leaf)) {
        return $zipPath
      }
    }
    if ($finalized -and -not [string]::IsNullOrWhiteSpace([string]$finalized.Error) -and $Errors) {
      [void]$Errors.Add(("PRE-RESTORE ARCHIVE :: {0}" -f [string]$finalized.Error))
    }
  } catch {
    if ($Errors) { [void]$Errors.Add(("PRE-RESTORE ARCHIVE :: {0}" -f $_.Exception.Message)) }
  }
  return $preOut
}

function Expand-BackupArchiveForRestore {
  param([Parameter(Mandatory=$true)][string]$ArchivePath)
  try {
    $zipPath = Normalize-Path ([string]$ArchivePath)
    if ([string]::IsNullOrWhiteSpace($zipPath) -or -not (Test-Path -LiteralPath $zipPath -PathType Leaf)) {
      throw "Backup archive not found: $ArchivePath"
    }
    if (-not (Ensure-ZipSupport)) { throw "ZIP support is unavailable." }
    $tempRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("StartMenuRestore_" + [guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory -Path $tempRoot -Force | Out-Null
    [System.IO.Compression.ZipFile]::ExtractToDirectory([string]$zipPath, [string]$tempRoot)
    $restoreRoot = $tempRoot
    $manifestAtRoot = Test-Path -LiteralPath (Join-Path $restoreRoot 'Manifest.json')
    if (-not $manifestAtRoot) {
      $dirs = @()
      try { $dirs = @(Get-ChildItem -LiteralPath $tempRoot -Directory -ErrorAction SilentlyContinue) } catch { $dirs = @() }
      if ($dirs.Count -eq 1) {
        $inner = [string]$dirs[0].FullName
        if (Test-Path -LiteralPath (Join-Path $inner 'Manifest.json')) {
          $restoreRoot = $inner
        }
      }
    }
    return [pscustomobject]@{
      TempRoot    = [string]$tempRoot
      RestoreRoot = [string]$restoreRoot
    }
  } catch {
    throw
  }
}

function Resolve-ManifestRestoreDestinationPath {
  param(
    [string]$Scope,
    [string]$RelativePath,
    [string]$OriginalPath
  )
  try {
    $sc = [string]$Scope
    $rel = [string]$RelativePath
    $relDecoded = Convert-RelativePathFromBackupStorage -RelativePath $rel
    $orig = [string]$OriginalPath
    if (-not [string]::IsNullOrWhiteSpace($sc) -and $scopeRoots.ContainsKey($sc)) {
      $root = Normalize-Path ([string]$scopeRoots[$sc])
      if (-not [string]::IsNullOrWhiteSpace($root)) {
        if (-not [string]::IsNullOrWhiteSpace($relDecoded)) {
          $p = Normalize-Path (Join-Path $root $relDecoded)
          if (-not [string]::IsNullOrWhiteSpace($p)) { return $p }
        }
      }
    }
    $o = Normalize-Path $orig
    if (-not [string]::IsNullOrWhiteSpace($o)) { return $o }
  } catch {}
  return $null
}

function Get-TextSha1Hex {
  param([string]$Text)
  try {
    $t = [string]$Text
    $sha1 = [System.Security.Cryptography.SHA1]::Create()
    try {
      $bytes = [System.Text.Encoding]::UTF8.GetBytes($t)
      $hash = $sha1.ComputeHash($bytes)
      return ([System.BitConverter]::ToString($hash) -replace '-', '').ToLowerInvariant()
    } finally {
      try { $sha1.Dispose() } catch {}
    }
  } catch {
    return ''
  }
}

function Get-RestoredShortcutIconCacheRoot {
  try {
    $root = Get-SystemIconUserSettingsRoot
    if ([string]::IsNullOrWhiteSpace($root)) { return '' }
    $dir = Join-Path $root 'Restored Shortcut Icons'
    if (-not (Test-Path -LiteralPath $dir -PathType Container)) {
      New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    return [string]$dir
  } catch {
    return ''
  }
}

function Install-RestoredShortcutIconForDestination {
  param(
    [Parameter(Mandatory=$true)][string]$DestinationLnkPath,
    [string]$BackupRoot = $null,
    [string]$IconBackupRelative = $null,
    [string]$IconSourceFile = $null
  )
  try {
    $dstLnk = Resolve-ExistingPathLenient -Path ([string]$DestinationLnkPath)
    if ([string]::IsNullOrWhiteSpace($dstLnk)) { $dstLnk = Normalize-Path ([string]$DestinationLnkPath) }
    if ([string]::IsNullOrWhiteSpace($dstLnk) -or -not (Test-Path -LiteralPath $dstLnk -PathType Leaf)) {
      return [pscustomobject]@{ Ok = $false; Error = 'Destination shortcut missing.' }
    }
    $srcIcon = ''
    if (-not [string]::IsNullOrWhiteSpace([string]$IconSourceFile)) {
      $srcIcon = Resolve-ExistingPathLenient -Path ([string]$IconSourceFile)
      if ([string]::IsNullOrWhiteSpace($srcIcon)) { $srcIcon = Normalize-Path ([string]$IconSourceFile) }
    } elseif (-not [string]::IsNullOrWhiteSpace([string]$BackupRoot) -and -not [string]::IsNullOrWhiteSpace([string]$IconBackupRelative)) {
      $srcIcon = Resolve-ExistingPathLenient -Path (Join-Path ([string]$BackupRoot) ([string]$IconBackupRelative))
      if ([string]::IsNullOrWhiteSpace($srcIcon)) { $srcIcon = Normalize-Path (Join-Path ([string]$BackupRoot) ([string]$IconBackupRelative)) }
    }
    if ([string]::IsNullOrWhiteSpace($srcIcon) -or -not (Test-Path -LiteralPath $srcIcon -PathType Leaf)) {
      return [pscustomobject]@{ Ok = $false; Error = 'Icon source file missing.' }
    }
    $cacheRoot = Get-RestoredShortcutIconCacheRoot
    if ([string]::IsNullOrWhiteSpace($cacheRoot)) {
      return [pscustomobject]@{ Ok = $false; Error = 'Icon cache root unavailable.' }
    }
    $identity = ([string]$dstLnk).ToLowerInvariant() + '|' + ([string]$IconBackupRelative).ToLowerInvariant()
    if ([string]::IsNullOrWhiteSpace($identity.Trim('|'))) {
      $identity = ([string]$dstLnk).ToLowerInvariant() + '|' + ([string]$srcIcon).ToLowerInvariant()
    }
    $hex = Get-TextSha1Hex -Text $identity
    if ([string]::IsNullOrWhiteSpace($hex)) { $hex = [guid]::NewGuid().ToString('N') }
    $cacheIco = Join-Path $cacheRoot ($hex + '.ico')
    $cacheDir = Split-Path -Path $cacheIco -Parent
    if (-not (Test-Path -LiteralPath $cacheDir -PathType Container)) {
      New-Item -ItemType Directory -Path $cacheDir -Force | Out-Null
    }
    Copy-Item -LiteralPath $srcIcon -Destination $cacheIco -Force -ErrorAction Stop
    # Prefer Unicode-safe shell-link writer for destination paths containing symbols/emoji.
    $iconApplied = $false
    $nativeErr = ''
    try {
      Ensure-ShellLinkInteropTypes
      $link = New-Object StartMenuTool.ShellLink
      $pf = [StartMenuTool.IPersistFile]$link
      [void]$pf.Load([string]$dstLnk, 2) # STGM_READWRITE
      $sl = [StartMenuTool.IShellLinkW]$link
      [void]$sl.SetIconLocation([string]$cacheIco, 0)
      [void]$pf.Save([string]$dstLnk, $true)
      $iconApplied = $true
    } catch {
      $nativeErr = [string]$_.Exception.Message
      $iconApplied = $false
    }
    if (-not $iconApplied) {
      # Fallback for environments where native interface is unavailable.
      $ws = New-Object -ComObject WScript.Shell
      $sc = $ws.CreateShortcut($dstLnk)
      $sc.IconLocation = ([string]$cacheIco + ',0')
      $sc.Save()
      $iconApplied = $true
    }
    if (-not $iconApplied) {
      if ([string]::IsNullOrWhiteSpace($nativeErr)) { $nativeErr = 'Failed to set icon location.' }
      return [pscustomobject]@{ Ok = $false; Error = $nativeErr }
    }
    return [pscustomobject]@{
      Ok = $true
      CachePath = [string]$cacheIco
    }
  } catch {
    return [pscustomobject]@{ Ok = $false; Error = [string]$_.Exception.Message }
  }
}

function Test-SkipRestoreIconRelinkForExplorerShortcut {
  param(
    [Parameter(Mandatory=$true)][string]$ShortcutPath
  )
  try {
    $lnk = Resolve-ExistingPathLenient -Path ([string]$ShortcutPath)
    if ([string]::IsNullOrWhiteSpace($lnk)) { $lnk = Normalize-Path ([string]$ShortcutPath) }
    if ([string]::IsNullOrWhiteSpace($lnk) -or -not (Test-Path -LiteralPath $lnk -PathType Leaf)) { return $false }
    $ext = ''
    try { $ext = [string][IO.Path]::GetExtension($lnk) } catch { $ext = '' }
    if ([string]::IsNullOrWhiteSpace($ext) -or -not $ext.Equals('.lnk', [StringComparison]::OrdinalIgnoreCase)) { return $false }
    $ws = New-Object -ComObject WScript.Shell
    $sc = $ws.CreateShortcut($lnk)
    $target = ''
    $args = ''
    $iconLoc = ''
    try { $target = Normalize-Path ([string]$sc.TargetPath) } catch { $target = '' }
    try { $args = [string]$sc.Arguments } catch { $args = '' }
    try { $iconLoc = [string]$sc.IconLocation } catch { $iconLoc = '' }
    $t = ''
    $a = ''
    $i = ''
    try { $t = [string]$target } catch { $t = '' }
    try { $a = ([string]$args).ToLowerInvariant() } catch { $a = [string]$args }
    try { $i = ([string]$iconLoc).ToLowerInvariant() } catch { $i = [string]$iconLoc }
    # Keep shell/native icon behavior intact for explorer-backed folder/shell shortcuts.
    if (-not [string]::IsNullOrWhiteSpace($t) -and $t -match '(?i)\\explorer\.exe$') { return $true }
    if ([string]::IsNullOrWhiteSpace($t)) {
      if ($a -match '(?i)(shell:|/e,|/root,|/select,)' -and $i -match '(?i)explorer\.exe') { return $true }
    }
    return $false
  } catch {
    return $false
  }
}

function Get-StableKey {
  param([Parameter(Mandatory=$true)][object]$it)
  $scope = [string]$it.Scope
  $p = Normalize-Path ([string]$it.OriginalPath)
  if ([string]::IsNullOrWhiteSpace($scope) -or [string]::IsNullOrWhiteSpace($p)) { return $null }
  return ("{0}|{1}" -f $scope, $p.ToLowerInvariant())
}

function Collect-ProfileEntries {
  $entries = New-Object System.Collections.Generic.List[object]
  $pending = Get-PendingChanges
  foreach ($it in $pending.Deletes) {
    $k = Get-StableKey -it $it
    if (-not $k) { continue }
    [void]$entries.Add([pscustomobject]@{
      Key          = $k
      Scope        = [string]$it.Scope
      OriginalPath = Normalize-Path ([string]$it.OriginalPath)
      Type         = [string]$it.Type
      Action       = "Delete"
      NewName      = $null
    })
  }
  foreach ($it in $pending.Renames) {
    $k = Get-StableKey -it $it
    if (-not $k) { continue }
    $newPath = Normalize-Path ([string](Get-PropString -Obj $it -Names @('Path','OriginalPath') -Fallback ''))
    [void]$entries.Add([pscustomobject]@{
      Key          = $k
      Scope        = [string]$it.Scope
      OriginalPath = Normalize-Path ([string]$it.OriginalPath)
      Type         = [string]$it.Type
      Action       = "Rename"
      NewName      = [string]$it.Name
      NewPath      = [string]$newPath
    })
  }
  foreach ($it in $pending.IconChanges) {
    $k = Get-StableKey -it $it
    if (-not $k) { continue }
    $iconPath = Normalize-Path ([string](Get-PropString -Obj $it -Names @('PendingIconPath') -Fallback ''))
    if ([string]::IsNullOrWhiteSpace($iconPath)) { continue }
    $iconIndex = 0
    try { $iconIndex = [int](Get-PropString -Obj $it -Names @('PendingIconIndex') -Fallback '0') } catch { $iconIndex = 0 }
    [void]$entries.Add([pscustomobject]@{
      Key              = $k
      Scope            = [string]$it.Scope
      OriginalPath     = Normalize-Path ([string]$it.OriginalPath)
      Type             = [string]$it.Type
      Action           = "IconEdit"
      NewName          = $null
      PendingIconPath  = [string]$iconPath
      PendingIconIndex = [int]$iconIndex
    })
  }
  foreach ($it in $pending.TargetChanges) {
    $k = Get-StableKey -it $it
    if (-not $k) { continue }
    $pendingTarget = Normalize-Path ([string](Get-PropString -Obj $it -Names @('PendingTargetPath') -Fallback ''))
    if ([string]::IsNullOrWhiteSpace($pendingTarget)) { continue }
    [void]$entries.Add([pscustomobject]@{
      Key               = $k
      Scope             = [string]$it.Scope
      OriginalPath      = Normalize-Path ([string]$it.OriginalPath)
      Type              = [string]$it.Type
      Action            = "TargetEdit"
      NewName           = $null
      PendingTargetPath = [string]$pendingTarget
    })
  }
  return $entries.ToArray()
}

function New-PlanPayload {
  param([Parameter(Mandatory=$true)][object[]]$Entries)
  return ([pscustomobject]@{
    SchemaVersion = 1
    CreatedUtc    = (Get-Date).ToUniversalTime().ToString("o")
    ComputerName  = $env:COMPUTERNAME
    UserName      = $env:USERNAME
    Tool          = "Start Menu Cleanup (Mockup Tree)"
    Entries       = $Entries
  })
}

function Save-PlanJson {
  param(
    [Parameter(Mandatory=$true)][string]$Path,
    [Parameter(Mandatory=$true)][object]$Payload
  )
  $json = $Payload | ConvertTo-Json -Depth 8
  [IO.File]::WriteAllText($Path, $json, [Text.Encoding]::UTF8)
}

function Write-BackupBundle {
  param(
    [Parameter(Mandatory=$true)][string]$BackupRoot,
    [Parameter(Mandatory=$true)][object[]]$Entries
  )
  $snapshotRoot = Join-Path $BackupRoot "Snapshot"
  New-Item -ItemType Directory -Path $snapshotRoot -Force | Out-Null
  $items  = New-Object System.Collections.Generic.List[object]
  $folders = New-Object System.Collections.Generic.List[object]
  $errors = New-Object System.Collections.Generic.List[string]
  $convOriginal = New-Object System.Collections.Generic.List[object]
  $convUnicode  = New-Object System.Collections.Generic.List[object]
  $convMappings = New-Object System.Collections.Generic.List[object]
  $convSeen     = @{}
  $copied = 0
  $folderSeen = @{}
  function Add-ManifestFolderRecord {
    param([string]$Scope, [string]$RootPath, [string]$FolderPath)
    try {
      if ([string]::IsNullOrWhiteSpace($Scope) -or [string]::IsNullOrWhiteSpace($RootPath) -or [string]::IsNullOrWhiteSpace($FolderPath)) { return }
      $rootN = ([string]$RootPath).TrimEnd('\')
      $fp = Normalize-Path ([string]$FolderPath)
      if ([string]::IsNullOrWhiteSpace($fp)) { return }
      if ($fp.Equals($rootN, [StringComparison]::OrdinalIgnoreCase)) { return }
      if (-not $fp.StartsWith($rootN + '\', [StringComparison]::OrdinalIgnoreCase)) { return }
      $rel = $fp.Substring($rootN.Length).TrimStart('\')
      if ([string]::IsNullOrWhiteSpace($rel)) { return }
      $relUnicode = Convert-RelativePathToUnicodeNotation -RelativePath $rel
      $relStore = Convert-RelativePathToBackupStorage -RelativePath $rel
      $k = ("{0}|{1}" -f $Scope, $fp.ToLowerInvariant())
      if ($folderSeen.ContainsKey($k)) { return }
      $folderSeen[$k] = $true
      Add-ConversionListMapping -Seen $convSeen -OriginalList $convOriginal -UnicodeList $convUnicode -Mappings $convMappings -Scope $Scope -Type 'Folder' -OriginalRelativePath $rel -UnicodeRelativePath $relUnicode
      [void]$folders.Add([pscustomobject]@{
        Scope        = $Scope
        OriginalPath = (Convert-ToPortableStartMenuPath -Scope $Scope -AbsolutePath $fp -RelativePath $rel)
        RelativePath = (Convert-RelativePathToBackupStorage -RelativePath $relUnicode)
      })
    } catch {}
  }
  foreach ($e in $Entries) {
    try {
      $scope = [string]$e.Scope
      $src   = Normalize-Path ([string]$e.OriginalPath)
      if (-not $src -or -not (Test-Path -LiteralPath $src)) { continue }
      if (-not $scopeRoots.ContainsKey($scope)) { continue }
      $entryAction = ''
      try { $entryAction = [string]$e.Action } catch { $entryAction = '' }
      if ($entryAction -eq 'Create') { continue }
      $root = $scopeRoots[$scope].TrimEnd('\')
      $rootN = ([string]$root).TrimEnd('\')
      # Snapshot semantics:
      # - If an entry is a folder, snapshot ALL shortcuts/urls inside it (recursive).
      # - If an entry is a file, snapshot it only if it is a shortcut/url.
      $isDir = $false
      try { $isDir = (Test-Path -LiteralPath $src -PathType Container) } catch { $isDir = $false }
      if ($isDir) {
        Add-ManifestFolderRecord -Scope $scope -RootPath $rootN -FolderPath $src
        try {
          $subDirs = @(Get-ChildItem -LiteralPath $src -Directory -Recurse -Force -ErrorAction SilentlyContinue)
          foreach ($sd in @($subDirs)) {
            if (-not $sd) { continue }
            Add-ManifestFolderRecord -Scope $scope -RootPath $rootN -FolderPath ([string]$sd.FullName)
          }
        } catch {}
        $files = @()
        try {
          $files = Get-ChildItem -LiteralPath $src -File -Recurse -Force -ErrorAction SilentlyContinue |
                   Where-Object { $_.Extension -in @(".lnk",".url") }
        } catch { $files = @() }
        foreach ($f in @($files)) {
          try {
            if (-not $f) { continue }
            $srcFile = Normalize-Path ([string]$f.FullName)
            if ([string]::IsNullOrWhiteSpace($srcFile)) { continue }
            $relFile = $srcFile
            if ($srcFile.StartsWith($rootN, [StringComparison]::OrdinalIgnoreCase)) {
              $relFile = $srcFile.Substring($rootN.Length).TrimStart('\')
            } else {
              $relFile = Join-Path "Misc" ([IO.Path]::GetFileName($srcFile))
            }
            $relFileUnicode = Convert-RelativePathToUnicodeNotation -RelativePath $relFile
            $relFileStore = Convert-RelativePathToBackupStorage -RelativePath $relFileUnicode
            $dstFile = Join-Path (Join-Path $snapshotRoot $scope) $relFileStore
            $dstDir  = Split-Path -Path $dstFile -Parent
            New-Item -ItemType Directory -Path $dstDir -Force | Out-Null
            Copy-Item -LiteralPath $srcFile -Destination $dstFile -Force -ErrorAction Stop
            $copied++
            Add-ConversionListMapping -Seen $convSeen -OriginalList $convOriginal -UnicodeList $convUnicode -Mappings $convMappings -Scope $scope -Type 'File' -OriginalRelativePath $relFile -UnicodeRelativePath $relFileUnicode
            [void]$items.Add([pscustomobject]@{
              Scope        = $scope
              OriginalPath = (Convert-ToPortableStartMenuPath -Scope $scope -AbsolutePath $srcFile -RelativePath $relFile)
              RelativePath = $relFileStore
              SnapshotPath = $dstFile
            })
          } catch {
            [void]$errors.Add(("SNAPSHOT :: {0} :: {1}" -f $f.FullName, $_.Exception.Message))
          }
        }
        continue
      }
      # File entry: only snapshot restorable shortcut/url types.
      $ext = ''
      try { $ext = [string][IO.Path]::GetExtension($src) } catch { $ext = '' }
      if ($ext -notin @(".lnk",".url")) { continue }
      $rel = $src
      if ($src.StartsWith($rootN, [StringComparison]::OrdinalIgnoreCase)) {
        $rel = $src.Substring($rootN.Length).TrimStart('\')
      } else {
        $rel = Join-Path "Misc" ([IO.Path]::GetFileName($src))
      }
      $relUnicode = Convert-RelativePathToUnicodeNotation -RelativePath $rel
      $relStore = Convert-RelativePathToBackupStorage -RelativePath $relUnicode
      $dst = Join-Path (Join-Path $snapshotRoot $scope) $relStore
      $dstDir = Split-Path -Path $dst -Parent
      New-Item -ItemType Directory -Path $dstDir -Force | Out-Null
      Copy-Item -LiteralPath $src -Destination $dst -Force -ErrorAction Stop
      $copied++
        Add-ConversionListMapping -Seen $convSeen -OriginalList $convOriginal -UnicodeList $convUnicode -Mappings $convMappings -Scope $scope -Type 'File' -OriginalRelativePath $rel -UnicodeRelativePath $relUnicode
        [void]$items.Add([pscustomobject]@{
          Scope        = $scope
          OriginalPath = (Convert-ToPortableStartMenuPath -Scope $scope -AbsolutePath $src -RelativePath $rel)
          RelativePath = $relStore
          SnapshotPath = $dst
        })
    } catch {
      [void]$errors.Add(("SNAPSHOT :: {0} :: {1}" -f $e.OriginalPath, $_.Exception.Message))
    }
  }
  Save-PlanJson -Path (Join-Path $BackupRoot "Plan.startmenu.json") -Payload (New-PlanPayload -Entries $Entries)
  Save-ConversionListJson -BackupRoot $BackupRoot -OriginalList $convOriginal -UnicodeList $convUnicode -Mappings $convMappings
  Save-PlanJson -Path (Join-Path $BackupRoot "Manifest.json") -Payload ([pscustomobject]@{
    SchemaVersion = 2
    FullSnapshot  = $false
    CreatedUtc    = (Get-Date).ToUniversalTime().ToString("o")
    Copied        = $copied
    Items         = $items.ToArray()
    Folders       = $folders.ToArray()
    Errors        = $errors.ToArray()
  })
  $archivePath = $null
  try { $archivePath = Write-BackupArchiveFromRoot -BackupRoot $BackupRoot } catch { $archivePath = $null }
  return [pscustomobject]@{ Copied=$copied; Errors=$errors.ToArray(); ArchivePath=[string]$archivePath }
}
function Write-FullSnapshotBundle {
  param(
    [Parameter(Mandatory=$true)][string]$BackupRoot
  )
  $snapshotRoot = Join-Path $BackupRoot "Snapshot"
  New-Item -ItemType Directory -Path $snapshotRoot -Force | Out-Null
  $items  = New-Object System.Collections.Generic.List[object]
  $folders = New-Object System.Collections.Generic.List[object]
  $errors = New-Object System.Collections.Generic.List[string]
  $convOriginal = New-Object System.Collections.Generic.List[object]
  $convUnicode  = New-Object System.Collections.Generic.List[object]
  $convMappings = New-Object System.Collections.Generic.List[object]
  $convSeen     = @{}
  $copied = 0
  foreach ($kv in $scopeRoots.GetEnumerator()) {
    $scope    = $kv.Key
    $rootPath = ($kv.Value.TrimEnd('\'))
    if (-not (Test-Path -LiteralPath $rootPath)) { continue }
    try {
      $dirs = @(Get-ChildItem -LiteralPath $rootPath -Directory -Recurse -Force -ErrorAction SilentlyContinue)
      foreach ($d in @($dirs)) {
        if (-not $d) { continue }
        $dirPath = Normalize-Path ([string]$d.FullName)
        if ([string]::IsNullOrWhiteSpace($dirPath)) { continue }
        if ($dirPath.Equals($rootPath, [StringComparison]::OrdinalIgnoreCase)) { continue }
        if (-not $dirPath.StartsWith($rootPath + '\', [StringComparison]::OrdinalIgnoreCase)) { continue }
        $relDir = $dirPath.Substring($rootPath.Length).TrimStart('\')
        if ([string]::IsNullOrWhiteSpace($relDir)) { continue }
        $relDirUnicode = Convert-RelativePathToUnicodeNotation -RelativePath $relDir
        $relDirStore = Convert-RelativePathToBackupStorage -RelativePath $relDirUnicode
        Add-ConversionListMapping -Seen $convSeen -OriginalList $convOriginal -UnicodeList $convUnicode -Mappings $convMappings -Scope $scope -Type 'Folder' -OriginalRelativePath $relDir -UnicodeRelativePath $relDirUnicode
        [void]$folders.Add([pscustomobject]@{
          Scope        = $scope
          OriginalPath = (Convert-ToPortableStartMenuPath -Scope $scope -AbsolutePath $dirPath -RelativePath $relDir)
          RelativePath = $relDirStore
        })
      }
    } catch {}
    # Full-fidelity snapshot: include all files under each Start Menu scope.
    $files = @()
    try {
      $files += Get-ChildItem -LiteralPath $rootPath -File -Recurse -Force -ErrorAction SilentlyContinue |
                Where-Object { $_ }
    } catch {}
    foreach ($f in $files) {
      try {
        $src = $f.FullName
        $rel = $src.Substring($rootPath.Length).TrimStart('\')
        if ([string]::IsNullOrWhiteSpace($rel)) {
          $rel = [IO.Path]::GetFileName($src)
        }
        $relUnicode = Convert-RelativePathToUnicodeNotation -RelativePath $rel
        $relStore = Convert-RelativePathToBackupStorage -RelativePath $relUnicode
        $ext = ''
        try { $ext = [string][IO.Path]::GetExtension($src) } catch { $ext = '' }
        $isLnk = $false
        try { $isLnk = ($ext -and $ext.Equals('.lnk', [StringComparison]::OrdinalIgnoreCase)) } catch { $isLnk = $false }
        $dst = Join-Path (Join-Path $snapshotRoot $scope) $relStore
        $dstDir = Split-Path -Path $dst -Parent
        New-Item -ItemType Directory -Path $dstDir -Force | Out-Null
        Copy-Item -LiteralPath $src -Destination $dst -Force -ErrorAction Stop
        $iconBackupRelative = $null
        if ($isLnk) {
          try {
            $iconBackupRelative = Join-Path (Join-Path 'ShortcutIcons' $scope) ($relStore + '.ico')
            $iconBackupAbs = Normalize-Path (Join-Path $BackupRoot $iconBackupRelative)
            $exp = Export-ShortcutIconToIcoFile -ShortcutPath $src -DestinationIcoPath $iconBackupAbs
            if ([string]::IsNullOrWhiteSpace([string]$exp) -or -not (Test-Path -LiteralPath $exp -PathType Leaf)) {
              $iconBackupRelative = $null
            }
          } catch {
            $iconBackupRelative = $null
          }
        }
        $copied++
        Add-ConversionListMapping -Seen $convSeen -OriginalList $convOriginal -UnicodeList $convUnicode -Mappings $convMappings -Scope $scope -Type 'File' -OriginalRelativePath $rel -UnicodeRelativePath $relUnicode
        [void]$items.Add([pscustomobject]@{
          Scope        = $scope
          OriginalPath = (Convert-ToPortableStartMenuPath -Scope $scope -AbsolutePath $src -RelativePath $rel)
          RelativePath = $relStore
          SnapshotPath = $dst
          IconBackupRelative = $iconBackupRelative
        })
      } catch {
        [void]$errors.Add(("SNAPSHOT :: {0} :: {1}" -f $f.FullName, $_.Exception.Message))
      }
    }
  }
  Save-PlanJson -Path (Join-Path $BackupRoot "Manifest.json") -Payload ([pscustomobject]@{
    SchemaVersion = 2
    FullSnapshot  = $true
    CreatedUtc    = (Get-Date).ToUniversalTime().ToString("o")
    Copied        = $copied
    Items         = $items.ToArray()
    Folders       = $folders.ToArray()
    Errors        = $errors.ToArray()
  })
  try {
    $entries = @()
    foreach ($it in @($items.ToArray())) {
      if (-not $it) { continue }
      $scope = [string]$it.Scope
      $orig  = Normalize-Path ([string]$it.OriginalPath)
      if ([string]::IsNullOrWhiteSpace($scope) -or [string]::IsNullOrWhiteSpace($orig)) { continue }
      $entries += [pscustomobject]@{
        Key          = ("{0}|{1}" -f $scope, $orig.ToLowerInvariant())
        Scope        = $scope
        OriginalPath = $orig
        Type         = [string][IO.Path]::GetExtension($orig)
        Action       = "Snapshot"
        NewName      = $null
      }
    }
    Save-PlanJson -Path (Join-Path $BackupRoot "Plan.startmenu.json") -Payload (New-PlanPayload -Entries $entries)
  } catch {}
  Save-ConversionListJson -BackupRoot $BackupRoot -OriginalList $convOriginal -UnicodeList $convUnicode -Mappings $convMappings
  $archivePath = $null
  try { $archivePath = Write-BackupArchiveFromRoot -BackupRoot $BackupRoot } catch { $archivePath = $null }
  return [pscustomobject]@{
    Copied = $copied
    Errors = $errors.ToArray()
    ArchivePath = [string]$archivePath
  }
}

function Backup-And-ApplyChanges {
  param(
    [object[]]$Deletes,
    [object[]]$Renames,
    [object[]]$Creates = @(),
    [object[]]$IconChanges = @(),
    [object[]]$TargetChanges = @(),
    [string]$BackupRoot = $null
  )
  $backupRoot = [string]$BackupRoot
  function Ensure-BackupRootForApply {
    if ([string]::IsNullOrWhiteSpace($backupRoot)) {
      $backupRoot = New-BackupFolder -Category Auto -Prefix "auto"
    }
    if (-not (Test-Path -LiteralPath $backupRoot)) {
      New-Item -ItemType Directory -Path $backupRoot -Force | Out-Null
    }
    return $backupRoot
  }
  $deleted = 0
  $renamed = 0
  $iconChanged = 0
  $targetChanged = 0
  $errors  = New-Object System.Collections.Generic.List[string]
  $bundleEntries = New-Object System.Collections.Generic.List[object]
  $bundleSeen = @{}
  function Add-BundleEntry {
    param(
      [Parameter(Mandatory=$true)][object]$Row,
      [Parameter(Mandatory=$true)][string]$Action
    )
    if (-not $Row) { return }
    $scope = [string](Get-PropString -Obj $Row -Names @('Scope') -Fallback '')
    $orig  = Normalize-Path ([string](Get-PropString -Obj $Row -Names @('OriginalPath','Path') -Fallback ''))
    if ([string]::IsNullOrWhiteSpace($scope) -or [string]::IsNullOrWhiteSpace($orig)) { return }
    $key = (($Action.Trim().ToLowerInvariant()) + '|' + ($scope.Trim().ToLowerInvariant()) + '|' + ($orig.TrimEnd('\').ToLowerInvariant()))
    if ($bundleSeen.ContainsKey($key)) { return }
    $bundleSeen[$key] = $true
    [void]$bundleEntries.Add([pscustomobject]@{
      Key          = ("{0}|{1}" -f $scope, $orig.ToLowerInvariant())
      Scope        = $scope
      OriginalPath = $orig
      Type         = [string](Get-PropString -Obj $Row -Names @('Type') -Fallback '')
      Action       = $Action
      NewName      = $(if ($Action -eq 'Rename') { [string](Get-PropString -Obj $Row -Names @('Name') -Fallback '') } else { $null })
      NewPath      = $(if ($Action -in @('Rename','Move','Create')) { Normalize-Path ([string](Get-PropString -Obj $Row -Names @('Path','OriginalPath') -Fallback '')) } else { $null })
    })
  }
  foreach ($x in @($Renames)) { Add-BundleEntry -Row $x -Action 'Rename' }
  foreach ($x in @($Creates)) { Add-BundleEntry -Row $x -Action 'Create' }
  foreach ($x in @($Deletes)) { Add-BundleEntry -Row $x -Action 'Delete' }
  foreach ($x in @($IconChanges)) { Add-BundleEntry -Row $x -Action 'Icon' }
  foreach ($x in @($TargetChanges)) { Add-BundleEntry -Row $x -Action 'Target' }
  # Write bundle (Plan + Manifest + Snapshot) BEFORE mutating filesystem,
  # but keep restore backups as full snapshots. If a full snapshot is not
  # already present at backup root, create one here as a safety net.
  try {
    $planEntries = @($bundleEntries.ToArray())
    if ($planEntries.Length -gt 0) {
      $backupRoot = Ensure-BackupRootForApply
      $manifestPath = Join-Path $backupRoot 'Manifest.json'
      $hasFullSnapshotManifest = $false
      try {
        if (Test-Path -LiteralPath $manifestPath -PathType Leaf) {
          $manifestRaw = Get-Content -LiteralPath $manifestPath -Raw -ErrorAction Stop
          $manifestObj = $manifestRaw | ConvertFrom-Json -ErrorAction Stop
          if ($manifestObj -and $manifestObj.PSObject.Properties.Match('FullSnapshot').Count -gt 0 -and [bool]$manifestObj.FullSnapshot) {
            $hasFullSnapshotManifest = $true
          }
        }
      } catch {}
      if (-not $hasFullSnapshotManifest) {
        $full = Write-FullSnapshotBundle -BackupRoot $backupRoot
        if ($full -and $full.Errors -and @($full.Errors).Count -gt 0) { foreach ($e in @($full.Errors)) { [void]$errors.Add([string]$e) } }
      }
      # Keep the apply operation plan as metadata only; do not replace Manifest.json.
      Save-PlanJson -Path (Join-Path $backupRoot 'Plan.apply.startmenu.json') -Payload (New-PlanPayload -Entries $planEntries)
    }
  } catch {
    [void]$errors.Add(("BUNDLE :: {0}" -f $_.Exception.Message))
  }
  function Backup-One {
    param([object]$it)
    $src = [string](Get-PropString -Obj $it -Names @('OriginalPath','Path') -Fallback '')
    if (-not [string]::IsNullOrWhiteSpace($src) -and -not (Test-Path -LiteralPath $src)) {
      $alt = [string](Get-PropString -Obj $it -Names @('Path','OriginalPath') -Fallback '')
      if (-not [string]::IsNullOrWhiteSpace($alt) -and (Test-Path -LiteralPath $alt)) { $src = $alt }
    }
    if (-not (Test-Path -LiteralPath $src)) { return $null }
    $backupRoot = Ensure-BackupRootForApply
    $scope = [string]$it.Scope
    if (-not $scopeRoots.ContainsKey($scope)) { return $null }
    $root  = $scopeRoots[$scope].TrimEnd('\')
    $rel = $src
    if ($src.StartsWith($root, [StringComparison]::OrdinalIgnoreCase)) {
      $rel = $src.Substring($root.Length).TrimStart('\')
    } else {
      $rel = Join-Path "Misc" ([IO.Path]::GetFileName($src))
    }
    $dst = Join-Path (Join-Path $backupRoot $scope) $rel
    $dstDir = Split-Path -Path $dst -Parent
    New-Item -ItemType Directory -Path $dstDir -Force | Out-Null
    $isDir = $false
    try { $isDir = (Test-Path -LiteralPath $src -PathType Container) } catch { $isDir = $false }
    if ($isDir) {
      Copy-Item -LiteralPath $src -Destination $dst -Force -Recurse -ErrorAction Stop
    } else {
      Copy-Item -LiteralPath $src -Destination $dst -Force -ErrorAction Stop
    }
    return $dst
  }
    function Set-PropSafe {
    param(
      [Parameter(Mandatory=$true)][object]$Obj,
      [Parameter(Mandatory=$true)][string]$Name,
      $Value
    )
    if (-not $Obj) { return }
    if ($Obj.PSObject.Properties.Match($Name).Count -eq 0) {
      Add-Member -InputObject $Obj -NotePropertyName $Name -NotePropertyValue $Value -Force
    } else {
      try { $Obj.$Name = $Value } catch { }
    }
  }
  foreach ($it in $Renames) {
    try {
      $src = [string](Get-PropString -Obj $it -Names @('OriginalPath','Path') -Fallback '')
      if (-not [string]::IsNullOrWhiteSpace($src) -and -not (Test-Path -LiteralPath $src)) {
        $alt = [string](Get-PropString -Obj $it -Names @('Path','OriginalPath') -Fallback '')
        if (-not [string]::IsNullOrWhiteSpace($alt) -and (Test-Path -LiteralPath $alt)) { $src = $alt }
      }
      if (-not (Test-Path -LiteralPath $src)) { throw ("Source not found for rename: " + [string](Get-PropString -Obj $it -Names @('OriginalPath','Path') -Fallback '<empty>')) }
      $dir = Split-Path -Path $src -Parent
      $ext = [IO.Path]::GetExtension($src)
      $pendingPath = Normalize-Path ([string](Get-PropString -Obj $it -Names @('Path') -Fallback ''))
      $pendingPathIsDifferent = $false
      if (-not [string]::IsNullOrWhiteSpace($pendingPath)) {
        $pendingPathIsDifferent = (-not (Test-PathEqualsCI -A $pendingPath -B $src))
      }
      $newBase = (Trim-NameInputPreserveNbsp -Text ([string]$it.Name))
      if ($newBase.ToLower().EndsWith($ext.ToLower())) {
        $newBase = (Trim-NameInputPreserveNbsp -Text $newBase.Substring(0, $newBase.Length - $ext.Length))
      }
      if (-not (Test-ValidFileName -Name $newBase)) { throw "Invalid file name: '$newBase'" }
      $targetDir = $dir
      if ($pendingPathIsDifferent) {
        $tmpDir = Split-Path -Path $pendingPath -Parent
        if (-not [string]::IsNullOrWhiteSpace($tmpDir)) { $targetDir = $tmpDir }
      }
      if (-not [string]::IsNullOrWhiteSpace($targetDir) -and -not (Test-Path -LiteralPath $targetDir -PathType Container)) {
        throw ("Target directory not found: " + [string]$targetDir)
      }
      $dst = Join-Path $targetDir ($newBase + $ext)
      if ($src -ne $dst -and (Test-Path -LiteralPath $dst)) { throw "Target already exists: $dst" }
      [void](Backup-One -it $it)
      Move-Item -LiteralPath $src -Destination $dst -Force -ErrorAction Stop
      try { [void](Ensure-EdgeIconOnShortcut -LnkPath $dst -Row $it) } catch {}
      # Count the rename as soon as the filesystem operation succeeds
      $renamed++
      # Update the row state safely (do NOT fail the whole rename if UI props differ)
      Set-PropSafe -Obj $it -Name 'OriginalPath' -Value $dst
      Set-PropSafe -Obj $it -Name 'Path'         -Value $dst
      Set-PropSafe -Obj $it -Name 'OriginalName' -Value ([string]$it.Name)
      Set-PropSafe -Obj $it -Name 'Action'       -Value 'None'
      Set-PropSafe -Obj $it -Name 'PendingLabel' -Value ''
      Set-PropSafe -Obj $it -Name 'PendingLabelRows' -Value @()
      Set-PropSafe -Obj $it -Name 'Pending'      -Value ''
      Set-PropSafe -Obj $it -Name 'PendingText'  -Value ''
    } catch {
      [void]$errors.Add(("RENAME :: {0} :: {1}" -f ([string]$it.OriginalPath), $_.Exception.Message))
    }
  }
  foreach ($it in $Deletes) {
    try {
      $src = [string](Get-PropString -Obj $it -Names @('OriginalPath','Path') -Fallback '')
      if (-not [string]::IsNullOrWhiteSpace($src) -and -not (Test-Path -LiteralPath $src)) {
        $alt = [string](Get-PropString -Obj $it -Names @('Path','OriginalPath') -Fallback '')
        if (-not [string]::IsNullOrWhiteSpace($alt) -and (Test-Path -LiteralPath $alt)) { $src = $alt }
      }
      if (-not (Test-Path -LiteralPath $src)) { throw ("Source not found for delete: " + [string](Get-PropString -Obj $it -Names @('OriginalPath','Path') -Fallback '<empty>')) }
      if (Test-IsProtectedAdministrativeToolsPath -PathText $src) {
        throw ("Refusing to delete protected Administrative Tools path: " + [string]$src)
      }
      $scope = [string]$it.Scope
      $root  = $null
      if ($scopeRoots.ContainsKey($scope)) { $root = [string]$scopeRoots[$scope] }
      $rootN = if ($root) { ([string]$root).TrimEnd('\') } else { '' }
      # Safety: only delete things under the Start Menu roots, never the roots themselves.
      if (-not [string]::IsNullOrWhiteSpace($rootN)) {
        $srcN = ([string]$src).TrimEnd('\')
        if ($srcN.Equals($rootN, [StringComparison]::OrdinalIgnoreCase)) {
          throw ("Refusing to delete scope root: " + $srcN)
        }
        if (-not $srcN.StartsWith($rootN + '\', [StringComparison]::OrdinalIgnoreCase)) {
          throw ("Refusing to delete path outside scope root: " + $srcN)
        }
      }
      $isDir = $false
      try { $isDir = (Test-Path -LiteralPath $src -PathType Container) } catch { $isDir = $false }
      [void](Backup-One -it $it)
      if ($isDir) {
        Remove-Item -LiteralPath $src -Recurse -Force -ErrorAction Stop
      } else {
        Remove-Item -LiteralPath $src -Force -ErrorAction Stop
      }
      $deleted++
      Set-PropSafe -Obj $it -Name 'Action'       -Value 'None'
      Set-PropSafe -Obj $it -Name 'PendingLabel' -Value ''
      Set-PropSafe -Obj $it -Name 'PendingLabelRows' -Value @()
      Set-PropSafe -Obj $it -Name 'Pending'      -Value ''
      Set-PropSafe -Obj $it -Name 'PendingText'  -Value ''
      Set-PropSafe -Obj $it -Name 'Selected'     -Value $false
    } catch {
      [void]$errors.Add(("DELETE :: {0} :: {1}" -f ([string]$it.OriginalPath), $_.Exception.Message))
    }
  }
  foreach ($it in @($IconChanges)) {
    try {
      if (-not $it) { continue }
      $pendingIconPath = Normalize-Path ([string](Get-PropString -Obj $it -Names @('PendingIconPath') -Fallback ''))
      if ([string]::IsNullOrWhiteSpace($pendingIconPath)) { continue }
      $pendingIconIndex = 0
      try { $pendingIconIndex = [int](Get-PropString -Obj $it -Names @('PendingIconIndex') -Fallback '0') } catch { $pendingIconIndex = 0 }
      if (-not (Test-Path -LiteralPath $pendingIconPath -PathType Leaf)) {
        throw ("Icon source not found: " + [string]$pendingIconPath)
      }
      $lnkPath = Resolve-ExistingShortcutPathForRow -Row $it
      if ([string]::IsNullOrWhiteSpace($lnkPath)) {
        throw ("Shortcut path not found for icon change: " + [string](Get-PropString -Obj $it -Names @('OriginalPath','Path') -Fallback '<empty>'))
      }
      if (-not $lnkPath.EndsWith('.lnk', [System.StringComparison]::OrdinalIgnoreCase)) {
        throw ("Icon change currently supports .lnk shortcuts only: " + [string]$lnkPath)
      }
      [void](Backup-One -it $it)
      $ws = New-Object -ComObject WScript.Shell
      $sc = $ws.CreateShortcut($lnkPath)
      $sc.IconLocation = ("{0},{1}" -f [string]$pendingIconPath, [int]$pendingIconIndex)
      $sc.Save()
      $img = $null
      try {
        $fb = [string](Get-PropString -Obj $it -Names @('Target') -Fallback '')
        $img = Get-ImageSourceFromIcon -IconPath $lnkPath -IconIndex 0 -FallbackExePath $fb
        if (-not $img) {
          try { $img = Get-ImageSourceFromShellParsingName -ParsingName $lnkPath } catch {}
        }
      } catch { $img = $null }
      if ($img) { Set-PropSafe -Obj $it -Name 'Icon' -Value $img }
      Set-PropSafe -Obj $it -Name 'PendingIconPath' -Value ''
      Set-PropSafe -Obj $it -Name 'PendingIconIndex' -Value 0
      try { Set-PendingState -it $it } catch {}
      $iconChanged++
    } catch {
      [void]$errors.Add(("ICON :: {0} :: {1}" -f ([string](Get-PropString -Obj $it -Names @('OriginalPath','Path') -Fallback '<empty>')), $_.Exception.Message))
    }
  }
  foreach ($it in @($TargetChanges)) {
    try {
      if (-not $it) { continue }
      $pendingTargetPath = Normalize-Path ([string](Get-PropString -Obj $it -Names @('PendingTargetPath') -Fallback ''))
      if ([string]::IsNullOrWhiteSpace($pendingTargetPath) -or -not (Test-Path -LiteralPath $pendingTargetPath)) { continue }
      $lnkPath = Resolve-ExistingShortcutPathForRow -Row $it
      if ([string]::IsNullOrWhiteSpace($lnkPath)) {
        throw ("Shortcut path not found for target change: " + [string](Get-PropString -Obj $it -Names @('OriginalPath','Path') -Fallback '<empty>'))
      }
      if (-not $lnkPath.EndsWith('.lnk', [System.StringComparison]::OrdinalIgnoreCase)) {
        throw ("Target change currently supports .lnk shortcuts only: " + [string]$lnkPath)
      }
      [void](Backup-One -it $it)
      $ws = New-Object -ComObject WScript.Shell
      $sc = $ws.CreateShortcut($lnkPath)
      $sc.TargetPath = [string]$pendingTargetPath
      $sc.Save()
      try { Set-PropSafe -Obj $it -Name 'Target' -Value ([string]$pendingTargetPath) } catch {}
      try { Set-PropSafe -Obj $it -Name 'PendingTargetPath' -Value '' } catch {}
      try { Set-PendingState -it $it } catch {}
      $targetChanged++
    } catch {
      [void]$errors.Add(("TARGET :: {0} :: {1}" -f ([string](Get-PropString -Obj $it -Names @('OriginalPath','Path') -Fallback '<empty>')), $_.Exception.Message))
    }
  }
  [pscustomobject]@{
    BackupRoot = $backupRoot
    Deleted    = $deleted
    Renamed    = $renamed
    IconChanged= $iconChanged
    TargetChanged = $targetChanged
    Errors     = $errors.ToArray()
  }
}

function Copy-FolderTreeRecursive {
  param(
    [Parameter(Mandatory=$true)][string]$Source,
    [Parameter(Mandatory=$true)][string]$Destination
  )
  if (-not (Test-Path -LiteralPath $Source -PathType Container)) { return }
  if (-not (Test-Path -LiteralPath $Destination)) {
    New-Item -ItemType Directory -Path $Destination -Force | Out-Null
  }
  foreach ($child in @(Get-ChildItem -LiteralPath $Source -Force -ErrorAction SilentlyContinue)) {
    if (-not $child) { continue }
    $dst = Join-Path $Destination $child.Name
    if ($child.PSIsContainer) {
      Copy-FolderTreeRecursive -Source ([string]$child.FullName) -Destination $dst
    } else {
      Copy-Item -LiteralPath ([string]$child.FullName) -Destination $dst -Force -ErrorAction Stop
    }
  }
}

function Invoke-PrepareStartMenu {
  param(
    [string]$BackupRoot = $null
  )
  $processed = @()
  $skipped   = @()
  $errors    = @()
  $allUsersRoot = [string]$scopeRoots['AllUsers']
  $currentUserRoot = [string]$scopeRoots['CurrentUser']
  if ([string]::IsNullOrWhiteSpace($allUsersRoot) -or -not (Test-Path -LiteralPath $allUsersRoot -PathType Container)) {
    throw "All Users Start Menu root is missing or inaccessible."
  }
  $mappings = @(
    @{ Target = 'Windows Accessories';          Family = @('windows accessories','accessories') },
    @{ Target = 'Windows Ease of Access';       Family = @('windows ease of access','accessibility') },
    @{ Target = 'Windows PowerShell';           Family = @('windows powershell') },
    @{ Target = 'Windows System';               Family = @('windows system','system tools') }
  )
  foreach ($m in $mappings) {
    $targetName = [string]$m.Target
    $familyKeys = @($m.Family)
    if ([string]::IsNullOrWhiteSpace($targetName) -or $familyKeys.Count -eq 0) { continue }
    $dest = Join-Path $allUsersRoot $targetName
    try {
      if (-not (Test-Path -LiteralPath $dest -PathType Container)) {
        if (Test-Path -LiteralPath $dest) {
          $errors += ("Destination exists but is not a folder: " + $dest)
          continue
        }
        New-Item -ItemType Directory -Path $dest -Force | Out-Null
      }
    } catch {
      $errors += ("Failed to create destination folder: " + $dest + " :: " + [string]$_.Exception.Message)
      continue
    }
    $sources = @()
    foreach ($scope in @('AllUsers','CurrentUser')) {
      $root = if ($scope -eq 'AllUsers') { $allUsersRoot } else { $currentUserRoot }
      if ([string]::IsNullOrWhiteSpace($root) -or -not (Test-Path -LiteralPath $root -PathType Container)) { continue }
      foreach ($d in @(Get-ChildItem -LiteralPath $root -Directory -Force -ErrorAction SilentlyContinue)) {
        if (-not $d) { continue }
        if (-not (Test-VisualNameInFamily -Name ([string]$d.Name) -FamilyKeys $familyKeys)) { continue }
        $sources += [pscustomobject]@{
          Scope = $scope
          Path  = [string]$d.FullName
          Name  = [string]$d.Name
        }
      }
    }
    if (-not $sources -or $sources.Count -eq 0) {
      $skipped += ("No source folders found for: " + $targetName)
      continue
    }
    $sourceSeen = @{}
    $uniqueSources = @()
    foreach ($s in @($sources)) {
      if (-not $s) { continue }
      $sp = [string]$s.Path
      if ([string]::IsNullOrWhiteSpace($sp)) { continue }
      $k = ($sp.TrimEnd('\').ToLowerInvariant())
      if ($sourceSeen.ContainsKey($k)) { continue }
      $sourceSeen[$k] = $true
      $uniqueSources += $s
    }
    $ordered = @($uniqueSources | Sort-Object @{ Expression = { if ([string]$_.Scope -eq 'AllUsers') { 0 } else { 1 } } }, @{ Expression = { [string]$_.Path } })
    foreach ($src in @($ordered)) {
      if (-not $src) { continue }
      $srcPath = [string]$src.Path
      if ([string]::IsNullOrWhiteSpace($srcPath)) { continue }
      if (Test-PathEqualsCI -A $srcPath -B $dest) { continue }
      if (-not (Test-Path -LiteralPath $srcPath -PathType Container)) { continue }
      try {
        Copy-FolderTreeRecursive -Source $srcPath -Destination $dest
        $processed += [pscustomobject]@{
          Scope       = [string]$src.Scope
          Source      = $srcPath
          Destination = $dest
          Mode        = 'MergedToAllUsers'
        }
      } catch {
        $errors += ([string]$src.Scope + " :: merge failed :: " + $srcPath + " -> " + $dest + " :: " + [string]$_.Exception.Message)
      }
    }
    foreach ($src in @($uniqueSources)) {
      if (-not $src) { continue }
      $srcPath = [string]$src.Path
      if ([string]::IsNullOrWhiteSpace($srcPath)) { continue }
      if (Test-PathEqualsCI -A $srcPath -B $dest) { continue }
      if (-not (Test-Path -LiteralPath $srcPath -PathType Container)) { continue }
      try {
        Remove-Item -LiteralPath $srcPath -Recurse -Force -ErrorAction Stop
        $processed += [pscustomobject]@{
          Scope       = [string]$src.Scope
          Source      = $srcPath
          Destination = $dest
          Mode        = 'RemovedOriginal'
        }
      } catch {
        $errors += ([string]$src.Scope + " :: remove failed :: " + $srcPath + " :: " + [string]$_.Exception.Message)
      }
    }
  }
  try { Invoke-StartMenuRefresh -TouchedFolder $allUsersRoot } catch {}
  try { if (-not [string]::IsNullOrWhiteSpace($currentUserRoot)) { Invoke-StartMenuRefresh -TouchedFolder $currentUserRoot } } catch {}
  try { Stop-Process -Name StartMenuExperienceHost -Force -ErrorAction SilentlyContinue } catch {}
  return [pscustomobject]@{
    Processed  = @($processed)
    Skipped    = @($skipped)
    Errors     = @($errors)
    BackupRoot = $BackupRoot
  }
}

function Test-IsFullSnapshotRestoreManifest {
  param(
    [object]$Manifest,
    [object[]]$PlanEntries = @()
  )
  try {
    if ($Manifest -and $Manifest.PSObject.Properties.Match('FullSnapshot').Count -gt 0) {
      return [bool]$Manifest.FullSnapshot
    }
  } catch {}
  return $false
}

function Get-FullSnapshotExpectedState {
  param(
    [Parameter(Mandatory=$true)][object]$Manifest,
    [object[]]$PlanEntries = @()
  )
  $expectedFiles = @{}
  $expectedFolders = @{}
  $isFull = Test-IsFullSnapshotRestoreManifest -Manifest $Manifest -PlanEntries $PlanEntries
  function Add-ExpectedFolderPath {
    param([string]$Scope, [string]$FolderPath)
    if ([string]::IsNullOrWhiteSpace($Scope) -or [string]::IsNullOrWhiteSpace($FolderPath)) { return }
    if (-not $scopeRoots.ContainsKey($Scope)) { return }
    $rootN = ([string]$scopeRoots[$Scope]).TrimEnd('\')
    if ([string]::IsNullOrWhiteSpace($rootN)) { return }
    $cur = Normalize-Path $FolderPath
    if ([string]::IsNullOrWhiteSpace($cur)) { return }
    if (-not $cur.StartsWith($rootN + '\', [StringComparison]::OrdinalIgnoreCase)) { return }
    while ($true) {
      $n = ([string]$cur).TrimEnd('\')
      if ([string]::IsNullOrWhiteSpace($n)) { break }
      $k = ("{0}|{1}" -f $Scope, $n.ToLowerInvariant())
      if (-not $expectedFolders.ContainsKey($k)) {
        $expectedFolders[$k] = [pscustomobject]@{ Scope = $Scope; Path = $n }
      }
      if ($n.Equals($rootN, [StringComparison]::OrdinalIgnoreCase)) { break }
      $parent = Split-Path -Path $n -Parent
      if ([string]::IsNullOrWhiteSpace($parent)) { break }
      if ($parent.Equals($n, [StringComparison]::OrdinalIgnoreCase)) { break }
      $cur = $parent
    }
  }
  if ($isFull) {
    foreach ($it in @($Manifest.Items)) {
      try {
        if (-not $it) { continue }
        $scope = [string]$it.Scope
        $dst = Resolve-ManifestRestoreDestinationPath -Scope $scope -RelativePath ([string]$it.RelativePath) -OriginalPath ([string]$it.OriginalPath)
        if ([string]::IsNullOrWhiteSpace($scope) -or [string]::IsNullOrWhiteSpace($dst)) { continue }
        if (-not $scopeRoots.ContainsKey($scope)) { continue }
        $rootN = ([string]$scopeRoots[$scope]).TrimEnd('\')
        if ($dst.Equals($rootN, [StringComparison]::OrdinalIgnoreCase)) { continue }
        if (-not $dst.StartsWith($rootN + '\', [StringComparison]::OrdinalIgnoreCase)) { continue }
        $fk = ("{0}|{1}" -f $scope, $dst.ToLowerInvariant())
        $expectedFiles[$fk] = [pscustomobject]@{ Scope = $scope; Path = $dst }
        Add-ExpectedFolderPath -Scope $scope -FolderPath (Split-Path -Path $dst -Parent)
      } catch {}
    }
    foreach ($fd in @($Manifest.Folders)) {
      try {
        if (-not $fd) { continue }
        $scope = [string]$fd.Scope
        if (-not $scopeRoots.ContainsKey($scope)) { continue }
        $fp = Normalize-Path ([string]$fd.OriginalPath)
        if ([string]::IsNullOrWhiteSpace($fp)) {
          $relRaw = [string]$fd.RelativePath
          $rel = Convert-RelativePathFromBackupStorage -RelativePath $relRaw
          if (-not [string]::IsNullOrWhiteSpace($rel)) {
            $fp = Normalize-Path (Join-Path ([string]$scopeRoots[$scope]) $rel)
          }
        }
        Add-ExpectedFolderPath -Scope $scope -FolderPath $fp
      } catch {}
    }
  }
  return [pscustomobject]@{
    IsFullSnapshot = [bool]$isFull
    ExpectedFiles  = $expectedFiles
    ExpectedFolders= $expectedFolders
  }
}

function Backup-PathForRestoreRemoval {
  param(
    [Parameter(Mandatory=$true)][string]$Path,
    [Parameter(Mandatory=$true)][string]$Scope,
    [Parameter(Mandatory=$true)][string]$ScopeRoot,
    [Parameter(Mandatory=$true)][string]$PreRoot,
    [Parameter(Mandatory=$true)][string]$Bucket,
    [ref]$PreCopied,
    [System.Collections.Generic.List[string]]$Errors
  )
  try {
    $src = Normalize-Path $Path
    if ([string]::IsNullOrWhiteSpace($src) -or -not (Test-Path -LiteralPath $src)) { return }
    $rootN = ([string]$ScopeRoot).TrimEnd('\')
    $srcN = ([string]$src).TrimEnd('\')
    if (-not $srcN.StartsWith($rootN + '\', [StringComparison]::OrdinalIgnoreCase)) { return }
    $rel = $srcN.Substring($rootN.Length).TrimStart('\')
    if ([string]::IsNullOrWhiteSpace($rel)) { $rel = [IO.Path]::GetFileName($srcN) }
    $prePath = Join-Path (Join-Path (Join-Path $PreRoot $Scope) $Bucket) $rel
    $preDir = Split-Path -Path $prePath -Parent
    if (-not (Test-Path -LiteralPath $preDir)) { New-Item -ItemType Directory -Path $preDir -Force | Out-Null }
    $isDir = $false
    try { $isDir = (Test-Path -LiteralPath $src -PathType Container) } catch { $isDir = $false }
    if ($isDir) {
      if (Test-Path -LiteralPath $prePath) { try { Remove-Item -LiteralPath $prePath -Recurse -Force -ErrorAction SilentlyContinue } catch {} }
      Copy-Item -LiteralPath $src -Destination $prePath -Recurse -Force -ErrorAction Stop
    } else {
      Copy-Item -LiteralPath $src -Destination $prePath -Force -ErrorAction Stop
    }
    if ($PreCopied) { $PreCopied.Value = [int]$PreCopied.Value + 1 }
  } catch {
    if ($Errors) { [void]$Errors.Add(("PRECOPY REMOVE :: {0} :: {1}" -f [string]$Path, $_.Exception.Message)) }
  }
}

function Reconcile-FullSnapshotBeforeRestore {
  param(
    [Parameter(Mandatory=$true)][hashtable]$ExpectedFiles,
    [Parameter(Mandatory=$true)][hashtable]$ExpectedFolders,
    [Parameter(Mandatory=$true)][string]$PreRoot,
    [ref]$Removed,
    [ref]$PreCopied,
    [System.Collections.Generic.List[string]]$Errors
  )
  foreach ($kv in $scopeRoots.GetEnumerator()) {
    $scope = [string]$kv.Key
    $rootN = ([string]$kv.Value).TrimEnd('\')
    if ([string]::IsNullOrWhiteSpace($rootN) -or -not (Test-Path -LiteralPath $rootN -PathType Container)) { continue }
    $files = @()
    try {
      $files = @(Get-ChildItem -LiteralPath $rootN -File -Recurse -Force -ErrorAction SilentlyContinue)
    } catch { $files = @() }
    foreach ($f in @($files)) {
      try {
        if (-not $f) { continue }
        $fp = Normalize-Path ([string]$f.FullName)
        if ([string]::IsNullOrWhiteSpace($fp)) { continue }
        if (Test-IsProtectedAdministrativeToolsPath -PathText $fp) { continue }
        $k = ("{0}|{1}" -f $scope, $fp.ToLowerInvariant())
        if ($ExpectedFiles.ContainsKey($k)) { continue }
        Backup-PathForRestoreRemoval -Path $fp -Scope $scope -ScopeRoot $rootN -PreRoot $PreRoot -Bucket '__removed_files' -PreCopied $PreCopied -Errors $Errors
        if (Test-Path -LiteralPath $fp) {
          Remove-Item -LiteralPath $fp -Force -ErrorAction Stop
          if ($Removed) { $Removed.Value = [int]$Removed.Value + 1 }
        }
      } catch {
        if ($Errors) { [void]$Errors.Add(("REMOVE EXTRA FILE :: {0}" -f $_.Exception.Message)) }
      }
    }
    $dirs = @()
    try {
      $dirs = @(Get-ChildItem -LiteralPath $rootN -Directory -Recurse -Force -ErrorAction SilentlyContinue |
        Sort-Object { $_.FullName.Length } -Descending)
    } catch { $dirs = @() }
    foreach ($d in @($dirs)) {
      try {
        if (-not $d) { continue }
        $dp = Normalize-Path ([string]$d.FullName)
        if ([string]::IsNullOrWhiteSpace($dp)) { continue }
        $dn = ([string]$dp).TrimEnd('\')
        if (Test-IsProtectedAdministrativeToolsPath -PathText $dn) { continue }
        if ($dn.Equals($rootN, [StringComparison]::OrdinalIgnoreCase)) { continue }
        $k = ("{0}|{1}" -f $scope, $dn.ToLowerInvariant())
        if ($ExpectedFolders.ContainsKey($k)) { continue }
        Backup-PathForRestoreRemoval -Path $dn -Scope $scope -ScopeRoot $rootN -PreRoot $PreRoot -Bucket '__removed_dirs' -PreCopied $PreCopied -Errors $Errors
        if (Test-Path -LiteralPath $dn) {
          Remove-Item -LiteralPath $dn -Recurse -Force -ErrorAction Stop
          if ($Removed) { $Removed.Value = [int]$Removed.Value + 1 }
        }
      } catch {
        if ($Errors) { [void]$Errors.Add(("REMOVE EXTRA DIR :: {0}" -f $_.Exception.Message)) }
      }
    }
  }
}

function Ensure-FullSnapshotFoldersAfterRestore {
  param(
    [Parameter(Mandatory=$true)][hashtable]$ExpectedFolders,
    [ref]$Restored,
    [System.Collections.Generic.List[string]]$Errors
  )
  $ordered = @()
  try {
    $ordered = @($ExpectedFolders.Values | Sort-Object { ([string]$_.Path).Length })
  } catch { $ordered = @($ExpectedFolders.Values) }
  foreach ($fd in @($ordered)) {
    try {
      if (-not $fd) { continue }
      $path = Normalize-Path ([string]$fd.Path)
      if ([string]::IsNullOrWhiteSpace($path)) { continue }
      if (-not (Test-Path -LiteralPath $path -PathType Container)) {
        New-Item -ItemType Directory -Path $path -Force | Out-Null
        if ($Restored) { $Restored.Value = [int]$Restored.Value + 1 }
      }
    } catch {
      if ($Errors) { [void]$Errors.Add(("RESTORE FOLDER :: {0}" -f $_.Exception.Message)) }
    }
  }
}

function Get-ManifestFolderMap {
  param([object]$Manifest)
  $map = @{}
  if (-not $Manifest) { return $map }
  function Add-Path {
    param([string]$Scope, [string]$FolderPath)
    if ([string]::IsNullOrWhiteSpace($Scope) -or [string]::IsNullOrWhiteSpace($FolderPath)) { return }
    if (-not $scopeRoots.ContainsKey($Scope)) { return }
    $rootN = ([string]$scopeRoots[$Scope]).TrimEnd('\')
    if ([string]::IsNullOrWhiteSpace($rootN)) { return }
    $cur = Normalize-Path $FolderPath
    if ([string]::IsNullOrWhiteSpace($cur)) { return }
    if (-not $cur.StartsWith($rootN + '\', [StringComparison]::OrdinalIgnoreCase)) { return }
    while ($true) {
      $n = ([string]$cur).TrimEnd('\')
      if ([string]::IsNullOrWhiteSpace($n)) { break }
      if (-not $n.StartsWith($rootN + '\', [StringComparison]::OrdinalIgnoreCase)) { break }
      $k = ("{0}|{1}" -f $Scope, $n.ToLowerInvariant())
      if (-not $map.ContainsKey($k)) { $map[$k] = [pscustomobject]@{ Scope = $Scope; Path = $n } }
      $parent = Split-Path -Path $n -Parent
      if ([string]::IsNullOrWhiteSpace($parent) -or $parent.Equals($n, [StringComparison]::OrdinalIgnoreCase)) { break }
      if ($parent.Equals($rootN, [StringComparison]::OrdinalIgnoreCase)) { break }
      $cur = $parent
    }
  }
  try {
    if ($Manifest.PSObject.Properties.Match('Folders').Count -eq 0) { return $map }
    foreach ($fd in @($Manifest.Folders)) {
      if (-not $fd) { continue }
      $scope = [string]$fd.Scope
      if ([string]::IsNullOrWhiteSpace($scope) -or -not $scopeRoots.ContainsKey($scope)) { continue }
      $fp = Normalize-Path ([string]$fd.OriginalPath)
      if ([string]::IsNullOrWhiteSpace($fp)) {
        $relRaw = [string]$fd.RelativePath
        $rel = Convert-RelativePathFromBackupStorage -RelativePath $relRaw
        if (-not [string]::IsNullOrWhiteSpace($rel)) {
          $fp = Normalize-Path (Join-Path ([string]$scopeRoots[$scope]) $rel)
        }
      }
      Add-Path -Scope $scope -FolderPath $fp
    }
  } catch {}
  return $map
}

function Invoke-PlanTargetCleanupBeforeRestore {
  param(
    [object[]]$PlanEntries = @(),
    [Parameter(Mandatory=$true)][string]$PreRoot,
    [ref]$Removed,
    [ref]$PreCopied,
    [System.Collections.Generic.List[string]]$Errors
  )
  foreach ($pe in @($PlanEntries)) {
    try {
      if (-not $pe) { continue }
      $act = ''
      try { $act = [string]$pe.Action } catch { $act = '' }
      if ($act -notin @('Rename','Move','Create')) { continue }
      $scope = [string]$pe.Scope
      if ([string]::IsNullOrWhiteSpace($scope) -or -not $scopeRoots.ContainsKey($scope)) { continue }
      $rootN = ([string]$scopeRoots[$scope]).TrimEnd('\')
      if ([string]::IsNullOrWhiteSpace($rootN)) { continue }
      $orig = Normalize-Path ([string]$pe.OriginalPath)
      $targetPath = Normalize-Path ([string]$pe.NewPath)
      if ([string]::IsNullOrWhiteSpace($targetPath)) {
        if ($act -eq 'Create') {
          $targetPath = $orig
        } else {
          $newNm = [string]$pe.NewName
          if (-not [string]::IsNullOrWhiteSpace($orig) -and -not [string]::IsNullOrWhiteSpace($newNm)) {
            $dir = Split-Path -Path $orig -Parent
            $ext = ''
            try { $ext = [string][IO.Path]::GetExtension($orig) } catch { $ext = '' }
            $newBase = (Trim-NameInputPreserveNbsp -Text ([string]$newNm))
            if (-not [string]::IsNullOrWhiteSpace($ext) -and $newBase.ToLower().EndsWith($ext.ToLower())) {
              $newBase = (Trim-NameInputPreserveNbsp -Text $newBase.Substring(0, $newBase.Length - $ext.Length))
            }
            $targetPath = Normalize-Path (Join-Path $dir ($newBase + $ext))
          }
        }
      }
      if ([string]::IsNullOrWhiteSpace($targetPath)) { continue }
      $targetN = ([string]$targetPath).TrimEnd('\')
      if (Test-IsProtectedAdministrativeToolsPath -PathText $targetN) { continue }
      if ($targetN.Equals($rootN, [StringComparison]::OrdinalIgnoreCase)) { continue }
      if (-not $targetN.StartsWith($rootN + '\', [StringComparison]::OrdinalIgnoreCase)) { continue }
      if (-not (Test-Path -LiteralPath $targetN)) { continue }
      Backup-PathForRestoreRemoval -Path $targetN -Scope $scope -ScopeRoot $rootN -PreRoot $PreRoot -Bucket '__plan_targets' -PreCopied $PreCopied -Errors $Errors
      $isDir = $false
      try { $isDir = (Test-Path -LiteralPath $targetN -PathType Container) } catch { $isDir = $false }
      if ($isDir) {
        Remove-Item -LiteralPath $targetN -Recurse -Force -ErrorAction Stop
      } else {
        Remove-Item -LiteralPath $targetN -Force -ErrorAction Stop
      }
      if ($Removed) { $Removed.Value = [int]$Removed.Value + 1 }
    } catch {
      if ($Errors) { [void]$Errors.Add(("PLAN REMOVE :: {0}" -f $_.Exception.Message)) }
    }
  }
}

# ==============================================================================
# Restore from backup (REPLACE behavior)
# - Supports:
#   A) Old style: <BackupRoot>\<Scope>\... direct copies
#   B) New style: <BackupRoot>\Snapshot\<Scope>\... + Manifest.json
# ==============================================================================
function Restore-FromBackupFolder {
  param([Parameter(Mandatory=$true)][string]$BackupRoot)
  $BackupRoot = Normalize-Path $BackupRoot
  if (-not $BackupRoot -or -not (Test-Path -LiteralPath $BackupRoot)) {
    throw "Backup folder not found: $BackupRoot"
  }
  # If user selected a scope folder or Snapshot, walk up
  $leaf = Split-Path -Path $BackupRoot -Leaf
  if ($leaf -in @("AllUsers","CurrentUser","DefaultProfile","Snapshot")) {
    $BackupRoot = Split-Path -Path $BackupRoot -Parent
  }
  $manifestPath = Join-Path $BackupRoot "Manifest.json"
  $useManifest  = Test-Path -LiteralPath $manifestPath
  # Pre-restore safety copy (only files we overwrite/remove)
  $preRoot = New-BackupFolder -Category Auto -Prefix "auto"
  $restored = 0
  $removed  = 0
  $preCopied = 0
  $errors   = New-Object System.Collections.Generic.List[string]
  if ($useManifest) {
    $raw = Get-Content -LiteralPath $manifestPath -Raw -ErrorAction Stop
    $m   = $raw | ConvertFrom-Json -ErrorAction Stop
    $conversionList = $null
    try {
      $convPath = Join-Path $BackupRoot 'Conversion List.json'
      if (Test-Path -LiteralPath $convPath -PathType Leaf) {
        $convRaw = Get-Content -LiteralPath $convPath -Raw -ErrorAction Stop
        $conversionList = $convRaw | ConvertFrom-Json -ErrorAction Stop
      }
    } catch {
      [void]$errors.Add(("CONVERSION LIST LOAD :: {0}" -f $_.Exception.Message))
    }
    $items = @($m.Items)
    $manifestItemCount = @($items).Count
    $planEntries = @()
    try {
      $planPath = Join-Path $BackupRoot "Plan.startmenu.json"
      if (Test-Path -LiteralPath $planPath) {
        $planRaw = Get-Content -LiteralPath $planPath -Raw -ErrorAction Stop
        $planObj = $planRaw | ConvertFrom-Json -ErrorAction Stop
        $planEntries = @($planObj.Entries)
      }
    } catch {
      [void]$errors.Add(("PLAN LOAD :: {0}" -f $_.Exception.Message))
    }
    $expectedState = Get-FullSnapshotExpectedState -Manifest $m -PlanEntries $planEntries
    $isFullSnapshotRestore = [bool]$expectedState.IsFullSnapshot
    if ($isFullSnapshotRestore) {
      try {
        Reconcile-FullSnapshotBeforeRestore `
          -ExpectedFiles $expectedState.ExpectedFiles `
          -ExpectedFolders $expectedState.ExpectedFolders `
          -PreRoot $preRoot `
          -Removed ([ref]$removed) `
          -PreCopied ([ref]$preCopied) `
          -Errors $errors
      } catch {
        [void]$errors.Add(("FULL SNAPSHOT RECONCILE :: {0}" -f $_.Exception.Message))
      }
    }
    # For plan-based backups (non-full snapshots), remove plan targets:
    # - Rename/Move destination targets
    # - Create targets
    try {
      if (-not $isFullSnapshotRestore) {
        Invoke-PlanTargetCleanupBeforeRestore `
          -PlanEntries $planEntries `
          -PreRoot $preRoot `
          -Removed ([ref]$removed) `
          -PreCopied ([ref]$preCopied) `
          -Errors $errors
      }
    } catch {
      [void]$errors.Add(("PLAN REMOVE :: {0}" -f $_.Exception.Message))
    }
    $manifestSnapshotRoot = Join-Path $BackupRoot 'Snapshot'
    foreach ($i in $items) {
      try {
        $scope = [string]$i.Scope
        $src   = Normalize-Path ([string]$i.SnapshotPath)
        $rel   = [string]$i.RelativePath
        $dst   = Resolve-ManifestRestoreDestinationPath -Scope $scope -RelativePath $rel -OriginalPath ([string]$i.OriginalPath)
        $dst   = Resolve-DestinationPathLenient -Path $dst -IsFilePath
        if (-not $scopeRoots.ContainsKey($scope)) { continue }
        if (-not $src -or -not (Test-Path -LiteralPath $src)) {
          $src = $null
          # Preferred for ZIP restores: reconstruct from Snapshot root + scope + relative path.
          if (-not [string]::IsNullOrWhiteSpace($rel)) {
            try {
              $cand = Join-Path (Join-Path $manifestSnapshotRoot $scope) $rel
              $cand = Normalize-Path $cand
              if (-not [string]::IsNullOrWhiteSpace($cand) -and (Test-Path -LiteralPath $cand)) { $src = $cand }
            } catch {}
          }
          # Secondary fallback for older layouts: <BackupRoot>\<Scope>\<RelativePath>
          if ((-not $src) -and (-not [string]::IsNullOrWhiteSpace($rel))) {
            try {
              $cand2 = Join-Path (Join-Path $BackupRoot $scope) $rel
              $cand2 = Normalize-Path $cand2
              if (-not [string]::IsNullOrWhiteSpace($cand2) -and (Test-Path -LiteralPath $cand2)) { $src = $cand2 }
            } catch {}
          }
          # Last chance: if manifest stored absolute SnapshotPath from original backup root,
          # remap the tail after "\Snapshot\" into the current extracted backup root.
          if (-not $src) {
            try {
              $rawSrc = [string]$i.SnapshotPath
              if (-not [string]::IsNullOrWhiteSpace($rawSrc)) {
                $idx = $rawSrc.IndexOf('\Snapshot\', [System.StringComparison]::OrdinalIgnoreCase)
                if ($idx -ge 0) {
                  $tail = $rawSrc.Substring($idx + 1) # "Snapshot\..."
                  $cand3 = Normalize-Path (Join-Path $BackupRoot $tail)
                  if (-not [string]::IsNullOrWhiteSpace($cand3) -and (Test-Path -LiteralPath $cand3)) { $src = $cand3 }
                }
              }
            } catch {}
          }
        }
        if (-not $src -or -not (Test-Path -LiteralPath $src)) { throw "Missing snapshot: $src" }
        if (-not $dst) { throw "Missing destination path" }
        $dstDir = Split-Path -Path $dst -Parent
        if (-not (Test-Path -LiteralPath $dstDir)) { New-Item -ItemType Directory -Path $dstDir -Force | Out-Null }
        # Pre-copy existing destination BEFORE restore/replace.
        if (Test-Path -LiteralPath $dst) {
          $preName = $null
          if (-not [string]::IsNullOrWhiteSpace($rel)) {
            $preName = $rel
          } else {
            $preName = [IO.Path]::GetFileName($dst)
          }
          $preFile = Join-Path (Join-Path $preRoot $scope) $preName
          $preDir  = Split-Path -Path $preFile -Parent
          New-Item -ItemType Directory -Path $preDir -Force | Out-Null
          Copy-Item -LiteralPath $dst -Destination $preFile -Force -ErrorAction Stop
          $preCopied++
        }
        # REPLACE logic in the destination folder
        $destFolder = Split-Path -Path $dst -Parent
        $tmp = Restore-ShortcutReplace -SnapshotLnkPath $src -DestFolder $destFolder
        if (-not $tmp) { throw "Restore-ShortcutReplace failed for $src" }
        # Ensure the restored file ends up at the exact original path (including original file name)
        if ([string]$tmp -ne [string]$dst) {
          Move-Item -LiteralPath $tmp -Destination $dst -Force -ErrorAction Stop
        }
        try {
          $dstExt = ''
          try { $dstExt = [string][IO.Path]::GetExtension($dst) } catch { $dstExt = '' }
          if ($dstExt -and $dstExt.Equals('.lnk', [StringComparison]::OrdinalIgnoreCase)) {
            $skipIconRelink = $false
            try { $skipIconRelink = (Test-SkipRestoreIconRelinkForExplorerShortcut -ShortcutPath $dst) } catch { $skipIconRelink = $false }
            if (-not $skipIconRelink) {
              $iconRel = [string](Get-PropString -Obj $i -Names @('IconBackupRelative') -Fallback '')
              $iconAppliedOk = $false
              if (-not [string]::IsNullOrWhiteSpace($iconRel)) {
                $iconApply = Install-RestoredShortcutIconForDestination -DestinationLnkPath $dst -BackupRoot $BackupRoot -IconBackupRelative $iconRel
                if ($iconApply -and [bool]$iconApply.Ok) {
                  $iconAppliedOk = $true
                } else {
                  $iconErr = ''
                  try { $iconErr = [string]$iconApply.Error } catch { $iconErr = '' }
                  if (-not [string]::IsNullOrWhiteSpace($iconErr)) {
                    [void]$errors.Add(("ICON RESTORE :: {0} :: {1}" -f $dst, $iconErr))
                  }
                }
              }
              if (-not $iconAppliedOk) {
                $tmpIco = $null
                try {
                  $tmpIco = Join-Path ([System.IO.Path]::GetTempPath()) ('SmltIconFallback_' + [guid]::NewGuid().ToString('N') + '.ico')
                  $expIco = Export-ShortcutIconToIcoFile -ShortcutPath $dst -DestinationIcoPath $tmpIco
                  if (-not [string]::IsNullOrWhiteSpace([string]$expIco) -and (Test-Path -LiteralPath $expIco -PathType Leaf)) {
                    $iconApply2 = Install-RestoredShortcutIconForDestination -DestinationLnkPath $dst -IconSourceFile $expIco -IconBackupRelative '__fallback__'
                    if (-not ($iconApply2 -and [bool]$iconApply2.Ok)) {
                      $iconErr2 = ''
                      try { $iconErr2 = [string]$iconApply2.Error } catch { $iconErr2 = '' }
                      if (-not [string]::IsNullOrWhiteSpace($iconErr2)) {
                        [void]$errors.Add(("ICON RESTORE FALLBACK :: {0} :: {1}" -f $dst, $iconErr2))
                      }
                    }
                  }
                } catch {}
                finally {
                  if (-not [string]::IsNullOrWhiteSpace([string]$tmpIco)) {
                    try { if (Test-Path -LiteralPath $tmpIco -PathType Leaf) { Remove-Item -LiteralPath $tmpIco -Force -ErrorAction SilentlyContinue } } catch {}
                  }
                }
              }
            }
          }
        } catch {}
        Invoke-StartMenuRefresh -TouchedFolder $destFolder
        $restored++
      } catch {
        [void]$errors.Add(("MANIFEST RESTORE :: {0}" -f $_.Exception.Message))
      }
    }
    if ($isFullSnapshotRestore) {
      try {
        Ensure-FullSnapshotFoldersAfterRestore `
          -ExpectedFolders $expectedState.ExpectedFolders `
          -Restored ([ref]$restored) `
          -Errors $errors
      } catch {
        [void]$errors.Add(("FULL SNAPSHOT FOLDERS :: {0}" -f $_.Exception.Message))
      }
    } else {
      try {
        $manifestFolders = Get-ManifestFolderMap -Manifest $m
        if ($manifestFolders.Count -gt 0) {
          Ensure-FullSnapshotFoldersAfterRestore `
            -ExpectedFolders $manifestFolders `
            -Restored ([ref]$restored) `
            -Errors $errors
        }
      } catch {
        [void]$errors.Add(("MANIFEST FOLDERS :: {0}" -f $_.Exception.Message))
      }
    }
    try {
      $renByConv = Invoke-RestoreRenameFromConversionList -ConversionList $conversionList -Errors $errors
      if ($renByConv -gt 0) {
        $restored += [int]$renByConv
        foreach ($kv in $scopeRoots.GetEnumerator()) {
          try {
            $rf = Normalize-Path ([string]$kv.Value)
            if (-not [string]::IsNullOrWhiteSpace($rf)) { Invoke-StartMenuRefresh -TouchedFolder $rf }
          } catch {}
        }
      }
    } catch {
      [void]$errors.Add(("CONVERSION LIST APPLY :: {0}" -f $_.Exception.Message))
    }
    if ($manifestItemCount -gt 0 -and ($restored -gt 0 -or $errors.Count -gt 0)) {
      try { [void](Sync-LegacyAdminToolsHideFlagFromFilesystem) } catch {}
      $preOut = Resolve-PreRestoreBackupPath -PreRestoreRoot $preRoot -Errors $errors
      return [pscustomobject]@{
        Restored   = $restored
        Removed    = $removed
        PreCopied  = $preCopied
        PreRestore = $preOut
        Errors     = $errors.ToArray()
      }
    }
  }
  # Fallback: old style scope folders at backup root
  foreach ($scope in @("AllUsers","CurrentUser","DefaultProfile")) {
    $srcScopeDir = Join-Path $BackupRoot $scope
    if (-not (Test-Path -LiteralPath $srcScopeDir)) { continue }
    if (-not $scopeRoots.ContainsKey($scope)) { continue }
    $dstRoot = $scopeRoots[$scope].TrimEnd('\')
    Get-ChildItem -LiteralPath $srcScopeDir -File -Recurse -Force -ErrorAction SilentlyContinue |
      Where-Object { $_.Extension -in @('.lnk','.url') } | ForEach-Object {
      $srcFile = $_.FullName
      $rel     = $srcFile.Substring($srcScopeDir.Length).TrimStart('\')
      $dstFile = Resolve-DestinationPathLenient -Path (Join-Path $dstRoot $rel) -IsFilePath
      if ([string]::IsNullOrWhiteSpace($dstFile)) { $dstFile = Join-Path $dstRoot $rel }
      try {
        $dstDir = Split-Path -Path $dstFile -Parent
        New-Item -ItemType Directory -Path $dstDir -Force | Out-Null
        # Pre-copy existing
        if (Test-Path -LiteralPath $dstFile) {
          $preFile = Join-Path (Join-Path $preRoot $scope) $rel
          $preDir  = Split-Path -Path $preFile -Parent
          New-Item -ItemType Directory -Path $preDir -Force | Out-Null
          Copy-Item -LiteralPath $dstFile -Destination $preFile -Force -ErrorAction Stop
          $preCopied++
        }
        # REPLACE logic (dest folder)
        $tmp = Restore-ShortcutReplace -SnapshotLnkPath $srcFile -DestFolder $dstDir
        if (-not $tmp) { throw "Restore-ShortcutReplace failed for $srcFile" }
        # Ensure exact original name/path
        if ([string]$tmp -ne [string]$dstFile) {
          if (Test-Path -LiteralPath $dstFile) {
            try { Remove-Item -LiteralPath $dstFile -Force -ErrorAction Stop; $removed++ } catch {}
          }
          Move-Item -LiteralPath $tmp -Destination $dstFile -Force -ErrorAction Stop
        }
        Invoke-StartMenuRefresh -TouchedFolder $dstDir
        $restored++
      } catch {
        [void]$errors.Add(("RESTORE :: {0} -> {1} :: {2}" -f $srcFile, $dstFile, $_.Exception.Message))
      }
    }
  }
  try { [void](Sync-LegacyAdminToolsHideFlagFromFilesystem) } catch {}
  $preOut = Resolve-PreRestoreBackupPath -PreRestoreRoot $preRoot -Errors $errors
  [pscustomobject]@{
    Restored   = $restored
    Removed    = $removed
    PreCopied  = $preCopied
    PreRestore = $preOut
    Errors     = $errors.ToArray()
  }
}

function Restore-FromBackupArchive {
  param([Parameter(Mandatory=$true)][string]$ArchivePath)
  $ArchivePath = Normalize-Path $ArchivePath
  if (-not $ArchivePath -or -not (Test-Path -LiteralPath $ArchivePath -PathType Leaf)) {
    throw "Backup archive not found: $ArchivePath"
  }
  if (-not (Ensure-ZipSupport)) {
    throw "ZIP support is unavailable."
  }
  function Normalize-ZipEntryPathLocal {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return '' }
    $p = [string]$Path
    $p = $p -replace '\\','/'
    while ($p.StartsWith('/')) { $p = $p.Substring(1) }
    return $p
  }
  function Get-ZipEntryKeyLocal {
    param([string]$Path)
    $p = Normalize-ZipEntryPathLocal $Path
    if ([string]::IsNullOrWhiteSpace($p)) { return '' }
    return $p.ToLowerInvariant()
  }
  function Read-ZipEntryTextLocal {
    param([Parameter(Mandatory=$true)][object]$Entry)
    $s = $null; $sr = $null
    try {
      $s = $Entry.Open()
      $sr = New-Object System.IO.StreamReader($s, [System.Text.Encoding]::UTF8, $true)
      return $sr.ReadToEnd()
    } finally {
      try { if ($sr) { $sr.Dispose() } } catch {}
      try { if ($s) { $s.Dispose() } } catch {}
    }
  }
  function Copy-ZipEntryToFileLocal {
    param(
      [Parameter(Mandatory=$true)][object]$Entry,
      [Parameter(Mandatory=$true)][string]$DestinationPath
    )
    $ds = $null; $ss = $null
    try {
      $dir = Split-Path -Path $DestinationPath -Parent
      if (-not [string]::IsNullOrWhiteSpace($dir) -and -not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
      }
      $ss = $Entry.Open()
      $ds = [System.IO.File]::Open($DestinationPath, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
      $ss.CopyTo($ds)
    } finally {
      try { if ($ds) { $ds.Dispose() } } catch {}
      try { if ($ss) { $ss.Dispose() } } catch {}
    }
  }
  $preRoot = New-BackupFolder -Category Auto -Prefix "auto"
  $restored = 0
  $removed = 0
  $preCopied = 0
  $errors = New-Object System.Collections.Generic.List[string]
  $tempEntryRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("StartMenuRestoreEntry_" + [guid]::NewGuid().ToString('N'))
  New-Item -ItemType Directory -Path $tempEntryRoot -Force | Out-Null
  $zipFs = $null
  $zip = $null
  try {
    $zipFs = [System.IO.File]::OpenRead($ArchivePath)
    $zip = New-Object System.IO.Compression.ZipArchive($zipFs, [System.IO.Compression.ZipArchiveMode]::Read, $false)
    $entryMap = @{}
    foreach ($ze in @($zip.Entries)) {
      if (-not $ze) { continue }
      $k = Get-ZipEntryKeyLocal ([string]$ze.FullName)
      if ([string]::IsNullOrWhiteSpace($k)) { continue }
      if (-not $entryMap.ContainsKey($k)) { $entryMap[$k] = $ze }
    }
    $manifestEntry = $null
    $manifestKey = Get-ZipEntryKeyLocal 'Manifest.json'
    if ($entryMap.ContainsKey($manifestKey)) { $manifestEntry = $entryMap[$manifestKey] }
    if ($manifestEntry) {
      $manifestText = Read-ZipEntryTextLocal -Entry $manifestEntry
      $m = $manifestText | ConvertFrom-Json -ErrorAction Stop
      $conversionList = $null
      try {
        $convEntry = $null
        $convKey = Get-ZipEntryKeyLocal 'Conversion List.json'
        if ($entryMap.ContainsKey($convKey)) { $convEntry = $entryMap[$convKey] }
        if ($convEntry) {
          $convText = Read-ZipEntryTextLocal -Entry $convEntry
          $conversionList = $convText | ConvertFrom-Json -ErrorAction Stop
        }
      } catch {
        [void]$errors.Add(("CONVERSION LIST LOAD :: {0}" -f $_.Exception.Message))
      }
      $items = @($m.Items)
      $manifestItemCount = @($items).Count
      $planEntries = @()
      try {
        $planEntry = $null
        $planKey = Get-ZipEntryKeyLocal 'Plan.startmenu.json'
        if ($entryMap.ContainsKey($planKey)) { $planEntry = $entryMap[$planKey] }
        if ($planEntry) {
          $planText = Read-ZipEntryTextLocal -Entry $planEntry
          $planObj = $planText | ConvertFrom-Json -ErrorAction Stop
          $planEntries = @($planObj.Entries)
        }
      } catch {
        [void]$errors.Add(("PLAN LOAD :: {0}" -f $_.Exception.Message))
      }
      $expectedState = Get-FullSnapshotExpectedState -Manifest $m -PlanEntries $planEntries
      $isFullSnapshotRestore = [bool]$expectedState.IsFullSnapshot
      if ($isFullSnapshotRestore) {
        try {
          Reconcile-FullSnapshotBeforeRestore `
            -ExpectedFiles $expectedState.ExpectedFiles `
            -ExpectedFolders $expectedState.ExpectedFolders `
            -PreRoot $preRoot `
            -Removed ([ref]$removed) `
            -PreCopied ([ref]$preCopied) `
            -Errors $errors
        } catch {
          [void]$errors.Add(("FULL SNAPSHOT RECONCILE :: {0}" -f $_.Exception.Message))
        }
      }
      # For plan-based backups (non-full snapshots), remove plan targets:
      # - Rename/Move destination targets
      # - Create targets
      try {
        if (-not $isFullSnapshotRestore) {
          Invoke-PlanTargetCleanupBeforeRestore `
            -PlanEntries $planEntries `
            -PreRoot $preRoot `
            -Removed ([ref]$removed) `
            -PreCopied ([ref]$preCopied) `
            -Errors $errors
        }
      } catch {
        [void]$errors.Add(("PLAN REMOVE :: {0}" -f $_.Exception.Message))
      }
      foreach ($i in $items) {
        $tempSnapshotFile = $null
        $tempIconFile = $null
        try {
          $scope = [string]$i.Scope
          $rel   = [string]$i.RelativePath
          $dst   = Resolve-ManifestRestoreDestinationPath -Scope $scope -RelativePath $rel -OriginalPath ([string]$i.OriginalPath)
          $dst   = Resolve-DestinationPathLenient -Path $dst -IsFilePath
          if (-not $scopeRoots.ContainsKey($scope)) { continue }
          if (-not $dst) { throw "Missing destination path" }
          $srcEntry = $null
          if (-not [string]::IsNullOrWhiteSpace($rel)) {
            $cand1 = Get-ZipEntryKeyLocal (Join-Path (Join-Path 'Snapshot' $scope) $rel)
            if ($entryMap.ContainsKey($cand1)) { $srcEntry = $entryMap[$cand1] }
          }
          if (-not $srcEntry -and -not [string]::IsNullOrWhiteSpace($rel)) {
            $cand2 = Get-ZipEntryKeyLocal (Join-Path $scope $rel)
            if ($entryMap.ContainsKey($cand2)) { $srcEntry = $entryMap[$cand2] }
          }
          if (-not $srcEntry) {
            $rawSrc = [string]$i.SnapshotPath
            if (-not [string]::IsNullOrWhiteSpace($rawSrc)) {
              $idx = $rawSrc.IndexOf('\Snapshot\', [System.StringComparison]::OrdinalIgnoreCase)
              if ($idx -ge 0) {
                $tail = $rawSrc.Substring($idx + 1) # Snapshot\...
                $cand3 = Get-ZipEntryKeyLocal $tail
                if ($entryMap.ContainsKey($cand3)) { $srcEntry = $entryMap[$cand3] }
              }
            }
          }
          if (-not $srcEntry) { throw "Missing snapshot entry" }
          $ext = ''
          try { $ext = [string][System.IO.Path]::GetExtension([string]$srcEntry.Name) } catch { $ext = '' }
          if ([string]::IsNullOrWhiteSpace($ext)) { $ext = '.lnk' }
          $tempSnapshotFile = Join-Path $tempEntryRoot (([guid]::NewGuid().ToString('N')) + $ext)
          Copy-ZipEntryToFileLocal -Entry $srcEntry -DestinationPath $tempSnapshotFile
          $dstDir = Split-Path -Path $dst -Parent
          if (-not (Test-Path -LiteralPath $dstDir)) { New-Item -ItemType Directory -Path $dstDir -Force | Out-Null }
          if (Test-Path -LiteralPath $dst) {
            $preName = if (-not [string]::IsNullOrWhiteSpace($rel)) { $rel } else { [IO.Path]::GetFileName($dst) }
            $preFile = Join-Path (Join-Path $preRoot $scope) $preName
            $preDir  = Split-Path -Path $preFile -Parent
            New-Item -ItemType Directory -Path $preDir -Force | Out-Null
            Copy-Item -LiteralPath $dst -Destination $preFile -Force -ErrorAction Stop
            $preCopied++
          }
          $destFolder = Split-Path -Path $dst -Parent
          $tmp = Restore-ShortcutReplace -SnapshotLnkPath $tempSnapshotFile -DestFolder $destFolder
          if (-not $tmp) { throw "Restore-ShortcutReplace failed" }
          if ([string]$tmp -ne [string]$dst) {
            Move-Item -LiteralPath $tmp -Destination $dst -Force -ErrorAction Stop
          }
          try {
            $dstExt = ''
            try { $dstExt = [string][IO.Path]::GetExtension($dst) } catch { $dstExt = '' }
            if ($dstExt -and $dstExt.Equals('.lnk', [StringComparison]::OrdinalIgnoreCase)) {
              $skipIconRelink = $false
              try { $skipIconRelink = (Test-SkipRestoreIconRelinkForExplorerShortcut -ShortcutPath $dst) } catch { $skipIconRelink = $false }
              if (-not $skipIconRelink) {
                $iconRel = [string](Get-PropString -Obj $i -Names @('IconBackupRelative') -Fallback '')
                $iconAppliedOk = $false
                if (-not [string]::IsNullOrWhiteSpace($iconRel)) {
                  $iconEntry = $null
                  $iconKey = Get-ZipEntryKeyLocal $iconRel
                  if (-not [string]::IsNullOrWhiteSpace($iconKey) -and $entryMap.ContainsKey($iconKey)) {
                    $iconEntry = $entryMap[$iconKey]
                  }
                  if ($iconEntry) {
                    $tempIconFile = Join-Path $tempEntryRoot ('ico_' + [guid]::NewGuid().ToString('N') + '.ico')
                    Copy-ZipEntryToFileLocal -Entry $iconEntry -DestinationPath $tempIconFile
                    $iconApply = Install-RestoredShortcutIconForDestination -DestinationLnkPath $dst -IconSourceFile $tempIconFile -IconBackupRelative $iconRel
                    if ($iconApply -and [bool]$iconApply.Ok) {
                      $iconAppliedOk = $true
                    } else {
                      $iconErr = ''
                      try { $iconErr = [string]$iconApply.Error } catch { $iconErr = '' }
                      if (-not [string]::IsNullOrWhiteSpace($iconErr)) {
                        [void]$errors.Add(("ICON RESTORE :: {0} :: {1}" -f $dst, $iconErr))
                      }
                    }
                  }
                }
                if (-not $iconAppliedOk) {
                  $tmpIco2 = $null
                  try {
                    $tmpIco2 = Join-Path $tempEntryRoot ('ico_fallback_' + [guid]::NewGuid().ToString('N') + '.ico')
                    $expIco2 = Export-ShortcutIconToIcoFile -ShortcutPath $dst -DestinationIcoPath $tmpIco2
                    if (-not [string]::IsNullOrWhiteSpace([string]$expIco2) -and (Test-Path -LiteralPath $expIco2 -PathType Leaf)) {
                      $iconApply2 = Install-RestoredShortcutIconForDestination -DestinationLnkPath $dst -IconSourceFile $expIco2 -IconBackupRelative '__fallback__'
                      if (-not ($iconApply2 -and [bool]$iconApply2.Ok)) {
                        $iconErr2 = ''
                        try { $iconErr2 = [string]$iconApply2.Error } catch { $iconErr2 = '' }
                        if (-not [string]::IsNullOrWhiteSpace($iconErr2)) {
                          [void]$errors.Add(("ICON RESTORE FALLBACK :: {0} :: {1}" -f $dst, $iconErr2))
                        }
                      }
                    }
                  } catch {}
                }
              }
            }
          } catch {}
          Invoke-StartMenuRefresh -TouchedFolder $destFolder
          $restored++
        } catch {
          [void]$errors.Add(("MANIFEST RESTORE :: {0}" -f $_.Exception.Message))
        } finally {
          if (-not [string]::IsNullOrWhiteSpace([string]$tempSnapshotFile)) {
            try { if (Test-Path -LiteralPath $tempSnapshotFile) { Remove-Item -LiteralPath $tempSnapshotFile -Force -ErrorAction SilentlyContinue } } catch {}
          }
          if (-not [string]::IsNullOrWhiteSpace([string]$tempIconFile)) {
            try { if (Test-Path -LiteralPath $tempIconFile) { Remove-Item -LiteralPath $tempIconFile -Force -ErrorAction SilentlyContinue } } catch {}
          }
        }
      }
      if ($isFullSnapshotRestore) {
        try {
          Ensure-FullSnapshotFoldersAfterRestore `
            -ExpectedFolders $expectedState.ExpectedFolders `
            -Restored ([ref]$restored) `
            -Errors $errors
        } catch {
          [void]$errors.Add(("FULL SNAPSHOT FOLDERS :: {0}" -f $_.Exception.Message))
        }
      } else {
        try {
          $manifestFolders = Get-ManifestFolderMap -Manifest $m
          if ($manifestFolders.Count -gt 0) {
            Ensure-FullSnapshotFoldersAfterRestore `
              -ExpectedFolders $manifestFolders `
              -Restored ([ref]$restored) `
              -Errors $errors
          }
        } catch {
          [void]$errors.Add(("MANIFEST FOLDERS :: {0}" -f $_.Exception.Message))
        }
      }
      try {
        $renByConv = Invoke-RestoreRenameFromConversionList -ConversionList $conversionList -Errors $errors
        if ($renByConv -gt 0) {
          $restored += [int]$renByConv
          foreach ($kv in $scopeRoots.GetEnumerator()) {
            try {
              $rf = Normalize-Path ([string]$kv.Value)
              if (-not [string]::IsNullOrWhiteSpace($rf)) { Invoke-StartMenuRefresh -TouchedFolder $rf }
            } catch {}
          }
        }
      } catch {
        [void]$errors.Add(("CONVERSION LIST APPLY :: {0}" -f $_.Exception.Message))
      }
      if ($manifestItemCount -gt 0 -and ($restored -gt 0 -or $errors.Count -gt 0)) {
        try { [void](Sync-LegacyAdminToolsHideFlagFromFilesystem) } catch {}
        $preOut = Resolve-PreRestoreBackupPath -PreRestoreRoot $preRoot -Errors $errors
        return [pscustomobject]@{
          Restored   = $restored
          Removed    = $removed
          PreCopied  = $preCopied
          PreRestore = $preOut
          Errors     = $errors.ToArray()
        }
      }
    }
    # Fallback for old ZIP layout without manifest.
    foreach ($scope in @("AllUsers","CurrentUser","DefaultProfile")) {
      if (-not $scopeRoots.ContainsKey($scope)) { continue }
      $dstRoot = $scopeRoots[$scope].TrimEnd('\')
      $prefix = (Normalize-ZipEntryPathLocal ($scope + '/'))
      foreach ($ze in @($zip.Entries)) {
        if (-not $ze) { continue }
        $full = Normalize-ZipEntryPathLocal ([string]$ze.FullName)
        if ([string]::IsNullOrWhiteSpace($full)) { continue }
        if (-not $full.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
        $isShortcutEntry = $false
        try {
          $isShortcutEntry = (
            $full.EndsWith('.lnk', [System.StringComparison]::OrdinalIgnoreCase) -or
            $full.EndsWith('.url', [System.StringComparison]::OrdinalIgnoreCase)
          )
        } catch { $isShortcutEntry = $false }
        if (-not $isShortcutEntry) { continue }
        $rel = $full.Substring($prefix.Length)
        if ([string]::IsNullOrWhiteSpace($rel)) { continue }
        $dstFile = Resolve-DestinationPathLenient -Path (Join-Path $dstRoot ($rel -replace '/', '\')) -IsFilePath
        if ([string]::IsNullOrWhiteSpace($dstFile)) { $dstFile = Join-Path $dstRoot ($rel -replace '/', '\') }
        $tempSnapshotFile = $null
        try {
          $ext = ''
          try { $ext = [string][System.IO.Path]::GetExtension([string]$ze.Name) } catch { $ext = '' }
          if ([string]::IsNullOrWhiteSpace($ext)) { $ext = '.lnk' }
          $tempSnapshotFile = Join-Path $tempEntryRoot (([guid]::NewGuid().ToString('N')) + $ext)
          Copy-ZipEntryToFileLocal -Entry $ze -DestinationPath $tempSnapshotFile
          $dstDir = Split-Path -Path $dstFile -Parent
          New-Item -ItemType Directory -Path $dstDir -Force | Out-Null
          if (Test-Path -LiteralPath $dstFile) {
            $preFile = Join-Path (Join-Path $preRoot $scope) ($rel -replace '/', '\')
            $preDir  = Split-Path -Path $preFile -Parent
            New-Item -ItemType Directory -Path $preDir -Force | Out-Null
            Copy-Item -LiteralPath $dstFile -Destination $preFile -Force -ErrorAction Stop
            $preCopied++
          }
          $tmp = Restore-ShortcutReplace -SnapshotLnkPath $tempSnapshotFile -DestFolder $dstDir
          if (-not $tmp) { throw "Restore-ShortcutReplace failed" }
          if ([string]$tmp -ne [string]$dstFile) {
            if (Test-Path -LiteralPath $dstFile) {
              try { Remove-Item -LiteralPath $dstFile -Force -ErrorAction Stop; $removed++ } catch {}
            }
            Move-Item -LiteralPath $tmp -Destination $dstFile -Force -ErrorAction Stop
          }
          Invoke-StartMenuRefresh -TouchedFolder $dstDir
          $restored++
        } catch {
          [void]$errors.Add(("RESTORE ZIP :: {0} -> {1} :: {2}" -f [string]$ze.FullName, $dstFile, $_.Exception.Message))
        } finally {
          if (-not [string]::IsNullOrWhiteSpace([string]$tempSnapshotFile)) {
            try { if (Test-Path -LiteralPath $tempSnapshotFile) { Remove-Item -LiteralPath $tempSnapshotFile -Force -ErrorAction SilentlyContinue } } catch {}
          }
        }
      }
    }
    try { [void](Sync-LegacyAdminToolsHideFlagFromFilesystem) } catch {}
    $preOut = Resolve-PreRestoreBackupPath -PreRestoreRoot $preRoot -Errors $errors
    [pscustomobject]@{
      Restored   = $restored
      Removed    = $removed
      PreCopied  = $preCopied
      PreRestore = $preOut
      Errors     = $errors.ToArray()
    }
  } finally {
    try { if ($zip) { $zip.Dispose() } } catch {}
    try { if ($zipFs) { $zipFs.Dispose() } } catch {}
    try { if (Test-Path -LiteralPath $tempEntryRoot) { Remove-Item -LiteralPath $tempEntryRoot -Recurse -Force -ErrorAction SilentlyContinue } } catch {}
  }
}

# ==============================================================================
# Apply button
# ==============================================================================
$applyBtn.Add_Click({
    End-GridEditTransaction

    # --------------------------
    # Windows Security proxy row detection
    # --------------------------
    $winSecRow = $null
    $winSecRen = 0
    $winSecDel = 0
    try { $winSecRow = $script:WindowsSecurityProxyRow } catch {}

    # Settings proxy row detection (same dedicated apply-stage pattern as Windows Security).
    $settingsRow = $null
    $settingsRen = 0
    $settingsDel = 0
    $outlookRow = $null
    $outlookRen = 0
    $outlookDel = 0
    $winBackupRow = $null
    $winBackupRen = 0
    $winBackupDel = 0

    # AppsFolder proxy actions (Settings/Edge/Outlook/Backup, etc.)
    $appsProxyDelCount = 0
    $appsProxyRenCount = 0
    $appsProxyDelRows  = New-Object System.Collections.Generic.List[object]
    $appsProxyRenRows  = New-Object System.Collections.Generic.List[object]
    $appsProxyActionRows = New-Object System.Collections.Generic.List[object]
    $appsProxySeen = @{}
    function Get-EffectiveRowAction {
      param([object]$r)
      if (-not $r) { return 'None' }
      $act = ''
      try { $act = [string]$r.Action } catch {}
      if ($act -eq 'Delete') { return 'Delete' }
      $pl = [string](Get-PropString -Obj $r -Names @('PendingLabel') -Fallback '')
      $hasDeleted = $false
      $hasRenamed = $false
      $hasMoved = $false
      $hasTargetEdit = $false
      try {
        foreach ($raw in @(([string]$pl -split "`r?`n"))) {
          $tok = ([string]$raw).Trim()
          if ([string]::IsNullOrWhiteSpace($tok)) { continue }
          if ([string]::Equals($tok, 'Deleted', [System.StringComparison]::OrdinalIgnoreCase)) { $hasDeleted = $true; continue }
          if ([string]::Equals($tok, 'Renamed', [System.StringComparison]::OrdinalIgnoreCase)) { $hasRenamed = $true; continue }
          if ([string]::Equals($tok, 'Moved', [System.StringComparison]::OrdinalIgnoreCase)) { $hasMoved = $true; continue }
          if ([string]::Equals($tok, 'Target Edit', [System.StringComparison]::OrdinalIgnoreCase)) { $hasTargetEdit = $true; continue }
        }
      } catch {}
      if ($hasDeleted) { return 'Delete' }
      if ($hasRenamed) { return 'Rename' }
      if ($hasMoved) { return 'Move' }
      if ($hasTargetEdit) { return 'TargetEdit' }
      $nm = [string](Get-PropString -Obj $r -Names @('Name') -Fallback '')
      $on = [string](Get-PropString -Obj $r -Names @('OriginalName') -Fallback $nm)
      if ($nm -ne $on) { return 'Rename' }
      $cp = Normalize-Path ([string](Get-PropString -Obj $r -Names @('Path') -Fallback ''))
      $op = Normalize-Path ([string](Get-PropString -Obj $r -Names @('OriginalPath','Path') -Fallback $cp))
      if (-not [string]::IsNullOrWhiteSpace($cp) -and -not [string]::IsNullOrWhiteSpace($op) -and (-not (Test-PathEqualsCI -A $cp -B $op))) {
        return 'Move'
      }
      if ($act -eq 'Rename') { return 'Rename' }
      return 'None'
    }

    # Dedicated Settings detection (same stage as Windows Security): resolve pending action BEFORE generic proxy handling.
    try {
      $settingsCandidates = New-Object System.Collections.Generic.List[object]
      foreach ($r in @($script:VisualAppsFolderProxyRows)) { if ($r) { [void]$settingsCandidates.Add($r) } }
      foreach ($r in @($script:VisibleRows)) { if ($r) { [void]$settingsCandidates.Add($r) } }
      foreach ($kv in $script:NodeMap.GetEnumerator()) {
        $n = $kv.Value
        if (-not $n) { continue }
        foreach ($r in @($n.Items)) { if ($r) { [void]$settingsCandidates.Add($r) } }
      }

      foreach ($r in @($settingsCandidates.ToArray())) {
        if (-not $r) { continue }
        if (-not (Test-IsSettingsAppsFolderRow -Row $r)) { continue }
        $ea = Get-EffectiveRowAction -r $r
        if ($ea -eq 'Delete') {
          $settingsDel = 1
          $settingsRen = 0
          $settingsRow = $r
          break
        } elseif ($ea -eq 'Rename' -and $settingsDel -eq 0) {
          $settingsRen = 1
          $settingsRow = $r
        }
      }
    } catch {}

    # Dedicated Outlook detection (same stage as Settings): resolve pending action BEFORE generic proxy handling.
    try {
      $outlookCandidates = New-Object System.Collections.Generic.List[object]
      foreach ($r in @($script:VisualAppsFolderProxyRows)) { if ($r) { [void]$outlookCandidates.Add($r) } }
      foreach ($r in @($script:VisibleRows)) { if ($r) { [void]$outlookCandidates.Add($r) } }
      foreach ($kv in $script:NodeMap.GetEnumerator()) {
        $n = $kv.Value
        if (-not $n) { continue }
        foreach ($r in @($n.Items)) { if ($r) { [void]$outlookCandidates.Add($r) } }
      }

      foreach ($r in @($outlookCandidates.ToArray())) {
        if (-not $r) { continue }
        if (-not (Test-IsOutlookAppsFolderRow -Row $r)) { continue }
        $ea = Get-EffectiveRowAction -r $r
        if ($ea -eq 'Delete') {
          $outlookDel = 1
          $outlookRen = 0
          $outlookRow = $r
          break
        } elseif ($ea -eq 'Rename' -and $outlookDel -eq 0) {
          $outlookRen = 1
          $outlookRow = $r
        }
      }
    } catch {}

    # Dedicated Windows Backup detection (same stage as Settings/Outlook).
    try {
      $wbCandidates = New-Object System.Collections.Generic.List[object]
      foreach ($r in @($script:VisualAppsFolderProxyRows)) { if ($r) { [void]$wbCandidates.Add($r) } }
      foreach ($r in @($script:VisibleRows)) { if ($r) { [void]$wbCandidates.Add($r) } }
      foreach ($r in @($script:CurrentView)) { if ($r) { [void]$wbCandidates.Add($r) } }
      foreach ($kv in $script:NodeMap.GetEnumerator()) {
        $n = $kv.Value
        if (-not $n) { continue }
        foreach ($r in @($n.Items)) { if ($r) { [void]$wbCandidates.Add($r) } }
      }

      foreach ($r in @($wbCandidates.ToArray())) {
        if (-not $r) { continue }
        if (-not (Test-IsWindowsBackupAppsFolderRow -Row $r)) { continue }
        $ea = Get-EffectiveRowAction -r $r
        if ($ea -eq 'Delete') {
          $winBackupDel = 1
          $winBackupRen = 0
          $winBackupRow = $r
          break
        } elseif ($ea -eq 'Rename' -and $winBackupDel -eq 0) {
          $winBackupRen = 1
          $winBackupRow = $r
        }
      }
    } catch {}

    function Add-AppProxyActionRow {
      param([object]$r)
      if (-not $r) { return }
      $isAppsProxy = $false
      try { $isAppsProxy = ($r.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$r.IsAppsFolderProxy) } catch {}
      if (-not $isAppsProxy) {
        try { $isAppsProxy = ($r.PSObject.Properties.Match('IsAppsFolderDisplayProxy').Count -gt 0 -and [bool]$r.IsAppsFolderDisplayProxy) } catch {}
      }
      if (-not $isAppsProxy) {
        # Fallback: treat any shell:AppsFolder-backed row as an AppsFolder proxy action row.
        $pp = [string](Get-PropString -Obj $r -Names @('Path','OriginalPath') -Fallback '')
        if (-not [string]::IsNullOrWhiteSpace($pp) -and $pp.StartsWith('shell:AppsFolder\', [System.StringComparison]::OrdinalIgnoreCase)) {
          $isAppsProxy = $true
        }
      }
      if (-not $isAppsProxy) { return }
      $act = Get-EffectiveRowAction -r $r
      if ($act -ne 'Rename' -and $act -ne 'Delete') { return }
      # Settings is resolved by dedicated detector above; skip here to avoid double counting.
      try { if (Test-IsSettingsAppsFolderRow -Row $r) { return } } catch {}
      try { if (Test-IsOutlookAppsFolderRow -Row $r) { return } } catch {}
      try {
        if (($winBackupRen -gt 0 -or $winBackupDel -gt 0) -and (Test-IsWindowsBackupAppsFolderRow -Row $r)) { return }
      } catch {}
      $k = ''
      try { $k = [string](Get-PropString -Obj $r -Names @('Id','AppsFolderId','Path','Name') -Fallback '') } catch {}
      if ([string]::IsNullOrWhiteSpace($k)) { try { $k = [guid]::NewGuid().ToString() } catch { $k = [string](Get-Random) } }
      $kk = $k.Trim().ToLowerInvariant()
      if ($appsProxySeen.ContainsKey($kk)) { return }
      $appsProxySeen[$kk] = $true
      if ($act -eq 'Rename') {
        $appsProxyRenCount++
        $logicalRenCount++
        [void]$appsProxyRenRows.Add($r)
      } else {
        $appsProxyDelCount++
        $logicalDelCount++
        [void]$appsProxyDelRows.Add($r)
      }
      [void]$appsProxyActionRows.Add($r)
    }

    if ($winSecRow -and ($winSecRow.PSObject.Properties.Match('IsWindowsSecurityProxy').Count -gt 0) -and [bool]$winSecRow.IsWindowsSecurityProxy) {
      if ([string]$winSecRow.Action -eq 'Delete') { $winSecDel = 1 }
      elseif ([string]$winSecRow.Action -eq 'Rename') { $winSecRen = 1 }
    }

    # --------------------------
    # Logical counts
    # Count pending actions directly off the model rows, BEFORE Meta expansion
    # (Skip the Windows Security proxy row because it is not a filesystem rename/delete.)
    # --------------------------
    $logicalRenCount = 0
    $logicalMoveCount = 0
    $logicalDelCount = 0
    $logicalTargetCount = 0
    $pendingCreateRows = @(Get-PendingCreateRows)
    $logicalCreateCount = @($pendingCreateRows).Count

    foreach ($kvp in $script:NodeMap.GetEnumerator()) {
      $node = $kvp.Value
      if (-not $node) { continue }

      foreach ($r in @($node.Folders) + @($node.Items)) {
        if (-not $r) { continue }
        if ($r.PSObject.Properties.Match('Action').Count -eq 0) { continue }

        try {
          if ($r.PSObject.Properties.Match('IsWindowsSecurityProxy').Count -gt 0 -and [bool]$r.IsWindowsSecurityProxy) { continue }
        } catch {}

        $isAppsProxy = $false
        try { $isAppsProxy = ($r.PSObject.Properties.Match('IsAppsFolderProxy').Count -gt 0 -and [bool]$r.IsAppsFolderProxy) } catch {}

        if ($isAppsProxy) {
          Add-AppProxyActionRow -r $r
          continue
        }

        switch (Get-EffectiveRowAction -r $r) {
          'Rename' { $logicalRenCount++ }
          'Move'   { $logicalMoveCount++ }
          'Delete' { $logicalDelCount++ }
          'TargetEdit' { $logicalTargetCount++ }
        }
      }
    }

    # Visual-only proxy rows are not in NodeMap; include them explicitly.
    foreach ($r in @($script:VisualAppsFolderProxyRows)) { Add-AppProxyActionRow -r $r }
    # Defensive: include any proxy currently visible in the grid if cache is stale.
    foreach ($r in @($script:VisibleRows)) { Add-AppProxyActionRow -r $r }
    # Include filtered collection too, so app-proxy deletes are never missed.
    foreach ($r in @($script:CurrentView)) { Add-AppProxyActionRow -r $r }

    $logicalRenCount += $winSecRen
    $logicalDelCount += $winSecDel
    $logicalRenCount += $settingsRen
    $logicalDelCount += $settingsDel
    $logicalRenCount += $outlookRen
    $logicalDelCount += $outlookDel
    $logicalRenCount += $winBackupRen
    $logicalDelCount += $winBackupDel

    # Collect filesystem-backed pending operations (including icon-only pending rows).
    $pending = Get-PendingChanges
    $logicalIconCount = @($pending.IconChanges).Count

    if ($logicalRenCount -eq 0 -and $logicalMoveCount -eq 0 -and $logicalDelCount -eq 0 -and $logicalCreateCount -eq 0 -and $logicalIconCount -eq 0 -and $logicalTargetCount -eq 0) {
      [System.Windows.MessageBox]::Show("No pending changes.", "Apply") | Out-Null
      return
    }

    # --------------------------
    # Physical counts (what filesystem operations will run)
    # Get-PendingChanges expands Meta renames into multiple scope targets
    # (Does NOT include Windows Security proxy)
    # --------------------------
    $physicalRenCount = @($pending.Renames).Count
    $physicalDelCount = @($pending.Deletes).Count

    $renLine = "Renames: $logicalRenCount"
    if ($physicalRenCount -gt ($logicalRenCount - $winSecRen)) {
      $renLine = "Renames: $logicalRenCount +duplicates"
    }

    $extra = ""
    if ($winSecRen -gt 0 -or $winSecDel -gt 0) {
      $extra = "`n`nWindows Security: pending change detected (special handling will run)."
    }
    if ($settingsRen -gt 0 -or $settingsDel -gt 0) {
      $extra += "`n`nSettings: pending change detected (special handling will run)."
    }
    if ($outlookRen -gt 0 -or $outlookDel -gt 0) {
      $extra += "`n`nOutlook: pending change detected (special handling will run)."
    }
    if ($winBackupRen -gt 0 -or $winBackupDel -gt 0) {
      $extra += "`n`nWindows Backup: pending change detected (special handling will run)."
    }
    $appsProxyActionCount = $appsProxyDelCount + $appsProxyRenCount
    if ($appsProxyActionCount -gt 0) {
      $extra += "`n`nAppsFolder actions: $appsProxyActionCount (renames: $appsProxyRenCount, deletes: $appsProxyDelCount; special handling will run)."
    }
    $applyBackupName = "auto_{0}" -f (Get-BackupStamp)
    $applyBackupRootPreview = Join-Path (Get-BackupsRoot) $applyBackupName
    $applyBackupArchivePreview = Get-BackupArchivePathForRoot -BackupRoot $applyBackupRootPreview

    $msgLines = New-Object System.Collections.Generic.List[string]
    [void]$msgLines.Add("Pending changes will now be applied to your Start Menu:")
    [void]$msgLines.Add("")
    if ($logicalRenCount -gt 0)     { [void]$msgLines.Add($renLine) }
    if ($logicalMoveCount -gt 0)    { [void]$msgLines.Add("Moved: $logicalMoveCount") }
    if ($logicalDelCount -gt 0)     { [void]$msgLines.Add("Deleted: $logicalDelCount") }
    if ($logicalCreateCount -gt 0)  { [void]$msgLines.Add("New Items: $logicalCreateCount") }
    if ($logicalIconCount -gt 0)    { [void]$msgLines.Add("Icon Changes: $logicalIconCount") }
    if ($logicalTargetCount -gt 0)  { [void]$msgLines.Add("Target Changes: $logicalTargetCount") }
    [void]$msgLines.Add("")
    [void]$msgLines.Add("Backup archive:")
    [void]$msgLines.Add([string]$applyBackupArchivePreview)
    $msg = [string]::Join("`n", @($msgLines.ToArray()))

    $res = [System.Windows.MessageBox]::Show(
      ($msg + $extra),
      "Apply Changes",
      [System.Windows.MessageBoxButton]::OKCancel,
      [System.Windows.MessageBoxImage]::Warning
    )
    if ($res -ne [System.Windows.MessageBoxResult]::OK) { return }

    try {
      Show-BusyOverlay
      # If any operation targets AllUsers (%ProgramData%), we must run elevated.
      try {
        $needsAdmin = $false
        foreach ($x in @($pending.Deletes) + @($pending.Renames) + @($pending.IconChanges)) {
          if (-not $x) { continue }
          $sc = ''
          try { $sc = [string]$x.Scope } catch {}
          if ($sc -eq 'AllUsers') { $needsAdmin = $true; break }
        }
        if ($needsAdmin) {
          if (-not (Ensure-ElevatedOrPrompt -Reason "Applying changes to the All Users Start Menu requires Administrator.")) { return }
        }
      } catch {}

    # Single backup root for all work in this apply (created lazily).
    $backupRoot = $null
    $applyArchivePath = ''
    function Ensure-ApplyBackupRoot {
      if ([string]::IsNullOrWhiteSpace([string]$backupRoot)) {
        $backupRoot = New-BackupFolder -Category Auto -Prefix "auto" -Name $applyBackupName
      }
      if (-not (Test-Path -LiteralPath $backupRoot)) {
        New-Item -ItemType Directory -Path $backupRoot -Force | Out-Null
      }
      return $backupRoot
    }

    # Always create a full backup snapshot before any mutation during Apply.
    try {
      $backupRoot = Ensure-ApplyBackupRoot
      $fullApplyBackup = Write-FullSnapshotBundle -BackupRoot $backupRoot
      if ($fullApplyBackup -and $fullApplyBackup.Errors -and @($fullApplyBackup.Errors).Count -gt 0) {
        $firstErr = [string](@($fullApplyBackup.Errors)[0])
        throw ("Full backup snapshot failed: " + $firstErr)
      }
      if ($fullApplyBackup -and -not [string]::IsNullOrWhiteSpace([string]$fullApplyBackup.ArchivePath)) {
        $applyArchivePath = [string]$fullApplyBackup.ArchivePath
      }
    } catch {
      [System.Windows.MessageBox]::Show(
        ("Apply was cancelled because full backup snapshot could not be created.`n`n" + [string]$_.Exception.Message),
        "Apply Changes"
      ) | Out-Null
      return
    }

    $specialInfo = New-Object System.Collections.Generic.List[string]
    $specialErrs = New-Object System.Collections.Generic.List[string]
    $winSecApplyOk = $false
    $settingsApplyOk = $false
    $outlookApplyOk = $false
    $winBackupApplyOk = $false
    $winBackupRestartNoticeShown = $false
    $appsProxyApplyOk = $false

    # --------------------------
    # Windows Security proxy apply
    # --------------------------
    if ($winSecRen -gt 0 -or $winSecDel -gt 0) {
      try {
        $backupRoot = Ensure-ApplyBackupRoot
        $dstRoot = [string]$scopeRoots['CurrentUser']
        if ([string]::IsNullOrWhiteSpace($dstRoot)) { $dstRoot = (Join-Path $env:AppData 'Microsoft\Windows\Start Menu\Programs') }

        if ($winSecDel -eq 0) {
          $created = Write-WindowsSecurityReplacementShortcut -DestRoot $dstRoot -LinkName ([string]$winSecRow.Name) -Placement 'Root' -BackupRoot $backupRoot
          [void]$specialInfo.Add(('Windows Security editable shortcut created/updated: ' + $created))
        } else {
          $p = [string]$winSecRow.Path
          if (-not [string]::IsNullOrWhiteSpace($p) -and (Test-Path -LiteralPath $p)) {
            try {
              $backupDir = Join-Path $backupRoot 'WindowsSecurityReplacementBackup'
              New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
              $stamp = (Get-Date).ToString('yyyyMMdd_HHmmss')
              Copy-Item -LiteralPath $p -Destination (Join-Path $backupDir ("Windows Security.deleted.$stamp.lnk")) -Force -ErrorAction Stop
            } catch {}
            Remove-Item -LiteralPath $p -Force -ErrorAction Stop
            try { Invoke-StartMenuRefresh -TouchedFolder $dstRoot } catch {}
          }
          [void]$specialInfo.Add(('Windows Security editable shortcut removed: ' + $p))
        }

        $winSecApplyOk = $true
        $script:WinSecLastApplyOkAt = Get-Date

        try { Stop-Process -Name StartMenuExperienceHost -Force -ErrorAction SilentlyContinue } catch {}
      } catch {
        $m = [string]$_.Exception.Message
        $t = ''
        try { $t = $_.Exception.GetType().FullName } catch {}
        [void]$specialErrs.Add(('Windows Security apply error: ' + $m + (if($t){' ('+$t+')'}else{''})))
      }
    }

    # --------------------------
    # Settings proxy apply (same stage as WinSec; no direct pre-Apply mutation)
    # --------------------------
    if ($settingsRen -gt 0 -or $settingsDel -gt 0) {
      try {
        $backupRoot = Ensure-ApplyBackupRoot
        $dstRoot = [string]$scopeRoots['CurrentUser']
        if ([string]::IsNullOrWhiteSpace($dstRoot)) { $dstRoot = (Join-Path $env:AppData 'Microsoft\Windows\Start Menu\Programs') }

        if ($settingsDel -eq 0) {
          $aid = [string](Get-PropString -Obj $settingsRow -Names @('AppsFolderId') -Fallback '')
          if ([string]::IsNullOrWhiteSpace($aid)) { $aid = 'windows.immersivecontrolpanel_cw5n1h2txyewy!microsoft.windows.immersivecontrolpanel' }
          $nm = [string](Get-PropString -Obj $settingsRow -Names @('Name','OriginalName') -Fallback 'Settings')

          $created = Write-AppsFolderEditableShortcut -DestRoot $dstRoot -LinkName $nm -AppId $aid -BackupRoot $backupRoot
          [void]$specialInfo.Add(('Settings editable shortcut created/updated: ' + [string]$created))
        } else {
          # Built-in Settings ShellApp is non-destructive in this tool; skip direct delete.
          [void]$specialInfo.Add('Settings built-in System App was left unchanged (delete skipped).')
        }

        $settingsApplyOk = $true
        try { Stop-Process -Name StartMenuExperienceHost -Force -ErrorAction SilentlyContinue } catch {}
      } catch {
        $m = [string]$_.Exception.Message
        $t = ''
        try { $t = $_.Exception.GetType().FullName } catch {}
        [void]$specialErrs.Add(('Settings apply error: ' + $m + (if($t){' ('+$t+')'}else{''})))
      }
    }

    # --------------------------
    # Outlook proxy apply (same stage as Settings; no direct pre-Apply mutation)
    # --------------------------
    if ($outlookRen -gt 0 -or $outlookDel -gt 0) {
      try {
        $backupRoot = Ensure-ApplyBackupRoot
        $dstRoot = [string]$scopeRoots['CurrentUser']
        if ([string]::IsNullOrWhiteSpace($dstRoot)) { $dstRoot = (Join-Path $env:AppData 'Microsoft\Windows\Start Menu\Programs') }

        if ($outlookDel -eq 0) {
          $aid = [string](Get-PropString -Obj $outlookRow -Names @('AppsFolderId') -Fallback '')
          if ([string]::IsNullOrWhiteSpace($aid)) {
            try {
              $oa = Get-StartAppsCached -MaxAgeSeconds 30 | Where-Object {
                $_ -and [string]$_.Name -match '^Outlook'
              } | Select-Object -First 1
              if ($oa) { $aid = [string]$oa.AppID }
            } catch {}
          }
          if ([string]::IsNullOrWhiteSpace($aid)) { throw "Outlook AppsFolderId not found." }

          $nm = [string](Get-PropString -Obj $outlookRow -Names @('Name','OriginalName') -Fallback 'Outlook')
          $created = Write-AppsFolderEditableShortcut -DestRoot $dstRoot -LinkName $nm -AppId $aid -BackupRoot $backupRoot
          [void]$specialInfo.Add(('Outlook editable shortcut created/updated: ' + [string]$created))
        } else {
          $forceDelete = $false
          try { $forceDelete = ($outlookRow.PSObject.Properties.Match('OutlookForceDeleteConfirmed').Count -gt 0 -and [bool]$outlookRow.OutlookForceDeleteConfirmed) } catch {}
          if (-not $forceDelete) {
            [System.Windows.MessageBox]::Show(
              "Outlook force deletion was not confirmed.`n`nUse 'Delete Selected' on the Outlook row and choose Delete in the warning dialog, then click Apply Changes.",
              "Apply"
            ) | Out-Null
            return
          }

          if (-not (Ensure-ElevatedOrPrompt -Reason "Force deletion of Outlook requires Administrator.")) { return }

          $removedCount = 0
          $pkgNames = New-Object System.Collections.Generic.List[string]
          try {
            $pkgs = @(Get-AppxPackage -AllUsers "Microsoft.OutlookForWindows" -ErrorAction SilentlyContinue)
            foreach ($p in @($pkgs)) {
              if (-not $p) { continue }
              $pfn = ''
              try { $pfn = [string]$p.PackageFullName } catch {}
              if (-not [string]::IsNullOrWhiteSpace($pfn)) {
                [void]$pkgNames.Add($pfn)
              }
            }
            if ($pkgNames.Count -gt 0) {
              foreach ($pfn in @($pkgNames.ToArray())) {
                try {
                  Remove-AppxPackage -Package $pfn -AllUsers -ErrorAction Stop
                  $removedCount++
                } catch {
                }
              }
            } else {
              # Fallback to user-provided pipeline style.
              try {
                Get-AppxPackage -AllUsers "Microsoft.OutlookForWindows" | Remove-AppxPackage -AllUsers -ErrorAction SilentlyContinue
              } catch {}
            }
          } catch {}

          try {
            ('OutlookForceDeletePackages=' + (($pkgNames.ToArray()) -join ';')) | Set-Content -LiteralPath (Join-Path $backupRoot 'OutlookForceDelete.txt') -Encoding ASCII
          } catch {}

          [void]$specialInfo.Add(("Outlook force-delete attempted (removed packages: " + [string]$removedCount + ")."))
        }

        $outlookApplyOk = $true
        try { Stop-Process -Name StartMenuExperienceHost -Force -ErrorAction SilentlyContinue } catch {}
      } catch {
        $m = [string]$_.Exception.Message
        $t = ''
        try { $t = $_.Exception.GetType().FullName } catch {}
        [void]$specialErrs.Add(('Outlook apply error: ' + $m + (if($t){' ('+$t+')'}else{''})))
      }
    }

    # --------------------------
    # Windows Backup delete apply (dedicated detector to avoid missed pending state)
    # --------------------------
    if ($winBackupDel -gt 0 -and $winBackupRow) {
      try {
        $backupRoot = Ensure-ApplyBackupRoot
        $pkg = ''
        try { $pkg = [string](Get-PropString -Obj $winBackupRow -Names @('WindowsBackupPlannedPackageName') -Fallback '') } catch { $pkg = '' }
        if ([string]::IsNullOrWhiteSpace($pkg)) {
          [System.Windows.MessageBox]::Show(
            "Windows Backup removal is pending, but no package was selected.`n`nUse 'Delete Selected' on the Windows Backup row, click Continue, select a package, then click Apply Changes.",
            "Apply"
          ) | Out-Null
          return
        }

        try { ('WindowsBackupUninstallSelected=' + $pkg) | Set-Content -LiteralPath (Join-Path $backupRoot 'WindowsBackupUninstall.txt') -Encoding ASCII } catch {}
        $wbRemove = $null
        Invoke-WithBusyOverlay -Status "Working..." -Action {
          $wbRemove = Remove-UserExperiencePackageStrict -PackageName ([string]$pkg)
        }
        if (-not $wbRemove -or -not [bool]$wbRemove.Ok) {
          $wbErr = 'UserExperience package uninstall failed.'
          try { if ($wbRemove -and -not [string]::IsNullOrWhiteSpace([string]$wbRemove.Error)) { $wbErr = [string]$wbRemove.Error } } catch {}
          throw $wbErr
        }

        [void]$specialInfo.Add(("Windows Backup: removed by uninstalling package: " + [string]$pkg))
        if (-not $winBackupRestartNoticeShown) {
          try {
            [System.Windows.MessageBox]::Show(
              "UserExperience package removed. Restart PC for changes to take effect.",
              "Apply"
            ) | Out-Null
          } catch {}
          $winBackupRestartNoticeShown = $true
        }
        $winBackupApplyOk = $true
        try { Stop-Process -Name StartMenuExperienceHost -Force -ErrorAction SilentlyContinue } catch {}
      } catch {
        $m = [string]$_.Exception.Message
        $t = ''
        try { $t = $_.Exception.GetType().FullName } catch {}
        [void]$specialErrs.Add(('Windows Backup apply error: ' + $m + (if($t){' ('+$t+')'}else{''})))
      }
    }

    # --------------------------
    # Windows Backup rename apply (dedicated detector to avoid missed pending state)
    # --------------------------
    if ($winBackupRen -gt 0 -and $winBackupRow) {
      try {
        $backupRoot = Ensure-ApplyBackupRoot
        $dstRoot = [string]$scopeRoots['CurrentUser']
        if ([string]::IsNullOrWhiteSpace($dstRoot)) { $dstRoot = (Join-Path $env:AppData 'Microsoft\Windows\Start Menu\Programs') }

        $aid = [string](Get-PropString -Obj $winBackupRow -Names @('AppsFolderId') -Fallback '')
        if ([string]::IsNullOrWhiteSpace($aid)) {
          try {
            $wa = Get-StartAppsCached -MaxAgeSeconds 30 | Where-Object { $_ -and [string]$_.Name -eq 'Windows Backup' } | Select-Object -First 1
            if ($wa) { $aid = [string]$wa.AppID }
          } catch {}
        }
        if ([string]::IsNullOrWhiteSpace($aid)) { throw "Windows Backup AppsFolderId not found." }

        $nm = [string](Get-PropString -Obj $winBackupRow -Names @('Name','OriginalName') -Fallback 'Windows Backup')
        $created = Write-AppsFolderEditableShortcut -DestRoot $dstRoot -LinkName $nm -AppId $aid -BackupRoot $backupRoot
        [void]$specialInfo.Add(('Windows Backup editable shortcut created/updated: ' + [string]$created))

        $winBackupApplyOk = $true
        try { Stop-Process -Name StartMenuExperienceHost -Force -ErrorAction SilentlyContinue } catch {}
      } catch {
        $m = [string]$_.Exception.Message
        $t = ''
        try { $t = $_.Exception.GetType().FullName } catch {}
        [void]$specialErrs.Add(('Windows Backup apply error: ' + $m + (if($t){' ('+$t+')'}else{''})))
      }
    }

    # --------------------------
    # AppsFolder proxy actions (ShellApp rename/delete handling)
    # --------------------------
    if ($appsProxyActionCount -gt 0) {
      try {
        $backupRoot = Ensure-ApplyBackupRoot
        $winBackupDelRows = New-Object System.Collections.Generic.List[object]
        $otherRows        = New-Object System.Collections.Generic.List[object]

        foreach ($r in @($appsProxyActionRows)) {
          if (-not $r) { continue }
          $act = ''
          try { $act = [string]$r.Action } catch {}
          if ($act -eq 'Delete' -and (Test-IsWindowsBackupAppsFolderRow -Row $r)) {
            [void]$winBackupDelRows.Add($r)
          } else {
            [void]$otherRows.Add($r)
          }
        }

        $needsShellAppAdmin = ($winBackupDelRows.Count -gt 0 -or $otherRows.Count -gt 0)
        if ($needsShellAppAdmin) {
          if (-not (Ensure-ElevatedOrPrompt -Reason "System App changes require Administrator (FSLogix masking may be used).")) { return }
        }

        # Windows Backup delete = package uninstall (planned at Mock Delete).
        if ($winBackupDelRows.Count -gt 0) {
          foreach ($r in @($winBackupDelRows)) {
            if (-not $r) { continue }
            $pkg = ''
            try { if ($r.PSObject.Properties.Match('WindowsBackupPlannedPackageName').Count -gt 0) { $pkg = [string]$r.WindowsBackupPlannedPackageName } } catch {}
            if ([string]::IsNullOrWhiteSpace($pkg)) {
              [System.Windows.MessageBox]::Show(
                "Windows Backup removal is pending, but no package was selected.`n`nUse 'Delete Selected' on the Windows Backup row, click Continue, select a package, then click Apply Changes.",
                "Apply"
              ) | Out-Null
              return
            }

            try { ('WindowsBackupUninstallSelected=' + $pkg) | Set-Content -LiteralPath (Join-Path $backupRoot 'WindowsBackupUninstall.txt') -Encoding ASCII } catch {}

            $wbRemove = $null
            Invoke-WithBusyOverlay -Status "Working..." -Action {
              $wbRemove = Remove-UserExperiencePackageStrict -PackageName ([string]$pkg)
            }
            if (-not $wbRemove -or -not [bool]$wbRemove.Ok) {
              $wbErr = 'UserExperience package uninstall failed.'
              try { if ($wbRemove -and -not [string]::IsNullOrWhiteSpace([string]$wbRemove.Error)) { $wbErr = [string]$wbRemove.Error } } catch {}
              throw $wbErr
            }

            [void]$specialInfo.Add(("Windows Backup: removed by uninstalling package: " + [string]$pkg))
            if (-not $winBackupRestartNoticeShown) {
              try {
                [System.Windows.MessageBox]::Show(
                  "UserExperience package removed. Restart PC for changes to take effect.",
                  "Apply"
                ) | Out-Null
              } catch {}
              $winBackupRestartNoticeShown = $true
            }
          }
          $appsProxyApplyOk = $true
        }

        if ($otherRows.Count -gt 0) {
          $apx = Apply-AppsFolderProxyActions -Rows @($otherRows.ToArray()) -BackupRoot $backupRoot
          foreach ($x in @($apx.Created)) { [void]$specialInfo.Add(("AppsFolder shortcut created: " + [string]$x)) }
          foreach ($x in @($apx.Hidden))  {
            if (-not $x) { continue }
            try {
              if ($x.Kind -eq 'File') {
                [void]$specialInfo.Add(("AppsFolder hidden (file): " + [string]$x.Path))
              } elseif ($x.Kind -eq 'Registry') {
                [void]$specialInfo.Add(("AppsFolder hidden (registry): " + [string]$x.Src))
              } else {
                [void]$specialInfo.Add(("AppsFolder hidden: " + [string]($x | ConvertTo-Json -Compress)))
              }
            } catch {}
          }
          foreach ($x in @($apx.Skipped)) { [void]$specialErrs.Add(("AppsFolder skip: " + [string]$x)) }
          foreach ($x in @($apx.Errors))  { [void]$specialErrs.Add(("AppsFolder error: " + [string]$x)) }
          $appsProxyApplyOk = $true
        }

        try { Stop-Process -Name StartMenuExperienceHost -Force -ErrorAction SilentlyContinue } catch {}
      } catch {
        [void]$specialErrs.Add(("AppsFolder action error: " + [string]$_.Exception.Message))
      }
    }

    # --------------------------
    # Pending create apply (new folders/shortcuts)
    # --------------------------
    $createAppliedCount = 0
    $createErrs = New-Object System.Collections.Generic.List[string]
    if ($logicalCreateCount -gt 0) {
      foreach ($cr in @($pendingCreateRows)) {
        if (-not $cr) { continue }
        try {
          $kind = [string](Get-PropString -Obj $cr -Names @('CreateKind') -Fallback '')
          if ([string]::IsNullOrWhiteSpace($kind)) {
            $rk = [string](Get-PropString -Obj $cr -Names @('RowKind') -Fallback 'Item')
            $kind = $(if ($rk -eq 'Folder') { 'Folder' } else { 'Shortcut' })
          }

          $dst = Normalize-Path ([string](Get-PropString -Obj $cr -Names @('Path','OriginalPath') -Fallback ''))
          if ([string]::IsNullOrWhiteSpace($dst)) { throw "Missing destination path." }

          if ($kind -eq 'Folder') {
            if (-not (Test-Path -LiteralPath $dst)) {
              New-Item -ItemType Directory -Path $dst -Force -ErrorAction Stop | Out-Null
            }
          } else {
            $tgt = Normalize-Path ([string](Get-PropString -Obj $cr -Names @('CreateTargetPath','Target') -Fallback ''))
            if ([string]::IsNullOrWhiteSpace($tgt) -or -not (Test-Path -LiteralPath $tgt)) {
              throw ("Shortcut target not found: " + [string](Get-PropString -Obj $cr -Names @('CreateTargetPath','Target') -Fallback '<empty>'))
            }

            $dstDir = Split-Path -Path $dst -Parent
            if (-not [string]::IsNullOrWhiteSpace($dstDir) -and -not (Test-Path -LiteralPath $dstDir)) {
              New-Item -ItemType Directory -Path $dstDir -Force | Out-Null
            }

            $ws = New-Object -ComObject WScript.Shell
            $sc = $ws.CreateShortcut($dst)
            $sc.TargetPath = $tgt
            $iconPath = Normalize-Path ([string](Get-PropString -Obj $cr -Names @('CreateIconPath') -Fallback ''))
            $iconIndex = 0
            try { $iconIndex = [int](Get-PropString -Obj $cr -Names @('CreateIconIndex') -Fallback '0') } catch { $iconIndex = 0 }
            $targetIsFolder = $false
            try { $targetIsFolder = (Test-Path -LiteralPath $tgt -PathType Container) } catch { $targetIsFolder = $false }
            if ($targetIsFolder) {
              if ([string]::IsNullOrWhiteSpace($iconPath) -or [string]::Equals((Normalize-Path $iconPath), (Normalize-Path $tgt), [System.StringComparison]::OrdinalIgnoreCase)) {
                try {
                  $folderSpec = Get-DefaultFolderIconLocationSpec
                  if ($folderSpec -and -not [string]::IsNullOrWhiteSpace([string]$folderSpec.IconPath)) {
                    $iconPath = [string]$folderSpec.IconPath
                    try { $iconIndex = [int]$folderSpec.IconIndex } catch { $iconIndex = 0 }
                  }
                } catch {}
              }
            }
            if (-not [string]::IsNullOrWhiteSpace($iconPath)) {
              $sc.IconLocation = ($iconPath + ',' + [string]$iconIndex)
            }
            $sc.Save()
            try { [void](Ensure-EdgeIconOnShortcut -LnkPath $dst -Row $cr) } catch {}
            try {
              $imgFromCreated = Get-ImageSourceFromIcon -IconPath $dst -IconIndex 0 -FallbackExePath $tgt
              if (-not $imgFromCreated) {
                try { $imgFromCreated = Get-ImageSourceFromShellParsingName -ParsingName $dst } catch {}
              }
              if ($imgFromCreated) { Set-PropSafeGlobal -Obj $cr -Name 'Icon' -Value $imgFromCreated }
            } catch {}
          }

          try {
            Set-PropSafeGlobal -Obj $cr -Name 'Action' -Value 'None'
            Set-PropSafeGlobal -Obj $cr -Name 'PendingLabel' -Value ''
            Set-PropSafeGlobal -Obj $cr -Name 'PendingLabelRows' -Value (@())
            Set-PropSafeGlobal -Obj $cr -Name 'Selected' -Value $false
          } catch {}

          $rid = ''
          try { $rid = [string]$cr.Id } catch {}
          if (-not [string]::IsNullOrWhiteSpace($rid)) { [void](Remove-PendingCreateRowById -Id $rid) }
          $createAppliedCount++
        } catch {
          $nm = [string](Get-PropString -Obj $cr -Names @('Name') -Fallback '<unnamed>')
          [void]$createErrs.Add(("CREATE :: " + $nm + " :: " + [string]$_.Exception.Message))
        }
      }

      foreach ($ce in @($createErrs)) { [void]$specialErrs.Add([string]$ce) }
    }

    # --------------------------
    # Apply (filesystem operations)
    # --------------------------
    $result = Backup-And-ApplyChanges -Deletes $pending.Deletes -Renames $pending.Renames -Creates $pendingCreateRows -IconChanges $pending.IconChanges -TargetChanges $pending.TargetChanges -BackupRoot $backupRoot
    if ($result -and -not [string]::IsNullOrWhiteSpace([string]$result.BackupRoot)) {
      $backupRoot = [string]$result.BackupRoot
    }
    if (-not [string]::IsNullOrWhiteSpace([string]$backupRoot) -and (Test-Path -LiteralPath $backupRoot -PathType Container)) {
      try {
        $finalized = Finalize-BackupArchivePackage -BackupRoot $backupRoot -DeleteSourceRootOnSuccess
        if ($finalized -and -not [string]::IsNullOrWhiteSpace([string]$finalized.ArchivePath)) {
          $applyArchivePath = [string]$finalized.ArchivePath
        } elseif ($result -and -not [string]::IsNullOrWhiteSpace([string]$result.ArchivePath)) {
          $applyArchivePath = [string]$result.ArchivePath
        }
        if ($finalized -and -not [string]::IsNullOrWhiteSpace([string]$finalized.Error)) {
          [void]$specialErrs.Add(('Backup archive finalize warning: ' + [string]$finalized.Error))
        }
      } catch {
        [void]$specialErrs.Add(('Backup archive finalize error: ' + [string]$_.Exception.Message))
      }
    }

    # If WinSec special apply succeeded, clear the proxy row so it doesn't stay stuck in Deleted/Renamed UI.
    if ($winSecApplyOk) {
      try { $script:WindowsSecurityProxyRow = $null } catch {}
      try { $script:WinSecShellAppPresentCacheAt = [datetime]::MinValue; $script:WinSecShellAppPresentCache = $false } catch {}
      try { $script:WinSecEditableShortcutCacheAt = [datetime]::MinValue; $script:WinSecEditableShortcutCache = $false } catch {}
    }
    if ($settingsApplyOk) {
      try { $script:SettingsProxyRow = $null } catch {}
    }
    if ($outlookApplyOk) {
      try { $script:OutlookProxyRow = $null } catch {}
    }
    if ($winBackupApplyOk -and $winBackupRow) {
      try { Set-PropSafeGlobal -Obj $winBackupRow -Name 'Action' -Value 'None' } catch {}
      try { Set-PropSafeGlobal -Obj $winBackupRow -Name 'PendingLabel' -Value '' } catch {}
      try { Set-PropSafeGlobal -Obj $winBackupRow -Name 'PendingLabelRows' -Value (@()) } catch {}
      try { Set-PropSafeGlobal -Obj $winBackupRow -Name 'Selected' -Value $false } catch {}
    }
    if ($appsProxyApplyOk) {
      foreach ($r in @($appsProxyActionRows)) {
        if (-not $r) { continue }
        try { Set-PropSafeGlobal -Obj $r -Name 'Action' -Value 'None' } catch {}
        try { Set-PropSafeGlobal -Obj $r -Name 'PendingLabel' -Value '' } catch {}
        try { Set-PropSafeGlobal -Obj $r -Name 'PendingLabelRows' -Value (@()) } catch {}
        try { Set-PropSafeGlobal -Obj $r -Name 'Selected' -Value $false } catch {}
        try { if ($r.PSObject.Properties.Match('WindowsBackupPlannedPackageName').Count -gt 0) { $r.WindowsBackupPlannedPackageName = '' } } catch {}
      }
    }

    # Completion display should be LOGICAL too (with duplicates note if applicable)
    $renDoneLine = "Renamed: $logicalRenCount"
    if ($result.Renamed -gt ($logicalRenCount - $winSecRen)) {
      $renDoneLine = "Renamed: $logicalRenCount (+duplicates)"
    }

    $moveDoneLine = "Moved: $logicalMoveCount"

    $delDoneLine = "Deleted: $logicalDelCount"
    if ($result.Deleted -gt ($logicalDelCount - $winSecDel)) {
      $delDoneLine = "Deleted: $logicalDelCount (+duplicates)"
    }
    $createDoneLine = "Created: $createAppliedCount"
    $iconDoneLine = "Icon Edit: " + [string]$result.IconChanged
    $targetDoneLine = "Target Edit: " + [string]$result.TargetChanged

    $allErrors = New-Object System.Collections.Generic.List[string]
    foreach ($x in @($result.Errors)) { [void]$allErrors.Add([string]$x) }
    foreach ($x in @($specialErrs))   { [void]$allErrors.Add([string]$x) }

    # Show only useful summary lines (omit 0-value actions).
    $summaryLines = New-Object System.Collections.Generic.List[string]
    if ($logicalRenCount -gt 0)   { [void]$summaryLines.Add($renDoneLine) }
    if ($logicalMoveCount -gt 0)  { [void]$summaryLines.Add($moveDoneLine) }
    if ($logicalDelCount -gt 0)   { [void]$summaryLines.Add($delDoneLine) }
    if ($createAppliedCount -gt 0){ [void]$summaryLines.Add($createDoneLine) }
    if ([int]$result.IconChanged -gt 0)   { [void]$summaryLines.Add($iconDoneLine) }
    if ([int]$result.TargetChanged -gt 0) { [void]$summaryLines.Add($targetDoneLine) }
    if ($summaryLines.Count -eq 0) { [void]$summaryLines.Add('No changes were applied.') }

    if ($allErrors.Count -gt 0) {
      $backupDisplay = '(none)'
      if (-not [string]::IsNullOrWhiteSpace([string]$applyArchivePath)) {
        $backupDisplay = [string]$applyArchivePath
      } elseif ($result -and -not [string]::IsNullOrWhiteSpace([string]$result.ArchivePath)) {
        $backupDisplay = [string]$result.ArchivePath
      } elseif (-not [string]::IsNullOrWhiteSpace([string]$backupRoot)) {
        $backupDisplay = [string]$backupRoot
      }
      $errText = ($allErrors | Select-Object -First 10) -join "`n"
      if ($allErrors.Count -gt 10) { $errText += "`n... (more errors omitted)" }

      [System.Windows.MessageBox]::Show(
        (($summaryLines -join "`n") + "`n" + "Backup: $backupDisplay" + "`n" + ("Errors: " + $allErrors.Count) + "`n`n" + $errText),
        "Apply Completed With Errors"
      ) | Out-Null
    }

    Clear-VisualProxyCaches
    $script:StartupInventory = @(Get-Inventory)
    try { Invalidate-LaunchDuplicateCaches } catch {}
    $model = Build-Model -inventoryItems $script:StartupInventory
    $script:TreeRoots = $model.TreeRoots
    $script:NodeMap   = $model.NodeMap

    $tree.ItemsSource = $null
    $tree.ItemsSource = $script:TreeRoots

    $script:UndoStack.Clear()
    $script:RedoStack.Clear()

    $grid.ItemsSource = $null
    $script:CurrentNode = $null
    $script:CurrentView = $null

      Select-DefaultStartNode
    } finally {
      Hide-BusyOverlay
    }
  })
  
# ==============================================================================
# Save / Load Pending States
# ==============================================================================
function Get-PendingItemsRoot {
  $root = Join-Path $PSScriptRoot 'Pending Items'
  if (-not (Test-Path -LiteralPath $root)) {
    New-Item -ItemType Directory -Path $root -Force | Out-Null
  }
  return $root
}

function Get-PendingCreateStatePathForProfile {
  param([Parameter(Mandatory=$true)][string]$ProfilePath)
  $base = ''
  try { $base = [System.IO.Path]::GetFileNameWithoutExtension([string]$ProfilePath) } catch { $base = '' }
  if ([string]::IsNullOrWhiteSpace($base)) { $base = 'pending_state' }
  return (Join-Path (Get-PendingItemsRoot) ($base + '.pending.creates.json'))
}

function Collect-PendingCreateProfileEntries {
  $rows = @(Get-PendingCreateRows)
  $out = New-Object System.Collections.Generic.List[object]
  foreach ($cr in @($rows)) {
    if (-not $cr) { continue }
    $kind = [string](Get-PropString -Obj $cr -Names @('CreateKind') -Fallback '')
    if ([string]::IsNullOrWhiteSpace($kind)) {
      $tp = [string](Get-PropString -Obj $cr -Names @('Type') -Fallback '')
      $kind = $(if ($tp -eq 'Folder') { 'Folder' } else { 'Shortcut' })
    }
    if ($kind -ne 'Folder' -and $kind -ne 'Shortcut') { continue }
    $destPath = Normalize-Path ([string](Get-PropString -Obj $cr -Names @('Path','OriginalPath') -Fallback ''))
    if ([string]::IsNullOrWhiteSpace($destPath)) { continue }
    $name = [string](Get-PropString -Obj $cr -Names @('Name','OriginalName') -Fallback '')
    if ([string]::IsNullOrWhiteSpace($name)) {
      try { $name = [System.IO.Path]::GetFileNameWithoutExtension($destPath) } catch { $name = '' }
    }
    $targetPath = Normalize-Path ([string](Get-PropString -Obj $cr -Names @('CreateTargetPath','Target') -Fallback ''))
    $iconPath = Normalize-Path ([string](Get-PropString -Obj $cr -Names @('CreateIconPath') -Fallback ''))
    $iconIndex = 0
    try { $iconIndex = [int](Get-PropString -Obj $cr -Names @('CreateIconIndex') -Fallback '0') } catch { $iconIndex = 0 }
    [void]$out.Add([pscustomobject]@{
      Action          = 'Create'
      CreateKind      = [string]$kind
      Name            = [string]$name
      NewName         = [string]$name
      NewPath         = [string]$destPath
      Scope           = [string](Get-PropString -Obj $cr -Names @('Scope') -Fallback 'CurrentUser')
      Type            = $(if ($kind -eq 'Folder') { 'Folder' } else { 'Shortcut' })
      CreateTargetPath= [string]$targetPath
      CreateIconPath  = [string]$iconPath
      CreateIconIndex = [int]$iconIndex
    })
  }
  return @($out.ToArray())
}

function Save-PendingCreateStateForProfile {
  param([Parameter(Mandatory=$true)][string]$ProfilePath)
  try {
    $entries = @(Collect-PendingCreateProfileEntries)
    $statePath = Get-PendingCreateStatePathForProfile -ProfilePath $ProfilePath
    $profileLeaf = ''
    try { $profileLeaf = [System.IO.Path]::GetFileName($ProfilePath) } catch { $profileLeaf = [string]$ProfilePath }
    $payload = [pscustomobject]@{
      SchemaVersion = 1
      CreatedUtc    = (Get-Date).ToUniversalTime().ToString('o')
      ProfileFile   = [string]$profileLeaf
      Creates       = @($entries)
    }
    Save-PlanJson -Path $statePath -Payload $payload
    return [pscustomobject]@{ Path = $statePath; Count = @($entries).Count }
  } catch {
    return [pscustomobject]@{ Path = ''; Count = 0; Error = [string]$_.Exception.Message }
  }
}

function Load-PendingCreateStateForProfile {
  param([Parameter(Mandatory=$true)][string]$ProfilePath)
  try {
    $statePath = Get-PendingCreateStatePathForProfile -ProfilePath $ProfilePath
    if (-not (Test-Path -LiteralPath $statePath)) { return @() }
    $raw = Get-Content -LiteralPath $statePath -Raw -ErrorAction Stop
    $obj = $raw | ConvertFrom-Json -ErrorAction Stop
    if (-not $obj -or -not $obj.Creates) { return @() }
    return @($obj.Creates)
  } catch {
    return @()
  }
}

function Apply-ProfileCreateEntry {
  param([Parameter(Mandatory=$true)][object]$Entry)
  try {
    $kind = [string](Get-PropString -Obj $Entry -Names @('CreateKind') -Fallback '')
    if ([string]::IsNullOrWhiteSpace($kind)) {
      $tp = [string](Get-PropString -Obj $Entry -Names @('Type') -Fallback '')
      $kind = $(if ($tp -eq 'Folder') { 'Folder' } else { 'Shortcut' })
    }
    if ($kind -ne 'Folder' -and $kind -ne 'Shortcut') { return $false }
    $destPath = Normalize-Path ([string](Get-PropString -Obj $Entry -Names @('NewPath','OriginalPath','Path') -Fallback ''))
    if ([string]::IsNullOrWhiteSpace($destPath)) { return $false }
    if (Test-Path -LiteralPath $destPath) { return $false }
    if (Test-PendingCreatePathExists -Path $destPath) { return $false }
    $name = [string](Get-PropString -Obj $Entry -Names @('NewName','Name') -Fallback '')
    if ([string]::IsNullOrWhiteSpace($name)) {
      if ($kind -eq 'Folder') {
        try { $name = [System.IO.Path]::GetFileName($destPath) } catch { $name = '' }
      } else {
        try { $name = [System.IO.Path]::GetFileNameWithoutExtension($destPath) } catch { $name = '' }
      }
    }
    if ([string]::IsNullOrWhiteSpace($name) -or -not (Test-ValidFileName -Name $name)) { return $false }
    $targetPath = Normalize-Path ([string](Get-PropString -Obj $Entry -Names @('CreateTargetPath','Target') -Fallback ''))
    $iconPath = Normalize-Path ([string](Get-PropString -Obj $Entry -Names @('CreateIconPath') -Fallback ''))
    $iconIndex = 0
    try { $iconIndex = [int](Get-PropString -Obj $Entry -Names @('CreateIconIndex') -Fallback '0') } catch { $iconIndex = 0 }
    $iconImage = $null
    if ($kind -eq 'Shortcut') {
      try { $iconImage = Get-ImageSourceFromIcon -IconPath $iconPath -IconIndex $iconIndex -FallbackExePath $targetPath } catch { $iconImage = $null }
    }
    $row = New-PendingCreateGridRow -Kind $kind -Name $name -DestPath $destPath -TargetPath $targetPath -IconPath $iconPath -IconIndex $iconIndex -IconImage $iconImage
    Add-PendingCreateRow -Row $row
    return $true
  } catch {
    return $false
  }
}

function Build-CurrentKeyMap {
  $map = @{}
  foreach ($r in $script:TreeRoots) {
    $stack = New-Object System.Collections.Generic.Stack[FolderNode]
    $stack.Push($r)
    while ($stack.Count -gt 0) {
      $n = $stack.Pop()
      foreach ($it in $n.Items) {
        $k = Get-StableKey -it $it
        if (-not $k) { continue }
        if (-not $map.ContainsKey($k)) { $map[$k] = $it }
      }
      foreach ($ch in $n.Children) { $stack.Push($ch) }
    }
  }
  return $map
}

function Apply-ProfileEntriesToMock {
  param([Parameter(Mandatory=$true)][object[]]$Entries)
  End-GridEditTransaction
  $map = Build-CurrentKeyMap
  $matched = 0
  $missing = New-Object System.Collections.Generic.List[object]
  $skipped = 0
  $createsAdded = 0
  foreach ($e in $Entries) {
    if ([string](Get-PropString -Obj $e -Names @('Action') -Fallback '') -eq 'Create') {
      if (Apply-ProfileCreateEntry -Entry $e) {
        $matched++
        $createsAdded++
      } else {
        $skipped++
      }
      continue
    }
    $k = [string]$e.Key
    if ([string]::IsNullOrWhiteSpace($k) -or -not $map.ContainsKey($k)) {
      [void]$missing.Add($e)
      continue
    }
    $it = $map[$k]
    if ($it.Action -eq "Delete") { $matched++; continue }
    if ([string]$e.Action -eq "Delete") {
      $it.Action       = "Delete"
      $it.PendingLabel = "Deleted"
      try { $it.PendingLabelRows = @([pscustomobject]@{ Text = 'Deleted'; Color = '#D32F2F' }) } catch {}
      $it.Selected     = $false
      $matched++
      continue
    }
    if ([string]$e.Action -eq "Rename") {
      $newName = (Trim-NameInputPreserveNbsp -Text ([string]$e.NewName))
      $newPath = Normalize-Path ([string]$e.NewPath)
      $canApplyName = $false
      if (-not [string]::IsNullOrWhiteSpace($newName) -and (Test-ValidFileName -Name $newName)) { $canApplyName = $true }
      $canApplyPath = (-not [string]::IsNullOrWhiteSpace($newPath))
      if (-not $canApplyName -and -not $canApplyPath) { $skipped++; continue }
      if ($canApplyName) { $it.Name = $newName }
      if ($canApplyPath) { try { Set-PropSafeGlobal -Obj $it -Name 'Path' -Value ([string]$newPath) } catch {} }
      Set-PendingState -it $it
      $matched++
      continue
    }
    if ([string]$e.Action -eq "IconEdit") {
      $iconPath = Normalize-Path ([string]$e.PendingIconPath)
      if ([string]::IsNullOrWhiteSpace($iconPath) -or -not (Test-Path -LiteralPath $iconPath -PathType Leaf)) { $skipped++; continue }
      $iconIndex = 0
      try { $iconIndex = [int]$e.PendingIconIndex } catch { $iconIndex = 0 }
      try { Set-PropSafeGlobal -Obj $it -Name 'PendingIconPath' -Value ([string]$iconPath) } catch {}
      try { Set-PropSafeGlobal -Obj $it -Name 'PendingIconIndex' -Value ([int]$iconIndex) } catch {}
      try {
        $img = Get-ImageSourceFromIcon -IconPath $iconPath -IconIndex $iconIndex -FallbackExePath $iconPath
        if ($img) { Set-PropSafeGlobal -Obj $it -Name 'Icon' -Value $img }
      } catch {}
      Set-PendingState -it $it
      $matched++
      continue
    }
    if ([string]$e.Action -eq "TargetEdit") {
      $newTarget = Normalize-Path ([string](Get-PropString -Obj $e -Names @('PendingTargetPath') -Fallback ''))
      if ([string]::IsNullOrWhiteSpace($newTarget) -or -not (Test-Path -LiteralPath $newTarget)) { $skipped++; continue }
      try { Set-PropSafeGlobal -Obj $it -Name 'PendingTargetPath' -Value ([string]$newTarget) } catch {}
      Set-PendingState -it $it
      $matched++
      continue
    }
    $skipped++
  }
  if ($createsAdded -gt 0) {
    try { Queue-RebuildVisibleRows } catch {}
  }
  Refresh-UI
  if ($missing.Count -gt 0) {
    $lines = @()
    foreach ($m in ($missing | Select-Object -First 10)) {
      $lines += ("{0} :: {1}" -f $m.Action, $m.OriginalPath)
    }
    if ($missing.Count -gt 10) { $lines += "... (more omitted)" }
    [System.Windows.MessageBox]::Show(
      ("Pending states loaded.`nApplied: {0}`nMissing: {1}`nSkipped: {2}`n`nFirst missing:`n{3}" -f `
        $matched, $missing.Count, $skipped, ($lines -join "`n")),
      "Load Pending States"
    ) | Out-Null
  } else {
    [System.Windows.MessageBox]::Show(
      ("Pending states loaded.`nApplied: {0}`nSkipped: {1}" -f $matched, $skipped),
      "Load Pending States"
    ) | Out-Null
  }
}

function Load-ProfileFile {
  param([Parameter(Mandatory=$true)][string]$Path)
  if (-not (Test-Path -LiteralPath $Path)) { throw "Profile file not found: $Path" }
  $raw = Get-Content -LiteralPath $Path -Raw -ErrorAction Stop
  $obj = $raw | ConvertFrom-Json -ErrorAction Stop
  if (-not $obj.Entries) { throw "Invalid profile: missing Entries" }
  $entries = @()
  foreach ($e in $obj.Entries) {
    $pendingIconIdx = 0
    try { $pendingIconIdx = [int](Get-PropString -Obj $e -Names @('PendingIconIndex') -Fallback '0') } catch { $pendingIconIdx = 0 }
    $createIconIdx = 0
    try { $createIconIdx = [int](Get-PropString -Obj $e -Names @('CreateIconIndex') -Fallback '0') } catch { $createIconIdx = 0 }
    $entries += [pscustomobject]@{
      Key              = [string](Get-PropString -Obj $e -Names @('Key') -Fallback '')
      Scope            = [string](Get-PropString -Obj $e -Names @('Scope') -Fallback '')
      OriginalPath     = Normalize-Path ([string](Get-PropString -Obj $e -Names @('OriginalPath') -Fallback ''))
      Type             = [string](Get-PropString -Obj $e -Names @('Type') -Fallback '')
      Action           = [string](Get-PropString -Obj $e -Names @('Action') -Fallback '')
      NewName          = [string](Get-PropString -Obj $e -Names @('NewName','Name') -Fallback '')
      NewPath          = Normalize-Path ([string](Get-PropString -Obj $e -Names @('NewPath','Path') -Fallback ''))
      PendingIconPath  = Normalize-Path ([string](Get-PropString -Obj $e -Names @('PendingIconPath') -Fallback ''))
      PendingIconIndex = [int]$pendingIconIdx
      CreateKind       = [string](Get-PropString -Obj $e -Names @('CreateKind') -Fallback '')
      CreateTargetPath = Normalize-Path ([string](Get-PropString -Obj $e -Names @('CreateTargetPath','Target') -Fallback ''))
      CreateIconPath   = Normalize-Path ([string](Get-PropString -Obj $e -Names @('CreateIconPath') -Fallback ''))
      CreateIconIndex  = [int]$createIconIdx
    }
  }
  # Merge sidecar pending-create state from "Pending Items" storage.
  $sidecarCreates = @(Load-PendingCreateStateForProfile -ProfilePath $Path)
  if ($sidecarCreates.Count -gt 0) {
    $createSeen = @{}
    foreach ($it in @($entries)) {
      if (-not $it) { continue }
      if ([string](Get-PropString -Obj $it -Names @('Action') -Fallback '') -ne 'Create') { continue }
      $cp = Normalize-Path ([string](Get-PropString -Obj $it -Names @('NewPath','Path') -Fallback ''))
      $ck = [string](Get-PropString -Obj $it -Names @('CreateKind','Type') -Fallback '')
      if (-not [string]::IsNullOrWhiteSpace($cp)) { $createSeen[($ck + '|' + $cp.ToLowerInvariant())] = $true }
    }
    foreach ($c in @($sidecarCreates)) {
      if (-not $c) { continue }
      $cp = Normalize-Path ([string](Get-PropString -Obj $c -Names @('NewPath','Path') -Fallback ''))
      $ck = [string](Get-PropString -Obj $c -Names @('CreateKind','Type') -Fallback '')
      if ([string]::IsNullOrWhiteSpace($cp)) { continue }
      $sig = ($ck + '|' + $cp.ToLowerInvariant())
      if ($createSeen.ContainsKey($sig)) { continue }
      $createSeen[$sig] = $true
      $cCreateIconIdx = 0
      try { $cCreateIconIdx = [int](Get-PropString -Obj $c -Names @('CreateIconIndex') -Fallback '0') } catch { $cCreateIconIdx = 0 }
      $entries += [pscustomobject]@{
        Key              = ''
        Scope            = [string](Get-PropString -Obj $c -Names @('Scope') -Fallback 'CurrentUser')
        OriginalPath     = Normalize-Path ([string](Get-PropString -Obj $c -Names @('OriginalPath','Path') -Fallback ''))
        Type             = [string](Get-PropString -Obj $c -Names @('Type') -Fallback '')
        Action           = 'Create'
        NewName          = [string](Get-PropString -Obj $c -Names @('NewName','Name') -Fallback '')
        NewPath          = [string]$cp
        PendingIconPath  = ''
        PendingIconIndex = 0
        CreateKind       = [string](Get-PropString -Obj $c -Names @('CreateKind') -Fallback '')
        CreateTargetPath = Normalize-Path ([string](Get-PropString -Obj $c -Names @('CreateTargetPath','Target') -Fallback ''))
        CreateIconPath   = Normalize-Path ([string](Get-PropString -Obj $c -Names @('CreateIconPath') -Fallback ''))
        CreateIconIndex  = [int]$cCreateIconIdx
      }
    }
  }
  Apply-ProfileEntriesToMock -Entries $entries
}

function Save-ProfileFile {
  param([Parameter(Mandatory=$true)][string]$Path)
  $entries = @(Collect-ProfileEntries)
  $pendingCreates = @(Collect-PendingCreateProfileEntries)
  if ($entries.Length -eq 0 -and $pendingCreates.Length -gt 0) {
    [System.Windows.MessageBox]::Show(
      "Pending actions can only be saved when they reference an existing item, therefore the program cannot save pending 'created' yet. Please commit created items first.",
      "Save Pending States"
    ) | Out-Null
    return
  }
  if ($entries.Length -eq 0 -and $pendingCreates.Length -eq 0) {
    [System.Windows.MessageBox]::Show("No pending states to save.", "Save Pending States") | Out-Null
    return
  }
  Save-PlanJson -Path $Path -Payload (New-PlanPayload -Entries $entries)
  $pendingState = Save-PendingCreateStateForProfile -ProfilePath $Path
  [System.Windows.MessageBox]::Show(
    ("Saved pending states with {0} entries and {1} pending creates.`n`nState: {2}`nCreates: {3}" -f `
      $entries.Count, $pendingCreates.Count, $Path, [string](Get-PropString -Obj $pendingState -Names @('Path') -Fallback '')),
    "Save Pending States"
  ) | Out-Null
}

if ($saveProfileBtn) {
  $saveProfileBtn.Add_Click({
    End-GridEditTransaction
    try {
      $suggestedName = ("user_{0}.zip" -f (Get-BackupStamp))
      $backupsRoot = Get-BackupsRoot
      $targetZipPath = $null
      $saveDlg = New-Object System.Windows.Forms.SaveFileDialog
      $saveDlg.Title = "Create Backup Snapshot"
      $saveDlg.Filter = "Backup Archive (*.zip)|*.zip|All files (*.*)|*.*"
      $saveDlg.AddExtension = $true
      $saveDlg.DefaultExt = "zip"
      $saveDlg.OverwritePrompt = $true
      $saveDlg.InitialDirectory = $backupsRoot
      $saveDlg.FileName = $suggestedName
      $dr = $saveDlg.ShowDialog()
      if ($dr -ne [System.Windows.Forms.DialogResult]::OK) { return }
      $targetZipPath = Normalize-Path ([string]$saveDlg.FileName)
      if ([string]::IsNullOrWhiteSpace($targetZipPath)) { return }

      $targetZipDir = Split-Path -Path $targetZipPath -Parent
      if ([string]::IsNullOrWhiteSpace($targetZipDir)) { throw "Invalid backup destination." }
      if (-not (Test-Path -LiteralPath $targetZipDir -PathType Container)) {
        New-Item -ItemType Directory -Path $targetZipDir -Force | Out-Null
      }

      $rootName = ''
      try { $rootName = [IO.Path]::GetFileNameWithoutExtension($targetZipPath) } catch { $rootName = '' }
      if ([string]::IsNullOrWhiteSpace($rootName)) { $rootName = ("user_{0}" -f (Get-BackupStamp)) }
      $backupRoot = New-BackupFolder -Category Manual -Prefix "user" -Name $rootName

      $bundle = Write-FullSnapshotBundle -BackupRoot $backupRoot
      $finalizedBackup = $null
      try { $finalizedBackup = Finalize-BackupArchivePackage -BackupRoot $backupRoot -DeleteSourceRootOnSuccess } catch { $finalizedBackup = $null }
      $archiveDisplay = ''
      try {
        if ($finalizedBackup -and -not [string]::IsNullOrWhiteSpace([string]$finalizedBackup.ArchivePath)) {
          $archiveDisplay = [string]$finalizedBackup.ArchivePath
        } else {
          $archiveDisplay = [string]$bundle.ArchivePath
        }
      } catch { $archiveDisplay = '' }
      try {
        if (-not [string]::IsNullOrWhiteSpace($archiveDisplay)) {
          $archiveActual = Normalize-Path $archiveDisplay
          if (-not [string]::IsNullOrWhiteSpace($archiveActual) -and (Test-Path -LiteralPath $archiveActual -PathType Leaf)) {
            if (-not $archiveActual.Equals($targetZipPath, [StringComparison]::OrdinalIgnoreCase)) {
              if (Test-Path -LiteralPath $targetZipPath -PathType Leaf) {
                Remove-Item -LiteralPath $targetZipPath -Force -ErrorAction SilentlyContinue
              }
              Move-Item -LiteralPath $archiveActual -Destination $targetZipPath -Force -ErrorAction Stop
            }
            $archiveDisplay = [string]$targetZipPath
          }
        }
      } catch {
        [System.Windows.MessageBox]::Show(
          ("Backup archive was created but could not be moved to selected location.`n`nSelected: " + [string]$targetZipPath + "`nArchive: " + [string]$archiveDisplay + "`nError: " + $_.Exception.Message),
          "Backup Move Warning"
        ) | Out-Null
      }
      if ([string]::IsNullOrWhiteSpace($archiveDisplay)) { $archiveDisplay = '(not created)' }
      $finalizeWarn = ''
      try { if ($finalizedBackup -and -not [string]::IsNullOrWhiteSpace([string]$finalizedBackup.Error)) { $finalizeWarn = [string]$finalizedBackup.Error } } catch {}

      if ($bundle.Errors.Count -gt 0) {
        $errText = ($bundle.Errors | Select-Object -First 10) -join "`n"
        if ($bundle.Errors.Count -gt 10) { $errText += "`n... (more errors omitted)" }
        if (-not [string]::IsNullOrWhiteSpace($finalizeWarn)) {
          $errText += ("`nBackup archive finalize warning: " + $finalizeWarn)
        }

        [System.Windows.MessageBox]::Show(
          "Manual backup snapshot created.`nCopied: $($bundle.Copied)`nArchive: $archiveDisplay`nErrors: $($bundle.Errors.Count)`n`n$errText",
          "Backup Snapshot Completed With Errors"
        ) | Out-Null
      } else {
        $okText = "Manual backup snapshot created.`nCopied: $($bundle.Copied)`nArchive: $archiveDisplay"
        if (-not [string]::IsNullOrWhiteSpace($finalizeWarn)) { $okText += ("`nFinalize warning: " + $finalizeWarn) }
        [System.Windows.MessageBox]::Show(
          $okText,
          "Backup Snapshot Completed"
        ) | Out-Null
      }
    } catch {
      [System.Windows.MessageBox]::Show($_.Exception.Message, "Backup Snapshot Error") | Out-Null
    }
  })
}

if ($savePendingStatesBtn) {
  $savePendingStatesBtn.Add_Click({
    End-GridEditTransaction
    try {
      $dlg = New-Object System.Windows.Forms.SaveFileDialog
      $dlg.Title = "Save Pending States"
      $dlg.Filter = "Pending States (*.json)|*.json|Legacy Pending States (*.startmenu.json)|*.startmenu.json|All files (*.*)|*.*"
      $dlg.AddExtension = $true
      $dlg.DefaultExt = "json"
      $dlg.FileName = ("pending_{0}.json" -f (Get-BackupStamp))
      $dr = $dlg.ShowDialog()
      if ($dr -eq [System.Windows.Forms.DialogResult]::OK) {
        Save-ProfileFile -Path $dlg.FileName
      }
    } catch {
      [System.Windows.MessageBox]::Show($_.Exception.Message, "Save Pending States Error") | Out-Null
    }
  })
}

if ($loadProfileBtn) {
  $loadProfileBtn.Add_Click({
    End-GridEditTransaction
    try {
      $dlg = New-Object System.Windows.Forms.OpenFileDialog
      $dlg.Title = "Load Pending States"
      $dlg.Filter = "Pending States (*.startmenu.json;*.json)|*.startmenu.json;*.json|All files (*.*)|*.*"
      $dlg.Multiselect = $false

      $dr = $dlg.ShowDialog()
      if ($dr -eq [System.Windows.Forms.DialogResult]::OK) {
        Load-ProfileFile -Path $dlg.FileName
      }
    } catch {
      [System.Windows.MessageBox]::Show($_.Exception.Message, "Load Pending States Error") | Out-Null
    }
  })
}

# ==============================================================================
# Restore Backup button (ZIP picker only)
# ==============================================================================
if ($restoreBackupBtn) {
  $restoreBackupBtn.Add_Click({
    End-GridEditTransaction
    try {

      # ZIP-only restore selection.
      $pickedZip = Select-BackupArchiveFile -InitialPath (Get-BackupsRoot)
      if ([string]::IsNullOrWhiteSpace([string]$pickedZip)) { return }
      $result = $null
      Invoke-WithBusyOverlay -Action {
        $result = Restore-FromBackupArchive -ArchivePath $pickedZip
        # refresh UI inventory
        $script:StartupInventory = @(Get-Inventory)
        try { Invalidate-LaunchDuplicateCaches } catch {}
        $model = Build-Model -inventoryItems $script:StartupInventory
        $script:TreeRoots = $model.TreeRoots
        $script:NodeMap   = $model.NodeMap
        $tree.ItemsSource = $null
        $tree.ItemsSource = $script:TreeRoots
        $grid.ItemsSource = $null
        $script:CurrentNode = $null
        $script:CurrentView = $null
        Select-DefaultStartNode
      }
      if (-not $result) { return }
      $restoredDiff = 0
      try { $restoredDiff = [int]$result.Restored - [int]$result.PreCopied } catch { $restoredDiff = [int]$result.Restored }
      $restoreLines = New-Object System.Collections.Generic.List[string]
      if ($restoredDiff -gt 0) { [void]$restoreLines.Add(("Restored: " + [string]$restoredDiff)) }
      if ([int]$result.Removed -gt 0) { [void]$restoreLines.Add(("Removed: " + [string]$result.Removed)) }
      $restoreBackup = [string]$result.PreRestore
      if ([string]::IsNullOrWhiteSpace($restoreBackup)) { $restoreBackup = '(none)' }
      [void]$restoreLines.Add(("Backup: " + $restoreBackup))
      if ($restoreLines.Count -eq 1) { $restoreLines.Insert(0, 'No changes were restored.') }
      if ($result.Errors.Count -gt 0) {
        $errText = ($result.Errors | Select-Object -First 10) -join "`n"
        if ($result.Errors.Count -gt 10) { $errText += "`n... (more errors omitted)" }
        [System.Windows.MessageBox]::Show(
          (($restoreLines -join "`n") + "`nErrors: $($result.Errors.Count)`n`n$errText"),
          "Restore Completed With Errors"
        ) | Out-Null
      } else {
        [System.Windows.MessageBox]::Show(
          ($restoreLines -join "`n"),
          "Restore Completed"
        ) | Out-Null
      }

    } catch {
      [System.Windows.MessageBox]::Show($_.Exception.Message, "Restore Backup Error") | Out-Null
    }
  })
}

function Invoke-ThemeVisualSyncPass {
  try {
    try { $script:IsLightAccentOverrideActive = Get-IsSystemLightMode } catch {}
    try { Refresh-SelectNameAccentStyle } catch {}
    try { Sync-ThemeContrastResources -Window $window -IsLight (Get-IsSystemLightMode) } catch {}
    try { Apply-MidGridScrollBarAccentStyle -ScrollBar $script:GridMidScrollBar -AccentBrush $script:SelectNameAccentBrushExact } catch {}
    try { if ($grid) { $grid.Items.Refresh() } } catch {}
    try { if ($grid) { $grid.InvalidateVisual(); $grid.UpdateLayout() } } catch {}
    try { if ($window) { $window.InvalidateVisual(); $window.UpdateLayout() } } catch {}
  } catch {}
}

function Show-ThemeChangedRestartHintIfNeeded {
  try {
    $allowThemeDialog = $false
    try { $allowThemeDialog = [bool](Get-IsWindowsBuildAbove1809Runtime) } catch { $allowThemeDialog = $false }
    if (-not $allowThemeDialog) { return }
    $currentKey = Get-ThemeModeStateKeyRaw
    if ([string]::IsNullOrWhiteSpace([string]$currentKey)) { return }
    if ([string]::IsNullOrWhiteSpace([string]$script:LastKnownThemeModeStateKey)) {
      $script:LastKnownThemeModeStateKey = [string]$currentKey
      try { $script:LastKnownSystemLightMode = Get-IsSystemLightModeRaw } catch {}
      return
    }
    if ([string]$script:LastKnownThemeModeStateKey -ne [string]$currentKey) {
      [void](Show-ThemeChangedDialogAndGetChoice)
      $script:LastKnownThemeModeStateKey = [string]$currentKey
      try { $script:LastKnownSystemLightMode = Get-IsSystemLightModeRaw } catch {}
    }
  } catch {}
}

function Show-ThemeChangedDialogAndGetChoice {
  try {
    [xml]$dlgXaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Theme Change Detected"
        SizeToContent="WidthAndHeight"
        ResizeMode="NoResize"
        WindowStartupLocation="CenterOwner"
        WindowStyle="SingleBorderWindow"
        ShowInTaskbar="False"
        Topmost="True">
  <Grid Margin="14" MinWidth="350">
    <Grid.RowDefinitions>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="12"/>
      <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>
    <TextBlock Grid.Row="0"
               TextWrapping="Wrap"
               MaxWidth="350"
               Text="Windows theme changed while the app was running. Intefrace colors may be inconsistent until you restart the app."/>
    <StackPanel Grid.Row="2" Orientation="Horizontal" HorizontalAlignment="Right">
      <Button Name="OkBtn" Content="OK" MinWidth="75"/>
    </StackPanel>
  </Grid>
</Window>
"@
    $reader = New-Object System.Xml.XmlNodeReader $dlgXaml
    $dlg = [Windows.Markup.XamlReader]::Load($reader)
    if ($window) { try { $dlg.Owner = $window } catch {} }
    $script:__theme_dialog_choice = 'OK'
    $okBtn = $dlg.FindName('OkBtn')
    if ($okBtn) {
      $okBtn.Add_Click({
        try { $script:__theme_dialog_choice = 'OK' } catch {}
        try { $dlg.Close() } catch {}
      })
    }
    try { $null = $dlg.ShowDialog() } catch { try { $dlg.Show() | Out-Null } catch {} }
    $result = 'OK'
    try { $result = [string]$script:__theme_dialog_choice } catch { $result = 'OK' }
    Remove-Variable -Scope Script -Name __theme_dialog_choice -ErrorAction SilentlyContinue
    return $result
  } catch {
    return 'OK'
  }
}

function Get-RelaunchPowerShellExe {
  try {
    $ps = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
    if (Test-Path -LiteralPath $ps) { return $ps }
  } catch {}
  return 'powershell.exe'
}

function Get-CurrentScriptPathForRelaunch {
  try {
    if (-not [string]::IsNullOrWhiteSpace([string]$script:SelfScriptPath) -and (Test-Path -LiteralPath $script:SelfScriptPath)) {
      return [string]$script:SelfScriptPath
    }
  } catch {}
  try {
    if (-not [string]::IsNullOrWhiteSpace([string]$PSCommandPath) -and (Test-Path -LiteralPath $PSCommandPath)) {
      return [string]$PSCommandPath
    }
  } catch {}
  try {
    $p = [string]$MyInvocation.MyCommand.Path
    if (-not [string]::IsNullOrWhiteSpace($p) -and (Test-Path -LiteralPath $p)) { return $p }
  } catch {}
  return ''
}

function Get-RelaunchLauncherPath {
  param(
    [Parameter(Mandatory=$true)][string]$ScriptPath
  )
  try {
    $dir = Split-Path -Parent $ScriptPath
    if ([string]::IsNullOrWhiteSpace($dir)) { $dir = $PSScriptRoot }
    if ([string]::IsNullOrWhiteSpace($dir)) { return '' }
    $base = ''
    try { $base = [System.IO.Path]::GetFileNameWithoutExtension($ScriptPath) } catch { $base = '' }
    if ([string]::IsNullOrWhiteSpace($base)) { $base = 'StartMenuTool' }
    return (Join-Path $dir ($base + '.launcher.cmd'))
  } catch {
    return ''
  }
}

function Ensure-RelaunchLauncherFile {
  param(
    [Parameter(Mandatory=$true)][string]$ScriptPath,
    [Parameter(Mandatory=$true)][string]$WorkingDirectory
  )
  $launcherPath = Get-RelaunchLauncherPath -ScriptPath $ScriptPath
  if ([string]::IsNullOrWhiteSpace($launcherPath)) {
    throw "Unable to determine launcher path."
  }
  $hostExe = Get-RelaunchPowerShellExe
  $safeHost = [string]$hostExe
  $scriptFile = ''
  try { $scriptFile = [System.IO.Path]::GetFileName([string]$ScriptPath) } catch { $scriptFile = '' }
  if ([string]::IsNullOrWhiteSpace($scriptFile)) { throw "Unable to resolve script file name for launcher." }
  $body = @(
    '@echo off'
    'setlocal'
    ('set "PS_EXE={0}"' -f $safeHost)
    'if not exist "%PS_EXE%" set "PS_EXE=powershell.exe"'
    'set "BASE_DIR=%~dp0"'
    ('set "SCRIPT_PATH=%BASE_DIR%{0}"' -f $scriptFile)
    'set "SMLT_HIDE_CONSOLE=1"'
    'if not exist "%SCRIPT_PATH%" exit /b 2'
    'start "" /D "%BASE_DIR%" "%PS_EXE%" -NoProfile -STA -ExecutionPolicy Bypass -File "%SCRIPT_PATH%"'
    'if errorlevel 1 exit /b 3'
    'exit /b 0'
  ) -join "`r`n"
  Set-Content -LiteralPath $launcherPath -Value $body -Encoding ASCII -Force
  return $launcherPath
}

function Invoke-BackupAndRelaunchAfterThemeChange {
  try {
    End-GridEditTransaction
    $backupRoot = New-BackupFolder -Category Auto -Prefix "auto"
    $bundle = Write-FullSnapshotBundle -BackupRoot $backupRoot
    $themeArchivePath = ''
    try {
      $finalized = Finalize-BackupArchivePackage -BackupRoot $backupRoot -DeleteSourceRootOnSuccess
      if ($finalized -and -not [string]::IsNullOrWhiteSpace([string]$finalized.ArchivePath)) { $themeArchivePath = [string]$finalized.ArchivePath }
      if ([string]::IsNullOrWhiteSpace($themeArchivePath)) { $themeArchivePath = [string]$bundle.ArchivePath }
    } catch {}
    $scriptPath = Get-CurrentScriptPathForRelaunch
    if ([string]::IsNullOrWhiteSpace($scriptPath)) {
      throw "Unable to determine script path for relaunch."
    }
    try { $script:SelfScriptPath = [string]$scriptPath } catch {}
    $wd = $PSScriptRoot
    if ([string]::IsNullOrWhiteSpace($wd)) { $wd = (Split-Path -Parent $scriptPath) }
    $launcherPath = Ensure-RelaunchLauncherFile -ScriptPath $scriptPath -WorkingDirectory $wd
    if ([string]::IsNullOrWhiteSpace([string]$launcherPath) -or -not (Test-Path -LiteralPath $launcherPath)) {
      throw "Relaunch launcher file was not created."
    }
    $proc = $null
    try {
      $proc = Start-Process -FilePath 'cmd.exe' -WorkingDirectory $wd -ArgumentList @('/c', ('"{0}"' -f $launcherPath)) -PassThru -ErrorAction Stop
    } catch {
      $proc = $null
    }
    if ($proc -and ($proc.Id -gt 0)) {
      try { $window.Close() } catch {}
      return
    }
    throw "Relaunch process did not start."
  } catch {
    [System.Windows.MessageBox]::Show(
      ("Backup/relaunch failed: {0}" -f [string]$_.Exception.Message),
      "Relaunch Error",
      [System.Windows.MessageBoxButton]::OK,
      [System.Windows.MessageBoxImage]::Error
    ) | Out-Null
  }
}

function Invoke-LiveRefreshFlow {
  End-GridEditTransaction
  try {
    # Re-read theme/accent visuals up front.
    Invoke-ThemeVisualSyncPass
    # IMPORTANT:
    # Refresh button is a FRONTEND visual refresh only.
    # It must NOT discard pending mock changes or rebuild from disk.
    if ($script:CurrentNode) {
      try {
        Rebuild-VisibleRows
      } catch {
        try { Queue-RebuildVisibleRows } catch {}
      }
    } else {
      # No current node bound yet: keep existing behavior of selecting default.
      Select-DefaultStartNode
    }
    Refresh-UI
    # Re-apply mode-dependent visuals after data/UI refresh too.
    Invoke-ThemeVisualSyncPass
    try {
      # One deferred pass catches late registry/theme write timing.
      $window.Dispatcher.BeginInvoke([Action]{
        try { Invoke-ThemeVisualSyncPass } catch {}
      }, [System.Windows.Threading.DispatcherPriority]::Background) | Out-Null
    } catch {}
    # Show dialog after refresh so user can evaluate visuals first.
    try { Show-ThemeChangedRestartHintIfNeeded } catch {}
  } catch {
    [System.Windows.MessageBox]::Show([string]$_.Exception.Message, "Refresh Error", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) | Out-Null
  }
}

function Invoke-ReloadStartMenuModelAfterFilesystemChange {
  try {
    Clear-VisualProxyCaches
    $script:StartupInventory = @(Get-Inventory)
    try { Invalidate-LaunchDuplicateCaches } catch {}
    $model = Build-Model -inventoryItems $script:StartupInventory
    $script:TreeRoots = $model.TreeRoots
    $script:NodeMap   = $model.NodeMap
    $tree.ItemsSource = $null
    $tree.ItemsSource = $script:TreeRoots
    $script:UndoStack.Clear()
    $script:RedoStack.Clear()
    $grid.ItemsSource = $null
    $script:CurrentNode = $null
    $script:CurrentView = $null
    Select-DefaultStartNode
  } catch {}
}

function Show-PrepareStartMenuChoiceDialog {
  param([System.Windows.Window]$OwnerWindow = $null)
  try {
    [xml]$x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Prepare Start Menu"
        WindowStartupLocation="CenterOwner"
        ResizeMode="NoResize"
        SizeToContent="WidthAndHeight"
        ShowInTaskbar="False">
  <Border Padding="14">
    <Grid Width="400">
      <Grid.RowDefinitions>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="Auto"/>
      </Grid.RowDefinitions>
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="*"/>
        <ColumnDefinition Width="16"/>
        <ColumnDefinition Width="*"/>
      </Grid.ColumnDefinitions>
      <TextBlock Grid.Row="0" Grid.ColumnSpan="3" TextWrapping="Wrap" Margin="0,0,0,12"
                 Text="Choose folders to prepare. A backup snapshot is created first before any folder is modified."/>
      <Border Grid.Row="1" Grid.Column="0" BorderBrush="#BEBEBE" BorderThickness="1" CornerRadius="3" Padding="10">
        <StackPanel>
          <TextBlock TextWrapping="Wrap" Margin="0,0,0,8">Windows Accessories&#x0a;Windows Ease of Access&#x0a;Windows PowerShell&#x0a;Windows System</TextBlock>
          <Button Name="PrepareCoreBtn" Content="Continue" MinWidth="60" HorizontalAlignment="Center"/>
        </StackPanel>
      </Border>
      <Border Grid.Row="1" Grid.Column="2" BorderBrush="#BEBEBE" BorderThickness="1" CornerRadius="3" Padding="10">
        <StackPanel>
          <TextBlock TextWrapping="Wrap" Margin="0,0,0,8">Windows Administrative Tools</TextBlock>
          <Button Name="PrepareAdminBtn" Content="*Continue" MinWidth="60" HorizontalAlignment="Center" Margin="0,36,0,0"/>
        </StackPanel>
      </Border>
      <StackPanel Grid.Row="2" Grid.ColumnSpan="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,12,0,0">
        <Button Name="CancelBtn" Content="Cancel" MinWidth="50"/>
      </StackPanel>
    </Grid>
  </Border>
</Window>
"@
    $reader = New-Object System.Xml.XmlNodeReader $x
    $dlg = [Windows.Markup.XamlReader]::Load($reader)
    if ($OwnerWindow) { try { $dlg.Owner = $OwnerWindow } catch {} }
    $core = $dlg.FindName("PrepareCoreBtn")
    $adm  = $dlg.FindName("PrepareAdminBtn")
    $cancel = $dlg.FindName("CancelBtn")
    if (-not $core -or -not $adm -or -not $cancel) { return '' }
    try { $dlg.Tag = '' } catch {}
    $core.Add_Click({
      try { $dlg.Tag = 'Core' } catch {}
      try { $dlg.DialogResult = $true } catch {}
      try { $dlg.Close() } catch {}
    })
    $adm.Add_Click({
      try { $dlg.Tag = 'Admin' } catch {}
      try { $dlg.DialogResult = $true } catch {}
      try { $dlg.Close() } catch {}
    })
    $cancel.Add_Click({
      try { $dlg.Tag = '' } catch {}
      try { $dlg.DialogResult = $false } catch {}
      try { $dlg.Close() } catch {}
    })
    [void]$dlg.ShowDialog()
    try { return [string]$dlg.Tag } catch { return '' }
  } catch {
    return ''
  }
}

