function Get-AdministrativeToolsSourceFolders {
  $legacy = [string](Get-LegacyAdministrativeToolsFolderPath)
  if ([string]::IsNullOrWhiteSpace($legacy)) { return @() }
  if (-not (Test-Path -LiteralPath $legacy -PathType Container)) { return @() }
  return @(
    [pscustomobject]@{
      Scope = 'AllUsers'
      Path  = $legacy
      Name  = 'Administrative Tools'
    }
  )
}

function Ensure-WindowsAdministrativeToolsShortcutSeed {
  param([Parameter(Mandatory=$true)][string]$FolderPath)
  $created = 0
  $errors = @()
  try {
    if (-not (Test-Path -LiteralPath $FolderPath -PathType Container)) {
      New-Item -ItemType Directory -Path $FolderPath -Force | Out-Null
    }
    $wsh = New-Object -ComObject WScript.Shell
    foreach ($seed in @(Get-WindowsAdministrativeToolsShortcutSeed)) {
      try {
        if (-not $seed) { continue }
        $name = [string]$seed.Name
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        $dest = Join-Path $FolderPath $name
        if (Test-Path -LiteralPath $dest -PathType Leaf) { continue }
        $target = [Environment]::ExpandEnvironmentVariables([string]$seed.Target)
        if ([string]::IsNullOrWhiteSpace($target)) { continue }
        $sc = $wsh.CreateShortcut($dest)
        $sc.TargetPath = $target
        $args = [string]$seed.Args
        if (-not [string]::IsNullOrWhiteSpace($args)) { $sc.Arguments = $args }
        try {
          $wd = Split-Path -Path $target -Parent
          if (-not [string]::IsNullOrWhiteSpace($wd)) { $sc.WorkingDirectory = $wd }
        } catch {}
        try { $sc.IconLocation = ($target + ",0") } catch {}
        $sc.Save()
        $created++
      } catch {
        $errors += ("seed create failed: " + [string]$seed.Name + " :: " + [string]$_.Exception.Message)
      }
    }
  } catch {
    $errors += [string]$_.Exception.Message
  }
  return [pscustomobject]@{
    Created = $created
    Errors  = @($errors)
  }
}

function Invoke-PrepareWindowsAdministrativeTools {
  param([string]$BackupRoot = $null)
  $errors = @()
  $moved = 0
  $skipped = 0
  $currentUserShortcutsRemoved = 0
  $allUsersRoot = [string]$scopeRoots['AllUsers']
  if ([string]::IsNullOrWhiteSpace($allUsersRoot) -or -not (Test-Path -LiteralPath $allUsersRoot -PathType Container)) {
    throw "All Users Start Menu root is missing or inaccessible."
  }
  $dest = [string](Get-PreparedAdministrativeToolsFolderPath)
  $legacy = [string](Get-LegacyAdministrativeToolsFolderPath)
  if ([string]::IsNullOrWhiteSpace($legacy)) {
    throw "Administrative Tools legacy path is unavailable."
  }
  if (-not (Test-Path -LiteralPath $legacy -PathType Container)) {
    throw ("Legacy Administrative Tools folder not found: " + $legacy)
  }
  try {
    if (-not (Test-Path -LiteralPath $dest -PathType Container)) {
      New-Item -ItemType Directory -Path $dest -Force | Out-Null
    }
  } catch {
    throw ("Failed to create destination folder: " + $dest + " :: " + [string]$_.Exception.Message)
  }

  foreach ($src in @(Get-AdministrativeToolsSourceFolders)) {
    if (-not $src) { continue }
    $srcPath = [string]$src.Path
    if ([string]::IsNullOrWhiteSpace($srcPath)) { continue }
    if (-not (Test-Path -LiteralPath $srcPath -PathType Container)) { continue }
    if (Test-PathEqualsCI -A $srcPath -B $dest) { continue }
    # Move shortcut payload only; never touch desktop.ini or other metadata files.
    foreach ($file in @(Get-ChildItem -LiteralPath $srcPath -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Extension -match '^\.(lnk|url)$' })) {
      if (-not $file) { continue }
      try {
        $baseName = [string]$file.Name
        $dstPath = Join-Path $dest $baseName
        if (Test-Path -LiteralPath $dstPath -PathType Leaf) {
          $nm = [System.IO.Path]::GetFileNameWithoutExtension($baseName)
          $ext = [System.IO.Path]::GetExtension($baseName)
          $i = 2
          do {
            $cand = ("{0} ({1}){2}" -f $nm, $i, $ext)
            $dstPath = Join-Path $dest $cand
            $i++
          } while (Test-Path -LiteralPath $dstPath -PathType Leaf)
        }
        Move-Item -LiteralPath ([string]$file.FullName) -Destination $dstPath -Force -ErrorAction Stop
        $moved++
      } catch {
        $errors += ("move failed: " + [string]$file.FullName + " :: " + [string]$_.Exception.Message)
      }
    }
    try {
      $remaining = @(Get-ChildItem -LiteralPath $srcPath -Force -ErrorAction SilentlyContinue)
      if ($remaining.Count -eq 0) {
        # Keep the legacy folder path but leave it empty; user can still restore contents later.
        $skipped++
      }
    } catch {}
  }

  # Cleanup pass: remove shortcut payload from CurrentUser "Windows Administrative Tools"
  # while preserving desktop.ini and any non-shortcut files.
  try {
    $currentUserAdminPath = [string](Get-CurrentUserAdministrativeToolsFolderPath)
    if (-not [string]::IsNullOrWhiteSpace($currentUserAdminPath) -and (Test-Path -LiteralPath $currentUserAdminPath -PathType Container)) {
      foreach ($f in @(Get-ChildItem -LiteralPath $currentUserAdminPath -File -Force -ErrorAction SilentlyContinue | Where-Object {
        $n = ''
        try { $n = [string]$_.Name } catch { $n = '' }
        if ($n -match '^(?i)desktop\.ini$') { return $false }
        return ([string]$_.Extension -match '^\.(lnk|url)$')
      })) {
        if (-not $f) { continue }
        try {
          Remove-Item -LiteralPath ([string]$f.FullName) -Force -ErrorAction Stop
          $currentUserShortcutsRemoved++
        } catch {
          $errors += ("current-user cleanup failed: " + [string]$f.FullName + " :: " + [string]$_.Exception.Message)
        }
      }
    }
  } catch {
    $errors += ("current-user admin-tools cleanup failed: " + [string]$_.Exception.Message)
  }

  try { Invoke-StartMenuRefresh -TouchedFolder $allUsersRoot } catch {}
  try { if (-not [string]::IsNullOrWhiteSpace([string]$scopeRoots['CurrentUser'])) { Invoke-StartMenuRefresh -TouchedFolder ([string]$scopeRoots['CurrentUser']) } } catch {}
  try { Stop-Process -Name StartMenuExperienceHost -Force -ErrorAction SilentlyContinue } catch {}
  try { Set-LegacyAdminToolsHideFlag -Hidden $true } catch {}

  return [pscustomobject]@{
    Moved      = $moved
    Seeded     = 0
    Skipped    = $skipped
    Errors     = @($errors)
    BackupRoot = $BackupRoot
    Destination= $dest
    LegacyPath = $legacy
    CurrentUserShortcutsRemoved = $currentUserShortcutsRemoved
  }
}

function Try-RenameAllUsersAdministrativeToolsCase {
  try {
    # Best-effort only (no force, no verification): mimic a manual rename attempt
    # under C:\Users\All Users\...\Programs for the displayed folder name.
    $allUsersPrograms = 'C:\Users\All Users\Microsoft\Windows\Start Menu\Programs'
    if (-not (Test-Path -LiteralPath $allUsersPrograms -PathType Container)) { return }
    foreach ($d in @(Get-ChildItem -LiteralPath $allUsersPrograms -Directory -Force -ErrorAction SilentlyContinue)) {
      if (-not $d) { continue }
      if ([string]$d.Name -ceq 'Windows Administrative Tools') {
        try {
          Rename-Item -LiteralPath ([string]$d.FullName) -NewName 'windows Administrative Tools' -ErrorAction SilentlyContinue
        } catch {}
      }
    }
  } catch {}
}

function Invoke-RestoreWindowsAdministrativeTools {
  $errors = @()
  $movedFromPrepared = 0
  $copiedToCurrentUser = 0
  $deletedPreparedFolder = $false
  $allUsersRoot = [string]$scopeRoots['AllUsers']
  $currentUserPath = [string](Get-CurrentUserAdministrativeToolsFolderPath)
  if ([string]::IsNullOrWhiteSpace($allUsersRoot) -or -not (Test-Path -LiteralPath $allUsersRoot -PathType Container)) {
    throw "All Users Start Menu root is missing or inaccessible."
  }
  $legacy = [string](Get-LegacyAdministrativeToolsFolderPath)
  $prepared = [string](Get-PreparedAdministrativeToolsFolderPath)
  try {
    if (-not (Test-Path -LiteralPath $legacy -PathType Container)) {
      New-Item -ItemType Directory -Path $legacy -Force | Out-Null
    }
  } catch {
    throw ("Failed to create/restore legacy folder: " + $legacy + " :: " + [string]$_.Exception.Message)
  }
  if (Test-Path -LiteralPath $prepared -PathType Container) {
    # Move shortcut payload only; never touch desktop.ini or other metadata files.
    foreach ($file in @(Get-ChildItem -LiteralPath $prepared -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Extension -match '^\.(lnk|url)$' })) {
      if (-not $file) { continue }
      try {
        $dst = Join-Path $legacy ([string]$file.Name)
        if (Test-Path -LiteralPath $dst -PathType Leaf) {
          try { Remove-Item -LiteralPath $dst -Force -ErrorAction Stop } catch {}
        }
        Move-Item -LiteralPath ([string]$file.FullName) -Destination $dst -Force -ErrorAction Stop
        $movedFromPrepared++
      } catch {
        $errors += ("restore move failed: " + [string]$file.FullName + " :: " + [string]$_.Exception.Message)
      }
    }
  }
  try {
    if (Test-Path -LiteralPath $prepared -PathType Container) {
      $left = @()
      try { $left = @(Get-ChildItem -LiteralPath $prepared -Force -ErrorAction SilentlyContinue) } catch { $left = @() }
      if ($left.Count -eq 0) {
        try { Remove-Item -LiteralPath $prepared -Force -ErrorAction Stop } catch {}
        try { $deletedPreparedFolder = (-not (Test-Path -LiteralPath $prepared -PathType Container)) } catch { $deletedPreparedFolder = $false }
      }
    }
  } catch {}
  $seed = Ensure-WindowsAdministrativeToolsShortcutSeed -FolderPath $legacy
  foreach ($er in @($seed.Errors)) { $errors += [string]$er }
  try { Invoke-StartMenuRefresh -TouchedFolder $allUsersRoot } catch {}
  try { if (-not [string]::IsNullOrWhiteSpace([string]$scopeRoots['CurrentUser'])) { Invoke-StartMenuRefresh -TouchedFolder ([string]$scopeRoots['CurrentUser']) } } catch {}
  try { Stop-Process -Name StartMenuExperienceHost -Force -ErrorAction SilentlyContinue } catch {}
  try { Set-LegacyAdminToolsHideFlag -Hidden $true } catch {}
  # Final redundancy step: ensure CurrentUser\Administrative Tools exists and
  # mirrors shortcut payload from ProgramData\Administrative Tools.
  try {
    if (-not [string]::IsNullOrWhiteSpace($currentUserPath)) {
      if (-not (Test-Path -LiteralPath $currentUserPath -PathType Container)) {
        New-Item -ItemType Directory -Path $currentUserPath -Force | Out-Null
      }
      foreach ($file in @(Get-ChildItem -LiteralPath $legacy -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Extension -match '^\.(lnk|url)$' })) {
        if (-not $file) { continue }
        try {
          $dst = Join-Path $currentUserPath ([string]$file.Name)
          Copy-Item -LiteralPath ([string]$file.FullName) -Destination $dst -Force -ErrorAction Stop
          $copiedToCurrentUser++
        } catch {
          $errors += ("copy to CurrentUser failed: " + [string]$file.FullName + " :: " + [string]$_.Exception.Message)
        }
      }
    }
  } catch {
    $errors += ("CurrentUser Administrative Tools sync failed: " + [string]$_.Exception.Message)
  }
  return [pscustomobject]@{
    MovedFromPrepared = $movedFromPrepared
    CopiedToCurrentUser = $copiedToCurrentUser
    DeletedPreparedFolder = [bool]$deletedPreparedFolder
    Seeded    = [int]$seed.Created
    Errors    = @($errors)
    LegacyPath = $legacy
    CurrentUserPath = $currentUserPath
    PreparedPath = $prepared
  }
}

function Invoke-PrepareStartMenuFlow {
  param([switch]$SkipIntro)
  End-GridEditTransaction
  try {
    $choice = ''
    try { $choice = [string](Show-PrepareStartMenuChoiceDialog -OwnerWindow $window) } catch { $choice = '' }
    if ([string]::IsNullOrWhiteSpace($choice)) { return }

    $isCore = ($choice -eq 'Core')
    $isAdmin = ($choice -eq 'Admin')
    if (-not $isCore -and -not $isAdmin) { return }

    if ($isAdmin) {
      $adminWarn = "It is advised to leave this folder untouched: ""preparing"" it will allow for its renaming, edit nested shortcuts, and change their icons, but it will also prevent control panel's Administrative Tools link from accessing that list of tools in the target folder.`n`nIf you chose to continue, the administrative tools list will still be accessible through the Start menu. (This method is not necessary if the goal is only to modify the nested items of this folder)"
      $okAdmin = Show-ContinueCancelDialog -Title "Prepare Windows Administrative Tools" -Message $adminWarn -ContinueText "Continue" -CancelText "Abort"
      if (-not $okAdmin) { return }
    }

    if (-not (Ensure-ElevatedOrPrompt -Reason "Preparing default Start Menu folders requires Administrator.")) { return }
    $backupRoot = New-BackupFolder -Category Auto -Prefix "auto"
    $bundle = Write-FullSnapshotBundle -BackupRoot $backupRoot
    $prep = $null
    if ($isCore) {
      $prep = Invoke-PrepareStartMenu -BackupRoot $backupRoot
    } else {
      $prep = Invoke-PrepareWindowsAdministrativeTools -BackupRoot $backupRoot
    }
    $prepArchivePath = ''
    $prepArchiveWarn = ''
    try {
      $finalizedPrep = Finalize-BackupArchivePackage -BackupRoot $backupRoot -DeleteSourceRootOnSuccess
      if ($finalizedPrep -and -not [string]::IsNullOrWhiteSpace([string]$finalizedPrep.ArchivePath)) { $prepArchivePath = [string]$finalizedPrep.ArchivePath }
      if ([string]::IsNullOrWhiteSpace($prepArchivePath)) { $prepArchivePath = [string]$bundle.ArchivePath }
      if ($finalizedPrep -and -not [string]::IsNullOrWhiteSpace([string]$finalizedPrep.Error)) { $prepArchiveWarn = [string]$finalizedPrep.Error }
    } catch {}
    $prepOk = $false
    try { $prepOk = (@($prep.Errors).Count -eq 0) } catch { $prepOk = $false }
    try {
      if ($isCore) {
        $script:PrepareStartMenuApprovedCoreSession = [bool]$prepOk
      } elseif ($isAdmin) {
        $script:PrepareStartMenuApprovedAdminSession = [bool]$prepOk
      }
      $script:PrepareStartMenuApprovedSession = ([bool]$script:PrepareStartMenuApprovedCoreSession -or [bool]$script:PrepareStartMenuApprovedAdminSession)
    } catch {}
    Invoke-ReloadStartMenuModelAfterFilesystemChange

    $msg = @(
      ("Prepared: " + $(if ($prep.PSObject.Properties.Match('Processed').Count -gt 0) { @($prep.Processed).Count } else { [int]$prep.Moved }))
      ("Skipped: " + $(if ($prep.PSObject.Properties.Match('Skipped').Count -gt 0) { @($prep.Skipped).Count } else { [int]$prep.Seeded }))
      ("Errors: " + @($prep.Errors).Count)
      ("Backup: " + $(if ([string]::IsNullOrWhiteSpace([string]$prepArchivePath)) { $backupRoot } else { $prepArchivePath }))
    ) -join "`n"
    if (@($bundle.Errors).Count -gt 0) {
      $msg += ("`nSnapshot warnings: " + @($bundle.Errors).Count)
    }
    if (-not [string]::IsNullOrWhiteSpace($prepArchiveWarn)) {
      $msg += ("`nBackup archive finalize warning: " + $prepArchiveWarn)
    }
    if ($isAdmin -and @($prep.Errors).Count -eq 0) {
      [System.Windows.MessageBox]::Show(
        "The folder can now accept edits. To restore the original Windows Administrative Tools folder, please visit the [misc.] tab.",
        "Windows Administrative Tools Prepared",
        [System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]::Information
      ) | Out-Null
      return
    }
    if (@($prep.Errors).Count -gt 0) {
      $errText = (@($prep.Errors) | Select-Object -First 10) -join "`n"
      if (@($prep.Errors).Count -gt 10) { $errText += "`n... (more errors omitted)" }
      [System.Windows.MessageBox]::Show(($msg + "`n`n" + $errText), "Prepare Start Menu Completed With Errors") | Out-Null
    } else {
      [System.Windows.MessageBox]::Show($msg, "Prepare Start Menu Completed") | Out-Null
    }
  } catch {
    $m = [string]$_.Exception.Message
    $t = ''
    try { $t = $_.Exception.GetType().FullName } catch {}
    $stack = ''
    try { $stack = [string]$_.ScriptStackTrace } catch {}
    $detail = [string]$m
    if (-not [string]::IsNullOrWhiteSpace($t)) { $detail += ("`n`nType: " + $t) }
    if (-not [string]::IsNullOrWhiteSpace($stack)) { $detail += ("`n`nStack:`n" + $stack) }
    [System.Windows.MessageBox]::Show([string]$detail, "Prepare Start Menu Error", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) | Out-Null
  }
}

