function Get-AppBaseDirectoryPath {
  try {
    $baseDir = ''
    try { $baseDir = [string]$PSScriptRoot } catch { $baseDir = '' }
    if ([string]::IsNullOrWhiteSpace($baseDir)) {
      try { $baseDir = Split-Path -Parent $PSCommandPath } catch { $baseDir = '' }
    }
    if ([string]::IsNullOrWhiteSpace($baseDir)) {
      try { $baseDir = Split-Path -Parent $MyInvocation.MyCommand.Path } catch { $baseDir = '' }
    }
    if ([string]::IsNullOrWhiteSpace($baseDir)) {
      try { $baseDir = (Get-Location).Path } catch { $baseDir = '.' }
    }
    return [string]$baseDir
  } catch {
    return '.'
  }
}

function Get-AddonsRoot {
  try {
    $root = Join-Path (Get-AppBaseDirectoryPath) 'Addons'
    if (-not (Test-Path -LiteralPath $root -PathType Container)) {
      New-Item -ItemType Directory -Path $root -Force | Out-Null
    }
    return [string]$root
  } catch {
    return ''
  }
}

function Get-AddonNotesJsonPath {
  try {
    $root = Get-AddonsRoot
    if ([string]::IsNullOrWhiteSpace($root)) { return '' }
    $newPath = [string](Join-Path $root 'AddonNodes.json')
    $oldPath = [string](Join-Path $root 'AddonNotes.json')
    try {
      if (-not (Test-Path -LiteralPath $newPath -PathType Leaf) -and (Test-Path -LiteralPath $oldPath -PathType Leaf)) {
        Copy-Item -LiteralPath $oldPath -Destination $newPath -Force -ErrorAction SilentlyContinue
      }
    } catch {}
    return $newPath
  } catch {
    return ''
  }
}

function Read-AddonMetadataDocument {
  $doc = [ordered]@{
    SchemaVersion = 2
    UpdatedUtc    = ''
    Notes         = [ordered]@{}
    Colors        = [ordered]@{}
  }
  try {
    $path = Get-AddonNotesJsonPath
    if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path -PathType Leaf)) { return $doc }
    $raw = ''
    try { $raw = [string](Get-Content -LiteralPath $path -Raw -ErrorAction Stop) } catch { $raw = '' }
    if ([string]::IsNullOrWhiteSpace($raw)) { return $doc }
    $obj = $null
    try { $obj = $raw | ConvertFrom-Json -ErrorAction Stop } catch { $obj = $null }
    if (-not $obj) { return $doc }
    foreach ($propName in @('Notes','Colors')) {
      $bag = $null
      try { $bag = $obj.$propName } catch { $bag = $null }
      if ($bag -eq $null) { continue }
      foreach ($p in @($bag.PSObject.Properties)) {
        if (-not $p) { continue }
        $k = [string]$p.Name
        if ([string]::IsNullOrWhiteSpace($k)) { continue }
        $v = ''
        try { $v = [string]$p.Value } catch { $v = '' }
        if ($propName -eq 'Notes') { $doc.Notes[$k] = $v } else { $doc.Colors[$k] = $v }
      }
    }
    try { $doc.SchemaVersion = [int]$obj.SchemaVersion } catch {}
    try { $doc.UpdatedUtc = [string]$obj.UpdatedUtc } catch {}
  } catch {}
  return $doc
}

function Write-AddonMetadataDocument {
  param([hashtable]$Document)
  try {
    $path = Get-AddonNotesJsonPath
    if ([string]::IsNullOrWhiteSpace($path)) { return }
    $src = if ($Document) { $Document } else { Read-AddonMetadataDocument }
    $notesObj = [ordered]@{}
    $colorsObj = [ordered]@{}
    foreach ($k in @($src.Notes.Keys | Sort-Object)) {
      $kk = [string]$k
      if ([string]::IsNullOrWhiteSpace($kk)) { continue }
      $vv = ''
      try { $vv = [string]$src.Notes[$k] } catch { $vv = '' }
      if ([string]::IsNullOrWhiteSpace($vv)) { continue }
      $notesObj[$kk] = $vv
    }
    foreach ($k in @($src.Colors.Keys | Sort-Object)) {
      $kk = [string]$k
      if ([string]::IsNullOrWhiteSpace($kk)) { continue }
      $vv = ''
      try { $vv = [string]$src.Colors[$k] } catch { $vv = '' }
      if ([string]::IsNullOrWhiteSpace($vv)) { continue }
      $colorsObj[$kk] = $vv
    }
    $doc = [ordered]@{
      SchemaVersion = 2
      UpdatedUtc    = [DateTime]::UtcNow.ToString('o')
      Notes         = $notesObj
      Colors        = $colorsObj
    }
    $json = $doc | ConvertTo-Json -Depth 10
    [System.IO.File]::WriteAllText($path, [string]$json, [System.Text.Encoding]::UTF8)
  } catch {}
}

function Read-AddonNotesMap {
  $map = @{}
  try {
    $doc = Read-AddonMetadataDocument
    foreach ($k in @($doc.Notes.Keys)) { $map[[string]$k] = [string]$doc.Notes[$k] }
  } catch {}
  return $map
}

function Write-AddonNotesMap {
  param([hashtable]$Map)
  try {
    $doc = Read-AddonMetadataDocument
    $doc.Notes = @{}
    if ($Map) {
      foreach ($k in @($Map.Keys)) {
        $kk = [string]$k
        if ([string]::IsNullOrWhiteSpace($kk)) { continue }
        $vv = ''
        try { $vv = [string]$Map[$k] } catch { $vv = '' }
        if ([string]::IsNullOrWhiteSpace($vv)) { continue }
        $doc.Notes[$kk] = $vv
      }
    }
    Write-AddonMetadataDocument -Document $doc
  } catch {}
}

function Read-AddonColorsMap {
