function Convert-AddonNoteToStoredValue {
  param([string]$Text)
  try {
    $t = [string]$Text
    if ([string]::IsNullOrWhiteSpace($t)) { return '' }
    return [uri]::EscapeDataString($t)
  } catch {
    return [string]$Text
  }
}

function Convert-AddonNoteFromStoredValue {
  param([string]$Stored)
  try {
    $s = [string]$Stored
    if ([string]::IsNullOrWhiteSpace($s)) { return '' }
    return [uri]::UnescapeDataString($s)
  } catch {
    return [string]$Stored
  }
}

function Get-AddonButtonBorderHex {
  param([string]$ButtonName)
  try {
    $n = [string]$ButtonName
    if (-not [string]::IsNullOrWhiteSpace($n) -and $n -match '^#?[0-9A-Fa-f]{6}$') {
      if ($n.StartsWith('#')) { return $n }
      return ('#' + $n)
    }
    return '#BEBEBE'
  } catch {
    return '#BEBEBE'
  }
}

function New-AddonBorderBrush {
  param(
    [string]$Hex,
    [double]$Transparency = 0.25
  )
  try {
    $h = [string](Get-AddonButtonBorderHex -ButtonName $Hex)
    $base = [System.Windows.Media.ColorConverter]::ConvertFromString($h)
    if (-not ($base -is [System.Windows.Media.Color])) {
      $base = [System.Windows.Media.Colors]::Gray
    }
    $tr = [Math]::Max(0.0, [Math]::Min(1.0, [double]$Transparency))
    $alpha = [byte]([Math]::Round((1.0 - $tr) * 255.0))
    $c = [System.Windows.Media.Color]::FromArgb($alpha, $base.R, $base.G, $base.B)
    return (New-Object System.Windows.Media.SolidColorBrush($c))
  } catch {
    return (New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb(102, 190, 190, 190)))
  }
}

function Get-AddonDisplayState {
  param([string]$RawName)
  try {
    $raw = [string]$RawName
    if ([string]::IsNullOrWhiteSpace($raw)) {
      return [pscustomobject]@{ DisplayName = ''; State = 'none' }
    }
    $m = [regex]::Match($raw, '^(?<base>.*?)(?:_(?<state>on|off))\s*$', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if ($m.Success) {
      $base = ''
      try { $base = [string]$m.Groups['base'].Value } catch { $base = '' }
      $base = $base.TrimEnd()
      if ([string]::IsNullOrWhiteSpace($base)) { $base = $raw }
      $st = ''
      try { $st = [string]$m.Groups['state'].Value } catch { $st = '' }
      if ([string]::IsNullOrWhiteSpace($st)) { $st = 'none' }
      return [pscustomobject]@{
        DisplayName = [string]$base
        State       = ([string]$st).ToLowerInvariant()
      }
    }
    return [pscustomobject]@{
      DisplayName = [string]$raw
      State       = 'none'
    }
  } catch {
    return [pscustomobject]@{
      DisplayName = [string]$RawName
      State       = 'none'
    }
  }
}

