function Read-AddonNoteFromRegFile {
  param([string]$Path)
  try {
    $p = Resolve-ExistingPathLenient -Path ([string]$Path)
    if ([string]::IsNullOrWhiteSpace($p)) { $p = Normalize-Path ([string]$Path) }
    if ([string]::IsNullOrWhiteSpace($p) -or -not (Test-Path -LiteralPath $p -PathType Leaf)) { return '' }
    $lines = @()
    try { $lines = @(Get-Content -LiteralPath $p -TotalCount 40 -ErrorAction Stop) } catch { $lines = @() }
    foreach ($ln in @($lines)) {
      $txt = [string]$ln
      if ($txt -match '^\s*;\s*SMLT_NOTE\s*:\s*(?<v>.*)$') {
        return (Convert-AddonNoteFromStoredValue -Stored ([string]$matches['v']))
      }
    }
    return ''
  } catch {
    return ''
  }
}

function Get-AddonNoteForFile {
  param(
    [string]$FileName,
    [string]$FullPath
  )
  try {
    $name = [string]$FileName
    if ([string]::IsNullOrWhiteSpace($name)) {
      try { $name = [string][IO.Path]::GetFileName([string]$FullPath) } catch { $name = '' }
    }
    $map = Read-AddonNotesMap
    if ($map -and -not [string]::IsNullOrWhiteSpace($name)) {
      if ($map.ContainsKey($name)) { return [string]$map[$name] }
      foreach ($k in @($map.Keys)) {
        if ([string]$k -ieq $name) { return [string]$map[$k] }
      }
    }
    # Backward compatibility: if note was stored in reg comment in older versions.
    try { return [string](Read-AddonNoteFromRegFile -Path ([string]$FullPath)) } catch {}
    return ''
  } catch {
    return ''
  }
}

function Set-AddonNoteForFile {
  param(
    [string]$FileName,
    [string]$Note
  )
  try {
    $name = [string]$FileName
    if ([string]::IsNullOrWhiteSpace($name)) { return }
    $map = Read-AddonNotesMap
    if (-not $map) { $map = @{} }
    $existingKey = $null
    foreach ($k in @($map.Keys)) {
      if ([string]$k -ieq $name) { $existingKey = [string]$k; break }
    }
    $val = [string]$Note
    if ([string]::IsNullOrWhiteSpace($val)) {
      if ($existingKey -ne $null) { [void]$map.Remove($existingKey) }
      else { [void]$map.Remove($name) }
    } else {
      if ($existingKey -ne $null) {
        # Preserve latest filename casing as the map key.
        if ($existingKey -cne $name) { [void]$map.Remove($existingKey); $map[$name] = $val }
        else { $map[$existingKey] = $val }
      }
      else { $map[$name] = $val }
    }
    Write-AddonNotesMap -Map $map
  } catch {}
}

function Remove-AddonNoteForFile {
  param([string]$FileName)
  try {
    $name = [string]$FileName
    if ([string]::IsNullOrWhiteSpace($name)) { return }
    $map = Read-AddonNotesMap
    if (-not $map) { return }
    foreach ($k in @($map.Keys)) {
      if ([string]$k -ieq $name) { [void]$map.Remove($k) }
    }
    Write-AddonNotesMap -Map $map
  } catch {}
}

function Get-AddonColorForFile {
  param([string]$FileName)
  try {
    $name = [string]$FileName
    if ([string]::IsNullOrWhiteSpace($name)) { return '' }
    $map = Read-AddonColorsMap
    if (-not $map) { return '' }
    if ($map.ContainsKey($name)) { return [string]$map[$name] }
    foreach ($k in @($map.Keys)) {
      if ([string]$k -ieq $name) { return [string]$map[$k] }
    }
    return ''
  } catch { return '' }
}

function Set-AddonColorForFile {
  param([string]$FileName, [string]$ColorHex)
  try {
    $name = [string]$FileName
    if ([string]::IsNullOrWhiteSpace($name)) { return }
    $map = Read-AddonColorsMap
    if (-not $map) { $map = @{} }
    $existingKey = $null
    foreach ($k in @($map.Keys)) { if ([string]$k -ieq $name) { $existingKey = [string]$k; break } }
    $val = [string]$ColorHex
    if ([string]::IsNullOrWhiteSpace($val)) {
      if ($existingKey -ne $null) { [void]$map.Remove($existingKey) } else { [void]$map.Remove($name) }
    } else {
      if ($existingKey -ne $null) {
        # Preserve latest filename casing as the map key.
        if ($existingKey -cne $name) { [void]$map.Remove($existingKey); $map[$name] = $val }
        else { $map[$existingKey] = $val }
      } else { $map[$name] = $val }
    }
    Write-AddonColorsMap -Map $map
  } catch {}
}

function Remove-AddonColorForFile {
  param([string]$FileName)
  try {
    Set-AddonColorForFile -FileName ([string]$FileName) -ColorHex ''
  } catch {}
}

function Resolve-AddonRecordFromMenuSender {
  param([object]$Sender)
  try {
    $node = $Sender
    while ($node) {
      try {
        if ($node -is [System.Windows.Controls.ContextMenu]) {
          $rec = $null
          try { $rec = $node.Tag } catch { $rec = $null }
          return $rec
        }
      } catch {}
      $parent = $null
      try { $parent = $node.Parent } catch { $parent = $null }
      if (-not $parent) {
        try { $parent = [System.Windows.Media.VisualTreeHelper]::GetParent($node) } catch { $parent = $null }
      }
      if (-not $parent) { break }
      $node = $parent
    }
  } catch {}
  return $null
}

function Read-AddonFileContent {
  param([string]$FullPath)
  try {
    $p = Resolve-ExistingPathLenient -Path ([string]$FullPath)
    if ([string]::IsNullOrWhiteSpace($p)) { $p = Normalize-Path ([string]$FullPath) }
    if ([string]::IsNullOrWhiteSpace($p) -or -not (Test-Path -LiteralPath $p -PathType Leaf)) { return '' }
    $sr = $null
    try {
      $sr = New-Object System.IO.StreamReader($p, $true)
      return [string]$sr.ReadToEnd()
    } finally {
      if ($sr) { try { $sr.Dispose() } catch {} }
    }
  } catch { return '' }
}

function Remove-AddonFileToRecycleBin {
  param([string]$FullPath)
  try {
    $p = Resolve-ExistingPathLenient -Path ([string]$FullPath)
    if ([string]::IsNullOrWhiteSpace($p)) { $p = Normalize-Path ([string]$FullPath) }
    if ([string]::IsNullOrWhiteSpace($p) -or -not (Test-Path -LiteralPath $p -PathType Leaf)) { return $false }
    try { Add-Type -AssemblyName Microsoft.VisualBasic -ErrorAction SilentlyContinue | Out-Null } catch {}
    [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteFile(
      $p,
      [Microsoft.VisualBasic.FileIO.UIOption]::OnlyErrorDialogs,
      [Microsoft.VisualBasic.FileIO.RecycleOption]::SendToRecycleBin
    )
    return $true
  } catch {
    try {
      $p2 = Resolve-ExistingPathLenient -Path ([string]$FullPath)
      if ([string]::IsNullOrWhiteSpace($p2)) { $p2 = Normalize-Path ([string]$FullPath) }
      if (-not [string]::IsNullOrWhiteSpace($p2) -and (Test-Path -LiteralPath $p2 -PathType Leaf)) {
        Remove-Item -LiteralPath $p2 -Force -ErrorAction SilentlyContinue
      }
    } catch {}
    return $false
  }
}

function Get-MiscAddonRecords {
  $rows = New-Object System.Collections.Generic.List[object]
  try {
    $root = Get-AddonsRoot
    if ([string]::IsNullOrWhiteSpace($root) -or -not (Test-Path -LiteralPath $root -PathType Container)) { return @() }
    $files = @()
    try { $files = @(Get-ChildItem -LiteralPath $root -File -Filter '*.reg' -ErrorAction SilentlyContinue | Sort-Object Name) } catch { $files = @() }
    foreach ($f in @($files)) {
      if (-not $f) { continue }
      $nm = ''
      try { $nm = [string][IO.Path]::GetFileNameWithoutExtension([string]$f.Name) } catch { $nm = [string]$f.BaseName }
      if ([string]::IsNullOrWhiteSpace($nm)) { $nm = [string]$f.Name }
      $ds = $null
      try { $ds = Get-AddonDisplayState -RawName ([string]$nm) } catch { $ds = $null }
      $displayName = [string]$nm
      $state = 'none'
      if ($ds) {
        try { $displayName = [string]$ds.DisplayName } catch {}
        try { $state = [string]$ds.State } catch {}
      }
      $note = ''
      try { $note = Get-AddonNoteForFile -FileName ([string]$f.Name) -FullPath ([string]$f.FullName) } catch { $note = '' }
      $clr = ''
      try { $clr = [string](Get-AddonColorForFile -FileName ([string]$f.Name)) } catch { $clr = '' }
      $hasCustomColor = -not [string]::IsNullOrWhiteSpace($clr)
      $borderHex = if ($hasCustomColor) { [string](Get-AddonButtonBorderHex -ButtonName $clr) } else { '#BEBEBE' }
      [void]$rows.Add([pscustomobject]@{
        Name           = [string]$nm
        DisplayName    = [string]$displayName
        State          = [string]$state
        FileName       = [string]$f.Name
        FullPath       = [string]$f.FullName
        Note           = [string]$note
        ColorHex       = [string]$clr
        HasCustomColor = [bool]$hasCustomColor
        BorderHex      = [string]$borderHex
      })
    }
  } catch {}
  return @($rows.ToArray())
}

function New-MiscAddonTileButton {
  param([Parameter(Mandatory=$true)][object]$Record)
  try {
    $btn = New-Object System.Windows.Controls.Button
    try { $btn.Style = $window.Resources['MiscAddonTileButtonStyle'] } catch {}
    $btn.Width = 107
    $btn.Height = 65
    $btn.Margin = New-Object System.Windows.Thickness(3)
    $btn.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Stretch
    $btn.VerticalAlignment = [System.Windows.VerticalAlignment]::Top
    $btn.HorizontalContentAlignment = [System.Windows.HorizontalAlignment]::Stretch
    $btn.VerticalContentAlignment = [System.Windows.VerticalAlignment]::Stretch
    $btn.Focusable = $false
    try {
      $bh = [string](Get-PropString -Obj $Record -Names @('BorderHex') -Fallback '#BEBEBE')
      $bb = New-AddonBorderBrush -Hex $bh -Transparency 0.25
      $btn.BorderBrush = $bb
    } catch {}
    $state = [string](Get-PropString -Obj $Record -Names @('State') -Fallback 'none')
    $displayName = [string](Get-PropString -Obj $Record -Names @('DisplayName','Name') -Fallback '')
    $state = if ([string]::IsNullOrWhiteSpace($state)) { 'none' } else { $state.ToLowerInvariant() }
    $layout = New-Object System.Windows.Controls.Grid
    $layout.Margin = New-Object System.Windows.Thickness(0)
    $layout.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Stretch
    $layout.VerticalAlignment = [System.Windows.VerticalAlignment]::Stretch
    $layout.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition))
    $txt = New-Object System.Windows.Controls.TextBlock
    $txt.Text = [string]$displayName
    $txt.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $txt.TextAlignment = [System.Windows.TextAlignment]::Left
    $txt.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Stretch
    $txt.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $txt.FontSize = 9
    $txt.Margin = New-Object System.Windows.Thickness(0,0,10,0)
    [void]$layout.Children.Add($txt)
    if ($state -eq 'on' -or $state -eq 'off') {
      try {
        $dot = New-Object System.Windows.Shapes.Ellipse
        $dot.Width = 12
        $dot.Height = 12
        $dot.StrokeThickness = 0
        $dot.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Right
        $dot.VerticalAlignment = [System.Windows.VerticalAlignment]::Top
        $dot.Margin = New-Object System.Windows.Thickness(0,-2,-4,0)
        $dot.Fill = if ($state -eq 'on') {
          New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString('#2ca536'))
        } else {
          New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString('#CC3D3D'))
        }
        [void]$layout.Children.Add($dot)
      } catch {}
    }
    $btn.Content = $layout
    $note = [string](Get-PropString -Obj $Record -Names @('Note') -Fallback '')
    if (-not [string]::IsNullOrWhiteSpace($note)) {
      try {
        $tipText = New-Object System.Windows.Controls.TextBlock
        $tipText.Text = [string]$note
        $tipText.TextWrapping = [System.Windows.TextWrapping]::Wrap
        $tipText.MaxWidth = 250
        $tipText.Width = [double]::NaN
        $btn.ToolTip = $tipText
      } catch {
        try { $btn.ToolTip = [string]$note } catch {}
      }
    }
    $btn.Tag = $Record
    try {
      $ctx = New-Object System.Windows.Controls.ContextMenu
      try { $ctx.Tag = $Record } catch {}
      $miEdit = New-Object System.Windows.Controls.MenuItem
      $miEdit.Header = 'Edit'
      $miColor = New-Object System.Windows.Controls.MenuItem
      $miColor.Header = 'Color'
      $miDelete = New-Object System.Windows.Controls.MenuItem
      $miDelete.Header = 'Delte'
      foreach ($c in @(Get-AddonColorPalette)) {
        if (-not $c) { continue }
        $mi = New-Object System.Windows.Controls.MenuItem
        $mi.Padding = New-Object System.Windows.Thickness(4,1,4,1)
        $row = New-Object System.Windows.Controls.StackPanel
        $row.Orientation = [System.Windows.Controls.Orientation]::Horizontal
        $sw = New-Object System.Windows.Shapes.Rectangle
        $sw.Width = 18; $sw.Height = 18
        $sw.Margin = New-Object System.Windows.Thickness(0,0,6,0)
        $sw.StrokeThickness = 1
        try { $sw.Fill = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString([string]$c.Hex)) } catch {}
        $lb = New-Object System.Windows.Controls.TextBlock
        $lb.Text = [string]$c.Name
        $lb.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        [void]$row.Children.Add($sw)
        [void]$row.Children.Add($lb)
        $mi.Header = $row
        $mi.Tag = $c
        $mi.Add_Click({
          param($s2,$e2)
          try {
            $rec2 = Resolve-AddonRecordFromMenuSender -Sender $s2
            if (-not $rec2) { return }
            $f2 = [string](Get-PropString -Obj $rec2 -Names @('FileName') -Fallback '')
            if ([string]::IsNullOrWhiteSpace($f2)) { return }
            $col = $null
            try { $col = $s2.Tag } catch { $col = $null }
            if (-not $col) { return }
            $hex2 = [string](Get-PropString -Obj $col -Names @('Hex') -Fallback '')
            Set-AddonColorForFile -FileName $f2 -ColorHex $hex2
            Refresh-MiscAddonsPanel -SearchText ([string]$miscAddonsSearchBox.Text)
          } catch {}
        })
        [void]$miColor.Items.Add($mi)
      }
      $miEdit.Add_Click({
        param($s2,$e2)
        try {
          $rec2 = Resolve-AddonRecordFromMenuSender -Sender $s2
          if (-not $rec2) { return }
          $oldName = [string](Get-PropString -Obj $rec2 -Names @('Name') -Fallback '')
          $oldFile = [string](Get-PropString -Obj $rec2 -Names @('FileName') -Fallback '')
          $oldPath = [string](Get-PropString -Obj $rec2 -Names @('FullPath') -Fallback '')
          if ([string]::IsNullOrWhiteSpace($oldName) -or [string]::IsNullOrWhiteSpace($oldFile)) { return }
          $fnTxt = Read-AddonFileContent -FullPath $oldPath
          $ntTxt = [string](Get-PropString -Obj $rec2 -Names @('Note') -Fallback '')
          Show-CreateAddonDialog -OwnerWindow $window -InitialName $oldName -InitialFunction $fnTxt -InitialNotes $ntTxt -DialogTitle 'Edit Addon' -PrimaryButtonText 'Save' -ExistingFileName $oldFile -OnSubmit ({
            param($payload)
            $createdPath = Write-AddonRegFileFromPayload -Payload $payload -ExistingFileName $oldFile
            if (-not [string]::IsNullOrWhiteSpace([string]$createdPath)) {
              $newFile = ''
              try { $newFile = [string][IO.Path]::GetFileName([string]$createdPath) } catch { $newFile = '' }
              if (-not [string]::IsNullOrWhiteSpace($newFile) -and -not [string]::IsNullOrWhiteSpace($oldFile) -and ($newFile -ine $oldFile)) {
                $oldClr = Get-AddonColorForFile -FileName $oldFile
                if (-not [string]::IsNullOrWhiteSpace($oldClr)) { Set-AddonColorForFile -FileName $newFile -ColorHex $oldClr }
                Remove-AddonColorForFile -FileName $oldFile
              }
              Refresh-MiscAddonsPanel -SearchText ([string]$miscAddonsSearchBox.Text)
            }
          }.GetNewClosure())
        } catch {
          [System.Windows.MessageBox]::Show(
            ("Edit addon failed.`n`n" + [string]$_.Exception.Message),
            "Edit Addon",
            [System.Windows.MessageBoxButton]::OK,
            [System.Windows.MessageBoxImage]::Error
          ) | Out-Null
        }
      })
      $miDelete.Add_Click({
        param($s2,$e2)
        try {
          $rec2 = Resolve-AddonRecordFromMenuSender -Sender $s2
          if (-not $rec2) { return }
          $nm2 = [string](Get-PropString -Obj $rec2 -Names @('DisplayName','Name') -Fallback 'Addon')
          $f2 = [string](Get-PropString -Obj $rec2 -Names @('FileName') -Fallback '')
          $p2 = [string](Get-PropString -Obj $rec2 -Names @('FullPath') -Fallback '')
          $okDel = Show-ContinueCancelDialog -Title "Delete Addon" -Message ("Delete addon ''" + $nm2 + "''?") -ContinueText "YES" -CancelText "NO"
          if (-not $okDel) { return }
          [void](Remove-AddonFileToRecycleBin -FullPath $p2)
          Remove-AddonNoteForFile -FileName $f2
          Remove-AddonColorForFile -FileName $f2
          Refresh-MiscAddonsPanel -SearchText ([string]$miscAddonsSearchBox.Text)
        } catch {}
      })
      [void]$ctx.Items.Add($miEdit)
      [void]$ctx.Items.Add($miColor)
      [void]$ctx.Items.Add($miDelete)
      $btn.ContextMenu = $ctx
    } catch {}
    $btn.Add_Click({
      param($sender, $e)
      try {
        if (-not $sender) { return }
        $rec = $null
        try { $rec = $sender.Tag } catch { $rec = $null }
        if (-not $rec) { return }
        $nm = [string](Get-PropString -Obj $rec -Names @('DisplayName','Name') -Fallback 'Addon')
        $fp = [string](Get-PropString -Obj $rec -Names @('FullPath') -Fallback '')
        if ([string]::IsNullOrWhiteSpace($fp) -or -not (Test-Path -LiteralPath $fp -PathType Leaf)) {
          [System.Windows.MessageBox]::Show(
            ("Addon file is missing:`n`n" + [string]$fp),
            "Launch Addon",
            [System.Windows.MessageBoxButton]::OK,
            [System.Windows.MessageBoxImage]::Warning
          ) | Out-Null
          return
        }
        $ok = Show-ContinueCancelDialog -Title "Launch Addon" -Message ("Are you sure you want to launch ''" + $nm + "''?") -ContinueText "YES" -CancelText "NO"
        if (-not $ok) { return }
        Start-Process -FilePath $fp | Out-Null
      } catch {
        [System.Windows.MessageBox]::Show(
          ("Failed to launch addon.`n`n" + [string]$_.Exception.Message),
          "Launch Addon",
          [System.Windows.MessageBoxButton]::OK,
          [System.Windows.MessageBoxImage]::Error
        ) | Out-Null
      }
    })
    return $btn
  } catch {
    return $null
  }
}

function Apply-MiscAddonTilesTheme {
  try {
    if (-not $miscAddonsButtonsHost) { return }
    if (-not (Test-Path variable:script:MiscAddonTileHoverWiredByHash)) { $script:MiscAddonTileHoverWiredByHash = @{} }
    if (-not (Test-Path variable:script:MiscAddonTileHoverThemeByHash)) { $script:MiscAddonTileHoverThemeByHash = @{} }
    $isDark = $false
    try { $isDark = ([string]$script:UiThemeMode -ieq 'Dark') } catch { $isDark = $false }
    $baseHex   = if ($isDark) { '#2A2A2A' } else { '#E4E4E4' }
    $hoverHex  = if ($isDark) { '#373737' } else { '#c8c8c8' }
    $textHex   = if ($isDark) { '#7C7C7C' } else { '#202020' }
    $neutralHex= if ($isDark) { '#3A3A3A' } else { '#BEBEBE' }
    $baseBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($baseHex))
    $hoverBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($hoverHex))
    $textBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($textHex))
    $neutralBrush = New-AddonBorderBrush -Hex $neutralHex -Transparency 0.25
    foreach ($child in @($miscAddonsButtonsHost.Children)) {
      try {
        $btn = $child -as [System.Windows.Controls.Button]
        if (-not $btn) { continue }
        $k = ''
        try { $k = [string]$btn.GetHashCode() } catch { $k = '' }
        if (-not [string]::IsNullOrWhiteSpace($k)) {
          try {
            $script:MiscAddonTileHoverThemeByHash[$k] = @{
              BaseBrush  = $baseBrush
              HoverBrush = $hoverBrush
            }
          } catch {}
          if (-not $script:MiscAddonTileHoverWiredByHash.ContainsKey($k)) {
            $btn.Add_MouseEnter({
              param($sender, $e)
              try {
                if (-not $sender) { return }
                $kk = ''
                try { $kk = [string]$sender.GetHashCode() } catch { $kk = '' }
                if ([string]::IsNullOrWhiteSpace($kk)) { return }
                $cfg = $null
                try { $cfg = $script:MiscAddonTileHoverThemeByHash[$kk] } catch { $cfg = $null }
                if (-not $cfg) { return }
                if (-not $sender.IsEnabled) { return }
                try { $sender.Background = $cfg.HoverBrush } catch {}
                try {
                  $null = $sender.ApplyTemplate()
                  $bd = $null
                  try { $bd = $sender.Template.FindName('AddonBtnBorder', $sender) } catch { $bd = $null }
                  if ($bd -is [System.Windows.Controls.Border]) { $bd.Background = $cfg.HoverBrush }
                } catch {}
              } catch {}
            })
            $btn.Add_MouseLeave({
              param($sender, $e)
              try {
                if (-not $sender) { return }
                $kk = ''
                try { $kk = [string]$sender.GetHashCode() } catch { $kk = '' }
                if ([string]::IsNullOrWhiteSpace($kk)) { return }
                $cfg = $null
                try { $cfg = $script:MiscAddonTileHoverThemeByHash[$kk] } catch { $cfg = $null }
                if (-not $cfg) { return }
                try { $sender.Background = $cfg.BaseBrush } catch {}
                try {
                  $null = $sender.ApplyTemplate()
                  $bd = $null
                  try { $bd = $sender.Template.FindName('AddonBtnBorder', $sender) } catch { $bd = $null }
                  if ($bd -is [System.Windows.Controls.Border]) { $bd.Background = $cfg.BaseBrush }
                } catch {}
              } catch {}
            })
            $script:MiscAddonTileHoverWiredByHash[$k] = $true
          }
        }
        try { $btn.Background = $baseBrush } catch {}
        try { $btn.Foreground = $textBrush } catch {}
        try {
          $null = $btn.ApplyTemplate()
          $bd = $null
          try { $bd = $btn.Template.FindName('AddonBtnBorder', $btn) } catch { $bd = $null }
          if ($bd -is [System.Windows.Controls.Border]) { $bd.Background = $baseBrush }
        } catch {}
        $hasCustomColor = $false
        $customHex = ''
        try {
          $rec = $btn.Tag
          $hcRaw = [string](Get-PropString -Obj $rec -Names @('HasCustomColor') -Fallback '')
          $hasCustomColor = ($hcRaw -match '^(?i:true|1|yes)$')
          $customHex = [string](Get-PropString -Obj $rec -Names @('ColorHex','BorderHex') -Fallback '')
        } catch {}
        if ($hasCustomColor -and -not [string]::IsNullOrWhiteSpace($customHex)) {
          try {
            $cb = New-AddonBorderBrush -Hex ([string](Get-AddonButtonBorderHex -ButtonName $customHex)) -Transparency 0.25
            $btn.BorderBrush = $cb
          } catch { try { $btn.BorderBrush = $neutralBrush } catch {} }
        } else {
          try { $btn.BorderBrush = $neutralBrush } catch {}
        }
        try {
          $tb = $btn.Content -as [System.Windows.Controls.TextBlock]
          if ($tb) { $tb.Foreground = $textBrush }
        } catch {}
      } catch {}
    }
  } catch {}
}

function Update-MiscAddonsButtonsColumns {
  try {
    if (-not $miscAddonsButtonsHost) { return }
    if (-not ($miscAddonsButtonsHost -is [System.Windows.Controls.Primitives.UniformGrid])) { return }
    $avail = 0.0
    try { if ($miscAddonsPanelScroll) { $avail = [double]$miscAddonsPanelScroll.ViewportWidth } } catch { $avail = 0.0 }
    if ($avail -le 1.0) { try { if ($miscAddonsPanelScroll) { $avail = [double]$miscAddonsPanelScroll.ActualWidth } } catch { $avail = 0.0 } }
    if ($avail -le 1.0) { try { $avail = [double]$miscAddonsButtonsHost.ActualWidth } catch { $avail = 0.0 } }
    if ($avail -le 1.0) { return }
    $tileW = 105.0
    $gapW  = 6.0
    $cellW = $tileW + $gapW
    $cols = [int][Math]::Floor(($avail + $gapW) / $cellW)
    if ($cols -lt 1) { $cols = 1 }
    try { if ([int]$miscAddonsButtonsHost.Columns -ne $cols) { $miscAddonsButtonsHost.Columns = $cols } } catch { $miscAddonsButtonsHost.Columns = $cols }
  } catch {}
}

function Refresh-MiscAddonsPanel {
  param([string]$SearchText = $null)
  try {
    if (-not $miscAddonsButtonsHost) { return }
    try { $script:MiscAddonsAllRecords = @(Get-MiscAddonRecords) } catch { $script:MiscAddonsAllRecords = @() }
    $needle = ''
    if ($PSBoundParameters.ContainsKey('SearchText')) {
      try { $needle = [string]$SearchText } catch { $needle = '' }
    } else {
      try { $needle = [string]$miscAddonsSearchBox.Text } catch { $needle = '' }
    }
    try { $script:MiscAddonsSearchText = [string]$needle } catch {}
    $needleLc = ''
    try { $needleLc = $needle.ToLowerInvariant().Trim() } catch { $needleLc = [string]$needle }
    $rows = @($script:MiscAddonsAllRecords)
    if (-not [string]::IsNullOrWhiteSpace($needleLc)) {
      $rows = @($rows | Where-Object {
        $nm = ''
        try { $nm = [string]$_.Name } catch { $nm = '' }
        if ([string]::IsNullOrWhiteSpace($nm)) { return $false }
        return ($nm.ToLowerInvariant().Contains($needleLc))
      })
    }
    try { $miscAddonsButtonsHost.Children.Clear() } catch {}
    foreach ($r in @($rows)) {
      $b = New-MiscAddonTileButton -Record $r
      if ($b) { try { [void]$miscAddonsButtonsHost.Children.Add($b) } catch {} }
    }
    try { Apply-MiscAddonTilesTheme } catch {}
    try { Update-MiscAddonsButtonsColumns } catch {}
    if ($miscAddonsEmptyText) {
      if (@($rows).Count -gt 0) {
        try { $miscAddonsEmptyText.Visibility = [System.Windows.Visibility]::Collapsed } catch {}
      } else {
        $msg = if ([string]::IsNullOrWhiteSpace($needleLc)) {
          'No addon files found. Add .reg or .txt files into the Addons folder or click Create Addon.'
        } else {
          'No addons match the search filter.'
        }
        try { $miscAddonsEmptyText.Text = $msg } catch {}
        try { $miscAddonsEmptyText.Visibility = [System.Windows.Visibility]::Visible } catch {}
      }
    }
  } catch {}
}

function Get-RegFilePathsFromDragData {
  param(
    [object]$DataObject,
    [string[]]$AllowedExtensions = @('.reg'),
    [switch]$FirstOnly
  )
  $found = New-Object System.Collections.Generic.List[string]
  $seen = @{}
  try {
    if (-not $DataObject) { return @() }
    $formats = @()
    $hasFileDrop = $false
    try { $hasFileDrop = [bool]$DataObject.GetDataPresent([System.Windows.DataFormats]::FileDrop) } catch { $hasFileDrop = $false }
    if ($hasFileDrop) {
      # Prefer CF_HDROP payload only; this avoids duplicate short-name aliases from fallback formats.
      $formats = @([System.Windows.DataFormats]::FileDrop)
    } else {
      $formats = @(
        'FileNameW',
        'FileName',
        [System.Windows.DataFormats]::UnicodeText,
        [System.Windows.DataFormats]::Text
      )
    }
    foreach ($fmt in @($formats)) {
      $hasFmt = $false
      try { $hasFmt = [bool]$DataObject.GetDataPresent($fmt) } catch { $hasFmt = $false }
      if (-not $hasFmt) { continue }
      $vals = @()
      try {
        $raw = $DataObject.GetData($fmt)
        if ($raw -is [System.Array]) {
          $vals = @($raw)
        } elseif ($raw -is [string]) {
          $s = [string]$raw
          $vals = @($s -split "(`0|`r`n|`n|`r)")
        } elseif ($null -ne $raw) {
          $vals = @([string]$raw)
        }
      } catch { $vals = @() }
      foreach ($v in @($vals)) {
        $p = ''
        try { $p = [string]$v } catch { $p = '' }
        if ([string]::IsNullOrWhiteSpace($p)) { continue }
        $p = $p.Trim().Trim('"')
        try {
          if ($p -match '^(?i)file://') {
            $u = $null
            if ([System.Uri]::TryCreate($p, [System.UriKind]::Absolute, [ref]$u)) {
              try { $p = [string]$u.LocalPath } catch {}
            }
          }
        } catch {}
        if ([string]::IsNullOrWhiteSpace($p)) { continue }
        $ext = ''
        try { $ext = ([string][IO.Path]::GetExtension($p)).ToLowerInvariant() } catch { $ext = '' }
        if ([string]::IsNullOrWhiteSpace($ext)) { continue }
        $okExt = $false
        foreach ($ae in @($AllowedExtensions)) {
          $a = ''
          try { $a = ([string]$ae).ToLowerInvariant() } catch { $a = '' }
          if ([string]::IsNullOrWhiteSpace($a)) { continue }
          if (-not $a.StartsWith('.')) { $a = '.' + $a }
          if ($ext -eq $a) { $okExt = $true; break }
        }
        if (-not $okExt) { continue }
        if (-not (Test-Path -LiteralPath $p -PathType Leaf)) { continue }
        try {
          $gi = Get-Item -LiteralPath $p -ErrorAction Stop
          if ($gi -and (-not [string]::IsNullOrWhiteSpace([string]$gi.FullName))) {
            $p = [string]$gi.FullName
          }
        } catch {}
        $k = ''
        try { $k = (Normalize-Path ([string]$p)).ToLowerInvariant() } catch { $k = [string]$p.ToLowerInvariant() }
        if ([string]::IsNullOrWhiteSpace($k)) { $k = [string]$p.ToLowerInvariant() }
        if ($seen.ContainsKey($k)) { continue }
        $seen[$k] = $true
        [void]$found.Add([string]$p)
        if ($FirstOnly) { return @($found.ToArray()) }
      }
    }
  } catch {}
  return @($found.ToArray())
}

if (-not (Test-Path variable:script:AddonPanelInvalidDropWarnAt)) { $script:AddonPanelInvalidDropWarnAt = [datetime]::MinValue }
if (-not (Test-Path variable:script:CreateAddonInvalidDropWarnAt)) { $script:CreateAddonInvalidDropWarnAt = [datetime]::MinValue }
function Test-AllowInvalidAddonDropWarning {
  param(
    [ValidateSet('Panel','Dialog')]
    [string]$Scope = 'Panel'
  )
  try {
    $now = Get-Date
    if ($Scope -eq 'Dialog') {
      if (($now - [datetime]$script:CreateAddonInvalidDropWarnAt).TotalMilliseconds -lt 800) { return $false }
      $script:CreateAddonInvalidDropWarnAt = $now
      return $true
    }
    if (($now - [datetime]$script:AddonPanelInvalidDropWarnAt).TotalMilliseconds -lt 800) { return $false }
    $script:AddonPanelInvalidDropWarnAt = $now
    return $true
  } catch {
    return $true
  }
}

function Import-AddonRegFilesFromPaths {
  param(
    [string[]]$Paths,
    [switch]$PromptOnOverwrite
  )
  $res = [ordered]@{
    Imported = 0
    Skipped  = 0
    Failed   = 0
    Errors   = New-Object System.Collections.Generic.List[string]
  }
  try {
    $root = Get-AddonsRoot
    if ([string]::IsNullOrWhiteSpace($root)) { throw "Addons folder is unavailable." }
    foreach ($src in @($Paths)) {
      try {
        $srcPath = [string]$src
        if ([string]::IsNullOrWhiteSpace($srcPath) -or -not (Test-Path -LiteralPath $srcPath -PathType Leaf)) { $res.Skipped++; continue }
        $srcExt = ''
        try { $srcExt = ([string][IO.Path]::GetExtension($srcPath)).ToLowerInvariant() } catch { $srcExt = '' }
        if (@('.reg','.txt') -notcontains $srcExt) { $res.Skipped++; continue }
        $name = [string][IO.Path]::GetFileNameWithoutExtension($srcPath)
        if ([string]::IsNullOrWhiteSpace($name)) { $res.Skipped++; continue }
        $safeName = [string]$name
        foreach ($ch in [IO.Path]::GetInvalidFileNameChars()) { $safeName = $safeName.Replace([string]$ch, '_') }
        $safeName = (Trim-NameInputPreserveNbsp -Text $safeName)
        if ([string]::IsNullOrWhiteSpace($safeName)) { $res.Skipped++; continue }
        $dst = Join-Path $root ($safeName + '.reg')
        if ($PromptOnOverwrite -and (Test-Path -LiteralPath $dst -PathType Leaf)) {
          $okOv = Show-ContinueCancelDialog -Title "Import Addon" -Message ("Addon already exists:`n`n" + $safeName + ".reg`n`nOverwrite?") -ContinueText "YES" -CancelText "NO"
          if (-not $okOv) { $res.Skipped++; continue }
        }
        $txt = ''
        $sr = $null
        try {
          $sr = New-Object System.IO.StreamReader($srcPath, $true)
          $txt = [string]$sr.ReadToEnd()
        } finally {
          if ($sr) { try { $sr.Dispose() } catch {} }
        }
        if ([string]::IsNullOrWhiteSpace($txt)) { $res.Skipped++; continue }
        $payload = [pscustomobject]@{
          Name = [string]$name
          Function = [string]$txt
          Notes = ''
        }
        [void](Write-AddonRegFileFromPayload -Payload $payload)
        $res.Imported++
      } catch {
        $res.Failed++
        try { [void]$res.Errors.Add([string]$_.Exception.Message) } catch {}
      }
    }
  } catch {
    $res.Failed++
    try { [void]$res.Errors.Add([string]$_.Exception.Message) } catch {}
  }
  return [pscustomobject]$res
}

function Show-CreateAddonDialog {
  param(
    [System.Windows.Window]$OwnerWindow = $null,
    [string]$InitialName = '',
    [string]$InitialFunction = '',
    [string]$InitialNotes = '',
    [string]$DialogTitle = 'Create Addon',
    [string]$PrimaryButtonText = 'Save',
    [string]$ExistingFileName = '',
    [scriptblock]$OnSubmit = $null
  )
  try {
    $xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Create Addon"
        Width="560"
        Height="420"
        MinWidth="520"
        MinHeight="360"
        WindowStyle="None"
        AllowsTransparency="True"
        Background="Transparent"
        WindowStartupLocation="CenterOwner"
        ResizeMode="CanResizeWithGrip"
        ShowInTaskbar="False"
        SnapsToDevicePixels="True">
  <Border Name="AddonDialogOuterBorder" BorderThickness="1">
    <Grid>
      <Grid.RowDefinitions>
        <RowDefinition Height="32"/>
        <RowDefinition Height="*"/>
      </Grid.RowDefinitions>

      <Border Name="AddonDialogTitleBar" Grid.Row="0" Padding="8,0,6,0">
        <Grid>
          <Grid.ColumnDefinitions>
            <ColumnDefinition Width="*"/>
            <ColumnDefinition Width="Auto"/>
          </Grid.ColumnDefinitions>
          <TextBlock Name="AddonDialogTitleText" Grid.Column="0" VerticalAlignment="Center" FontSize="12" FontWeight="SemiBold" Text="Create Addon"/>
          <Button Name="AddonDialogCloseBtn" Grid.Column="1" Width="34" Height="22" Padding="0" FontSize="12" Content="✕"/>
        </Grid>
      </Border>

      <Grid Grid.Row="1" Margin="12">
        <Grid.RowDefinitions>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="7*"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="3*"/>
          <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <Grid Grid.Row="0" Margin="0,0,0,8">
          <Grid.ColumnDefinitions>
            <ColumnDefinition Width="Auto"/>
            <ColumnDefinition Width="*"/>
          </Grid.ColumnDefinitions>
          <TextBlock Grid.Column="0" Margin="0,0,8,0" VerticalAlignment="Center" Text="Name"/>
          <TextBox Name="AddonNameBox" Grid.Column="1" VerticalAlignment="Center"/>
        </Grid>

        <TextBlock Grid.Row="1" Margin="0,0,0,4" Text="Function"/>
        <TextBox Name="AddonFunctionBox"
                 Grid.Row="2"
                 Margin="0,0,0,0"
                 AllowDrop="True"
                 AcceptsReturn="True"
                 TextWrapping="Wrap"
                 VerticalAlignment="Stretch"
                 VerticalScrollBarVisibility="Auto"
                 HorizontalScrollBarVisibility="Disabled"/>

        <TextBlock Grid.Row="3" Margin="0,8,0,4" Text="Notes"/>
        <TextBox Name="AddonNotesBox"
                 Grid.Row="4"
                 Margin="0,0,0,0"
                 AcceptsReturn="True"
                 TextWrapping="Wrap"
                 VerticalAlignment="Stretch"
                 VerticalScrollBarVisibility="Auto"
                 HorizontalScrollBarVisibility="Disabled"/>

        <DockPanel Grid.Row="5" Margin="0,10,0,0" LastChildFill="False" HorizontalAlignment="Right">
          <Button Name="AddonAbortBtn" MinWidth="84" Margin="0,0,8,0">Cancel</Button>
          <Button Name="AddonCreateBtn" MinWidth="84" IsDefault="True">Save</Button>
        </DockPanel>
      </Grid>
    </Grid>
  </Border>
</Window>
"@
    $reader = New-Object System.Xml.XmlNodeReader ([xml]$xaml)
    $dlg = [Windows.Markup.XamlReader]::Load($reader)
    if ($OwnerWindow) { try { $dlg.Owner = $OwnerWindow } catch {} }
    $isDark = $false
    try { $isDark = ([string]$script:UiThemeMode -ieq 'Dark') } catch { $isDark = $false }
    $bgHex = if ($isDark) { '#202020' } else { '#E1E1E1' }
    $fgHex = if ($isDark) { '#7C7C7C' } else { '#202020' }
    $bdHex = if ($isDark) { '#3A3A3A' } else { '#BEBEBE' }
    $inHex = if ($isDark) { '#2F2F2F' } else { '#FFFFFF' }
    $btnHex = if ($isDark) { '#2A2A2A' } else { '#E4E4E4' }
    $bg = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($bgHex))
    $fg = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($fgHex))
    $bd = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($bdHex))
    $inp= New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($inHex))
    $btnb=New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($btnHex))
    try { $dlg.Background = $bg; $dlg.Foreground = $fg } catch {}
    $outerBorder = $dlg.FindName('AddonDialogOuterBorder')
    $titleBar = $dlg.FindName('AddonDialogTitleBar')
    $titleText = $dlg.FindName('AddonDialogTitleText')
    $titleCloseBtn = $dlg.FindName('AddonDialogCloseBtn')
    $nameBox = $dlg.FindName('AddonNameBox')
    $funcBox = $dlg.FindName('AddonFunctionBox')
    $noteBox = $dlg.FindName('AddonNotesBox')
    try {
      if (-not [string]::IsNullOrWhiteSpace($DialogTitle)) {
        $dlg.Title = [string]$DialogTitle
        if ($titleText) { $titleText.Text = [string]$DialogTitle }
      }
    } catch {}
    try { if ($outerBorder) { $outerBorder.Background = $bg; $outerBorder.BorderBrush = $bd } } catch {}
    $titleBgHex = if ($isDark) { '#2A2A2A' } else { '#E4E4E4' }
    $titleFgHex = if ($isDark) { '#7C7C7C' } else { '#202020' }
    $titleHoverHex = if ($isDark) { '#5A5A5A' } else { '#C8C8C8' }
    $titlePressHex = if ($isDark) { '#474747' } else { '#B8B8B8' }
    $titleBg = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($titleBgHex))
    $titleFg = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($titleFgHex))
    $titleHover = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($titleHoverHex))
    $titlePress = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($titlePressHex))
    try { if ($titleBar) { $titleBar.Background = $titleBg } } catch {}
    try { if ($titleText) { $titleText.Foreground = $titleFg } } catch {}
    if ($titleBar) {
      $titleBar.Add_MouseLeftButtonDown({
        param($s,$e)
        try {
          if ($e.ClickCount -ge 2) { return }
          $dlg.DragMove()
        } catch {}
      })
    }
    if ($titleCloseBtn) {
      try {
        $titleCloseBtn.Background = $titleBg
        $titleCloseBtn.Foreground = $titleFg
        $titleCloseBtn.BorderBrush = $bd
      } catch {}
      $titleCloseBtn.Add_MouseEnter({ try { $titleCloseBtn.Background = $titleHover } catch {} })
      $titleCloseBtn.Add_MouseLeave({ try { $titleCloseBtn.Background = $titleBg } catch {} })
      $titleCloseBtn.Add_PreviewMouseLeftButtonDown({ try { $titleCloseBtn.Background = $titlePress } catch {} })
      $titleCloseBtn.Add_PreviewMouseLeftButtonUp({ try { $titleCloseBtn.Background = $titleHover } catch {} })
      $titleCloseBtn.Add_Click({ try { $dlg.Close() } catch {} })
    }
    foreach ($tb in @($nameBox,$funcBox,$noteBox)) {
      if (-not $tb) { continue }
      try { $tb.Background = $inp; $tb.Foreground = $fg; $tb.BorderBrush = $bd } catch {}
    }
    # Direct clipboard write using WinForms clipboard API (STA on UI thread).
    # Keep this single-shot to avoid UI stalls from retry loops.
    $setClipboardTextFast = {
      param([string]$clipText)
      if ([string]::IsNullOrEmpty([string]$clipText)) { return }
      try {
        [System.Windows.Forms.Clipboard]::SetText([string]$clipText, [System.Windows.Forms.TextDataFormat]::UnicodeText)
      } catch {}
    }
    # Pure-string cut path for Addon editor text fields (Ctrl+X).
    $wirePureStringCut = {
      param([System.Windows.Controls.TextBox]$tb)
      if (-not $tb) { return }
      try {
        $tb.Add_PreviewKeyDown({
          param($sender, $e)
          try {
            if (-not ($sender -is [System.Windows.Controls.TextBox])) { return }
            $mods = [System.Windows.Input.Keyboard]::Modifiers
            $k = $e.Key
            if ($k -eq [System.Windows.Input.Key]::System) { $k = $e.SystemKey }
            if ((($mods -band [System.Windows.Input.ModifierKeys]::Control) -eq 0) -or ($k -ne [System.Windows.Input.Key]::X)) { return }

            $txt = ''
            $start = 0
            $len = 0
            try { $txt = [string]$sender.Text } catch { $txt = '' }
            try { $start = [int]$sender.SelectionStart } catch { $start = 0 }
            try { $len = [int]$sender.SelectionLength } catch { $len = 0 }
            if ($len -le 0) { return }
            if ($start -lt 0) { $start = 0 }
            if ($start -gt $txt.Length) { $start = $txt.Length }
            if (($start + $len) -gt $txt.Length) { $len = $txt.Length - $start }
            if ($len -le 0) { return }

            $cutText = ''
            try { $cutText = [string]$txt.Substring($start, $len) } catch { $cutText = '' }
            try { & $setClipboardTextFast $cutText } catch {}

            $left = ''
            $right = ''
            try { $left = [string]$txt.Substring(0, $start) } catch { $left = '' }
            try {
              $rStart = $start + $len
              if ($rStart -lt $txt.Length) { $right = [string]$txt.Substring($rStart) } else { $right = '' }
            } catch { $right = '' }

            try { $sender.Text = ($left + $right) } catch {}
            try { $sender.SelectionStart = $start } catch {}
            try { $sender.SelectionLength = 0 } catch {}
            $e.Handled = $true
          } catch {}
        })
      } catch {}
    }
    foreach ($tb in @($nameBox,$funcBox,$noteBox)) {
      try { & $wirePureStringCut $tb } catch {}
    }
    try { if ($nameBox -and -not [string]::IsNullOrWhiteSpace($InitialName)) { $nameBox.Text = [string]$InitialName } } catch {}
    try { if ($funcBox -and -not [string]::IsNullOrWhiteSpace($InitialFunction)) { $funcBox.Text = [string]$InitialFunction } } catch {}
    try { if ($noteBox -and -not [string]::IsNullOrWhiteSpace($InitialNotes)) { $noteBox.Text = [string]$InitialNotes } } catch {}
    $resolveDroppedRegPath = {
      param([object]$dataObj)
      try {
        if (-not ($dataObj -and $dataObj.GetDataPresent([System.Windows.DataFormats]::FileDrop))) { return '' }
        $arr = @($dataObj.GetData([System.Windows.DataFormats]::FileDrop))
        foreach ($v in @($arr)) {
          $p = [string]$v
          if ([string]::IsNullOrWhiteSpace($p)) { continue }
          $ext = ''
          try { $ext = ([string][IO.Path]::GetExtension($p)).ToLowerInvariant() } catch { $ext = '' }
          if (($ext -eq '.reg' -or $ext -eq '.txt') -and (Test-Path -LiteralPath $p -PathType Leaf)) {
            return [string]$p
          }
        }
      } catch {}
      return ''
    }
    $importDroppedRegIntoFields = {
      param([string]$regPath)
      try {
        $picked = [string]$regPath
        if ([string]::IsNullOrWhiteSpace($picked) -or -not (Test-Path -LiteralPath $picked -PathType Leaf)) { return $false }
        $txt = ''
        $sr = $null
        try {
          $sr = New-Object System.IO.StreamReader($picked, $true)
          $txt = [string]$sr.ReadToEnd()
        } finally {
          if ($sr) { try { $sr.Dispose() } catch {} }
        }
        if ([string]::IsNullOrWhiteSpace($txt)) {
          [System.Windows.MessageBox]::Show("The selected file is empty.", "Create Addon", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
          return $false
        }
        $baseName = ''
        try { $baseName = [string][IO.Path]::GetFileNameWithoutExtension($picked) } catch { $baseName = '' }
        if (-not [string]::IsNullOrWhiteSpace($baseName)) {
          try { $nameBox.Text = [string]$baseName } catch {}
        }
        try { $funcBox.Text = $txt } catch {}
        try { $funcBox.CaretIndex = 0 } catch {}
        try { $funcBox.Focus() } catch {}
        return $true
      } catch {
        [System.Windows.MessageBox]::Show(
          ("Failed to import file.`n`n" + [string]$_.Exception.Message),
          "Create Addon",
          [System.Windows.MessageBoxButton]::OK,
          [System.Windows.MessageBoxImage]::Error
        ) | Out-Null
        return $false
      }
    }
    $addonDragOver = {
      param($sender, $e)
      try {
        $picked = ''
        try { $picked = & $resolveDroppedRegPath $e.Data } catch { $picked = '' }
        if (-not [string]::IsNullOrWhiteSpace($picked)) {
          $e.Effects = [System.Windows.DragDropEffects]::Copy
        } else {
          $e.Effects = [System.Windows.DragDropEffects]::None
        }
        $e.Handled = $true
      } catch {}
    }
    $addonDrop = {
      param($sender, $e)
      try {
        $picked = ''
        try { $picked = & $resolveDroppedRegPath $e.Data } catch { $picked = '' }
        if ([string]::IsNullOrWhiteSpace($picked)) {
          try { $e.Effects = [System.Windows.DragDropEffects]::None } catch {}
          try { $e.Handled = $true } catch {}
          if (Test-AllowInvalidAddonDropWarning -Scope Dialog) {
            [System.Windows.MessageBox]::Show("Drop a valid .reg or .txt file.", "Create Addon", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
          }
          return
        }
        [void](& $importDroppedRegIntoFields $picked)
        $e.Handled = $true
      } catch {}
    }
    foreach ($dropSurface in @($dlg, $outerBorder, $nameBox, $funcBox, $noteBox)) {
      if (-not $dropSurface) { continue }
      try { $dropSurface.AllowDrop = $true } catch {}
      try { $dropSurface.Add_PreviewDragOver($addonDragOver) } catch {}
      try { $dropSurface.Add_PreviewDrop($addonDrop) } catch {}
    }
    if ($funcBox) {
      try { $funcBox.AcceptsReturn = $true; $funcBox.TextWrapping = [System.Windows.TextWrapping]::Wrap } catch {}
      try { $funcBox.AllowDrop = $true } catch {}
      try { $funcBox.VerticalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Auto } catch {}
      try { $funcBox.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Disabled } catch {}
      try { $funcBox.ToolTip = "You can drag a .reg or .txt file anywhere in this window to auto-fill Name + Function." } catch {}
      # Drag/drop handlers are wired on all dialog surfaces above via Preview events.
    }
    if ($noteBox) {
      try { $noteBox.AcceptsReturn = $true; $noteBox.TextWrapping = [System.Windows.TextWrapping]::Wrap } catch {}
      try { $noteBox.VerticalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Auto } catch {}
      try { $noteBox.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Disabled } catch {}
    }
    $abortBtn = $dlg.FindName('AddonAbortBtn')
    $createBtn = $dlg.FindName('AddonCreateBtn')
    try { if ($createBtn -and -not [string]::IsNullOrWhiteSpace($PrimaryButtonText)) { $createBtn.Content = [string]$PrimaryButtonText } } catch {}
    foreach ($b in @($abortBtn,$createBtn)) {
      if (-not $b) { continue }
      try { $b.Style = $window.Resources['RightPanelNavButtonStyle'] } catch {}
      try { $b.Background = $btnb; $b.BorderBrush = $bd; $b.Foreground = $fg } catch {}
    }
    $script:__addonCreateResult = $null
    if ($abortBtn) { $abortBtn.Add_Click({ $script:__addonCreateResult = $null; $dlg.Close() }) }
    if ($createBtn) {
      $createBtn.Add_Click({
        try {
          $nm = ''
          $fn = ''
          $nt = ''
          try { $nm = [string]$nameBox.Text } catch { $nm = '' }
          try { $fn = [string]$funcBox.Text } catch { $fn = '' }
          try { $nt = [string]$noteBox.Text } catch { $nt = '' }
          $nm = (Trim-NameInputPreserveNbsp -Text $nm)
          if ([string]::IsNullOrWhiteSpace($nm)) {
            [System.Windows.MessageBox]::Show("Name is required.", "Create Addon", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
            return
          }
          if ([string]::IsNullOrWhiteSpace($fn)) {
            [System.Windows.MessageBox]::Show("Function is required.", "Create Addon", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
            return
          }
          $safeName = [string]$nm
          foreach ($ch in [IO.Path]::GetInvalidFileNameChars()) {
            $safeName = $safeName.Replace([string]$ch, '_')
          }
          $safeName = (Trim-NameInputPreserveNbsp -Text $safeName)
          if ([string]::IsNullOrWhiteSpace($safeName)) {
            [System.Windows.MessageBox]::Show("Invalid addon name.", "Create Addon", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
            return
          }
          $root = Get-AddonsRoot
          if ([string]::IsNullOrWhiteSpace($root)) {
            [System.Windows.MessageBox]::Show("Addons folder is unavailable.", "Create Addon", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) | Out-Null
            return
          }
          $dst = Join-Path $root ($safeName + '.reg')
          if (Test-Path -LiteralPath $dst -PathType Leaf) {
            $sameAsExisting = $false
            try {
              $existingNorm = [string]$ExistingFileName
              if (-not [string]::IsNullOrWhiteSpace($existingNorm) -and -not $existingNorm.ToLowerInvariant().EndsWith('.reg')) { $existingNorm += '.reg' }
              $sameAsExisting = (-not [string]::IsNullOrWhiteSpace($existingNorm) -and ([string]$existingNorm -ieq ([string]$safeName + '.reg')))
            } catch { $sameAsExisting = $false }
            if ($sameAsExisting) {
              # editing same file name; allow save without overwrite prompt
            } else {
              $okOverwrite = Show-ContinueCancelDialog -Title "Create Addon" -Message ("Addon already exists:`n`n" + $safeName + ".reg`n`nOverwrite?") -ContinueText "YES" -CancelText "NO"
              if (-not $okOverwrite) { return }
            }
          }
          $script:__addonCreateResult = [pscustomobject]@{
            Name = [string]$nm
            Function = [string]$fn
            Notes = [string]$nt
          }
          $dlg.Close()
        } catch {}
      })
    }
    $null = $dlg.ShowDialog()
    $result = $script:__addonCreateResult
    if ($OnSubmit -and $result) {
      try { & $OnSubmit $result } catch {
        [System.Windows.MessageBox]::Show(
          ("Create Addon failed.`n`n" + [string]$_.Exception.Message),
          "Create Addon",
          [System.Windows.MessageBoxButton]::OK,
          [System.Windows.MessageBoxImage]::Error
        ) | Out-Null
      }
    }
    return $result
  } catch {
    return $null
  }
}
function Write-AddonRegFileFromPayload {
  param(
    [Parameter(Mandatory=$true)][object]$Payload,
    [string]$ExistingFileName = ''
  )
  try {
    $root = Get-AddonsRoot
    if ([string]::IsNullOrWhiteSpace($root)) { throw "Addons folder is unavailable." }
    $name = [string](Get-PropString -Obj $Payload -Names @('Name') -Fallback '')
    $func = [string](Get-PropString -Obj $Payload -Names @('Function') -Fallback '')
    $note = [string](Get-PropString -Obj $Payload -Names @('Notes') -Fallback '')
    $safeName = [string]$name
    foreach ($ch in [IO.Path]::GetInvalidFileNameChars()) {
      $safeName = $safeName.Replace([string]$ch, '_')
    }
    $safeName = (Trim-NameInputPreserveNbsp -Text $safeName)
    if ([string]::IsNullOrWhiteSpace($safeName)) { throw "Invalid addon name." }
    $dst = Join-Path $root ($safeName + '.reg')
    $dstLeaf = ''
    try { $dstLeaf = [string][IO.Path]::GetFileName($dst) } catch { $dstLeaf = '' }
    $oldPath = ''
    $existingFileNorm = ''
    try {
      $existingFileNorm = [string]$ExistingFileName
      if (-not [string]::IsNullOrWhiteSpace($existingFileNorm) -and -not $existingFileNorm.ToLowerInvariant().EndsWith('.reg')) { $existingFileNorm += '.reg' }
      if (-not [string]::IsNullOrWhiteSpace($existingFileNorm)) { $oldPath = Join-Path $root $existingFileNorm }
    } catch { $oldPath = '' }
    $oldLeaf = ''
    try { if (-not [string]::IsNullOrWhiteSpace($existingFileNorm)) { $oldLeaf = [string][IO.Path]::GetFileName($existingFileNorm) } } catch { $oldLeaf = '' }

    # Case-only rename handling:
    # if source/destination resolve to same path (case-insensitive) but name casing differs,
    # force casing update via temporary rename hop.
    try {
      if (-not [string]::IsNullOrWhiteSpace($oldPath) -and (Test-Path -LiteralPath $oldPath -PathType Leaf)) {
        $dstPathNorm0 = Normalize-Path ([string]$dst)
        $oldPathNorm0 = Normalize-Path ([string]$oldPath)
        $sameResolvedPath = (-not [string]::IsNullOrWhiteSpace($dstPathNorm0) -and -not [string]::IsNullOrWhiteSpace($oldPathNorm0) -and ($dstPathNorm0 -ieq $oldPathNorm0))
        $caseOnlyNameChange = (-not [string]::IsNullOrWhiteSpace($oldLeaf) -and -not [string]::IsNullOrWhiteSpace($dstLeaf) -and ($oldLeaf -ieq $dstLeaf) -and ($oldLeaf -cne $dstLeaf))
        if ($sameResolvedPath -and $caseOnlyNameChange) {
          $tmpCaseHop = ''
          try { $tmpCaseHop = Join-Path $root ("__smlt_casehop_" + [guid]::NewGuid().ToString('N') + ".tmp") } catch { $tmpCaseHop = '' }
          if (-not [string]::IsNullOrWhiteSpace($tmpCaseHop)) {
            Move-Item -LiteralPath $oldPath -Destination $tmpCaseHop -Force -ErrorAction Stop
            Move-Item -LiteralPath $tmpCaseHop -Destination $dst -Force -ErrorAction Stop
            $oldPath = [string]$dst
          }
        }
      }
    } catch {}
    # Ensure registry header exists once at the top:
    # if already present (v5 or REGEDIT4), do not prepend another.
    $funcText = [string]$func
    $checkText = [string]$funcText
    try {
      if ($checkText.Length -gt 0 -and [int][char]$checkText[0] -eq 0xFEFF) {
        $checkText = $checkText.Substring(1)
      }
    } catch {}
    if ($checkText -match '^\s*(Windows Registry Editor Version 5\.00|REGEDIT4)\s*(\r?\n|$)') {
      $content = $funcText
    } else {
      $content = "Windows Registry Editor Version 5.00`r`n`r`n$funcText"
    }
    [System.IO.File]::WriteAllText($dst, $content, [System.Text.Encoding]::Unicode)
    try { Set-AddonNoteForFile -FileName ([string][IO.Path]::GetFileName($dst)) -Note ([string]$note) } catch {}
    try {
      if (-not [string]::IsNullOrWhiteSpace($oldPath)) {
        $dstPathNorm = Normalize-Path ([string]$dst)
        $oldPathNorm = Normalize-Path ([string]$oldPath)
        if (-not [string]::IsNullOrWhiteSpace($oldPathNorm) -and -not [string]::IsNullOrWhiteSpace($dstPathNorm) -and ($oldPathNorm -ine $dstPathNorm)) {
          if (Test-Path -LiteralPath $oldPath -PathType Leaf) { Remove-Item -LiteralPath $oldPath -Force -ErrorAction SilentlyContinue }
          Remove-AddonNoteForFile -FileName ([string]$existingFileNorm)
        }
      }
    } catch {}
    return [string]$dst
  } catch {
    throw
  }
}

