$addonPanelDragOver = {
  param($sender, $e)
  try {
    $paths = @(Get-RegFilePathsFromDragData -DataObject $e.Data -AllowedExtensions @('.reg','.txt'))
    if (@($paths).Count -gt 0) {
      $e.Effects = [System.Windows.DragDropEffects]::Copy
      $e.Handled = $true
    } else {
      $e.Effects = [System.Windows.DragDropEffects]::None
      $e.Handled = $true
    }
  } catch {}
}
$addonPanelDrop = {
  param($sender, $e)
  try {
    $paths = @(Get-RegFilePathsFromDragData -DataObject $e.Data -AllowedExtensions @('.reg','.txt'))
    if (@($paths).Count -eq 0) {
      try { $e.Effects = [System.Windows.DragDropEffects]::None } catch {}
      try { $e.Handled = $true } catch {}
      if (Test-AllowInvalidAddonDropWarning -Scope Panel) {
        [System.Windows.MessageBox]::Show("Drop one or more valid .reg or .txt files.", "Import Addons", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
      }
      return
    }
    $res = Import-AddonRegFilesFromPaths -Paths @($paths) -PromptOnOverwrite
    try { Refresh-MiscAddonsPanel -SearchText ([string]$miscAddonsSearchBox.Text) } catch { try { Refresh-MiscAddonsPanel } catch {} }
    try { Update-MiscAddonsButtonsColumns } catch {}
    if ([int]$res.Failed -gt 0) {
      $errLine = ''
      try { $errLine = [string](@($res.Errors) | Select-Object -First 1) } catch { $errLine = '' }
      [System.Windows.MessageBox]::Show(
        ("Addon import completed with errors.`n`nImported: {0}`nSkipped: {1}`nFailed: {2}`n{3}" -f [int]$res.Imported, [int]$res.Skipped, [int]$res.Failed, $errLine),
        "Import Addons",
        [System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]::Warning
      ) | Out-Null
    }
    $e.Handled = $true
  } catch {
    [System.Windows.MessageBox]::Show(
      ("Addon import failed.`n`n" + [string]$_.Exception.Message),
      "Import Addons",
      [System.Windows.MessageBoxButton]::OK,
      [System.Windows.MessageBoxImage]::Error
    ) | Out-Null
  }
}
foreach ($dropSurface in @($miscAddonsPanelScroll, $miscAddonsButtonsHost, $miscAddonsEmptyText)) {
  if (-not $dropSurface) { continue }
  try { $dropSurface.AllowDrop = $true } catch {}
  try { $dropSurface.Add_PreviewDragOver($addonPanelDragOver) } catch {}
  try { $dropSurface.Add_PreviewDrop($addonPanelDrop) } catch {}
}

