        throw "Addons folder is unavailable."
      }
      if (-not (Test-Path -LiteralPath $addonsRoot -PathType Container)) {
        New-Item -ItemType Directory -Path $addonsRoot -Force | Out-Null
      }
      Start-Process -FilePath (Join-Path $env:WINDIR 'explorer.exe') -ArgumentList @("`"$addonsRoot`"") | Out-Null
    } catch {
      [System.Windows.MessageBox]::Show(
        ("Open Addons folder directory failed.`n`n" + [string]$_.Exception.Message),
        "Addons",
        [System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]::Error
      ) | Out-Null
    }
  })
