if ($miscRestoreAdminToolsBtn) {
  $miscRestoreAdminToolsBtn.Add_Click({
    End-GridEditTransaction
    try {
      $okRestore = Show-ContinueCancelDialog -Title "Restore Windows Administrative Tools" -Message "Original Windows Administrative Tools folder will now be recreated. Would you like to proceed?" -ContinueText "YES" -CancelText "NO"
      if (-not $okRestore) { return }
      if (-not (Ensure-ElevatedOrPrompt -Reason "Restoring Windows Administrative Tools requires Administrator.")) { return }
      $res = Invoke-RestoreWindowsAdministrativeTools
      try {
        $script:PrepareStartMenuApprovedAdminSession = $false
        $script:PrepareStartMenuApprovedSession = ([bool]$script:PrepareStartMenuApprovedCoreSession -or [bool]$script:PrepareStartMenuApprovedAdminSession)
      } catch {}
      Invoke-ReloadStartMenuModelAfterFilesystemChange
      if (@($res.Errors).Count -gt 0) {
        $errText = (@($res.Errors) | Select-Object -First 10) -join "`n"
        if (@($res.Errors).Count -gt 10) { $errText += "`n... (more errors omitted)" }
        [System.Windows.MessageBox]::Show(
          ("Restore completed with errors.`n`nMoved from prepared: {0}`nCopied to current user: {1}`nSeeded: {2}`n`n{3}" -f [int]$res.MovedFromPrepared, [int]$res.CopiedToCurrentUser, [int]$res.Seeded, $errText),
          "Restore Windows Administrative Tools",
          [System.Windows.MessageBoxButton]::OK,
          [System.Windows.MessageBoxImage]::Warning
        ) | Out-Null
      } else {
        [System.Windows.MessageBox]::Show(
          "You might need to log out and back in to your account for changes to take effect.",
          "Restore Windows Administrative Tools",
          [System.Windows.MessageBoxButton]::OK,
          [System.Windows.MessageBoxImage]::Information
        ) | Out-Null
      }
    } catch {
      [System.Windows.MessageBox]::Show(
        ("Restore failed.`n`n" + [string]$_.Exception.Message),
        "Restore Windows Administrative Tools",
        [System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]::Error
      ) | Out-Null
    }
  })
}

if ($miscBlurGridWallpaperBox) {
