  $applyDisableDupFlag = {
    param($isOn)
    try { $script:DisableDuplicateShortcutFlagging = [bool]$isOn } catch {}
    if ($isOn) {
      try { $script:DuplicateTargetPathSet = @{} } catch {}
      try { $script:DuplicateTargetPathSetReady = $true } catch {}
      try { $script:DuplicateTargetExpandPendingRebuild = $false } catch {}
    } else {
      try { $script:DuplicateTargetPathSet = @{} } catch {}
      try { $script:DuplicateTargetPathSetReady = $false } catch {}
    }
    try { Refresh-VisibleTargetDuplicateOverlayFlags } catch {}
    try { Refresh-UIAsync } catch {}
    try { Queue-RebuildVisibleRows } catch {}
  }
  $miscDisableDuplicateFlaggingBox.Add_Checked({ & $applyDisableDupFlag $true })
