      Items = @(
        'Gray tile background = currently selected (from ''Show'' column) category''s icons.',
        'Dark gray border = icon is categorized and its category is not selected.',
        'Blue border = pending add/assign state (when selecting icons with the "Dark gray border"). 
1) Tick the checkbox in the ''Select'' columnin of a category. 
2a) To ADD: Begin chosing icons that have not already been saved to the selected category, then click on ''Save Category'' button at the top UI panel.',
        'Red border = pending remove/unbind state (when selecting icons with the "Gray tile background"). 
2b) To REMOVE: Begin clicking on icons that have already been saved to the selected category, then click on ''Save Category'' button at the top UI panel',
        'Orange border = selected for icon extraction. **1) Tick the checkbox of ''☑ Select icons to extract'' at the top of the UI panel. 
2) Select icon(s) to extract. 3) Press ''Extract'' button and then chose if you want the file to be extracted as an .ico or a .png format.',
        'Light gray border = temporary selection without any active ''Select'' category.'
      )
    }
  )
}

function Show-InfoGuideDialog {
  param(
    [System.Windows.Window]$OwnerWindow = $null
  )
  try {
    try {
      if ((Test-Path variable:script:InfoGuideWindow) -and $script:InfoGuideWindow) {
        if ($script:InfoGuideWindow.IsVisible) {
          try { $script:InfoGuideWindow.Activate() } catch {}
          return
        }
      }
    } catch {}
    $isDarkGuide = ([string]$script:UiThemeMode -ieq 'Dark')
    $fallbackHexSurface = if ($isDarkGuide) { '#202020' } else { '#E1E1E1' }
    # Use a stronger foreground in dark mode so text cannot visually disappear.
    $fallbackHexText    = if ($isDarkGuide) { '#D4D4D4' } else { '#202020' }
    $fallbackHexBorder  = if ($isDarkGuide) { '#3A3A3A' } else { '#BEBEBE' }
    $surfaceBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($fallbackHexSurface))
    $textBrush    = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($fallbackHexText))
    $borderBrush  = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($fallbackHexBorder))
    $dlg = New-Object System.Windows.Window
    $dlg.Title = 'Start Menu Lite Tools Guide'
    $dlg.Width = 780
    $dlg.Height = 720
    $dlg.MinWidth = 620
    $dlg.MinHeight = 500
    $dlg.ShowInTaskbar = $true
    $dlg.ResizeMode = [System.Windows.ResizeMode]::CanResize
    $dlg.Background = $surfaceBrush
    $dlg.Foreground = $textBrush
    $dlg.WindowStartupLocation = if ($OwnerWindow) { [System.Windows.WindowStartupLocation]::CenterOwner } else { [System.Windows.WindowStartupLocation]::CenterScreen }
    if ($OwnerWindow) { try { $dlg.Owner = $OwnerWindow } catch {} }
    function Apply-InfoGuideThemeToVisualTree {
      param(
        [System.Windows.DependencyObject]$Root,
        [System.Windows.Media.Brush]$ForegroundBrush,
        [System.Windows.Media.Brush]$BackgroundBrush,
        [System.Windows.Media.Brush]$BorderBrushLocal
      )
      try {
        if (-not $Root) { return }
        if ($Root -is [System.Windows.Controls.TextBlock]) {
          try { $Root.Foreground = $ForegroundBrush } catch {}
        } elseif ($Root -is [System.Windows.Controls.TextBox]) {
          try { $Root.Foreground = $ForegroundBrush } catch {}
          try { $Root.CaretBrush = $ForegroundBrush } catch {}
          try { $Root.Background = [System.Windows.Media.Brushes]::Transparent } catch {}
        } elseif ($Root -is [System.Windows.Controls.Button]) {
          try { $Root.Foreground = $ForegroundBrush } catch {}
          try { $Root.Background = $BackgroundBrush } catch {}
          try { $Root.BorderBrush = $BorderBrushLocal } catch {}
        } elseif ($Root -is [System.Windows.Controls.Control]) {
          try { $Root.Foreground = $ForegroundBrush } catch {}
        } elseif ($Root -is [System.Windows.Controls.Border]) {
          try { $Root.BorderBrush = $BorderBrushLocal } catch {}
        }
        $childCount = 0
        try { $childCount = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($Root) } catch { $childCount = 0 }
        for ($i = 0; $i -lt $childCount; $i++) {
          $child = $null
          try { $child = [System.Windows.Media.VisualTreeHelper]::GetChild($Root, $i) } catch { $child = $null }
          if ($child) { Apply-InfoGuideThemeToVisualTree -Root $child -ForegroundBrush $ForegroundBrush -BackgroundBrush $BackgroundBrush -BorderBrushLocal $BorderBrushLocal }
        }
      } catch {}
    }
    $root = New-Object System.Windows.Controls.Grid
    $rowMain = New-Object System.Windows.Controls.RowDefinition
    $rowMain.Height = New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star)
    $rowBtns = New-Object System.Windows.Controls.RowDefinition
    $rowBtns.Height = New-Object System.Windows.GridLength(48)
    [void]$root.RowDefinitions.Add($rowMain)
    [void]$root.RowDefinitions.Add($rowBtns)
    $iconCache = @{}
    function Resolve-GuideIconSource {
      param(
        [string]$ModuleFile,
        [int]$IconIndex
      )
      try {
        if ([string]::IsNullOrWhiteSpace($ModuleFile)) { return $null }
        $k = ('{0}|{1}' -f $ModuleFile, $IconIndex)
        if ($iconCache.ContainsKey($k)) { return $iconCache[$k] }
        $modulePath = Join-Path $env:WINDIR ("System32\" + $ModuleFile)
        $img = $null
        try { $img = Get-ImageSourceFromIcon -IconPath $modulePath -IconIndex $IconIndex -FallbackExePath $modulePath } catch { $img = $null }
        if (-not $img) {
          try { $img = Get-ImageSourceFromIcon -IconPath $modulePath -IconIndex (-1 * [int]$IconIndex) -FallbackExePath $modulePath } catch { $img = $null }
        }
        $iconCache[$k] = $img
        return $img
      } catch { return $null }
    }
    function Get-GuideItemIconSource {
      param([string]$ItemText)
      try {
        $t = [string]$ItemText
        if ([string]::IsNullOrWhiteSpace($t)) { return $null }
        switch -regex ($t) {
          '^Undo/Redo:'                    { return (Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 299) }
          '^Delete Selected:'              { return (Resolve-GuideIconSource -ModuleFile 'imageres.dll' -IconIndex 235) }
          '^Un-Delete Selected:'           { return (Resolve-GuideIconSource -ModuleFile 'imageres.dll' -IconIndex 76) }
          '^Prepare Start Menu'            { return (Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 39) }
          '^Create Backup'                 { return (Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 258) }
          '^Restore Backup'                { return (Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 239) }
          '^Save Pending'                  { return (Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 295) }
          '^Load Pending'                  { return (Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 132) }
          '^Refresh Grid:'                 { return (Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 238) }
          '^Clear Selection:'             { return (Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 100) }
          '^Clear Pending:'                { return (Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 152) }
          '^Apply All Changes:'            { return (Resolve-GuideIconSource -ModuleFile 'comres.dll' -IconIndex 16) }
          '^Theme button'                  { return (Resolve-GuideIconSource -ModuleFile 'imageres.dll' -IconIndex 332) }
          default                          { return $null }
        }
      } catch { return $null }
    }
    function New-GuideBrushFromHex {
      param(
        [string]$Hex,
        [string]$FallbackHex = '#9A9A9A'
      )
      try {
        $h = [string]$Hex
        if ([string]::IsNullOrWhiteSpace($h)) { $h = [string]$FallbackHex }
        return (New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($h)))
      } catch {
        try { return (New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($FallbackHex))) } catch { return $null }
      }
    }
    function Get-GuideVisualSpecByText {
      param([string]$DisplayText)
      $res = [pscustomobject]@{
        IconSource      = $null
        BorderBrush     = $null
        BorderThickness = 0
        CornerRadius    = 0
        TileBackground  = $null
      }
      try {
        $t = ''
        try { $t = ([string]$DisplayText).Trim() } catch { $t = '' }
        if ([string]::IsNullOrWhiteSpace($t)) { return $res }
        switch -regex ($t) {
          '^Save category:' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 295
            break
          }
          '^Load category:' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 68
            break
          }
          '^Delete Selected Category:' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 152
            break
          }
          '^Backup Icon Pack Directory:' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 5
            break
          }
          '^Refresh:' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 238
            break
          }
          '^Clear Selection:' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 100
            break
          }
          '^Select icons to extract \+ Extract:' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'imageres.dll' -IconIndex 288
            break
          }
          '^Gray tile background =' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 0
            $res.BorderThickness = 1
            $res.BorderBrush = New-GuideBrushFromHex -Hex '#696969'
            $res.CornerRadius = 3
            $res.TileBackground = New-GuideBrushFromHex -Hex '#a0a0a0'
            break
          }
          '^Dark gray border =' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 0
            $res.BorderThickness = 1
            $res.BorderBrush = New-GuideBrushFromHex -Hex '#696969'
            $res.CornerRadius = 3
            break
          }
          '^Blue border =' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 0
            $res.BorderThickness = 2
            $res.BorderBrush = New-GuideBrushFromHex -Hex '#3A7BFF'
            $res.CornerRadius = 3
            break
          }
          '^Red border =' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 0
            $res.BorderThickness = 2
            $res.BorderBrush = New-GuideBrushFromHex -Hex '#D9534F'
            $res.CornerRadius = 3
            break
          }
          '^Orange border =' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 0
            $res.BorderThickness = 2
            $res.BorderBrush = New-GuideBrushFromHex -Hex '#F0A020'
            $res.CornerRadius = 3
            break
          }
          '^Light gray border =' {
            $res.IconSource = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 0
            $res.BorderThickness = 2
            $res.BorderBrush = New-GuideBrushFromHex -Hex '#C8C8C8'
            $res.CornerRadius = 3
            break
          }
        }
      } catch {}
      return $res
    }
    $sv = New-Object System.Windows.Controls.ScrollViewer
    $sv.VerticalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Auto
    $sv.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Disabled
    $sv.Margin = New-Object System.Windows.Thickness(10,10,10,0)
    $sv.Background = $surfaceBrush
    $sv.BorderBrush = $borderBrush
    $sv.BorderThickness = New-Object System.Windows.Thickness(1)
    [System.Windows.Controls.Grid]::SetRow($sv, 0)
    $stack = New-Object System.Windows.Controls.StackPanel
    $stack.Orientation = [System.Windows.Controls.Orientation]::Vertical
    $stack.Margin = New-Object System.Windows.Thickness(8)
    $headRow = New-Object System.Windows.Controls.StackPanel
    $headRow.Orientation = [System.Windows.Controls.Orientation]::Horizontal
    $headRow.Margin = New-Object System.Windows.Thickness(0,0,0,6)
    $headRow.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $headIcon = New-Object System.Windows.Controls.Image
    $headIcon.Source = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 221
    $headIcon.Width = 24
    $headIcon.Height = 24
    $headIcon.Margin = New-Object System.Windows.Thickness(0,0,8,-3)
    $headIcon.Stretch = [System.Windows.Media.Stretch]::Uniform
    $headIcon.SnapsToDevicePixels = $true
    [void]$headRow.Children.Add($headIcon)
    $head = New-Object System.Windows.Controls.TextBlock
    $head.Text = 'Start Menu Lite Tools Guide'
    $head.FontSize = 18
    $head.FontWeight = [System.Windows.FontWeights]::SemiBold
    $head.Foreground = $textBrush
    $head.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    [void]$headRow.Children.Add($head)
    [void]$stack.Children.Add($headRow)
    $tip = New-Object System.Windows.Controls.TextBlock
    $tip.Text = '_____________________________________________________________________________________________________________________________________________'
    $tip.FontSize = 12
    $tip.Margin = New-Object System.Windows.Thickness(0,0,0,10)
    $tip.Foreground = $textBrush
    [void]$stack.Children.Add($tip)
    foreach ($sec in @(Get-InfoGuideSections)) {
      $secIndent = 0
      try {
        if ($sec.PSObject.Properties.Match('Indent').Count -gt 0) { $secIndent = [int]$sec.Indent }
      } catch { $secIndent = 0 }
      if ($secIndent -lt 0) { $secIndent = 0 }
      $secTitle = [string]$sec.Title
      if ($secTitle -like 'Icon Allocator*') {
        $titleRow = New-Object System.Windows.Controls.StackPanel
        $titleRow.Orientation = [System.Windows.Controls.Orientation]::Horizontal
        $titleRow.Margin = New-Object System.Windows.Thickness($secIndent,8,0,4)
        $titleRow.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $titleIcon = New-Object System.Windows.Controls.Image
        try { $titleIcon.Source = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 327 } catch { $titleIcon.Source = $null }
        $titleIcon.Width = 18
        $titleIcon.Height = 18
        $titleIcon.Margin = New-Object System.Windows.Thickness(0,0,6,0)
        $titleIcon.Stretch = [System.Windows.Media.Stretch]::Uniform
        $titleIcon.SnapsToDevicePixels = $true
        [void]$titleRow.Children.Add($titleIcon)
        $title = New-Object System.Windows.Controls.TextBlock
        $title.Text = $secTitle
        $title.FontSize = 16
        $title.FontWeight = [System.Windows.FontWeights]::SemiBold
        $title.Foreground = $textBrush
        $title.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        [void]$titleRow.Children.Add($title)
        [void]$stack.Children.Add($titleRow)
      } else {
        $title = New-Object System.Windows.Controls.TextBlock
        $title.Text = $secTitle
        $title.FontSize = 13
        $title.FontWeight = [System.Windows.FontWeights]::SemiBold
        $title.Margin = New-Object System.Windows.Thickness($secIndent,8,0,4)
        $title.Foreground = $textBrush
        [void]$stack.Children.Add($title)
      }
      foreach ($item in @($sec.Items)) {
        $row = New-Object System.Windows.Controls.Grid
        $row.Margin = New-Object System.Windows.Thickness($secIndent,0,0,2)
        [void]$row.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition -Property @{ Width = [System.Windows.GridLength]::Auto }))
        [void]$row.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition -Property @{ Width = New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star) }))
        $itemText = [string]$item
        $displayText = $itemText
        $iconSrc = $null
        $customVisualAdded = $false
        $visualSpec = Get-GuideVisualSpecByText -DisplayText $displayText
        if ($visualSpec) {
          $iconSrc = $visualSpec.IconSource
          $bt = 0
          try { $bt = [int]$visualSpec.BorderThickness } catch { $bt = 0 }
          $hasTileBg = $false
          try { $hasTileBg = ($null -ne $visualSpec.TileBackground) } catch { $hasTileBg = $false }
          if ($iconSrc -and ($bt -gt 0 -or $hasTileBg)) {
            $sample = New-Object System.Windows.Controls.Border
            $sample.Width = 22
            $sample.Height = 22
            $sample.Margin = New-Object System.Windows.Thickness(0,1,6,0)
            if ($hasTileBg) { $sample.Background = $visualSpec.TileBackground } else { $sample.Background = [System.Windows.Media.Brushes]::Transparent }
            $sample.BorderThickness = New-Object System.Windows.Thickness($bt)
            if ($bt -gt 0) {
              try { $sample.BorderBrush = $visualSpec.BorderBrush } catch { $sample.BorderBrush = [System.Windows.Media.Brushes]::Gray }
            } else {
              $sample.BorderBrush = [System.Windows.Media.Brushes]::Transparent
            }
            $cr = 0
            try { $cr = [double]$visualSpec.CornerRadius } catch { $cr = 0 }
            if ($cr -gt 0) { $sample.CornerRadius = New-Object System.Windows.CornerRadius($cr) }
            $sampleImg = New-Object System.Windows.Controls.Image
            $sampleImg.Source = $iconSrc
            $sampleImg.Width = 16
            $sampleImg.Height = 16
            $sampleImg.Stretch = [System.Windows.Media.Stretch]::Uniform
            $sampleImg.SnapsToDevicePixels = $true
            $sample.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Left
            $sample.VerticalAlignment = [System.Windows.VerticalAlignment]::Top
            $sample.Child = $sampleImg
            [System.Windows.Controls.Grid]::SetColumn($sample, 0)
            [void]$row.Children.Add($sample)
            $customVisualAdded = $true
          }
        }
        if (-not $customVisualAdded -and ($displayText -match '^Duplicate \+ broken-link overlay sample =')) {
          $sample = New-Object System.Windows.Controls.Border
          $sample.Width = 22
          $sample.Height = 22
          $sample.Margin = New-Object System.Windows.Thickness(0,1,6,0)
          $sample.Background = New-GuideBrushFromHex -Hex '#7A7A7A'
          $sample.BorderThickness = New-Object System.Windows.Thickness(1)
          $sample.BorderBrush = New-GuideBrushFromHex -Hex '#696969'
          $sample.CornerRadius = New-Object System.Windows.CornerRadius(3)

          $sampleGrid = New-Object System.Windows.Controls.Grid

          $baseIcon = New-Object System.Windows.Controls.Image
          $baseIcon.Source = Resolve-GuideIconSource -ModuleFile 'shell32.dll' -IconIndex 0
          $baseIcon.Width = 16
          $baseIcon.Height = 16
          $baseIcon.Stretch = [System.Windows.Media.Stretch]::Uniform
          $baseIcon.SnapsToDevicePixels = $true
          $baseIcon.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
          $baseIcon.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
          [void]$sampleGrid.Children.Add($baseIcon)

          $dupOverlay = New-Object System.Windows.Controls.Image
          $dupOverlay.Source = Get-DuplicateTargetOverlayIconSource
          $dupOverlay.Width = 12
          $dupOverlay.Height = 12
          $dupOverlay.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Right
          $dupOverlay.VerticalAlignment = [System.Windows.VerticalAlignment]::Top
          $dupOverlay.Margin = New-Object System.Windows.Thickness(0,-3,-9,0)
          $dupOverlay.Stretch = [System.Windows.Media.Stretch]::Uniform
          $dupOverlay.SnapsToDevicePixels = $true
          [void]$sampleGrid.Children.Add($dupOverlay)

          $brokenOverlay = New-Object System.Windows.Controls.Image
          $brokenOverlay.Source = Resolve-GuideIconSource -ModuleFile 'compstui.dll' -IconIndex 1
          $brokenOverlay.Width = 17
          $brokenOverlay.Height = 17
          $brokenOverlay.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Right
          $brokenOverlay.VerticalAlignment = [System.Windows.VerticalAlignment]::Bottom
          $brokenOverlay.Margin = New-Object System.Windows.Thickness(0,0,-11,-6)
          $brokenOverlay.Stretch = [System.Windows.Media.Stretch]::Uniform
          $brokenOverlay.SnapsToDevicePixels = $true
          [void]$sampleGrid.Children.Add($brokenOverlay)

          $sample.Child = $sampleGrid
          [System.Windows.Controls.Grid]::SetColumn($sample, 0)
          [void]$row.Children.Add($sample)
          $customVisualAdded = $true
        }
        if (-not $customVisualAdded) {
          if (-not $iconSrc) { $iconSrc = Get-GuideItemIconSource -ItemText $displayText }
          if ($iconSrc) {
            $img = New-Object System.Windows.Controls.Image
            $img.Source = $iconSrc
            $img.Width = 20
            $img.Height = 20
            $img.Margin = New-Object System.Windows.Thickness(0,1,6,0)
            $img.Stretch = [System.Windows.Media.Stretch]::Uniform
            $img.SnapsToDevicePixels = $true
            [System.Windows.Controls.Grid]::SetColumn($img, 0)
            [void]$row.Children.Add($img)
          }
        }
        $lineText = [string]$displayText
        $trimText = ''
        try { $trimText = $lineText.Trim() } catch { $trimText = $lineText }
        $isHeadingItem = $false
        if ($trimText -in @('Manage categories panel:', 'Right panel tabs:', 'Icon color and border states:')) {
          $isHeadingItem = $true
        }
        $tokenWord = ''
        $tokenBrush = $null
        $tokenBold = $false
        if ($lineText -match "^The 'Select' column") {
          $tokenWord = "'Select'"
          $tokenBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString('#2FA44F'))
          $tokenBold = $true
        } elseif ($lineText -match "^The 'Show' column") {
          $tokenWord = "'Show'"
          $tokenBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString('#3A7BFF'))
          $tokenBold = $true
        } elseif ($lineText -match "^The 'Mask' column") {
          $tokenWord = "'Mask'"
          $tokenBrush = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString('#D9534F'))
          $tokenBold = $true
        } elseif ($lineText -match "^\[Icon pack directory\]") {
          $tokenWord = "[Icon pack directory]"
          $tokenBrush = $textBrush
          $tokenBold = $true
        } elseif ($lineText -match "^\[Categorised icons\]") {
          $tokenWord = "[Categorised icons]"
          $tokenBrush = $textBrush
          $tokenBold = $true
        }
        $handledInlineExtract = $false
        if ($lineText -like '*Select icons to extract + Extract:*') {
          $inline = New-Object System.Windows.Controls.TextBlock
          $inline.TextWrapping = [System.Windows.TextWrapping]::Wrap
          $inline.Foreground = $textBrush
          $inline.Background = [System.Windows.Media.Brushes]::Transparent
          $inline.Margin = New-Object System.Windows.Thickness(0)
          $inline.Padding = New-Object System.Windows.Thickness(0)
          $extractPrefix = ''
          try { $extractPrefix = [regex]::Match($lineText, '^.*?\+\s*').Value } catch {}
          if ([string]::IsNullOrWhiteSpace($extractPrefix)) { $extractPrefix = 'Select icons to extract + ' }
          $extractSuffix = ''
          try { $extractSuffix = [regex]::Replace($lineText, '^.*?\+\s*', '') } catch {}
          if ([string]::IsNullOrWhiteSpace($extractSuffix)) { $extractSuffix = 'Extract:' }
          [void]$inline.Inlines.Add((New-Object System.Windows.Documents.Run($extractPrefix)))
          $extractInlineIcon = New-Object System.Windows.Controls.Image
          try { $extractInlineIcon.Source = Resolve-GuideIconSource -ModuleFile 'imageres.dll' -IconIndex 288 } catch { $extractInlineIcon.Source = $null }
          $extractInlineIcon.Width = 16
          $extractInlineIcon.Height = 16
          $extractInlineIcon.Stretch = [System.Windows.Media.Stretch]::Uniform
          $extractInlineIcon.SnapsToDevicePixels = $true
          $extractInlineIcon.Margin = New-Object System.Windows.Thickness(0,-1,2,-2)
          $inlineUi = New-Object System.Windows.Documents.InlineUIContainer
          $inlineUi.Child = $extractInlineIcon
          [void]$inline.Inlines.Add($inlineUi)
          [void]$inline.Inlines.Add((New-Object System.Windows.Documents.Run($extractSuffix)))
          [System.Windows.Controls.Grid]::SetColumn($inline, 1)
          [void]$row.Children.Add($inline)
          $handledInlineExtract = $true
        }
        if (-not $handledInlineExtract -and -not [string]::IsNullOrWhiteSpace($tokenWord) -and $tokenBrush) {
          $rtb = New-Object System.Windows.Controls.RichTextBox
          $rtb.IsReadOnly = $true
          $rtb.IsDocumentEnabled = $false
          $rtb.VerticalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Hidden
          $rtb.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Hidden
          $rtb.BorderThickness = New-Object System.Windows.Thickness(0)
          $rtb.Background = [System.Windows.Media.Brushes]::Transparent
          $rtb.Foreground = $textBrush
          $rtb.CaretBrush = $textBrush
          $rtb.Padding = New-Object System.Windows.Thickness(0)
          $rtb.Margin = New-Object System.Windows.Thickness(0)
          $doc = New-Object System.Windows.Documents.FlowDocument
          $doc.PagePadding = New-Object System.Windows.Thickness(0)
          $doc.Background = [System.Windows.Media.Brushes]::Transparent
          $para = New-Object System.Windows.Documents.Paragraph
          $para.Margin = New-Object System.Windows.Thickness(0)
          $idxWord = -1
          try { $idxWord = $lineText.IndexOf($tokenWord, [System.StringComparison]::Ordinal) } catch { $idxWord = -1 }
          if ($idxWord -ge 0) {
            $pre = $lineText.Substring(0, $idxWord)
            $tok = $lineText.Substring($idxWord, $tokenWord.Length)
            $post = $lineText.Substring($idxWord + $tokenWord.Length)
            [void]$para.Inlines.Add((New-Object System.Windows.Documents.Run($pre)))
            $runTok = New-Object System.Windows.Documents.Run($tok)
            $runTok.Foreground = $tokenBrush
            if ($tokenBold) { $runTok.FontWeight = [System.Windows.FontWeights]::SemiBold }
            [void]$para.Inlines.Add($runTok)
            [void]$para.Inlines.Add((New-Object System.Windows.Documents.Run($post)))
          } else {
            [void]$para.Inlines.Add((New-Object System.Windows.Documents.Run($lineText)))
          }
          [void]$doc.Blocks.Add($para)
          $rtb.Document = $doc
          [System.Windows.Controls.Grid]::SetColumn($rtb, 1)
          [void]$row.Children.Add($rtb)
        } elseif (-not $handledInlineExtract) {
          $line = New-Object System.Windows.Controls.TextBox
          $line.IsReadOnly = $true
          $line.TextWrapping = [System.Windows.TextWrapping]::Wrap
          $line.AcceptsReturn = $true
          $line.VerticalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Hidden
          $line.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Hidden
          $line.BorderThickness = New-Object System.Windows.Thickness(0)
          $line.Background = [System.Windows.Media.Brushes]::Transparent
          $line.Foreground = $textBrush
          $line.CaretBrush = $textBrush
          $line.Padding = New-Object System.Windows.Thickness(0)
          if ($isHeadingItem) { $line.FontWeight = [System.Windows.FontWeights]::SemiBold }
          $line.Text = $lineText
          [System.Windows.Controls.Grid]::SetColumn($line, 1)
          [void]$row.Children.Add($line)
        }
        [void]$stack.Children.Add($row)
      }
    }
    $sv.Content = $stack
    [void]$root.Children.Add($sv)
    $btnHost = New-Object System.Windows.Controls.DockPanel
    $btnHost.LastChildFill = $false
    $btnHost.Margin = New-Object System.Windows.Thickness(10,8,10,10)
    [System.Windows.Controls.Grid]::SetRow($btnHost, 1)
    $okBtn = New-Object System.Windows.Controls.Button
    $okBtn.Content = 'Close'
    $okBtn.Width = 92
    $okBtn.Height = 30
    $okBtn.Margin = New-Object System.Windows.Thickness(0,0,0,0)
    $okBtn.Background = $surfaceBrush
    $okBtn.Foreground = $textBrush
    $okBtn.BorderBrush = $borderBrush
    $okBtn.BorderThickness = New-Object System.Windows.Thickness(1)
    [System.Windows.Controls.DockPanel]::SetDock($okBtn, [System.Windows.Controls.Dock]::Right)
    $okBtn.Add_Click({
      param($sender, $e)
      try {
        $host = [System.Windows.Window]::GetWindow($sender)
        if ($host) { $host.Close(); return }
      } catch {}
      try { if ($script:InfoGuideWindow) { $script:InfoGuideWindow.Close() } } catch {}
    })
    [void]$btnHost.Children.Add($okBtn)
    [void]$root.Children.Add($btnHost)
    $dlg.Content = $root
    $dlg.Add_ContentRendered({
      try { Apply-InfoGuideThemeToVisualTree -Root $dlg -ForegroundBrush $textBrush -BackgroundBrush $surfaceBrush -BorderBrushLocal $borderBrush } catch {}
    })
    $dlg.Add_Closed({
      try { $script:InfoGuideWindow = $null } catch {}
    })
    $script:InfoGuideWindow = $dlg
    [void]$dlg.Show()
    try {
      $action = [Action]{ try { Apply-InfoGuideThemeToVisualTree -Root $dlg -ForegroundBrush $textBrush -BackgroundBrush $surfaceBrush -BorderBrushLocal $borderBrush } catch {} }
      $dlg.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Background, $action) | Out-Null
    } catch {}
    try { $dlg.Activate() } catch {}
  } catch {
    try {
      [System.Windows.MessageBox]::Show(
        "Unable to open the guide window.`n`n$($_.Exception.Message)",
        'Info',
        [System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]::Warning
      ) | Out-Null
    } catch {}
  }
}

if ($infoBtn) {
  $infoBtn.Add_Click({
    Show-InfoGuideDialog -OwnerWindow $window
  })
}

if (-not (Test-Path variable:script:GridF2RenameWired) -or -not $script:GridF2RenameWired) {
  $script:GridF2RenameWired = $true
  $grid.Add_PreviewKeyDown({
    param($s,$e)
    try {
      if ($e.Key -ne [System.Windows.Input.Key]::F2) { return }
      $dep = $e.OriginalSource -as [System.Windows.DependencyObject]
      if ($dep -and (Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.TextBox]))) { return }

      $row = $null
      try { $row = $grid.SelectedItem } catch {}
      if ($row) {
        Start-RenameForRow -Row $row
      }
      $e.Handled = $true
    } catch {}
  })
}

if (-not (Test-Path variable:script:WindowUndoRedoHotkeysWired) -or -not $script:WindowUndoRedoHotkeysWired) {
  $script:WindowUndoRedoHotkeysWired = $true

  # In-window only: no global hotkey registration (prevents hijacking Ctrl+Z/Ctrl+Y outside app focus).
  # Single path: InputManager pre-process so undo/redo does not depend on grid row focus.
  try {
    $script:UndoRedoLastHotkeyTick = 0
    $script:UndoRedoLastHotkeyKey = ''
    $script:UndoRedoPreProcessHandler = [System.Windows.Input.PreProcessInputEventHandler]{
      param($sender, $e)
      try {
        if (-not $window -or -not $window.IsActive) { return }
        if (-not $e -or -not $e.StagingItem) { return }
        $inp = $e.StagingItem.Input
        if (-not ($inp -is [System.Windows.Input.KeyEventArgs])) { return }
        $kea = [System.Windows.Input.KeyEventArgs]$inp
        if ($kea.Handled) { return }
        if ($kea.RoutedEvent -ne [System.Windows.Input.Keyboard]::PreviewKeyDownEvent) { return }

        $dep = $kea.OriginalSource -as [System.Windows.DependencyObject]
        if ($dep -and (Find-VisualAncestor -Start $dep -Type ([System.Windows.Controls.TextBox]))) { return }

        $mods = [System.Windows.Input.Keyboard]::Modifiers
        if (($mods -band [System.Windows.Input.ModifierKeys]::Control) -eq 0) { return }
        $k = $kea.Key
        if ($k -eq [System.Windows.Input.Key]::System) { $k = $kea.SystemKey }

        if ($k -eq [System.Windows.Input.Key]::Z) {
          $kname = [string]$k
          $nowTick = [Environment]::TickCount
          $dt = [Math]::Abs([int]($nowTick - [int]$script:UndoRedoLastHotkeyTick))
          if ($script:UndoRedoLastHotkeyKey -eq $kname -and $dt -lt 120) { return }
          $script:UndoRedoLastHotkeyTick = $nowTick
          $script:UndoRedoLastHotkeyKey = $kname
          [void]$window.Dispatcher.BeginInvoke([Action]{ Invoke-UndoViaButtonClick })
          $kea.Handled = $true
          return
        }
        if ($k -eq [System.Windows.Input.Key]::Y) {
          $kname = [string]$k
          $nowTick = [Environment]::TickCount
          $dt = [Math]::Abs([int]($nowTick - [int]$script:UndoRedoLastHotkeyTick))
          if ($script:UndoRedoLastHotkeyKey -eq $kname -and $dt -lt 120) { return }
          $script:UndoRedoLastHotkeyTick = $nowTick
          $script:UndoRedoLastHotkeyKey = $kname
          [void]$window.Dispatcher.BeginInvoke([Action]{ Invoke-RedoViaButtonClick })
          $kea.Handled = $true
          return
        }
      } catch {}
    }
    [System.Windows.Input.InputManager]::Current.add_PreProcessInput($script:UndoRedoPreProcessHandler)
  } catch {}

  $window.Add_Closed({
    try {
      if ($script:UndoRedoPreProcessHandler) {
        [System.Windows.Input.InputManager]::Current.remove_PreProcessInput($script:UndoRedoPreProcessHandler)
      }
    } catch {}
    try { Stop-EmbeddedCharMap } catch {}
  })
}

try {
  Ensure-MidGridScrollBarWiring
  Queue-MidGridScrollBarSync -LayoutUpdate:$true
} catch {}

if (-not (Test-Path variable:script:StartupWorkingOverlayWired) -or -not $script:StartupWorkingOverlayWired) {
  $script:StartupWorkingOverlayWired = $true
  try {
    $window.Add_ContentRendered({
      try {
        $alreadyShown = $false
        try { $alreadyShown = [bool]$script:StartupWorkingOverlayShown } catch { $alreadyShown = $false }
        if ($alreadyShown) { return }
        $script:StartupWorkingOverlayShown = $true
        Show-BusyOverlay -Status "Working..."
        $startupOverlayTimer = New-Object System.Windows.Threading.DispatcherTimer
        $startupOverlayTimer.Interval = [TimeSpan]::FromSeconds(7)
        $startupOverlayTimer.Add_Tick({
          param($sender, $args)
          try { $sender.Stop() } catch {}
          try { Hide-BusyOverlay } catch {}
        })
        try { $startupOverlayTimer.Start() } catch { try { Hide-BusyOverlay } catch {} }
      } catch {}
    })
  } catch {}
}

try { Set-StartupSplashStatus -Status "Launching..." -Value 99 } catch {}
$window.ShowDialog() | Out-Null















